### `app.py`

```python
#!/usr/bin/env python3
import os
import uuid
import threading
from pathlib import Path
from typing import List, Dict

from flask import (
    Flask,
    render_template,
    request,
    session,
    jsonify,
    send_from_directory,
    abort,
)
from werkzeug.utils import secure_filename

app = Flask(__name__)
# A secret key is required for signed cookies (session)
app.secret_key = os.getenv("FLASK_SECRET_KEY", "dev-secret-key")


# ----------------------------------------------------------------------
#  Queue / state handling – all protected by a (process‑wide) lock
# ----------------------------------------------------------------------
class UploadQueue:
    """
    Very small in‑memory queue.  For a real deployment you would replace
    this with Redis or a DB, but the logic stays exactly the same.
    """

    def __init__(self):
        self.lock = threading.Lock()
        self.queue: List[str] = []                   # list of client_id strings
        self.current_uploader: str | None = None    # client id that may upload now
        self.finished_files: List[Dict] = []        # { "filename": ..., "original": ... }

    # ------------------------------------------------------------------
    # Queue operations
    # ------------------------------------------------------------------
    def join(self, client_id: str) -> int:
        """Add client to the queue if it is not already there and return its position."""
        with self.lock:
            if client_id not in self.queue:
                self.queue.append(client_id)
                # If nobody is uploading right now, give the turn immediately
                if self.current_uploader is None:
                    self.current_uploader = client_id
            return self.queue.index(client_id) + 1   # 1‑based position

    def position(self, client_id: str) -> int:
        with self.lock:
            if client_id not in self.queue:
                return -1
            return self.queue.index(client_id) + 1

    def allowed(self, client_id: str) -> bool:
        """True if the client is the one that may upload right now."""
        with self.lock:
            return client_id == self.current_uploader

    def finish(self, client_id: str) -> None:
        """
        Called when the current uploader clicks “Finish”.  Removes the client
        from the queue and gives the turn to the next waiting client (if any).
        """
        with self.lock:
            if client_id in self.queue:
                self.queue.remove(client_id)
            # reset current uploader – the next client (if any) becomes the owner
            self.current_uploader = self.queue[0] if self.queue else None

    def add_finished_file(self, stored_name: str, original_name: str) -> None:
        with self.lock:
            self.finished_files.append(
                {"stored": stored_name, "original": original_name}
            )

    def list_files(self):
        with self.lock:
            # Return a *copy* so the caller cannot mutate the internal list
            return list(self.finished_files)


upload_queue = UploadQueue()


# ----------------------------------------------------------------------
# Helper – ensure the user has a client_id in the session
# ----------------------------------------------------------------------
def get_client_id() -> str:
    """
    A UUID that lives in the signed cookie so we can recognise the same
    browser across requests.  The first request creates it.
    """
    if "client_id" not in session:
        session["client_id"] = str(uuid.uuid4())
    return session["client_id"]


# ----------------------------------------------------------------------
# Routes – index + queue handling
# ----------------------------------------------------------------------
@app.get("/")
def index():
    """Render the Dropzone page."""
    return render_template("index.html")


@app.post("/join-queue")
def join_queue():
    """
    Called once (via AJAX) when the page loads.  It registers the client
    and returns the current queue position.
    """
    client_id = get_client_id()
    pos = upload_queue.join(client_id)
    return jsonify({"position": pos})


@app.get("/queue-status")
def queue_status():
    """
    Polled by the front‑end every second.
    Returns {position: N, allowed: true/false}
    """
    client_id = get_client_id()
    pos = upload_queue.position(client_id)
    allowed = upload_queue.allowed(client_id)
    return jsonify({"position": pos, "allowed": allowed})


@app.post("/start-upload")
def start_upload():
    """
    The user clicks the **Start upload** button.  We just check that
    the client is still the one that may upload.
    """
    client_id = get_client_id()
    if not upload_queue.allowed(client_id):
        # 423 Locked – Dropzone will stop sending chunks
        return "You are not at the head of the queue.", 423
    return "You may start uploading.", 200


# ----------------------------------------------------------------------
# Chunk upload – the original logic with an extra queue guard
# ----------------------------------------------------------------------
@app.post("/upload")
def upload_chunk():
    """
    Dropzone chunk handler.  It refuses any chunk that does NOT belong to the
    client currently holding the lock.
    """
    client_id = get_client_id()
    if not upload_queue.allowed(client_id):
        # The client tried to upload while not being at the head of the queue.
        # Dropzone treats 4xx as a permanent error and stops.
        return "Locked – wait for your turn.", 423

    # ------------------------------------------------------------------
    # The code you already had – unchanged apart from a tiny tweak
    # ------------------------------------------------------------------
    file = request.files["file"]
    file_uuid = request.form["dzuuid"]
    # Build a safe filename that also encodes the UUID (8 chars are enough for uniqueness)
    stored_name = f"{file_uuid[:8]}_{secure_filename(file.filename)}"
    save_path = Path("static", "img", stored_name)

    current_chunk = int(request.form["dzchunkindex"])

    try:
        with open(save_path, "ab") as f:
            # The byte offset is sent by Dropzone; we honour it so that a client
            # can resume a broken upload.
            f.seek(int(request.form["dzchunkbyteoffset"]))
            f.write(file.stream.read())
    except OSError:
        return "Error saving file.", 500

    total_chunks = int(request.form["dztotalchunkcount"])

    # When we receive the *last* chunk we do a quick sanity‑check on size.
    if current_chunk + 1 == total_chunks:
        if os.path.getsize(save_path) != int(request.form["dztotalfilesize"]):
            return "Size mismatch.", 500

        # Store information about the finished file – it will later appear
        # on the /files page.
        upload_queue.add_finished_file(stored_name, file.filename)

    return "Chunk upload successful.", 200


# ----------------------------------------------------------------------
# Client signals that the whole upload is finished (presses the button)
# ----------------------------------------------------------------------
@app.post("/finish-upload")
def finish_upload():
    """
    The user clicks **Finish upload** after the last chunk has been sent.
    This releases the lock so the next client may start.
    """
    client_id = get_client_id()
    if not upload_queue.allowed(client_id):
        # Should never happen – the button is only shown when allowed is true.
        return "You are not the current uploader.", 400

    upload_queue.finish(client_id)
    return "Upload session finished, next user may start.", 200


# ----------------------------------------------------------------------
# Download page – simple list of links
# ----------------------------------------------------------------------
@app.get("/files")
def list_files():
    """Show a tiny html page that lists every file that has been uploaded."""
    files = upload_queue.list_files()
    return render_template("files.html", files=files)


@app.get("/download/<filename>")
def download(filename):
    """
    Serve a file from the static/img folder.  The filename is the *stored*
    name (the one that contains the UUID prefix).  For extra safety we
    only allow files that actually belong to the finished‑files list.
    """
    # Basic validation – prevent path traversal attacks
    if "/" in filename or "\\" in filename:
        abort(400)

    # Ensure we only serve files that are known (optional but nice)
    known = {f["stored"] for f in upload_queue.list_files()}
    if filename not in known:
        abort(404)

    return send_from_directory(
        directory=Path("static", "img"),
        path=filename,
        as_attachment=True,
    )


# ----------------------------------------------------------------------
# Run the app
# ----------------------------------------------------------------------
if __name__ == "__main__":
    # NOTE: when you run with `debug=True` Flask uses a reloader that spawns
    # a second process – the in‑memory queue would be duplicated.  For a real
    # deployment you would use `gunicorn` with a single worker or a redis based
    # queue.  For this demo the built‑in server is fine.
    app.run(debug=True, host="0.0.0.0", port=5000)
```

