// main.js – Gère le bouton, le SSE et l'affichage de la barre de progression

document.addEventListener('DOMContentLoaded', () => {
    const startBtn   = document.getElementById('startBtn');
    const progressBar = document.getElementById('progressBar');
    const logDiv     = document.getElementById('log');

    // Fonction d'ajout d'une ligne de log
    const addLog = (msg, type='info') => {
        const p = document.createElement('p');
        p.classList.add('mb-0');
        if (type === 'error') p.classList.add('text-danger');
        else if (type === 'info') p.classList.add('text-primary');
        p.textContent = `[${new Date().toLocaleTimeString()}] ${msg}`;
        logDiv.appendChild(p);
        logDiv.scrollTop = logDiv.scrollHeight;
    };

    // Lance la copie via POST /start-copy
    startBtn.addEventListener('click', () => {
        startBtn.disabled = true;
        addLog('Demande de lancement de la copie...', 'info');

        fetch('/start-copy', {method: 'POST'})
            .then(resp => {
                if (resp.status === 202) {
                    addLog('Copie démarrée.', 'info');
                    // Ouvre le flux SSE pour récupérer la progression
                    const evtSource = new EventSource('/progress');

                    evtSource.onmessage = (event) => {
                        const data = JSON.parse(event.data);
                        if (data.type === 'progress') {
                            progressBar.style.width = `${data.percent}%`;
                            progressBar.textContent = `${data.percent}%`;
                        }
                        if (data.type === 'info' || data.type === 'progress') {
                            addLog(data.msg, 'info');
                        }
                        if (data.type === 'error') {
                            addLog(data.msg, 'error');
                            evtSource.close();
                            startBtn.disabled = false;
                        }
                        if (data.type === 'end') {
                            progressBar.style.width = '100%';
                            progressBar.textContent = '100%';
                            addLog(data.msg, 'info');
                            evtSource.close();
                            startBtn.disabled = false;
                        }
                    };

                    evtSource.onerror = () => {
                        addLog('Connexion au serveur perdue.', 'error');
                        evtSource.close();
                        startBtn.disabled = false;
                    };
                } else if (resp.status === 409) {
                    addLog('Une copie est déjà en cours.', 'error');
                    startBtn.disabled = false;
                } else {
                    addLog('Erreur inconnue lors du lancement.', 'error');
                    startBtn.disabled = false;
                }
            })
            .catch(err => {
                addLog('Exception : ' + err, 'error');
                startBtn.disabled = false;
            });
    });
});
```

