        "outline": f"请根据以下关键词或简要描述，帮我写一个 1500‑2000 字的网络小说大纲，结构清晰，包含起承转合，每一段落的核心冲突要标注出来。\n关键词/描述：{content}",
        "character": f"请根据以下关键词或简要描述，为网络小说的主角（或配角）写一份完整的人设，包括姓名、年龄、外貌、性格、背景、成长目标、关键经历等，字数控制在 800‑1000 字。\n关键词/描述：{content}",
        "plot": f"请根据以下关键词或简要描述，为网络小说写一个 1500‑2000 字的情节梗概，包含主要冲突、高潮、转折点以及可能的结局走向。\n关键词/描述：{content}",
    }

    if expand_type not in prompts:
        return jsonify({"error": "type 参数错误"}), 400

    try:
        result = gpt_chat([{"role": "user", "content": prompts[expand_type]}])
        # 保存到 session
        session[expand_type] = result
        session.modified = True
        return jsonify({"result": result})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/generate_chapter", methods=["POST"])
def api_generate_chapter():
    """
    根据已保存的大纲、人物设定、情节梗概以及用户选的语言风格
    生成章节草稿。
    request JSON:
    {
        "style": "古风/现代/轻松/悬疑 …（任意文字描述）",
        "continue": false | true   # true 表示在已确认章节的基础上生成下一章节
    }
    """
    data = request.json
    style = data.get("style", "").strip()
    continue_flag = data.get("continue", False)

    # 必须先有大纲、人物、情节
    if not session.get("outline") or not session.get("character") or not session.get("plot"):
        return jsonify({"error": "请先完成大纲、人物设定、情节梗概的扩写"}), 400

    # 记录本次使用的风格
    session["style"] = style
    session.modified = True

    # 把已经确认的章节拼接为“已写内容”
    confirmed_text = "\n".join(session["confirmed_chapters"])

    # 构造 Prompt
    system_prompt = (
        "你是一个专业的网络小说作者，擅长根据大纲、人物设定、情节梗概以及指定的语言风格写出连贯、有吸引力的章节。"
    )

    user_prompt = (
        f"**大纲**（仅供参考，不直接出现于正文）：\n{session['outline']}\n\n"
        f"**人物设定**（仅供参考）：\n{session['character']}\n\n"
        f"**情节梗概**（仅供参考）：\n{session['plot']}\n\n"
        f"**已确认章节（如有）**：\n{confirmed_text}\n\n"
        f"请**根据上述信息**，以 **{style or '默认语言风格'}** 来写出 **下一章节**（约 2000‑2500 字），章节标题自行设定，要求情节连贯、冲突明显、人物性格鲜明、语言风格统一。"
    )

    try:
        chapter = gpt_chat(
            [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            temperature=0.85,
            max_tokens=2500,
        )
        # 保存草稿
        session["draft_chapter"] = chapter
        session.modified = True
        return jsonify({"chapter": chapter})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/regenerate", methods=["POST"])
def api_regenerate():
    """
    根据用户的“意见”重新生成当前草稿章节。
    request JSON:
    {
        "feedback": "比如要求更快的节奏，或增加对话等"
    }
    """
    data = request.json
    feedback = data.get("feedback", "").strip()

    # 仍然需要原始信息
    if not session.get("outline") or not session.get("character") or not session.get("plot"):
        return jsonify({"error": "缺少必要的上下文信息"}), 400

    confirmed_text = "\n".join(session["confirmed_chapters"])

    system_prompt = "你是一名网络小说作家，擅长根据用户反馈对章节进行二次创作。"
    user_prompt = (
        f"**大纲**：\n{session['outline']}\n\n"
        f"**人物设定**：\n{session['character']}\n\n"
        f"**情节梗概**：\n{session['plot']}\n\n"
        f"**已确认章节**：\n{confirmed_text}\n\n"
        f"**当前草稿章节**：\n{session.get('draft_chapter','（无）')}\n\n"
        f"**用户反馈**：{feedback}\n\n"
        "请在上述基础上重新生成章节，保持章节标题不变，重点满足用户的反馈。"
    )
    try:
        new_chapter = gpt_chat(
            [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            temperature=0.85,
            max_tokens=2500,
        )
        session["draft_chapter"] = new_chapter
        session.modified = True
        return jsonify({"chapter": new_chapter})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/confirm", methods=["POST"])
def api_confirm():
    """
    用户确认当前草稿章节，将其加入已确认章节列表。
    """
    draft = session.get("draft_chapter", "")
    if not draft:
        return jsonify({"error": "没有可确认的章节"}), 400

    # 将草稿推入已确认章节
    session["confirmed_chapters"].append(draft)
    # 清空草稿
    session["draft_chapter"] = ""
    session.modified = True
    return jsonify({"msg": "章节已确认，已保存到已确认列表"})


@app.route("/api/download", methods=["GET"])
def api_download():
    """
    把所有已确认章节合并成一个 TXT 并返回给前端下载。
    """
    confirmed = session.get("confirmed_chapters", [])
    if not confirmed:
        return jsonify({"error": "暂无已确认章节"}), 400

    # 合并文本
    txt_content = "\n\n".join(confirmed)
    # 生成文件名（可加时间戳或 UUID）
    filename = f"novel_{uuid.uuid4().hex[:8]}.txt"

    # 用 BytesIO 把文本转成文件流
    buffer = BytesIO()
    buffer.write(txt_content.encode("utf-8"))
    buffer.seek(0)

    return send_file(
        buffer,
        as_attachment=True,
        download_name=filename,
        mimetype="text/plain",
    )


# ------------ 运行入口 ------------
if __name__ == "__main__":
    # 开发模式
    app.run(host="0.0.0.0", port=5000, debug=True)
```

> **关键点解释**  

1. **会话 (`session`)**：把大纲、人物设定、情节、语言风格、已确认章节、当前草稿保存在用户的浏览器会话里（服务器端的 `Flask session`，默认基于签名的 cookie）。这样用户在刷新页面、继续写下一章节时不需要重复输入。  
2. **`gpt_chat`**：包装了一次 ChatCompletion 调用，返回 assistant 的文本。所有的提示（prompt）都在后端生成，前端只负责把用户的关键词发送过去。  
3. **`/api/expand`**：一次性扩写“大纲 / 人设 / 情节”。如果用户想要重新生成，只需再次点击对应按钮，前端会再次调用此接口。  
4. **`/api/generate_chapter`**：根据已保存的大纲、角色、人设以及用户选择的语言风格生成章节草稿。支持“续写”模式（`continue:true`），在已有章节后继续生成。  
5. **`/api/regenerate`**：接受用户的自由文字反馈（如 “把对话多写点”），在原草稿基础上重新生成。  
6. **`/api/confirm`**：用户确认当前章节后，把草稿加入已确认列表。  
7. **`/api/download`**：把已确认章节汇总成 txt 文件并提供下载。  

