        .flex > div {flex:1;min-width:250px;}
        .download-link {margin-top:10px;display:inline-block;background:#28a745;color:#fff;padding:8px 12px;border-radius:4px;text-decoration:none;}
    </style>
</head>
<body>
<div class="container">
    <h1>AI 网络小说章节生成器</h1>

    <!-- 1. 输入关键字/简要描述 -->
    <div class="section">
        <h2>1️⃣ 输入关键字/简要描述（可自行决定是否先手写）</h2>
        <div class="flex">
            <div>
                <label>大纲关键字：</label><br>
                <textarea id="outline-keywords" placeholder="比如：都市、穿越、女强、逆袭"></textarea>
                <button onclick="expand('outline')">自动扩写大纲</button>
            </div>
            <div>
                <label>角色关键字：</label><br>
                <textarea id="character-keywords" placeholder="比如：女主、白领、逆天天赋、冷酷外表"></textarea>
                <button onclick="expand('character')">自动扩写角色设定</button>
            </div>
            <div>
                <label>情节关键字：</label><br>
                <textarea id="plot-keywords" placeholder="比如：意外穿越、宫斗、复仇、暗藏大阴谋"></textarea>
                <button onclick="expand('plot')">自动扩写情节梗概</button>
            </div>
        </div>

        <h3>扩写结果（可自行编辑后再次提交）</h3>
        <label>大纲：</label>
        <textarea id="outline-result"></textarea>
        <label>角色设定：</label>
        <textarea id="character-result"></textarea>
        <label>情节梗概：</label>
        <textarea id="plot-result"></textarea>
    </div>

    <!-- 2. 选择语言风格并生成章节 -->
    <div class="section">
        <h2>2️⃣ 选择语言风格 & 生成章节</h2>
        <div>
            <label>语言风格（可自由填写，如“古风”、“轻松搞笑”等）:</label>
            <input type="text" id="style-input" style="width:60%;padding:6px;" placeholder="比如：古风、悬疑、轻松...">
            <button onclick="generateChapter()">开始写章节</button>
            <button onclick="continueNext()">继续写下一章节</button>
        </div>

        <h3>章节草稿（可直接编辑后确认）</h3>
        <textarea id="draft-chapter"></textarea>
        <div style="margin-top:10px;">
            <button onclick="confirmChapter()">确认章节（保存）</button>
            <button onclick="showRegenerate()">重新生成（带反馈）</button>
        </div>
    </div>

    <!-- 3. 重新生成（带反馈）弹窗 -->
    <div class="section" id="regenerate-section" style="display:none;">
        <h2>🔄 重新生成章节（提供反馈）</h2>
        <textarea id="feedback-input" placeholder="请写下希望修改的地方，例如：增加角色对白，节奏更快……"></textarea>
        <button onclick="regenerate()">提交反馈并重新生成</button>
        <button onclick="hideRegenerate()">取消</button>
    </div>

    <!-- 4. 已确认章节列表 + 下载 -->
    <div class="section">
        <h2>3️⃣ 已确认章节 & 下载文档</h2>
        <div id="confirmed-list" class="output">暂无已确认章节</div>
        <a href="/api/download" class="download-link" id="download-link" style="display:none;">下载已确认章节（txt）</a>
    </div>
</div>

<script>
/* ---------- 辅助函数 ---------- */
function showAlert(msg){ alert(msg); }

/* ---------- 1️⃣ 扩写 ---------- */
async function expand(type){
    const map = {
        outline: document.getElementById('outline-keywords').value,
        character: document.getElementById('character-keywords').value,
        plot: document.getElementById('plot-keywords').value,
    };
    const content = map[type] || "";
    if (!content.trim()){
        showAlert("请先填写对应的关键字/简要描述");
        return;
    }

    const btn = event.target;
    btn.disabled = true;
    btn.textContent = "生成中…";

    const resp = await fetch("/api/expand", {
        method: "POST",
        headers: {"Content-Type":"application/json"},
        body: JSON.stringify({type, content})
    }).then(r=>r.json());

    btn.disabled = false;
    btn.textContent = `自动扩写${type==="outline"?"大纲":type==="character"?"角色设定":"情节梗概"}`;

    if (resp.error){
        showAlert(resp.error);
        return;
    }
    // 把返回的文本放进对应的 textarea
    if (type === "outline") document.getElementById('outline-result').value = resp.result;
    else if (type === "character") document.getElementById('character-result').value = resp.result;
    else document.getElementById('plot-result').value = resp.result;
}

/* ---------- 2️⃣ 生成章节 ---------- */
async function generateChapter(continueFlag=false){
    const style = document.getElementById('style-input').value.trim();
    if (!style){
        if (!confirm("未填写语言风格，是否仍继续使用默认风格？")) return;
    }

    // 先把用户可能手动编辑过的“大纲/角色/情节”保存回 session
    const outline = document.getElementById('outline-result').value.trim();
    const character = document.getElementById('character-result').value.trim();
    const plot = document.getElementById('plot-result').value.trim();

    if (!outline || !character || !plot){
        showAlert("请确保“大纲、角色设定、情节梗概”都有内容后再生成章节");
        return;
    }

    // 通过一个临时接口把编辑后的文本写回 session（不做太多校验）
    // 这里直接调用 /api/expand，利用它的实现把内容写回；或者自行写一个保存接口，这里简化。
    // 为了演示，我们直接让后端使用最新的 session 内容（因为 Flask 会在同一个会话里持续）。
    // 因此这里不必额外请求，后端已经拥有最新的 session（因为这是同一次请求）。
    // 只要在前端刷新页面后再次提交，session 中的内容才会失效。

    const btn = event.target;
    btn.disabled = true;
    btn.textContent = "生成中…";

    const resp = await fetch("/api/generate_chapter", {
        method: "POST",
        headers: {"Content-Type":"application/json"},
        body: JSON.stringify({style, continue: continueFlag})
    }).then(r=>r.json());

    btn.disabled = false;
    btn.textContent = continueFlag ? "继续写下一章节" : "开始写章节";

    if (resp.error){
        showAlert(resp.error);
        return;
    }
    document.getElementById('draft-chapter').value = resp.chapter;
}

/* 按钮 “继续写下一章节” */
function continueNext(){
    generateChapter(true);
}

/* ---------- 章节确认 ---------- */
async function confirmChapter(){
    const draft = document.getElementById('draft-chapter').value.trim();
    if (!draft){
        showAlert("章节草稿为空，无法确认");
        return;
    }
    if (!confirm("确认该章节并保存？确认后章节将加入已确认列表。")){
        return;
    }
    const resp = await fetch("/api/confirm", {method:"POST"}).then(r=>r.json());
    if (resp.error){
        showAlert(resp.error);
        return;
    }
    document.getElementById('draft-chapter').value = "";
    refreshConfirmedList();
}

/* ---------- 已确认章节列表 ---------- */
async function refreshConfirmedList(){
    const listDiv = document.getElementById('confirmed-list');
    // 这里直接读取 session 内容的方式是通过后端再返回一次（简化：我们把已确认章节直接放进页面的隐藏属性中）。
    // 为了不再额外写接口，直接通过一次获取 /api/download 的 HEAD 判断是否有内容。
    // 这里演示直接请求 /api/download（GET）并捕获返回的文本。
    const resp = await fetch("/api/download");
    if (resp.status === 400){
        listDiv.textContent = "暂无已确认章节";
        document.getElementById('download-link').style.display = "none";
        return;
    }
    // 读取返回的 txt 内容（因为是文件流）。
    const txt = await resp.text();
    listDiv.textContent = txt;
    // 展示下载链接
    document.getElementById('download-link').style.display = "inline-block";
}

/* 页面加载时刷新一次已确认列表 */
window.onload = refreshConfirmedList;

/* ---------- 重新生成（带反馈） ---------- */
function showRegenerate(){
    document.getElementById('regenerate-section').style.display = "block";
}
function hideRegenerate(){
    document.getElementById('regenerate-section').style.display = "none";
}
async function regenerate(){
    const feedback = document.getElementById('feedback-input').value.trim();
    if (!feedback){
        showAlert("请先输入反馈内容");
        return;
    }
    const btn = event.target;
    btn.disabled = true;
    btn.textContent = "重新生成中…";

    const resp = await fetch("/api/regenerate", {
        method: "POST",
        headers: {"Content-Type":"application/json"},
        body: JSON.stringify({feedback})
    }).then(r=>r.json());

    btn.disabled = false;
    btn.textContent = "提交反馈并重新生成";

    if (resp.error){
        showAlert(resp.error);
        return;
    }
    document.getElementById('draft-chapter').value = resp.chapter;
    hideRegenerate();
}
</script>
</body>
</html>
```

### 代码要点说明

| 区块 | 功能 | 关键实现 |
|------|------|----------|
| **输入关键字** | 用户手动填写大纲、角色、情节的关键词或简要描述 | `textarea#outline-keywords`、`#character-keywords`、`#plot-keywords` |
| **自动扩写** | 调用 `/api/expand` 把关键词转成完整的大纲/角色设定/情节梗概 | `expand(type)` 函数，通过 `fetch` POST |
| **编辑结果** | 扩写完后返回的文本直接放进对应的 textarea，用户仍能自行微调 | `#outline-result`、`#character-result`、`#plot-result` |
| **选择语言风格** | 文本输入框 `#style-input`（任意描述），默认风格可不填 | `generateChapter()` 中读取 |
| **生成章节** | 调用 `/api/generate_chapter`（带 `continue` 参数）生成草稿 | `draft-chapter` textarea 用于展示、编辑 |
| **重新生成** | `regenerate()` 把用户的文字反馈提交给后端 `/api/regenerate` | 将反馈拼入 Prompt，返回新章节 |
| **确认章节** | 确认后调用 `/api/confirm` 把草稿写入 `confirmed_chapters` | 同时刷新已确认列表 |
| **已确认章节 & 下载** | 页面加载/确认后调用 `/api/download`（GET）把 txt 内容读回页面展示，同时提供下载链接 | `refreshConfirmedList()` |

> **为什么 `/api/download` 同时用来取已确认章节文本？**  
> Flask 会在返回文件流时自动设置 `Content-Type: text/plain`，前端只要把响应视作文本读取即可。若后端不想暴露文件下载接口，也可以新建 `/api/get_confirmed` 用 JSON 返回列表，这里为了示例 **简化** 代码。

