## 2. Последовательность действий (чистый RPC)

### 2.1. Получить список подписей

```json
POST https://api.mainnet-beta.solana.com
Content-Type: application/json

{
  "jsonrpc":"2.0",
  "id":1,
  "method":"getSignaturesForAddress",
  "params":[
    "YourPublicKeyBase58",   // <‑‑ адрес кошелька
    {
      "limit": 1000,        // максимум 1000 за один запрос
      "before": null,       // подпись, от которой «отматывать» назад (если есть)
      "until": null         // подпись, до которой (включительно) собрать
    }
  ]
}
```

**Ответ** – массив объектов `{ signature, slot, err, blockTime, confirmationStatus }`.  

**Пагинация**  
1. Сохраните `signature` последнего полученного элемента.  
2. Для следующего «пакета» передайте его в поле `before`.  
3. Повторяйте, пока массив будет пуст или вы достигнете нужного `until`.

> **Важно:** если требуется **полный** список (все транзакции за всё время), придётся выполнять цикл до тех пор, пока `before` будет `null` (или до известного «старого» сигнатурного маркера).

### 2.2. По каждой подписи запросить детали транзакции

```json
POST https://api.mainnet-beta.solana.com
Content-Type: application/json

{
  "jsonrpc":"2.0",
  "id":1,
  "method":"getParsedTransaction",
  "params":[
    "5UjLkZvz...signature...", // подпись
    {
      "encoding":"jsonParsed",
      "maxSupportedTransactionVersion":0
    }
  ]
}
```

Ответ – развернутый объект транзакции, где уже видно:
* отправителя/получателя,
* сумму SOL,
* операции с токенами SPL,
* статус (успешно/ошибка),
* метаданные (метка времени, номер слота).

### 2.3. Пример полной цепочки на Node.js (async/await)

```js
const fetch = require('node-fetch');

const RPC_URL = 'https://api.mainnet-beta.solana.com';
const ADDRESS = 'YourPublicKeyBase58';
const PAGE_SIZE = 1000; // максимальный лимит

async function getAllSignatures() {
  let before = null;
  const allSigs = [];

  while (true) {
    const body = {
      jsonrpc: '2.0',
      id: 1,
      method: 'getSignaturesForAddress',
      params: [
        ADDRESS,
        { limit: PAGE_SIZE, before }
      ]
    };

    const res = await fetch(RPC_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const json = await res.json();
    const sigs = json.result;

    if (!sigs || sigs.length === 0) break; // конец истории

    allSigs.push(...sigs.map(o => o.signature));
    before = sigs[sigs.length - 1].signature; // смещаем «окно» назад
    console.log(`Fetched ${allSigs.length} signatures so far...`);
  }

  return allSigs;
}

async function getTxDetails(sig) {
  const body = {
    jsonrpc: '2.0',
    id: 1,
    method: 'getParsedTransaction',
    params: [sig, { encoding: 'jsonParsed' }]
  };
  const res = await fetch(RPC_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  const { result } = await res.json();
  return result;
}

// Пример использования
(async () => {
  const signatures = await getAllSignatures(); // <-- может занять минуту‑полтора
  console.log(`Всего подписей: ${signatures.length}`);

  // Получаем первые 10 транзакций полностью (чтобы не перегружать сеть)
  const sample = signatures.slice(0, 10);
  const txs = await Promise.all(sample.map(getTxDetails));

  console.log('Пример транзакций:');
  console.dir(txs, { depth: null });
})();
```

*Заметка:* если вам нужно **полностью** обработать все подписи, лучше делать запросы к `getParsedTransaction` пачками (по 10‑20 подписи за запрос) и реализовать **retry‑логику** (ошибки сети, rate‑limit).  

