**Arduino Pro Mini – код «умного датчика»**  
(датчик температуры DS18B20 + один цифровой вход + модуль HC‑12 для беспроводной передачи).  

> **Что делает код**  
> 1. Считывает температуру с DS18B20 (OneWire + DallasTemperature).  
> 2. Считывает состояние цифрового входа `DIGITAL_IN_PIN` (0 / 1).  
> 3. Формирует пакет данных, включающий уникальный **ID** контроллера, температуру, состояние входа и простую контрольную сумму.  
> 4. Отсылает пакет через HC‑12 (SoftwareSerial).  
> 5. Пакет оформлен так, чтобы его удобно разобрать на стороне Orange Pi Zero.  

---

```cpp
/********************************************************************************************
 *  Arduino Pro Mini → HC‑12 «умный датчик»
 *
 *  Состав системы:
 *   – Arduino Pro Mini 3,3 V / 8 MHz
 *   – DS18B20 (One‑Wire) – температура
 *   – Один цифровой вход (например, кнопка, датчик движения и т.п.)
 *   – HC‑12 (UART) – радиоканал к Orange Pi Zero
 *
 *  Описание протокола (строка ASCII, заканчивается символом '\n'):
 *
 *    <ID>|<TEMP_C>|<DIG_IN>|<CRC>
 *
 *  где:
 *    <ID>      – уникальный 2‑байтовый идентификатор контроллера (0‑65535)
 *    <TEMP_C>  – температура в градусах Цельсия, с одной десятичной (например, 23.4)
 *    <DIG_IN>  – 0 или 1 – состояние цифрового входа
 *    <CRC>     – простая 8‑бит контрольная сумма XOR всех символов до '|<CRC>'
 *
 *  Пример пакета:
 *    12|23.4|1|5A\n
 *
 *  На Orange Pi Zero пакет будет разбит по символу ‘|’ и проверен по CRC.
 *
 *  Пакет отправляется раз в 2 секунды (можно менять период в SEND_INTERVAL_MS).
 *
 ********************************************************************************************/

// ---------- БИБЛИОТЕКИ ---------------------------------------------------------------
#include <OneWire.h>               // Базовый протокол OneWire
#include <DallasTemperature.h>    // Драйвер DS18B20
#include <SoftwareSerial.h>        // Для общения с HC‑12 (UART на произвольных пинах)
#include <EEPROM.h>                // Хранение ID в энергонезависимой памяти (по желанию)

// ---------- НАСТРОЙКИ ПИНОВ ---------------------------------------------------------
const uint8_t ONE_WIRE_PIN   = 2;   // Пин, к которому подключён датчик DS18B20
const uint8_t DIGITAL_IN_PIN = 3;   // Пин цифрового входа (внутренняя подтяжка включена)
const uint8_t HC12_RX_PIN    = 10;  // Приём (Arduino‑RX) от HC‑12 (TX)
const uint8_t HC12_TX_PIN    = 11;  // Передача (Arduino‑TX) к HC‑12 (RX)

// ---------- ПАРАМЕТРЫ ПРОГРАММЫ ------------------------------------------------------
const unsigned long SEND_INTERVAL_MS = 2000UL; // Пауза между отправками (мс)

// ---------- ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ ---------------------------------------------------
OneWire oneWire(ONE_WIRE_PIN);                     // Объект OneWire
DallasTemperature tempSensor(&oneWire);           // Драйвер DS18B20
SoftwareSerial hc12(HC12_RX_PIN, HC12_TX_PIN);     // HC‑12 «виртуальный» UART

uint16_t deviceID = 0;          // Уникальный 2‑байтовый ID нашего контроллера
unsigned long lastSendTime = 0; // Время последней отправки (мс)

// ---------- ФУНКЦИИ ---------------------------------------------------------------

/* -------------------------------------------------------------------------
 *  calcCRC8 – простая контрольная сумма XOR всех символов в строке.
 *  Поскольку пакет короткий, такой CRC достаточно для обнаружения ошибок.
 * --------------------------------------------------------------------------*/
uint8_t calcCRC8(const char *data)
{
    uint8_t crc = 0;
    while (*data) {               // Пока не встретили '\0'
        crc ^= (uint8_t)*data;    // XOR текущий байт
        ++data;
    }
    return crc;
}

/* -------------------------------------------------------------------------
 *  readDeviceID – пытаемся загрузить ID из EEPROM.
 *  Если в EEPROM не записан (0xFFFF), генерируем случайный ID и сохраняем.
 * --------------------------------------------------------------------------*/
void readDeviceID()
{
    uint16_t stored = (EEPROM.read(0) << 8) | EEPROM.read(1);
    if (stored == 0xFFFF || stored == 0x0000) {   // «пусто» – генерируем
        randomSeed(analogRead(A0));               // хакаем энтропию
        deviceID = random(1, 0xFFFE);              // ID от 1 до 65534
        EEPROM.update(0, highByte(deviceID));
        EEPROM.update(1, lowByte(deviceID));
    } else {
        deviceID = stored;
    }
}

/* -------------------------------------------------------------------------
 *  sendPacket – формирует строку пакета и отсылает её через HC‑12.
 * --------------------------------------------------------------------------*/
void sendPacket(float temperature, uint8_t digInState)
{
    // Форматируем строку без CRC (добавим позже)
    char payload[32];                     // Достаточно места для всей строки
    snprintf(payload, sizeof(payload), "%u|%.1f|%u", deviceID, temperature, digInState);

    // Вычисляем CRC от строки до символа конца строки
    uint8_t crc = calcCRC8(payload);

    // Добавляем CRC и символ переноса строки
    char packet[40];
    snprintf(packet, sizeof(packet), "%s|%02X\n", payload, crc);

    // Отправка
    hc12.print(packet);                   // HC‑12 в режиме «transparent» передаёт как есть
}

/* -------------------------------------------------------------------------
 *  setup – инициализация всех периферий.
 * --------------------------------------------------------------------------*/
void setup()
{
    // 1. Пины
    pinMode(DIGITAL_IN_PIN, INPUT_PULLUP);   // Внутренняя подтяжка + читаем LOW‑/HIGH‑сигнал

    // 2. Последовательные порты
    Serial.begin(9600);                      // Для отладки в монитор порта
    hc12.begin(9600);                        // По умолчанию HC‑12 работает на 9600 baud

    // 3. Датчик температуры
    tempSensor.begin();

    // 4. Уникальный ID контроллера
    readDeviceID();

    // 5. Информируем в консоль (можно убрать в финальном релизе)
    Serial.print(F("Device ID = "));
    Serial.println(deviceID);
}

/* -------------------------------------------------------------------------
 *  loop – основной цикл: читаем датчики и раз в SEND_INTERVAL_MS шлём пакет.
 * --------------------------------------------------------------------------*/
void loop()
{
    // 1. Считываем цифровой вход
    uint8_t digIn = digitalRead(DIGITAL_IN_PIN);   // 0 = LOW, 1 = HIGH (с учётом подтяжки)

    // 2. Запрашиваем измерение температуры (DS18B20 – 12‑бит, ~750 ms)
    tempSensor.requestTemperatures();               // Инициируем измерение (асинхронно)
    // Ждём завершения (можно использовать non‑blocking, но пока просто)
    while (!tempSensor.isConversionComplete()) {
        // Ничего не делаем; задержка в 1 мс, чтобы не блокировать watchdog
        delay(1);
    }
    float temperature = tempSensor.getTempCByIndex(0); // Первый (и единственный) датчик

    // Если датчик не подключён, DS18B20 вернёт значение -127.0°C – это признак ошибки
    if (temperature == -127.0) {
        Serial.println(F("DS18B20 sensor error!"));
        temperature = 0.0;      // Можно заменить на «nan», но отправим 0 для упрощения
    }

    // 3. Если настало время отправки – формируем и шлём пакет
    unsigned long now = millis();
    if (now - lastSendTime >= SEND_INTERVAL_MS) {
        sendPacket(temperature, digIn);
        lastSendTime = now;

        // Вывод в монитор порта (для отладки)
        Serial.print(F("Sent -> ID:"));
        Serial.print(deviceID);
        Serial.print(F(" Temp:"));
        Serial.print(temperature);
        Serial.print(F("°C  DigIn:"));
        Serial.println(digIn);
    }

    // 4. Небольшая «пауза», чтобы не перегружать процессор (можно убрать)
    delay(10);
}
```

### Пояснение каждого блока кода  

| Строка/Блок | Что делает | Почему это важно |
|-------------|------------|-------------------|
| `#include <OneWire.h>` | Подключаем протокол OneWire | DS18B20 общается по этому протоколу |
| `#include <DallasTemperature.h>` | Библиотека‑обёртка для удобного чтения температуры | Позволяет получить °C без ручных расчётов |
| `#include <SoftwareSerial.h>` | Позволяет создать второй UART на произвольных пинах | Arduino Pro Mini имеет только один аппаратный UART (для отладки), а HC‑12 нужен отдельный |
| `#include <EEPROM.h>` | Доступ к энергонезависимой памяти | Сохраняем уникальный ID, чтобы после перепрошивки контроллер сохранял «своё» имя |
| `ONE_WIRE_PIN = 2` … | Назначаем пины | Делаем схему фиксированной, но легко меняем в коде |
| `HC12_RX_PIN / HC12_TX_PIN` | Пины для связи с HC‑12 | На Arduino‑Pro‑Mini часто используют 10/11, так как они не конфликтуют с другими интерфейсами |
| `SEND_INTERVAL_MS = 2000` | Период отправки 2 с | Слишком частая передача загромозит канал, слишком редкая – будет «запаздывать» данные |
| `OneWire oneWire(ONE_WIRE_PIN);` | Инициализируем шину OneWire | Дальше её использует драйвер temperature |
| `DallasTemperature tempSensor(&oneWire);` | Создаём объект датчика | Позволяет `requestTemperatures()` и `getTempCByIndex()` |
| `SoftwareSerial hc12(HC12_RX_PIN, HC12_TX_PIN);` | Объект для общения с модулем | `hc12.print()` → отправка пакета |
| `calcCRC8()` | Вычисление XOR‑контрольной суммы | Пакет легко проверить на стороне Orange Pi |
| `readDeviceID()` | Чтение/генерация ID | Гарантирует, что каждый Arduino‑контроллер имеет уникальный идентификатор |
| `sendPacket()` | Формирование строки `<ID>|<TEMP>|<DIG_IN>|<CRC>\n` | Стандартный, человекочитаемый формат – удобно парсить в скрипте Python/Node.js |
| `setup()` | Настройка пинов, портов, датчика, чтение ID | Выполняется один раз при включении |
| `loop()` | Основной цикл: чтение входов, измерение температуры, отправка пакета каждые 2 сек | Оставляет процессор почти свободным (все задержки короткие) |
| `tempSensor.requestTemperatures()` + `while (!tempSensor.isConversionComplete())` | Асинхронный запрос + ожидание | DS18B20 требует ~750 мс для измерения; без запроса получаем **старые** данные |
| `temperature == -127.0` | Проверка ошибки датчика | DS18B20 возвращает -127 °C, если шина «отрыва» |
| `delay(10);` в конце `loop()` | Немного разгрузить CPU | Опционально, но помогает избежать 100 % загрузки |

### Как собрать схему

| Компонент | Подключение к Arduino Pro Mini |
|----------|--------------------------------|
| **DS18B20** (пин 1 – GND, пин 2 – DATA, пин 3 – VCC) | GND → GND, VCC → 3.3 V (или 5 V, датчик совместим), DATA → pin 2 + 4.7 kΩ резистор подтягивает к VCC |
| **Цифровой вход** (кнопка, датчик, и т.д.) | Один конец к GND, другой к pin 3 (внутренняя подтяжка включена) |
| **HC‑12** (VCC, GND, TX, RX) | VCC → 3.3 V (или 5 V, модуль имеет стабилизатор), GND → GND, TX (модуля) → pin 10 (Arduino‑RX), RX (модуля) → pin 11 (Arduino‑TX). При необходимости добавить делитель/заглушку уровня, но HC‑12 обычно работает от 5 V. |
