> **注意**：若使用 **playwright**（内置 CDP）可以省去手动开启 Chrome，但这里演示底层 CDP。

#### 3.2.2 示例代码 `py_debugger.py`

```python
# py_debugger.py
import pychrome
import time
import json

# 1️⃣ 连接到 Chrome
browser = pychrome.Browser(url="http://127.0.0.1:9222")

# 2️⃣ 创建一个新 Tab
tab = browser.new_tab()

# 3️⃣ 启用需要的 domain
tab.start()
tab.call_method("Page.enable")
tab.call_method("Runtime.enable")
tab.call_method("Debugger.enable")
tab.call_method("Network.enable")

# 4️⃣ 设置断点 (example.py, 第 5 行)
source_url = f"file://{__file__.replace('py_debugger.py','example.py')}"
breakpoint = tab.call_method("Debugger.setBreakpointByUrl", 
                             url=source_url,
                             lineNumber=4,  # 0-based
                             columnNumber=0)

print("Breakpoint ID:", breakpoint["breakpointId"])

# 5️⃣ 监听暂停事件
def on_paused(**kwargs):
    print("\n>>> Paused")
    for i, frame in enumerate(kwargs["callFrames"]):
        func = frame["functionName"] or "<anonymous>"
        line = frame["location"]["lineNumber"] + 1
        url  = frame["url"]
        print(f"  #{i} {func} at {url}:{line}")
    # 继续执行
    tab.call_method("Debugger.resume")

tab.set_listener("Debugger.paused", on_paused)

# 6️⃣ 加载本地脚本
tab.call_method("Page.navigate", url=source_url)
tab.wait(5)   # 等待页面加载结束

# 7️⃣ 关闭 Tab
browser.close_tab(tab)
```

