> **最新版本**请访问 Maven Central。

#### 3.3.2 示例代码 `CdpDemo.java`

```java
// CdpDemo.java
import io.webfolder.cdp.*;
import io.webfolder.cdp.session.*;
import io.webfolder.cdp.command.*;

public class CdpDemo {

    public static void main(String[] args) {
        // 1️⃣ 创建 CdpLauncher，默认连接到 localhost:9222
        try (CdpLauncher launcher = new CdpLauncher();
             SessionFactory factory = launcher.launch();) {

            // 2️⃣ 打开一个新 Tab (Target)
            Session session = factory.create();

            // 3️⃣ 启用需要的域
            Page page = session.getCommand().getPage();
            Runtime runtime = session.getCommand().getRuntime();
            Debugger debugger = session.getCommand().getDebugger();

            page.enable();
            runtime.enable();
            debugger.enable();

            // 4️⃣ 加载本地 HTML（这里可以是任何 JS，演示 console.log）
            String url = "file://" + System.getProperty("user.dir") + "/example.html";
            page.navigate(url);
            page.loadEventFired();

            // 5️⃣ 设置断点（example.js 第 8 行）
            String scriptUrl = "file://" + System.getProperty("user.dir") + "/example.js";
            debugger.setBreakpointByUrl(scriptUrl, 7, 0);

            // 6️⃣ 监听 pause 事件
            debugger.addPausedListener(event -> {
                System.out.println("\n>>> Paused at breakpoint");
                event.getCallFrames().forEach(frame -> {
                    String fn = frame.getFunctionName();
                    int line = frame.getLocation().getLineNumber() + 1;
                    System.out.println("  " + fn + " @ " + frame.getUrl() + ":" + line);
                });
                debugger.resume(); // 继续执行
            });

            // 7️⃣ 触发脚本执行（通过 Runtime.evaluate）
            runtime.evaluate("runDemo()", true);

            // 等待几秒让脚本跑完
            Thread.sleep(3000);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

