## 3️⃣  `app.py` – Flask backend  

```python
#!/usr/bin/env python
"""
BotDoggy – GPT‑AI Dog Translator
Flask backend that receives either plain‑text "barks" or an audio file,
converts the audio to text (using Whisper if you have it), then asks OpenAI
to translate the dog‑language into a friendly English sentence.
"""

import os
import base64
from pathlib import Path
from flask import Flask, request, jsonify, render_template
from dotenv import load_dotenv
import openai
from werkzeug.utils import secure_filename

# -------------------------------------------------
# Load environment variables
# -------------------------------------------------
load_dotenv()
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
OPENAI_MODEL   = os.getenv("OPENAI_MODEL", "gpt-4o-mini")

if not OPENAI_API_KEY:
    raise RuntimeError("❗  OPENAI_API_KEY not set. Put it in a .env file or export it.")

openai.api_key = OPENAI_API_KEY

# -------------------------------------------------
# Flask app config
# -------------------------------------------------
app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 10 * 1024 * 1024   # 10 MB upload limit
UPLOAD_FOLDER = Path("uploads")
UPLOAD_FOLDER.mkdir(exist_ok=True)
app.config["UPLOAD_FOLDER"] = str(UPLOAD_FOLDER)

ALLOWED_EXTENSIONS = {"wav", "mp3", "m4a", "ogg", "webm"}

def allowed_file(filename: str) -> bool:
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS


# -------------------------------------------------
# Helper: Prompt that tells GPT we want a dog‑to‑human translation
# -------------------------------------------------
def build_prompt(dog_text: str) -> str:
    """
    Returns a system+user prompt that instructs the model to translate
    a dog's vocalisation (or a textual representation of the bark) into
    a natural‑language English sentence.
    """
    system_prompt = (
        "You are BotDoggy, the world's friendliest AI dog translator. "
        "Given a string that represents a dog's bark, howl, whine, etc., "
        "return a short, friendly, human‑readable translation of what the dog might be trying to say. "
        "Focus on tone, emotion, and context, not a literal phonetic transcription."
    )
    user_prompt = f"Dog says: \"{dog_text}\""
    return f"{system_prompt}\n\n{user_prompt}"


# -------------------------------------------------
# Route: Home page
# -------------------------------------------------
@app.route("/", methods=["GET"])
def index():
    return render_template("index.html")


# -------------------------------------------------
# Route: Translate endpoint (AJAX POST)
# -------------------------------------------------
@app.route("/translate", methods=["POST"])
def translate():
    """
    Accepts:
        - form field `bark_text` (plain text)   OR
        - file field `bark_file` (audio)
    Returns JSON: { success: bool, translation: str, error?: str }
    """
    # -------------------------------------------------
    # 1️⃣  Determine source (text vs audio)
    # -------------------------------------------------
    bark_text = request.form.get("bark_text", "").strip()
    bark_file = request.files.get("bark_file")

    # -------------------------------------------------
    # 2️⃣  If an audio file was provided, transcribe it using Whisper (OpenAI)
    # -------------------------------------------------
    if bark_file and bark_file.filename != "":
        if not allowed_file(bark_file.filename):
            return jsonify({"success": False, "error": "Unsupported audio format"}), 400

        filename = secure_filename(bark_file.filename)
        file_path = Path(app.config["UPLOAD_FOLDER"], filename)
        bark_file.save(file_path)

        # Use OpenAI Whisper to turn audio → text (bark transcription)
        try:
            with open(file_path, "rb") as audio_f:
                whisper_resp = openai.audio.transcriptions.create(
                    model="whisper-1",
                    file=audio_f,
                    response_format="text",
                )
            bark_text = whisper_resp.strip()
        except Exception as e:
            return jsonify({"success": False, "error": f"Whisper error: {e}"}), 500
        finally:
            # Clean up uploaded file
            if file_path.exists():
                file_path.unlink()

    # -------------------------------------------------
    # 3️⃣  Validate we have something to translate
    # -------------------------------------------------
    if not bark_text:
        return jsonify({"success": False, "error": "No bark text or audio provided"}), 400

    # -------------------------------------------------
    # 4️⃣  Call the OpenAI chat completion endpoint
    # -------------------------------------------------
    try:
        response = openai.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": "You are an AI dog translator."},
                {"role": "user",   "content": build_prompt(bark_text)},
            ],
            temperature=0.7,
            max_tokens=100,
        )
        translation = response.choices[0].message.content.strip()
    except Exception as exc:
        return jsonify({"success": False, "error": f"OpenAI error: {exc}"}), 500

    # -------------------------------------------------
    # 5️⃣  Return result
    # -------------------------------------------------
    return jsonify({"success": True, "translation": translation})


# -------------------------------------------------
# Run the app (development mode)
# -------------------------------------------------
if __name__ == "__main__":
    # Flask's built‑in server is fine for a demo. For production, use gunicorn / uwsgi.
    app.run(host="0.0.0.0", port=5000, debug=True)
```

### What does the backend do?

| Step | Description |
|------|-------------|
| **Upload handling** | Accept a **text field** (`bark_text`) **or** an **audio file** (`bark_file`). |
| **Audio transcription** (optional) | If an audio file is sent, the code uses **OpenAI Whisper (`whisper-1`)** to transcribe the sound into text. |
| **Prompt construction** | A clear system‑prompt tells GPT that it’s *BotDoggy* and must translate dog‑sounds into a friendly human sentence. |
| **Chat completion** | Calls the chosen model (default `gpt-4o-mini`). |
| **Response** | Returns JSON `{ success, translation }` (or `{ success:false, error }`). |

