## 6️⃣  Front‑end logic – `static/script.js`

```javascript
// -------------------------------------------------------------
// BotDoggy – AJAX form handler
// -------------------------------------------------------------
document.addEventListener("DOMContentLoaded", () => {
    const form = document.getElementById("translateForm");
    const submitBtn = document.getElementById("submitBtn");
    const resetBtn = document.getElementById("resetBtn");
    const resultSection = document.getElementById("resultSection");
    const translationBox = document.getElementById("translationBox");

    // ---------------------------------------------------------
    // Submit translation request
    // ---------------------------------------------------------
    form.addEventListener("submit", async (e) => {
        e.preventDefault();

        // Disable button to avoid double submissions
        submitBtn.disabled = true;
        submitBtn.textContent = "Translating…";

        const formData = new FormData(form);

        try {
            const resp = await fetch("/translate", {
                method: "POST",
                body: formData,
            });

            const data = await resp.json();

            if (!resp.ok || !data.success) {
                throw new Error(data.error || "Unknown server error");
            }

            // Show translation
            translationBox.textContent = data.translation;
            resultSection.classList.remove("hidden");
            form.classList.add("hidden");
        } catch (err) {
            alert("❌ Error: " + err.message);
        } finally {
            submitBtn.disabled = false;
            submitBtn.textContent = "Translate";
        }
    });

    // ---------------------------------------------------------
    // Reset UI for another bark
    // ---------------------------------------------------------
    resetBtn.addEventListener("click", () => {
        form.reset();
        resultSection.classList.add("hidden");
        form.classList.remove("hidden");
    });
});
```

