### 3.3 `transferPoints` —— 原子转账（事务）

> **核心要点**  
> 1. 使用 `db.runTransaction` 确保：  
>    - 读取发/收双方最新积分  
>    - 检查发方积分是否足够  
>    - 同时更新两条记录  
>    - 写日志  
> 2. 若任何一步失败，事务回滚，返回失败信息。  

```js
// cloudfunctions/transferPoints/index.js
const cloud = require('wx-server-sdk')
cloud.init()
const db = cloud.database()
const users = db.collection('users')
const logs = db.collection('transfer_logs')

exports.main = async (event, context) => {
  const { OPENID: fromOpenId } = cloud.getWXContext()
  const { toOpenId, amount, desc = '' } = event

  // 参数校验
  if (!toOpenId || typeof amount !== 'number' || amount <= 0) {
    return { success: false, msg: '参数错误' }
  }

  // 防止自己给自己转
  if (fromOpenId === toOpenId) {
    return { success: false, msg: '不能给自己转账' }
  }

  try {
    const result = await db.runTransaction(async (transaction) => {
      // 1️⃣ 读取发起者积分
      const fromSnap = await transaction.collection('users').doc(fromOpenId).get()
      const fromData = fromSnap.data
      if (!fromData) throw new Error('发起者不存在')
      if (fromData.points < amount) throw new Error('积分不足')

      // 2️⃣ 读取接收者积分（若不存在就创建）
      const toSnap = await transaction.collection('users').doc(toOpenId).get()
      let toData = toSnap.data
      if (!toData) {
        // 初始化接收者（积分为0）
        toData = {
          _id: toOpenId,
          nickname: '未知用户',
          avatarUrl: '',
          points: 0,
          createTime: db.serverDate(),
          updateTime: db.serverDate()
        }
        await transaction.collection('users').doc(toOpenId).set({ data: toData })
      }

      // 3️⃣ 更新两人积分（原子）
      await transaction.collection('users').doc(fromOpenId).update({
        data: {
          points: db.command.inc(-amount),
          updateTime: db.serverDate()
        }
      })
      await transaction.collection('users').doc(toOpenId).update({
        data: {
          points: db.command.inc(+amount),
          updateTime: db.serverDate()
        }
      })

      // 4️⃣ 写入日志（务必在事务内部，确保成功才留下日志）
      await transaction.collection('transfer_logs').add({
        data: {
          from: fromOpenId,
          to: toOpenId,
          amount,
          status: 'SUCCESS',
          desc,
          createTime: db.serverDate()
        }
      })
    })   // end transaction

    // 若走到这里说明事务提交成功
    return { success: true, msg: '转账成功' }

  } catch (e) {
    // 事务回滚，写入失败日志（单独写，非事务）
    await logs.add({
      data: {
        from: fromOpenId,
        to: toOpenId,
        amount,
        status: 'FAIL',
        desc,
        createTime: db.serverDate(),
        errMsg: e.message || ''
      }
    })
    return { success: false, msg: e.message || '转账失败' }
  }
}
```

