### 4.1 `utils/request.js`（统一调用云函数）

```js
// utils/request.js
function call(name, data = {}) {
  return wx.cloud.callFunction({
    name,
    data
  }).then(res => {
    if (res.result && res.result.success !== false) {
      return res.result
    } else {
      throw new Error(res.result.msg || '云函数调用失败')
    }
  })
}
export default { call }
```

