### 4.5 转账页 `pages/transfer/transfer.js`

```js
// pages/transfer/transfer.js
import request from '../../utils/request'

Page({
  data: {
    toOpenId: '',
    amount: '',
    desc: '',
    loading: false
  },

  // 输入框绑定
  onToOpenIdInput(e) { this.setData({ toOpenId: e.detail.value.trim() }) },
  onAmountInput(e)   { this.setData({ amount: e.detail.value }) },
  onDescInput(e)     { this.setData({ desc: e.detail.value }) },

  // 发起转账
  async onTransfer() {
    const { toOpenId, amount, desc } = this.data
    const numAmount = Number(amount)

    if (!toOpenId) {
      return wx.showToast({ title: '请填写收款方 openid', icon: 'none' })
    }
    if (!numAmount || numAmount <= 0) {
      return wx.showToast({ title: '请输入合法的积分数量', icon: 'none' })
    }

    this.setData({ loading: true })
    try {
      const res = await request.call('transferPoints', {
        toOpenId,
        amount: numAmount,
        desc
      })
      wx.showToast({ title: '转账成功', icon: 'success' })
      // 返回首页刷新积分
      wx.navigateBack()
    } catch (e) {
      wx.showToast({ title: e.message, icon: 'none' })
    } finally {
      this.setData({ loading: false })
    }
  }
})
```

