### 3.2 `app.py`

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Flask app that copies all *.mp4* files from SOURCE_DIR to /media/usb
and exposes a simple UI with a start button + live progress bar.
"""

import os
import shutil
import threading
from pathlib import Path
from flask import Flask, render_template, jsonify, request

app = Flask(__name__)

# --------------------------------------------------------------
# Configuration (adapt to your environment) --------------------
# --------------------------------------------------------------
SOURCE_DIR = Path("/path/to/source")          # <-- à modifier
USB_MOUNT  = Path("/media/usb")               # point de montage de la clé

# Shared state (protected by a lock)
progress = {
    "total_files": 0,
    "copied":      0,
    "running":    False,
    "error":      None,
}
progress_lock = threading.Lock()


# --------------------------------------------------------------
# Helper : copy worker -----------------------------------------
# --------------------------------------------------------------
def copy_worker():
    """Thread target – copies MP4 files and updates `progress`."""
    try:
        mp4_files = list(SOURCE_DIR.rglob("*.mp4"))
        total = len(mp4_files)

        with progress_lock:
            progress.update({
                "total_files": total,
                "copied": 0,
                "running": True,
                "error": None,
            })

        if total == 0:
            # rien à copier → on sort immédiatement
            with progress_lock:
                progress["running"] = False
            return

        # assure que le répertoire destination existe
        USB_MOUNT.mkdir(parents=True, exist_ok=True)

        for src_path in mp4_files:
            # Destination = même nom de fichier sur la clé USB
            dst_path = USB_MOUNT / src_path.name

            # copie (preserve les métadonnées)
            shutil.copy2(src_path, dst_path)

            # mise à jour du compteur
            with progress_lock:
                progress["copied"] += 1

        # fin normale
        with progress_lock:
            progress["running"] = False

    except Exception as exc:               # pragma: no cover
        # on garde l’erreur pour l’afficher côté UI
        with progress_lock:
            progress["error"] = str(exc)
            progress["running"] = False


# --------------------------------------------------------------
# Routes Flask ------------------------------------------------
# --------------------------------------------------------------

@app.route("/")
def index():
    """Page principale – bouton + progress bar."""
    return render_template("index.html")


@app.route("/start", methods=["POST"])
def start_copy():
    """Démarre le thread de copie s’il n’est pas déjà en cours."""
    with progress_lock:
        if progress["running"]:
            return jsonify({"status": "already_running"}), 409

        # (re)initialise le statut
        progress.update({
            "total_files": 0,
            "copied": 0,
            "running": True,
            "error": None,
        })

    thread = threading.Thread(target=copy_worker, daemon=True)
    thread.start()
    return jsonify({"status": "started"})


@app.route("/progress")
def get_progress():
    """Renvoie le pourcentage actuel et éventuellement une erreur."""
    with progress_lock:
        total = progress["total_files"]
        copied = progress["copied"]
        running = progress["running"]
        error = progress["error"]

    if total == 0:
        percent = 0
    else:
        percent = int((copied / total) * 100)

    return jsonify({
        "percent": percent,
        "running": running,
        "error": error,
        "total": total,
        "copied": copied,
    })


# --------------------------------------------------------------
# Entrée du script ---------------------------------------------
# --------------------------------------------------------------
if __name__ == "__main__":
    # Assurez‑vous que le répertoire source existe avant de lancer
    if not SOURCE_DIR.is_dir():
        raise RuntimeError(f"SOURCE_DIR does not exist: {SOURCE_DIR}")

    # Le serveur Flask en mode debug (pour le dev) – à désactiver en prod
    app.run(host="0.0.0.0", port=5000, debug=True)
```

**Points d’attention**

* **Permissions** – L’utilisateur qui lance le script doit pouvoir lire `SOURCE_DIR` et écrire dans `/media/usb`.  
* **Sécurité** – L’application ne fait **aucune** validation d’input côté client, donc **NE LA DÉPLOYEZ PAS** directement sur Internet.  
* **Montage USB** – Le répertoire `/media/usb` doit déjà être monté (ex : `mount /dev/sdx1 /media/usb`).  

