```javascript
// progress.js – logique côté client
(() => {
    const startBtn    = document.getElementById('startBtn');
    const progressBar = document.getElementById('progressBar');
    const statusMsg   = document.getElementById('statusMsg');

    let pollInterval = null;   // ID du setInterval

    // ----------------------------------------------------------
    // Fonction qui interroge l'endpoint /progress
    // ----------------------------------------------------------
    async function fetchProgress() {
        try {
            const resp = await fetch('/progress');
            const data = await resp.json();

            // Met à jour la barre
            const percent = data.percent;
            progressBar.style.width = `${percent}%`;
            progressBar.setAttribute('aria-valuenow', percent);
            progressBar.textContent = `${percent}%`;

            // Affiche un petit texte d’état
            if (data.error) {
                statusMsg.innerHTML = `<span class="text-danger">Erreur : ${data.error}</span>`;
                stopPolling();
                startBtn.disabled = false;
            } else if (!data.running) {
                // Fin de la copie
                statusMsg.innerHTML = `<span class="text-success">Copie terminée ! (${data.copied}/${data.total} fichiers)</span>`;
                stopPolling();
                startBtn.disabled = false;
            } else {
                // Copie en cours
                statusMsg.textContent = `Copie en cours… (${data.copied}/${data.total})`;
            }
        } catch (e) {
            console.error('Erreur lors du fetch /progress', e);
            statusMsg.innerHTML = `<span class="text-danger">Impossible de récupérer la progression.</span>`;
            stopPolling();
            startBtn.disabled = false;
        }
    }

    // ----------------------------------------------------------
    // Démarre le polling (0.5 s)
    // ----------------------------------------------------------
    function startPolling() {
        // première récupération immédiate
        fetchProgress();
        pollInterval = setInterval(fetchProgress, 500);
    }

    function stopPolling() {
        if (pollInterval) {
            clearInterval(pollInterval);
            pollInterval = null;
        }
    }

    // ----------------------------------------------------------
    // Gestion du clic sur le bouton “Lancer la copie”
    // ----------------------------------------------------------
    startBtn.addEventListener('click', async () => {
        startBtn.disabled = true;
        statusMsg.textContent = 'Initialisation…';
        progressBar.style.width = '0%';
        progressBar.textContent = '0%';
        progressBar.classList.remove('bg-success', 'bg-danger');

        try {
            const resp = await fetch('/start', { method: 'POST' });
            if (resp.status === 200) {
                const data = await resp.json();
                if (data.status === 'started') {
                    statusMsg.textContent = 'Copie lancée…';
                    startPolling();
                }
            } else if (resp.status === 409) {
                statusMsg.innerHTML = `<span class="text-warning">Une copie est déjà en cours.</span>`;
                startBtn.disabled = false;
            } else {
                const txt = await resp.text();
                statusMsg.innerHTML = `<span class="text-danger">Erreur serveur : ${txt}</span>`;
                startBtn.disabled = false;
            }
        } catch (e) {
            console.error('Erreur lors du POST /start', e);
            statusMsg.innerHTML = `<span class="text-danger">Impossible de contacter le serveur.</span>`;
            startBtn.disabled = false;
        }
    });

})();
