inline void ExpectDescription(const std::string& got,
                              const std::string& mustContain)
{
    EXPECT_NE(got.find(mustContain), std::string::npos)
        << "Full description was: \"" << got << "\""
        << "\nExpected to contain: \"" << mustContain << "\"";
}

} // anonymous namespace
```

All tests live in an **anonymous namespace** to keep the symbols local to the translation unit (a common GTest idiom).

