                           const std::string& piece,
                           const char* file,
                           int line)
{
    if (whole.find(piece) == std::string::npos) {
        GTEST_MESSAGE_AT_(file, line,
            (std::string("Expected substring not found: \"") + piece +
             "\"\nFull string was: \"" + whole + "\"").c_str(),
            ::testing::TestPartResult::kNonFatalFailure);
    }
}
#define EXPECT_CONTAINS(whole, piece) ExpectContains(whole, piece, __FILE__, __LINE__)

} // anonymous namespace

// --------------------------------------------------------------------------
// 1️⃣  ONE TEST PER BRANCH
// --------------------------------------------------------------------------
TEST(MyFuncTest, Branch_ConditionA_True) {
    auto result = myFunc(/* arguments that make condition A true */);
    EXPECT_CONTAINS(result, "something that only appears when A is true");
}

TEST(MyFuncTest, Branch_ConditionA_False) {
    auto result = myFunc(/* arguments that make condition A false */);
    EXPECT_CONTAINS(result, "something that only appears when A is false");
}

// --------------------------------------------------------------------------
// 2️⃣  COMPOSITE/COMBINED TESTS (optional but nice for regression)
// --------------------------------------------------------------------------
TEST(MyFuncTest, MultipleFlagsTogether) {
    auto result = myFunc(/* arguments that set flag X, Y, Z simultaneously */);
    EXPECT_CONTAINS(result, "X");
    EXPECT_CONTAINS(result, "Y");
    EXPECT_CONTAINS(result, "Z");
}

// --------------------------------------------------------------------------
// 3️⃣  EXCEPTION OR ERROR PATHS
// --------------------------------------------------------------------------
TEST(MyFuncTest, ThrowsOnBadInput) {
    EXPECT_THROW(myFunc(/* illegal args */),
                 std::invalid_argument);
}
```

### Tips while writing the tests

| Situation                                               | Test strategy                                                                                         |
|----------------------------------------------------------|--------------------------------------------------------------------------------------------------------|
| **`if (cond) return ...; else continue;`**              | Write **two** tests: one where `cond` is true (early‑return) and one where it is false (continue). |
| **`switch` with several `case`s**                        | One test per case, plus a default‑case test (if reachable).                                          |
| **Nested `if`s** (`if (A) { if (B) … } else …`)          | Write tests for every combination that reaches each leaf (`A&&B`, `A&&!B`, `!A`).                     |
| **Short‑circuit logical operators** (`&&`, `||`)        | Use values that force evaluation of the right‑hand side (e.g. `true && expr` or `false || expr`).     |
| **Loops with early `break`/`continue`**                 | Create data that triggers the break on the first, middle, and last iteration.                        |
| **Exceptions** (`throw`)                                 | `EXPECT_THROW` / `EXPECT_ANY_THROW` for each distinct error condition.                               |
| **Multiple flags in a string** (as in the example)      | `EXPECT_NE(str.find("word"), std::string::npos)` – you can wrap this into a helper macro.           |
| **Performance‑critical path (no side‑effects)**         | Use `ASSERT_NO_THROW` to guarantee the path does not accidentally throw while you focus on logic.   |

---

## 6️⃣  Quick checklist – “Did I cover everything?”

- [ ] **Every `if`** – at least one test where the condition is true **and** one where it is false.  
- [ ] **Every `else` / `else if`** – same as above.  
- [ ] **Every `case`** of a `switch`.  
- [ ] **All logical operators** (`&&`, `||`, `!`) – test each side both evaluated and short‑circuited.  
- [ ] **Every loop exit** – test an empty iteration, a single‑pass iteration, and a multi‑pass iteration if the loop body matters.  
- [ ] **All throws** – use `EXPECT_THROW` / `EXPECT_ANY_THROW`.  
- [ ] **All return values** – `EXPECT_EQ`, `EXPECT_NE`, `EXPECT_TRUE/FALSE`, or `EXPECT_STREQ` for strings.  
- [ ] **All side‑effects** – if the function mutates a container, assert the container’s final state.  

Run the coverage tool and verify **branch coverage = 100 %**. If any branch stays red, add the minimal test that forces that path.  

---

