## Алгоритм (псевдокод)

```
read JSON → построить граф G (adjacency list)
state_btn[6]   // текущие состояния кнопок
state_relay[6] // текущие состояния реле

loop forever
    read hardware buttons → new_btn[6]
    for each i = 0..5
        if new_btn[i] == 1 && state_btn[i] == 0   // только переход 0→1
            propagate(i, "btn")                  // стартовая вершина

    state_btn = new_btn
    // опционально: если нужно сбрасывать реле при отпускании кнопки → добавить другой цикл

---------------------------------------------------------
procedure propagate(idx, type)   // type = "btn" или "relay"
    queue ← empty
    visited[6] ← false

    // Помещаем в очередь все «выходы» из стартовой вершины
    for each edge in G where edge.from == (type=="btn"? "btn"+idx : "relay"+idx)
        push(queue, edge.to)

    while queue not empty
        node ← pop(queue)                  // node = "relayN"
        r ← номер реле (0..5) из строки node
        if visited[r]      // предотвратить бесконечный цикл
            continue
        visited[r] = true

        // переключаем состояние реле (можно просто ставить 1,
        // а если нужно toggle – изменить на !state_relay[r])
        state_relay[r] = 1                 // включаем

        // добавляем все дальнейшие переходы из текущего реле
        for each edge in G where edge.from == node
            push(queue, edge.to)
```

* **BFS** (очередь) гарантирует, что каждый реле включится не более одного раза за один цикл, независимо от наличия циклов в графе.  
