## Реализация на C с использованием **mjson**

Ниже полностью рабочий пример (компилируется под любой ANSI‑C, только требуется `mjson.h` и `mjson.c`).

```c
/* --------------  mjson_example.c  ---------------- */
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include "mjson.h"

/* ---------- Константы ---------- */
#define N_BTN   6
#define N_RELAY 6
#define MAX_EDGES 64          /* достаточно для простого проекта */

/* ---------- Структуры ---------- */
typedef struct {
    int from;     /* 0..5 – кнопка, 6..11 – реле (offset 6) */
    int to;       /* 0..5 – реле (в графе только реле могут быть получателем) */
} Edge;

/* ---------- Глобальные переменные ---------- */
static bool btn_state[N_BTN]   = {0};
static bool relay_state[N_RELAY] = {0};

static Edge edges[MAX_EDGES];
static int  edge_cnt = 0;

/* ---------- Утилиты ---------- */
static int name_to_index(const char *name)
{
    /* name = "btn0".."btn5"  или  "relay0".."relay5" */
    if (strncmp(name, "btn", 3) == 0) {
        int n = name[3] - '0';
        if (n >= 0 && n < N_BTN) return n;                // 0..5
    } else if (strncmp(name, "relay", 5) == 0) {
        int n = name[5] - '0';
        if (n >= 0 && n < N_RELAY) return 6 + n;          // 6..11
    }
    return -1;   /* ошибка */
}

/* ---------- Парсинг JSON ---------- */
static bool parse_json(const char *json)
{
    edge_cnt = 0;

    int i = 0;
    while (1) {
        const char *path = mjson_find(json, i, "$.connections[#]");
        if (!path) break;                       // нет больше элементов

        /* Считываем from и to как строки */
        char from[16] = {0}, to[16] = {0};
        if (!mjson_get_string(json, path, "from", from, sizeof(from))) break;
        if (!mjson_get_string(json, path, "to",   to,   sizeof(to)))   break;

        int from_idx = name_to_index(from);
        int to_idx   = name_to_index(to);   // to всегда реле → 6..11

        if (from_idx < 0 || to_idx < 6) {
            fprintf(stderr, "Bad connection: %s -> %s\n", from, to);
            return false;
        }

        edges[edge_cnt].from = from_idx;
        edges[edge_cnt].to   = to_idx - 6;   // сохраняем номер реле 0..5
        edge_cnt++;

        i = mjson_next(json, i);
    }

    return true;
}

/* ---------- Прототипы алгоритма ---------- */
static void propagate_from_button(int btn_idx);
static void propagate_from_relay (int relay_idx);

/* ---------- Реализация propagate ---------- */
static void propagate_from_button(int btn_idx)
{
    bool visited[N_RELAY] = {0};
    int queue[N_RELAY];
    int q_head = 0, q_tail = 0;

    /* Ищем все edges, где from == btn_idx */
    for (int e = 0; e < edge_cnt; ++e) {
        if (edges[e].from == btn_idx) {
            queue[q_tail++] = edges[e].to;
        }
    }

    while (q_head < q_tail) {
        int r = queue[q_head++];
        if (visited[r]) continue;
        visited[r] = true;

        /* Включаем реле (можно заменить на toggle) */
        relay_state[r] = true;
        printf("Relay %d turned ON (by button %d)\n", r, btn_idx);

        /* Добавляем реле → реле переходы */
        for (int e = 0; e < edge_cnt; ++e) {
            if (edges[e].from == 6 + r) {          // from = relayX (offset 6)
                queue[q_tail++] = edges[e].to;
            }
        }
    }
}

/* Если захотим инициировать цепочку от уже включённого реле,
   просто вызываем эту же функцию (она почти одинаковая) */
static void propagate_from_relay(int relay_idx)
{
    bool visited[N_RELAY] = {0};
    int queue[N_RELAY];
    int q_head = 0, q_tail = 0;

    /* стартовый элемент – сам реле (чтобы обработать его «выходы») */
    queue[q_tail++] = relay_idx;

    while (q_head < q_tail) {
        int r = queue[q_head++];
        if (visited[r]) continue;
        visited[r] = true;

        /* Включаем (если ещё не включено) */
        if (!relay_state[r]) {
            relay_state[r] = true;
            printf("Relay %d turned ON (by relay propagation)\n", r);
        }

        /* Двигаемся дальше по графу */
        for (int e = 0; e < edge_cnt; ++e) {
            if (edges[e].from == 6 + r) {
                queue[q_tail++] = edges[e].to;
            }
        }
    }
}

