        "   {\"from\":\"btn0\", \"to\":\"relay2\"},"
        "   {\"from\":\"btn1\", \"to\":\"relay0\"},"
        "   {\"from\":\"relay2\", \"to\":\"relay4\"},"
        "   {\"from\":\"relay4\", \"to\":\"relay5\"},"
        "   {\"from\":\"relay0\", \"to\":\"relay1\"},"
        "   {\"from\":\"relay0\", \"to\":\"relay3\"}"
        " ]"
        "}";

    if (!parse_json(json_cfg)) {
        fprintf(stderr, "Failed to parse configuration\n");
        return 1;
    }

    printf("Configuration parsed, %d edges loaded.\n", edge_cnt);

    /* -----------------------------------------------------------------
       Симуляция: имитируем чтение кнопок в бесконечном цикле.
       В реальном контроллере вместо этого будет ISR/ poll GPIO.
       ----------------------------------------------------------------- */
    while (1) {
        /* ---------- 1) Чтение текущих состояний кнопок ----------- */
        bool cur_btn[N_BTN] = {0};
        printf("\nEnter button states (6 digits 0/1, например 100010): ");
        char line[32];
        if (!fgets(line, sizeof(line), stdin)) break;

        if (strlen(line) < N_BTN) {
            printf("Too short, try again.\n");
            continue;
        }

        for (int i = 0; i < N_BTN; ++i) {
            cur_btn[i] = (line[i] == '1');
        }

        /* ---------- 2) Обработать только восходящие фронты -------- */
        for (int i = 0; i < N_BTN; ++i) {
            if (cur_btn[i] && !btn_state[i]) {   // 0 → 1
                propagate_from_button(i);
            }
        }

        /* ---------- 3) Сохранить новое состояние ------------------ */
        memcpy(btn_state, cur_btn, sizeof(btn_state));

        /* ---------- 4) Текущее состояние реле --------------------- */
        printf("\nCurrent relay states: ");
        for (int i = 0; i < N_RELAY; ++i) {
            printf("%d", relay_state[i] ? 1 : 0);
        }
        printf("\n");
    }

    return 0;
}
```

### Пояснения к коду

| Блок | Что делает |
|------|------------|
|`name_to_index`|Преобразует строку `"btnX"` → 0‑5, `"relayX"` → 6‑11 (добавляем offset 6, чтобы различать типы в графе).|
|`parse_json`|С помощью `mjson` ищет массив `connections`, читает поля `from` и `to`, заполняет массив `edges`.|
|`propagate_from_button`|BFS‑проход от начала‑кнопки, включающий все реле, достижимые через цепочки.|
|`propagate_from_relay`|Тот же алгоритм, но стартует от уже включённого реле (может потребоваться, если кто‑то вручную меняет состояние реле).|
|`main`|Для демонстрации – читает строку из stdin (шесть символов 0/1) и генерирует событие `0→1`. В реальном устройстве заменяется чтением GPIO (interrupt/ poll).|

---

## Как адаптировать под ваш контроллер

1. **Ввод кнопок** – вместо чтения из `stdin` используйте драйвер GPIO/ADC.  
   ```c
   cur_btn[0] = HAL_GPIO_ReadPin(BTN0_PORT, BTN0_PIN);
   ...
   ```
2. **Управление реле** – вместо простого `relay_state[i] = true;` записывайте в порт:  
   ```c
   HAL_GPIO_WritePin(RELAY_PORT[i], RELAY_PIN[i], GPIO_PIN_SET);
   ```
3. **Обновление состояний** – если требуется, чтобы реле выключались, когда нет активных предшественников, добавьте отдельный проход, который проверяет:  
   ```c
   bool should_be_on = false;
   for (each edge where edge.to == i) {
       if (edge.from < 6 && btn_state[edge.from])          should_be_on = true;
       if (edge.from >= 6 && relay_state[edge.from-6])    should_be_on = true;
   }
   relay_state[i] = should_be_on;
   ```
4. **Обработка циклов** – уже реализовано через массив `visited`. Если в графе могут быть более 6 реле, замените `queue` и `visited` на динамические структуры (или увеличьте их размер).  

---

## Что ещё может понадобиться

| Функция | Описание |
