## 2. 主要函数概览

| 函数 | 功能 |
|------|------|
| `int safety_check(int avail[], PCB *procs, int n)` | **安全性检查**：在给定可用向量 `avail` 的情况下，判断系统是否仍然安全（即是否存在一个安全序列）。 |
| `void create_process(PCB *procs, int *cnt, int *next_id)` | **随机创建新进程**（只要系统中进程数 < `MAX_P`），并把它加入就绪队列。 |
| `int try_allocate(PCB *p, int avail[], int req[])` | **尝试分配资源**：若 `req` 不超过 `need` 且 `avail` 足够，先临时分配后做安全性检查，成功则正式分配并返回 1，失败则恢复并返回 0。 |
| `void release_resources(PCB *p, int avail[])` | **进程完成后释放全部资源**。 |
| `void unblock_processes(PCB *procs, int n, int avail[])` | **检查阻塞队列**，把能再次分配的进程从 BLOCK → WAIT。 |
| `void print_system(int step, PCB *procs, int n, int avail[])` | **打印一次调度结果**：包括正在运行的进程、就绪/阻塞/完成队列以及每个 PCB 的详细信息。 |
| `int schedule(PCB *procs, int *n, int avail[])` | **一次时间片的调度**：轮转就绪队列中的进程、产生随机请求、调用银行家算法、处理完成/阻塞/就绪转换。 |

---

## 3. 完整代码

```c
/********************************************************************
 *  Banker's Algorithm + Round‑Robin Scheduler (简易模拟器)
 *  资源: A=10, B=15, C=8
 *  最多并发进程: 5
 *  状态: WAIT、RUN、BLOCK、FINISH
 *
 *  编译: gcc -Wall -O2 -o banker banker.c
 *  运行: ./banker
 ********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N_RES   3               // 资源种类数
#define MAX_P   5               // 最大并发进程数
#define MAX_NAME 4              // 进程名最大长度 ("p1\0")
#define MAX_STEPS 50            // 运行的调度步数，您可以自行增大

typedef enum { WAIT, RUN, BLOCK, FINISH } State;

typedef struct {
    char name[MAX_NAME];       // 进程名
    int max[N_RES];            // 最大需求
    int alloc[N_RES];          // 已分配
    int need[N_RES];           // 仍需
    State state;               // 当前状态
    int request[N_RES];        // BLOCK 时的请求向量
} PCB;

/* ---------- 全局资源向量 ---------- */
int TOTAL[N_RES] = {10, 15, 8};   // 系统总资源数
/* ----------------------------------- */

/* ---------- 工具函数 ---------- */
const char* state_str(State s) {
    switch (s) {
        case WAIT:   return "W";   // Wait (Ready)
        case RUN:    return "R";   // Run
        case BLOCK:  return "B";   // Block
        case FINISH: return "F";   // Finish
        default:     return "?";
    }
}

/* 判断安全性：返回 1 表示安全，0 表示不安全 */
int safety_check(int avail[], PCB *procs, int n) {
    int work[N_RES];
    int finish[MAX_P] = {0};
    int i, j, progress;

    memcpy(work, avail, sizeof(work));

    /* 只考虑非 FINISH 的进程 */
    while (1) {
        progress = 0;
        for (i = 0; i < n; ++i) {
            if (procs[i].state == FINISH || finish[i]) continue;
            int can = 1;
            for (j = 0; j < N_RES; ++j)
                if (procs[i].need[j] > work[j]) { can = 0; break; }
            if (can) {
                for (j = 0; j < N_RES; ++j) work[j] += procs[i].alloc[j];
                finish[i] = 1;
                progress = 1;
            }
        }
        if (!progress) break;   // 没有进程能够继续
    }

    /* 若所有非完成进程均已 finish，则安全 */
    for (i = 0; i < n; ++i)
        if (procs[i].state != FINISH && !finish[i]) return 0;
    return 1;
}

/* 产生 0~need[i] 的随机数 */
int rand_between(int lo, int hi) {          // inclusive
    return lo + rand() % (hi - lo + 1);
}

/* 创建一个新进程（只要系统中实际进程数 < MAX_P） */
void create_process(PCB *procs, int *cnt, int *next_id) {
    if (*cnt >= MAX_P) return;      // 已满

    PCB *p = &procs[*cnt];
    snprintf(p->name, MAX_NAME, "p%d", (*next_id)++);
    p->state = WAIT;

    /* 随机产生 max 需求，不能超过系统总资源 */
    for (int i = 0; i < N_RES; ++i)
        p->max[i] = rand_between(0, TOTAL[i]);   // 允许 0

    /* 初始分配为 0 */
    for (int i = 0; i < N_RES; ++i) {
        p->alloc[i] = 0;
        p->need[i] = p->max[i];
        p->request[i] = 0;
    }

    (*cnt)++;
}

/* 尝试把 req 分配给进程 p；
   需要满足 req <= need && req <= avail，并且分配后系统仍安全 */
int try_allocate(PCB *p, int avail[], int req[]) {
    int i;
    /* 先检查基本限制 */
    for (i = 0; i < N_RES; ++i) {
        if (req[i] > p->need[i] || req[i] > avail[i]) return 0;
    }

    /* 暂时分配 */
    for (i = 0; i < N_RES; ++i) {
        avail[i]      -= req[i];
        p->alloc[i]   += req[i];
        p->need[i]    -= req[i];
    }

    /* 安全性检查 */
    // 注意：这里的安全检查只需要把所有进程整体传进去，函数内部会忽略 FINISH 进程
    // 所以这里暂不需要额外的参数
    // 该函数在调用前要传入当前进程表和进程数
    // 为了避免循环依赖，这里只返回安全性结果，由调用者自行决定是否回滚
    //（我们在 schedule() 中会重新调用 safety_check）
    return 1;   // 实际安全性将在 schedule() 中再次检查
}

/* 释放进程 p 持有的全部资源 */
void release_resources(PCB *p, int avail[]) {
    for (int i = 0; i < N_RES; ++i) {
        avail[i] += p->alloc[i];
        p->alloc[i] = 0;
        p->need[i] = 0;
        p->max[i] = 0;
    }
}

/* 检查阻塞队列，尝试把能够满足请求的进程唤醒 */
void unblock_processes(PCB *procs, int n, int avail[]) {
    for (int i = 0; i < n; ++i) {
        if (procs[i].state != BLOCK) continue;
        int can = 1;
        for (int j = 0; j < N_RES; ++j)
            if (procs[i].request[j] > avail[j]) { can = 0; break; }

        if (!can) continue;     // 资源仍不足

        /* 暂时分配请求，看是否安全 */
        int tmpAvail[N_RES];
        memcpy(tmpAvail, avail, sizeof(tmpAvail));
        for (int j = 0; j < N_RES; ++j) {
            tmpAvail[j]        -= procs[i].request[j];
            procs[i].alloc[j]  += procs[i].request[j];
            procs[i].need[j]   -= procs[i].request[j];
        }

        if (safety_check(tmpAvail, procs, n)) {
            /* 安全 → 正式分配 */
            memcpy(avail, tmpAvail, sizeof(avail));
            procs[i].state = WAIT;
            // 清除请求向量
            for (int j = 0; j < N_RES; ++j) procs[i].request[j] = 0;
        } else {
            /* 不安全 → 恢复临时分配 */
            for (int j = 0; j < N_RES; ++j) {
                procs[i].alloc[j] -= procs[i].request[j];
                procs[i].need[j]  += procs[i].request[j];
            }
        }
    }
}

/* 打印系统当前状态（一次调度） */
void print_system(int step, PCB *procs, int n, int avail[]) {
    printf("=== Step %2d ===\n", step);
    printf("Available   : A=%2d B=%2d C=%2d\n", avail[0], avail[1], avail[2]);

    printf("Running     : ");
    int hasRun = 0;
    for (int i = 0; i < n; ++i)
        if (procs[i].state == RUN) { printf("%s ", procs[i].name); hasRun = 1; }
    if (!hasRun) printf("-");

    printf("\nReady queue : ");
    int hasReady = 0;
    for (int i = 0; i < n; ++i)
        if (procs[i].state == WAIT) { printf("%s ", procs[i].name); hasReady = 1; }
    if (!hasReady) printf("-");

    printf("\nBlocked queue: ");
    int hasBlock = 0;
    for (int i = 0; i < n; ++i)
        if (procs[i].state == BLOCK) { printf("%s ", procs[i].name); hasBlock = 1; }
    if (!hasBlock) printf("-");

    printf("\nFinished    : ");
    int hasFin = 0;
    for (int i = 0; i < n; ++i)
        if (procs[i].state == FINISH) { printf("%s ", procs[i].name); hasFin = 1; }
    if (!hasFin) printf("-");

    printf("\n\n--- PCB List -------------------------------------------------\n");
    printf("%-4s %-5s %-5s %-5s %-5s %-5s %-5s %-5s\n",
           "PID", "Amax", "Bmax", "Cmax", "Aalloc","Balloc","Calloc","State");
    for (int i = 0; i < n; ++i) {
        PCB *p = &procs[i];
        printf("%-4s %-5d %-5d %-5d %-5d %-5d %-5d %-5s\n",
               p->name,
               p->max[0], p->max[1], p->max[2],
               p->alloc[0], p->alloc[1], p->alloc[2],
               state_str(p->state));
    }
    printf("----------------------------------------------------------------\n\n");
}

/* ---------- 调度一次时间片 ----------
   返回 0 结束模拟， 1 继续
   轮转就绪队列中的进程，若没有就绪进程则直接返回 1 (模拟空闲) */
int schedule(PCB *procs, int *cnt, int avail[]) {
    static int rr_index = 0;          // 轮转指针，指向下一个就绪进程

    /* 1）挑选下一个就绪进程作为 “运行” */
    int n = *cnt;
    int run_idx = -1;
    for (int i = 0; i < n; ++i) {
        int idx = (rr_index + i) % n;
        if (procs[idx].state == WAIT) {
            run_idx = idx;
            rr_index = (idx + 1) % n;       // 下次从其后的进程开始找
            break;
        }
    }
    if (run_idx == -1) {
        /* 没有就绪进程——所有进程要么阻塞要么已完成 */
        return 1;   // 继续模拟空闲时间
    }

    PCB *p = &procs[run_idx];
    p->state = RUN;

    /* 2）生成本时间片的随机资源请求 */
    int req[N_RES];
    int allZero = 1;
    for (int i = 0; i < N_RES; ++i) {
        req[i] = rand_between(0, p->need[i]);   // 包括 0
        if (req[i] != 0) allZero = 0;
    }

    /* 3）如果请求恰好等于全部剩余需求，则视为 “完成” */
    int request_is_finish = 1;
    for (int i = 0; i < N_RES; ++i)
        if (req[i] != p->need[i]) { request_is_finish = 0; break; }

    if (request_is_finish && !allZero) {
        /* 为了让进程一次性完成，仅在请求不全是 0 时才执行 */
        // 先做安全性检查（在满足请求的前提下）
        int tmpAvail[N_RES];
        memcpy(tmpAvail, avail, sizeof(tmpAvail));
        for (int i = 0; i < N_RES; ++i) {
            tmpAvail[i]      -= req[i];
            p->alloc[i]      += req[i];
            p->need[i]       -= req[i];
        }
        if (safety_check(tmpAvail, procs, n)) {
            // 安全 → 正式分配并立刻完成
            memcpy(avail, tmpAvail, sizeof(avail));
            p->state = FINISH;
            release_resources(p, avail);
            // 完成后产生一个新进程（保持系统中最多 MAX_P 个活跃进程）
            int dummy = 0;
            create_process(procs, cnt, &dummy);
        } else {
            // 不安全 → 恢复
            for (int i = 0; i < N_RES; ++i) {
                p->alloc[i] -= req[i];
                p->need[i]  += req[i];
            }
            p->state = WAIT;   // 仍然在就绪队列
        }
        unblock_processes(procs, n, avail);
        return 1;
    }

    /* 4）普通请求：尝试分配 */
    int canAllocate = 1;
    for (int i = 0; i < N_RES; ++i)
        if (req[i] > p->need[i] || req[i] > avail[i]) { canAllocate = 0; break; }

    if (canAllocate && !allZero) {
        // 暂时分配
        int tmpAvail[N_RES];
        memcpy(tmpAvail, avail, sizeof(tmpAvail));
        for (int i = 0; i < N_RES; ++i) {
            tmpAvail[i]      -= req[i];
            p->alloc[i]      += req[i];
            p->need[i]       -= req[i];
        }

        if (safety_check(tmpAvail, procs, n)) {
            // 安全 → 正式分配
            memcpy(avail, tmpAvail, sizeof(avail));
            p->state = WAIT;   // 仍在就绪（会在下一轮被调度）
        } else {
            // 不安全 → 回滚，进入阻塞
            for (int i = 0; i < N_RES; ++i) {
                p->alloc[i] -= req[i];
                p->need[i]  += req[i];
                p->request[i] = req[i];   // 记录请求以便后续解除阻塞
            }
            p->state = BLOCK;
        }
    } else {
        // 资源不足 → 阻塞（把请求记录下来，以便以后尝试）
        if (!allZero) {
            for (int i = 0; i < N_RES; ++i) p->request[i] = req[i];
            p->state = BLOCK;
        } else {
            // 本时间片没有任何请求，保持就绪状态即可
            p->state = WAIT;
        }
    }

    /* 5）检查是否有进程已经满足所有需求（need 全部为 0） */
    for (int i = 0; i < n; ++i) {
        if (procs[i].state != FINISH) {
            int done = 1;
            for (int j = 0; j < N_RES; ++j)
                if (procs[i].need[j] != 0) { done = 0; break; }
            if (done) {
                procs[i].state = FINISH;
                release_resources(&procs[i], avail);
                // 创建新进程补位（保持活跃进程数不低于 1）
                int dummy = 0;
                create_process(procs, cnt, &dummy);
            }
        }
    }

    /* 6）尝试唤醒阻塞进程 */
    unblock_processes(procs, n, avail);
    return 1;   // 继续模拟
}

/* ---------- 主函数 ---------- */
int main(void) {
    srand((unsigned)time(NULL));

    PCB processes[MAX_P];
    int proc_cnt = 0;          // 当前系统中进程的个数（包括 FINISH）
    int next_id = 1;           // 进程编号递增，用于生成唯一名字

    /* 初始可用资源向量 = 系统总资源 */
    int available[N_RES];
    memcpy(available, TOTAL, sizeof(available));

    /* 初始创建若干进程（不一定满 5） */
    int init_num = rand_between(2, MAX_P);
    for (int i = 0; i < init_num; ++i)
        create_process(processes, &proc_cnt, &next_id);

    printf("=== Banker's Algorithm + Round‑Robin Simulation ===\n");
    printf("System resources: A=%d B=%d C=%d\n", TOTAL[0], TOTAL[1], TOTAL[2]);
    printf("Initially %d process(es) created.\n\n", init_num);

    /* 主循环：每一步模拟一次时间片 */
    for (int step = 1; step <= MAX_STEPS; ++step) {
        print_system(step, processes, proc_cnt, available);
        if (!schedule(processes, &proc_cnt, available))
            break;
        /* 简单地让用户看到每一步的变化（可自行去掉） */
        // usleep(300000);   // 300ms，需 <unistd.h>，在 Windows 可注释掉
    }

    printf("=== Simulation finished after %d steps ===\n", MAX_STEPS);
    return 0;
}
```

