    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, fp) != -1) {
        /* Strip newline */
        line[strcspn(line, "\r\n")] = '\0';

        /* Parse */
        int id, done;
        char desc[MAX_DESC_LEN];
        if (sscanf(line, "%d\t%d\t%255[^\n]", &id, &done, desc) != 3)
            continue;  /* malformed → skip */

        /* Ensure capacity */
        if (list->count == list->cap) {
            size_t newcap = list->cap ? list->cap * 2 : 8;
            TodoItem *tmp = realloc(list->items, newcap * sizeof *tmp);
            if (!tmp) { free(line); fclose(fp); return false; }
            list->items = tmp;
            list->cap = newcap;
        }
        TodoItem *it = &list->items[list->count++];
        it->id   = id;
        it->done = (done != 0);
        strncpy(it->desc, desc, MAX_DESC_LEN-1);
        it->desc[MAX_DESC_LEN-1] = '\0';
    }
    free(line);
    fclose(fp);
    return true;
}

/* Save all tasks to DB_FILE (overwrites old file) */
static bool todo_save(const TodoList *list)
{
    FILE *fp = fopen(DB_FILE, "w");
    if (!fp) return false;

    for (size_t i = 0; i < list->count; ++i) {
        const TodoItem *it = &list->items[i];
        fprintf(fp, "%d\t%d\t%s\n", it->id, it->done ? 1 : 0, it->desc);
    }
    fclose(fp);
    return true;
}

/* Add a new task – id is always max(existing)+1 */
static void todo_add(TodoList *list, const char *desc)
{
    if (list->count == list->cap) {
        size_t newcap = list->cap ? list->cap * 2 : 8;
        TodoItem *tmp = realloc(list->items, newcap * sizeof *tmp);
        if (!tmp) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        list->items = tmp;
        list->cap = newcap;
    }
    TodoItem *it = &list->items[list->count];
    it->id   = (list->count == 0) ? 1 : list->items[list->count-1].id + 1;
    it->done = false;
    strncpy(it->desc, desc, MAX_DESC_LEN-1);
    it->desc[MAX_DESC_LEN-1] = '\0';
    ++list->count;
}

/* Print all tasks in a pretty table */
static void todo_print(const TodoList *list)
{
    if (list->count == 0) {
        puts("\nNo tasks. You can add one with 'add' or 'a'.");
        return;
    }

    puts("\n\033[1;33mID  Done  Description\033[0m");
    puts("------------------------------");
    for (size_t i = 0; i < list->count; ++i) {
        const TodoItem *it = &list->items[i];
        /* colour: green for done, red for pending */
        const char *col = it->done ? "\x1b[32m" : "\x1b[31m";
        printf("%-3d %s%-4s\x1b[0m  %s\n",
               it->id,
               col,
               it->done ? "✔" : "✘",
               it->desc);
    }
}

/* Toggle the done flag of a task with the given id.
   Returns true if a task was found.
*/
static bool todo_toggle(TodoList *list, int id)
{
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].id == id) {
            list->items[i].done = !list->items[i].done;
            return true;
        }
    }
    return false;
}

/* Remove a task by id. Returns true on success.
   The array is compacted, and later tasks keep their original ids.
*/
static bool todo_delete(TodoList *list, int id)
{
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].id == id) {
            /* Shift everything left */
            memmove(&list->items[i],
                    &list->items[i+1],
                    (list->count - i - 1) * sizeof(TodoItem));
            --list->count;
            return true;
        }
    }
    return false;
}

/* Simple pause helper (optional) */
static void press_enter_to_continue(void)
{
    puts("\nPress ENTER to continue...");
    while (getchar()!='\n');
}
```

