## 2. Mã nguồn hoàn chỉnh (C)

```c
/*******************************************************************
 *  Lab 5.4 – Tính tiền lương hàng tuần
 *  Sử dụng macro, if‑else.
 *******************************************************************/
#include <stdio.h>

/* ---------- Định nghĩa macro ---------- */
#define PAYRATE      12.00   /* $12 / giờ */
#define TAXRATE_300  0.15    /* 15% */
#define TAXRATE_450  0.20    /* 20% */
#define TAXRATE_REST 0.25    /* 25% */
#define OVERTIME     40      /* giờ làm thường */

/* ---------- Hàm tính thuế dựa trên gross (có thể dùng switch) ---------- */
double calcTax(double gross)
{
    if (gross <= 300.0)
        return gross * TAXRATE_300;
    else if (gross <= 450.0)
        return gross * TAXRATE_450;
    else
        return gross * TAXRATE_REST;
}

/* ---------- Hàm chính ---------- */
int main(void)
{
    /* ----- Khai báo biến ----- */
    unsigned int hours = 0;
    double grossPay = 0.0;
    double taxes    = 0.0;
    double netPay   = 0.0;

    /* ----- Nhập số giờ ----- */
    printf("Nhap so gio lam viec trong 1 tuan: ");
    if (scanf("%u", &hours) != 1) {
        printf("Loi nhap du lieu!\n");
        return 1;
    }

    /* ----- Tính lương gross ----- */
    if (hours <= OVERTIME) {
        grossPay = hours * PAYRATE;
    } else {
        /* Lương cơ bản cho OVERTIME giờ */
        double basic = OVERTIME * PAYRATE;
        /* Lương làm thêm: 1.5 lần lương cơ bản */
        double overtimePay = (hours - OVERTIME) * (1.5 * PAYRATE);
        grossPay = basic + overtimePay;
    }

    /* ----- Tính thuế ----- */
    taxes = calcTax(grossPay);

    /* ----- Tính lương net ----- */
    netPay = grossPay - taxes;

    /* ----- In kết quả ----- */
    printf("\n--- Ket qua tinh luong ---\n");
    printf("So gio lam viec : %u\n", hours);
    printf("Luong gross   : $%6.2f\n", grossPay);
    printf("Thue (%%)      : $%6.2f\n", taxes);
    printf("Luong net     : $%6.2f\n", netPay);

    return 0;
}
```

