#include <string.h>

/* ------------------------------- Constantes ---------------------------------------- */
#define MAX_LIVROS   5               /* tamanho máximo do vetor de livros          */
#define MAX_FILA    5                /* tamanho máximo da fila de espera           */
#define TAM_NOME   50                /* tamanho máximo para nomes                  */
#define TAM_TELEFONE 15               /* tamanho máximo para telefone               */

/* ------------------------------- Tipos ------------------------------------------------ */
typedef struct {
    int   codigo;                     /* código único do livro                     */
