    int   codigoLivro;               /* código do livro desejado                 */
    char  telefone[TAM_TELEFONE];    /* telefone para contato                    */
} PessoaFila;

/* ------------------------------- Variáveis globais ----------------------------------- */
static Livro   vetorLivros[MAX_LIVROS];
static int     qtdLivros = 0;                 /* número de livros inseridos                */

static PessoaFila filaEspera[MAX_FILA];
