static int        tras      = -1;              /* índice do último da fila                  */
static int        qtdFila   = 0;               /* quantos elementos na fila                */

/* ------------------------------- Protótipos (cabeçalhos) ---------------------------- */
void menu(void);
void inserirLivro(void);
int  buscarLivroPorCodigo(int cod);                 /* retorna índice ou -1 */
