/* ------------------------------- Funções ------------------------------------------- */

/* -------------------- Função principal --------------------------------------------- */
int main(void)
{
    menu();                     /* tudo o que o programa faz está dentro da rotina menu */
    return 0;
}

/* -------------------- Menu -------------------------------------------------------- */
