    do {
        printf("\n=== SISTEMA DE FILA DE ESPERA DE LIVROS ===\n");
        printf("1 - Inserir livro no vetor\n");
        printf("2 - Buscar disponibilidade do livro\n");
        printf("3 - Listar livros\n");
        printf("4 - Listar pessoas da fila de espera\n");
        printf("5 - Atualizar disponibilidade de um livro (devolução)\n");
        printf("6 - Sair\n");
        printf("Escolha a opção: ");
