        switch (opcao) {
            case 1: inserirLivro();                break;
            case 2: buscarDisponibilidade();        break;
            case 3: listarLivros();                 break;
            case 4: listarFila();                   break;
            case 5: atualizarDisponibilidade();     break;
            case 6: printf("Encerrando o programa...\n"); break;
            default: printf("Opção inválida!\n");
        }
    } while (opcao != 6);
