    fgets(l.titulo, TAM_NOME, stdin);
    l.titulo[strcspn(l.titulo, "\n")] = '\0';   /* remove '\n' */

    l.disponivel = 1;                           /* ao inserir, o livro começa disponível */

    vetorLivros[qtdLivros++] = l;
