/* -------------------- Busca livro por código (retorna índice) -------------------- */
int buscarLivroPorCodigo(int cod)
{
    for (int i = 0; i < qtdLivros; ++i) {
        if (vetorLivros[i].codigo == cod)
            return i;
    }
    return -1;                                   /* não encontrado */
}

/* -------------------- Buscar disponibilidade e, se indisponível, entrar na fila */
void buscarDisponibilidade(void)
{
    int cod;
    printf("\n--- Consulta de disponibilidade ---\n");
    printf("Informe o código do livro: ");
    scanf("%d", &cod);
    getchar();

    int idx = buscarLivroPorCodigo(cod);
    if (idx == -1) {
        printf("Livro não encontrado.\n");
        return;
    }

    if (vetorLivros[idx].disponivel) {
        printf("Livro \"%s\" está disponível.\n", vetorLivros[idx].titulo);
