           somente “consulta”, deixamos assim. */
    } else {
        printf("Livro \"%s\" está emprestado.\n", vetorLivros[idx].titulo);
        enfileirarPessoa(cod);
    }
}

/* -------------------- Enfileirar pessoa ------------------------------------------- */
void enfileirarPessoa(int codLivro)
{
    if (filaCheia()) {
        printf("A fila de espera está cheia! Não é possível registrar mais aguardando.\n");
        return;
    }

    PessoaFila p;
    printf("Nome da pessoa que deseja o livro: ");
    fgets(p.nomePessoa, TAM_NOME, stdin);
    p.nomePessoa[strcspn(p.nomePessoa, "\n")] = '\0';

    p.codigoLivro = codLivro;

    printf("Telefone para contato: ");
    fgets(p.telefone, TAM_TELEFONE, stdin);
    p.telefone[strcspn(p.telefone, "\n")] = '\0';

    /* inserção circular */
    tras = (tras + 1) % MAX_FILA;
    filaEspera[tras] = p;
    qtdFila++;

    printf("Pessoa adicionada à fila de espera do livro %d.\n", codLivro);
}

/* -------------------- Verificar se a fila está cheia ----------------------------- */
int filaCheia(void)
{
    return qtdFila == MAX_FILA;
}

/* -------------------- Verificar se a fila está vazia ---------------------------- */
int filaVazia(void)
{
    return qtdFila == 0;
}

/* -------------------- Listar todos os livros ------------------------------------ */
void listarLivros(void)
{
    if (qtdLivros == 0) {
        printf("\nNenhum livro cadastrado.\n");
        return;
    }

    printf("\n--- Lista de livros (máx. %d) ---\n", MAX_LIVROS);
    for (int i = 0; i < qtdLivros; ++i) {
        printf("Código: %d | Título: %s | %s\n",
               vetorLivros[i].codigo,
               vetorLivros[i].titulo,
               vetorLivros[i].disponivel ? "Disponível" : "Emprestado");
    }
}

/* -------------------- Listar fila de espera ------------------------------------ */
void listarFila(void)
{
    if (filaVazia()) {
        printf("\nA fila de espera está vazia.\n");
        return;
    }

    printf("\n--- Pessoas na fila de espera (máx. %d) ---\n", MAX_FILA);
    int i = frente, cont = 0;
    while (cont < qtdFila) {
        PessoaFila *p = &filaEspera[i];
        printf("Pos %d | Nome: %s | Código do Livro: %d | Telefone: %s\n",
               cont + 1, p->nomePessoa, p->codigoLivro, p->telefone);
        i = (i + 1) % MAX_FILA;
        ++cont;
    }
}

/* -------------------- Atualizar disponibilidade (devolução) ------------------- */
/* Esta rotina recebe o código do livro como parâmetro (conforme requisito 2). */
void atualizarDisponibilidade(void)
{
    int cod;
    printf("\n--- Devolução de livro ---\n");
    printf("Informe o código do livro que está sendo devolvido: ");
    scanf("%d", &cod);
    getchar();

    int idx = buscarLivroPorCodigo(cod);
    if (idx == -1) {
        printf("Livro não encontrado.\n");
        return;
    }

    if (vetorLivros[idx].disponivel) {
        printf("O livro já está marcado como disponível.\n");
        return;
    }

    vetorLivros[idx].disponivel = 1;      /* agora está livre */
    printf("Livro \"%s\" devolvido e marcado como disponível.\n", vetorLivros[idx].titulo);

    /* Se houver alguém na fila esperando esse mesmo livro, atenda o primeiro */
    if (desenfileirarPrimeiroDaFila(cod)) {
        /* O empréstimo ao primeiro da fila implica mudar a disponibilidade para
           “emprestado” novamente e avisar a pessoa. */
        vetorLivros[idx].disponivel = 0;
        printf("O primeiro da fila foi atendido e o livro foi emprestado novamente.\n");
    }
}

/* -------------------- Remover o primeiro da fila que espera o livro ----------- */
/* Retorna 1 se alguém foi atendido, 0 se não havia ninguém na fila para esse livro. */
int desenfileirarPrimeiroDaFila(int codLivro)
{
    if (filaVazia())
        return 0;

    /* Percorre a fila a partir de “frente” procurando o primeiro registro
       cujo codigoLivro seja o mesmo que o passado. Quando encontrado,
       remove‑o deslocando os demais elementos. Como a fila é pequena (máx.5)
       podemos fazer a remoção de forma simples (não circular).                */
    int i = frente;
    int encontrado = -1;
    for (int cont = 0; cont < qtdFila; ++cont) {
        if (filaEspera[i].codigoLivro == codLivro) {
            encontrado = i;
            break;
        }
        i = (i + 1) % MAX_FILA;
    }

    if (encontrado == -1)          /* ninguém na fila para este livro */
        return 0;

    /* Exibe os dados da pessoa que será atendida */
    PessoaFila *p = &filaEspera[encontrado];
    printf("\n*** ATENDIMENTO ***\n");
    printf("Nome: %s\n", p->nomePessoa);
    printf("Telefone: %s\n", p->telefone);
    printf("Livro solicitado (código): %d\n", p->codigoLivro);
    printf("***************\n");

    /* Remover elemento: desloca todos os elementos posteriores uma posição para
       a esquerda, mantendo a circularidade da fila.                              */
    int pos = encontrado;
    while (pos != tras) {
        int prox = (pos + 1) % MAX_FILA;
        filaEspera[pos] = filaEspera[prox];
        pos = prox;
    }
    tras = (tras - 1 + MAX_FILA) % MAX_FILA;
    qtdFila--;

    /* Se a fila ficou vazia, reposiciona índices para estado neutro */
    if (qtdFila == 0) {
        frente = 0;
        tras   = -1;
    }

    return 1;
}

/* -------------------- Fim do programa ------------------------------------------- */
```

