#include <stdio.h>

#define MAX_PROC 10            /* you can raise this if you wish */

struct proc {
    int id;               /* process number (1‑based) */
    int burst;            /* CPU burst time */
    int waiting;          /* waiting time   */
    int turnaround;       /* turnaround time = burst + waiting */
};

/* Simple bubble‑sort that works on an array of struct proc */
static void sort_desc_by_burst(struct proc p[], int n)
{
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (p[j].burst < p[j + 1].burst) {      /* descending */
                struct proc tmp = p[j];
                p[j] = p[j + 1];
                p[j + 1] = tmp;
            }
        }
    }
}

int main(void)
{
    int n;                                  /* number of processes */

    printf("Enter the number of processes (max %d): ", MAX_PROC);
    if (scanf("%d", &n) != 1 || n <= 0 || n > MAX_PROC) {
        fprintf(stderr, "Invalid number of processes.\n");
        return 1;
    }

    struct proc p[MAX_PROC];                /* array of processes */

    /* -----------------------------------------------------------------
       INPUT: burst times
       ----------------------------------------------------------------- */
    printf("Enter the burst time of each process:\n");
    for (int i = 0; i < n; ++i) {
        p[i].id = i + 1;                    /* human‑readable id */
        printf("  Process %d : ", p[i].id);
        if (scanf("%d", &p[i].burst) != 1 || p[i].burst < 0) {
            fprintf(stderr, "Invalid burst time.\n");
            return 1;
        }
        p[i].waiting = 0;                   /* initialise */
        p[i].turnaround = 0;
    }

    /* -----------------------------------------------------------------
       SORT: descending burst time (the original code tried this)
       ----------------------------------------------------------------- */
    sort_desc_by_burst(p, n);

    /* -----------------------------------------------------------------
       CALCULATE waiting time and turnaround time
       ----------------------------------------------------------------- */
    int cumulative = 0;                     /* time elapsed so far */
    int total_wait = 0;                     /* sum of waiting times */

    for (int i = 0; i < n; ++i) {
        p[i].waiting   = cumulative;               /* wait until it gets CPU */
        p[i].turnaround = p[i].waiting + p[i].burst;

        cumulative += p[i].burst;                  /* next process starts here */
        total_wait += p[i].waiting;
    }

    /* -----------------------------------------------------------------
       OUTPUT
       ----------------------------------------------------------------- */
    printf("\n=== FCFS Schedule (descending burst time) ===\n");
    for (int i = 0; i < n; ++i) {
        printf("Process %2d : burst = %3d | waiting = %3d | turnaround = %3d\n",
               p[i].id, p[i].burst, p[i].waiting, p[i].turnaround);
    }

    double avg_wait = (double) total_wait / n;
    printf("\nAverage waiting time : %.2f\n", avg_wait);

    return 0;
}
```

