## 10.  Full, **clean, compilable** code (with all fixes)

```c
/* queue_ll.c : Queue implementation using a singly linked list */

#include <stdio.h>
#include <stdlib.h>

/* ---------- node definition ---------- */
struct node {
    int data;
    struct node *next;
};

/* ---------- global queue pointers ---------- */
static struct node *front = NULL;   /* head of the queue */
static struct node *rear  = NULL;   /* tail of the queue */

/* ---------- enqueue : add at rear ---------- */
void enqueue(int value)
{
    struct node *ptr = (struct node *)malloc(sizeof(struct node));
    if (!ptr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    ptr->data = value;
    ptr->next = NULL;

    if (front == NULL && rear == NULL) {   /* empty queue */
        front = rear = ptr;
    } else {
        rear->next = ptr;
        rear = ptr;
    }
    printf("Node is Inserted\n\n");
}

/* ---------- dequeue : remove from front ---------- */
int dequeue(void)
{
    if (front == NULL) {
        printf("\nUnderflow (queue is empty)\n");
        return -1;                     /* sentinel for error */
    }

    struct node *temp = front;
    int value = temp->data;

    front = front->next;               /* move head forward */
    if (front == NULL) {               /* queue became empty */
        rear = NULL;
    }

    free(temp);
    return value;
}

/* ---------- display : print the queue ---------- */
void display(void)
{
    if (front == NULL) {
        printf("\nQueue is Empty\n");
        return;
    }

    printf("\nThe queue is: ");
    for (struct node *p = front; p != NULL; p = p->next) {
        printf("%d --> ", p->data);
    }
    printf("NULL\n\n");
}

/* ---------- main : menu driver ---------- */
int main(void)
{
    int choice = 0, value;

    printf("\nImplementation of Queue using Linked List\n");

    while (choice != 4) {
        printf("\n1. Enqueue\n2. Dequeue\n3. Display\n4. Exit\n");
        printf("Enter your choice: ");
        if (scanf("%d", &choice) != 1) {
            /* bad input, clear stdin */
            int c;
            while ((c = getchar()) != '\n' && c != EOF);
            printf("Invalid input. Please enter a number 1‑4.\n");
            continue;
        }

        switch (choice) {
            case 1:
                printf("Enter the value to be inserted: ");
                scanf("%d", &value);
                enqueue(value);
                break;

            case 2:
                value = dequeue();
                if (value != -1) {
                    printf("Deleted value = %d\n", value);
                }
                break;

            case 3:
                display();
                break;

            case 4:
                printf("Exiting program.\n");
                break;

            default:
                printf("Invalid choice! Please try again.\n");
        }
    }

    /* free any nodes left in the queue */
    while (front != NULL) {
        dequeue();   /* reuse dequeue to free memory */
    }

    return 0;
}
```

Compile with:

```bash
gcc -Wall -Wextra -std=c11 -o queue_ll queue_ll.c
```

Run and you’ll see a simple interactive menu where you can `enqueue` numbers, `dequeue` them, and `display` the current contents.

