## 完整、正确且安全的实现

下面给出 **完整、可直接提交的** C 语言实现，兼顾了 **可读性**、**性能** 与 **安全**。

```c
/*  LeetCode 300. Longest Increasing Subsequence
 *  时间复杂度：O(n^2)   (n = numsSize)
 *  空间复杂度：O(n)
 */

#include <stddef.h>   // for NULL
#include <stdlib.h>   // for malloc / free
#include <limits.h>   // for INT_MIN (optional)

/* 取 max 的宏，避免使用 fmax（double） */
#ifndef MAX
#define MAX(a,b) ((a) > (b) ? (a) : (b))
#endif

int lengthOfLIS(int* nums, int numsSize) {
    /* 1. 边界情况 */
    if (numsSize == 0) return 0;          // 空数组
    if (numsSize == 1) return 1;          // 单元素数组

    /* 2. 动态分配 dp */
    int *dp = (int *)malloc(numsSize * sizeof(int));
    if (dp == NULL) return 0;             // 内存分配失败（极端情况）

    /* 3. 初始化 */
    for (int i = 0; i < numsSize; ++i) {
        dp[i] = 1;                        // 每个元素本身至少构成长度为 1 的子序列
    }

    int result = 1;                       // 至少有一个元素时，最长长度不小于 1

    /* 4. DP 主循环 */
    for (int i = 1; i < numsSize; ++i) {
        for (int j = 0; j < i; ++j) {
            if (nums[i] > nums[j]) {
                dp[i] = MAX(dp[i], dp[j] + 1);
            }
        }
        result = MAX(result, dp[i]);      // 实时维护全局最大值
    }

    /* 5. 清理并返回 */
    free(dp);
    return result;
}
```

