 *      rabbit = (leg - 2*head) / 2
 *      chicken = head - rabbit
 *
 *  为了让调用者能够直接得到结果，使用指针参数把计算结果写回。
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>

/*--------------------------------------------------------------
 *  函数原型
 *      参数：
 *          head   - 总头数（正整数）
 *          leg    - 总腿数（正整数）
 *          pChicken - 指向保存鸡数量的 int 变量的指针
 *          pRabbit  - 指向保存兔数量的 int 变量的指针
 *      返回值：
 *          0   - 成功求解，*pChicken、*pRabbit 已被写入
 *         -1   - 输入非法（head、leg 为负数或为 0）
 *         -2   - 无整数解（比如腿数与头数不匹配，或得到负数动物数）
 *--------------------------------------------------------------*/
int solveChickenRabbit(int head, int leg, int *pChicken, int *pRabbit)
{
    /* 1. 基本合法性检查 */
    if (head <= 0 || leg <= 0)   /* 头数或腿数必须为正 */
        return -1;

    /* 2. 根据推导公式直接求解 */
    /*    rabbit = (leg - 2*head) / 2   必须保证分子为偶数且 >=0 */
    int numerator = leg - 2 * head;          /* 计算分子 */
    if (numerator < 0 || numerator % 2 != 0) /* 负数或不是偶数 => 没有整数解 */
        return -2;

    int rabbit = numerator / 2;              /* 兔子数 */
    int chicken = head - rabbit;             /* 鸡的数目 */

    /* 3. 再次检查得到的数量是否为非负整数 */
    if (rabbit < 0 || chicken < 0)
        return -2;

    /* 4. 把结果写回调用者提供的地址 */
    if (pChicken) *pChicken = chicken;
    if (pRabbit)  *pRabbit  = rabbit;

    return 0;    /* 成功 */
}

/*--------------------------------------------------------------
 *  示例：主函数演示如何使用 solveChickenRabbit
 *--------------------------------------------------------------*/
int main(void)
{
    int head, leg;
    printf("请输入总头数和总腿数（用空格分开）：");
    if (scanf("%d %d", &head, &leg) != 2) {
        fprintf(stderr, "输入格式错误！\n");
        return EXIT_FAILURE;
    }

    int chicken = 0, rabbit = 0;
    int rc = solveChickenRabbit(head, leg, &chicken, &rabbit);

    if (rc == 0) {
        printf("解：鸡 %d 只，兔 %d 只。\n", chicken, rabbit);
    } else if (rc == -1) {
        printf("错误：头数和腿数必须为正整数。\n");
    } else if (rc == -2) {
        printf("无解：给定的头数和腿数不匹配，或者得到负数动物数。\n");
    } else {
        printf("未知错误。\n");
    }

    return EXIT_SUCCESS;
}
```

### 代码要点说明

| 步骤 | 说明 |
|------|------|
| **指针参数** | `int *pChicken, int *pRabbit` 用来把计算得到的结果返回给调用者，符合“利用指针做参数”的要求。 |
| **合法性检查** | - 头数、腿数必须为正<br>- `(leg - 2*head)` 必须是非负的偶数，才能得到整数的兔子数量 |
| **求解公式** | `rabbit = (leg - 2*head)/2`，`chicken = head - rabbit`，直接来源于线性方程组的求解。 |
| **错误码** | 返回 `0` 表示成功，`-1` 为输入非法，`-2` 为无整数解（包括负数动物数、奇数分子等）。这样调用者可以根据返回值作进一步处理。 |
| **主函数示例** | 读取用户输入、调用函数、根据返回值打印相应信息，演示了完整的使用流程。 |

