 *  board_id.c  –  генерация уникального идентификатора платы
 *  Компиляция:   gcc -Wall -O2 board_id.c -o board_id -lcrypto
 *  Требуется:   OpenSSL (для SHA256). Если OpenSSL нежелателен,
 *               замените SHA256 на собственную реализацию.
 * -------------------------------------------------------------- */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <openssl/sha.h>   // libcrypto

#define UUID_STR_LEN 36  // 8-4-4-4-12 + '\0'

/* Чтение строки из файла, обрезка пробелов и \n */
static int read_one_line(const char *path, char *buf, size_t buflen)
{
    FILE *f = fopen(path, "r");
    if (!f) return -1;
    if (!fgets(buf, (int)buflen, f)) {
        fclose(f);
        return -1;
    }
    fclose(f);
    /* Убираем \n и пробелы */
    size_t len = strlen(buf);
    while (len && (buf[len-1] == '\n' || buf[len-1] == '\r' || buf[len-1] == ' '))
        buf[--len] = '\0';
    return 0;
}

/* Получаем Serial из /proc/cpuinfo */
static int get_cpu_serial(char *out, size_t outlen)
{
    FILE *f = fopen("/proc/cpuinfo", "r");
    if (!f) return -1;
    char line[256];
    while (fgets(line, sizeof(line), f)) {
        if (strncmp(line, "Serial", 6) == 0) {
            char *p = strchr(line, ':');
            if (!p) continue;
            ++p; while (*p == ' ' || *p == '\t') ++p;
            strncpy(out, p, outlen-1);
            out[outlen-1] = '\0';
            /* Убираем любые завершающие пробелы/переводы строк */
            size_t len = strlen(out);
            while (len && (out[len-1] == '\n' || out[len-1] == '\r' || out[len-1] == ' '))
                out[--len] = '\0';
            fclose(f);
            return 0;
        }
    }
    fclose(f);
    return -1;   // не найдено
}

/* Получаем MAC‑адрес первого сетевого iface (eth0, wlan0, …) */
static int get_first_mac(char *out, size_t outlen)
{
    FILE *f = popen("ip -o link | awk -F' ' '/ether/ {print $17; exit}'", "r");
    if (!f) return -1;
    if (!fgets(out, (int)outlen, f)) {
        pclose(f);
        return -1;
    }
    pclose(f);
    /* Убираем \n */
    size_t len = strlen(out);
    if (len && out[len-1] == '\n') out[--len] = '\0';
    return (len > 0) ? 0 : -1;
}

/* Формируем SHA‑256 из входных данных, выводим как UUID */
static void sha256_to_uuid(const unsigned char *hash, char *uuid_str)
{
    /* UUID‑style: 8-4-4-4-12 */
    snprintf(uuid_str, UUID_STR_LEN + 1,
             "%02x%02x%02x%02x-%02x%02x-%02x%02x-%02x%02x-%02x%02x%02x%02x%02x%02x",
             hash[0], hash[1], hash[2], hash[3],
             hash[4], hash[5],
             hash[6], hash[7],
             hash[8], hash[9],
             hash[10], hash[11], hash[12], hash[13], hash[14], hash[15]);
}

int main(void)
{
    char serial[64] = "";
    char mac[32]    = "";
    char combined[128];
    unsigned char hash[SHA256_DIGEST_LENGTH];
    char uuid[UUID_STR_LEN + 1];

    if (get_cpu_serial(serial, sizeof(serial)) == 0) {
        /* Сериал найден – используем его */
        snprintf(combined, sizeof(combined), "%s", serial);
    } else if (get_first_mac(mac, sizeof(mac)) == 0) {
        /* Нет Serial, но есть MAC */
        snprintf(combined, sizeof(combined), "%s", mac);
    } else {
        /* Оба способа провалились – берём рандомные 16 байт */
        FILE *rnd = fopen("/dev/urandom", "rb");
        if (!rnd) {
            perror("open /dev/urandom");
            return 1;
        }
        unsigned char buf[16];
        fread(buf, 1, sizeof(buf), rnd);
        fclose(rnd);
        /* Преобразуем в шестнадцатеричную строку */
        for (int i = 0; i < 16; ++i)
            sprintf(combined + i*2, "%02x", buf[i]);
        combined[32] = '\0';
    }

    /* Подсчитаем SHA‑256 */
    SHA256((unsigned char*)combined, strlen(combined), hash);
    sha256_to_uuid(hash, uuid);

    printf("%s\n", uuid);
    return 0;
}
```

