```c
/* --------------------------------------------------------------- */
/* remove surrounding quotes from a string that is guaranteed to   */
/* start and end with '"'                                            */
static char *strip_quotes(const char *s)
{
    size_t len = strlen(s);
    if (len < 2 || s[0] != '"' || s[len-1] != '"')
        return NULL;
    char *out = malloc(len-1);                /* without the two quotes */
    if (!out) return NULL;
    memcpy(out, s+1, len-2);
    out[len-2] = '\0';
    return out;
}

/* --------------------------------------------------------------- */
/* read a whole line (including the trailing '\n') from a FILE*    */
/* the returned buffer must be freed by the caller                  */
static char *read_line(FILE *fp)
{
    char *line = NULL;
    size_t sz = 0;
    ssize_t n = getline(&line, &sz, fp);
    if (n == -1) {
        free(line);
        return NULL;
    }
    /* erase possible trailing '\n' */
    if (line[n-1] == '\n')
        line[n-1] = '\0';
    return line;
}

/* --------------------------------------------------------------- */
/* parse a line of the form  "key":"value"   (whitespaces allowed)  */
static int parse_key_value(const char *line, char **key, char **value)
{
    const char *p = line;
    while (*p && isspace((unsigned char)*p)) ++p;      /* skip leading ws */

    if (*p != '"') return -1;
    const char *k1 = p;
    const char *k2 = strchr(k1+1, '"');
    if (!k2) return -1;

    p = k2+1;
    while (*p && isspace((unsigned char)*p)) ++p;
    if (*p != ':') return -1;
    ++p;
    while (*p && isspace((unsigned char)*p)) ++p;
    if (*p != '"') return -1;
    const char *v1 = p;
    const char *v2 = strchr(v1+1, '"');
    if (!v2) return -1;

    /* allocate result strings */
    *key   = strndup(k1, k2-k1+1);    /* includes the surrounding quotes   */
    *value = strndup(v1, v2-v1+1);
    if (!*key || !*value) {
        free(*key); free(*value);
        return -1;
    }
    return 0;
}

/* --------------------------------------------------------------- */
/* Load all words from a .db file into the struct base   */
static int load_words(struct base *b)
{
    FILE *fp = fopen(b->pathtobase, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open database file \"%s\": %s\n",
                b->pathtobase, strerror(errno));
        return -1;
    }

    size_t capacity = 0;
    b->words = NULL;
    b->nwords = 0;

    char *line = NULL;
    size_t sz = 0;
    while (getline(&line, &sz, fp) != -1) {
        /* remove trailing newline */
        size_t ln = strlen(line);
        if (ln && line[ln-1] == '\n') line[ln-1] = '\0';
        /* skip empty lines */
        if (line[0] == '\0') continue;

        if (b->nwords == capacity) {
            size_t ncap = capacity ? capacity*2 : 16;
            char **tmp = realloc(b->words, ncap * sizeof *tmp);
            if (!tmp) {
                perror("realloc");
                free(line);
                fclose(fp);
                return -1;
            }
            b->words = tmp;
            capacity = ncap;
        }
        b->words[b->nwords++] = strdup(line);
        if (!b->words[b->nwords-1]) {
            perror("strdup");
            free(line);
            fclose(fp);
            return -1;
        }
    }
    free(line);
    fclose(fp);
    return 0;
}

/* --------------------------------------------------------------- */
/* return a random word from the given base (words must be loaded) */
static const char *random_word(struct base *b)
{
    if (b->nwords == 0) return "";
    size_t idx = (size_t) ( (double)rand() / RAND_MAX * b->nwords );
    if (idx == b->nwords) idx = b->nwords-1;   /* safety */
    return b->words[idx];
}

/* --------------------------------------------------------------- */
/* Find a struct base with a given name (basename without the % … %) */
static struct base *find_base(struct base *arr, size_t n,
                              const char *name)
{
    for (size_t i = 0; i < n; ++i)
        if (strcmp(arr[i].basename, name) == 0)
            return &arr[i];
    return NULL;
}
