int main(void)
{
    char src_name[256];
    char dst_name[256];

    printf("Enter name of source file: ");
    if (!fgets(src_name, sizeof src_name, stdin)) return 1;
    src_name[strcspn(src_name, "\n")] = '\0';

    printf("Enter name of destination file: ");
    if (!fgets(dst_name, sizeof dst_name, stdin)) return 1;
    dst_name[strcspn(dst_name, "\n")] = '\0';

    /* ---------- 1. read src.ini --------------------------------- */
    FILE *src = fopen(src_name, "r");
    if (!src) {
        perror("fopen source");
        return 1;
    }

    char *text_file = NULL;
    char *data_file = NULL;
    char *line;
    while ( (line = read_line(src)) ) {
        char *key = NULL, *value = NULL;
        if (parse_key_value(line, &key, &value) == 0) {
            char *k = strip_quotes(key);
            char *v = strip_quotes(value);
            if (k && v) {
                if (strcmp(k, "text") == 0) {
                    free(text_file);
                    text_file = v;               /* keep the stripped value */
                } else if (strcmp(k, "data") == 0) {
                    free(data_file);
                    data_file = v;
                } else {
                    free(v);                     /* unknown key – ignore */
                }
                free(k);
            }
            free(key);
            free(value);
        }
        free(line);
    }
    fclose(src);

    if (!text_file || !data_file) {
        fprintf(stderr, "Source file must contain \"text\" and \"data\" keys.\n");
        return 1;
    }

    /* ---------- 2. read file2 (the data file) -------------------- */
    FILE *data = fopen(data_file, "r");
    if (!data) {
        perror("fopen data file");
        return 1;
    }

    struct base *bases = NULL;
    size_t nbases = 0, cap = 0;

    while ( (line = read_line(data)) ) {
        char *key = NULL, *value = NULL;
        if (parse_key_value(line, &key, &value) == 0) {
            char *bk = strip_quotes(key);       /* "base-a" -> base-a   */
            char *pv = strip_quotes(value);     /* "./a.db"   -> ./a.db */
            if (bk && pv) {
                if (nbases == cap) {
                    size_t ncap = cap ? cap*2 : 8;
                    struct base *tmp = realloc(bases, ncap * sizeof *tmp);
                    if (!tmp) {
                        perror("realloc bases");
                        exit(1);
                    }
                    bases = tmp;
                    cap = ncap;
                }
                bases[nbases].basename   = bk;
                bases[nbases].pathtobase = pv;
                bases[nbases].words      = NULL;
                bases[nbases].nwords     = 0;
                ++nbases;
            } else {
                free(bk); free(pv);
            }
            free(key);
            free(value);
        }
        free(line);
    }
    fclose(data);

    if (nbases == 0) {
        fprintf(stderr, "No base definitions found in \"%s\".\n", data_file);
        return 1;
    }

    /* ---------- 3. read the text file (file1) ------------------- */
    FILE *txt = fopen(text_file, "r");
    if (!txt) {
        perror("fopen text file");
        return 1;
    }

    char *out_line = NULL;
    size_t out_sz = 0;
    char *tmp = NULL;
    size_t tmp_sz = 0;
    int first_out_line = 1;       /* we will write a newline after the
                                    * first processed line */
    while ( (line = read_line(txt)) ) {
        /* tokenise the line – placeholders are separated by any white‑space */
        char *saveptr = NULL;
        char *tok = strtok_r(line, " \t\r\n", &saveptr);
        while (tok) {
            size_t tlen = strlen(tok);
            if (tlen >= 2 && tok[0] == '%' && tok[tlen-1] == '%') {
                /* %basename% -> strip the % signs */
                char name[256];
                snprintf(name, sizeof name, "%.*s", (int)(tlen-2), tok+1);
                struct base *b = find_base(bases, nbases, name);
                if (!b) {
                    fprintf(stderr,
                        "Warning: unknown base \"%s\" – kept as is.\n", name);
                    /* write the original token */
                    if (asprintf(&tmp, "%s%s", (first_out_line? "" : " "), tok) < 0) {
                        perror("asprintf");
                        exit(1);
                    }
                } else {
                    /* load words from the .db if not already done */
                    if (!b->words) {
                        if (load_words(b) != 0) {
                            fprintf(stderr,
                                    "Failed to load words for base \"%s\".\n",
                                    b->basename);
                            exit(1);
                        }
                    }
                    const char *rw = random_word(b);
                    if (asprintf(&tmp, "%s%s", (first_out_line? "" : " "), rw) < 0) {
                        perror("asprintf");
                        exit(1);
                    }
                }
                /* append tmp to out_line */
                size_t need = out_sz + strlen(tmp) + 1;
                out_line = realloc(out_line, need);
                if (!out_line) {
                    perror("realloc out_line");
                    exit(1);
                }
                if (out_sz == 0)                /* first token */
                    strcpy(out_line, tmp);
                else
                    strcat(out_line, tmp);
                out_sz += strlen(tmp);
                free(tmp);
                first_out_line = 0;
            } else {
                /* ordinary token – copy unchanged */
                if (asprintf(&tmp, "%s%s", (first_out_line? "" : " "), tok) < 0) {
                    perror("asprintf");
                    exit(1);
                }
                size_t need = out_sz + strlen(tmp) + 1;
                out_line = realloc(out_line, need);
                if (!out_line) {
                    perror("realloc out_line");
                    exit(1);
                }
                if (out_sz == 0)
                    strcpy(out_line, tmp);
                else
                    strcat(out_line, tmp);
                out_sz += strlen(tmp);
                free(tmp);
                first_out_line = 0;
            }
            tok = strtok_r(NULL, " \t\r\n", &saveptr);
        }
        free(line);
    }
    fclose(txt);

    /* ---------- 4. write result to destination file ---------------- */
    FILE *dst = fopen(dst_name, "w");
    if (!dst) {
        perror("fopen destination");
        return 1;
    }
    if (out_line) {
        fprintf(dst, "%s\n", out_line);
        free(out_line);
    }
    fclose(dst);

    /* ---------- 5. free all allocated memory ---------------------- */
    for (size_t i = 0; i < nbases; ++i) {
        free(bases[i].basename);
        free(bases[i].pathtobase);
        for (size_t j = 0; j < bases[i].nwords; ++j)
            free(bases[i].words[j]);
        free(bases[i].words);
    }
    free(bases);
    free(text_file);
    free(data_file);

    printf("Result written to \"%s\".\n", dst_name);
    return 0;
}
