/*********************************************************************
 *  Kruskal‑MST  –  读取邻接矩阵，按照 Kruskal 算法输出最小生成树 *
 *  说明
 *      • 输入：  n e          (顶点数, 边数——e 在这里仅作占位)
 *                n 行 n 列的邻接矩阵，32767 表示 “无边”，对角线上的 0
 *                被视为不存在的边。
 *      • 输出：  第一行输出  "Kruskal:"
 *                随后每行输出  (i,j):w   表示 MST 中的一条边及其权值.
 *                边按权值从小到大输出，i、j 为顶点下标（0‑based）。
 *
 *  与原题中提供的代码相比，主要改动有：
 *      1. 正确地把所有边收集到一个数组中，而不是用“visited”贪心。
 *      2. 用 qsort 对边按权值升序排序。
 *      3. 使用并查集 (Union‑Find) 判断两端点是否已经在同一连通分量，
 *         从而避免环，真正实现 Kruskal。
 *      4. 代码中加入必要的错误检查和注释，便于阅读和调试。
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 32767          /* 题目约定的“无穷大” */

/* --------------------------- 图的定义 --------------------------- */
typedef struct {
    int n;          /* 顶点数 */
    int **w;        /* 邻接矩阵，w[i][j] 为权值（无边则为 INF） */
} MGraph;

/* --------------------------- 边的定义 --------------------------- */
typedef struct {
    int u, v;       /* 边的两个端点 */
    int w;          /* 权值 */
} Edge;

/* --------------------------- 并查集 --------------------------- */
static int *parent;   /* parent[i] = i 的根节点 */
static int *rankv;    /* 用于按秩合并 */

int find_set(int x)               /* 路径压缩 */
{
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

void union_set(int x, int y)      /* 按秩合并 */
{
    int fx = find_set(x);
    int fy = find_set(y);
    if (fx == fy) return;

    if (rankv[fx] < rankv[fy])
        parent[fx] = fy;
    else if (rankv[fx] > rankv[fy])
        parent[fy] = fx;
    else {
        parent[fy] = fx;
        rankv[fx]++;               /* 同等秩时提升秩 */
    }
}

/* --------------------------- 边比较函数 --------------------------- */
int cmp_edge(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    return ea->w - eb->w;          /* 升序 */
}

/* --------------------------- Kruskal 实现 --------------------------- */
void Kruskal(MGraph g)
{
    int i, j, m = 0;               /* m 为实际收集到的边数 */
    Edge *edges = NULL;            /* 动态数组，保存所有可用边 */

    /* 1️⃣ 收集所有（无向）边：只取 i < j，避免重复 */
    for (i = 0; i < g.n; ++i) {
        for (j = i + 1; j < g.n; ++j) {
            int w = g.w[i][j];
            if (w != INF && w != 0) {      /* 0 只出现在对角线 */
                edges = realloc(edges, (m + 1) * sizeof(Edge));
                edges[m].u = i;
                edges[m].v = j;
                edges[m].w = w;
                ++m;
            }
        }
    }

    /* 2️⃣ 按权值排序 */
    qsort(edges, m, sizeof(Edge), cmp_edge);

    /* 3️⃣ 初始化并查集 */
    parent = (int *)malloc(g.n * sizeof(int));
    rankv  = (int *)malloc(g.n * sizeof(int));
    for (i = 0; i < g.n; ++i) {
        parent[i] = i;
        rankv[i]  = 0;
    }

    /* 4️⃣ 主循环：从最小边开始尝试加入生成树 */
    int taken = 0;                     /* 已经加入 MST 的边数 */
    for (i = 0; i < m && taken < g.n - 1; ++i) {
        int u = edges[i].u, v = edges[i].v;
        if (find_set(u) != find_set(v)) {   /* 两端不在同一集合 → 加入 */
            printf("(%d,%d):%d\n", u, v, edges[i].w);
            union_set(u, v);
            ++taken;
        }
    }

    /* 释放资源 */
    free(edges);
    free(parent);
    free(rankv);
}

/* --------------------------- 主函数 --------------------------- */
int main(void)
{
    int n, e;
    if (scanf("%d %d", &n, &e) != 2) return 0;   /* 读取 n、e */

    /* 为图分配空间 */
    MGraph g;
    g.n = n;
    g.w = (int **)malloc(n * sizeof(int *));
    for (i = 0; i < n; ++i)
        g.w[i] = (int *)malloc(n * sizeof(int));

    /* 读取邻接矩阵 */
    for (i = 0; i < n; ++i) {
        for (j = 0; j < n; ++j) {
            scanf("%d", &g.w[i][j]);
            if (g.w[i][j] == 0)            /* 对角线 0 视作“无边” */
                g.w[i][j] = INF;
        }
    }

    printf("Kruskal:\n");
    Kruskal(g);

    /* 释放图的内存 */
    for (i = 0; i < n; ++i)
        free(g.w[i]);
    free(g.w);
    return 0;
}
```

