```c
/*  factorial.c
 *  Tính n! = 1 * 2 * ... * n
 *  (có thể tính tới 20! với kiểu unsigned long long)
 *  --------------------------------------------------
 *  Người biên dịch: gcc -std=c11 -Wall -Wextra factorial.c -o factorial
 */

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    unsigned int n;               // n ≤ 20 để tránh overflow
    unsigned long long fact = 1;  // kết quả

    printf("Nhap n (0 <= n <= 20): ");
    if (scanf("%u", &n) != 1) {
        fprintf(stderr, "Loi: khong doc duoc gia tri n.\n");
        return EXIT_FAILURE;
