        fprintf(stderr,
                "Loi: gia tri n qua lon, vung duoc tinh su dung unsigned long long chi den 20!\n");
        return EXIT_FAILURE;
    }

    for (unsigned int i = 2; i <= n; ++i) {
        fact *= i;
    }

    printf("%u! = %llu\n", n, fact);
    return EXIT_SUCCESS;
}
