{
    unsigned int n;
    mpz_t fact;               // kiểu số nguyên lớn của GMP
    mpz_init_set_ui(fact, 1); // fact = 1

    printf("Nhap n (>=0): ");
    scanf("%u", &n);

    for (unsigned int i = 2; i <= n; ++i)
        mpz_mul_ui(fact, fact, i);   // fact = fact * i

    gmp_printf("%u! = %Zd\n", n, fact);
    mpz_clear(fact);
    return 0;
}
```

