Below is a **stand‑alone, self‑contained kernel module** that you can compile against a Linux‑4.19 tree and use to **exercise the DMA‑Engine framework** (the “DMA‑engine memcpy” test).  
It does **not depend on any specific hardware** – it asks the DMA‑engine core for a “memcpy‑capable” channel (most SoCs expose one for internal memory‑to‑memory copies) and then copies a small buffer from src → dst using that channel.  

The code is deliberately kept short, well‑commented and ready for copy‑&‑paste.  After the source you’ll also find a small `Makefile`, the exact steps to build / load the module, and a checklist of kernel configuration options that must be enabled for the test to succeed.

---

## 1. What the test does (high‑level)

| Step | What happens | Why it matters |
|------|--------------|----------------|
| 1. Allocate two *coherent* DMA buffers (`src_buf` and `dst_buf`) | Guarantees the CPU and the DMA engine see the same physical memory without cache‑coherency headaches | Simplifies mapping; we can write/read directly from the buffers |
| 2. Fill `src_buf` with a known pattern (`0xA5`) | Gives us data to verify after the copy | Helps us know if the DMA actually transferred |
| 3. Request a DMA‑engine channel that can perform *memcpy* (`DMA_MEMCPY`) | The core picks the best available hardware engine (e.g., PL330, DWC‑DMA, etc.) | Works on any platform that has a generic memcpy engine |
| 4. Build a **descriptor** describing the copy (src, dst, length) | Descriptor is the DMA‑engine’s “command list” | The hardware will read this and start the transfer |
| 5. Submit the descriptor, start the transaction, and **wait for completion** (via a completion callback) | The driver gets notified when the hardware finishes | Guarantees that we check the data only after the DMA is really done |
| 6. Verify the destination buffer matches the source pattern and print a success/failure message | Provides visible confirmation in `dmesg` | The only user‑visible output of the test |
| 7. Clean up – free buffers, release channel | Avoids memory leaks / dangling references | Good kernel‑module hygiene |

If any step fails, the module prints a clear error message and aborts cleanly.

---

## 2. Full source code – `dma_test.c`

```c
/* SPDX-License-Identifier: GPL-2.0 */
/*
 * dma_test.c – Simple DMA‑engine memcpy test for Linux 4.19
 *
 * This module allocates two coherent DMA buffers, fills the source
 * with a pattern, requests a DMA‑engine memcpy channel, copies the
 * data, and validates the result.
 *
 * It is intentionally minimal and does not require a real peripheral.
 *
 * Build:
 *   make -C /lib/modules/$(uname -r)/build M=$(pwd) modules
 *
 * Load:
 *   sudo insmod dma_test.ko
 *   dmesg | tail -n 20
 *
 * Unload:
 *   sudo rmmod dma_test
 *
 * Author:  ChatGPT <chatgpt@example.com>
 * License: GPL v2
 */

#include <linux/module.h>
#include <linux/init.h>
#include <linux/dmaengine.h>
#include <linux/dma-mapping.h>
#include <linux/completion.h>
#include <linux/slab.h>
#include <linux/of_dma.h>
#include <linux/platform_device.h>
#include <linux/err.h>
#include <linux/kernel.h>

#define TEST_BUF_SIZE   (64 * 1024)   /* 64 KiB – small but enough to see DMA activity */
#define TEST_PATTERN    0xA5          /* Fill pattern for source buffer */

/* Completion used for the async callback */
static DECLARE_COMPLETION(dma_test_done);

/* -------------------------------------------------------------------- */
/* Async callback – called from DMA completion interrupt context */
static void dma_test_callback(void *completion)
{
	complete(completion);
}

/* -------------------------------------------------------------------- */
/* The core test routine – called from module_init() */
static int __init dma_test_init(void)
{
	struct dma_chan *chan = NULL;
	struct dma_device *dma_dev;
	dma_cap_mask_t mask;
	struct dma_async_tx_descriptor *tx = NULL;
	enum dma_ctrl_flags flags = DMA_CTRL_ACK | DMA_PREP_INTERRUPT;
	struct completion *cmp = &dma_test_done;
	dma_addr_t src_dma, dst_dma;
	void *src_buf = NULL;
	void *dst_buf = NULL;
	int ret = 0;
	int i;
	u8 *src_ptr, *dst_ptr;

	pr_info("%s: starting DMA‑engine memcpy test (bufsize=%u)\n",
		KBUILD_MODNAME, TEST_BUF_SIZE);

	/* --------------------------------------------------------------
	 * 1) Allocate two coherent DMA buffers (CPU visible + DMA address)
	 * -------------------------------------------------------------- */
	src_buf = dma_alloc_coherent(NULL, TEST_BUF_SIZE, &src_dma, GFP_KERNEL);
	if (!src_buf) {
		pr_err("%s: failed to allocate source DMA buffer\n", KBUILD_MODNAME);
		ret = -ENOMEM;
		goto out;
	}
	dst_buf = dma_alloc_coherent(NULL, TEST_BUF_SIZE, &dst_dma, GFP_KERNEL);
	if (!dst_buf) {
		pr_err("%s: failed to allocate destination DMA buffer\n", KBUILD_MODNAME);
		ret = -ENOMEM;
		goto free_src;
	}

	/* Fill source with a known pattern and zero destination */
	src_ptr = src_buf;
	dst_ptr = dst_buf;
	for (i = 0; i < TEST_BUF_SIZE; i++) {
		src_ptr[i] = TEST_PATTERN;
		dst_ptr[i] = 0;
	}

	/* --------------------------------------------------------------
	 * 2) Request a DMA‑engine channel that can do memcpy
	 * -------------------------------------------------------------- */
	dma_cap_zero(mask);
	dma_cap_set(DMA_MEMCPY, mask);

	chan = dma_request_chan_by_mask(&mask);
	if (IS_ERR(chan)) {
		pr_err("%s: no DMA memcpy channel available (error %ld)\n",
		       KBUILD_MODNAME, PTR_ERR(chan));
		ret = PTR_ERR(chan);
		chan = NULL;
		goto free_dst;
	}
	dma_dev = chan->device;
	pr_info("%s: obtained DMA channel \"%s\"\n", KBUILD_MODNAME,
		dma_chan_name(chan));

	/* --------------------------------------------------------------
	 * 3) Build a memcpy descriptor
	 * -------------------------------------------------------------- */
	tx = dma_dev->device_prep_dma_memcpy(chan, dst_dma, src_dma,
					     TEST_BUF_SIZE, flags);
	if (!tx) {
		pr_err("%s: failed to prepare memcpy descriptor\n", KBUILD_MODNAME);
		ret = -EIO;
		goto release_chan;
	}
	/* Set our callback that will fire when the copy is done */
	tx->callback = dma_test_callback;
	tx->callback_param = cmp;

	/* --------------------------------------------------------------
	 * 4) Submit, start and wait for completion
	 * -------------------------------------------------------------- */
	if (dma_submit_error(dmaengine_submit(tx))) {
		pr_err("%s: dmaengine_submit() failed\n", KBUILD_MODNAME);
		ret = -EIO;
		goto release_chan;
	}
	dma_async_issue_pending(chan);

	/* Wait up to 5 seconds – should be instantaneous for 64 KiB */
	if (!wait_for_completion_timeout(cmp, msecs_to_jiffies(5000))) {
		pr_err("%s: DMA transfer timed out\n", KBUILD_MODNAME);
		ret = -ETIMEDOUT;
		goto release_chan;
	}

	/* --------------------------------------------------------------
	 * 5) Verify the copy
	 * -------------------------------------------------------------- */
	for (i = 0; i < TEST_BUF_SIZE; i++) {
		if (src_ptr[i] != dst_ptr[i]) {
			pr_err("%s: data mismatch at offset %d (src=%02x dst=%02x)\n",
			       KBUILD_MODNAME, i, src_ptr[i], dst_ptr[i]);
			ret = -EIO;
			goto release_chan;
		}
	}
	pr_info("%s: DMA memcpy succeeded – %u bytes transferred correctly\n",
		KBUILD_MODNAME, TEST_BUF_SIZE);

	/* --------------------------------------------------------------
	 * 6) Normal exit path
	 * -------------------------------------------------------------- */
release_chan:
	if (chan)
		dma_release_channel(chan);
free_dst:
	if (dst_buf)
		dma_free_coherent(NULL, TEST_BUF_SIZE, dst_buf, dst_dma);
free_src:
	if (src_buf)
		dma_free_coherent(NULL, TEST_BUF_SIZE, src_buf, src_dma);
out:
	return ret;
}

/* -------------------------------------------------------------------- */
static void __exit dma_test_exit(void)
{
	pr_info("%s: module unloaded – cleanup already done\n", KBUILD_MODNAME);
}

/* -------------------------------------------------------------------- */
module_init(dma_test_init);
module_exit(dma_test_exit);

MODULE_AUTHOR("ChatGPT <chatgpt@example.com>");
MODULE_DESCRIPTION("Simple DMA‑engine memcpy test for Linux 4.19");
MODULE_LICENSE("GPL v2");
```

