static const unsigned char b64_reverse[256] = {
    [0 ... 255] = 0xFF,   /* 0xFF means “invalid” */
    ['A'] = 0,  ['B'] = 1,  ['C'] = 2,  ['D'] = 3,
    ['E'] = 4,  ['F'] = 5,  ['G'] = 6,  ['H'] = 7,
