    ['U'] =20,  ['V'] =21,  ['W'] =22,  ['X'] =23,
    ['Y'] =24,  ['Z'] =25,
    ['a'] =26,  ['b'] =27,  ['c'] =28,  ['d'] =29,
    ['e'] =30,  ['f'] =31,  ['g'] =32,  ['h'] =33,
    ['i'] =34,  ['j'] =35,  ['k'] =36,  ['l'] =37,
    ['m'] =38,  ['n'] =39,  ['o'] =40,  ['p'] =41,
    ['q'] =42,  ['r'] =43,  ['s'] =44,  ['t'] =45,
    ['u'] =46,  ['v'] =47,  ['w'] =48,  ['x'] =49,
    ['y'] =50,  ['z'] =51,
    ['0'] =52,  ['1'] =53,  ['2'] =54,  ['3'] =55,
    ['4'] =56,  ['5'] =57,  ['6'] =58,  ['7'] =59,
    ['8'] =60,  ['9'] =61,
    ['+'] =62,  ['/'] =63,
};

static inline size_t b64_encode(const unsigned char *in, size_t inlen,
                                char *out, size_t outsize)
{
    size_t o = 0;
    size_t i;
    for (i = 0; i < inlen; i += 3) {
        unsigned int octet_a = i < inlen ? in[i] : 0;
        unsigned int octet_b = i+1 < inlen ? in[i+1] : 0;
        unsigned int octet_c = i+2 < inlen ? in[i+2] : 0;
        unsigned int triple = (octet_a << 0x10) + (octet_b << 0x08) + octet_c;

        if (o+4 > outsize) return 0;   /* not enough space */
        out[o++] = b64_table[(triple >> 3*6) & 0x3F];
        out[o++] = b64_table[(triple >> 2*6) & 0x3F];
        out[o++] = b64_table[(triple >> 1*6) & 0x3F];
        out[o++] = b64_table[(triple >> 0*6) & 0x3F];
    }
    /* pad */
    switch (inlen % 3) {
        case 1: out[o-2] = '='; out[o-1] = '=';
                break;
        case 2: out[o-1] = '=';
                break;
    }
    return o;
}

static inline size_t b64_decode(const char *in, size_t inlen,
                                unsigned char *out, size_t outsize)
{
    if (inlen % 4) return 0;           /* must be multiple of 4 */
    size_t o = 0;
    size_t i;
    for (i = 0; i < inlen; i += 4) {
        unsigned char sextet[4];
        for (int j = 0; j < 4; ++j) {
            char c = in[i+j];
            if (c == '=') { sextet[j] = 0; continue; }
            unsigned char val = b64_reverse[(unsigned char)c];
            if (val == 0xFF) return 0;      /* illegal character */
            sextet[j] = val;
        }
        unsigned int triple = (sextet[0] << 3*6) |
                              (sextet[1] << 2*6) |
                              (sextet[2] << 1*6) |
                              (sextet[3] << 0*6);
        if (o+3 > outsize) return 0;
        out[o++] = (triple >> 2*8) & 0xFF;
        out[o++] = (triple >> 1*8) & 0xFF;
        out[o++] = (triple >> 0*8) & 0xFF;
    }
    /* adjust for padding */
    if (inlen >= 2 && in[inlen-1] == '=') o--;
    if (inlen >= 2 && in[inlen-2] == '=') o--;
    return o;
}
#endif /* BASE64_H */
