                            b64_payload + total_read,
                            content_len - total_read);
        if (more <= 0) { close(client_fd); return; }
        total_read += more;
    }

    /* Decode Base64 */
    size_t raw_len = b64_decode((char*)b64_payload, content_len,
                                raw_payload, sizeof(raw_payload));
    if (raw_len == 0) { close(client_fd); return; }

    /* --------------------------------------------------------------
       Connect to the target, forward the data, read the reply.
       -------------------------------------------------------------- */
    int tgt = connect_target(target_ip, target_port);
    if (tgt < 0) { close(client_fd); return; }

    if (write(tgt, raw_payload, raw_len) != (ssize_t)raw_len) {
        close(tgt); close(client_fd); return;
    }

    /* Simple implementation: read whatever is available up to MAX_BUF */
    ssize_t reply_len = read(tgt, raw_payload, sizeof(raw_payload));
    close(tgt);
    if (reply_len < 0) reply_len = 0;

    /* Encode the reply */
    char b64_reply[MAX_BUF * 2];
    size_t b64_len = b64_encode(raw_payload, reply_len,
                                b64_reply, sizeof(b64_reply));
    if (b64_len == 0) { close(client_fd); return; }

    /* --------------------------------------------------------------
       Send HTTP response
       -------------------------------------------------------------- */
    char header[256];
    int hdr_len = snprintf(header, sizeof(header),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/plain\r\n"
        "Content-Length: %zu\r\n"
        "\r\n", b64_len);
    write(client_fd, header, hdr_len);
    write(client_fd, b64_reply, b64_len);
    close(client_fd);
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 4) {
        fprintf(stderr,
            "Usage: %s <listen_port> <target_ip> <target_port>\n", argv[0]);
        return 1;
    }
    const char *listen_port = argv[1];
    const char *target_ip   = argv[2];
    const char *target_port = argv[3];

    /* Create listening socket */
    struct addrinfo hints = {0}, *res, *rp;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family   = AF_UNSPEC;
    hints.ai_flags    = AI_PASSIVE;
    if (getaddrinfo(NULL, listen_port, &hints, &res) != 0) {
        perror("getaddrinfo");
        return 1;
    }

    int listen_fd = -1;
    for (rp = res; rp; rp = rp->ai_next) {
        listen_fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (listen_fd < 0) continue;
        int opt = 1;
        setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
        if (bind(listen_fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(listen_fd);
        listen_fd = -1;
    }
    freeaddrinfo(res);
    if (listen_fd < 0) {
        perror("socket/bind");
        return 1;
    }
    if (listen(listen_fd, 5) < 0) {
        perror("listen");
        return 1;
    }
    printf("[*] Listening on port %s – forwarding to %s:%s\n",
           listen_port, target_ip, target_port);

    while (1) {
        struct sockaddr_storage client_addr;
        socklen_t client_len = sizeof(client_addr);
