                               (struct sockaddr *)&client_addr,
                               &client_len);
        if (client_fd < 0) { perror("accept"); continue; }

        /* For a tiny demo we just handle one client at a time (blocking). */
        handle_one_client(client_fd, target_ip, target_port);
        /* In a real daemon you would `fork()` or spin a thread here. */
    }
    return 0;
}
```

### How it works

1. **Listener** – binds to `<listen_port>` and accepts a TCP connection.
2. **Parse HTTP** – reads the request, extracts `Content‑Length:` and the
   body (the Base64 payload).
3. **Decode** – turns the Base64 payload into the raw stream meant for
   the destination.
4. **Connect to target** – opens a new TCP socket to `<target_ip>:<target_port>`.
5. **Forward** – writes the raw payload, reads up to `MAX_BUF` bytes
   of the reply (you can turn this into a loop if you need a full‑duplex tunnel).
6. **Encode reply** – Base64‑encodes the response.
7. **Reply** – sends a minimal HTTP 200 response containing the encoded body.

> **Note:** This implementation reads a *single* request/response pair.
> If you want a *continuous* tunnel you can keep the client connection
> open and repeatedly read/write in a loop, but that makes the code a
> little longer. The client below already does a “one‑request‑per‑read”
> design – you can easily turn it into a full duplex stream.


---

## 3.  The **client** – `tunnel_client.c`

```c
/*
 * tunnel_client.c
 *
 * A tiny client that works like a local “proxy”.  It connects to a
 * user‑specified HTTP tunnel server, wraps every chunk of data that
 * arrives from the local application in a Base64‑encoded HTTP POST,
 * sends it to the server, receives the Base64 response, decodes it,
 * and writes it back to the local socket.
 *
 * Compile:
 *     gcc -Wall -O2 -o tunnel_client tunnel_client.c
 *
 * Run:
 *     ./tunnel_client <listen_port> <server_ip> <server_port>
 *
 * Example (tunnel SSH through http tunnel on the same machine):
 *     ./tunnel_client 1080 127.0.0.1 8080
 *     ssh -p 1080 user@localhost   # connects to the tunnel, which
 *                                   # forwards to the real SSH server
 */

#define _POSIX_C_SOURCE 200112L
#include <arpa/inet.h>
#include <errno.h>
#include <netdb.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>
#include "base64.h"

#define MAX_BUF   8192
#define HTTP_TUNNEL_PATH "/tunnel"

/* ---------------------------------------------------------------------- */
static int connect_to_server(const char *host, const char *port)
{
    struct addrinfo hints = {0}, *res, *rp;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family   = AF_UNSPEC;
    int s = getaddrinfo(host, port, &hints, &res);
    if (s) {
        fprintf(stderr, "getaddrinfo(%s,%s): %s\n", host, port, gai_strerror(s));
        return -1;
    }
    int fd = -1;
    for (rp = res; rp; rp = rp->ai_next) {
        fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (fd == -1) continue;
        if (connect(fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    return fd;
}

/* ---------------------------------------------------------------------- */
static ssize_t read_all(int fd, void *buf, size_t len)
{
    size_t off = 0;
    while (off < len) {
        ssize_t r = read(fd, (char*)buf + off, len - off);
        if (r <= 0) return -1;
        off += r;
    }
    return off;
}

/* ---------------------------------------------------------------------- */
static int do_one_transfer(int local_fd, int server_fd)
{
    unsigned char in_buf[MAX_BUF];
    unsigned char out_buf[MAX_BUF];
    char http_req[MAX_BUF * 2];
    char http_resp[MAX_BUF * 2];

    /* --------------------------------------------------------------
       1️⃣  Read from the local socket (application side)
       -------------------------------------------------------------- */
    ssize_t n = read(local_fd, in_buf, sizeof(in_buf));
    if (n <= 0) return -1;                 /* EOF or error */

    /* --------------------------------------------------------------
       2️⃣  Base64‑encode the payload
       -------------------------------------------------------------- */
    size_t b64_len = b64_encode(in_buf, n,
                                http_req + 1024,   /* temp buffer */
                                sizeof(http_req) - 1024);
    if (b64_len == 0) return -1;

    /* --------------------------------------------------------------
       3️⃣  Build a minimal HTTP POST request
       -------------------------------------------------------------- */
    int hdr_len = snprintf(http_req, 1024,
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: text/plain\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n",
        HTTP_TUNNEL_PATH,
        "tunnel",       /* fake Host – not used by the server */
        b64_len);
    if (hdr_len < 0 || hdr_len + b64_len > (int)sizeof(http_req)) return -1;

    memcpy(http_req + hdr_len, http_req + 1024, b64_len);
    size_t total_req = hdr_len + b64_len;

    /* --------------------------------------------------------------
       4️⃣  Send request to the tunnel server
       -------------------------------------------------------------- */
    if (write(server_fd, http_req, total_req) != (ssize_t)total_req)
        return -1;

    /* --------------------------------------------------------------
       5️⃣  Read HTTP response (very simple, no chunked encoding)
       -------------------------------------------------------------- */
    ssize_t r = read(server_fd, http_resp, sizeof(http_resp)-1);
    if (r <= 0) return -1;
    http_resp[r] = '\0';

    /* Find body start */
    const char *body = strstr(http_resp, "\r\n\r\n");
    if (!body) return -1;
    body += 4;                 /* skip CRLFCRLF */

    /* The server always returns a normal 200 response.  We ignore
       the Content‑Length header and simply decode whatever follows.   */
    size_t b64_body_len = r - (body - http_resp);
    size_t decoded_len = b64_decode(body, b64_body_len,
                                    out_buf, sizeof(out_buf));
    if (decoded_len == 0) return -1;

    /* --------------------------------------------------------------
       6️⃣  Write the decoded data back to the local socket
       -------------------------------------------------------------- */
    if (write(local_fd, out_buf, decoded_len) != (ssize_t)decoded_len)
        return -1;

    return 0;   /* success */
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 4) {
        fprintf(stderr,
            "Usage: %s <listen_port> <server_ip> <server_port>\n", argv[0]);
        return 1;
    }
    const char *listen_port = argv[1];
    const char *server_ip   = argv[2];
    const char *server_port = argv[3];

    /* --------------------------------------------------------------
       Create a listening socket for the local “proxy”.
       -------------------------------------------------------------- */
    struct addrinfo hints = {0}, *res, *rp;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family   = AF_UNSPEC;
    hints.ai_flags    = AI_PASSIVE;
    if (getaddrinfo(NULL, listen_port, &hints, &res) != 0) {
        perror("getaddrinfo");
        return 1;
    }

    int listen_fd = -1;
    for (rp = res; rp; rp = rp->ai_next) {
        listen_fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (listen_fd < 0) continue;
        int opt = 1;
        setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
        if (bind(listen_fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(listen_fd);
        listen_fd = -1;
    }
    freeaddrinfo(res);
    if (listen_fd < 0) {
        perror("socket/bind");
        return 1;
    }
    if (listen(listen_fd, 5) < 0) {
        perror("listen");
        return 1;
    }
    printf("[*] Proxy listening on 127.0.0.1:%s – forwarding to %s:%s\n",
           listen_port, server_ip, server_port);

    while (1) {
        struct sockaddr_storage client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(listen_fd,
                               (struct sockaddr *)&client_addr,
                               &client_len);
        if (client_fd < 0) { perror("accept"); continue; }

        /* ----------------------------------------------------------
           For a concise demo we handle the client serially.
           A “real” proxy would `fork()` or spawn a thread here.
           ---------------------------------------------------------- */
        int srv = connect_to_server(server_ip, server_port);
        if (srv < 0) {
            close(client_fd);
            continue;
        }

        /* Loop: read‑forward‑read … until the local side closes. */
        while (do_one_transfer(client_fd, srv) == 0) {
            /* nothing – the function does everything */
        }
        close(srv);
        close(client_fd);
    }
    return 0;
}
```

### How to use it

1. **Compile both programs**

   ```bash
   gcc -Wall -O2 -o tunnel_server tunnel_server.c
   gcc -Wall -O2 -o tunnel_client tunnel_client.c
   ```

2. **Start the server** – for example, forward everything to an SSH
   daemon running on `10.0.0.1:22`:

   ```bash
   ./tunnel_server 8080 10.0.0.1 22
   ```

   The server now listens on port **8080** and expects Base64‑wrapped POST
   requests at the path `/tunnel`.

3. **Start the client** – expose a local “proxy” on port 1080 that talks
   to the server we just started:

   ```bash
   ./tunnel_client 1080 127.0.0.1 8080
   ```

4. **Test it** – open an SSH connection **through** the HTTP tunnel:

   ```bash
   ssh -p 1080 user@127.0.0.1
   ```

   The SSH client talks to the local client (`tunnel_client`) on
   127.0.0.1:1080, which in turn sends Base64‑encoded HTTP POSTs to
   `tunnel_server`. The server forwards the data to the real SSH daemon
   (`10.0.0.1:22`) and relays the reply.

5. **Other protocols** – anything that works over TCP can be tunnelled
   the same way (HTTP, POP3, MySQL, …). Just point the server at the
   desired target host/port and make the client listen on a convenient
   local port.

---

## 4.  Things to Keep in Mind

| Issue | What the sample does | What you probably want in production |
|-------|----------------------|--------------------------------------|
| **Authentication** | None – anyone who can reach the HTTP port can tunnel. | Add a shared secret, HTTP Basic/Digest, or TLS client‑cert. |
| **TLS / HTTPS** | Plain HTTP only. | Wrap the server socket with OpenSSL (`SSL_accept`) and the client with `SSL_connect`. |
| **Full‑duplex streaming** | Server reads *once* and writes *once* per request. | Loop on both sockets (`select()`/`poll()`) and forward data continuously. |
| **Concurrency** | Single‑threaded, handles one client at a time. | `fork()`, `pthread_create()`, or an event‑loop (`libuv`, `libevent`). |
| **Chunked Transfer / Large payloads** | Fixed buffer (`MAX_BUF`). | Implement a proper HTTP parser + dynamic buffering, or use `Transfer‑Encoding: chunked`. |
| **Error handling & time‑outs** | Minimal. | Set socket time‑outs (`setsockopt`) and return proper HTTP error codes. |
| **Port‑forwarding semantics** | Always forwards to the same fixed `<target_ip>:<target_port>`. | Encode destination address in the HTTP request (e.g. query string or extra header). |

The code above is deliberately **minimalist** so you can see the core
idea of an HTTP tunnel using Base64.  Extending it to a robust, secure
solution is straightforward once you have the skeleton in place.

Enjoy! If you run into any trouble or want help adding a particular
feature, feel free to ask.

