**Solution Overview**

The task is to read a C source file (`test.txt`) and compose a *call tree* – i.e. for every function we must know which other functions it calls.  
For simplicity we accept the following **rules**:

| Rule                                   | Meaning |
|----------------------------------------|------------------------------------------------|
| *function name* – a word that consists of letters, digits and ‘_’, starts with a letter or ‘_’ | identifier |
| A function **definition** – `identifier '(' … ')'` followed (possibly after whitespace/new‑lines) by a `{` | start of a new function body |
| A function **call** – the same identifier followed immediately (after optional whitespace) by `(` **inside the body of some other function** | edge of the call graph |
| Comments (`//…` and `/* … */`) and string/character literals are ignored | they must not be treated as calls |
| The program contains only free (non‑nested) functions | C does not have nested function definitions, so a simple brace counter is enough |

The result is printed as an indented tree that starts from `main`.  
If a function is never reached from `main` it is omitted (you can change the output routine if you need a full graph).

--------------------------------------------------------------------

### 1. Data structures

```c
/* One node of the call‑graph – a function name and list of called functions */
typedef struct FuncNode {
    char *name;                     /* function name                */
    struct CallList *calls;         /* linked list of outgoing edges */
    struct FuncNode *next;          /* hash‑table / list linkage    */
} FuncNode;

/* One outgoing edge – name of a called function */
typedef struct CallList {
    char *callee;                   /* name of called function      */
    struct CallList *next;
} CallList;
```

We keep the graph in a **hash table** (simple fixed‑size array of pointers to `FuncNode`).  
All strings are duplicated with `strdup()` – the program never modifies them.

--------------------------------------------------------------------

### 2. Helper functions

```c
/* ---------- hash table ---------- */
#define HSIZE  1024
static FuncNode *htable[HSIZE] = {0};

static unsigned hash(const char *s)
{
    unsigned h = 0;
    while (*s) h = (h * 31) + (unsigned)(*s++);
    return h % HSIZE;
}

/* Find an existing node or create a new one */
static FuncNode *get_func(const char *name)
{
    unsigned h = hash(name);
    FuncNode *p = htable[h];
    while (p) {
        if (strcmp(p->name, name) == 0) return p;
        p = p->next;
    }
    /* not found → create */
    p = malloc(sizeof *p);
    p->name   = strdup(name);
    p->calls  = NULL;
    p->next   = htable[h];
    htable[h] = p;
    return p;
}

/* Add a call edge (caller → callee) */
static void add_call(const char *caller, const char *callee)
{
    if (!caller) return;                 /* call outside any function → ignore */
    FuncNode *c = get_func(caller);
    /* avoid duplicate edges – not required, but makes the output nicer */
    CallList *q = c->calls;
    while (q) {
        if (strcmp(q->callee, callee) == 0) return;
        q = q->next;
    }
    CallList *n = malloc(sizeof *n);
    n->callee = strdup(callee);
    n->next   = c->calls;
    c->calls  = n;
}

/* ---------- printing ---------- */
static void print_tree(const char *func, int depth, int *visited)
{
    unsigned h = hash(func);
    FuncNode *p = htable[h];
    while (p && strcmp(p->name, func) != 0) p = p->next;
    if (!p) return;          /* unknown function – should not happen */

    for (int i = 0; i < depth; ++i) printf("    ");
    printf("%s\n", p->name);
    visited[depth] = 1;      /* simple cycle guard – depth is enough for call‑trees */

    CallList *c = p->calls;
    while (c) {
        /* avoid infinite recursion on recursive functions */
        int already = 0;
        for (int i = 0; i < depth; ++i)
            if (strcmp(func, c->callee) == 0) { already = 1; break; }

        if (!already)
            print_tree(c->callee, depth + 1, visited);
        else {
            for (int i = 0; i <= depth; ++i) printf("    ");
            printf("%s (recursive)\n", c->callee);
        }
        c = c->next;
    }
}

/* ---------- utilities ---------- */
static int is_id_start(char c) { return isalpha((unsigned)c) || c == '_'; }
static int is_id_part (char c) { return isalnum((unsigned)c) || c == '_'; }
```

--------------------------------------------------------------------

### 3. The parser – stepping through the source file

The parser works **character by character** and respects three “modes”:

| Mode               | What is ignored                                   |
|--------------------|---------------------------------------------------|
| `NORMAL`           | ordinary code – we look for identifiers          |
| `LINE_COMMENT`     | everything up to `\n`                             |
| `BLOCK_COMMENT`    | everything up to the matching `*/`               |
| `STRING_LITERAL`   | everything up to the matching unescaped `"`      |
| `CHAR_LITERAL`     | everything up to the matching unescaped `'`      |

When the parser is in `NORMAL` mode it extracts an identifier, looks ahead (skipping only blanks and new‑lines) and decides whether the identifier is

* a **definition** – the next non‑blank character after the matching `)` is `{`.  
  In that case the identifier becomes the *current function* (`cur_func`).  
  The opening `{` also increments a *brace counter* (`brace_depth`).

* a **call** – the next non‑blank character after the identifier is `(`.  
  The identifier is stored as a call from `cur_func`.

While inside a function body the brace counter is increased on every `{` and decreased on every `}`.  
When `brace_depth` returns to `0` we have left the function – `cur_func` becomes `NULL`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ---- data structures and helper functions (see sections 1‑2) ---- */
#define HSIZE 1024
typedef struct CallList {
    char *callee;
    struct CallList *next;
} CallList;
typedef struct FuncNode {
    char *name;
    CallList *calls;
    struct FuncNode *next;
} FuncNode;

static FuncNode *htable[HSIZE] = {0};

static unsigned hash(const char *s) {
    unsigned h = 0;
    while (*s) h = h*31 + (unsigned)*s++;
