        if (strcmp(q->callee, callee) == 0) return;
        q = q->next;
    }
    CallList *n = malloc(sizeof *n);
    n->callee = strdup(callee);
    n->next   = c->calls;
    c->calls  = n;
}

/* ---- printing ---- */
static void print_tree(const char *func, int depth, int *stack) {
    unsigned h = hash(func);
    FuncNode *p = htable[h];
    while (p && strcmp(p->name, func) != 0) p = p->next;
    if (!p) return;
    for (int i = 0; i < depth; ++i) printf("    ");
    printf("%s\n", p->name);
    stack[depth] = 1;                 /* remember that we are on this level */

    CallList *c = p->calls;
