            }
            ident[ident_len] = '\0';
            if (ch != EOF) ungetc(ch, fp);     /* put back the first non‑identifier char */

            /* look ahead, skipping only whitespace and new‑lines */
            long savepos = ftell(fp);
            int nxt;
            do { nxt = fgetc(fp); } while (nxt != EOF && isspace(nxt));
            if (nxt == '(') {                     /* could be a call OR a definition */
                /* to decide we need to know where the matching ')' is */
                int par = 1;
                while (par && (nxt = fgetc(fp)) != EOF) {
                    if (nxt == '(') ++par;
                    else if (nxt == ')') --par;
                    else if (nxt == '\'' || nxt == '"') {   /* skip strings inside prototype */
                        int quote = nxt;
                        while ((nxt = fgetc(fp)) != EOF && nxt != quote) {
                            if (nxt == '\\') fgetc(fp);
                        }
                    }
                }
                /* after the closing ')' we again skip blanks */
                while ((nxt = fgetc(fp)) != EOF && isspace(nxt));
                if (nxt == '{' && brace_depth == 0) {
                    /* ----- function definition ----- */
                    cur_func = strdup(ident);
                    brace_depth = 1;            /* we have already consumed the opening '{' */
                } else {
                    /* ----- ordinary function call ----- */
                    if (cur_func) add_call(cur_func, ident);
                }
                if (nxt != EOF) ungetc(nxt, fp);
            } else {
                /* not a '(' → just a plain identifier, ignore */
                fseek(fp, savepos, SEEK_SET);
            }
            continue;
        }

        /* ---------- braces – only relevant when we are inside a function body ---------- */
        if (brace_depth > 0) {
            if (ch == '{')
                ++brace_depth;
            else if (ch == '}') {
                --brace_depth;
                if (brace_depth == 0) {
                    /* we left the current function */
                    free(cur_func);
                    cur_func = NULL;
                }
            }
        }
    }   /* while file */

    fclose(fp);

    /* ----- output ----- */
    printf("Call tree (starting from main):\n");
    int dummy[256] = {0};
    print_tree("main", 0, dummy);
    return 0;
}
```

--------------------------------------------------------------------

### 4. How the program works (step‑by‑step)

| Step | Action |
|------|--------|
| 1️⃣  | Open *test.txt*. |
| 2️⃣  | Scan the file character‑wise, keeping a **state machine** that skips comments, string literals and character literals. |
| 3️⃣  | When the state is *NORMAL* and a **identifier** is seen – collect the whole word (`ident`). |
| 4️⃣  | Look ahead (ignoring whitespace) to see whether the next non‑blank character is `(`. |
| 5️⃣  | If it is `(`, read until the matching `)` (to correctly skip nested parentheses inside a prototype). |
| 6️⃣  | After the closing `)` skip whitespace again:   |
|      | – If the next char is `{` **and** we are *not* already inside a function body (`brace_depth==0`) → this identifier is a **function definition**. Store its name in `cur_func` and set `brace_depth = 1`. |
|      | – Otherwise we are looking at a **function call**. Add an edge `cur_func → ident` to the graph (if `cur_func` is not `NULL`). |
| 7️⃣  | While `brace_depth > 0` count every `{` and `}`. When the counter returns to `0` we have exited the current function – clear `cur_func`. |
| 8️⃣  | After the whole file is processed, the hash table contains the whole call graph. |
| 9️⃣  | Starting from the node `"main"` a depth‑first walk prints the tree, indenting one level per recursion depth. Recursive calls are detected and printed with the note “(recursive)”. |

--------------------------------------------------------------------

### 5. Example

**`test.txt`**

```c
#include <stdio.h>

void foo(void) {
    bar();
    baz();
}

int bar() {
    return 0;
}

/* recursive example */
int baz() {
    baz();          // recursive call
    return 1;
}

int main(void) {
    foo();
    bar();
    return 0;
}
```

**Program output**

```
Call tree (starting from main):
main
    foo
        bar
        baz
            baz (recursive)
    bar
```

The tree shows that `main` calls `foo` and `bar`; `foo` calls `bar` and `baz`; `baz` calls itself recursively.

--------------------------------------------------------------------

### 6. Limitations & Possible Improvements

| Limitation | Reason | Possible fix |
|------------|--------|--------------|
| The parser is *approximate*: it does not handle macros that generate code, `#include`‑d files, or function‑like macros that hide a `(` after an identifier. | Full C parsing is extremely complex. | Run the program on pre‑processed source (`gcc -E`). |
| Only a **single** definition per name is stored – if there are overloaded functions (C does not have them, but static functions with the same name in different translation units could appear). | The graph is built per file, not per whole program. | Build a global graph from several source files. |
| Recursive functions are printed only once (the second appearance is labelled “recursive”). | To keep the output a tree rather than a generic graph. | Output a DOT/GraphViz file for a full graph visualization. |
| No detection of *indirect* calls through function pointers. | Static analysis cannot see them without sophisticated data‑flow analysis. | Combine with a separate analysis tool or add heuristics. |

--------------------------------------------------------------------

### 7. Build & run

```sh
gcc -Wall -Wextra -std=c11 -o calltree calltree.c
./calltree            # expects a file named test.txt in the same directory
```

The program prints the call tree to the console. You may redirect the output to a file or modify the printing routine to generate GraphViz (`.dot`) source for nicer graphical representation.

