/****************************************************************
 *   MyDX11Hook.cpp – универсальный DX11 hook + ImGui меню
 *   Требуемые библиотеки:
 *      - MinHook (libminhook.lib, include/minhook.h)
 *      - ImGui (imgui.h/.cpp + impl_win32/dx11)
 *   Сборка:   MSVC, /MD, проект типа DLL
 ****************************************************************/

#include <Windows.h>
#include <d3d11.h>
#include <dxgi.h>

// ----------------- MinHook -----------------
#include "MinHook.h"

// ----------------- ImGui -------------------
#include "imgui.h"
#include "imgui_impl_win32.h"
#include "imgui_impl_dx11.h"

// ------------------------------------------
// Декларации функций DirectX
// ------------------------------------------
using PresentFn = HRESULT(__stdcall*)(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags);
static PresentFn oPresent = nullptr;               // указатель на оригинальную функцию

// ----------------------------------------------------------------
// Глобальные переменные, используемые в hook'е
// ----------------------------------------------------------------
static ID3D11Device*           g_pd3dDevice = nullptr;
static ID3D11DeviceContext*    g_pd3dContext = nullptr;
static IDXGISwapChain*         g_pSwapChain = nullptr;
static ID3D11RenderTargetView* g_mainRenderTargetView = nullptr;

static bool g_ImGuiInitialized = false;
static bool g_ShowMenu = false;   // переключаем через Insert

// ----------------------------------------------------------------
// Вспомогательная функция: создание RenderTargetView из back‑bufferа
// ----------------------------------------------------------------
static void CreateRenderTarget()
{
    ID3D11Texture2D* pBackBuffer = nullptr;
    g_pSwapChain->GetBuffer(0, __uuidof(ID3D11Texture2D), (LPVOID*)&pBackBuffer);
    if (pBackBuffer)
    {
        g_pd3dDevice->CreateRenderTargetView(pBackBuffer, nullptr, &g_mainRenderTargetView);
        pBackBuffer->Release();
    }
}

// ----------------------------------------------------------------
// Очистка render‑target'а
// ----------------------------------------------------------------
static void CleanupRenderTarget()
{
    if (g_mainRenderTargetView)
    {
        g_mainRenderTargetView->Release();
        g_mainRenderTargetView = nullptr;
    }
}

// ----------------------------------------------------------------
// Инициализация ImGui (один раз)
// ----------------------------------------------------------------
static void InitImGui(IDXGISwapChain* pSwapChain)
{
    // Получаем устройство/контекст из swap‑chain
    if (FAILED(pSwapChain->GetDevice(__uuidof(ID3D11Device), (void**)&g_pd3dDevice)))
        return;
    g_pd3dDevice->GetImmediateContext(&g_pd3dContext);
    g_pSwapChain = pSwapChain;

    // Render target
    CreateRenderTarget();

    // ImGui context
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO(); (void)io;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard; // (опционально)

    // Платформенно‑графические бекенды
    ImGui_ImplWin32_Init(FindWindowW(L"SDL_app", nullptr)); // часто в играх окно имеет класс "SDL_app". Если не работает – подставьте свой.
    ImGui_ImplDX11_Init(g_pd3dDevice, g_pd3dContext);

    // Стиль (можно менять)
    ImGui::StyleColorsDark();

    g_ImGuiInitialized = true;
}

// ----------------------------------------------------------------
// Отрисовка нашего ImGui‑меню
// ----------------------------------------------------------------
static void RenderImGui()
{
    // Новый кадр
    ImGui_ImplDX11_NewFrame();
    ImGui_ImplWin32_NewFrame();
    ImGui::NewFrame();

    // ------------------ Меню ------------------
    if (g_ShowMenu)
    {
        ImGui::Begin("My DX11 Hook", &g_ShowMenu, ImGuiWindowFlags_AlwaysAutoResize);
        static bool      checkbox = false;
        static float     slider = 0.5f;
        static int       counter = 0;

        ImGui::Text("Привет, мир!");
        ImGui::Checkbox("Чекбокс", &checkbox);
        ImGui::SliderFloat("Ползунок", &slider, 0.0f, 1.0f);
        if (ImGui::Button("Нажми меня"))
            ++counter;
        ImGui::SameLine();
        ImGui::Text("Счётчик = %d", counter);
        ImGui::End();
    }

    // Rendering
    ImGui::Render();
    g_pd3dContext->OMSetRenderTargets(1, &g_mainRenderTargetView, nullptr);
    ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());
}

// ----------------------------------------------------------------
// Хук на IDXGISwapChain::Present
// ----------------------------------------------------------------
static HRESULT __stdcall hkPresent(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags)
{
    // Один раз инициализируем ImGui
    if (!g_ImGuiInitialized)
        InitImGui(pSwapChain);

    // Обновляем render‑target, если он был пере‑создан (пример: ресайз)
    static bool first = true;
    if (first)
    {
        // иногда в некоторых играх render target уже готов, но если он нулевой – создаём.
        if (!g_mainRenderTargetView)
            CreateRenderTarget();
        first = false;
    }

    // Переключаем меню клавишей Insert (не забудьте включить MAP VK_INSERT в GetAsyncKeyState)
    if (GetAsyncKeyState(VK_INSERT) & 1)
        g_ShowMenu = !g_ShowMenu;

    // Рисуем ImGui
    if (g_ImGuiInitialized)
        RenderImGui();

    // Вызов оригинального Present
    return oPresent(pSwapChain, SyncInterval, Flags);
}

// ----------------------------------------------------------------
// Патчинг функции Present через MinHook
// ----------------------------------------------------------------
DWORD WINAPI MainThread(LPVOID)
{
    // Дождёмся, пока DirectX будет готов (некоторые игры создают swapchain позже)
    Sleep(2000);

    // Инициализируем MinHook
    if (MH_Initialize() != MH_OK)
        return 1;

    // Получаем адрес оригинального Present.
    // Чтобы не создавать собственный swapchain, делаем "мягкий" трюк:
    // 1) создаём временный device+swapchain
    // 2) берём из его vtable нужный метод (8‑й элемент)
    D3D_FEATURE_LEVEL featureLevel = D3D_FEATURE_LEVEL_11_0;
    DXGI_SWAP_CHAIN_DESC sd = {0};
    sd.BufferCount = 2;
    sd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    sd.BufferDesc.Width = 100;
    sd.BufferDesc.Height = 100;
    sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    sd.OutputWindow = GetForegroundWindow(); // любой активный HWND
    sd.SampleDesc.Count = 1;
    sd.Windowed = TRUE;
    sd.SwapEffect = DXGI_SWAP_EFFECT_DISCARD;

    ID3D11Device*           pDevice = nullptr;
    ID3D11DeviceContext*    pContext = nullptr;
    IDXGISwapChain*         pSwap = nullptr;

    if (FAILED(D3D11CreateDeviceAndSwapChain(
        nullptr,
        D3D_DRIVER_TYPE_HARDWARE,
        nullptr,
        0,
        &featureLevel,
        1,
        D3D11_SDK_VERSION,
        &sd,
        &pSwap,
        &pDevice,
        nullptr,
        &pContext)))
    {
        MH_Uninitialize();
        return 1;
    }

    // Получаем указатель на функцию Present из VTable (index 8)
    void** pVTable = *reinterpret_cast<void***>(pSwap);
    void* pPresent = pVTable[8];

    // Создаём хук
    if (MH_CreateHook(pPresent, &hkPresent, reinterpret_cast<LPVOID*>(&oPresent)) != MH_OK)
    {
        pSwap->Release(); pDevice->Release(); pContext->Release();
        MH_Uninitialize();
        return 1;
    }

    // Включаем хук
    if (MH_EnableHook(pPresent) != MH_OK)
    {
        pSwap->Release(); pDevice->Release(); pContext->Release();
        MH_Uninitialize();
        return 1;
    }

    // Убираем временные объекты – они нам больше не нужны
    pSwap->Release(); pDevice->Release(); pContext->Release();

    // Периодически проверяем, не ушёл ли процесс
    while (GetModuleHandleW(L"game.exe") || GetModuleHandleW(nullptr)) // замените на имя вашей игры, если надо
    {
        Sleep(500);
    }

    // Отключаем и чистим
    MH_DisableHook(pPresent);
    MH_Uninitialize();

    // ImGui cleanup
    if (g_ImGuiInitialized)
    {
        ImGui_ImplDX11_Shutdown();
        ImGui_ImplWin32_Shutdown();
        ImGui::DestroyContext();
    }

    CleanupRenderTarget();
    if (g_pd3dContext) g_pd3dContext->Release();
    if (g_pd3dDevice)  g_pd3dDevice->Release();

    FreeLibraryAndExitThread(static_cast<HMODULE>(GetModuleHandleW(nullptr)), 0);
    return 0;
}

// ----------------------------------------------------------------
// DllMain – точка входа DLL
// ----------------------------------------------------------------
BOOL APIENTRY DllMain(HMODULE hModule,
                      DWORD  ul_reason_for_call,
                      LPVOID lpReserved)
{
    switch (ul_reason_for_call)
    {
    case DLL_PROCESS_ATTACH:
        DisableThreadLibraryCalls(hModule);
        // Запускаем наш поток в отдельном контексте, чтобы DllMain не блокировался
        CreateThread(nullptr, 0, MainThread, nullptr, 0, nullptr);
        break;
    case DLL_PROCESS_DETACH:
        // Всё очищаем в MainThread – сюда обычно попадаем уже после освобождения.
        break;
    }
    return TRUE;
}
```

