```c
#include <stdio.h>
#include <stdlib.h>

/* Kiểm tra một số nguyên (long long) có phải là palindrome không */
int isPalindrome(long long x)
{
    if (x < 0)                 // bỏ qua số âm
        return 0;

    long long orig = x, rev = 0;
    while (x > 0)
    {
        rev = rev * 10 + x % 10;
        x   /= 10;
    }
    return rev == orig;
}

int main(void)
{
    int n;
    long long value;
    long long sum = 0;      // tổng các số palindrome
    int        cnt = 0;     // số lượng palindrome

    printf("Nhap so luong n: ");
    if (scanf("%d", &n) != 1 || n <= 0)
    {
        printf("Gia tri n khong hop le.\n");
        return 1;
    }

    printf("Nhap %d so nguyen (cach nhau bang khoang trang hoac dong moi):\n", n);
    for (int i = 0; i < n; ++i)
    {
        if (scanf("%lld", &value) != 1)
        {
            printf("Du lieu nhap khong hop le.\n");
            return 1;
        }

        if (isPalindrome(value))
        {
            sum += value;
            ++cnt;
        }
    }

    if (cnt == 0)
    {
        printf("Khong co so doi xung.\n");
    }
    else
    {
        double avg = (double)sum / cnt;
        printf("So luong so doi xung: %d\n", cnt);
        printf("Tong cac so doi xung: %lld\n", sum);
        printf("Trung binh cong cac so doi xung: %.2f\n", avg);
    }

    return 0;
}
```

### Giải thích nhanh

| Phần | Mô tả |
|------|------|
| `isPalindrome` | Đảo ngược số bằng phép chia `%10` và so sánh với giá trị gốc. |
| `sum` và `cnt` | Lưu trữ tổng và số lượng các số palindrome để tính trung bình. |
| Kiểm tra `n` | Đảm bảo người dùng nhập một số nguyên dương. |
| Đầu ra | Nếu có ít nhất một số palindrome → in số lượng, tổng và trung bình (đến 2 chữ số thập phân). Nếu không → thông báo “Khong co so doi xung”. |

---

## Ví dụ chạy chương trình

```
Nhap so luong n: 7
Nhap 7 so nguyen (cach nhau bang khoang trang hoac dong moi):
121 34 55 -121 777 202 99

So luong so doi xung: 5
Tong cac so doi xung: 1274
Trung binh cong cac so doi xung: 254.80
```

- Các số palindrome trong dãy: 121, 55, 777, 202, 99.  
- Tổng = 121 + 55 + 777 + 202 + 99 = 1274  
- Trung bình = 1274 / 5 = 254.8

---

**Lưu ý**  
- Nếu muốn tính trung bình dưới dạng `float` thay cho `double`, chỉ cần thay kiểu `double` thành `float`.  
- Nếu muốn xét cả số 0 là palindrome (đương nhiên là có), hàm `isPalindrome` đã xử lý được vì `rev` và `orig` đều bằng 0.  

Chúc bạn thành công!

