#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <semaphore.h>
#include <fcntl.h>   /* O_* */
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/types.h>

/* Nazwy semaforów w systemie */
#define SEM1_NAME "/mySem1_demo"
#define SEM2_NAME "/mySem2_demo"

/* Globalne uchwyty – potrzebne w handlerze sygnału */
static sem_t *g_sem1 = NULL;
static sem_t *g_sem2 = NULL;

/* --------------------------------------------------------------- *
 *  Funkcja pomocnicza – wypisuje komunikat z identyfikatorem PID *
 * --------------------------------------------------------------- */
static void info(const char *fmt, ...)
{
