/* --------------------------------------------------------------- *
 *  Obsługa sygnału SIGINT (Ctrl‑C) – sprzątanie i exit            *
 * --------------------------------------------------------------- */
static void sigint_handler(int signo)
{
    (void)signo;                     /* nie używane */
