        sem_close(g_sem1);
        /* Nie usuwamy semaforów tutaj – zostaną usunięte przez
         * ostatnią instancję, która wywoła sem_unlink (zobacz main). */
    }
    if (g_sem2) sem_close(g_sem2);
    _exit(EXIT_SUCCESS);
}

/* --------------------------------------------------------------- *
 *  Zajęcie (wait) semafora z komunikatem                           *
 * --------------------------------------------------------------- */
static void lock_sem(sem_t *sem, const char *name)
{
    info("Czeka na %s ... ", name);
    if (sem_wait(sem) == -1) {
        perror("sem_wait");
        return;
    }
    info("zajęto %s\n", name);
}

/* --------------------------------------------------------------- *
 *  Zwolnienie (post) semafora z komunikatem                        *
 * --------------------------------------------------------------- */
static void unlock_sem(sem_t *sem, const char *name)
{
    if (sem_post(sem) == -1) {
        perror("sem_post");
        return;
    }
    info("zwolniono %s\n", name);
}

/* --------------------------------------------------------------- *
 *  Główna pętla programu                                           *
 * --------------------------------------------------------------- */
