     *  Otwieramy (lub tworzymy) dwa semafory nazwane              *
     *  O_CREAT  – jeżeli nie istnieją, zostaną utworzone          *
     *  O_EXCL   – pozwala wykryć, czy to pierwsza instancja        *
     * ----------------------------------------------------------- */
    int first_instance = 0;            /* true, jeżeli tworzymy od nowa */

    g_sem1 = sem_open(SEM1_NAME, O_CREAT | O_EXCL, 0644, 1);
    if (g_sem1 == SEM_FAILED) {
