            g_sem1 = sem_open(SEM1_NAME, 0);
        } else {
            perror("sem_open sem1");
            exit(EXIT_FAILURE);
        }
    } else {
        first_instance = 1;
        info("stworzono semafor %s (wartość początkowa = 1)\n", SEM1_NAME);
    }

