            break;
        case '2':   /* zajęcie sem2 */
            lock_sem(g_sem2, "sem2");
            break;
        case 'w':   /* zwolnienie sem2 */
            unlock_sem(g_sem2, "sem2");
            break;
        case 'a':   /* zajęcie obu – najpierw 1, potem 2 */
