/*======================================================================
 *  magazzino.c – implementation of the warehouse functions
 *====================================================================*/

#include "magazzino.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/*--------------------------------------------------------------------*/
/* 1) READ STOCK                                                       */
int read_stock(FILE *fp, Product stock[], int *nProd)
{
    if (!fp || !stock || !nProd) return -1;

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        /* Skip blank lines */
        if (line[0] == '\n' || line[0] == '\r')
            continue;

        /* Expected format: code price qty */
        char code[MAX_CODE_LEN];
        double price;
        int qty;

        int scanned = sscanf(line, "%31s %lf %d", code, &price, &qty);
        if (scanned != 3) {
            fprintf(stderr, "Warning: line ignored (bad format): %s", line);
            continue;
        }

        if (count >= MAX_PRODUCTS) {
            fprintf(stderr,
                    "Warning: maximum number of products (%d) reached – line ignored\n",
                    MAX_PRODUCTS);
            continue;
        }

        /* store */
        strncpy(stock[count].code, code, MAX_CODE_LEN);
        stock[count].code[MAX_CODE_LEN - 1] = '\0';
        stock[count].price = price;
        stock[count].qty   = qty;
        ++count;
    }

    *nProd = count;
    return count;               /* >0 = ok, 0 = empty file */
}

/*--------------------------------------------------------------------*/
/* 2) CHECK VARIATION                                                  */
static int find_product(const Product stock[], int nProd,
                        const char *code)
{
    for (int i = 0; i < nProd; ++i)
        if (strcmp(stock[i].code, code) == 0)
            return i;
    return -1;                  /* not found */
}

int check_variation(const Product stock[], int nProd,
                    const char *code, int delta)
{
    int idx = find_product(stock, nProd, code);
    if (idx < 0) return -1;                 /* product not present */

    int new_qty = stock[idx].qty + delta;

    if (new_qty < 0 || new_qty > 10000)
        return -2;                          /* out of allowed range */

    /* variation is possible – print it */
    printf("Variazione possibile: prodotto %s, delta %d, nuova quantità %d\n",
           code, delta, new_qty);
    return 1;
}

/*--------------------------------------------------------------------*/
/* 3) UPDATE AND PRINT                                                 */
double stock_total(const Product stock[], int nProd)
{
    double tot = 0.0;
    for (int i = 0; i < nProd; ++i)
        tot += stock[i].price * stock[i].qty;
    return tot;
}

void update_and_print(Product stock[], int nProd,
                      const char *code, int delta)
{
    int idx = find_product(stock, nProd, code);
    if (idx < 0) {
        /* should never happen if caller used check_variation() */
        fprintf(stderr, "update_and_print: product %s not found!\n", code);
        return;
    }

    double before = stock_total(stock, nProd);

    stock[idx].qty += delta;    /* apply the variation */

    double after = stock_total(stock, nProd);

    printf("Valore totale magazzino prima della modifica: %.2f €\n", before);
    printf("Valore totale magazzino dopo  la modifica: %.2f €\n", after);
}

/*--------------------------------------------------------------------*/
/* 4) SORT AND SAVE                                                    */
static int cmp_desc_total(const void *a, const void *b)
{
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;

    double ta = pa->price * pa->qty;
    double tb = pb->price * pb->qty;

    if (ta < tb) return  1;     /* descending order */
    if (ta > tb) return -1;
    return 0;
}

void sort_and_save(FILE *fp, Product stock[], int nProd)
{
    if (!fp) return;

    /* make a copy because we do not want to disturb the order used in
       the interactive part (it is not required, but it is a clean approach) */
    Product *copy = malloc(nProd * sizeof(Product));
    if (!copy) {
        perror("malloc");
        return;
    }
    memcpy(copy, stock, nProd * sizeof(Product));

    qsort(copy, nProd, sizeof(Product), cmp_desc_total);

    /* output format: code price qty totalValue */
    for (int i = 0; i < nProd; ++i) {
        double total = copy[i].price * copy[i].qty;
        fprintf(fp, "%s %.2f %d %.2f\n",
                copy[i].code,
                copy[i].price,
                copy[i].qty,
                total);
    }

    free(copy);
}

/*--------------------------------------------------------------------*/
/* End of magazzino.c                                                  */
```

--------------------------------------------------------------------

## 4. Driver – *main.c*

```c
/*======================================================================
 *  main.c – interactive driver of the warehouse program
 *====================================================================*/

#include "magazzino.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define STOP_CODE "XXXXXX"

int main(int argc, char *argv[])
{
    /* ----------------------------------------------------------------
     *  Check command‑line arguments
     * ---------------------------------------------------------------- */
    if (argc != 3) {
        fprintf(stderr,
                "Uso: %s <file_input_magazzino> <file_output_magazzino>\n",
                argv[0]);
        return EXIT_FAILURE;
    }

    const char *in_name  = argv[1];
    const char *out_name = argv[2];

    /* ----------------------------------------------------------------
     *  Open the input file and read the initial stock
     * ---------------------------------------------------------------- */
    FILE *fin = fopen(in_name, "r");
    if (!fin) {
        perror(in_name);
        return EXIT_FAILURE;
    }

    Product stock[MAX_PRODUCTS];
    int nProd = 0;

    if (read_stock(fin, stock, &nProd) < 0) {
        fprintf(stderr, "Errore nella lettura del file di magazzino.\n");
        fclose(fin);
        return EXIT_FAILURE;
    }
    fclose(fin);

    printf("Caricati %d prodotti dal magazzino.\n", nProd);

    /* ----------------------------------------------------------------
     *  Interactive loop – read commands from stdin
     * ---------------------------------------------------------------- */
    char code[MAX_CODE_LEN];
    int  delta;

    while (true) {
        printf("\nInserire comando (codice variazione) oppure \"%s\" per terminare:\n> ",
               STOP_CODE);
        fflush(stdout);

        /* read a line; we use fgets to avoid problems with stray spaces */
        char line[128];
        if (!fgets(line, sizeof(line), stdin)) {
            /* EOF (Ctrl‑D) */
            break;
        }

        /* Strip the trailing newline */
        line[strcspn(line, "\r\n")] = '\0';

        /* empty line → ask again */
        if (line[0] == '\0')
            continue;

        /* stop condition */
        if (strcmp(line, STOP_CODE) == 0)
            break;

        /* parse the command */
        int scanned = sscanf(line, "%31s %d", code, &delta);
        if (scanned != 2) {
            printf("Formato non valido. Usa: <codice> <variazione>\n");
            continue;
        }

        /* ----------------------------------------------------------------
         *  1) Verify if the variation can be applied
         * ---------------------------------------------------------------- */
        int chk = check_variation(stock, nProd, code, delta);
        if (chk == 1) {
            /* ----------------------------------------------------------------
             *  2) Perform the update and report the global value
             * ---------------------------------------------------------------- */
            update_and_print(stock, nProd, code, delta);
        } else if (chk == -1) {
            printf("Prodotto \"%s\" non presente in magazzino. Operazione ignorata.\n",
                   code);
        } else if (chk == -2) {
            printf("Variazione impossibile per \"%s\" (quantità negativa o >10000). Operazione ignorata.\n",
                   code);
        }
        /* otherwise (should not happen) we just loop again */
    }

    /* ----------------------------------------------------------------
     *  3) Write the final, sorted stock to the output file
     * ---------------------------------------------------------------- */
    FILE *fout = fopen(out_name, "w");
    if (!fout) {
        perror(out_name);
        return EXIT_FAILURE;
    }

    sort_and_save(fout, stock, nProd);
    fclose(fout);

    printf("\nMagazzino salvato su \"%s\" (ordinato per valore decrescente).\n",
           out_name);
    return EXIT_SUCCESS;
}
```

--------------------------------------------------------------------

## 5. How to compile & run  

```bash
# Compile
gcc -Wall -Wextra -std=c11 -o magazzino main.c magazzino.c

# Run
./magazzino magazzino_input.txt magazzino_output.txt
```

*`magazzino_input.txt`* must contain one product per line with the three fields separated by white‑space, for example:

```
A123 12.50 100
B02  0.80  5000
XYZ9 45.00  20
```

During execution the program repeatedly asks for commands:

```
codice variazione
```

* `codice` → product identifier (max 31 chars, no spaces)  
* `variazione` → signed integer, e.g. `+10` or `-5`

When the user types `XXXXXX` the loop ends, the program writes the sorted stock to the output file (each line contains **code price qty totalValue**) and terminates.

--------------------------------------------------------------------

## 6. Remarks & possible extensions  

* **Error handling** – the program prints warnings for malformed lines in the input file and continues.  
* **Limits** – quantity limits (`0 … 10000`) and a maximum of 100 distinct products are enforced as required.  
* **Sorting** – we use `qsort()` with a comparator that orders by `price * qty` descending. The original order stored in `stock[]` is left untouched (the sorting works on a copy).  
* **Portability** – only standard C library functions are used; the code compiles with any C11‑compatible compiler.  

Feel free to adapt the input format, add more fields (e.g. description), or integrate a more sophisticated user interface. The core logic respecting the five exercises is fully covered.

