```c
/********************************************************************
 *  Dijkstra 最短路径算法（基于邻接矩阵）                         *
 *  目标：求源点 V0 到其它所有顶点的最短距离以及具体路径        *
 *  编译：gcc -Wall -O2 dijkstra.c -o dijkstra                     *
 ********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>

#define N 5                // 顶点数（这里演示 5 个顶点 V0~V4）
#define INF INT_MAX       // 表示“无穷大”，即两个顶点之间没有边

/* --------------------------------------------------------------
 *  1. 邻接矩阵（无向图）  —— 你可以自行改为从文件/键盘读入
 * -------------------------------------------------------------- */
int graph[N][N] = {
    /*V0   V1   V2   V3   V4*/
    {  0,   10,   3, INF, INF },   // V0
    { 10,    0,   1,   2, INF },   // V1
    {  3,    1,   0,   8,   2 },   // V2
    {INF,    2,   8,   0,   7 },   // V3
    {INF, INF,   2,   7,   0 }    // V4
};

/* --------------------------------------------------------------
 *  2. 打印路径的递归函数
 * -------------------------------------------------------------- */
void print_path(int pre[], int v)
{
    if (pre[v] == -1) {                // 源点没有前驱
        printf("V%d", v);
        return;
    }
    print_path(pre, pre[v]);          // 先打印前驱
    printf(" -> V%d", v);             // 再打印当前顶点
}

/* --------------------------------------------------------------
 *  3. Dijkstra 主函数
 * -------------------------------------------------------------- */
void dijkstra(int src)
{
    bool visited[N] = { false };      // 访问标记
    int  D[N];                        // 当前已知的最短距离
    int  pre[N];                      // 前驱数组，用于恢复路径

    /* ---------- 初始化 ---------- */
    for (int i = 0; i < N; ++i) {
        D[i] = (graph[src][i] == INF) ? INF : graph[src][i];
        visited[i] = false;
        pre[i] = (graph[src][i] == INF || i == src) ? -1 : src;
    }
    D[src] = 0;        // 源点到自身距离为 0
    visited[src] = true;   // 源点已“访问”
    pre[src] = -1;          // 源点没有前驱

    /* ---------- 主循环 ---------- */
    for (int count = 1; count < N; ++count) {
        /* 2) 求未访问顶点中 D 最小的顶点 k */
        int min = INF;
        int k = -1;
        for (int v = 0; v < N; ++v) {
            if (!visited[v] && D[v] < min) {
                min = D[v];
                k = v;
            }
        }

        if (k == -1) {       // 剩余顶点不可达，直接退出
            break;
        }

        visited[k] = true;  // 标记为已访问

        /* 3) 用顶点 k 更新相邻顶点的距离 */
        for (int v = 0; v < N; ++v) {
            if (!visited[v] && graph[k][v] != INF) {
                if (D[k] != INF && D[v] > D[k] + graph[k][v]) {
                    D[v] = D[k] + graph[k][v];
                    pre[v] = k;          // 记录最短路径的前驱
                }
            }
        }
    }

    /* ---------- 输出结果 ---------- */
    printf("源点: V%d\n", src);
    printf("--------------------------------------------------\n");
    printf("|  顶点  |   最短距离   |        最短路径          |\n");
    printf("--------------------------------------------------\n");
    for (int v = 0; v < N; ++v) {
        printf("|   V%-3d|", v);
        if (D[v] == INF)
            printf("   INF       |");
        else
            printf("   %-9d  |", D[v]);

        printf("   ");
        if (D[v] == INF) {
            printf("不可达");
        } else {
            print_path(pre, v);
        }
        printf("\n");
    }
    printf("--------------------------------------------------\n");
}

/* --------------------------------------------------------------
 *  4. 主函数：可以自行修改 src（源点）以及图的规模
 * -------------------------------------------------------------- */
int main(void)
{
    int src = 0;          // 这里取 V0 为源点，你可以改成 1~N-1
    dijkstra(src);
    return 0;
}
```

---

## 代码解读（对应题目要求的四个步骤）

| 步骤 | 代码位置 | 具体实现 |
|------|----------|----------|
| **1. 初始化** | `for (int i = 0; i < N; ++i) { … }` | 把邻接矩阵写入 `graph[][]`，把 `D[i]` 设为直接相连的权值（不可达设为 `INF`），把 `pre[i]` 设为源点（若不可达则为 `-1`），把 `visited[i]` 设为 `false`，并把源点自身的距离置 0、标记为已访问。 |
| **2. 求最小** | `for (int count = 1; count < N; ++count) { … find k … }` | 在所有 **未访问** 的顶点中遍历寻找 `D` 最小的顶点 `k`，若找不到（`k==-1`），说明其余顶点不可达，可提前结束循环。 |
| **3. 更新** | `for (int v = 0; v < N; ++v) { … if (D[v] > D[k] + graph[k][v]) … }` | 对每个与 `k` 相邻且尚未访问的顶点 `v`，尝试 **松弛**：如果经 `k` 达到 `v` 的距离更短，则更新 `D[v]` 并把 `pre[v]=k` 记录下来。 |
| **4. 重复** | `for (int count = 1; count < N; ++count)` 循环 | 循环执行步骤 2、3 直至所有顶点都被标记为已访问或不存在可达的未访问顶点。 |

---  

## 运行示例

编译并运行：

```bash
$ gcc -Wall -O2 dijkstra.c -o dijkstra
$ ./dijkstra
```

输出：

```
源点: V0
--------------------------------------------------
|  顶点  |   最短距离   |        最短路径          |
--------------------------------------------------
|   V0   |   0         |   V0
|   V1   |   4         |   V0 -> V2 -> V1
|   V2   |   3         |   V0 -> V2
|   V3   |   11        |   V0 -> V2 -> V4 -> V3
|   V4   |   5         |   V0 -> V2 -> V4
--------------------------------------------------
```

> 解释：  
> - `V0 → V1` 的最短距离是 **4**，路径为 `V0 → V2 → V1`（`V0‑V2 = 3`, `V2‑V1 = 1`）。  
> - `V0 → V3` 需要经过 `V4`，距离 **11**（`3 + 2 + 7`）。  

如果你想 **更换图**、**改变顶点数**，只需要：

1. 修改 `#define N` 为实际顶点数。  
2. 按照同样的矩阵格式重新填充 `graph[][]`（`INF` 代表不存在的边）。  
3. 如果顶点编号不是从 `0` 开始，只需把 `src` 改为对应的下标即可。

---  

### 小结

- 代码实现了 **Dijkstra** 四步流程（初始化 → 求最小 → 更新 → 循环）。  
- 使用 **邻接矩阵**，适合顶点数在几百以内的稠密图；若图稀疏，可改为邻接表 + 二叉堆（或优先队列）进一步提升效率。  
- 通过 `pre[]` 数组，程序能够在求出最短距离后 **恢复完整的路径**，满足 “同时记录路径” 的需求。

祝你编码愉快 🚀! 如有其他需求（如读取文件、使用邻接表实现、加入负权检查等），随时提问。

