```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

/*--------------------------------------------------------------
   Returns 1 (true) if n is a prime number, 0 otherwise.
   Works for n >= 0.
--------------------------------------------------------------*/
_Bool isPrime(int n)
{
    if (n < 2)                     /* 0 and 1 are not prime */
        return 0;

    int limit = (int)sqrt((double)n);
    for (int i = 2; i <= limit; ++i) {
        if (n % i == 0)
            return 0;              /* divisor found */
    }
    return 1;                      /* no divisor → prime */
}

/*--------------------------------------------------------------
   Returns 1 (true) if n is a palindrome in base‑10,
   0 otherwise.
--------------------------------------------------------------*/
_Bool isSymn(int n)
{
    n = abs(n);                     /* ignore sign */
    if (n < 10)                     /* single digit → palindrome */
        return 1;

    /* ---- determine the number of decimal digits ---- */
    int len = 0;
    int tmp = n;
    while (tmp > 0) {
        ++len;
        tmp /= 10;
    }

    /* ---- compare symmetric digits ---- */
    for (int i = 1; i <= len / 2; ++i) {
        int leftDigit  = (n / (int)pow(10, i - 1)) % 10;      /* i‑th digit from the right */
        int rightDigit = (n / (int)pow(10, len - i)) % 10;   /* i‑th digit from the left */
        if (leftDigit != rightDigit)
            return 0;              /* mismatch → not a palindrome */
    }
    return 1;                      /* all pairs matched */
}

/*--------------------------------------------------------------
   Reads five integers and prints “Yes” if the number is both
   prime and a palindrome, otherwise prints “No”.
--------------------------------------------------------------*/
int main(void)
{
    int n;
    for (int i = 0; i < 5; ++i) {
        if (scanf("%d", &n) != 1)    /* defensive: stop if input ends */
            break;

        if (isPrime(n) && isSymn(n))
            printf("Yes\n");
        else
            printf("No\n");
    }
    return 0;
}
```

### How it works

1. **`isPrime`**  
   * Rejects numbers `< 2`.  
   * Checks divisibility only up to `√n`.  
2. **`isSymn`** (palindrome test)  
   * First computes how many decimal digits `n` has (`len`).  
   * Then walks from the outermost digits toward the centre, comparing the *i‑th* digit from the right with the *i‑th* digit from the left.  
   * If any pair differs, the number isn’t a palindrome.  
3. **`main`**  
   * Reads exactly five integers.  
   * For each one prints `"Yes"` if it satisfies **both** conditions, otherwise `"No"`.  
   * A newline (`\n`) after every answer makes the output readable.

---

### Quick test

