typedef struct {
    int          idx;           // 线程编号 0..NTHREADS-1
    const char  *local_ip;      // 绑定的本地 IP
} thread_arg_t;

/* 线程主循环 */
static void *worker_thread(void *arg)
{
    thread_arg_t *targ = (thread_arg_t *)arg;
    int idx = targ->idx;
    const char *local_ip = targ->local_ip;
    int epfd = -1;
    struct epoll_event ev, events[MAX_EVENTS];
    conn_t *c = NULL;          // 本线程唯一的连接对象

    /* 1）创建 epoll 实例（每线程独立） */
    epfd = epoll_create1(EPOLL_CLOEXEC);
    if (epfd == -1) {
        perr("epoll_create1");
        goto out;
    }

    /* 2）建立并绑定 socket */
    int sfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sfd == -1) { perr("socket"); goto out; }

    if (set_nonblocking(sfd) == -1) { perr("set_nonblocking"); close(sfd); goto out; }

    /* 绑定本地 IP（端口为 0，让系统分配） */
    struct sockaddr_in local_addr;
    memset(&local_addr, 0, sizeof(local_addr));
    local_addr.sin_family = AF_INET;
    local_addr.sin_port   = htons(0);               // 让系统自动选择端口
    if (inet_pton(AF_INET, local_ip, &local_addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid local IP %s\n", local_ip);
        close(sfd);
        goto out;
    }
    if (bind(sfd, (struct sockaddr *)&local_addr, sizeof(local_addr)) == -1) {
        perr("bind");
        close(sfd);
        goto out;
    }

    /* 3）发起 connect（非阻塞） */
    struct sockaddr_in remote_addr;
    memset(&remote_addr, 0, sizeof(remote_addr));
    remote_addr.sin_family = AF_INET;
    remote_addr.sin_port   = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &remote_addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid server IP %s\n", SERVER_IP);
        close(sfd);
        goto out;
    }
    int rc = connect(sfd, (struct sockaddr *)&remote_addr, sizeof(remote_addr));
    if (rc == -1 && errno != EINPROGRESS) {
        perr("connect");
        close(sfd);
        goto out;
    }

