    ev.events  = EPOLLIN | EPOLLOUT | EPOLLET | EPOLLONESHOT;
    ev.data.ptr = c;          // 把 conn_t 指针塞进去，后面直接拿到
    if (epoll_ctl(epfd, EPOLL_CTL_ADD, sfd, &ev) == -1) {
        perr("epoll_ctl ADD");
        free(c);
        close(sfd);
        goto out;
    }

    /* 5）事件循环 */
    while (1) {
        int n = epoll_wait(epfd, events, MAX_EVENTS, -1);
        if (n == -1) {
            if (errno == EINTR) continue;   // 被信号中断，继续
            perr("epoll_wait");
            break;
        }

        for (int i = 0; i < n; ++i) {
            conn_t *conn = (conn_t *)events[i].data.ptr;
            uint32_t evs = events[i].events;

            /*-------------------------- 处理 connect 完成 --------------------------*/
            if (conn->state == ST_CONNECTING && (evs & EPOLLOUT)) {
                int err = 0;
                socklen_t len = sizeof(err);
                if (getsockopt(conn->fd, SOL_SOCKET, SO_ERROR, &err, &len) < 0) {
                    perr("getsockopt after connect");
                    conn->state = ST_CLOSING;
                } else if (err != 0) {
                    fprintf(stderr, "Thread %d: connect to %s:%d failed: %s\n",
                            idx, SERVER_IP, SERVER_PORT, strerror(err));
                    conn->state = ST_CLOSING;
                } else {
                    printf("Thread %d: connect succeeded (local %s)\n",
                           idx, local_ip);
                    conn->state = ST_ESTABLISHED;
                }
            }

            /*-------------------------- 可读事件 --------------------------*/
            if (evs & EPOLLIN) {
                while (1) {
                    ssize_t nr = read(conn->fd, conn->buf, BUF_SIZE);
                    if (nr > 0) {
                        /* 这里我们把收到的数据直接回写（Echo），演示业务 */
                        conn->wpos = (size_t)nr;
                        // 将 EPOLLOUT 重新打开
                        ev.events  = EPOLLIN | EPOLLOUT | EPOLLET | EPOLLONESHOT;
                        ev.data.ptr = conn;
                        if (epoll_ctl(epfd, EPOLL_CTL_MOD, conn->fd, &ev) == -1) {
                            perr("epoll_ctl MOD after read");
                            conn->state = ST_CLOSING;
                        }
                        break;          // 等待写事件再发送
                    } else if (nr == 0) {
                        /* 对端已关闭 */
                        printf("Thread %d: peer closed connection\n", idx);
                        conn->state = ST_CLOSING;
                        break;
                    } else { // nr < 0
                        if (errno == EAGAIN || errno == EWOULDBLOCK) {
                            /* 已读完所有数据 */
                            break;
                        }
                        perr("read");
                        conn->state = ST_CLOSING;
                        break;
                    }
                }
            }

            /*-------------------------- 可写事件 --------------------------*/
            if (evs & EPOLLOUT && conn->state == ST_ESTABLISHED && conn->wpos > 0) {
                while (conn->wpos > 0) {
                    ssize_t nw = write(conn->fd, conn->buf, conn->wpos);
                    if (nw > 0) {
                        /* 已写出一部分 */
                        if ((size_t)nw < conn->wpos) {
                            memmove(conn->buf, conn->buf + nw, conn->wpos - nw);
                        }
                        conn->wpos -= (size_t)nw;
                    } else {
                        if (errno == EAGAIN || errno == EWOULDBLOCK) {
                            /* 写缓冲区满，稍后再尝试 */
                            break;
                        }
                        perr("write");
                        conn->state = ST_CLOSING;
                        break;
                    }
                }
            }

            /*-------------------------- 重新开启事件（或关闭） --------------------------*/
            if (conn->state == ST_CLOSING) {
                close(conn->fd);
                free(conn);
                /* 此线程不再复用该 fd，直接退出 loop（也可以重连） */
                goto thread_exit;
            } else {
                /* 重新开启 EPOLLONESHOT，确保下次仍然只能被本线程处理 */
                ev.events  = EPOLLIN | EPOLLOUT | EPOLLET | EPOLLONESHOT;
                ev.data.ptr = conn;
                if (epoll_ctl(epfd, EPOLL_CTL_MOD, conn->fd, &ev) == -1) {
                    perr("epoll_ctl MOD final");
                    conn->state = ST_CLOSING;
                }
            }
        } // for each event
    } // while epoll_wait

thread_exit:
    /* 清理资源（若还有残留） */
    if (c) {
        if (c->fd >= 0) close(c->fd);
        free(c);
    }
    if (epfd >= 0) close(epfd);
    printf("Thread %d exit\n", idx);
    return NULL;
}
```

