## 4. 主函数（创建线程池）

```c
int main(void)
{
    pthread_t th[NTHREADS];
    thread_arg_t args[NTHREADS];

    for (int i = 0; i < NTHREADS; ++i) {
        args[i].idx      = i;
        args[i].local_ip = LOCAL_IPS[i];
        int rc = pthread_create(&th[i], NULL, worker_thread, &args[i]);
        if (rc != 0) {
            fprintf(stderr, "pthread_create %d failed: %s\n", i, strerror(rc));
            exit(EXIT_FAILURE);
        }
    }

    /* 主线程可以做统计、捕获信号、或等所有子线程退出 */
    for (int i = 0; i < NTHREADS; ++i) {
        pthread_join(th[i], NULL);
    }
    return 0;
}
```

