 *  depth (on average) and O(n²) worst‑case time.  To mitigate the
 *  worst case we pick a **random pivot** in partition().
 * ------------------------------------------------------------- */
void quick_sort(int arr[], int low, int high)
{
    if (low < high) {
        int p = partition(arr, low, high);   /* p is the final index of the pivot */
        quick_sort(arr, low, p - 1);
        quick_sort(arr, p + 1, high);
