static int partition(int arr[], int low, int high)
{
    /* Choose a random pivot and move it to the end */
    int pivot_index = low + rand() % (high - low + 1);
    int pivot_value = arr[pivot_index];
    int tmp = arr[pivot_index];
    arr[pivot_index] = arr[high];
    arr[high] = tmp;          /* now pivot is at arr[high] */

    int store_index = low;    /* place for the next element <= pivot */

    for (int i = low; i < high; ++i) {
        if (arr[i] <= pivot_value) {
            /* swap arr[i] and arr[store_index] */
            tmp = arr[i];
            arr[i] = arr[store_index];
            arr[store_index] = tmp;
            ++store_index;
        }
    }

    /* Move pivot to its final place */
    tmp = arr[store_index];
    arr[store_index] = arr[high];
    arr[high] = tmp;

    return store_index;
