#include <stdio.h>
#include <stdlib.h>
#include <math.h>

/*--------------------------------------------------------------------*/
/*  1.  Binary‑search‑tree node                                         */
typedef struct BstNode {
    int data;
    struct BstNode *lchild, *rchild;
} BstNode;

/* 2.  Create a single node                                            */
static BstNode *GetNewNode(int data)
{
    BstNode *p = (BstNode *)malloc(sizeof(BstNode));
    p->data = data;
    p->lchild = p->rchild = NULL;
    return p;
}

/* 3.  Insert – returns the (possibly new) subtree root                */
static BstNode *Insert(BstNode *root, int data)
{
    if (root == NULL)                     /* empty subtree -> new node   */
        return GetNewNode(data);

    if (data < root->data)                /* go left                     */
        root->lchild = Insert(root->lchild, data);
    else                                   /* go right (>=)               */
        root->rchild = Insert(root->rchild, data);

    return root;                          /* unchanged root               */
}

/*--------------------------------------------------------------------*/
/*  4.  Queue used by BFS – stores a node together with its depth      */
typedef struct QNode {
    BstNode *node;
    int      depth;            /* depth of 'node' (root = 0) */
    struct QNode *next;
} QNode;

typedef struct {
    QNode *front;      /* dummy header – never NULL   */
    QNode *rear;       /* points to last real element */
    int    size;       /* number of real elements     */
} BiTQueue;

/* 5.  Initialise an empty queue (dummy header)                        */
static BiTQueue *InitQueue(void)
{
    BiTQueue *q = (BiTQueue *)malloc(sizeof(BiTQueue));
    QNode    *dummy = (QNode *)malloc(sizeof(QNode));
    dummy->next = NULL;
    q->front = q->rear = dummy;
    q->size = 0;
    return q;
}

/* 6.  Enqueue                                                       */
static void Push(BiTQueue *q, BstNode *node, int depth)
{
    QNode *n = (QNode *)malloc(sizeof(QNode));
    n->node  = node;
    n->depth = depth;
    n->next  = NULL;

    q->rear->next = n;       /* link after current rear */
    q->rear = n;             /* move rear pointer       */
    ++q->size;
}

/* 7.  Dequeue – returns the stored node; caller also gets depth via pointer */
static BstNode *Pop(BiTQueue *q, int *pDepth)
{
    if (q->size == 0) return NULL;    /* should never happen */

    QNode *first = q->front->next;    /* first real element */
    BstNode *ans = first->node;
    *pDepth = first->depth;

    q->front->next = first->next;     /* detach */
    if (q->front->next == NULL)       /* queue becomes empty */
        q->rear = q->front;

    free(first);
    --q->size;
    return ans;
}

/*--------------------------------------------------------------------*/
/*  8.  Breadth‑first traversal that prints only the requested level   */
static void LevelOrderPrint(BstNode *root, int wantedLevel)
{
    if (root == NULL) return;

    BiTQueue *q = InitQueue();
    Push(q, root, 0);                     /* root is at depth 0 */

    while (q->size > 0) {
        int curDepth;
        BstNode *cur = Pop(q, &curDepth);

        if (curDepth == wantedLevel)      /* this node belongs to the query */
