        if (cur->lchild) Push(q, cur->lchild, curDepth + 1);
        if (cur->rchild) Push(q, cur->rchild, curDepth + 1);
    }

    /* optional newline – matches the usual “one line per level” style */
    if (wantedLevel >= 0) printf("\n");

    /* free queue structure (its dummy header) */
    free(q->front);
    free(q);
}

/*--------------------------------------------------------------------*/
/*  9.  (optional) free the whole tree – not needed for the judge, but good practice */
static void DestroyTree(BstNode *root)
{
    if (!root) return;
    DestroyTree(root->lchild);
    DestroyTree(root->rchild);
    free(root);
}

/*--------------------------------------------------------------------*/
int main(void)
{
    int cnt, a, level;

    /* 1) number of elements */
    if (scanf("%d", &cnt) != 1) return 0;

    BstNode *root = NULL;
    for (int i = 0; i < cnt; ++i) {
