/*--------------------------------------------------------------
 * Чтение первой найденной строки, содержащей подстроку "key".
 * Возвращает 0 – успешно, -1 – ошибка.
 *--------------------------------------------------------------*/
static int read_key_from_file(const char *path,
                              const char *key,
                              char *out, size_t out_sz)
{
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, key)) {
            /* Убираем конец строки */
            char *p = strchr(line, '\n');
            if (p) *p = '\0';

            /* Находим символ ':' (если есть) и берём всё после него */
            char *val = strchr(line, ':');
            if (val) {
                val++;                     /* за ':' */
                while (*val == ' ' || *val == '\t')
                    ++val;                 /* пропустить пробелы */
                strncpy(out, val, out_sz - 1);
                out[out_sz - 1] = '\0';
                fclose(fp);
                return 0;
            } else {
                /* Если ':' нет – берём всю строку после ключа */
                char *src = line + strlen(key);
                while (*src == ' ' || *src == '\t' || *src == ':')
                    ++src;
                strncpy(out, src, out_sz - 1);
                out[out_sz - 1] = '\0';
                fclose(fp);
                return 0;
            }
        }
    }

    fclose(fp);
    return -1;          /* ключ не найден */
}

/*--------------------------------------------------------------
 * Чтение произвольного файла целиком (без '\n' в конце строки).
 *--------------------------------------------------------------*/
static int read_file(const char *path, char *out, size_t out_sz)
{
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;

    size_t r = fread(out, 1, out_sz - 1, fp);
    out[r] = '\0';
    fclose(fp);
    return 0;
}

/*--------------------------------------------------------------
 * Получаем MAC‑адрес первого доступного сетевого интерфейса.
 * Пытаемся открыть eth0 → wlan0 → any (первая строка в /sys/class/net).
 *--------------------------------------------------------------*/
static int get_mac_address(char *out, size_t out_sz)
{
    const char *ifs[] = { "eth0", "wlan0", NULL };
    char path[128];
    FILE *fp;
    size_t i;

    for (i = 0; ifs[i]; ++i) {
        snprintf(path, sizeof(path),
                 "/sys/class/net/%s/address", ifs[i]);
        if ((fp = fopen(path, "r")) != NULL) {
            if (fgets(out, out_sz, fp)) {
                char *p = strchr(out, '\n');
                if (p) *p = '\0';
                fclose(fp);
                return 0;
            }
            fclose(fp);
        }
    }

    /* Если eth0 и wlan0 нет, ищем любой интерфейс: */
    if ((fp = fopen("/sys/class/net", "r")) != NULL) {
        /* Список каталогов в /sys/class/net содержит имена интерфейсов,
         * но здесь проще открыть каталог через opendir(). */
        fclose(fp);
    }

    /* Как последний шанс – читаем /sys/class/net/eth0/address,
     * даже если файл не существует, возвратим ошибку. */
    snprintf(path, sizeof(path),
             "/sys/class/net/eth0/address");
    if ((fp = fopen(path, "r")) != NULL) {
        if (fgets(out, out_sz, fp)) {
            char *p = strchr(out, '\n');
            if (p) *p = '\0';
            fclose(fp);
            return 0;
        }
        fclose(fp);
    }

    return -1;  /* не удалось получить MAC */
}

/*--------------------------------------------------------------
 * Вычисляем SHA‑256 и преобразуем в шестнадцатеричную строку.
 *--------------------------------------------------------------*/
static void sha256_hex(const unsigned char *data,
                       size_t len,
                       char out_hex[65])   // 64 символа + '\0'
{
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(data, len, hash);

    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i)
        sprintf(out_hex + i * 2, "%02x", hash[i]);
    out_hex[64] = '\0';
}

/*=====================================================================
 * main()
 *=====================================================================*/
int main(void)
{
    char serial[MAX_LINE]   = "";
    char mac[MAX_LINE]      = "";
    char machine_id[MAX_LINE] = "";
    char buffer[MAX_BUF]    = "";
    char uuid[65];

    /* 1) serial из /proc/cpuinfo */
    if (read_key_from_file("/proc/cpuinfo", "Serial", serial,
                           sizeof(serial)) == 0) {
        /* Удаляем возможно присутствующий префикс "0x" */
        if (strncmp(serial, "0x", 2) == 0)
            memmove(serial, serial + 2, strlen(serial) - 1);
    }

    /* 2) MAC‑адрес */
    if (get_mac_address(mac, sizeof(mac)) != 0)
        strcpy(mac, "");    // если не удалось – оставляем пустой

    /* 3) /etc/machine-id (если файл существует) */
    if (read_file("/etc/machine-id", machine_id, sizeof(machine_id)) != 0)
        strcpy(machine_id, "");

    /* Формируем один длинный ввод для хеширования */
    snprintf(buffer, sizeof(buffer),
             "serial=%s;mac=%s;machine-id=%s",
             serial, mac, machine_id);

    /* Вычисляем SHA‑256 */
    sha256_hex((unsigned char *)buffer, strlen(buffer), uuid);

    printf("Device UUID (SHA‑256): %s\n", uuid);
    return 0;
}
```

### Что делает программа

| Шаг | Какой источник используется | Почему он уникален |
|-----|----------------------------|--------------------|
| **Serial** | `Serial` в `/proc/cpuinfo` – это заводской серийный номер процессора/чипа SoC. | На большинстве одноплатных компьютеров (Orange Pi, Raspberry Pi, …) это уникальное значение, записываемое производителем. |
| **MAC‑address** | MAC‑адрес первого сетевого интерфейса (`eth0`/`wlan0`). | MAC‑адрес сетевой карты также уникален (если сеть включена). |
| **machine‑id** | Содержимое `/etc/machine-id` (создаётся в процессе установки ОС). | Предоставляет дополнительный «software‑level» идентификатор, который сохраняется в образе ОС. |
| **SHA‑256** | Все найденные части склеиваются в одну строку, из неё считается SHA‑256. | Хеш гарантирует фиксированную длину (64 HEX‑символа) и скрывает исходные данные от посторонних. |

### Как собрать

```bash
# Установить dev‑пакет OpenSSL, если его ещё нет
sudo apt-get install libssl-dev   # Debian/Ubuntu

# Сборка
gcc -Wall -O2 device_id.c -lcrypto -o device_id
```

### Как запустить

```bash
./device_id
# Пример вывода:
# Device UUID (SHA-256): 9f3c2a5e6b7d1c8e4f2a1b3c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4
```

Если какая‑то часть (например, MAC‑адрес) недоступна, программа просто оставит её пустой строкой – в итоге хеш всё равно будет уникален благодаря остальным полям.

### Как адаптировать под свои нужды

| Требование | Что менять |
|------------|------------|
| **Другое хеш‑функцию** | Заменить `SHA256` на `SHA1`, `MD5` или любой пользовательский алгоритм. |
| **Добавить данные** | Считать, например, `hostname`, `cpuinfo` полностью, или `board name` из `/proc/device-tree/model`. |
| **Сохранить UUID** | Записать полученный UUID в файл (`/etc/device-id`) или в NVRAM (если есть). |
| **Отказ от OpenSSL** | Можно использовать лёгкую реализацию SHA‑256 (есть публичные одностраничные версии) и избавиться от зависимости `-lcrypto`. |

--- 

**Итого:** Приведённый пример демонстрирует простой, но надёжный способ получения уникального идентификатора платы Orange Pi Zero в Linux‑среде, используя только системные файлы и библиотеку OpenSSL. При необходимости его легко расширить или модифицировать под любые другие одноплатные компьютеры.

