## 2. Реализация

```cpp
#include <iostream>
#include <cstring>
#include <cctype>
#include <stdexcept>

struct BigInt {
    static const int MAX_DIGITS = 35;          // > 30 (нужен запас)
    char digits[MAX_DIGITS];                   // каждый элемент – одна десятичная цифра
    bool negative;                             // знак

    // ------------------- Конструкторы -------------------
    BigInt() {                                   // по умолчанию = 0
        negative = false;
        std::memset(digits, 0, sizeof(digits));
    }

    explicit BigInt(const char *s) {            // из строки
        fromString(s);
    }

    explicit BigInt(long long v) {              // из обычного целого
        negative = (v < 0);
        if (v < 0) v = -v;
        std::memset(digits, 0, sizeof(digits));
        int pos = MAX_DIGITS - 1;
        if (v == 0) digits[pos] = 0;
        while (v > 0 && pos >= 0) {
            digits[pos--] = v % 10;
            v /= 10;
        }
        normalize();
    }

    // ------------------- Вспомогательные -------------------
    void fromString(const char *s) {
        std::memset(digits, 0, sizeof(digits));
        negative = false;
        while (std::isspace(*s)) ++s;            // пропустить начальные пробелы

        if (*s == '+' || *s == '-') {
            negative = (*s == '-');
            ++s;
        }

        // пропускаем ведущие нули, запоминаем длину
        while (*s == '0') ++s;
        int len = 0;
        const char *p = s;
        while (std::isdigit(*p)) { ++len; ++p; }

        if (len == 0) {                          // строка не содержит цифр → 0
            negative = false;
            return;
        }
        if (len > MAX_DIGITS) throw std::overflow_error("Number too long");

        // кладём цифры в массив справа налево
        int src = len - 1;
        int dst = MAX_DIGITS - 1;
        while (src >= 0) {
            digits[dst--] = s[src--] - '0';
        }
        normalize();
    }

    // Удаляем лишние нули слева, делаем 0 всегда положительным
    void normalize() {
        int i = 0;
        while (i < MAX_DIGITS && digits[i] == 0) ++i;
        if (i == MAX_DIGITS) {           // всё нули → 0
            negative = false;
            return;
        }
        // если после удаления нулей число стало 0, сбрасываем знак
        if (i == MAX_DIGITS - 1 && digits[i] == 0) negative = false;
    }

    // Сравнение по модулю:  >0 если |a|>|b|, 0 если |a|==|b|, <0 иначе
    static int cmpAbs(const BigInt& a, const BigInt& b) {
        for (int i = 0; i < MAX_DIGITS; ++i) {
            if (a.digits[i] != b.digits[i])
                return (a.digits[i] > b.digits[i]) ? 1 : -1;
        }
        return 0;
    }

    // |a| + |b| → res
    static void addAbs(const BigInt& a, const BigInt& b, BigInt& res) {
        int carry = 0;
        for (int i = MAX_DIGITS - 1; i >= 0; --i) {
            int sum = a.digits[i] + b.digits[i] + carry;
            res.digits[i] = sum % 10;
            carry = sum / 10;
        }
        // переполнение в этом диапазоне невозможно (задан достаточный размер)
        res.negative = false;
        res.normalize();
    }

    // |a| - |b|, где гарантировано |a| >= |b| → res (знак не меняем)
    static void subAbs(const BigInt& a, const BigInt& b, BigInt& res) {
        int borrow = 0;
        for (int i = MAX_DIGITS - 1; i >= 0; --i) {
            int diff = a.digits[i] - b.digits[i] - borrow;
            if (diff < 0) {
                diff += 10;
                borrow = 1;
            } else borrow = 0;
            res.digits[i] = diff;
        }
        res.negative = false;
        res.normalize();
    }

    // ------------------- Операторы -------------------
    friend BigInt operator+(const BigInt& a, const BigInt& b) {
        BigInt res;
        if (a.negative == b.negative) {               // одинаковые знаки → просто сложить модули
            addAbs(a, b, res);
            res.negative = a.negative;
        } else {
            // разные знаки → вычитаем меньший модуль из большего
            int cmp = cmpAbs(a, b);
            if (cmp == 0) {                // |a|==|b| → 0
                res = BigInt();
            } else if (cmp > 0) {          // |a| > |b|
                subAbs(a, b, res);
                res.negative = a.negative;
            } else {                       // |b| > |a|
                subAbs(b, a, res);
                res.negative = b.negative;
            }
        }
        return res;
    }

    friend BigInt operator-(const BigInt& a, const BigInt& b) {
        BigInt nb = b;
        nb.negative = !b.negative;    // a - b = a + (-b)
        return a + nb;
    }

    friend BigInt operator*(const BigInt& a, const BigInt& b) {
        BigInt res;                    // уже ноль
        for (int i = MAX_DIGITS - 1; i >= 0; --i) {   // перебираем цифры b (множитель)
            if (b.digits[i] == 0) continue;
            int carry = 0;
            BigInt tmp;                // промежуточный результат "a * digit"
            // позиция, куда ставим первую цифру: i (отсчёт от конца)
            int pos = i;
            for (int j = MAX_DIGITS - 1; j >= 0; --j) {
                int prod = a.digits[j] * b.digits[i] + carry;
                tmp.digits[pos] = prod % 10;
                carry = prod / 10;
                --pos;
            }
            // добавляем полученный промежуточный результат к общему ответу
            BigInt newRes;
            addAbs(res, tmp, newRes);
            res = newRes;
        }
        res.negative = (a.negative != b.negative) && !(cmpAbs(res, BigInt()) == 0);
        res.normalize();
        return res;
    }

    // Деление: возвращается только целая часть (все остальные операции могут быть реализованы отдельно)
    friend BigInt operator/(const BigInt& a, const BigInt& b) {
        if (cmpAbs(b, BigInt()) == 0) throw std::runtime_error("Division by zero");
        BigInt dividend = a;
        dividend.negative = false;   // будем работать с абсолютными величинами
        BigInt divisor = b;
        divisor.negative = false;

        BigInt zero;
        BigInt one("1");
        BigInt quotient;

        // Алгоритм «длинного деления» в десятичной системе.
        // Мы будем формировать частичную часть делимого слева направо.
        BigInt cur;                   // текущий «частичный» остаток
        for (int i = 0; i < MAX_DIGITS; ++i) {
            // сдвинуть cur на одну цифру влево и добавить следующую цифру из dividend
            // (по‑сути cur = cur*10 + dividend.digits[i])
            // Сдвиг реализуем простым умножением на 10
            // (это безопасно, так как размер массива достаточен)
            // Переносим цифру
            // 1) умножаем cur на 10
            int carry = 0;
            for (int k = MAX_DIGITS - 1; k >= 0; --k) {
                int val = cur.digits[k] * 10 + carry;
                cur.digits[k] = val % 10;
                carry = val / 10;
            }
            // 2) добавляем текущую цифру dividend
            cur.digits[MAX_DIGITS - 1] = cur.digits[MAX_DIGITS - 1] + dividend.digits[i];
            // нормализуем (в случае переполнения, хотя в нашем диапазоне не случится)
            for (int k = MAX_DIGITS - 1; k > 0; --k) {
                if (cur.digits[k] >= 10) {
                    cur.digits[k] -= 10;
                    cur.digits[k - 1] += 1;
                }
            }

            // теперь ищем, сколько раз divisor помещается в cur (0…9)
            int cnt = 0;
            while (cmpAbs(cur, divisor) >= 0) {
                BigInt tmp;
                subAbs(cur, divisor, tmp);
                cur = tmp;
                ++cnt;
            }
            // записываем найденную цифру в частное
            quotient.digits[i] = cnt;
        }
        quotient.negative = (a.negative != b.negative) && !(cmpAbs(quotient, zero) == 0);
        quotient.normalize();
        return quotient;
    }

    // Остаток от деления a % b  (по определению: a = (a/b)*b + a% b)
    friend BigInt operator%(const BigInt& a, const BigInt& b) {
        if (cmpAbs(b, BigInt()) == 0) throw std::runtime_error("Division by zero");
        BigInt div = a / b;
        BigInt mult = div * b;
        BigInt rem = a - mult;
        return rem;
    }

    // ------------------- Вывод -------------------
    friend std::ostream& operator<<(std::ostream& os, const BigInt& v) {
        if (v.negative) os << '-';
        int i = 0;
        while (i < BigInt::MAX_DIGITS && v.digits[i] == 0) ++i;
        if (i == BigInt::MAX_DIGITS) { os << '0'; return os; } // 0
        for (; i < BigInt::MAX_DIGITS; ++i) os << char('0' + v.digits[i]);
        return os;
    }
};
```

### Пояснения к ключевым частям

| Функция | Что делает |
|---------|------------|
| `fromString` | Парсит строку (может содержать `+`/`-`, пробелы, ведущие нули). Заполняет массив справа‑налево. |
| `normalize` | Убирает лишние ведущие нули (не меняет массив, только запоминает, где начинается число). Если число равно нулю – снимает знак. |
| `cmpAbs` | Сравнение модулей без учёта знака – цикл от старшего разряда к младшему. |
| `addAbs` / `subAbs` | Сложение/вычитание только модулей; результат всегда положительный. |
| `operator+` / `operator-` | Реализованы через `addAbs`/`subAbs` и сравнение знаков. |
| `operator*` | «Школьное» умножение: для каждой цифры `b` умножаем `a` на эту цифру, сдвигаем и складываем. |
| `operator/` | Длинное деление в десятичной системе. Мы построили частный остаток последовательно, поэтому получаем **целую часть**. |
| `operator%` | Вычисляется как `a - (a/b)*b`. |

