#include <iostream>
#include <cstring>          // strlen、strcpy
using namespace std;

class CGoods
{
protected:
    long   no;           // 商品号
    char  *p_name;       // 商品名（动态分配）
    double price;        // 商品价格

public:
    // ---------- 构造函数 ----------
    CGoods(long no_val, const char *p_val, double price_val)
        : no(no_val), price(price_val)
    {
        // 为商品名分配空间（长度+1，用于保存 '\0'）
        size_t len = strlen(p_val);
        p_name = new char[len + 1];
        strcpy(p_name, p_val);
        ++count;                         // 计数器 +1
    }

    // ---------- 复制构造函数（深拷贝） ----------
    CGoods(const CGoods &g)
        : no(g.no), price(g.price)
    {
        size_t len = strlen(g.p_name);
        p_name = new char[len + 1];
        strcpy(p_name, g.p_name);
        ++count;
    }

    // ---------- 析构函数 ----------
    virtual ~CGoods()                 // 为后面的多态准备 virtual
    {
        delete [] p_name;
        --count;                     // 计数器 -1
    }

    // ---------- 打印成员 ----------
    void print() const
    {
        cout << "No: " << no
             << "  Name: " << p_name
             << "  Price: " << price << endl;
    }

    // ---------- 下面的成员会在后面的题目中使用 ----------
    // (a) 静态计数器
    static int getCount() { return count; }

    // (b) 运算符重载
    bool operator<(const CGoods &rhs) const { return price <  rhs.price; }
    bool operator>=(const CGoods &rhs) const { return price >= rhs.price; }

    // (c) 为多态准备的虚函数（默认实现可以为空）
    virtual void usedFor() const   // 基类不关心具体用途，留空或打印通用信息
    {
        cout << "[CGoods] No specific usage.\n";
    }

    // ---------- 友元函数 ----------
    friend const char* getName(const CGoods &g);   // 只能在类外部读取 p_name

private:
    // 商品总数（所有对象共享）——**静态数据成员**
    static int count;
};

/* 静态成员必须在类外进行定义（并给出初值） */
int CGoods::count = 0;

/* 友元函数实现：访问 private 成员 p_name */
const char* getName(const CGoods &g)
{
    return g.p_name;               // 直接返回内部指针（只读用法）
}
