    CFood(const CFood &f)
        : CGoods(f)
    {
        size_t len = strlen(f.p_brand);
        p_brand = new char[len + 1];
        strcpy(p_brand, f.p_brand);
    }

    // 析构函数
    ~CFood() override
    {
        delete [] p_brand;
    }

    // 用途输出（覆盖基类虚函数）
