### 5.  Complete program (C99)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* --------------------------------------------------------------
   Global board – each cell contains two characters plus '\0'
   -------------------------------------------------------------- */
char **board;

/* --------------------------------------------------------------
   Helper
   -------------------------------------------------------------- */
int isPowerOfTwo(int v) { return v > 0 && (v & (v-1)) == 0; }

void setCell(int x, int y, const char *s)
{
    board[y][x]   = s[0];
    board[y][x+1] = s[1];
}

/* --------------------------------------------------------------
   Recursive tiling function
   -------------------------------------------------------------- */
void tromino(int x_board, int y_board,
             int x_missing, int y_missing,
             int board_size)
{
    if (board_size == 2)                 /* ---- base case ---- */
    {
        /* write the missing square */
        setCell(x_missing, y_missing, "MS");

        /* which corner is missing ? */
        if (x_missing == x_board && y_missing == y_board+1)          /* UL */
        {
            setCell(x_board+1, y_board,     "LR");
            setCell(x_board,   y_board,     "LR");
            setCell(x_board+1, y_board+1,   "LR");
        }
        else if (x_missing == x_board+1 && y_missing == y_board+1)   /* UR */
        {
            setCell(x_board,   y_board+1,   "LL");
            setCell(x_board,   y_board,     "LL");
            setCell(x_board+1, y_board,     "LL");
        }
        else if (x_missing == x_board+1 && y_missing == y_board)     /* LR */
        {
            setCell(x_board,   y_board+1,   "UL");
            setCell(x_board+1, y_board+1,   "UL");
            setCell(x_board,   y_board,     "UL");
        }
        else                                                          /* LL */
        {
            setCell(x_board,   y_board+1,   "UR");
            setCell(x_board+1, y_board+1,   "UR");
            setCell(x_board+1, y_board,     "UR");
        }
        return;
    }

    /* ---- recursive case ---- */
    int half = board_size / 2;

    /* centre cells (the four cells that touch the four sub‑boards) */
    int cx = x_board + half - 1;
    int cy = y_board + half - 1;

    /* which quadrant contains the real missing square ? */
    int missingUL = (x_missing < x_board + half) && (y_missing >= y_board + half);
    int missingUR = (x_missing >= x_board + half) && (y_missing >= y_board + half);
    int missingLL = (x_missing < x_board + half) && (y_missing <  y_board + half);
    int missingLR = (x_missing >= x_board + half) && (y_missing <  y_board + half);

    /* place the centre tromino – orientation depends on the quadrant
       that already has the hole                                           */
    if (missingUL)               /* hole in UL → label LR */
    {
        setCell(cx+1, cy,   "LR");   /* lower‑right */
        setCell(cx,   cy,   "LR");   /* lower‑left  */
        setCell(cx+1, cy+1, "LR");   /* upper‑right */
    }
    else if (missingUR)          /* hole in UR → label LL */
    {
        setCell(cx,   cy,   "LL");
        setCell(cx,   cy+1, "LL");
        setCell(cx+1, cy,   "LL");
    }
    else if (missingLR)          /* hole in LR → label UL */
    {
        setCell(cx,   cy,   "UL");
        setCell(cx,   cy+1, "UL");
        setCell(cx+1, cy,   "UL");
    }
    else                         /* missingLL → label UR */
    {
        setCell(cx+1, cy,   "UR");
        setCell(cx,   cy,   "UR");
        setCell(cx+1, cy+1, "UR");
    }

    /* new “missing” squares for the three sub‑boards that did NOT contain
       the original missing cell                                            */
    int ul_mx = missingUL ? x_missing : cx;       int ul_my = missingUL ? y_missing : cy+1;
    int ur_mx = missingUR ? x_missing : cx+1;     int ur_my = missingUR ? y_missing : cy+1;
    int ll_mx = missingLL ? x_missing : cx;       int ll_my = missingLL ? y_missing : cy;
    int lr_mx = missingLR ? x_missing : cx+1;     int lr_my = missingLR ? y_missing : cy;

    /* recurse on the four quadrants */
    tromino(x_board,         y_board + half, ul_mx, ul_my, half);   /* UL */
    tromino(x_board + half,  y_board + half, ur_mx, ur_my, half);   /* UR */
    tromino(x_board,         y_board,        ll_mx, ll_my, half);   /* LL */
    tromino(x_board + half,  y_board,        lr_mx, lr_my, half);   /* LR */
}

/* --------------------------------------------------------------
   Print the board (top row first)
   -------------------------------------------------------------- */
void printBoard(int size)
{
    for (int y = size-1; y >= 0; --y) {
        for (int x = 0; x < size; ++x) {
            printf("%c%c", board[y][x], board[y][x+1]);
            if (x != size-1) printf("\t");
        }
        printf("\n");
    }
}

/* --------------------------------------------------------------
   Main driver
   -------------------------------------------------------------- */
int main(void)
{
    while (1)
    {
        int n;
        printf("Please enter size of board as a power of 2 (0 to quit): ");
        if (scanf("%d", &n) != 1) return 0;
        if (n == 0) break;

        if (!isPowerOfTwo(n))
        {
            printf("The board size should be a power of 2\n");
            continue;
        }

        int xm, ym;
        printf("Please enter coordinates of missing square (separate by a space): ");
        if (scanf("%d %d", &xm, &ym) != 2) return 0;

        if (xm < 0 || xm >= n || ym < 0 || ym >= n)
        {
            printf("Coordinates out of range, try again.\n");
            continue;
        }

        /* allocate global board (2 characters per cell) */
        board = malloc(n * sizeof(char*));
        for (int i = 0; i < n; ++i)
        {
            board[i] = malloc(2 * n * sizeof(char));   /* 2 chars per cell */
            for (int j = 0; j < 2*n; ++j) board[i][j] = '\0';
        }

        tromino(0, 0, xm, ym, n);
        printBoard(n);

        /* free the board */
        for (int i = 0; i < n; ++i) free(board[i]);
        free(board);
    }
    return 0;
}
```

--------------------------------------------------------------------

### 6.  Correctness Argument  

We prove by induction on `board_size` that after the call  

```
tromino(0,0,x_missing,y_missing,board_size)
```

* every cell of the board is filled with a two‑letter code,
* exactly one cell contains `"MS"` (the original missing square),
* the other cells are partitioned into disjoint L‑shaped trominoes, and
* each tromino is labelled correctly (`LR`, `LL`, `UL`, `UR`) according to the
  location of its missing corner.

---

**Base (`board_size = 2`).**  
The function writes `"MS"` to the given missing cell and fills the remaining
three cells with the unique label belonging to the opposite corner (the four
possibilities are handled explicitly).  By construction the three filled cells
form an L‑shape, are disjoint, and together with the missing cell cover the
whole 2 × 2 board.

**Inductive step.**  
Assume the statement holds for size `k = board_size/2`.  
For size `2k` the algorithm:

1. Determines the quadrant (UL, UR, LL, LR) that already contains the real
   missing cell.
2. Places **one** centre tromino covering the three centre squares that belong
   to the *other* three quadrants.  Its orientation label is exactly the label
   that corresponds to the quadrant left empty – therefore the centre tromino
   is correct.
3. For each quadrant it calls `tromino` recursively with size `k`.  
   *The quadrant that originally contained the missing cell* receives the
   original missing coordinates, so by the inductive hypothesis it is tiled
   correctly.  
   *Each of the other three quadrants* receives as its “missing” cell the
   centre square that was just covered by the centre tromino.  Again the
   inductive hypothesis guarantees a correct tiling of that sub‑board.

All four sub‑boards together cover the whole board, they are pairwise
disjoint, and exactly one cell (the original one) is labelled `"MS"`.  Hence
the statement holds for size `2k`.

By induction the algorithm is correct for every power‑of‑two board size.

--------------------------------------------------------------------

### 7.  Complexity Analysis  

The board contains `N = 2ⁿ·2ⁿ = 4ⁿ` cells.

*Each recursive call* works on a board of size `s × s` and performs **O(1)**
work (placing the centre tromino and a constant number of arithmetic
operations).  
The recursion creates four sub‑calls of size `s/2`.  

Therefore the recurrence for the running time `T(s)` is

```
T(s) = 4·T(s/2) + O(1) ,    T(2) = O(1)
```

Its solution is `T(s) = Θ(s²) = Θ(N)`.  
The algorithm uses a board of `N` cells → `Θ(N)` memory.

--------------------------------------------------------------------

**The program above follows exactly the specification, prints the board
in the required format (e.g. for size = 2, missing = (0,1) it prints)**  

```
MS  LR
LR  LR
```

and works for any power‑of‑two board size.

