**What’s wrong?**  

You are sorting the two groups (`incr_pos` and `incr_neg`) by the **increment value** (`incr`) :

```c
int compare(const void *a, const void *b)
{
    Station *first_station  = (Station *)a;
    Station *second_station = (Station *)b;
    return first_station->incr - second_station->incr;   // <-- sorts by incr
}
```

For a *positive* increment we have to visit the stations in **increasing order of the
minimal oxygen that is required to enter the station** (`min_req`).  

For a *negative* increment we have to be a little more careful: after we have
visited a station the oxygen level drops, therefore we want to do the “most
dangerous” stations **first**.  The classic greedy rule (the same one that is used
in the “Dragon‑and‑Knights” / “Project Planning with Gains and Losses” problems)
is:

* sort the negative‑increment stations by **decreasing** value of  

  `min_req + incr` (the oxygen that will remain **after** we have paid the loss).

The current comparator does none of the above, so the program can answer
incorrectly.

---

## Fixed program

Below is a compact, self‑contained version that follows the required ordering.
Only the two comparator functions have changed; the rest of the logic is kept
exactly as you wrote it.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Station {
    int min_req;   /* oxygen needed before entering */
    int incr;      /* change of oxygen after the station (may be negative) */
} Station;

/* -------------------------------------------------------------
   Comparator for the positive‑increment stations:
   sort by min_req   (ascending)
   ------------------------------------------------------------- */
int cmp_pos(const void *a, const void *b)
{
    const Station *s1 = (const Station *)a;
    const Station *s2 = (const Station *)b;
    return s1->min_req - s2->min_req;          /* ascending */
}

/* -------------------------------------------------------------
   Comparator for the negative‑increment stations:
   sort by (min_req + incr)   (descending)
   ------------------------------------------------------------- */
int cmp_neg(const void *a, const void *b)
{
    const Station *s1 = (const Station *)a;
    const Station *s2 = (const Station *)b;

    int v1 = s1->min_req + s1->incr;   /* oxygen left after this station */
    int v2 = s2->min_req + s2->incr;

    return v2 - v1;                   /* descending */
}

/* ------------------------------------------------------------- */
int main(void)
{
    int n, oxygen;
    if (scanf("%d %d", &n, &oxygen) != 2) return 0;

    /* temporary storage for the raw input */
    int *minreq = malloc(n * sizeof *minreq);
    int *incr   = malloc(n * sizeof *incr);

    for (int i = 0; i < n; ++i) scanf("%d", &minreq[i]);
    for (int i = 0; i < n; ++i) scanf("%d", &incr[i]);

    /* Two dynamic arrays that will hold only the really used stations */
    Station *pos = malloc(n * sizeof *pos);   /* incr >= 0 */
    Station *neg = malloc(n * sizeof *neg);   /* incr <  0 */
    int pos_cnt = 0, neg_cnt = 0;

    for (int i = 0; i < n; ++i) {
        if (incr[i] >= 0) {
            pos[pos_cnt].min_req = minreq[i];
            pos[pos_cnt].incr    = incr[i];
            ++pos_cnt;
        } else {
            neg[neg_cnt].min_req = minreq[i];
            neg[neg_cnt].incr    = incr[i];
            ++neg_cnt;
        }
    }

    /* Apply the two greedy orders */
    qsort(pos, pos_cnt, sizeof *pos, cmp_pos);
    qsort(neg, neg_cnt, sizeof *neg, cmp_neg);

    /* 1️⃣  Positive‑increment stations (ascending min_req) */
    for (int i = 0; i < pos_cnt; ++i) {
        if (oxygen < pos[i].min_req) {
            printf("NO\n");
            goto finish;
        }
        oxygen += pos[i].incr;               /* safe – incr is non‑negative */
    }

    /* 2️⃣  Negative‑increment stations (descending min_req+incr) */
    for (int i = 0; i < neg_cnt; ++i) {
        if (oxygen < neg[i].min_req) {
            printf("NO\n");
            goto finish;
        }
        oxygen += neg[i].incr;               /* incr is negative */
        if (oxygen < 0) {                    /* oxygen may become negative */
            printf("NO\n");
            goto finish;
        }
    }

    printf("YES\n");

finish:
    free(minreq);
    free(incr);
    free(pos);
    free(neg);
    return 0;
}
```

### Why this works

| Group                | Ordering rule                              | Reason                                                                                               |
|----------------------|--------------------------------------------|------------------------------------------------------------------------------------------------------|
| `incr ≥ 0`           | **Increasing** `min_req`                   | You never lose oxygen, so you only have to guarantee that the current level is at least the required entry level. Doing the cheapest (smallest requirement) stations first can never hurt. |
| `incr < 0`           | **Decreasing** `(min_req + incr)`          | After a negative‑increment station you will have `oxygen – |incr|`. To stay safe you want the *largest* remaining level *as early as possible*. Sorting by the *post‑station* level (i.e. `min_req + incr`) descending ensures that the “most dangerous” stations are taken first, which minimises the maximal oxygen needed before the sequence starts. |

The algorithm is exactly the standard greedy solution for this class of
problems and runs in `O(n log n)` because of the two sorts.

---

