**Краткое описание задачи**  
Нужно написать программу‑просмотрщик, которая читает файл‑исходник на C и выводит его на экран, выделяя (например, цветом) все шестнадцатеричные константы вида  

```
0x1A3F   0XdeadbeefU   0xFFul   …
```

Для «выделения» будем использовать ANSI‑коды терминала (красный цвет).  
В программе реализован простой разбор строки, который умеет
* распознавать блоки комментариев `/* … */`,
* строковые литералы `"…"`,
* символьные литералы `'…'`,
* однострочные комментарии `// …`.

Внутри этих областей константы **не** выделяются – так выглядит более «чистый» вывод.

---

## Полный исходный код (C)

```c
/*
 * hex_highlight.c
 *
 * Выводит содержимое файла С‑кода, выделяя (красным) все
 * шестнадцатеричные константы (0x…[uUlL…]).
 *
 * Компиляция (пример):
 *     gcc -Wall -Wextra -std=c11 -o hex_highlight hex_highlight.c
 *
 * Запуск:
 *     ./hex_highlight source.c
 *
 * Требования: терминал, понимающий ANSI‑escape‑последовательности.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define LINE_BUF 4096               /* Максимальная длина строки */
#define COLOR_HEX "\033[31m"        /* Красный */
#define COLOR_RESET "\033[0m"       /* Сброс цветов */

/* -------------------------------------------------------------
 * Функция печатает одну строку, выделяя в ней шестнадцатеричные
 * константы.  Параметр inBlockComment – состояние «внутри
 * многократного комментария*/ /* … */, которое может
 * продолжаться сквозь несколько строк.
 * ------------------------------------------------------------- */
static void print_line_highlighted(char *line,
                                   int *inBlockComment)
{
    size_t i = 0, len = strlen(line);
    int inString = 0;      /* внутри "...", учитываем экранирование \" */
    int inChar   = 0;      /* внутри '...' */
    while (i < len) {
        /* -------------------------------------------------
         * 1) Обрабатываем многократный комментарий  /*…*/
         * ------------------------------------------------- */
        if (*inBlockComment) {
            if (line[i] == '*' && line[i + 1] == '/') {
                *inBlockComment = 0;
                putchar('*');
                putchar('/');
                i += 2;
                continue;
            }
            putchar(line[i++]);
            continue;
        }

        /* -------------------------------------------------
         * 2) Попадаем в начало нового многократного
         *    комментария
         * ------------------------------------------------- */
        if (!inString && !inChar && line[i] == '/' && line[i + 1] == '*') {
            *inBlockComment = 1;
            putchar('/');
            putchar('*');
            i += 2;
            continue;
        }

        /* -------------------------------------------------
         * 3) Однострочный комментарий // – до конца строки
         *    ничего больше не анализируем
         * ------------------------------------------------- */
        if (!inString && !inChar && line[i] == '/' && line[i + 1] == '/') {
            /* Всё, что осталось – обычный вывод */
            fputs(line + i, stdout);
            return;
        }

        /* -------------------------------------------------
         * 4) Строковый литерал
         * ------------------------------------------------- */
        if (!inChar && line[i] == '"' && !inString) {
            inString = 1;
            putchar('"');
            ++i;
            continue;
        }
        if (inString && line[i] == '"' && line[i - 1] != '\\') {
            inString = 0;
            putchar('"');
            ++i;
            continue;
        }

        /* -------------------------------------------------
         * 5) Символьный литерал
         * ------------------------------------------------- */
        if (!inString && line[i] == '\'' && !inChar) {
            inChar = 1;
            putchar('\'');
            ++i;
            continue;
        }
        if (inChar && line[i] == '\'' && line[i - 1] != '\\') {
            inChar = 0;
            putchar('\'');
            ++i;
            continue;
        }

        /* -------------------------------------------------
         * 6) Если мы НЕ внутри строки/символа/комментария,
         *    ищем шестнадцатеричный литерал.
         * ------------------------------------------------- */
        if (!inString && !inChar &&
            line[i] == '0' && (line[i + 1] == 'x' || line[i + 1] == 'X')) {

            size_t j = i + 2;                  /* после 0x */

            /* Должны быть хотя бы один шестнадцатеричный символ */
            if (!isxdigit((unsigned char)line[j])) {
                putchar(line[i]);      /* обычный «0» */
                ++i;
                continue;
            }

            while (isxdigit((unsigned char)line[j])) ++j;

            /* Суффиксы: u/U/l/L (можно их несколько) */
            while (line[j] == 'u' || line[j] == 'U' ||
                   line[j] == 'l' || line[j] == 'L')
                ++j;

            /* Выводим найденный литерал «красным» */
            printf(COLOR_HEX);
            fwrite(line + i, 1, j - i, stdout);
            printf(COLOR_RESET);

            i = j;               /* продолжаем после литерала */
            continue;
        }

        /* -------------------------------------------------
         * 7) Обычный символ
         * ------------------------------------------------- */
        putchar(line[i]);
        ++i;
    }
}

/* -------------------------------------------------------------
 * main()
 * ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <C‑source‑file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    char line[LINE_BUF];
    int inBlockComment = 0;          /* состояние между строками */

    while (fgets(line, sizeof line, fp)) {
        print_line_highlighted(line, &inBlockComment);
    }

    fclose(fp);
    return EXIT_SUCCESS;
}
```

---

## Как это работает

1. **Чтение файла построчно** – `fgets` помещает строку (включая завершающий `\n`) в буфер `line`.

2. **Контекстный анализ** – переменные `inBlockComment`, `inString` и `inChar` хранят текущий контекст.  
   * `/* … */` может занимать несколько строк, поэтому состояние хранится между вызовами `print_line_highlighted`.  
   * Однострочный комментарий `//` «завершается» в конце текущей строки – после его обнаружения оставшаяся часть строки просто выводится без дальнейшего анализа.  
   * Строковые и символьные литералы учитывают экранирование (`\"` и `\'`).

3. **Поиск шестнадцатеричного литерала**  
   * Паттерн начинается с `0x` или `0X`.  
   * После этого должно идти хотя бы одно шестнадцатеричное число (`0‑9`, `a‑f`, `A‑F`).  
   * Затем допускаются суффиксы `u`, `U`, `l`, `L` (в любой комбинации).  

4. **Выделение** – найденный кусок выводится между ANSI‑последовательностями `\033[31m` (красный) и `\033[0m` (сброс атрибутов).

5. **Сборка и запуск**  

```sh
$ gcc -Wall -Wextra -std=c11 -o hex_highlight hex_highlight.c
$ ./hex_highlight my_program.c
```

В терминале, поддерживающем ANSI‑коды, все шестнадцатеричные константы будут отображаться ярко‑красным цветом, остальные части кода – обычным цветом.  

---

### Что можно улучшить (по желанию)

| Возможность                              | Как реализовать                                   |
|------------------------------------------|---------------------------------------------------|
| Поддержка более сложных суффиксов (например, `ULL`) | Расширить проверку суффиксов, учитывая их порядок. |
| Выделение другими цветами (например, синим) | Поменять `COLOR_HEX` на другой ANSI‑код.          |
| Выделять только в «реальном» коде (без комментариев и строк) – уже реализовано. |
| Обработка Unicode‑символов в строках (в современных кодах) | Перейти к `wchar_t`‑подходу или использовать библиотеки, работающие с UTF‑8. |
| Показать номер строки рядом с выводом | Позиционировать номер в начале каждой строки.   |

