**Overview**

The program consists of two processes that communicate only through **System‑V IPC**:

| Process | What it does |
|---------|--------------|
| **server** | 1. Creates a *command* shared‑memory segment (`shm_cmd`).<br>2. Creates a semaphore set (`sem`).<br>3. Waits for a client to place a command in `shm_cmd`.<br>4. When a command arrives it spawns a POSIX thread that handles the request.<br>5. For a **read** request the thread creates a *data* shared‑memory segment (`shm_data`), copies the file content there, and writes the key of that segment back to the original `shm_cmd` so that the client can attach to it.<br>6. For a **write** request the thread simply writes the supplied data to the target file. |
| **client** | 1. Reads a command from the terminal (`read <file>` or `write <file> <data>`).<br>2. Takes the *mutex* semaphore, writes the whole command string to `shm_cmd`, releases the *command‑ready* semaphore and unlocks the mutex.<br>3. If the command is **read**, it blocks on the *response‑ready* semaphore, reads the key of the data segment that the server just created, attaches to it, prints the file contents and finally removes the data segment.<br>4. If the command is **write** it simply exits after the command has been handed over to the server. |

Only three semaphores are required:

| sem‑id | Meaning | Initial value |
|--------|---------|----------------|
| 0 – **mutex**        | protects concurrent access to the command segment | 1 |
| 1 – **cmd_ready**    | posted by a client when a command is available | 0 |
| 2 – **resp_ready**   | posted by the server after the response key is written (read only) | 0 |

All error handling is kept simple – the program aborts with `perror()` in case a system call fails.

---

## 1️⃣  server.c

```c
/* -------------------------------------------------------------
   server.c – command dispatcher using shared memory & semaphores
   ----------------------------------------------------------- */
#define _GNU_SOURCE            /* for asprintf() */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

/* ---------- constants ------------------------------------------------- */
#define CMD_SHM_KEY   0x1234            /* key for command shared memory   */
#define SEM_KEY       0x5678            /* key for semaphore set           */
#define SHM_SIZE      4096              /* big enough for command + data   */
#define MAX_CMD_LEN   1024

/* ---------- semaphore helpers (System‑V) ------------------------------ */
union semun {
    int              val;    /* value for SETVAL */
    struct semid_ds *buf;    /* buffer for IPC_STAT, IPC_SET */
    unsigned short  *array;  /* array for GETALL, SETALL */
    struct seminfo  *__buf;  /* buffer for IPC_INFO (Linux) */
};

/* P (wait) operation */
static void sem_op(int semid, int semnum, int delta)
{
    struct sembuf sb = { .sem_num = semnum,
                         .sem_op  = delta,
                         .sem_flg = 0 };
    if (semop(semid, &sb, 1) == -1) {
        perror("semop");
        exit(EXIT_FAILURE);
    }
}

/* P (decrement) */
static void sem_wait(int semid, int semnum) { sem_op(semid, semnum, -1); }
/* V (increment) */
static void sem_post(int semid, int semnum) { sem_op(semid, semnum, +1); }

/* ---------- data structures ------------------------------------------- */
typedef struct {
    char buf[SHM_SIZE];        /* command string written by client */
} cmd_shm_t;

/* Thread argument – contains the command string (already copied) */
typedef struct {
    char cmd[MAX_CMD_LEN];
    int  semid;
    int  shmid_cmd;            /* id of the command shm – needed for response */
} tharg_t;

/* ---------- helper functions ------------------------------------------ */

/* Trim leading/trailing white space (in‑place) */
static char *trim(char *s)
{
    while (isspace((unsigned char)*s)) s++;
    if (*s == 0) return s;
    char *end = s + strlen(s) - 1;
    while (end > s && isspace((unsigned char)*end)) *end-- = '\0';
    return s;
}

/* Write a whole file into a newly created shared memory segment.
   Returns the key (as integer) of the new segment. */
static int create_data_shm_and_fill(const char *filename)
{
    /* Open and read the file */
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open (read file)");
        return -1;
    }
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return -1;
    }

    /* Create a new shared memory segment – key based on pid+filename */
    key_t key = ftok(filename, getpid() & 0xff);
    if (key == -1) {
        perror("ftok");
        close(fd);
        return -1;
    }

    int shmid = shmget(key, st.st_size, IPC_CREAT | 0600);
    if (shmid == -1) {
        perror("shmget (data)");
        close(fd);
        return -1;
    }

    /* Attach, copy file, detach */
    void *addr = shmat(shmid, NULL, 0);
    if (addr == (void *)-1) {
        perror("shmat (data)");
        close(fd);
        return -1;
    }
    ssize_t n = read(fd, addr, st.st_size);
    if (n != st.st_size) {
        perror("read (file)");
        shmdt(addr);
        close(fd);
        return -1;
    }
    shmdt(addr);
    close(fd);
    return key;                     /* this key will be sent back to client */
}

