    char *saveptr;
    char *tok = strtok_r(cmd, " ", &saveptr);
    if (!tok) goto malformed;

    if (strcmp(tok, "read") == 0) {
        char *filename = strtok_r(NULL, " ", &saveptr);
        if (!filename) goto malformed;

        /* ---- read request --------------------------------------- */
        int data_key = create_data_shm_and_fill(filename);
        if (data_key == -1) {
            /* on error, write an empty key (0) – client will treat it as failure */
            data_key = 0;
        }

        /* write the key back to the command shared memory   */
        snprintf(shm_cmd->buf, SHM_SIZE, "%d", data_key);
        /* signal the client that the response is ready       */
        sem_post(semid, 2);        /* resp_ready */

    } else if (strcmp(tok, "write") == 0) {
        char *filename = strtok_r(NULL, " ", &saveptr);
        char *data     = strtok_r(NULL, "", &saveptr);   /* rest of line */
        if (!filename || !data) goto malformed;

        /* ---- write request -------------------------------------- */
        int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd == -1) {
            perror("open (write file)");
            /* we still have to wake the client – it does not wait for a response */
            goto done;
        }
        ssize_t w = write(fd, data, strlen(data));
        if (w != (ssize_t)strlen(data))
            perror("write (file)");
        close(fd);
        /* No response needed for write */
    } else {
        goto malformed;
    }

done:
    shmdt(shm_cmd);
    free(t);
    return NULL;

malformed:
    fprintf(stderr, "Server: malformed command \"%s\"\n", cmd);
    /* write a 0 key so the client knows something went wrong */
    snprintf(shm_cmd->buf, SHM_SIZE, "0");
    sem_post(semid, 2);
    goto done;
}

/* ---------- main ------------------------------------------------------ */
int main(void)
{
    /* ---- create / attach the command shared memory ----------------- */
    int shmid_cmd = shmget(CMD_SHM_KEY, SHM_SIZE, IPC_CREAT | 0600);
    if (shmid_cmd == -1) {
        perror("shmget (command)");
        exit(EXIT_FAILURE);
    }
    cmd_shm_t *shm_cmd = (cmd_shm_t *)shmat(shmid_cmd, NULL, 0);
    if (shm_cmd == (void *)-1) {
        perror("shmat (command)");
        exit(EXIT_FAILURE);
    }
    memset(shm_cmd->buf, 0, SHM_SIZE);   /* make sure it is clean */

    /* ---- create semaphore set -------------------------------------- */
    int semid = semget(SEM_KEY, 3, IPC_CREAT | 0600);
    if (semid == -1) {
        perror("semget");
        exit(EXIT_FAILURE);
    }
    union semun arg;
    unsigned short vals[3] = {1, 0, 0};          /* mutex=1, cmd_ready=0, resp_ready=0 */
    arg.array = vals;
    if (semctl(semid, 0, SETALL, arg) == -1) {
        perror("semctl SETALL");
        exit(EXIT_FAILURE);
    }

    printf("SERVER started – waiting for commands …\n");

    /* ---------- main loop : wait for a command, then spawn a thread ---------- */
    while (1) {
        /* wait until a client signals that a command is ready */
        sem_wait(semid, 1);        /* cmd_ready */

        /* lock the command buffer, copy the command and clear the buffer   */
        sem_wait(semid, 0);        /* mutex */
        char cmd_copy[MAX_CMD_LEN];
        strncpy(cmd_copy, shm_cmd->buf, MAX_CMD_LEN - 1);
        cmd_copy[MAX_CMD_LEN - 1] = '\0';
        memset(shm_cmd->buf, 0, SHM_SIZE);
        sem_post(semid, 0);        /* unlock mutex */

        /* trim newline / trailing spaces – client may have pressed ENTER */
        char *c = trim(cmd_copy);
        if (strlen(c) == 0)       /* empty line – just ignore */
            continue;

        /* Spawn a thread to handle this request */
        pthread_t tid;
        tharg_t *targ = malloc(sizeof(tharg_t));
        if (!targ) {
            perror("malloc");
            continue;
        }
        strncpy(targ->cmd, c, MAX_CMD_LEN - 1);
        targ->cmd[MAX_CMD_LEN - 1] = '\0';
        targ->semid = semid;
        targ->shmid_cmd = shmid_cmd;

        if (pthread_create(&tid, NULL, handle_cmd, targ) != 0) {
            perror("pthread_create");
            free(targ);
            continue;
        }
        pthread_detach(tid);      /* we do not need to join */
    }

    /* never reached – clean‑up code (just for reference) */
    shmdt(shm_cmd);
    shmctl(shmid_cmd, IPC_RMID, NULL);
    semctl(semid, 0, IPC_RMID);
    return 0;
}
```

### What the server does

1. **Creates** a single command shared‑memory segment (`CMD_SHM_KEY`) that will hold the whole command string.  
2. **Creates** a semaphore set (`SEM_KEY`) with three semaphores:  
   * `0` – **mutex** – guarantees exclusive write access to the command buffer.  
   * `1` – **cmd_ready** – client posts it when the command is ready.  
   * `2` – **resp_ready** – server posts it after it has written the response (the key of a data segment).  
3. Enters an **infinite loop** where it blocks on `cmd_ready`.  
4. When a command arrives it **copies** it, **clears** the buffer and **spawns** a detached POSIX thread (`handle_cmd`).  
5. The thread parses the command.  
   * For `read <file>` it creates a **new** shared‑memory segment that holds *exactly* the file contents, writes that segment’s **key** (as a decimal string) back into the original command buffer, then posts `resp_ready`.  
   * For `write <file> <data>` it opens/creates the file and writes the supplied data. No response is required.  

The server is completely **asynchronous** – simultaneous client requests are handled by independent threads.

---

## 2️⃣  client.c

```c
/* -------------------------------------------------------------
   client.c – issue a file command to the server
   ----------------------------------------------------------- */
#define _GNU_SOURCE            /* for asprintf() */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ctype.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <errno.h>

/* ---------- constants (must match server) --------------------- */
#define CMD_SHM_KEY   0x1234
#define SEM_KEY       0x5678
#define SHM_SIZE      4096
#define MAX_CMD_LEN   1024

/* ---------- semaphore helpers (same as server) ---------------- */
union semun {
    int              val;
    struct semid_ds *buf;
    unsigned short  *array;
    struct seminfo  *__buf;
};

static void sem_op(int semid, int semnum, int delta)
{
    struct sembuf sb = { .sem_num = semnum,
                         .sem_op  = delta,
                         .sem_flg = 0 };
    if (semop(semid, &sb, 1) == -1) {
        perror("semop");
        exit(EXIT_FAILURE);
    }
}
static void sem_wait(int semid, int semnum) { sem_op(semid, semnum, -1); }
static void sem_post(int semid, int semnum) { sem_op(semid, semnum, +1); }

/* ---------- trim helper ------------------------------------------ */
static char *trim(char *s)
{
    while (isspace((unsigned char)*s)) s++;
    if (*s == 0) return s;
    char *end = s + strlen(s) - 1;
    while (end > s && isspace((unsigned char)*end)) *end-- = '\0';
    return s;
}

/* ---------- validate the command entered by the user ----------- */
static int build_command_string(char *dest, const char *line)
{
    char buf[MAX_CMD_LEN];
    strncpy(buf, line, MAX_CMD_LEN - 1);
    buf[MAX_CMD_LEN - 1] = '\0';
    char *p = trim(buf);
    if (strlen(p) == 0) return -1;

    /* tokenise just to be able to detect malformed input */
    char *saveptr;
    char *tok = strtok_r(p, " ", &saveptr);
    if (!tok) return -1;

    if (strcmp(tok, "read") == 0) {
        char *fname = strtok_r(NULL, " ", &saveptr);
        if (!fname) return -1;
        snprintf(dest, MAX_CMD_LEN, "read %s", fname);
        return 0;
    } else if (strcmp(tok, "write") == 0) {
        char *fname = strtok_r(NULL, " ", &saveptr);
        char *data  = strtok_r(NULL, "", &saveptr);   /* rest of line */
        if (!fname || !data) return -1;
        snprintf(dest, MAX_CMD_LEN, "write %s %s", fname, data);
        return 0;
    } else {
        return -1;
    }
}

/* ---------- main ------------------------------------------------ */
int main(void)
{
    char line[2048];
    printf("Enter command (read <file> | write <file> <data>)\n> ");
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Failed to read line\n");
        return EXIT_FAILURE;
    }

    char cmd[MAX_CMD_LEN];
    if (build_command_string(cmd, line) != 0) {
        fprintf(stderr, "Invalid command format.\n");
        return EXIT_FAILURE;
    }

    /* ---- attach to server's shared memory ------------------------ */
    int shmid = shmget(CMD_SHM_KEY, SHM_SIZE, 0600);
    if (shmid == -1) {
        perror("shmget (command)");
        return EXIT_FAILURE;
    }
    char *shm = (char *)shmat(shmid, NULL, 0);
    if (shm == (void *)-1) {
        perror("shmat");
        return EXIT_FAILURE;
    }

    /* ---- get semaphore set --------------------------------------- */
    int semid = semget(SEM_KEY, 3, 0600);
    if (semid == -1) {
        perror("semget");
        shmdt(shm);
        return EXIT_FAILURE;
    }

    /* ---- write command into shared memory (protected by mutex) -- */
    sem_wait(semid, 0);                 /* mutex */
    strncpy(shm, cmd, SHM_SIZE - 1);
    shm[SHM_SIZE - 1] = '\0';
    sem_post(semid, 0);                 /* unlock mutex */

    /* ---- notify the server --------------------------------------- */
    sem_post(semid, 1);                 /* cmd_ready */

    /* ---- if READ : wait for the response (key of data segment) -- */
    if (strncmp(cmd, "read", 4) == 0) {
        /* block until server posts resp_ready */
        sem_wait(semid, 2);             /* resp_ready */

        /* the server wrote a decimal key (or 0 on error) */
        int data_key = 0;
        if (sscanf(shm, "%d", &data_key) != 1) data_key = 0;

        if (data_key == 0) {
            fprintf(stderr, "Server reported error while reading the file.\n");
            shmdt(shm);
            return EXIT_FAILURE;
        }

        /* attach to the data segment created by the server */
        int data_shmid = shmget(data_key, SHM_SIZE, 0600);
        if (data_shmid == -1) {
            perror("shmget (data)");
            shmdt(shm);
            return EXIT_FAILURE;
        }
        char *data = (char *)shmat(data_shmid, NULL, 0);
        if (data == (void *)-1) {
            perror("shmat (data)");
            shmdt(shm);
            return EXIT_FAILURE;
        }

        /* print the file content */
        printf("\n--- file content start ---\n%s\n--- file content end ---\n",
               data);

        /* clean up the temporary segment */
        shmdt(data);
        shmctl(data_shmid, IPC_RMID, NULL);
    }

    /* ------------------------------------------------------------ */
    shmdt(shm);
    return EXIT_SUCCESS;
}
```

### What the client does

1. **Reads** a line from `stdin`.  
2. **Parses** it and checks that it matches one of the two allowed formats.  
3. **Attaches** to the command shared‑memory segment (`CMD_SHM_KEY`) that the server created.  
4. **Locks** the *mutex* semaphore, copies the command string into the segment, unlocks the mutex.  
5. **Posts** the *cmd_ready* semaphore – this wakes up the server.  
6. If the command is a **read**:  
   * Waits on **resp_ready**.  
   * The server writes the *key* of a newly created data segment (or `0` on error).  
   * The client attaches to that data segment, prints its contents and finally removes the segment (`IPC_RMID`).  
7. If the command is a **write** there is nothing to wait for – the client simply exits after it has handed the command to the server.  

All synchronization is performed with the same set of semaphores that the server created, thus both processes see a consistent view of the shared memory.

---

## How to compile & run

```bash
gcc -Wall -Wextra -pthread -o server server.c
gcc -Wall -Wextra -o client client.c
```

Run the server **first** (it will stay alive waiting for commands):

```bash
$ ./server
SERVER started – waiting for commands …
```

In another terminal, fire a client:

```bash
$ ./client
Enter command (read <file> | write <file> <data>)
> read /etc/hostname

--- file content start ---
my-hostname
--- file content end ---
```

Or a write command:

```bash
$ ./client
Enter command (read <file> | write <file> <data>)
> write myfile.txt Hello, world!
$ cat myfile.txt
Hello, world!
```

Multiple clients can be started simultaneously; each request is processed in its own server thread, and the semaphores guarantee that the command buffer is never corrupted.

--- 

### Remarks & possible extensions

* **Security** – the keys are generated with `ftok()` that uses the pathname of the file and the client’s PID. For a production system you would want to protect the shared‑memory identifiers (e.g. using a permission check or a dedicated “auth” handshake).  
* **Error reporting** – at the moment the server writes a `"0"` key on errors. A richer protocol (e.g. a small status word) could be added.  
* **Maximum file size** – we limited the data segment to `SHM_SIZE` (4 KB). If you need to transfer larger files you can either enlarge `SHM_SIZE` or create a **chain** of segments.  
* **Cleanup** – the server never removes the command shared memory or the semaphore set while it runs. If you abort it with `Ctrl‑C` you may want a signal handler that calls `shmctl(..., IPC_RMID, ...)` and `semctl(..., IPC_RMID)`.

