#define NOTE_TIME   200   // 每个音符的时长（单位：10ms），这里相当于 200×10ms = 2s
#define MAX_NOTE_NUM    32 // 最多可以保存的音符数

/* 状态机 */
typedef enum { IDLE, RECORD, PLAY, PAUSE } work_state_t;

/* 用来保存音符的结构（下标+时长） */
typedef struct {
    uint8_t idx;   // freq[] 中的下标，0 → 休止（静音），1..n → 真音符
    uint8_t len;   // 音符时长（以 10ms 为单位），这里固定为 NOTE_TIME
} note_t;
