## 3. 关键函数

### 3.1 产生单个音符（统一入口）

```c
/*--------------------------------------------------------------
  根据 freq[] 的下标 (idx) 播放一个音符，时长由 len 决定
  idx==0 → 休止符（只延时，不产生方波）
  --------------------------------------------------------------*/
static void play_one_note(uint8_t idx, uint8_t len)
{
    unsigned int val;
    if (idx == 0) {                     // 休止符
        song_playing = 0;
        Delay(len);                     // 只延时
        return;
    }

    /* 计算定时器 reload 值（与原来的代码相同） */
    val = Clk / freq[idx];
    val = 0xFFFF - val;
    val_H = (val >> 8) & 0xFF;
    val_L =  val       & 0xFF;
    TH0 = val_H; TL0 = val_L;          // 立即装入，ISR 会每次重新装

    song_playing = 1;                  // 开始产生方波
    Delay(len);                        // 持续 len×10ms
    song_playing = 0;                  // 停止方波（防止 ISR 继续翻转）
}
```

### 3.2 读取键盘，返回 **字符**（已经写好的 `matrix_keypad_scan`）  
我们在 `main` 中直接调用它，得到 `'1'..'9','0','A'…'D','*','#'`。

### 3.3 把字符映射为 `freq[]` 的下标

```c
/*--------------------------------------------------------------
  根据键盘字符返回 freq[] 的下标（0 表示休止符）
  我们把键盘分成四组（C 大调）：
  1 2 3 4 5 6 7 8 9 0 * # A B C D
  只演示 8 个音符 + 休止符，其他键可自行扩展
  --------------------------------------------------------------*/
static uint8_t key_to_note_idx(char k)
{
    switch (k) {
        case '1': return 1;   // C  262Hz
        case '2': return 2;   // D  294Hz
        case '3': return 3;   // E  330Hz
        case '4': return 4;   // F  349Hz
        case '5': return 5;   // G  392Hz
        case '6': return 6;   // A  440Hz
        case '7': return 7;   // B  494Hz
        case '8': return 8;   // C' 523Hz
        case '9': return 10;  // D' 587Hz
        case '0': return 11;  // E' 659Hz
        case '*': return 12;  // F' 698Hz
        case '#': return 13;  // G' 784Hz
        case 'A': case 'B': case 'C': case 'D':
            /* 这四个键是功能键，返回 0，后面会被单独处理 */
            return 0;
        default: return 0;    // 其余键统一视为休止符
    }
}
```

### 3.4 录音（把弹奏的音符保存到 `music_buf`）

```c
/*--------------------------------------------------------------
  把弹奏的音符保存进缓冲区（如果还有空间）
  --------------------------------------------------------------*/
static void record_note(uint8_t idx)
{
    if (music_len >= MAX_NOTE_NUM) return;      // 缓冲已满，直接丢弃

    music_buf[music_len].idx = idx;             // 保存下标
    music_buf[music_len].len = NOTE_TIME;       // 固定时长
    music_len++;
}
```

### 3.5 回放（顺序播放缓冲区中的音符）

```c
/*--------------------------------------------------------------
  回放函数 —— 在 PLAY 状态下被主循环周期性调用
  --------------------------------------------------------------*/
static void playback(void)
{
    if (play_pos >= music_len) {                 // 已经播放完毕 → 循环或停止
        play_pos = 0;            // 循环播放（如果不想循环，把这里改成 return;）
        return;
    }

    play_one_note(music_buf[play_pos].idx,
                  music_buf[play_pos].len);
    play_pos++;
}
```

### 3.6 状态切换（键盘功能键）

```c
/*--------------------------------------------------------------
  处理功能键（A/B/C/D）对应的状态切换
  --------------------------------------------------------------*/
static void process_ctrl_key(char k)
{
    switch (k) {
        case 'A':               // 录音 开/关
            if (cur_state != RECORD) {
                cur_state = RECORD;
                music_len = 0;   // 开始新录音，清空旧记录
                play_pos  = 0;
            } else {
                cur_state = IDLE;    // 结束录音
            }
            break;

        case 'B':               // 播放 开/关
            if (cur_state != PLAY) {
                if (music_len == 0) break;   // 没有录音直接返回
                cur_state = PLAY;
                play_pos = 0;                // 从头开始
            } else {
                cur_state = IDLE;            // 停止播放
            }
            break;

        case 'C':               // 暂停 / 恢复（仅在 PLAY 时有效）
            if (cur_state == PLAY) {
                cur_state = PAUSE;
                song_playing = 0;            // 立马关闭方波
            } else if (cur_state == PAUSE) {
                cur_state = PLAY;            // 恢复
            }
            break;

        case 'D':               // 退出（停止并清空缓冲区）
            cur_state = IDLE;
            song_playing = 0;
            music_len = 0;
            play_pos  = 0;
            break;

        default: break;
    }
}
```

