## 2. Исходный код `calc.c`

```c
/*  calc.c – сложный калькулятор
 *  Поддержка: + - * / % ^, унарные +/-, скобки,
 *  функции: sin, cos, tan, log, exp, sqrt
 *  Автор: ChatGPT, 2024
 */

#define _GNU_SOURCE   // для strcasecmp
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <errno.h>

/* ---------- Токены ---------- */
typedef enum {
    TOK_NUMBER,
    TOK_OPERATOR,
    TOK_FUNC,
    TOK_LPAREN,
    TOK_RPAREN,
    TOK_END
} TokenType;

typedef struct Token {
    TokenType type;
    double    value;         // для чисел
    char      op;            // + - * / % ^ и т.п.
    const char *func;        // имя функции (sin, cos, …)
    struct Token *next;
} Token;

/* ---------- Стек для токенов (используется в алгоритме шунтинг‑ярд) ---------- */
typedef struct TokStack {
    Token *top;
} TokStack;

static void push_tok(TokStack *s, Token *t) {
    t->next = s->top;
    s->top = t;
}
static Token *pop_tok(TokStack *s) {
    if (!s->top) return NULL;
    Token *t = s->top;
    s->top = t->next;
    return t;
}
static Token *peek_tok(const TokStack *s) {
    return s->top;
}

/* ---------- Стек для чисел (вычисление RPN) ---------- */
typedef struct NumStack {
    double *data;
    size_t  size;
    size_t  capa;
} NumStack;

static void ns_init(NumStack *ns) {
    ns->capa = 64;
    ns->size = 0;
    ns->data = malloc(ns->capa * sizeof(double));
}
static void ns_push(NumStack *ns, double v) {
    if (ns->size == ns->capa) {
        ns->capa *= 2;
        ns->data = realloc(ns->data, ns->capa * sizeof(double));
    }
    ns->data[ns->size++] = v;
}
static double ns_pop(NumStack *ns) {
    if (ns->size == 0) {
        fprintf(stderr, "Ошибка: стек пуст\n");
        exit(EXIT_FAILURE);
    }
    return ns->data[--ns->size];
}
static void ns_free(NumStack *ns) {
    free(ns->data);
}

/* ---------- Приоритеты и ассоциативность операторов ---------- */
static int precedence(char op) {
    switch (op) {
        case '^': return 4;
        case '*': case '/': case '%': return 3;
        case '+': case '-': return 2;
        default: return 0;
    }
}
static int is_right_associative(char op) {
    return op == '^';
}

/* ---------- Распознавание функций ---------- */
static const char *functions[] = {
    "sin", "cos", "tan", "log", "exp", "sqrt", NULL
};

/* ---------- Лексер (разбор строки на токены) ---------- */
static Token *new_token(TokenType t) {
    Token *tok = calloc(1, sizeof(Token));
    tok->type = t;
    return tok;
}

/* Пропускает пробелы */
static const char *skip_spaces(const char *p) {
    while (isspace((unsigned char)*p)) ++p;
    return p;
}

/* Считывает число (поддержка экспоненциальной записи) */
static Token *read_number(const char **sp) {
    const char *p = *sp;
    char *end;
    errno = 0;
    double val = strtod(p, &end);
    if (p == end) {
        return NULL; // не число
    }
    if (errno == ERANGE) {
        fprintf(stderr, "Переполнение/недополняемость числа %.*s\n",
                (int)(end - p), p);
        exit(EXIT_FAILURE);
    }
    *sp = end;
    Token *t = new_token(TOK_NUMBER);
    t->value = val;
    return t;
}

/* Считывает идентификатор (функцию) */
static Token *read_identifier(const char **sp) {
    const char *p = *sp;
    if (!isalpha((unsigned char)*p)) return NULL;
    const char *start = p;
    while (isalnum((unsigned char)*p) || *p == '_') ++p;
    size_t len = p - start;
    char *name = strndup(start, len);
    for (const char **f = functions; *f; ++f) {
        if (strcasecmp(name, *f) == 0) {
            Token *t = new_token(TOK_FUNC);
            t->func = *f;
            free(name);
            *sp = p;
            return t;
        }
    }
    free(name);
    return NULL; // неизвестный идентификатор
}

/* Главный лексер */
static Token *tokenize(const char *expr) {
    const char *p = expr;
    Token head = {0}, *cur = &head;   // фиктивный начало списка
    Token *last_tok = NULL;          // нужен для определения унарного +/- 

    while (1) {
        p = skip_spaces(p);
        if (*p == '\0') {
            cur->next = new_token(TOK_END);
            break;
        }

        Token *t = NULL;
        if (isdigit((unsigned char)*p) || *p == '.') {
            t = read_number(&p);
        } else if (isalpha((unsigned char)*p)) {
            t = read_identifier(&p);
            if (!t) {
                fprintf(stderr, "Неизвестный идентификатор в позиции %ld\n",
                        (long)(p - expr));
                exit(EXIT_FAILURE);
            }
        } else {
            /* Операторы и скобки */
            char c = *p++;
            switch (c) {
                case '+': case '-':
                    /* Унарный плюс/минус, если предшествующий токен – начало,
                       открывающая скобка или другой оператор */
                    if (!last_tok ||
                        last_tok->type == TOK_OPERATOR ||
                        last_tok->type == TOK_LPAREN) {
                        /* Превратим в унарный оператор, представив его как
                           ноль +/‑ число */
                        Token *zero = new_token(TOK_NUMBER);
                        zero->value = 0.0;
                        cur->next = zero;
                        cur = zero;
                        last_tok = zero;
                    }
                    t = new_token(TOK_OPERATOR);
                    t->op = c;
                    break;
                case '*': case '/': case '%': case '^':
                    t = new_token(TOK_OPERATOR);
                    t->op = c;
                    break;
                case '(':
                    t = new_token(TOK_LPAREN);
                    break;
                case ')':
                    t = new_token(TOK_RPAREN);
                    break;
                default:
                    fprintf(stderr, "Неизвестный символ '%c'\n", c);
                    exit(EXIT_FAILURE);
            }
        }

        if (!t) {
            fprintf(stderr, "Не удалось прочитать токен в позиции %ld\n",
                    (long)(p - expr));
            exit(EXIT_FAILURE);
        }

        cur->next = t;
        cur = t;
        last_tok = t;
    }
    return head.next;   // первый реальный токен
}

/* ---------- Преобразование инфикса → постфикс (RPN) ---------- */
static Token *infix_to_rpn(Token *in) {
    TokStack opstack = {0};
    Token *out_head = NULL, *out_tail = NULL;   // список RPN

    for (Token *tok = in; tok && tok->type != TOK_END; tok = tok->next) {
        switch (tok->type) {
            case TOK_NUMBER:
                /* Добавляем сразу в выход */
                {
                    Token *copy = new_token(TOK_NUMBER);
                    copy->value = tok->value;
                    if (!out_head) out_head = out_tail = copy;
                    else { out_tail->next = copy; out_tail = copy; }
                }
                break;
            case TOK_FUNC:
                push_tok(&opstack, tok);
                break;
            case TOK_OPERATOR: {
                char op1 = tok->op;
                while (1) {
                    Token *top = peek_tok(&opstack);
                    if (!top) break;
                    if (top->type == TOK_OPERATOR) {
                        char op2 = top->op;
                        int p1 = precedence(op1);
                        int p2 = precedence(op2);
                        if ((is_right_associative(op1) && p1 < p2) ||
                            (!is_right_associative(op1) && p1 <= p2)) {
                            /* Снять оператор со стека в выход */
                            Token *pop = pop_tok(&opstack);
                            Token *copy = new_token(TOK_OPERATOR);
                            copy->op = pop->op;
                            if (!out_head) out_head = out_tail = copy;
                            else { out_tail->next = copy; out_tail = copy; }
                            continue;
                        }
                    }
                    if (top->type == TOK_FUNC) {
                        Token *pop = pop_tok(&opstack);
                        Token *copy = new_token(TOK_FUNC);
                        copy->func = pop->func;
                        if (!out_head) out_head = out_tail = copy;
                        else { out_tail->next = copy; out_tail = copy; }
                        continue;
                    }
                    break;
                }
                push_tok(&opstack, tok);
                break;
            }
            case TOK_LPAREN:
                push_tok(&opstack, tok);
                break;
            case TOK_RPAREN:
                while (1) {
                    Token *top = pop_tok(&opstack);
                    if (!top) {
                        fprintf(stderr, "Несбалансированные скобки\n");
                        exit(EXIT_FAILURE);
                    }
                    if (top->type == TOK_LPAREN) {
                        /* Если перед '(' стояла функция – перенести её в выход */
                        Token *maybe_func = peek_tok(&opstack);
                        if (maybe_func && maybe_func->type == TOK_FUNC) {
                            Token *f = pop_tok(&opstack);
                            Token *copy = new_token(TOK_FUNC);
                            copy->func = f->func;
                            if (!out_head) out_head = out_tail = copy;
                            else { out_tail->next = copy; out_tail = copy; }
                        }
                        break; /* найдено '(' */
                    }
                    /* Оператор → в выход */
                    Token *copy = (top->type == TOK_OPERATOR) ?
                        new_token(TOK_OPERATOR) :
                        new_token(TOK_FUNC);
                    copy->op   = top->op;
                    copy->func = top->func;
                    if (!out_head) out_head = out_tail = copy;
                    else { out_tail->next = copy; out_tail = copy; }
                }
                break;
            default:
                break;
        }
    }

    /* После обработки всех токенов вытаскиваем оставшиеся */
    while (opstack.top) {
        Token *top = pop_tok(&opstack);
        if (top->type == TOK_LPAREN || top->type == TOK_RPAREN) {
            fprintf(stderr, "Несбалансированные скобки\n");
            exit(EXIT_FAILURE);
        }
        Token *copy = (top->type == TOK_OPERATOR) ?
            new_token(TOK_OPERATOR) :
            new_token(TOK_FUNC);
        copy->op = top->op;
        copy->func = top->func;
        if (!out_head) out_head = out_tail = copy;
        else { out_tail->next = copy; out_tail = copy; }
    }

    /* Добавляем маркер конца */
    Token *end = new_token(TOK_END);
    if (!out_head) out_head = out_tail = end;
    else { out_tail->next = end; out_tail = end; }

    return out_head;
}

/* ---------- Вычисление постфиксного выражения ---------- */
static double eval_rpn(Token *rpn) {
    NumStack ns;
    ns_init(&ns);

    for (Token *tok = rpn; tok && tok->type != TOK_END; tok = tok->next) {
        switch (tok->type) {
            case TOK_NUMBER:
                ns_push(&ns, tok->value);
                break;
            case TOK_OPERATOR: {
                double b = ns_pop(&ns);
                double a = ns_pop(&ns);
                double res = 0.0;
                switch (tok->op) {
                    case '+': res = a + b; break;
                    case '-': res = a - b; break;
                    case '*': res = a * b; break;
                    case '/':
                        if (b == 0.0) {
                            fprintf(stderr, "Деление на ноль!\n");
                            exit(EXIT_FAILURE);
                        }
                        res = a / b;
                        break;
                    case '%':
                        if (b == 0.0) {
                            fprintf(stderr, "Деление на ноль (остаток)!\n");
                            exit(EXIT_FAILURE);
                        }
                        res = fmod(a, b);
                        break;
                    case '^': res = pow(a, b); break;
                    default:
                        fprintf(stderr, "Неизвестный оператор '%c'\n", tok->op);
                        exit(EXIT_FAILURE);
                }
                ns_push(&ns, res);
                break;
            }
            case TOK_FUNC: {
                double a = ns_pop(&ns);
                double res = 0.0;
                if (strcmp(tok->func, "sin") == 0)   res = sin(a);
                else if (strcmp(tok->func, "cos") == 0)   res = cos(a);
                else if (strcmp(tok->func, "tan") == 0)   res = tan(a);
                else if (strcmp(tok->func, "log") == 0)   res = log(a);
                else if (strcmp(tok->func, "exp") == 0)   res = exp(a);
                else if (strcmp(tok->func, "sqrt") == 0)  {
                    if (a < 0) {
                        fprintf(stderr, "sqrt от отрицательного числа!\n");
                        exit(EXIT_FAILURE);
                    }
                    res = sqrt(a);
                } else {
                    fprintf(stderr, "Неизвестная функция %s\n", tok->func);
                    exit(EXIT_FAILURE);
                }
                ns_push(&ns, res);
                break;
            }
            default:
                break;
        }
    }

    double result = ns_pop(&ns);
    if (ns.size != 0) {
        fprintf(stderr, "Ошибка: в стеке осталось %zu элементов\n", ns.size);
        exit(EXIT_FAILURE);
    }
    ns_free(&ns);
    return result;
}

/* ---------- Освобождение списка токенов ---------- */
static void free_tokens(Token *t) {
    while (t) {
        Token *next = t->next;
        free(t);
        t = next;
    }
}

/* ---------- Интерактивный цикл ---------- */
int main(void) {
    printf("Сложный калькулятор (введите выражение, пустая строка – выход)\n");
    printf("Поддерживаемые функции: sin, cos, tan, log, exp, sqrt\n");
    printf("Операторы: + - * / %% ^ ( )\n\n");

    char line[1024];
    while (1) {
        printf("> ");
        if (!fgets(line, sizeof(line), stdin))
            break;                      // EOF

        /* Удаляем конечный '\n' */
        line[strcspn(line, "\n")] = '\0';

        /* Пустая строка = выход */
        if (line[0] == '\0')
            break;

        /* Лексика → RPN → Вычисление */
        Token *tokens = tokenize(line);
        Token *rpn = infix_to_rpn(tokens);
        double result = eval_rpn(rpn);
        printf("= %.15g\n", result);

        free_tokens(tokens);
        free_tokens(rpn);
    }

    puts("\nBye!");
    return 0;
}
