#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>

#define SMR_PHYS_ADDR   0x000010UL          /* 你得到的物理基址 */
#define SMR_SIZE        (128UL * 1024 * 1024)   /* 128 MiB */

/* 页对齐工具 */
static inline off_t page_align(off_t addr) {
    const off_t pagesz = sysconf(_SC_PAGESIZE);
    return addr & ~(pagesz - 1);
}
static inline off_t page_offset(off_t addr) {
    const off_t pagesz = sysconf(_SC_PAGESIZE);
    return addr & (pagesz - 1);
}

int main(void)
{
    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("open /dev/mem");
        return 1;
    }

    /* 计算映射起始地址（必须页对齐） */
    off_t align_addr = page_align(SMR_PHYS_ADDR);
    off_t offset     = page_offset(SMR_PHYS_ADDR);
    size_t map_len   = offset + SMR_SIZE;   /* 包含前面的对齐空洞 */

    void *map = mmap(NULL, map_len,
                     PROT_READ | PROT_WRITE,
                     MAP_SHARED,
                     fd, align_addr);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    /* 这里得到的指针已经包含了对齐偏移 */
    volatile uint8_t *base = (volatile uint8_t *)map + offset;

    /* ------------------- 示例读写 ------------------- */
    /* 写 0x55 到偏移 0x1000（相对于 SMR_PHYS_ADDR） */
    *((volatile uint32_t *)(base + 0x1000)) = 0x55;
    /* 确保写完成（对用户态而言，大多数 CPU 已经保证顺序），但可以使用 mb() */
    __sync_synchronize();   /* GCC 内建的全屏障 */

    uint32_t val = *((volatile uint32_t *)(base + 0x1000));
    printf("Read back value = 0x%08x\n", val);

    /* 大块拷贝：把 1 MiB 的缓冲写入 offset 0x2000 */
    {
        uint8_t src[1024*1024];
        memset(src, 0xAA, sizeof(src));
        memcpy((void *)(base + 0x2000), src, sizeof(src));
    }

    /* ------------------------------------------------- */

    munmap(map, map_len);
    close(fd);
    return 0;
}
```

#### 关键点说明

| 步骤 | 说明 |
|------|------|
| `open("/dev/mem", O_RDWR | O_SYNC)` | 必须以 **读写** 权限打开，`O_SYNC` 保证写后立即同步到物理地址。（`O_DSYNC` 也可） |
