/*  calltree.c
 *  -------------------------------------------------
 *  Программа строит дерево вызовов функций из C‑файла test.txt.
 *
 *  Компиляция (gcc):
 *      gcc -Wall -Wextra -std=c11 calltree.c -o calltree
 *
 *  Запуск:
 *      ./calltree
 *
 *  -------------------------------------------------
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ---------- структуры данных ---------- */

typedef struct Node {
    char *name;                 // имя функции
    struct Node **calls;        // массив указателей на вызываемые функции
    size_t  calls_cnt;          // количество элементов в массиве
    size_t  calls_cap;          // ёмкость массива
    struct Node *next;          // в хеш‑таблице
} Node;

/* Хеш‑таблица для быстрых поисков узлов по имени */
#define HASH_SIZE 1024
static Node *hash_table[HASH_SIZE];

/* ---------- вспомогательные функции ---------- */

/* Простейший (но достаточно хороший) хеш-функция для строк */
static unsigned hash_str(const char *s)
{
    unsigned h = 5381;
    while (*s)
        h = ((h << 5) + h) + (unsigned char)*s++;   /* h * 33 + c */
    return h % HASH_SIZE;
}

/* Получить узел по имени, создавая его при необходимости */
static Node *get_node(const char *name)
{
    unsigned h = hash_str(name);
    Node *p = hash_table[h];
    while (p) {
        if (strcmp(p->name, name) == 0)
            return p;
        p = p->next;
    }
    /* not found → create */
    p = (Node *)malloc(sizeof(Node));
    p->name = strdup(name);
    p->calls = NULL;
    p->calls_cnt = p->calls_cap = 0;
    p->next = hash_table[h];
    hash_table[h] = p;
    return p;
}

/* Добавить в список вызовов узла */
static void node_add_call(Node *caller, Node *callee)
{
    /* проверка на дубли (необязательно, но удобно) */
    for (size_t i = 0; i < caller->calls_cnt; ++i)
        if (caller->calls[i] == callee)
            return;                     // уже есть

    if (caller->calls_cnt == caller->calls_cap) {
        size_t new_cap = caller->calls_cap ? caller->calls_cap * 2 : 4;
        caller->calls = (Node **)realloc(caller->calls,
                                         new_cap * sizeof(Node *));
        caller->calls_cap = new_cap;
    }
    caller->calls[caller->calls_cnt++] = callee;
}

/* Пропустить пробелы и табуляцию */
static const char *skip_spaces(const char *p)
{
    while (*p && isspace((unsigned char)*p))
        ++p;
    return p;
}

/* Прочитать идентификатор (имя функции/переменной) */
static const char *read_identifier(const char *p, char *out, size_t out_sz)
{
    size_t i = 0;
    if (p && (isalpha((unsigned char)*p) || *p == '_' )) {
        while (p && (isalnum((unsigned char)*p) || *p == '_' )) {
            if (i + 1 < out_sz)
                out[i++] = *p;
            ++p;
        }
    }
    out[i] = '\0';
    return p;
}

/* Проверить, является ли слово служебным (if, for, while, switch, return, sizeof, do) */
static int is_keyword(const char *s)
{
    static const char *kw[] = {
        "if", "for", "while", "switch", "return", "sizeof", "do", "else"
    };
    for (size_t i = 0; i < sizeof kw / sizeof kw[0]; ++i)
        if (strcmp(s, kw[i]) == 0)
            return 1;
    return 0;
}

/* Пропустить комментарий // или /* … *\/   (примитивно) */
static const char *skip_comment(const char *p)
{
    if (p[0] == '/' && p[1] == '/') {            // // comment
        p += 2;
        while (*p && *p != '\n')
            ++p;
        return p;
    }
    if (p[0] == '/' && p[1] == '*') {            // /* comment */
        p += 2;
        while (*p && !(p[0] == '*' && p[1] == '/'))
            ++p;
        if (*p) p += 2;                           // skip "*/"
        return p;
    }
    return p;
}

/* Пропустить строковый литерал ( "…",  L"…",  R"delimiter( … )delimiter"…)  */
static const char *skip_string(const char *p)
{
    if (*p == '"') {
        ++p;
        while (*p && *p != '"') {
            if (*p == '\\' && p[1])   // escaped char
                p += 2;
            else
