static char *read_file(const char *filename)
{
    FILE *f = fopen(filename, "rb");
    if (!f) {
        perror("open");
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
