        printf("    ");

    printf("%s\n", node->name);

    /* Защита от рекурсии: если уже есть в текущем пути → цикл */
    for (int i = 0; i < level; ++i) {
        if (strcmp(path[i], node->name) == 0) {
            for (int j = 0; j < level; ++j)
                printf("    ");
            printf("<cycle>\n");
            return;
        }
    }

    /* Добавляем в путь */
    const char *new_path[256];
    memcpy(new_path, path, sizeof(const char *) * level);
    new_path[level] = node->name;

    /* Сортируем вызовы (для предсказуемого вывода) */
    if (node->calls_cnt > 1) {
        for (size_t i = 0; i < node->calls_cnt - 1; ++i) {
            for (size_t j = i + 1; j < node->calls_cnt; ++j) {
                if (strcmp(node->calls[i]->name, node->calls[j]->name) > 0) {
                    Node *tmp = node->calls[i];
                    node->calls[i] = node->calls[j];
                    node->calls[j] = tmp;
                }
            }
        }
    }

    for (size_t i = 0; i < node->calls_cnt; ++i)
        print_tree(node->calls[i], level + 1, new_path);
}

/* ------------------------------------------------- */

int main(void)
{
    const char *filename = "test.txt";

    char *src = read_file(filename);
    if (!src) {
        fprintf(stderr, "Не удалось загрузить файл %s\n", filename);
        return 1;
    }

    parse_program(src);
    free(src);

    /* Ищем функцию main */
    Node *main_node = get_node("main");
    if (!main_node) {
        fprintf(stderr, "В файле %s не найдено определение функции main\n", filename);
        return 1;
    }

    printf("Дерево вызовов (начало с main):\n");
    const char *empty_path[256] = {0};
    print_tree(main_node, 0, empty_path);

    /* Освобождение памяти (необязательно, процесс завершится) */
    for (size_t i = 0; i < HASH_SIZE; ++i) {
        Node *p = hash_table[i];
        while (p) {
            Node *next = p->next;
            free(p->calls);
            free(p->name);
            free(p);
            p = next;
        }
    }

    return 0;
}
```

