    printf("hello");
    bar();
}

void bar(void) {
    baz();
}

void baz(void) {
    // ничего не вызывает
}

int main(void) {
    foo();
    return 0;
}
```

**Запуск**

```
$ gcc -Wall -Wextra -std=c11 calltree.c -o calltree
$ ./calltree
Дерево вызовов (начало с main):
main
    foo
        printf
