## 1. BMP 文件格式要点

| 区域            | 内容                                 | 大小（字节） |
|----------------|--------------------------------------|------------|
| BITMAPFILEHEADER | 文件标识、文件大小、数据偏移等       | 14         |
| BITMAPINFOHEADER | 图像宽高、色深、压缩方式等           | 40         |
| (可选)调色板    | 仅在 1、4、8 位 BMP 中使用            | 0‑1024      |
| 像素数据        | 按行顺序存放，每行需 4‑字节对齐        | 视图像大小  |

- `bfType` 必须是字符 **'BM'**（0x4D42）。  
- `biBitCount` 为 **24** 表示每像素 3 字节（B、G、R）。  
- `biCompression` 为 **0**（BI_RGB）表示不压缩。  

---

## 2. 代码实现

```c
/***********************************************************************
 *  BMP 保存示例 (24 位真彩色)
 *  仅依赖标准 C 库，兼容 Windows / Linux / macOS
 ***********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

/* 把结构体设为 1 字节对齐，防止编译器插入填充字节 */
#pragma pack(push, 1)

/* BMP 文件头 (14 bytes) */
typedef struct {
    uint16_t bfType;      /* 必须是 0x4D42 ('BM') */
    uint32_t bfSize;      /* 文件总大小 (字节) */
    uint16_t bfReserved1; /* 必须为 0 */
    uint16_t bfReserved2; /* 必须为 0 */
    uint32_t bfOffBits;   /* 从文件头到像素数据的偏移量 (字节) */
} BITMAPFILEHEADER;

/* BMP 信息头 (40 bytes) */
typedef struct {
    uint32_t biSize;          /* 本结构体的大小，必须为 40 */
    int32_t  biWidth;         /* 图像宽度(像素) */
    int32_t  biHeight;        /* 图像高度(像素)。正值表示自下而上，负值表示自上而下 */
    uint16_t biPlanes;        /* 必须为 1 */
    uint16_t biBitCount;      /* 每像素位数：24、8、4、1 等 */
    uint32_t biCompression;   /* 压缩方式，0=BI_RGB(不压缩) */
    uint32_t biSizeImage;     /* 图像数据大小 (字节)，可设为 0 让系统自行计算 */
    int32_t  biXPelsPerMeter; /* 水平分辨率（像素/米），可设为 0 */
    int32_t  biYPelsPerMeter; /* 垂直分辨率（像素/米），可设为 0 */
    uint32_t biClrUsed;       /* 实际使用的颜色表索引数，0=默认 */
    uint32_t biClrImportant;  /* 重要颜色索引数，0=全部重要 */
} BITMAPINFOHEADER;

#pragma pack(pop)

/* -------------------------------------------------------------
 *  把 RGB24 数据写入 BMP 文件
 *  参数:
 *      filename    - 输出文件名
 *      width, height - 图像尺寸（像素）
 *      rgb24       - 指向宽*高*3 字节的原始数据（RGB 顺序）
 *  返回值:
 *      0   - 成功
 *     -1   - 打开文件失败
 *     -2   - 写文件出错
 * ------------------------------------------------------------- */
int save_rgb24_to_bmp(const char *filename,
                      int width, int height,
                      const unsigned char *rgb24)
{
    /* ----- 计算行填充（每行必须是 4 字节的整数倍） ----- */
    int bytes_per_pixel = 3;                     /* 24 位 = 3 字节 */
    int stride = width * bytes_per_pixel;        /* 每行实际像素字节数 */
    int padding = (4 - (stride & 3)) & 3;        /* 需要的填充字节数 (0~3) */
    int stride_with_pad = stride + padding;     /* 包含填充后的每行字节数 */

    /* ----- 设定 BMP 头部 ----- */
    BITMAPFILEHEADER file_header;
    BITMAPINFOHEADER info_header;

    memset(&file_header, 0, sizeof(file_header));
    memset(&info_header, 0, sizeof(info_header));

    file_header.bfType      = 0x4D42;                         /* 'BM' */
    file_header.bfOffBits   = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER);
    file_header.bfSize      = file_header.bfOffBits + stride_with_pad * height;

    info_header.biSize          = sizeof(BITMAPINFOHEADER);
    info_header.biWidth         = width;
    info_header.biHeight        = -height;      /* 负数 → 自上而下，便于直接使用行顺序 */
    info_header.biPlanes        = 1;
    info_header.biBitCount      = 24;           /* 24 位真彩色 */
    info_header.biCompression   = 0;            /* BI_RGB，不压缩 */
    info_header.biSizeImage     = stride_with_pad * height;  /* 可为 0，但这里给出实际值 */
    info_header.biXPelsPerMeter = 0;
    info_header.biYPelsPerMeter = 0;
    info_header.biClrUsed       = 0;
    info_header.biClrImportant  = 0;

    /* ----- 打开文件写入 ----- */
    FILE *fp = fopen(filename, "wb");
    if (!fp) return -1;

    /* 写文件头、信息头 */
    if (fwrite(&file_header, sizeof(file_header), 1, fp) != 1 ||
        fwrite(&info_header, sizeof(info_header), 1, fp) != 1) {
        fclose(fp);
        return -2;
    }

    /* 写像素数据（BGR 顺序） */
    const unsigned char *src_line = rgb24;      /* RGB 排列的原始数据起始地址 */
    unsigned char pad[3] = {0,0,0};              /* 最多 3 字节的填充 */

    for (int y = 0; y < height; ++y) {
        /* BMP 24 位要求每像素顺序为 B G R，而我们在内存里是 R G B，
           所以需要在写入时把顺序颠倒。 */
        for (int x = 0; x < width; ++x) {
            unsigned char r = src_line[3*x + 0];
            unsigned char g = src_line[3*x + 1];
            unsigned char b = src_line[3*x + 2];
            unsigned char pix[3] = { b, g, r };
            if (fwrite(pix, 3, 1, fp) != 1) {
                fclose(fp);
                return -2;
            }
        }
        /* 写行填充 */
        if (padding) {
            if (fwrite(pad, padding, 1, fp) != 1) {
                fclose(fp);
                return -2;
            }
        }
        src_line += stride;      /* 移动到下一行原始数据 */
    }

    fclose(fp);
    return 0;   /* 成功 */
}

/* -------------------------------------------------------------
 *  示例：生成 256×256 的彩色渐变图像
 * ------------------------------------------------------------- */
int main(void)
{
    const int WIDTH  = 256;
    const int HEIGHT = 256;

    /* 为每像素分配 3 字节 (RGB) */
    unsigned char *image = (unsigned char*)malloc(WIDTH * HEIGHT * 3);
    if (!image) {
        fprintf(stderr, "内存分配失败！\n");
        return 1;
    }

    /* 这里生成一个简单的渐变：红通道随 X 增大，绿通道随 Y 增大，蓝通道固定为 128 */
    for (int y = 0; y < HEIGHT; ++y) {
        for (int x = 0; x < WIDTH; ++x) {
            image[(y*WIDTH + x)*3 + 0] = (unsigned char)x;      // R
            image[(y*WIDTH + x)*3 + 1] = (unsigned char)y;      // G
            image[(y*WIDTH + x)*3 + 2] = 128;                   // B
        }
    }

    const char *outfile = "test.bmp";
    int ret = save_rgb24_to_bmp(outfile, WIDTH, HEIGHT, image);
    if (ret != 0) {
        fprintf(stderr, "保存 BMP 失败，错误码 %d\n", ret);
        free(image);
        return 1;
    }

    printf("BMP 文件已成功写入 %s\n", outfile);
    free(image);
    return 0;
}
```

### 代码说明

| 步骤 | 关键点 |
|------|--------|
| **结构体定义** | 使用 `#pragma pack(push,1)` 确保 **紧凑**（没有编译器插入的填充），因为 BMP 规范要求严格的字节布局。 |
| **行填充计算** | `padding = (4 - (stride & 3)) & 3;` → 计算每行需要补齐到 **4 字节对齐** 的字节数（0~3）。 |
| **负高度** | `info_header.biHeight = -height;` → 让像素从左上角开始顺序存储，省去把行顺序反转的麻烦。 |
| **像素写入** | BMP 24 位像素顺序是 **B‑G‑R**，而我们常用的内存布局是 **R‑G‑B**，所以在写文件时 (`b,g,r`) 调换顺序。 |
| **填充写入** | 使用 `pad[3]`（全 0）写入每行末尾的填充字节。 |
| **返回值** | 函数返回 `0` 表示成功，负数表示不同错误（文件打开/写入错误），便于调用者自行处理。 |

---

