static bool read_date_from_input(Date *out)
{
    char buf[64];
    printf("请输入初始日期（格式: YYYY-MM-DD）: ");
    if (!fgets(buf, sizeof(buf), stdin))
        return false;

    /* 去掉结尾的换行符 */
    char *p = buf;
    while (*p) {
        if (*p == '\n' || *p == '\r') { *p = '\0'; break; }
        ++p;
    }

    int y, m, d;
    if (sscanf(buf, "%d-%d-%d", &y, &m, &d) != 3) {
        printf("格式错误！请使用 YYYY-MM-DD\n");
        return false;
    }

    Date tmp = { y, m, d };
    if (!is_valid_date(&tmp)) {
        printf("非法日期！请重新输入。\n");
        return false;
    }

    *out = tmp;
    return true;
}

