#include <stdio.h>

#define MAX_SIZE 101          /* Kích thước tối đa của mảng */

/* Hàm in mảng */
void printArray(const int a[], int n)
{
    for (int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i < n - 1) printf(" ");
    }
    printf("\n");
}

/* Sắp xếp giảm dần (bubble‑sort) */
void sortDesc(int a[], int n)
{
    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (a[i] < a[j]) {               /* Đổi chỗ nếu a[i] < a[j] */
                int tmp = a[i];
                a[i]   = a[j];
                a[j]   = tmp;
            }
        }
    }
}

/* Sắp xếp tăng dần (bubble‑sort) */
void sortAsc(int a[], int n)
{
    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (a[i] > a[j]) {               /* Đổi chỗ nếu a[i] > a[j] */
                int tmp = a[i];
                a[i]   = a[j];
                a[j]   = tmp;
            }
        }
    }
}

int main(void)
{
    int a[MAX_SIZE];     /* Bước 1: khai báo mảng */
    int n;               /* số phần tử */

    /* Bước 2: nhập số lượng phần tử, kiểm tra hợp lệ */
    do {
        printf("Nhap so luong phan tu (0 <= n <= %d): ", MAX_SIZE);
        if (scanf("%d", &n) != 1) {
            /* Nếu người dùng nhập ký tự không phải số */
            while (getchar() != '\n');   /* xóa bộ đệm */
            n = -1;                       /* buộc vòng lặp lặp lại */
        }
        if (n < 0 || n > MAX_SIZE) {
            printf("So luong phan tu khong hop le! Vui long nhap lai.\n");
        }
    } while (n < 0 || n > MAX_SIZE);

    /* Bước 3: nhập các phần tử của dãy */
    for (int i = 0; i < n; ++i) {
        printf("a[%d] = ", i);
        while (scanf("%d", &a[i]) != 1) {
            while (getchar() != '\n');   /* xóa bộ đệm */
            printf("Gia tri khong hop le! Nhap lai a[%d] = ", i);
        }
    }

    /* Sao chép mảng để có thể in cả hai kết quả (giảm & tăng) */
    int b[MAX_SIZE];
    for (int i = 0; i < n; ++i) b[i] = a[i];

    /* Bước 4: sắp xếp giảm dần */
    sortDesc(a, n);

    /* Bước 5: hiển thị mảng đã sắp xếp giảm dần */
    printf("\nMang sau khi sap xep giam dan:\n");
    printArray(a, n);

    /* Bước 6: sắp xếp tăng dần và hiển thị */
    sortAsc(b, n);
    printf("\nMang sau khi sap xep tang dan:\n");
    printArray(b, n);

    return 0;
}
```

