/*****************************************************************
 *  Longest increasing subsequence whose adjacent elements differ *
 *  by exactly 1.  C implementation (compatible with C99/C11).   *
 *****************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <string.h>

/* ---------- simple hash table (separate chaining) ------------ */

#define HASH_SIZE  4096               /* should be a power of two */
typedef struct Node {
    int key;               /* the array element value                */
    int val;               /* last index (1‑based) where it appeared */
    struct Node *next;
} Node;

static Node *hash_table[HASH_SIZE] = {0};

/* simple (unsigned) hash function */
static unsigned int hash_func(int x)
{
    /* mix the bits a little – not critical for this task */
    unsigned int h = (unsigned int)x;
    h ^= h >> 16;
    return h & (HASH_SIZE - 1);
}

/* find a node with the given key; returns NULL if not present */
static Node *hash_find(int key)
{
    unsigned int h = hash_func(key);
    Node *p = hash_table[h];
    while (p) {
        if (p->key == key)
            return p;
        p = p->next;
    }
    return NULL;
}

/* insert a key‑value pair (or update the value if the key already exists) */
static void hash_insert(int key, int val)
{
    unsigned int h = hash_func(key);
    Node *p = hash_table[h];
    while (p) {
        if (p->key == key) {
            p->val = val;          /* update */
            return;
        }
        p = p->next;
    }
    /* not found → create a new node */
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->val = val;
    new_node->next = hash_table[h];
    hash_table[h] = new_node;
}

/* free the whole table (just for completeness) */
static void hash_free(void)
{
    for (int i = 0; i < HASH_SIZE; ++i) {
        Node *p = hash_table[i];
        while (p) {
            Node *tmp = p;
            p = p->next;
            free(tmp);
        }
        hash_table[i] = NULL;
    }
}

/* --------------------------------------------------------------- */

/* longest subsequence whose adjacent elements differ by exactly 1 */
int longestSubsequence(const int a[], int n)
{
    /* dp[i] – length of longest valid subsequence that ends at a[i] */
    int *dp = (int *)malloc(n * sizeof(int));
    if (!dp) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    memset(dp, 0, n * sizeof(int));

    int maximum = INT_MIN;

    for (int i = 0; i < n; ++i) {
        /* look for a[i] - 1 that has already appeared */
        Node *prev = hash_find(a[i] - 1);
        if (prev) {
            /* the stored value is 1‑based index of the last occurrence */
            int lastIndex = prev->val - 1;   /* convert to 0‑based */
            dp[i] = 1 + dp[lastIndex];
        } else {
            dp[i] = 1;
        }

        /* store (a[i] , i+1) → we keep the index 1‑based as in the original */
        hash_insert(a[i], i + 1);

        if (dp[i] > maximum)
            maximum = dp[i];
    }

    free(dp);
    return maximum;
}

/* --------------------------------------------------------------- */

int main(void)
{
    int a[] = { 4, 3, 10, 3, 11, 4, 5, 6, 7, 8, 12 };
    int n = sizeof(a) / sizeof(a[0]);

    int ans = longestSubsequence(a, n);
    printf("%d\n", ans);

    /* clean up the hash table (optional, program ends anyway) */
    hash_free();

    return 0;
}
```

### How the code works

1. **Hash table** – `hash_find` and `hash_insert` let us query in **O(1)**
   average time whether a value `x‑1` has already occurred and, if so,
   retrieve the last (1‑based) index where it appeared.  
   This replicates the behaviour of `std::unordered_map<int,int>` in the C++ version.

2. **Dynamic programming** – `dp[i]` is computed exactly as in the original
   algorithm:
   * if a previous element equal to `a[i]‑1` exists, we extend the subsequence
     that ended there (`dp[lastIndex] + 1`);
   * otherwise the subsequence consisting solely of `a[i]` has length `1`.

3. **Result** – `maximum` stores the largest `dp[i]` encountered and is
   returned.

The program compiles with any standard C compiler, e.g.

```sh
gcc -std=c99 -Wall -Wextra -O2 longest_subseq.c -o longest_subseq
```

and prints

```
7
```

which matches the output of the original C++ program.

