## 3. 裸机（Bare‑Metal）示例代码

下面的例子基于 **ARM Cortex‑M4**（或任何 MMIO 可直接访问的 MCU），假设：

- **SSI 基址** 为 `0x4001_3000`（请根据你使用的 SoC 手册替换）  
- **时钟已配置**（SPI CLK = 50 MHz，SPI SCK = 5 MHz）  
- **片选使用 SER[0]**（低电平有效）  

### 3.1 头文件与宏定义

```c
/* -------------------------------------------------------------
 *  DWC_SSI 寄存器映射（以 0x40013000 为例）
 * ------------------------------------------------------------- */
#define DWC_SSI_BASE      0x40013000U

#define SSI_CR0   (*(volatile uint32_t *)(DWC_SSI_BASE + 0x00))
#define SSI_CR1   (*(volatile uint32_t *)(DWC_SSI_BASE + 0x04))
#define SSI_SR    (*(volatile uint32_t *)(DWC_SSI_BASE + 0x08))
#define SSI_CPSR  (*(volatile uint32_t *)(DWC_SSI_BASE + 0x10))
#define SSI_IMR   (*(volatile uint32_t *)(DWC_SSI_BASE + 0x0C))
#define SSI_DMACR (*(volatile uint32_t *)(DWC_SSI_BASE + 0x14))
#define SSI_SER   (*(volatile uint32_t *)(DWC_SSI_BASE + 0x30))
#define SSI_DR0   (*(volatile uint32_t *)(DWC_SSI_BASE + 0x60))

/* -------------------------------------------------------------
 *  常用位宏（只列出本例需要的位）
 * ------------------------------------------------------------- */
#define CR0_DFS_MASK      (0x1F)          /* 位 0‑4 */
#define CR0_DFS_SHIFT     (0)
#define CR0_EE_MODE       (1U << 23)      /* EEPROM模式 */

#define CR1_SSE           (1U << 0)       /* 使能 SSI */
#define CR1_MS            (1U << 1)       /* 0: 主机, 1: 从机 */

#define SR_TFE            (1U << 0)       /* 发送 FIFO 空 */
#define SR_RNE            (1U << 2)       /* 接收 FIFO 非空 */

/* -------------------------------------------------------------
 *  简单延时（仅用于演示，实际请使用 timer / systick）
 * ------------------------------------------------------------- */
static inline void delay_cycles(uint32_t n)
{
    while (n--) __asm volatile ("nop");
}
```

### 3.2 初始化函数

```c
/**
 * @brief 初始化 DWC‑SSI 为主机 + EEPROM 模式
 * @param clk_hz   输入时钟（PCLK）频率
 * @param sck_hz   目标 SPI 时钟频率（不超过 50 MHz）
 */
static void dwc_ssi_init(uint32_t clk_hz, uint32_t sck_hz)
{
    /* 1. 关闭 SSI，防止改寄存器时产生意外传输 */
    SSI_CR1 &= ~CR1_SSE;

    /* 2. 配置数据帧大小：本例使用 8 bit（即 1 byte） */
    uint32_t cr0 = SSI_CR0 & ~CR0_DFS_MASK;
    cr0 |= (8U - 1U) << CR0_DFS_SHIFT;   /* DFS = 7 → 8 bits */
    SSI_CR0 = cr0;

    /* 3. 使能 EEPROM 模式（地址+数据在同一次传输） */
    SSI_CR0 |= CR0_EE_MODE;

    /* 4. 设定时钟分频（CPSR）  SCK = PCLK / (CPSR * (SCR+1))  */
    /*    这里我们直接使用 CPSR = 2, SCR = 4 → SCK ≈ PCLK / 10   */
    uint32_t cpsr = clk_hz / (sck_hz * 10U);
    if (cpsr == 0) cpsr = 2;    /* 最低 2（硬件要求为偶数） */
    if (cpsr & 1U) cpsr++;     /* 必须为偶数 */
    SSI_CPSR = cpsr;           /* 设定 CPSR */

    /* 5. 片选默认不选中（SER=0 为片选有效，故写 1 关闭） */
    SSI_SER = 0xFF;            /* 所有片选均为非激活（高） */

    /* 6. 关闭所有中断（裸机情况下不使用） */
    SSI_IMR = 0x0;

    /* 7. 使能 SSI 主机模式 */
    SSI_CR1 = CR1_MS;          /* MS=0 → 主机 */
    SSI_CR1 |= CR1_SSE;        /* 最后再打开 SSI */
}
```

### 3.3 片选控制（低电平有效）

```c
/* 片选 0（对应 SER[0]） */
static inline void cs_low(void)  { SSI_SER &= ~0x01U; }   /* 片选有效 */
static inline void cs_high(void) { SSI_SER |=  0x01U; }   /* 片选失效 */
```

### 3.4 发送（写）函数（EEPROM 模式）

```c
/**
 * @brief 向 EEPROM 写入（Address + Data）一次性发送
 *        本例以 24‑bit地址 + 8‑bit数据 为例（常见 25xx 系列）。
 *
 * @param addr   24‑bit EEPROM 地址
 * @param data   要写入的一个字节
 * @return 0 成功, -1 失败
 */
static int eeprom_write_byte(uint32_t addr, uint8_t data)
{
    uint8_t tx_buf[4];

    /* 1. 组装“地址+数据”帧：
     *    - 常见 EEPROM 的写指令是 0x02（写使能指令 0x06/0x04 已在外部完成）,
     *      这里假设外部已经发送 WREN，直接发送 [0x02][A23..A0][data]。
     */
    tx_buf[0] = 0x02;                     // WRITE 命令
    tx_buf[1] = (addr >> 16) & 0xFF;      // A23..A16
    tx_buf[2] = (addr >>  8) & 0xFF;      // A15..A8
    tx_buf[3] = (addr >>  0) & 0xFF;      // A7..A0
    /* 最后一个字节是要写的数据 */
    uint8_t data_buf[1] = { data };

    cs_low();                 // 拉低 CS，保持整个事务期间低电平

    /* -------------------------------------------------
     * 发送命令+地址（4 bytes）
     * ------------------------------------------------- */
    for (int i = 0; i < 4; ++i) {
        while (!(SSI_SR & SR_TFE)) {}   // 等待 TX FIFO 空
        SSI_DR0 = tx_buf[i];
    }

    /* -------------------------------------------------
     * 发送真实数据（1 byte）
     * ------------------------------------------------- */
    while (!(SSI_SR & SR_TFE)) {}
    SSI_DR0 = data_buf[0];

    /* -------------------------------------------------
     * 等待传输结束：检查 BUSY 位（SR[4]）或轮询 TFE+RNE
     * ------------------------------------------------- */
    while (SSI_SR & (1U << 4)) {}   // BUSY 位（如果有）

    cs_high();                // 结束事务
    return 0;
}
```

> **关键点解释**  
> - **一次完整事务**：`cs_low()` → 发送 **地址+数据** → `cs_high()`，期间 **未进行任何 CS 失活**，这正是 **EEPROM 模式** 所要求的。  
> - **`SSI_CR0.EE_MODE = 1`** 只影响 **硬件自动保持 CS 低电平**，但我们仍在软件层面手动控制 CS（以兼容所有平台）。如果你把 `SSI_SER` 直接映射到硬件内部 CS（不需要手动 GPIO），则仅需把 `EE_MODE` 置位即可。

### 3.5 读取（Read）函数（EEPROM 模式）

读取过程稍有不同：**先发送指令+地址**（保持 CS 低），然后 **切换为接收模式**，再读取返回的字节。下面的示例实现 **24‑bit地址 + 1 byte 数据** 的读取（典型 25AA/25LC 系列）。

```c
/**
 * @brief 从 EEPROM 读取单字节（地址 + READ）。
 *
 * @param addr   24‑bit地址
 * @param pData  输出指针
 * @return 0 成功, -1 失败
 */
static int eeprom_read_byte(uint32_t addr, uint8_t *pData)
{
    uint8_t tx_buf[4];

    tx_buf[0] = 0x03;                     // READ 命令
    tx_buf[1] = (addr >> 16) & 0xFF;
    tx_buf[2] = (addr >>  8) & 0xFF;
    tx_buf[3] = (addr >>  0) & 0xFF;

    cs_low();

    /* 发送 READ 命令 + 地址（4 bytes） */
    for (int i = 0; i < 4; ++i) {
        while (!(SSI_SR & SR_TFE)) {}
        SSI_DR0 = tx_buf[i];
    }

    /* 发送 1 byte 的 “dummy” 来产生时钟，随后接收返回的字节 */
    while (!(SSI_SR & SR_TFE)) {}
    SSI_DR0 = 0xFF;          // dummy byte：仅产生 SCK

    /* 等待接收 FIFO 有数据 */
    while (!(SSI_SR & SR_RNE)) {}
    *pData = (uint8_t)SSI_DR0;   // 从 DR0 读取接收数据

    cs_high();
    return 0;
}
```

