## 4. Linux Kernel 中的 DWC SSI EEPROM 模式（参考实现）

> **前置说明**  
> - **Linux** SPI 框架已经把 **CS** 的拉低与释放封装在 `spi_transfer` 的 `cs_change` / `delay_after_cs` 成员里，用户只需要准备好一次 `spi_message`，把 **地址 + 数据** 放进同一个 `tx_buf` 即可。  
> - 若想显式打开 DWC‑SSI 的 **EEPROM 模式寄存器位**，通常在 **spi‑master 驱动的 `probe` / `setup`** 里完成。

### 4.1 SPI‑master 驱动（片段）

```c
/* SPDX-License-Identifier: GPL-2.0 */
/* dwc_ssi_master.c – 简化版的 DesignWare SSI master driver */
#include <linux/module.h>
#include <linux/spi/spi.h>
#include <linux/io.h>
#include <linux/of.h>

#define SSI_BASE        0x...   /* 从 DT 或平台数据获取 */
#define SSI_CR0         0x00
#define SSI_CR1         0x04
#define SSI_SER         0x30
#define SSI_DR0         0x60

#define CR0_EE_MODE    (1U << 23)
#define CR1_SSE        (1U << 0)

static void dwc_ssi_setup_eeprom_mode(void __iomem *base)
{
    u32 cr0 = readl(base + SSI_CR0);
    cr0 |= CR0_EE_MODE;           /* 使能 EEPROM 模式 */
    writel(cr0, base + SSI_CR0);
}

/* 典型的 .transfer_one_message 实现（略） */
```

> **关键点**：只要在 `probe` 中调用 `dwc_ssi_setup_eeprom_mode()`（或在 `spi_setup` 中），后续的 `spi_transfer` 会自动使用 **EEPROM 模式**（CS 在一次 `transfer` 内不会自动释放）。

### 4.2 用户层驱动（简单示例）

```c
/* eeprom_drv.c – 通过 Linux SPI 框架使用 EEPROM */
#include <linux/spi/spi.h>
#include <linux/module.h>
#include <linux/delay.h>

static int eeprom_write(struct spi_device *spi, u32 addr, u8 data)
{
    u8 tx[5] = { 0x02,
                 (addr >> 16) & 0xff,
                 (addr >>  8) & 0xff,
                 (addr >>  0) & 0xff,
                 data };

    struct spi_transfer t = {
        .tx_buf = tx,
        .len    = sizeof(tx),
        .cs_change = 0,           // 保持 CS 低（默认）
    };
    struct spi_message m;
    spi_message_init(&m);
    spi_message_add_tail(&t, &m);
    return spi_sync(spi, &m);
}

static int eeprom_read(struct spi_device *spi, u32 addr, u8 *pdata)
{
    u8 tx[4] = { 0x03,
                 (addr >> 16) & 0xff,
                 (addr >>  8) & 0xff,
                 (addr >>  0) & 0xff };
    u8 rx[1];                     // 读取 1 byte

    struct spi_transfer t[2] = {
        { .tx_buf = tx, .len = sizeof(tx) },          // 命令+地址
        { .rx_buf = rx, .len = 1, .cs_change = 0 }    // 读取数据
    };
    struct spi_message m;
    spi_message_init(&m);
    spi_message_add_tail(&t[0], &m);
    spi_message_add_tail(&t[1], &m);
    int ret = spi_sync(spi, &m);
    if (!ret)
        *pdata = rx[0];
    return ret;
}
```

> **结论**：在 Linux 中，**只要 SPI‑master 已经把 `EE_MODE` 打开**，`spi_sync`/`spi_async` 的一次完整 `spi_message`（包括多个 `spi_transfer`）就会保持 CS 低电平，等价于 “EEPROM 模式”。  

