## 3. 完整代码

> **编译提示**：  
> - Linux/macOS：`gcc -Wall -Wextra -o calendar calendar.c -lrt`（`-lrt` 只在某些平台需要）  
> - Windows：使用 MinGW 或 Visual Studio 编译，`settimeofday` 需要改为 `SetSystemTime`（示例已在代码中给出宏分支）。  

```c
/*********************************************************************
 * 万年历实验 – 日期调整 (C 语言实现)
 *  功能：
 *    1) 通过键盘选择增加/减少 年、月、日
 *    2) 统一处理跨月、跨年、闰年
 *    3) 可将编辑后的日期写回系统时间（需管理员权限）
 *
 *  编译 (Linux/macOS)：
 *      gcc -Wall -Wextra -o calendar calendar.c
 *
 *  注意：
 *      - 写回系统时间需要 root 权限 (sudo ./calendar)
 *      - 本示例仅演示核心逻辑，未做过多错误检查
 *********************************************************************/

#define _POSIX_C_SOURCE 200809L   /* 需要 settimeofday()   */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>
#include <unistd.h>

/* ---------- 辅助函数声明 ---------- */
int  isLeapYear(int year);
int  daysInMonth(int year, int month);          /* month: 1~12 */
void normalizeDate(struct tm *tm);
void printDate(const struct tm *tm);
void setSystemTime(const struct tm *tm);

/* ---------- 主程序 ---------- */
int main(void)
{
    struct tm work_tm;            /* 我们要编辑的日期 */
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return 1;
    }
    localtime_r(&now, &work_tm); /* 初始化为当前系统时间 */

    int choice = -1;
    while (choice != 0) {
        printf("\n========== 万年历 – 日期调整 ==========\n");
        printf("当前工作日期   : ");
        printDate(&work_tm);
        printf("\n");
        printf("请选择操作 (输入数字然后回车) :\n");
        printf(" 1) 显示当前工作日期\n");
        printf(" 2) 年   +1 / -1\n");
        printf(" 3) 月   +1 / -1\n");
        printf(" 4) 日   +1 / -1\n");
        printf(" 5) 重置为系统当前时间\n");
        printf(" 6) 把工作日期写回系统时间 (需管理员权限)\n");
        printf(" 0) 退出\n");
        printf("=> ");
        if (scanf("%d", &choice) != 1) {
            /* 输入非法字符，清空缓冲区 */
            int c;
            while ((c = getchar()) != '\n' && c != EOF) ;
            continue;
        }

        switch (choice) {
        case 1:
            printf("工作日期 : ");
            printDate(&work_tm);
            printf("\n");
            break;

        case 2: {   /* 年 +1 / -1 */
            int delta;
            printf("输入 1 增加一年，-1 减少一年: ");
            if (scanf("%d", &delta) != 1) delta = 0;
            work_tm.tm_year += delta;
            normalizeDate(&work_tm);
            break;
        }

        case 3: {   /* 月 +1 / -1 */
            int delta;
            printf("输入 1 增加一月，-1 减少一月: ");
            if (scanf("%d", &delta) != 1) delta = 0;
            work_tm.tm_mon += delta;      /* tm_mon 原始范围 0~11 */
            normalizeDate(&work_tm);
            break;
        }

        case 4: {   /* 日 +1 / -1 */
            int delta;
            printf("输入 1 增加一天，-1 减少一天: ");
            if (scanf("%d", &delta) != 1) delta = 0;
            work_tm.tm_mday += delta;
            normalizeDate(&work_tm);
            break;
        }

        case 5:   /* 重置为系统当前时间 */
            now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
                break;
            }
            localtime_r(&now, &work_tm);
            printf("已重置为系统当前时间。\n");
            break;

        case 6:   /* 把工作日期写回系统时间 */
            setSystemTime(&work_tm);
            break;

        case 0:
            printf("程序结束。\n");
            break;

        default:
            printf("无效选项，请重新输入。\n");
            break;
        }

        /* 清除输入缓冲区中残余字符（防止循环中出现意外） */
        int ch;
        while ((ch = getchar()) != '\n' && ch != EOF) ;
    }

    return 0;
}

/* ---------- 辅助函数实现 ---------- */

/* 判断闰年（公历规则） */
int isLeapYear(int year)
{
    /* tm_year 为“自1900起的年数”，这里传入完整的公历年 */
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

/* 返回指定月份的天数（1~12） */
int daysInMonth(int year, int month)
{
    static const int days[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };
    if (month == 2) {   /* 二月要考虑闰年 */
        return isLeapYear(year) ? 29 : 28;
    }
    return days[month - 1];
}

/* 统一处理 tm 结构中因增减导致的越界/欠缺情况
   注意：tm_year 为 "1900+year"，tm_mon 为 0~11，tm_mday 为 1~31 */
void normalizeDate(struct tm *tm)
{
    /* 1) 先把月份溢出纠正为合法 0~11，顺便调整年份 */
    while (tm->tm_mon < 0) {
        tm->tm_mon += 12;
        tm->tm_year--;
    }
    while (tm->tm_mon > 11) {
        tm->tm_mon -= 12;
        tm->tm_year++;
    }

    /* 2) 处理日期（天）溢出/欠缺 */
    while (1) {
        int curYear  = tm->tm_year + 1900;
        int curMonth = tm->tm_mon + 1;                /* 1~12 */
        int dim = daysInMonth(curYear, curMonth);    /* 当月天数 */

        if (tm->tm_mday > dim) {         /* 超出本月最大天数 → 进位 */
            tm->tm_mday -= dim;
            tm->tm_mon++;
            if (tm->tm_mon > 11) {
                tm->tm_mon = 0;
                tm->tm_year++;
            }
            continue;
        }
        if (tm->tm_mday < 1) {           /* 小于1 → 借位 */
            tm->tm_mon--;
            if (tm->tm_mon < 0) {
                tm->tm_mon = 11;
                tm->tm_year--;
            }
            curYear  = tm->tm_year + 1900;
            curMonth = tm->tm_mon + 1;
            dim = daysInMonth(curYear, curMonth);
            tm->tm_mday += dim;
            continue;
        }
        break;   /* 日期已合法 */
    }

    /* 3) 重新计算 tm_wday, tm_yday 等信息（并保证 tm_isdst 正确） */
    time_t t = mktime(tm);   /* mktime 会自动填充剩余字段 */
    if (t == (time_t)-1) {
        perror("mktime 在 normalizeDate 中失败");
        /* 这里不退出，继续使用已修正的年月日 */
    } else {
        /* mktime 修改了 tm 本身，因此这里不需要额外操作 */
        ;
    }
}

/* 打印日期，格式：YYYY-MM-DD  星期X */
void printDate(const struct tm *tm)
{
    const char *weekday[] = {
        "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"
    };
    printf("%04d-%02d-%02d  %s",
           tm->tm_year + 1900,
           tm->tm_mon  + 1,
           tm->tm_mday,
           weekday[tm->tm_wday]);
}

/* 把 struct tm 表示的时间写回系统时间
   需要超级用户权限（root）。如果没有权限会打印错误信息。 */
void setSystemTime(const struct tm *tm)
{
    struct timeval tv;
    struct tm tmp = *tm;      /* 需要一个可写副本，mktime 会修改 */
    time_t t = mktime(&tmp); /* 把 struct tm → time_t (UTC) */
    if (t == (time_t)-1) {
        perror("mktime 失败，无法转换时间");
        return;
    }

    tv.tv_sec  = t;
    tv.tv_usec = 0;

    /* Linux/macOS 使用 settimeofday */
#if defined(__unix__) || defined(__APPLE__) || defined(__MACH__)
    if (settimeofday(&tv, NULL) == -1) {
        perror("settimeofday（写回系统时间）失败。请以 root 权限运行。");
        return;
    }
    printf("系统时间已成功更新！\n");
#else
    /* Windows 示例（需要 <windows.h> 与 SetSystemTime） */
    #error "本代码仅在 Unix-like 系统下实现。若在 Windows 上，请自行改为使用 SetSystemTime。"
#endif
}
```

