## 2️⃣ 运行时堆管理（简易 malloc / free）

在资源极其紧张的 MCU 上，**glibc 的 `malloc` 太重**，我们更倾向使用 **轻量级内存池**、**固定块分配器** 或 **伙伴系统**。下面先给出最常见的 **FreeRTOS “heap_4.c”**（基于 **块合并**）的简化实现，再给出 **TLSF（两级适配）** 的代码示例。

### 2.1 经典的 `heap_4`（块合并）实现（约 400 行）

> 这段代码摘自 FreeRTOS（已做注释），可以直接拷贝到自己的项目里。  
> 它把堆划分成 **不等长的块**（头部 8‑bytes），在 `free` 时尝试合并相邻空闲块，减少碎片。

```c
/* tiny_heap.c --------------------------------------------------- */
/* 只保留最核心的结构体和 API，去掉了 FreeRTOS 的调度/宏定义 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* ------------------------------------------------------------------
 * 1. 堆的起始/结束地址（由链接脚本提供）
 *    这里用 extern 声明，让编译器在链接阶段把地址绑定进去。
 * ------------------------------------------------------------------ */
extern uint8_t __heap_start;
extern uint8_t __heap_end;

/* ------------------------------------------------------------------
 * 2. 堆块头（Block Header）——8 字节
 * ------------------------------------------------------------------ */
typedef struct BlockLink
{
    struct BlockLink *pxNextFreeBlock;   /* 指向下一个空闲块 */
    size_t            xBlockSize;       /* 块的总大小（包括头部），最低位保留 flag */
} BlockLink_t;

/* ------------------------------------------------------------------
 * 3. 维护的全局变量
 * ------------------------------------------------------------------ */
static BlockLink_t *xFreeListHead = NULL;   /* 空闲链表的哨兵 */
static size_t       xTotalHeapSize = 0;

/* ------------------------------------------------------------------
 * 4. 对齐宏（所有块都必须 8 字节对齐）
 * ------------------------------------------------------------------ */
#define portBYTE_ALIGNMENT          (8U)
#define portBYTE_ALIGNMENT_MASK     (portBYTE_ALIGNMENT - 1U)
#define ALIGN(size)  (((size) + portBYTE_ALIGNMENT_MASK) & ~portBYTE_ALIGNMENT_MASK)

/* ------------------------------------------------------------------
 * 5. 低位标记：块是否被分配（为兼容 FreeRTOS，使用最低位作为 "allocated" 标志）
 * ------------------------------------------------------------------ */
#define BLOCK_ALLOCATED_FLAG   ( (size_t) 1 )
#define BLOCK_SIZE_MASK        ( ~BLOCK_ALLOCATED_FLAG )

/* ------------------------------------------------------------------
 * 6. 初始化函数（在系统启动后、调用任何 malloc 之前一次性调用）
 * ------------------------------------------------------------------ */
void tiny_heap_init(void)
{
    /* 计算堆总大小 */
    xTotalHeapSize = (size_t)(&__heap_end - &__heap_start);

    /* 第一个（也是唯一的）空闲块占满整个堆，块头放在堆起始处 */
    xFreeListHead = (BlockLink_t *)&__heap_start;
    xFreeListHead->pxNextFreeBlock = NULL;
    xFreeListHead->xBlockSize = xTotalHeapSize;

    /* 让块大小对齐，确保不产生碎片 */
    xFreeListHead->xBlockSize = ALIGN(xFreeListHead->xBlockSize);
}

/* ------------------------------------------------------------------
 * 7. 申请内存（tiny_malloc）
 *    - 首先把请求大小对齐 + 块头大小
 *    - 在空闲链表中搜索第一个足够大的块（first‑fit）
 *    - 如有必要拆分块（剩余部分仍然是空闲块）
 * ------------------------------------------------------------------ */
void *tiny_malloc(size_t xWantedSize)
{
    BlockLink_t *pxPrev, *pxCurr, *pxNewBlock;
    void *pvReturn = NULL;
    size_t xTotalSize;

    if (xWantedSize == 0) return NULL;

    /* 1️⃣ 按 8‑字节对齐 + 头部大小 */
    xWantedSize = ALIGN(xWantedSize);
    xTotalSize   = xWantedSize + sizeof(BlockLink_t);
    xTotalSize   = ALIGN(xTotalSize);   /* 再次对齐防止溢出 */

    /* 2️⃣ 遍历空闲链表，first‑fit */
    pxPrev = NULL;
    pxCurr = xFreeListHead;

    while (pxCurr != NULL)
    {
        if ( (pxCurr->xBlockSize & BLOCK_SIZE_MASK) >= xTotalSize )
        {
            /* 找到合适块 */
            if ( (pxCurr->xBlockSize & BLOCK_SIZE_MASK) - xTotalSize
                 >= (sizeof(BlockLink_t) + portBYTE_ALIGNMENT) )
            {
                /* 3️⃣ 拆分块：在分配的块后面留出最小空闲块 */
                pxNewBlock = (BlockLink_t *)((uint8_t *)pxCurr + xTotalSize);
                pxNewBlock->xBlockSize = (pxCurr->xBlockSize & BLOCK_SIZE_MASK) - xTotalSize;
                pxNewBlock->pxNextFreeBlock = pxCurr->pxNextFreeBlock;

                /* 更新当前块的大小 & 标记已分配 */
                pxCurr->xBlockSize = xTotalSize | BLOCK_ALLOCATED_FLAG;
                pxCurr->pxNextFreeBlock = NULL;   /* 已分配块不在空闲链表中 */

                /* 链表链接：把新空闲块插回链表 */
                if (pxPrev == NULL)
                    xFreeListHead = pxNewBlock;
                else
                    pxPrev->pxNextFreeBlock = pxNewBlock;
            }
            else
            {
                /* 4️⃣ 块太小不能再拆分，直接整块使用 */
                if (pxPrev == NULL)
                    xFreeListHead = pxCurr->pxNextFreeBlock;
                else
                    pxPrev->pxNextFreeBlock = pxCurr->pxNextFreeBlock;

                pxCurr->xBlockSize |= BLOCK_ALLOCATED_FLAG; /* 设置已分配标记 */
                pxCurr->pxNextFreeBlock = NULL;
            }
            /* 用户指针不返回块头，而是跳过 */
            pvReturn = (void *)((uint8_t *)pxCurr + sizeof(BlockLink_t));
            break;
        }
        pxPrev = pxCurr;
        pxCurr = pxCurr->pxNextFreeBlock;
    }
    return pvReturn;
}

/* ------------------------------------------------------------------
 * 8. 释放内存（tiny_free）
 *    - 将块标记为“空”，再尝试与相邻空闲块合并
 * ------------------------------------------------------------------ */
void tiny_free(void *pv)
{
    BlockLink_t *pxBlock, *pxIter, *pxPrev;
    uint8_t *pool_start = &__heap_start;
    uint8_t *pool_end   = &__heap_end;

    if (pv == NULL) return;

    /* 1️⃣ 找到块头 */
    pxBlock = (BlockLink_t *)((uint8_t *)pv - sizeof(BlockLink_t));

    /* 2️⃣ 清除已分配标记，使其成为空闲块 */
    pxBlock->xBlockSize &= BLOCK_SIZE_MASK;
    pxBlock->pxNextFreeBlock = NULL;

    /* 3️⃣ 将块重新插入空闲链表，保持地址顺序（便于合并） */
    if (xFreeListHead == NULL || (uint8_t *)pxBlock < (uint8_t *)xFreeListHead)
    {
        /* 插入链表头部 */
        pxBlock->pxNextFreeBlock = xFreeListHead;
        xFreeListHead = pxBlock;
    }
    else
    {
        /* 找到合适的位置 */
        pxIter = xFreeListHead;
        while (pxIter->pxNextFreeBlock != NULL &&
               (uint8_t *)pxIter->pxNextFreeBlock < (uint8_t *)pxBlock)
            pxIter = pxIter->pxNextFreeBlock;

        pxBlock->pxNextFreeBlock = pxIter->pxNextFreeBlock;
        pxIter->pxNextFreeBlock = pxBlock;
    }

    /* 4️⃣ 合并相邻空闲块（前向 & 后向） */
    pxPrev = NULL;
    pxIter = xFreeListHead;

    while (pxIter != NULL)
    {
        uint8_t *block_end = (uint8_t *)pxIter + (pxIter->xBlockSize & BLOCK_SIZE_MASK);
        /* 若下一个块紧挨着当前块，则合并 */
        if (pxIter->pxNextFreeBlock != NULL &&
            (uint8_t *)pxIter->pxNextFreeBlock == block_end)
        {
            /* 合并：当前块的大小 + 下一个块的大小 */
            pxIter->xBlockSize = (pxIter->xBlockSize & BLOCK_SIZE_MASK) +
                                 (pxIter->pxNextFreeBlock->xBlockSize & BLOCK_SIZE_MASK);
            pxIter->pxNextFreeBlock = pxIter->pxNextFreeBlock->pxNextFreeBlock;
            continue;   /* 继续检查是否还能合并 */
        }
        pxPrev = pxIter;
        pxIter = pxIter->pxNextFreeBlock;
    }
}

/* ------------------------------------------------------------------
 * 9. 辅助函数：返回当前堆剩余可用字节数（调试/监控用）
 * ------------------------------------------------------------------ */
size_t tiny_heap_free_space(void)
{
    size_t total = 0;
    BlockLink_t *px = xFreeListHead;

    while (px != NULL)
    {
        total += (px->xBlockSize & BLOCK_SIZE_MASK);
        px = px->pxNextFreeBlock;
    }
    return total;
}

/* ------------------------------------------------------------------
 * 10. 示例：在系统启动时调用初始化
 * ------------------------------------------------------------------ */
#if defined(__GNUC__)   /* GCC: 使用构造函数属性在 main 之前执行 */
__attribute__((constructor))
static void __tiny_heap_auto_init(void)
{
    tiny_heap_init();
}
#endif
```

**使用方式**（类似 `malloc`/`free`）：

```c
#include "tiny_heap.h"
#include <stdio.h>

void demo(void)
{
    char *buf = (char *)tiny_malloc(100);   // 分配 100 字节
    if (buf)
    {
        snprintf(buf, 100, "Hello Embedded OS");
        puts(buf);
    }

    printf("Free before free: %zu bytes\n", tiny_heap_free_space());
    tiny_free(buf);
    printf("Free after free: %zu bytes\n", tiny_heap_free_space());
}
```

**优点**：

- **确定性**（最坏情况 O(N) 但 N==空闲块数，通常非常小）。
- **低开销**：只需要 8‑byte 头部和一次遍历。
- **可预见的最大碎片**（因为我们在 `free` 时尝试合并）。

**局限**：

- 对 **大量小块**（如 10~20 bytes）频繁分配/释放时仍可能产生**内部碎片**。
- 需要 **手动初始化**（`tiny_heap_init`），虽然可以用 `constructor` 自动完成。

