### 2.2 更高效的两级适配器（TLSF）— 适合实时系统

如果你的系统对 **分配/释放延迟有毫秒级甚至微秒级的严格要求**，可以使用 **TLSF（Two‑Level Segregated Fit）**。下面给出 **简化版的 TLSF**，核心思路是把 **块大小分成两层索引**（`FL`=第一层，`SL`=第二层），查询/插入都是 **O(1)**。

> **注**：完整实现大约 400 行，下面只保留关键结构、初始化、分配、释放函数，供你快速上手。完整源码（MIT）可以在 GitHub `yarrick/tlsf` 或 `micropython` 中找到。

```c
/* tlsf.c ---------------------------------------------------------- */
/* 参考：TLSF V2.1 实现，已将所有平台相关代码抽象，只保留核心 */
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

#define TLSF_FL_BITS   5   /* 0..31  -> 支持最大 2^31 块 */
#define TLSF_SL_BITS   5   /* 每个 FL 有 32 个 SL */

/* 通过宏计算位图尺寸 */
#define TLSF_FL_COUNT  (1U << TLSF_FL_BITS)   /* 32 */
#define TLSF_SL_COUNT  (1U << TLSF_SL_BITS)   /* 32 */
#define TLSF_MAX_BLOCK_SIZE   ((size_t)1 << (TLSF_FL_BITS + TLSF_SL_BITS + 3))  /* 约 2GB */

/* 对齐宏 */
#define ALIGN_SIZE 8U
#define ALIGN_MASK (ALIGN_SIZE - 1U)
#define ALIGN_UP(s)   (((s) + ALIGN_MASK) & ~ALIGN_MASK)

/* 块头结构体（无额外状态位，只用 size & prev_free） */
typedef struct BlockHdr
{
    size_t          size;               /* 包含自身的大小，最低位 1 表示前块空闲 */
    struct BlockHdr *prev_phys_block;   /* 前一个块（用于合并） */
    struct BlockHdr *next_free;         /* 链表指针（只在空闲块中有效） */
    struct BlockHdr *prev_free;         /* 双向链表 */
} BlockHdr_t;

/* TLSF 控制结构体 */
typedef struct
{
    BlockHdr_t *free_list[TLSF_FL_COUNT][TLSF_SL_COUNT];
    uint32_t fl_bitmap;                     /* 每位表示该 FL 是否非空 */
    uint32_t sl_bitmap[TLSF_FL_COUNT];      /* 每位表示该 SL 是否非空 */
    BlockHdr_t *pool_start;
    BlockHdr_t *pool_end;
} TLSF_t;

/* ---------------------- 位图操作 ---------------------- */
static inline void set_bit(uint32_t *map, uint32_t idx)   { *map |= (1U << idx); }
static inline void clear_bit(uint32_t *map, uint32_t idx) { *map &= ~(1U << idx); }
static inline bool test_bit(uint32_t map, uint32_t idx)   { return (map & (1U << idx)) != 0; }

/* ---------------------- FL/SL 计算 ---------------------- */
static inline int fls(uint32_t x)        /* Find Last Set (返回最高 1 位的下标，从 0 开始) */
{
    int r = 0;
    while (x >>= 1) ++r;
    return r;
}

/* 根据块大小得到对应的 FL/SL */
static inline void mapping_search(size_t size, int *fl, int *sl)
{
    size_t aligned = ALIGN_UP(size);
    if (aligned < (1U << (TLSF_SL_BITS + 3)))   /* 小于最小块 (32 bytes)——直接放在 FL=0 */
    {
        *fl = 0;
        *sl = aligned >> 3;     /* 8-byte 对齐后直接取 SL */
    }
    else
    {
        int f = fls((uint32_t)(aligned >> (TLSF_SL_BITS + 3)));
        *fl = f;
        *sl = (aligned >> (f + 3)) & (TLSF_SL_COUNT - 1);
    }
}

/* ---------------------- 初始化 ---------------------- */
static void tlsf_insert_block(TLSF_t *tlsf, BlockHdr_t *block)
{
    int fl, sl;
    mapping_search(block->size, &fl, &sl);
    block->next_free = tlsf->free_list[fl][sl];
    block->prev_free = NULL;
    if (tlsf->free_list[fl][sl] != NULL)
        tlsf->free_list[fl][sl]->prev_free = block;
    tlsf->free_list[fl][sl] = block;

    set_bit(&tlsf->sl_bitmap[fl], sl);
    set_bit(&tlsf->fl_bitmap, fl);
}

static void tlsf_remove_block(TLSF_t *tlsf, BlockHdr_t *block)
{
    int fl, sl;
    mapping_search(block->size, &fl, &sl);
    if (block->prev_free)
        block->prev_free->next_free = block->next_free;
    if (block->next_free)
        block->next_free->prev_free = block->prev_free;
    if (tlsf->free_list[fl][sl] == block)
        tlsf->free_list[fl][sl] = block->next_free;

    /* 如果该 SL 现在为空，清位 */
    if (tlsf->free_list[fl][sl] == NULL)
        clear_bit(&tlsf->sl_bitmap[fl], sl);
    /* 如果该 FL 所有 SL 都为空，清位 */
    if (tlsf->sl_bitmap[fl] == 0)
        clear_bit(&tlsf->fl_bitmap, fl);
}

/* 将整个堆转化成一个大空闲块 */
void tlsf_init(TLSF_t *tlsf, void *mem, size_t size)
{
    /* 清零所有域 */
    for (int i = 0; i < TLSF_FL_COUNT; ++i) {
        for (int j = 0; j < TLSF_SL_COUNT; ++j)
            tlsf->free_list[i][j] = NULL;
        tlsf->sl_bitmap[i] = 0;
    }
    tlsf->fl_bitmap = 0;
    tlsf->pool_start = (BlockHdr_t *)mem;
    tlsf->pool_end   = (BlockHdr_t *)((uint8_t *)mem + size);

    /* 建立第一个大块（标记为“空闲”） */
    BlockHdr_t *first = tlsf->pool_start;
    first->size = size;
    first->prev_phys_block = NULL;
    first->next_free = first->prev_free = NULL;
    tlsf_insert_block(tlsf, first);
}

/* ---------------------- 分配 -------------------------- */
static BlockHdr_t *tlsf_find_suitable_block(TLSF_t *tlsf, size_t size)
{
    int fl, sl;
    mapping_search(size, &fl, &sl);

    uint32_t sl_map = tlsf->sl_bitmap[fl] & (~0U << sl);
    int fl_search = fl;
    /* 若当前 FL 中没有足够的大块，向高位 FL 搜索 */
    if (sl_map == 0) {
        uint32_t fl_map = tlsf->fl_bitmap & (~0U << (fl + 1));
        if (fl_map == 0) return NULL;    /* 完全没有空闲块 */
        fl_search = fls(fl_map);
        sl_map = tlsf->sl_bitmap[fl_search];
    }
    int sl_search = fls(sl_map);   /* 找到第一个满足的 SL */
    return tlsf->free_list[fl_search][sl_search];
}

/* 真实的分配实现：可能会把块拆分成两块 */
void *tlsf_malloc(TLSF_t *tlsf, size_t size)
{
    size_t need = ALIGN_UP(size) + sizeof(BlockHdr_t);
    BlockHdr_t *block = tlsf_find_suitable_block(tlsf, need);
    if (!block) return NULL;   /* OOM */

    tlsf_remove_block(tlsf, block);

    /* 拆分（如果剩余空间仍然大于最小块大小） */
    size_t remain = (block->size & ~1U) - need;
    if (remain >= (sizeof(BlockHdr_t) + ALIGN_SIZE)) {
        BlockHdr_t *newblk = (BlockHdr_t *)((uint8_t *)block + need);
        newblk->size = remain;
        newblk->prev_phys_block = block;
        newblk->next_free = newblk->prev_free = NULL;
        block->size = need | (block->size & 1U);   /* 只保留前块空闲标记 */
        tlsf_insert_block(tlsf, newblk);
    } else {
        need = block->size & ~1U;   /* 整块使用 */
    }

    block->size |= 1U;        /* 标记为已分配（前块空闲位） */
    return (void *)((uint8_t *)block + sizeof(BlockHdr_t));
}

/* ---------------------- 释放 -------------------------- */
void tlsf_free(TLSF_t *tlsf, void *ptr)
{
    if (!ptr) return;
    BlockHdr_t *block = (BlockHdr_t *)((uint8_t *)ptr - sizeof(BlockHdr_t));
    block->size &= ~1U;               /* 清除已分配标记 */

    /* 合并前向块（如果前块空闲） */
    if (block->prev_phys_block && !(block->prev_phys_block->size & 1U)) {
        BlockHdr_t *prev = block->prev_phys_block;
        tlsf_remove_block(tlsf, prev);
        prev->size += block->size;
        block = prev;
    }

    /* 合并后向块（如果后块空闲） */
    BlockHdr_t *next = (BlockHdr_t *)((uint8_t *)block + (block->size & ~1U));
    if ((uint8_t *)next < (uint8_t *)tlsf->pool_end && !(next->size & 1U)) {
        tlsf_remove_block(tlsf, next);
        block->size += next->size;
    }

    tlsf_insert_block(tlsf, block);
}

/* ---------------------- 示例 --------------------------- */
#if defined(TEST_TLSF)
#include <stdio.h>
int main(void)
{
    static uint8_t pool[32 * 1024];
    TLSF_t mytlsf;
    tlsf_init(&mytlsf, pool, sizeof(pool));

    void *p1 = tlsf_malloc(&mytlsf, 100);
    void *p2 = tlsf_malloc(&mytlsf, 500);
    printf("p1=%p p2=%p\n", p1, p2);

    tlsf_free(&mytlsf, p1);
    tlsf_free(&mytlsf, p2);

    void *p3 = tlsf_malloc(&mytlsf, 1024);
    printf("p3=%p\n", p3);
    return 0;
}
#endif
```

**特点一眼看出**：

| 特性 | 描述 |
|------|------|
| **分配/释放时间** | **O(1)**（仅两次位图查询） |
| **内部碎片** | **极低**（块大小严格对应 8‑byte 对齐） |
| **实现复杂度** | 代码稍长，但**只在系统初始化一次**，后续运行时强度极低 |
| **适用场景** | 对 **实时性** 要求极高、**大量小块** 且**频繁** 的系统（工业控制、车规 MCU） |

