## 1. Serwer (UDP)

```c
/* ------------------------------------------------------------
 *  udp_server.c – prosty serwer UDP
 *  Nasłuchuje na porcie >4000, odbiera ciąg znaków,
 *  zmienia go na duże litery i odsyła do nadawcy.
 * ------------------------------------------------------------ */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>          // toupper()
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <errno.h>

#define SERVER_PORT 5000            // dowolny > 4000
#define BUF_SIZE    1024

/* Funkcja zamienia ciąg znaków na wielkie litery */
static void to_uppercase(char *buf, ssize_t len)
{
    for (ssize_t i = 0; i < len; ++i)
        buf[i] = (char) toupper((unsigned char)buf[i]);
}

int main(void)
{
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    char buffer[BUF_SIZE];
    socklen_t client_len;
    ssize_t nbytes;

    /* --------------------------------------------------------
     *  1. Utworzenie gniazda UDP
     * -------------------------------------------------------- */
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket() error");
        exit(EXIT_FAILURE);
    }

    /* --------------------------------------------------------
     *  2. Wiązanie gniazda z portem (INADDR_ANY – wszystkie
     *     dostępne interfejsy)
     * -------------------------------------------------------- */
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family      = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port        = htons(SERVER_PORT);

    if (bind(sockfd,
             (struct sockaddr *)&server_addr,
             sizeof(server_addr)) < 0) {
        perror("bind() error");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("UDP server listening on port %d ...\n", SERVER_PORT);

    /* --------------------------------------------------------
     *  3. Pętla nieskończona – odbieramy, przetwarzamy,
     *     odsyłamy
     * -------------------------------------------------------- */
    while (1) {
        client_len = sizeof(client_addr);
        nbytes = recvfrom(sockfd,
                          buffer,
                          BUF_SIZE,
                          0,
                          (struct sockaddr *)&client_addr,
                          &client_len);
        if (nbytes < 0) {
            perror("recvfrom() error");
            continue;               // nie przerywamy działania serwera
        }

        /* Dodajemy znak zakończenia, aby można było używać jako string */
        if (nbytes < BUF_SIZE)
            buffer[nbytes] = '\0';
        else
            buffer[BUF_SIZE-1] = '\0';

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr,
                  client_ip, sizeof(client_ip));
        printf("Received %zd bytes from %s:%d : \"%s\"\n",
               nbytes, client_ip, ntohs(client_addr.sin_port), buffer);

        /* 4. Konwersja na wielkie litery */
        to_uppercase(buffer, nbytes);

        /* 5. Odpowiedź do nadawcy */
        if (sendto(sockfd,
                   buffer,
                   nbytes,
                   0,
                   (struct sockaddr *)&client_addr,
                   client_len) < 0) {
            perror("sendto() error");
        } else {
            printf("Sent back \"%s\"\n", buffer);
        }
    }

    /* Nigdy nie zostanie wykonane, ale warto mieć porządek */
    close(sockfd);
    return 0;
}
```

