 * ------------------------------------------------------------ */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define SERVER_PORT 5000            // musi być taki sam jak w serwerze
#define BUF_SIZE    1024
#define DEFAULT_NAME "Jan Kowalski" // można zmienić lub podać w args

int main(int argc, char *argv[])
{
    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[BUF_SIZE];
    ssize_t nbytes;
    socklen_t server_len;

    /* --------------------------------------------------------
     *  1. Przygotowanie danych (imię i nazwisko)
     * -------------------------------------------------------- */
    const char *name = (argc > 1) ? argv[1] : DEFAULT_NAME;
    size_t name_len = strlen(name);
    if (name_len >= BUF_SIZE) {
        fprintf(stderr, "Name is too long (max %d characters)\n", BUF_SIZE-1);
        exit(EXIT_FAILURE);
    }

    /* --------------------------------------------------------
     *  2. Utworzenie gniazda UDP
     * -------------------------------------------------------- */
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket() error");
        exit(EXIT_FAILURE);
    }

    /* --------------------------------------------------------
     *  3. Uzupełnienie struktury adresu serwera
     * -------------------------------------------------------- */
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port   = htons(SERVER_PORT);

    /* Wpisz tutaj adres IP serwera (płytki) */
    const char *server_ip = "192.168.1.42";   // <-- zmień na własny
    if (inet_pton(AF_INET, server_ip,
                  &server_addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid server IP address: %s\n", server_ip);
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* --------------------------------------------------------
     *  4. Wysłanie datagramu (imię i nazwisko)
     * -------------------------------------------------------- */
    if (sendto(sockfd,
               name,
               name_len,
               0,
               (struct sockaddr *)&server_addr,
               sizeof(server_addr)) != (ssize_t)name_len) {
        perror("sendto() error");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    printf("Sent \"%s\" to %s:%d\n", name, server_ip, SERVER_PORT);

    /* --------------------------------------------------------
     *  5. Oczekiwanie na odpowiedź
     * -------------------------------------------------------- */
    server_len = sizeof(server_addr);
    nbytes = recvfrom(sockfd,
                      buffer,
                      BUF_SIZE - 1,
                      0,
                      (struct sockaddr *)&server_addr,
                      &server_len);
    if (nbytes < 0) {
        perror("recvfrom() error");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    buffer[nbytes] = '\0';       // zakończenie stringa
    printf("Received reply: \"%s\"\n", buffer);

    close(sockfd);
    return 0;
}
```

### Kompilacja i uruchomienie klienta

```bash
gcc -Wall -O2 -o udp_client udp_client.c
./udp_client               # użyje domyślnego "Jan Kowalski"
# lub podać własne imię i nazwisko jako argument:
./udp_client "Anna Nowak"
```

> **Ważne!** – w linii `const char *server_ip = "192.168.1.42";`
> wpisz rzeczywisty adres IP płytki, na której działa serwer.  
> (Jeśli uruchamiasz oba programy na tym samym komputerze, możesz
> użyć `127.0.0.1`.)

-------------------------------------------------------------------
## 3. Kroki testowe (cały proces)

1. **Sprawdź adres IP serwera**  
   ```bash
   $ ip addr          # znajdź np. 192.168.1.42/24 przy interfejsie wlan0
   ```
2. **Skopiuj serwer na płytkę** (jeśli kompilujesz tam) i uruchom:  
   ```bash
   $ gcc -Wall -O2 -o udp_server udp_server.c
   $ sudo ./udp_server
   ```
   Na konsoli płytki powinno pojawić się:  
   `UDP server listening on port 5000 ...`

3. **Skopiuj klienta na komputer PC (lub odwrotnie)** i skompiluj:  
   ```bash
   $ gcc -Wall -O2 -o udp_client udp_client.c
   ```
4. **Uruchom klienta**, podając adres IP serwera:  
   ```bash
   $ ./udp_client "Marek Skowron"
   Sent "Marek Skowron" to 192.168.1.42:5000
   Received reply: "MAREK SKOWRON"
   ```
5. **Sprawdź wyjście serwera** – powinno wypisać odebraną wiadomość i
   odsyłany tekst.

-------------------------------------------------------------------
## 4. Co się dzieje „pod maską”

| Krok | Co robi kod                | Systemowe wywołania |
|------|---------------------------|---------------------|
| **socket** | tworzy gniazdo typu `SOCK_DGRAM` (UDP) | `socket(AF_INET, SOCK_DGRAM, 0)` |
| **bind** _(serwer)_ | przydziela port i „przyczepia” gniazdo do wszystkich interfejsów | `bind()` |
| **sendto** | wysyła datagram do podanego adresu | `sendto()` |
| **recvfrom** | blokuje, oczekuje na przybycie datagramu, zwraca adres nadawcy | `recvfrom()` |
| **inet_pton / inet_ntop** | konwersja tekstowego IP ↔ struktura binarna | `inet_pton()`, `inet_ntop()` |
| **toupper** | zamiana znaków na wielkie litery | `toupper()` z `<ctype.h>` |
| **close** | zamyka gniazdo, zwalnia zasoby | `close()` |

UDP jest **bezpołączeniowy**, więc nie ma potrzeby wykonywania
`connect()`. Każdy `recvfrom()` zwraca adres nadawcy – dzięki temu
serwer wie, dokąd ma odsyłać odpowiedź, nawet jeśli klient znajduje się
w innym pod‑sieci.

-------------------------------------------------------------------
## 5. Częste problemy i ich rozwiązania

| Problem | Przyczyna | Rozwiązanie |
|---------|-----------|-------------|
| **„Connection timed out” / brak odpowiedzi** | Zły adres IP, zapora sieciowa, różne podsieci | Sprawdź `ip addr` po obu stronach; wyłącz `ufw`/`firewalld` albo dodaj regułę zezwalającą na UDP port 5000 |
| **„Message too long”** | Wysłany bufor > `BUF_SIZE` | Zwiększ `BUF_SIZE` lub ogranicz długość tekstu (np. 100 znaków) |
| **„Permission denied” przy `bind`** | Port < 1024 (systemowy) | Użyj portu > 4000 (np. 5000) albo uruchom z uprawnieniami root |
| **„Invalid argument” przy `inet_pton`** | Niewłaściwy format IP (np. literówka) | `192.168.1.42` – 4 liczby oddzielone kropkami |
| **Nie widać wypisów na serwerze** | Uruchomiono program w tle albo z `nohup` i wyjście nie jest przekierowane | Uruchom w terminalu lub dodaj `printf`/`fflush(stdout)` po wypisaniu |

-------------------------------------------------------------------
## 6. Rozszerzenia (jeżeli chcesz dalej rozwijać projekt)

| Pomysł | Co trzeba dodać |
|--------|-----------------|
| **Obsługa wielu klientów jednocześnie** | UDP i tak jest bezpołączeniowy – serwer już obsługuje wielu nadawców (każdy pakiet jest niezależny). |
| **Zmienny port** | Przyjmuj port jako argument wiersza poleceń (`argv`). |
| **Zabezpieczenia** | Dodaj proste „shared secret” – klient wysyła dodatkowy token, serwer go weryfikuje. |
| **Logowanie do pliku** | `fprintf(logfile, ...)`. |
| **Komunikacja TCP** | Zmien `SOCK_DGRAM` → `SOCK_STREAM`, dodaj `listen()`, `accept()` w serwerze i `connect()` w kliencie. |
| **Obsługa znaków spoza ASCII** (np. polskie litery) | Użyj kodowania UTF‑8 i funkcji `mbtowc`/`towlower`, ale w prostych przypadkach `toupper` wystarczy. |

-------------------------------------------------------------------
## 7. Podsumowanie

* **Serwer** (UDP) nasłuchuje na porcie > 4000, przyjmuje dowolny tekst,
  zamienia go na wielkie litery i odsyła tę samą wiadomość do nadawcy.
* **Klient** (UDP) wysyła w jednej wiadomości imię i nazwisko,
  odbiera odpowiedź i wyświetla ją.
* Całość opiera się wyłącznie na standardowych wywołaniach POSIX
  (`socket`, `bind`, `sendto`, `recvfrom`) – kod jest przenośny,
  skompilowany w GCC pod Linux.
* Adres serwera uzyskuje się poleceniem `ip addr`.  
* Programy można uruchamiać na dowolnych platformach z obsługą gniazd
  (np. PC – Linux, Raspberry Pi, inne mikrokontrolery z IP).

