/*********************************************************************
 *  Пример реализации функции fullTree
 *  ---------------------------------------------------------------
 *  Требования:
 *      • Есть готовая функция
 *            void AddNode(Node *&root, int data);
 *        – она вставляет один элемент в бинарное дерево (по
 *          правилам BST или любой другой логике, которой она
 *          реализована).
 *      • Нужно написать функцию, которая создаст дерево с
 *        произвольным числом узлов.
 *
 *  Ниже приведён минимальный набор объявлений структуры узла,
 *  прототипов функций и сама реализация fullTree.
 *********************************************************************/

#include <iostream>
#include <vector>
#include <random>   // std::mt19937, std::uniform_int_distribution
#include <ctime>    // std::time

/*--------------------------------------------------------------
 *  Структура узла бинарного дерева
 *  -----------------------------------------------------------*/
struct Node
{
    int   data;   // значение узла
    Node *left;   // левый потомок
    Node *right;  // правый потомок

    Node(int v) : data(v), left(nullptr), right(nullptr) {}
};

/*--------------------------------------------------------------
 *  Прототип готовой функции вставки.  Реализацию вы пишете
 *  самостоятельно (или получаете откуда‑нибудь).  Здесь
 *  показана простая реализация вставки в BST.
 *  -----------------------------------------------------------*/
void AddNode(Node *&root, int data)
{
    if (root == nullptr)                // пустое дерево – создаём корень
    {
        root = new Node(data);
        return;
    }

    // Для простоты реализуем обычное BST (меньше – влево, больше – вправо)
    if (data < root->data)
        AddNode(root->left, data);
    else
        AddNode(root->right, data);
}

/*--------------------------------------------------------------
 *  Функция fullTree
 *
 *  Параметры:
 *      - root   : ссылка на указатель корня дерева.
 *      - count  : сколько узлов нужно добавить.
 *      - minVal : нижняя граница генерируемых значений (по умолчанию 0).
 *      - maxVal : верхняя граница генерируемых значений (по умолчанию 99).
 *
 *  Что делает:
 *      1. Инициализирует генератор случайных чисел (один раз за процесс
 *         жизни программы, а не при каждом вызове функции).
 *      2. Генерирует `count` случайных целых чисел в диапазоне
 *         [minVal, maxVal].
 *      3. Для каждого числа вызывает готовую функцию AddNode(root, value).
 *
 *  Замечание:
 *      Если вам нужен не случайный набор, а, скажем, последовательный
 *      1,2,3,…, то вместо генерации случайных чисел просто передавайте
 *      эти значения в цикл.
 *  -----------------------------------------------------------*/
void fullTree(Node *&root,
              std::size_t count,
              int minVal = 0,
              int maxVal = 99)
{
    // Если диапазон задан неверно – поправим его, чтобы не падать
    if (minVal > maxVal) std::swap(minVal, maxVal);

    // Статический объект генератора – будет инициализирован один раз
    static std::mt19937 rng(static_cast<unsigned>(std::time(nullptr)));
    std::uniform_int_distribution<int> dist(minVal, maxVal);

    for (std::size_t i = 0; i < count; ++i)
    {
        int value = dist(rng);   // получаем случайное число
        AddNode(root, value);    // вставляем в дерево
    }
}

/*--------------------------------------------------------------
 *  Вспомогательная функция для печати дерева (симметричный обход)
 *  -----------------------------------------------------------*/
void InOrderPrint(const Node *node)
{
    if (!node) return;
    InOrderPrint(node->left);
    std::cout << node->data << ' ';
    InOrderPrint(node->right);
}

/*--------------------------------------------------------------
 *  Пример использования
 *  -----------------------------------------------------------*/
int main()
{
    Node *root = nullptr;                 // дерево пусто
    const std::size_t N = 15;             // захотим 15 узлов

    // Заполняем дерево произвольным набором элементов
    fullTree(root, N, 10, 200);           // значения от 10 до 200

    std::cout << "In‑order traversal of the built tree:\n";
    InOrderPrint(root);
    std::cout << '\n';

    // (Не забывайте освобождать память – здесь это опущено для
    //  краткости, но в реальном коде следует реализовать функцию
    //  DeleteTree(root); )
    return 0;
}
```

### Как это работает

1. **`Node`** – простая структура, представляющая один элемент дерева.
2. **`AddNode`** – готовая (или ваша) функция вставки. В примере реализована
   обычная вставка в бинарное дерево поиска (BST). Если у вас другая
   логика вставки, просто замените её.
3. **`fullTree`**  
   * При первом вызове статический генератор `rng` инициализируется текущим
     временем, что гарантирует разный набор случайных чисел при разных запусках.  
   * Затем в цикле `count` раз генерируется случайное число из диапазона
     `[minVal, maxVal]` и сразу передаётся в `AddNode`.  
