**Unix‑Domain‑Socket (AF_UNIX) client – server example**  
The task is to write two programs in C :

* **server** – creates a stream socket in the Unix‑domain, waits for a
  connection, receives a text (first and last name), converts it to
  upper‑case and sends the result back.
* **client** – connects to the server socket, reads a name from *stdin*
  (or from the command line), sends it, receives the converted text
  and prints it.

The socket is created with the ordinary `socket()` call (not
`socketpair()`); the address family is `AF_UNIX` and the address type
is `struct sockaddr_un`.  
All errors are reported and the server removes the socket‑file when it
terminates.



--------------------------------------------------------------------
## 1. Common notes

* **Maximum message length** – we limit it to 256 bytes (enough for a
  name).  
* **Blocking I/O** – both sides use the default blocking mode, which is
  sufficient for a simple request/answer exchange.
* **Upper‑case conversion** – `toupper()` from `<ctype.h>`.
* **Compilation**

```bash
gcc -Wall -Wextra -O2 -o server server.c
gcc -Wall -Wextra -O2 -o client client.c
```

* **Run**

```bash
# one terminal
./server /tmp/my_unix_socket

# another terminal
./client /tmp/my_unix_socket "Jan Kowalski"
```

The client can also read the name from *stdin* if the argument is omitted.

--------------------------------------------------------------------
## 2. Server (`server.c`)

```c
/*  server.c - Unix‑domain‑socket echo server that returns the text in
 *  upper‑case.
 *
 *  Compile:  gcc -Wall -Wextra -O2 -o server server.c
 *
 *  Usage:    ./server <socket_path>
 *
 *  The server creates a stream socket (SOCK_STREAM) in the Unix
 *  domain, binds it to <socket_path>, listens, accepts one client,
 *  processes the request and then exits.  You can easily turn the
 *  loop into a multi‑client server – this example keeps it simple.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ctype.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <errno.h>
#include <signal.h>

#define BUF_SIZE 256

static const char *socket_path = NULL;

/* Remove the socket file when the program terminates */
static void cleanup(void)
{
    if (socket_path)
        unlink(socket_path);
}

/* Catch SIGINT / SIGTERM to guarantee cleanup */
static void sig_handler(int signo)
{
    (void)signo;   /* unused */
    exit(EXIT_SUCCESS);
}

/* Convert a NUL‑terminated string to upper case (in‑place) */
static void str_toupper(char *s)
{
    for ( ; *s; ++s)
        *s = (char) toupper((unsigned char)*s);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <socket_path>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    socket_path = argv[1];

    /* Register cleanup & signal handling */
    atexit(cleanup);
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* 1. Create socket */
    int listen_fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (listen_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* 2. Make sure the socket file does not already exist */
    unlink(socket_path);

    /* 3. Bind */
    struct sockaddr_un addr;
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, socket_path, sizeof(addr.sun_path) - 1);

    if (bind(listen_fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1) {
        perror("bind");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 4. Listen */
    if (listen(listen_fd, 5) == -1) {
        perror("listen");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on %s …\n", socket_path);

    /* 5. Accept one connection (loop can be added for many) */
    for (;;) {
        int conn_fd = accept(listen_fd, NULL, NULL);
        if (conn_fd == -1) {
            /* EINTR is normal when a signal interrupts accept() */
            if (errno == EINTR)
                continue;
            perror("accept");
            break;
        }

        char buf[BUF_SIZE];
        ssize_t n = recv(conn_fd, buf, sizeof(buf) - 1, 0);
        if (n <= 0) {
            if (n == 0)
                fprintf(stderr, "client closed connection unexpectedly\n");
            else
                perror("recv");
            close(conn_fd);
            continue;
        }

        buf[n] = '\0';                 /* NUL‑terminate */
        printf("Received: \"%s\"\n", buf);

        /* 6. Convert to upper case */
        str_toupper(buf);

        /* 7. Send the result back */
        ssize_t sent = send(conn_fd, buf, strlen(buf), 0);
        if (sent == -1)
            perror("send");

        close(conn_fd);               /* close this client */
        printf("Processed one request – waiting for next …\n");
    }

    close(listen_fd);
    return 0;
}
```

### What the server does

1. **Create** a stream socket (`socket(AF_UNIX, SOCK_STREAM, 0)`).
2. **Bind** it to the pathname supplied on the command line.
3. **Listen** for incoming connections.
4. **Accept** a client, read up to `BUF_SIZE‑1` bytes, NUL‑terminate,
   convert the string to upper case, **send** it back and close the
   connection.
5. Loop forever (you can stop it with `Ctrl‑C`).  
   The socket file is removed automatically on exit (`atexit()`).

--------------------------------------------------------------------
## 3. Client (`client.c`)

```c
/*  client.c - Connects to a Unix‑domain‑socket server, sends a name
 *  (first + last), receives the upper‑case version and prints it.
 *
 *  Compile:  gcc -Wall -Wextra -O2 -o client client.c
 *
 *  Usage:    ./client <socket_path> [name]
 *
 *  If the name is omitted the program reads a line from stdin.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <errno.h>

#define BUF_SIZE 256

int main(int argc, char *argv[])
{
    if (argc < 2 || argc > 3) {
        fprintf(stderr, "Usage: %s <socket_path> [name]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *socket_path = argv[1];
    char name[BUF_SIZE];

    if (argc == 3) {
        strncpy(name, argv[2], sizeof(name) - 1);
        name[sizeof(name) - 1] = '\0';
    } else {
        /* read a line from stdin */
        if (!fgets(name, sizeof(name), stdin)) {
            perror("fgets");
            exit(EXIT_FAILURE);
        }
        /* remove possible trailing newline */
        name[strcspn(name, "\n")] = '\0';
    }

    /* 1. Create a stream socket */
    int fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* 2. Build server address */
    struct sockaddr_un addr;
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, socket_path, sizeof(addr.sun_path) - 1);

    /* 3. Connect */
    if (connect(fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1) {
        perror("connect");
        close(fd);
        exit(EXIT_FAILURE);
    }

    /* 4. Send the name */
    size_t len = strlen(name);
    if (send(fd, name, len, 0) != (ssize_t)len) {
        perror("send");
        close(fd);
        exit(EXIT_FAILURE);
    }

    /* 5. Receive the upper‑case response */
    char buf[BUF_SIZE];
    ssize_t n = recv(fd, buf, sizeof(buf) - 1, 0);
    if (n <= 0) {
        if (n == 0)
            fprintf(stderr, "Server closed connection\n");
        else
            perror("recv");
        close(fd);
        exit(EXIT_FAILURE);
    }
    buf[n] = '\0';

    printf("Server replied: %s\n", buf);

    close(fd);
    return 0;
}
```

### What the client does

1. Builds a **Unix‑domain** socket address (`sockaddr_un`) with the same
   pathname that the server uses.
2. Calls `connect()` – this establishes a single TCP‑like stream
   connection over the filesystem.
3. Sends the name string (`send()`).
4. Waits for the reply (`recv()`), prints it and exits.

--------------------------------------------------------------------
## 4. Testing the program

```bash
# Terminal 1 – start the server
$ ./server /tmp/example.sock
Server listening on /tmp/example.sock …
```

```bash
# Terminal 2 – run a client
$ ./client /tmp/example.sock "Anna Nowak"
Server replied: ANNA NOWAK
```

You can launch several clients one after another – the server will
accept each, process it, and keep listening.

--------------------------------------------------------------------
## 5. Extending the example (optional)

* **Multiple concurrent clients** – replace the simple `for(;;){ accept… }`
  loop with `fork()` / `pthread_create()` after `accept()`, or use
  `select()/poll()` on the listening socket.
* **Protocol** – prepend the length of the message, or use a
  newline‑terminated line (`getline()`), to allow sending larger data.
* **Graceful shutdown** – add a signal handler that closes the listening
  socket before exiting; `cleanup()` already removes the socket file.

--------------------------------------------------------------------
