```c
/********************************************************************
 *  Diary Management System   (C99)
 *  功能：添加、修改、删除、浏览、查询、密码保护、密码修改
 *  数据持久化：二进制文件 diary.dat、password.dat
 ********************************************************************/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define DIARY_FILE    "diary.dat"
#define PASS_FILE     "password.dat"

#define KEYWORD_MAX   32
#define CONTENT_MAX   512
#define INPUT_BUF    1024      /* 辅助读取行的临时缓冲区 */

/* ---------- 数据结构 ---------- */
typedef struct {
    int year, month, day;               /* 日期 */
} Date;

typedef struct {
    Date   date;                        /* 日期 */
    char   keyword[KEYWORD_MAX];        /* 关键字 */
    char   content[CONTENT_MAX];        /* 正文 */
} DiaryEntry;

/* ---------- 全局变量 ---------- */
DiaryEntry *g_entries = NULL;   /* 动态数组 */
int         g_cnt     = 0;      /* 当前条目数 */

/* ---------- 工具函数 ---------- */

/* 去除字符串末尾的换行符 */
static void trim_newline(char *s) {
    size_t n = strlen(s);
    if (n && (s[n-1] == '\n' || s[n-1] == '\r')) s[n-1] = '\0';
}

/* 简单的 BKDR 哈希（用于密码） */
static unsigned long hash_password(const char *pwd) {
    unsigned long seed = 131;
    unsigned long hash = 0;
    while (*pwd) hash = hash * seed + (unsigned char)(*pwd++);
    return hash;
}

/* 读取一行（带缓冲） */
static void read_line(char *buf, size_t sz) {
    if (fgets(buf, (int)sz, stdin) == NULL) {
        buf[0] = '\0';
        return;
    }
    trim_newline(buf);
}

/* 日期比较：<0 表示 a<b，=0 表示相等，>0 表示 a>b */
static int date_cmp(const Date *a, const Date *b) {
    if (a->year  != b->year)  return a->year  - b->year;
    if (a->month != b->month) return a->month - b->month;
    return a->day - b->day;
}

/* qsort 用的比较函数（按日期升序） */
static int entry_cmp(const void *p1, const void *p2) {
    const DiaryEntry *e1 = (const DiaryEntry *)p1;
    const DiaryEntry *e2 = (const DiaryEntry *)p2;
    return date_cmp(&e1->date, &e2->date);
}

/* ---------- 文件 I/O ---------- */

/* 读取密码散列，如文件不存在返回 0（表示未设置） */
static unsigned long load_password_hash(void) {
    FILE *fp = fopen(PASS_FILE, "rb");
    if (!fp) return 0;
    unsigned long h = 0;
    fread(&h, sizeof(h), 1, fp);
    fclose(fp);
    return h;
}

/* 保存密码散列 */
static void save_password_hash(unsigned long h) {
    FILE *fp = fopen(PASS_FILE, "wb");
    if (!fp) {
        perror("打开 password.dat 失败");
        return;
    }
    fwrite(&h, sizeof(h), 1, fp);
    fclose(fp);
}

/* 初始密码（首次运行） */
static void init_password_if_needed(void) {
    unsigned long h = load_password_hash();
    if (h == 0) {      /* 文件不存在或空 */
        printf("系统首次运行，请设置管理员密码（默认 admin）\n");
        char pwd[INPUT_BUF];
        printf("请输入密码（回车确认）: ");
        read_line(pwd, sizeof(pwd));
        if (strlen(pwd) == 0) strcpy(pwd, "admin");
        save_password_hash(hash_password(pwd));
        printf("密码已设置，默认密码为 'admin'（若你直接回车）\n");
    }
}

/* 验证密码 */
static int verify_password(void) {
    init_password_if_needed();
    unsigned long stored = load_password_hash();
    char pwd[INPUT_BUF];
    printf("请输入系统密码: ");
    read_line(pwd, sizeof(pwd));
    if (hash_password(pwd) == stored) {
        return 1;
    } else {
        printf("密码错误！\n");
        return 0;
    }
}

/* 修改密码 */
static void change_password(void) {
    char oldpwd[INPUT_BUF], newpwd[INPUT_BUF], repeat[INPUT_BUF];
    unsigned long stored = load_password_hash();

    printf("请输入当前密码: ");
    read_line(oldpwd, sizeof(oldpwd));
    if (hash_password(oldpwd) != stored) {
        printf("当前密码错误，无法修改！\n");
        return;
    }

    printf("请输入新密码: ");
    read_line(newpwd, sizeof(newpwd));
    printf("请再次输入新密码: ");
    read_line(repeat, sizeof(repeat));

    if (strcmp(newpwd, repeat) != 0) {
        printf("两次输入不一致，修改取消。\n");
        return;
    }

    save_password_hash(hash_password(newpwd));
    printf("密码修改成功！\n");
}

/* 加载日记文件 */
static int load_diaries(void) {
    FILE *fp = fopen(DIARY_FILE, "rb");
    if (!fp) {
        g_cnt = 0;
        g_entries = NULL;
        return 0;               /* 文件不存在视为空库 */
    }

    int cnt = 0;
    if (fread(&cnt, sizeof(cnt), 1, fp) != 1) { fclose(fp); return -1; }
    if (cnt < 0) cnt = 0;

    DiaryEntry *arr = (DiaryEntry *)malloc(cnt * sizeof(DiaryEntry));
    if (!arr) { fclose(fp); return -1; }

    if (cnt > 0 && fread(arr, sizeof(DiaryEntry), cnt, fp) != (size_t)cnt) {
        free(arr);
        fclose(fp);
        return -1;
    }
    fclose(fp);

    g_cnt = cnt;
    g_entries = arr;
    qsort(g_entries, g_cnt, sizeof(DiaryEntry), entry_cmp);   /* 确保已排序 */
    return 0;
}

/* 保存日记文件 */
static int save_diaries(void) {
    FILE *fp = fopen(DIARY_FILE, "wb");
    if (!fp) {
        perror("打开 diary.dat 失败");
        return -1;
    }
    if (fwrite(&g_cnt, sizeof(g_cnt), 1, fp) != 1) { fclose(fp); return -1; }
    if (g_cnt > 0 && fwrite(g_entries, sizeof(DiaryEntry), g_cnt, fp) != (size_t)g_cnt) {
        fclose(fp); return -1;
    }
    fclose(fp);
    return 0;
}

/* ---------- 日记操作 ---------- */

/* 输入日期，返回 0 表示成功，1 表示格式错误 */
static int input_date(Date *d) {
    char buf[INPUT_BUF];
    printf("请输入日期 (YYYY-MM-DD): ");
    read_line(buf, sizeof(buf));
    if (sscanf(buf, "%d-%d-%d", &d->year, &d->month, &d->day) != 3) {
        printf("日期格式错误！\n");
        return 1;
    }
    if (d->month < 1 || d->month > 12 || d->day < 1 || d->day > 31) {
        printf("日期数值不合法！\n");
        return 1;
    }
    return 0;
}

/* 在数组中查找首个匹配日期（相等） */
static int find_entry_by_date(const Date *d) {
    for (int i = 0; i < g_cnt; ++i) {
        if (date_cmp(&g_entries[i].date, d) == 0)
            return i;
    }
    return -1;
}

/* 关键字查询返回匹配的下标集合（动态分配） */
static int *find_entries_by_keyword(const char *kw, int *out_cnt) {
    int *idx = NULL;
    int cnt = 0;
    for (int i = 0; i < g_cnt; ++i) {
        if (strstr(g_entries[i].keyword, kw) != NULL) {
            idx = (int *)realloc(idx, (cnt + 1) * sizeof(int));
            idx[cnt++] = i;
        }
    }
    *out_cnt = cnt;
    return idx;
}

/* 添加新日记 */
static void add_entry(void) {
    DiaryEntry newe;
    if (input_date(&newe.date) != 0) return;

    printf("请输入关键字 (不超过 %d 字符): ", KEYWORD_MAX-1);
    read_line(newe.keyword, KEYWORD_MAX);

    printf("请输入正文内容 (不超过 %d 字符，回车结束): ", CONTENT_MAX-1);
    read_line(newe.content, CONTENT_MAX);

    /* 扩容 */
    DiaryEntry *tmp = (DiaryEntry *)realloc(g_entries, (g_cnt + 1) * sizeof(DiaryEntry));
    if (!tmp) {
        printf("内存不足，添加失败！\n");
        return;
    }
    g_entries = tmp;
    g_entries[g_cnt] = newe;   /* 直接放在末尾 */
    ++g_cnt;

    /* 重新排序 */
    qsort(g_entries, g_cnt, sizeof(DiaryEntry), entry_cmp);
    printf("日记已添加并排序！\n");
}

/* 修改已有日记（按日期定位） */
static void modify_entry(void) {
    Date d;
    if (input_date(&d) != 0) return;
    int pos = find_entry_by_date(&d);
    if (pos < 0) {
        printf("未找到该日期的日记！\n");
        return;
    }
    printf("\n--- 当前内容 ---\n");
    printf("日期   : %04d-%02d-%02d\n", g_entries[pos].date.year,
           g_entries[pos].date.month, g_entries[pos].date.day);
    printf("关键字 : %s\n", g_entries[pos].keyword);
    printf("正文   : %s\n", g_entries[pos].content);
    printf("-----------------\n");

    printf("请输入新关键字 (留空不改): ");
    char buf[KEYWORD_MAX];
    read_line(buf, sizeof(buf));
    if (strlen(buf) > 0) strncpy(g_entries[pos].keyword, buf, KEYWORD_MAX-1);

    printf("请输入新正文 (留空不改): ");
    char cont[CONTENT_MAX];
    read_line(cont, sizeof(cont));
    if (strlen(cont) > 0) strncpy(g_entries[pos].content, cont, CONTENT_MAX-1);

    printf("修改完成！\n");
}

/* 删除日记（按日期或关键字） */
static void delete_entry(void) {
    printf("删除方式: 1. 按日期  2. 按关键字\n");
    char choice[INPUT_BUF];
    read_line(choice, sizeof(choice));
    if (choice[0] == '1') {
        Date d; 
        if (input_date(&d)!=0) return;
        int pos = find_entry_by_date(&d);
        if (pos < 0) { printf("未找到该日期的日记！\n"); return; }
        /* 删除 */
        for (int i = pos; i < g_cnt-1; ++i) g_entries[i] = g_entries[i+1];
        --g_cnt;
        g_entries = (DiaryEntry *)realloc(g_entries, g_cnt * sizeof(DiaryEntry));
        printf("已删除该条日记。\n");
    } else if (choice[0] == '2') {
        char kw[KEYWORD_MAX];
        printf("请输入关键字: ");
        read_line(kw, sizeof(kw));
        int cnt;
        int *idx = find_entries_by_keyword(kw, &cnt);
        if (cnt == 0) {
            printf("没有匹配的日记。\n");
            free(idx);
            return;
        }
        printf("共找到 %d 条匹配记录，是否全部删除? (y/n): ", cnt);
        char confirm[INPUT_BUF];
        read_line(confirm, sizeof(confirm));
        if (tolower(confirm[0]) != 'y') {
            free(idx);
            printf("已取消删除操作。\n");
            return;
        }
        /* 标记删除，采用倒序遍历防止索引错位 */
        for (int i = cnt-1; i >= 0; --i) {
            int pos = idx[i];
            for (int j = pos; j < g_cnt-1; ++j) g_entries[j] = g_entries[j+1];
            --g_cnt;
        }
        g_entries = (DiaryEntry *)realloc(g_entries, g_cnt * sizeof(DiaryEntry));
        printf("已删除全部匹配记录。\n");
        free(idx);
    } else {
        printf("无效选择。\n");
    }
}

/* 浏览全部日记（已排好序） */
static void browse_entries(void) {
    if (g_cnt == 0) {
        printf("当前没有任何日记。\n");
        return;
    }
    printf("\n=== 日记列表（共 %d 条）===\n", g_cnt);
    for (int i = 0; i < g_cnt; ++i) {
        DiaryEntry *e = &g_entries[i];
        printf("%02d. %04d-%02d-%02d | %s\n", i+1,
               e->date.year, e->date.month, e->date.day,
               e->keyword);
    }
    printf("输入序号查看详细内容，或回车返回: ");
    char line[INPUT_BUF];
    read_line(line, sizeof(line));
    if (strlen(line) == 0) return;
    int sel = atoi(line);
    if (sel < 1 || sel > g_cnt) {
        printf("序号超出范围。\n");
        return;
    }
    DiaryEntry *e = &g_entries[sel-1];
    printf("\n--- 详细内容 ---\n");
    printf("日期   : %04d-%02d-%02d\n", e->date.year, e->date.month, e->date.day);
    printf("关键字 : %s\n", e->keyword);
    printf("正文   : %s\n", e->content);
    printf("-----------------\n");
}

/* 查询日记（日期范围或关键字） */
static void search_entries(void) {
    printf("查询方式: 1. 按日期范围  2. 按关键字\n");
    char choice[INPUT_BUF];
    read_line(choice, sizeof(choice));

    if (choice[0] == '1') {
        Date start, end;
        printf("请输入起始日期 (YYYY-MM-DD): ");
        if (input_date(&start)!=0) return;
        printf("请输入结束日期 (YYYY-MM-DD): ");
        if (input_date(&end)!=0) return;
        printf("\n--- 区间查询结果 ---\n");
        int found = 0;
        for (int i = 0; i < g_cnt; ++i) {
            if (date_cmp(&g_entries[i].date, &start) >= 0 &&
                date_cmp(&g_entries[i].date, &end) <= 0) {
                printf("%04d-%02d-%02d | %s\n",
                       g_entries[i].date.year,
                       g_entries[i].date.month,
                       g_entries[i].date.day,
                       g_entries[i].keyword);
                ++found;
            }
        }
        if (!found) printf("无符合条件的记录。\n");
    } else if (choice[0] == '2') {
        char kw[KEYWORD_MAX];
        printf("请输入关键字: ");
        read_line(kw, sizeof(kw));
        int cnt;
        int *idx = find_entries_by_keyword(kw, &cnt);
        if (cnt == 0) {
            printf("没有匹配的日记。\n");
        } else {
            printf("\n--- 关键字查询结果 (%d 条) ---\n", cnt);
            for (int i = 0; i < cnt; ++i) {
                DiaryEntry *e = &g_entries[idx[i]];
                printf("%04d-%02d-%02d | %s\n",
                       e->date.year, e->date.month, e->date.day,
                       e->keyword);
            }
        }
        free(idx);
    } else {
        printf("无效选择。\n");
    }
}

