/*********************************************************************
 *  超市商品管理系统（四类商品）
 *  功能：  添加、查询、修改、删除、销售、统计
 *  编译方式（gcc）:  gcc -Wall -Wextra -std=c99 supermarket.c -o supermarket
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ---------- 常量、宏 ---------- */
#define MAX_NAME_LEN      50          /* 商品名称最大长度        */
#define MAX_MANU_LEN      50          /* 生产厂家名称最大长度    */
#define MAX_BRAND_LEN     30          /* 品牌名称最大长度        */
#define INIT_CAPACITY     100         /* 初始分配的商品空间      */

#define CLEAR_STDIN() while ( getchar()!= '\n' ) ;

/* ---------- 商品类别 ---------- */
typedef enum {
    FOOD = 1,          /* 食品       */
    COSMETIC,          /* 化妆品     */
    DAILY,             /* 日用品     */
    DRINK              /* 饮料       */
} Category;

/* ---------- 商品结构体 ---------- */
typedef struct {
    Category   cat;                     /* 所属类别      */
    char       name[MAX_NAME_LEN];     /* 商品名称      */
    double     price;                  /* 单价（元）    */
    int        stock;                  /* 库存数量      */
    char       manufacturer[MAX_MANU_LEN]; /* 生产厂家  */
    char       brand[MAX_BRAND_LEN];   /* 品牌          */
} Product;

/* ---------- 动态商品库 ---------- */
typedef struct {
    Product *data;      /* 商品数组指针   */
    size_t   size;      /* 当前已使用的条目数 */
    size_t   capacity;  /* 已分配的容量   */
} ProductDB;

/* ---------- 全局变量 ---------- */
ProductDB gDB = {NULL, 0, 0};

/* ---------- 辅助函数 ---------- */
static const char *category_str(Category c)
{
    switch (c) {
        case FOOD:    return "食品";
        case COSMETIC:return "化妆品";
        case DAILY:   return "日用品";
        case DRINK:   return "饮料";
        default:      return "未知";
    }
}

/* 动态扩容 */
static void db_ensure_capacity(ProductDB *db)
{
    if (db->size >= db->capacity) {
        size_t newCap = db->capacity ? db->capacity * 2 : INIT_CAPACITY;
        Product *tmp = realloc(db->data, newCap * sizeof(Product));
        if (!tmp) {
            fprintf(stderr, "内存分配失败！\n");
            exit(EXIT_FAILURE);
        }
        db->data = tmp;
        db->capacity = newCap;
    }
}

/* 读取一行字符串（去掉换行） */
static void read_line(char *buf, size_t size)
{
    if (fgets(buf, (int)size, stdin)) {
        size_t len = strlen(buf);
        if (len && buf[len-1] == '\n')
            buf[len-1] = '\0';
        else
            CLEAR_STDIN();   /* 输入太长，清空剩余字符 */
    }
}

/* 输入一个商品（不检查重复） */
static void input_product(Product *p)
{
    int cat;
    printf("请选择商品类别（1-食品 2-化妆品 3-日用品 4-饮料）: ");
    while (scanf("%d", &cat) != 1 || cat < 1 || cat > 4) {
        printf("输入错误，请重新输入 1~4: ");
        CLEAR_STDIN();
    }
    CLEAR_STDIN();   /* 清除换行 */

    p->cat = (Category)cat;
    printf("商品名称: ");      read_line(p->name, sizeof(p->name));
    printf("商品单价(元): ");
    while (scanf("%lf", &p->price) != 1 || p->price < 0) {
        printf("输入错误，请重新输入正数: ");
        CLEAR_STDIN();
    }
    printf("库存数量: ");
    while (scanf("%d", &p->stock) != 1 || p->stock < 0) {
        printf("输入错误，请重新输入非负整数: ");
        CLEAR_STDIN();
    }
    CLEAR_STDIN();
    printf("生产厂家: ");      read_line(p->manufacturer, sizeof(p->manufacturer));
    printf("品牌: ");          read_line(p->brand, sizeof(p->brand));
}

/* 按类别+名称在库中查找，返回下标（-1 表示未找到） */
static int find_product(const char *name, Category cat)
{
    for (size_t i = 0; i < gDB.size; ++i) {
        if (gDB.data[i].cat == cat && strcmp(gDB.data[i].name, name) == 0)
            return (int)i;
    }
    return -1;
}

/* 打印单个商品信息 */
static void print_product(const Product *p)
{
    printf("--------------------------------------------------\n");
    printf("类别    : %s\n", category_str(p->cat));
    printf("名称    : %s\n", p->name);
    printf("单价    : %.2lf 元\n", p->price);
    printf("库存    : %d 件\n", p->stock);
    printf("厂家    : %s\n", p->manufacturer);
    printf("品牌    : %s\n", p->brand);
}

/* ---------- 功能实现 ---------- */

/* 1. 添加商品 */
static void add_product(void)
{
    Product p;
    input_product(&p);
    /* 检查是否已存在同名同类商品（可自行决定是否允许） */
    if (find_product(p.name, p.cat) != -1) {
        printf("提示：该类别下已存在同名商品，是否覆盖？(Y/N) ");
        char ch = getchar();
