        /* 覆盖：直接修改 */
        int idx = find_product(p.name, p.cat);
        gDB.data[idx] = p;
        printf("商品信息已覆盖！\n");
        return;
    }
    db_ensure_capacity(&gDB);
    gDB.data[gDB.size++] = p;
    printf("商品添加成功！\n");
}

/* 2. 查询商品（可按类别、名称、厂家） */
static void query_product(void)
{
    int mode;
    printf("\n查询方式:\n");
