            if (strcmp(gDB.data[i].name, name) == 0) {
                print_product(&gDB.data[i]);
                found = 1;
            }
        if (!found) printf("该记录不存在！\n");
    } else {   /* mode == 3 */
        char manu[MAX_MANU_LEN];
        printf("生产厂家: "); read_line(manu, sizeof(manu));
