                found = 1;
            }
        if (!found) printf("该记录不存在！\n");
    }
}

/* 3. 修改商品（先查询，再覆盖） */
static void modify_product(void)
{
    char name[MAX_NAME_LEN];
    int cat;
    printf("请输入要修改商品的类别 (1~4): "); scanf("%d", &cat); CLEAR_STDIN();
    printf("请输入要修改商品的名称: ");   read_line(name, sizeof(name));

