    printf("\n请重新输入商品信息（直接回车保持原值）\n");
    Product p = gDB.data[idx];   /* 先拷贝原始值 */

    /* 下面的输入如果用户只按回车，则保持原值 */
    char buf[128];

    printf("新单价（当前 %.2lf）: ", p.price);
    read_line(buf, sizeof(buf));
    if (strlen(buf) > 0) {
        double newPrice = atof(buf);
        if (newPrice >= 0) p.price = newPrice;
    }

    printf("新库存（当前 %d）: ", p.stock);
    read_line(buf, sizeof(buf));
    if (strlen(buf) > 0) {
        int newStock = atoi(buf);
        if (newStock >= 0) p.stock = newStock;
    }

    printf("新厂家（当前 %s）: ", p.manufacturer);
    read_line(buf, sizeof(buf));
    if (strlen(buf) > 0) strncpy(p.manufacturer, buf, sizeof(p.manufacturer)-1);

    printf("新品牌（当前 %s）: ", p.brand);
    read_line(buf, sizeof(buf));
