}

/* 4. 删除商品 */
static void delete_product(void)
{
    int cat;
    char name[MAX_NAME_LEN];
    printf("请输入要删除商品的类别 (1~4): "); scanf("%d", &cat); CLEAR_STDIN();
    printf("请输入要删除商品的名称: ");       read_line(name, sizeof(name));

    int idx = find_product(name, (Category)cat);
    if (idx == -1) {
        printf("该商品不存在！\n");
        return;
    }

    /* 用最后一条记录覆盖被删记录，保持数组紧凑 */
    gDB.data[idx] = gDB.data[gDB.size - 1];
    gDB.size--;
    printf("商品已删除！\n");
}

/* 5. 销售商品 */
static void sell_product(void)
{
    int cat;
    char name[MAX_NAME_LEN];
    printf("请选择商品类别 (1~4): "); scanf("%d", &cat); CLEAR_STDIN();
    printf("请输入商品名称: ");       read_line(name, sizeof(name));

    int idx = find_product(name, (Category)cat);
    if (idx == -1) {
        printf("该商品不存在！\n");
        return;
    }

    Product *p = &gDB.data[idx];
    print_product(p);

    int quantity;
    printf("请输入购买数量: ");
    while (scanf("%d", &quantity) != 1 || quantity <= 0) {
        printf("输入错误，请输入正整数: ");
        CLEAR_STDIN();
    }
    CLEAR_STDIN();

    if (quantity > p->stock) {
        printf("库存不足！当前库存 %d，无法完成购买。\n", p->stock);
        return;
    }

    p->stock -= quantity;
    double total = quantity * p->price;
    printf("购买成功！付款金额：%.2lf 元\n", total);
}

/* 6. 统计/列出全部商品（可按价格、库存、厂家排序） */
static int cmp_price_desc(const void *a, const void *b)
{
    double pa = ((Product*)a)->price;
    double pb = ((Product*)b)->price;
    return (pa < pb) - (pa > pb);   /* 降序 */
}
static int cmp_stock_desc(const void *a, const void *b)
{
    int sa = ((Product*)a)->stock;
    int sb = ((Product*)b)->stock;
    return (sa < sb) - (sa > sb);   /* 降序 */
}

/* 按厂家名称降序（若相同再按商品名） */
static int cmp_manu_desc(const void *a, const void *b)
{
    const Product *pa = a, *pb = b;
    int r = strcmp(pb->manufacturer, pa->manufacturer);   /* 降序 */
    if (r != 0) return r;
    return strcmp(pa->name, pb->name);   /* 同厂家按名称升序 */
}

/* 统计并输出 */
static void statistics(void)
{
    if (gDB.size == 0) {
        printf("当前库中暂无商品！\n");
        return;
    }

    printf("\n=== 当前库中商品总数: %zu ===\n", gDB.size);
    for (size_t i = 0; i < gDB.size; ++i) {
        print_product(&gDB.data[i]);
    }

    printf("\n--- 按价格从高到低排序 ---\n");
    Product *tmp = malloc(gDB.size * sizeof(Product));
    memcpy(tmp, gDB.data, gDB.size * sizeof(Product));
    qsort(tmp, gDB.size, sizeof(Product), cmp_price_desc);
    for (size_t i = 0; i < gDB.size; ++i) print_product(&tmp[i]);
    free(tmp);

    printf("\n--- 按库存从高到低排序 ---\n");
    tmp = malloc(gDB.size * sizeof(Product));
    memcpy(tmp, gDB.data, gDB.size * sizeof(Product));
    qsort(tmp, gDB.size, sizeof(Product), cmp_stock_desc);
    for (size_t i = 0; i < gDB.size; ++i) print_product(&tmp[i]);
    free(tmp);

    printf("\n--- 按生产厂家（名称）从高到低排序 ---\n");
    tmp = malloc(gDB.size * sizeof(Product));
    memcpy(tmp, gDB.data, gDB.size * sizeof(Product));
    qsort(tmp, gDB.size, sizeof(Product), cmp_manu_desc);
    for (size_t i = 0; i < gDB.size; ++i) print_product(&tmp[i]);
    free(tmp);
}

/* ---------- 主菜单循环 ---------- */
static void show_menu(void)
{
    printf("\n=================== 超市商品管理系统 ===================\n");
    printf("1. 添加商品\n");
    printf("2. 查询商品\n");
    printf("3. 修改商品\n");
    printf("4. 删除商品\n");
    printf("5. 销售商品\n");
    printf("6. 统计/列出所有商品\n");
    printf("0. 退出\n");
    printf("请选择功能 (0~6): ");
}

/* 程序入口 */
int main(void)
{
    int choice;
    while (1) {
        show_menu();
        if (scanf("%d", &choice) != 1) {
            printf("输入错误，请重新选择！\n");
            CLEAR_STDIN();
            continue;
        }
        CLEAR_STDIN();   /* 清除输入缓冲区多余字符 */

        switch (choice) {
            case 0:
                printf("程序结束，感谢使用！\n");
                free(gDB.data);
                return 0;
            case 1: add_product();      break;
            case 2: query_product();    break;
            case 3: modify_product();   break;
            case 4: delete_product();   break;
            case 5: sell_product();     break;
            case 6: statistics();       break;
            default:
                printf("不存在的选项，请重新输入！\n");
        }
    }
}
