```c
/********************************************************************
 *  Square‑Root Calculator
 *  ----------------------
 *  - Reads a non‑negative double from stdin.
 *  - Prints the square root using either:
 *        a) sqrt() from <math.h>  (library version)
 *        b) Newton–Raphson iteration (manual version)
 *
 *  Compile:
 *      gcc -Wall -Wextra -O2 sqrt_demo.c -o sqrt_demo -lm
 *
 *  Run:
 *      ./sqrt_demo
 *
 *  Author: ChatGPT (2024)
 ********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <math.h>   // for sqrt()
#include <float.h>  // for DBL_EPSILON

/* --------------------------------------------------------------
 *  Function: newton_sqrt
 *  Purpose : Compute sqrt(x) using Newton‑Raphson iteration.
 *  Input   : x – number ≥ 0
 *  Return  : Approximate square root of x.
 * --------------------------------------------------------------*/
double newton_sqrt(double x)
{
    if (x == 0.0)               // sqrt(0) == 0, avoid division by zero later
        return 0.0;

    /*  Initial guess: a value close to sqrt(x).
        Using x itself works for x >= 1, while 1 works for 0 < x < 1. */
    double guess = (x >= 1.0) ? x : 1.0;

    /*  Newton‑Raphson formula:
            guess_{n+1} = 0.5 * (guess_n + x / guess_n)
        Stop when the change is smaller than epsilon.
        DBL_EPSILON ≈ 2.22e‑16, but we relax it a little for speed. */
    const double epsilon = 1e-12;   // acceptable absolute error
    double diff;

    do {
        double next = 0.5 * (guess + x / guess);
        diff = fabs(next - guess);
        guess = next;
    } while (diff > epsilon);

    return guess;
}

/* --------------------------------------------------------------
 *  Main driver
 * --------------------------------------------------------------*/
int main(void)
{
    double value;

    printf("Enter a non‑negative number: ");
    if (scanf("%lf", &value) != 1) {
        fprintf(stderr, "Error: invalid input.\n");
        return EXIT_FAILURE;
    }

    if (value < 0.0) {
        fprintf(stderr, "Error: square root of a negative number is not real.\n");
        return EXIT_FAILURE;
    }

    /* ---- 1) Library version (sqrt from <math.h>) ---- */
    double lib_root = sqrt(value);       // requires linking with -lm
    printf("\n[Library] sqrt(%.12g) = %.12g\n", value, lib_root);

    /* ---- 2) Manual version (Newton‑Raphson) ---- */
    double nr_root = newton_sqrt(value);
    printf("[Newton] sqrt(%.12g) = %.12g\n", value, nr_root);

    /* ---- Optional: show the difference (should be ~0) ---- */
    printf("Difference between the two methods: %.12g\n",
           fabs(lib_root - nr_root));

    return EXIT_SUCCESS;
}
