## 📂  Code complet

```c
/* --------------------------------------------------------------
   Dictionnaire sous forme de liste doublement chaînée
   -------------------------------------------------------------- */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* ---------- Structure d'un maillon ----------
 * - word  : le mot (chaîne de caractères terminée par '\0')
 * - prev  : pointeur vers le maillon précédent
 * - next  : pointeur vers le maillon suivant
 * ------------------------------------------------ */
typedef struct Node {
    char *word;
    struct Node *prev;
    struct Node *next;
} Node;

/* ---------- Création d'un nouveau maillon ----------
 * Retourne un pointeur vers un maillon contenant une copie de `mot`.
 * --------------------------------------------------- */
static Node *nouveauMaillon(const char *mot)
{
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->word = strdup(mot);           /* duplique le texte */
    if (!n->word) {
        perror("strdup");
        free(n);
        exit(EXIT_FAILURE);
    }
    n->prev = n->next = NULL;
    return n;
}

/* ==============================================================
   Fonction : ajoutMOT
   --------------------------------------------------------------
   Ajoute `mot` dans la liste doublement chaînée pointée par *head
   en respectant l’ordre alphabétique (strcmp < 0).

   Paramètres
   ----------
   - head : pointeur vers le pointeur de tête de la liste
   - mot  : le mot à insérer (chaîne C)

   Retour
   ------
   - true  : le mot a été inséré (ou déjà présent, on ne duplique pas)
   - false : problème d’allocation (impossible d’insérer)
   ============================================================== */
bool ajoutMOT(Node **head, const char *mot)
{
    if (!head || !mot) return false;

    /* Cas 1 : liste vide → le nouveau maillon devient la tête */
    if (*head == NULL) {
        *head = nouveauMaillon(mot);
        return true;
    }

    Node *cour = *head;
    Node *prec = NULL;

    /* ------------------------------------------------------------
       Parcours de la liste à la recherche de la bonne position
       (ou du doublon).  strcmp < 0  → on continue à avancer.
       ------------------------------------------------------------ */
    while (cour != NULL && strcmp(cour->word, mot) < 0) {
        prec = cour;
        cour = cour->next;
    }

    /* ------------------------------------------------------------
       Si le mot existe déjà (strcmp == 0), on ne l’ajoute pas.
       ------------------------------------------------------------ */
    if (cour != NULL && strcmp(cour->word, mot) == 0) {
        /* Le mot est déjà présent → rien à faire */
        return true;
    }

    /* ------------------------------------------------------------
       Insertion du nouveau maillon entre `prec` et `cour`.
       - Si `prec` == NULL → insertion en tête.
       - Sinon → insertion au milieu ou en fin.
       ------------------------------------------------------------ */
    Node *nouv = nouveauMaillon(mot);

    if (prec == NULL) {          /* insertion en tête */
        nouv->next = *head;
        (*head)->prev = nouv;
        *head = nouv;
    } else {                     /* insertion après `prec` */
        nouv->prev = prec;
        nouv->next = cour;
        prec->next = nouv;
        if (cour) cour->prev = nouv;
    }

    return true;
}

/* ---------- Fonctions utilitaires (affichage, libération) ---------- */
void afficheListe(const Node *head)
{
    const Node *c = head;
    while (c) {
        printf("%s", c->word);
        if (c->next) printf(" -> ");
        c = c->next;
    }
    putchar('\n');
}

/* Libère toute la liste (et les chaînes qu’elle contient). */
void libereListe(Node *head)
{
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp->word);
        free(tmp);
    }
}

/* ------------------- Exemple d’utilisation ------------------- */
int main(void)
{
    Node *dico = NULL;                     /* dictionnaire vide */

    /* Insertion de quelques mots (ordre aléatoire) */
    const char *mots[] = {
        "pomme", "banane", "cerise", "abricot",
        "datte", "figue", "orange", "kiwi"
    };
    size_t n = sizeof(mots) / sizeof(mots[0]);

    for (size_t i = 0; i < n; ++i) {
        ajoutMOT(&dico, mots[i]);
        printf("Après insertion de \"%s\" : ", mots[i]);
        afficheListe(dico);
    }

    /* Test d’insertion d’un doublon */
    printf("\n--- Insertion d'un doublon \"banane\" ---\n");
    ajoutMOT(&dico, "banane");
    afficheListe(dico);

    /* Nettoyage */
    libereListe(dico);
    return 0;
}
```

