    /* 末尾必须以全 0 的 entry 结束（即 name[0] == '\0'） */
    memset(&dynamic_id_table[cnt], 0, sizeof(dynamic_id_table[0]));

    dynamic_id_cnt = cnt;
    pr_info("demo_i2c: built dynamic id_table with %u entries\n", cnt);
    return 0;
}

/* -------------- 5. module init / exit ------------------- */
static int __init demo_i2c_init(void)
{
    int ret;

    ret = build_dynamic_id_table();
    if (ret) {
        pr_err("demo_i2c: failed to build id_table (%d)\n", ret);
        return ret;
    }

    demo_i2c_driver.id_table = dynamic_id_table;   /* 把指针挂上 */

    /* 手动注册驱动（而不是使用 module_i2c_driver 宏） */
    ret = i2c_add_driver(&demo_i2c_driver);
    if (ret) {
        pr_err("demo_i2c: i2c_add_driver failed (%d)\n", ret);
        kfree(dynamic_id_table);
        demo_i2c_driver.id_table = NULL;
        return ret;
    }

    pr_info("demo_i2c: driver registered (dynamic id_table)\n");
    return 0;
}

static void __exit demo_i2c_exit(void)
{
    i2c_del_driver(&demo_i2c_driver);
    kfree(dynamic_id_table);
    dynamic_id_table = NULL;
    pr_info("demo_i2c: driver unregistered, memory freed\n");
}

module_init(demo_i2c_init);
module_exit(demo_i2c_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("ChatGPT <example@openai.com>");
MODULE_DESCRIPTION("Demo I2C driver with runtime‑generated id_table");
