## 2. 完整代码（read_csv_to_byte_array.c）

```c
/***********************************************************************
 *  read_csv_to_byte_array.c
 *
 *  读取一个逗号分隔的 CSV 文件 (纯数字) ，把每个单元格的值保存
 *  为一个 uint8_t（byte）数组。演示了:
 *      • 动态统计行/列数
 *      • 动态分配一维 byte 数组 (row*col)
 *      • 逐行/逐字段解析 (strtok)
 *      • 错误检查和资源释放
 *
 *  编译 (Linux / macOS / MinGW):
 *      gcc -Wall -Wextra -std=c11 read_csv_to_byte_array.c -o readcsv
 *
 *  运行:
 *      ./readcsv test.csv
 *
 ***********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>

#define MAX_LINE_LEN 1024    // 单行最大字符数（包括换行符）
#define DELIM        ","     // CSV 分隔符

/*----------------------------------------------------------------------
 * 读取 CSV 并把每个数字保存到 uint8_t 数组中。
 *
 * 参数:
 *   filename   - CSV 文件路径
 *   outRows    - 输出：行数（返回给调用者）
 *   outCols    - 输出：列数（返回给调用者）
 *
 * 返回:
 *   成功: 动态分配的 uint8_t* 数组，长度 = rows*cols
 *   失败: NULL（并通过 fprintf 输出错误信息）
 *---------------------------------------------------------------------*/
static uint8_t *read_csv_to_bytes(const char *filename,
                                 size_t *outRows,
                                 size_t *outCols)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening file \"%s\": %s\n", filename, strerror(errno));
        return NULL;
    }

    char line[MAX_LINE_LEN];
    size_t rows = 0;
    size_t cols = 0;               // 第1行的列数，用来检查后续行是否一致
    uint8_t *data = NULL;          // 最终返回的字节数组
    size_t capacity = 0;           // 已分配的元素数（rows*cols）

    /* ------------ 第一次遍历：统计行/列数 -------------------------- */
    while (fgets(line, sizeof(line), fp)) {
        // 去除末尾换行符（如果有）
        line[strcspn(line, "\r\n")] = '\0';

        // 跳过空行
        if (line[0] == '\0')
            continue;

        // 统计当前行的列数
        size_t curCols = 0;
        char *tmp = line;
        while ((tmp = strtok(tmp, DELIM))) {
            ++curCols;
            tmp = NULL;   // 让 strtok 继续在同一行上工作
        }

        if (curCols == 0) continue; // 空行安全检查

        if (rows == 0) {
            cols = curCols; // 第1行决定列数
        } else if (curCols != cols) {
            fprintf(stderr,
                    "Inconsistent column count at line %zu: expected %zu, got %zu\n",
                    rows + 1, cols, curCols);
            fclose(fp);
            return NULL;
        }
        ++rows;
    }

    if (rows == 0 || cols == 0) {
        fprintf(stderr, "Empty or malformed CSV file.\n");
        fclose(fp);
        return NULL;
    }

    // 为所有单元格分配内存 (row * col) 个 uint8_t
    capacity = rows * cols;
    data = (uint8_t *)malloc(capacity);
    if (!data) {
        fprintf(stderr, "Memory allocation failed (%zu bytes).\n", capacity);
        fclose(fp);
        return NULL;
    }

    // ------------ 第二次遍历：实际读取并填充 data --------------- */
    rewind(fp);                     // 回到文件开头
    size_t idx = 0;                 // data[] 的写入位置

    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\r\n")] = '\0';   // 移除换行

        if (line[0] == '\0') continue;        // 跳空行

        char *token = strtok(line, DELIM);
        while (token) {
            // 把 token 转成 long，然后截断到 0..255
            char *endptr = NULL;
            long val = strtol(token, &endptr, 10);
            if (endptr == token) {
                fprintf(stderr, "Non‑numeric token \"%s\" at row %zu, col %zu\n",
                        token, (idx / cols) + 1, (idx % cols) + 1);
                free(data);
                fclose(fp);
                return NULL;
            }
            if (val < 0)   val = 0;
            if (val > 255) val = 255;   // 超出范围就截断（也可以直接报错）

            data[idx++] = (uint8_t)val;

            token = strtok(NULL, DELIM);
        }
    }

    fclose(fp);
    *outRows = rows;
    *outCols = cols;
    return data;
}

/*----------------------------------------------------------------------
 * 一个帮助函数，用来把一维的 byte 数组「按行列」打印出来
 *---------------------------------------------------------------------*/
static void print_byte_array(const uint8_t *data,
                             size_t rows,
                             size_t cols)
{
    printf("CSV 内容 (%zu x %zu):\n", rows, cols);
    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            printf("%3u", data[r * cols + c]);   // 每个 byte 右对齐宽度 3
            if (c + 1 < cols) putchar(' ');
        }
        putchar('\n');
    }
}

/*----------------------------------------------------------------------
 * 主函数：演示如何调用上面的接口
 *---------------------------------------------------------------------*/
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv-file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    size_t rows = 0, cols = 0;

    uint8_t *bytes = read_csv_to_bytes(filename, &rows, &cols);
    if (!bytes) {
        // 错误信息已在 read_csv_to_bytes 中打印
        return EXIT_FAILURE;
    }

    // 【演示】打印出读取的 byte 数组
    print_byte_array(bytes, rows, cols);

    // 此时 bytes 中保存的就是 "raw byte" 形式的 CSV 数据，
    // 你可以直接把它传给别的函数、写入网络、或保存为二进制文件等。
    // ------------------- 示例：写入二进制文件 --------------------
    {
        const char *bin_name = "output.bin";
        FILE *bf = fopen(bin_name, "wb");
        if (bf) {
            fwrite(bytes, 1, rows * cols, bf);
            fclose(bf);
            printf("\nSaved raw bytes to \"%s\" (%zu bytes).\n",
                   bin_name, rows * cols);
        } else {
            perror("Failed to write binary file");
        }
    }

    // 最后别忘记释放内存
    free(bytes);
    return EXIT_SUCCESS;
}
