## 1. Kiểm tra từng số (phương pháp `isPrime`)

```c
#include <stdio.h>
#include <stdbool.h>
#include <math.h>

/* Kiểm tra một số i có phải là số nguyên tố không */
bool isPrime(int i)
{
    if (i < 2) return false;
    if (i == 2) return true;
    if (i % 2 == 0) return false;          // loại bỏ các số chẵn > 2

    int limit = (int)sqrt(i);
    for (int d = 3; d <= limit; d += 2)    // chỉ kiểm tra các ước lẻ
        if (i % d == 0) return false;
    return true;
}

/* In ra tất cả các số nguyên tố <= n bằng cách kiểm tra từng số */
void listPrimes_simple(int n)
{
    for (int i = 2; i <= n; ++i)
        if (isPrime(i))
            printf("%d ", i);
    printf("\n");
}
```

---

## 2. Sàng Eratosthenes (phương pháp nhanh)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* In ra các số nguyên tố <= n bằng thuật toán Sàng Eratosthenes */
void listPrimes_sieve(int n)
{
    if (n < 2) {               // không có số nguyên tố nào
        printf("\n");
        return;
    }

    /* Tạo mảng đánh dấu: 0 → chưa được loại, 1 → đã loại (không phải số nguyên tố) */
    bool *isComposite = (bool *)calloc(n + 1, sizeof(bool));
    if (!isComposite) {
        fprintf(stderr, "Không đủ bộ nhớ.\n");
        exit(EXIT_FAILURE);
    }

    /* Đánh dấu các bội của mỗi số nguyên tố tìm được */
    for (int p = 2; p * p <= n; ++p) {
        if (!isComposite[p]) {                 // p là số nguyên tố
            for (int multiple = p * p; multiple <= n; multiple += p)
                isComposite[multiple] = true; // đánh dấu bội
        }
    }

    /* In các số còn lại (không bị đánh dấu) – chính là các số nguyên tố */
    for (int i = 2; i <= n; ++i)
        if (!isComposite[i])
            printf("%d ", i);
    printf("\n");

    free(isComposite);
}
```

