    -------------------------------------------------------------
    The program builds a hash table that maps each number to the
    index of its **last** occurrence in the input array.
    Then it scans the array, finds the start of every possible
    consecutive block and keeps the longest one.
    If several blocks have the same length, the one that begins
    earlier in the input (i.e. with the smallest original index)
    is kept.
   ------------------------------------------------------------- */

#include <stdio.h>

#define MAX_HASH 1000001                 /* enough for the problem limits */

int hashtable[MAX_HASH];                 /* number -> last index */

/* -------------------------------------------------------------
   Initialise the table: -1 means “the number never appears”.
   ------------------------------------------------------------- */
void clearHashtable(void) {
    for (int i = 0; i < MAX_HASH; ++i)
        hashtable[i] = -1;
}

/* -------------------------------------------------------------
   Simple accessors – they silently ignore numbers outside the
   supported range.
   ------------------------------------------------------------- */
int getHash(int number) {
    if (number >= 0 && number < MAX_HASH)
        return hashtable[number];
    return -1;
}

void setHash(int number, int index) {
    if (number >= 0 && number < MAX_HASH)
        hashtable[number] = index;
}

/* -------------------------------------------------------------
   Find the longest consecutive block and print **one** of them.
   ------------------------------------------------------------- */
void findLongestConsecutiveSequence(int book[], int n) {
    clearHashtable();

    /* store the last occurrence of every value */
    for (int i = 0; i < n; ++i)
        setHash(book[i], i);

    int bestLen      = 0;      /* length of the best block found */
    int bestStartNum = -1;     /* the first number of that block   */
    int bestStartPos = n;      /* its position in the input array */

    /* ---------------------------------------------------------
       Scan the array – every element may be the start of a block
       if the previous integer is NOT present.
       --------------------------------------------------------- */
    for (int i = 0; i < n; ++i) {
        int curNum = book[i];

        /* curNum can be the start only when (curNum‑1) is absent */
        if (getHash(curNum - 1) == -1) {
            int curLen = 1;
            while (getHash(curNum + curLen) != -1)
                ++curLen;                     /* extend the block */

            /* ----- update the best block -------------------------------- */
            if (curLen > bestLen ||
               (curLen == bestLen && i < bestStartPos)) {
                bestLen      = curLen;
                bestStartNum = curNum;
                bestStartPos = i;          /* remember the earliest start */
            }
        }
    }

    /* ----- Output --------------------------------------------------- */
    printf("%d\n", bestLen);
    for (int k = 0; k < bestLen; ++k) {
        printf("%d ", getHash(bestStartNum + k));
    }
    printf("\n");
}

/* -------------------------------------------------------------
   Driver code – reads the data and calls the routine.
   ------------------------------------------------------------- */
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int book[n];
    for (int i = 0; i < n; ++i)
        scanf("%d", &book[i]);

    findLongestConsecutiveSequence(book, n);
    return 0;
}
