## 3. Реализация **Server**

```cpp
// ---------------------------------------------------
//  Server.cpp
// ---------------------------------------------------
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <iostream>
#include <fstream>
#include <vector>
#include <unordered_map>
#include <string>

#pragma comment(lib, "kernel32.lib")

// ---------- Протокол (см. выше) ----------
enum class Op : uint8_t { NONE=0, READ_REQ=1, READ_DONE=2, WRITE_REQ=3,
                          WRITE_DATA=4, WRITE_DONE=5, EXIT=255 };
enum class Status : uint8_t { OK=0, BUSY=1, NOTFOUND=2, ERROR=255 };

#pragma pack(push,1)
struct Msg {
    Op      op;
    uint32_t id;    // key (ID)
    Status  status; // set by server
    int     num;
    char    name[10];
    double  hours;
};
#pragma pack(pop)

static const wchar_t* PIPE_NAME = L"\\\\.\\pipe\\EmpPipe";

// ---------- структура блокировки ----------
struct LockInfo {
    uint32_t readCount = 0;   // сколько читателей сейчас держат lock
    uint32_t writeOwner = 0;  // 0 – никто; иначе PID клиента
};

// ---------- вспомогательные функции ----------
bool loadEmployees(const std::wstring& fname,
                   std::vector<employee>& out)
{
    std::ifstream f(fname, std::ios::binary);
    if (!f) return false;
    employee e;
    while (f.read(reinterpret_cast<char*>(&e), sizeof(e))) {
        out.push_back(e);
    }
    return true;
}

bool saveEmployees(const std::wstring& fname,
                   const std::vector<employee>& data)
{
    std::ofstream f(fname, std::ios::binary | std::ios::trunc);
    if (!f) return false;
    for (const auto& e : data)
        f.write(reinterpret_cast<const char*>(&e), sizeof(e));
    return true;
}

// поиск по ID, возвращает индекс в векторе или -1
int findById(const std::vector<employee>& vec, int id) {
    for (size_t i = 0; i < vec.size(); ++i)
        if (vec[i].num == id) return static_cast<int>(i);
    return -1;
}

// ---------- основной код сервера ----------
int wmain()
{
    // 1) ввод имени файла и данных
    std::wcout << L"Введите имя файла (будет создан/перезаписан): ";
    std::wstring fname;
    std::getline(std::wcin, fname);
    if (fname.empty()) fname = L"employees.dat";

    std::wcout << L"Введите количество сотрудников: ";
    int n = 0; std::wcin >> n;
    std::cin.ignore(); // consume newline

    std::vector<employee> db;
    db.reserve(n);
    for (int i = 0; i < n; ++i) {
        employee e;
        std::wcout << L"--- Сотрудник #" << i+1 << L" ---\n";
        std::wcout << L"ID: "; std::wcin >> e.num;
        std::wcin.ignore();
        std::wcout << L"Имя (<=9 символов): ";
        std::string tmp; std::getline(std::cin, tmp);
        memset(e.name, 0, sizeof(e.name));
        memcpy(e.name, tmp.c_str(), std::min<size_t>(tmp.size(), sizeof(e.name)-1));
        std::wcout << L"Отработанные часы: "; std::wcin >> e.hours;
        std::cin.ignore();
        db.push_back(e);
    }

    // 2) сохраняем файл и выводим его содержимое
    if (!saveEmployees(fname, db)) {
        std::wcerr << L"Не удалось записать файл!\n";
        return 1;
    }

    std::wcout << L"\n=== Содержимое файла ===\n";
    for (const auto& e : db)
        std::wcout << L"ID=" << e.num
                   << L", name=" << std::string(e.name, 10).c_str()
                   << L", hours=" << e.hours << L'\n';

    // 3) создаём именованный канал
    HANDLE hPipe = CreateNamedPipeW(
        PIPE_NAME,
        PIPE_ACCESS_DUPLEX,          // чтение+запись
        PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
        PIPE_UNLIMITED_INSTANCES,    // сколько угодно клиентов
        512, 512,                    // размер буферов (достаточно для Msg)
        0, NULL);
    if (hPipe == INVALID_HANDLE_VALUE) {
        std::wcerr << L"CreateNamedPipe failed, error " << GetLastError() << L'\n';
        return 1;
    }

    std::wcout << L"\nОжидание подключения клиента...\n";
    BOOL connected = ConnectNamedPipe(hPipe, NULL) ?
                     TRUE : (GetLastError() == ERROR_PIPE_CONNECTED);
    if (!connected) {
        std::wcerr << L"ConnectNamedPipe failed, error " << GetLastError() << L'\n';
        CloseHandle(hPipe);
        return 1;
    }
    std::wcout << L"Клиент подключён.\n";

    // 4) таблица блокировок (по ID)
    std::unordered_map<int, LockInfo> locks;

    // 5) основной цикл обработки запросов
    bool serverRun = true;
    while (serverRun) {
        Msg req{};
        DWORD bytesRead = 0;
        BOOL ok = ReadFile(hPipe, &req, sizeof(req), &bytesRead, NULL);
        if (!ok || bytesRead != sizeof(req)) {
            std::wcerr << L"ReadFile error " << GetLastError() << L'\n';
            break;
        }

        Msg reply{};
        reply.op = req.op;
        reply.id = req.id;
        reply.status = Status::ERROR; // по умолчанию

        // ------- обработка разных типов запросов ----------
        switch (req.op) {
        case Op::READ_REQ: {
            int idx = findById(db, static_cast<int>(req.id));
            if (idx < 0) {
                reply.status = Status::NOTFOUND;
                break;
            }
            // проверяем, не имеет ли кто‑то write‑lock
            LockInfo& li = locks[req.id];
            if (li.writeOwner != 0) {
                reply.status = Status::BUSY;
                break;
            }
            // разрешаем чтение: увеличиваем счётчик
            li.readCount++;
            // возвращаем запись клиенту
            reply.status = Status::OK;
            reply.num = db[idx].num;
            memcpy(reply.name, db[idx].name, sizeof(reply.name));
            reply.hours = db[idx].hours;
            break;
        }
        case Op::READ_DONE: {
            // клиент сообщает, что закончил чтение – просто уменьшаем счётчик
            auto it = locks.find(req.id);
            if (it != locks.end() && it->second.readCount > 0)
                it->second.readCount--;
            reply.status = Status::OK;
            break;
        }
        case Op::WRITE_REQ: {
            int idx = findById(db, static_cast<int>(req.id));
            if (idx < 0) {
                reply.status = Status::NOTFOUND;
                break;
            }
            LockInfo& li = locks[req.id];
            // запись свободна, только если нет ни читателей, ни писателя
            if (li.readCount == 0 && li.writeOwner == 0) {
                li.writeOwner = GetCurrentProcessId(); // запоминаем владельца
                reply.status = Status::OK;
                // отдаём клиенту текущие данные (как при чтении)
                reply.num = db[idx].num;
                memcpy(reply.name, db[idx].name, sizeof(reply.name));
                reply.hours = db[idx].hours;
            } else {
                reply.status = Status::BUSY;
            }
            break;
        }
        case Op::WRITE_DATA: {
            // клиент посылает изменённую запись
            int idx = findById(db, static_cast<int>(req.id));
            if (idx < 0) {
                reply.status = Status::NOTFOUND;
                break;
            }
            LockInfo& li = locks[req.id];
            if (li.writeOwner != GetCurrentProcessId()) {
                reply.status = Status::BUSY; // кто‑то нарушил протокол
                break;
            }
            // записываем изменения в вектор (в файл будем писать позже)
            db[idx].num   = req.num;
            memcpy(db[idx].name, req.name, sizeof(db[idx].name));
            db[idx].hours = req.hours;
            reply.status = Status::OK;
            break;
        }
        case Op::WRITE_DONE: {
            // клиент завершил работу с записью – снимаем write‑lock
            auto it = locks.find(req.id);
            if (it != locks.end() && it->second.writeOwner == GetCurrentProcessId())
                it->second.writeOwner = 0;
            reply.status = Status::OK;
            break;
        }
        case Op::EXIT: {
            serverRun = false;
            reply.status = Status::OK;
            break;
        }
        default:
            reply.status = Status::ERROR;
            break;
        }

        // отправляем ответ
        DWORD bytesWritten = 0;
        ok = WriteFile(hPipe, &reply, sizeof(reply), &bytesWritten, NULL);
        if (!ok || bytesWritten != sizeof(reply)) {
            std::wcerr << L"WriteFile error " << GetLastError() << L'\n';
            break;
        }
    }

    // 6) закрываем pipe
    FlushFileBuffers(hPipe);
    DisconnectNamedPipe(hPipe);
    CloseHandle(hPipe);

    // 7) выводим окончательное содержимое файла
    std::wcout << L"\n=== Содержимое файла после работы клиентов ===\n";
    for (const auto& e : db)
        std::wcout << L"ID=" << e.num
                   << L", name=" << std::string(e.name, 10).c_str()
                   << L", hours=" << e.hours << L'\n';

    // сохраняем окончательное состояние в файл
    saveEmployees(fname, db);

    std::wcout << L"\nНажмите ENTER для завершения сервера...";
    std::cin.get();
    return 0;
}
```

### Что делает сервер

| Шаг | Описание |
|-----|----------|
| **Инициализация** | Считывает имя файла и создаёт вектор `db` со всеми записями. |
| **Запись** | Сохраняет в бинарный файл `employees.dat`. |
| **Создание pipe** | `CreateNamedPipe` с типом `PIPE_TYPE_MESSAGE` → сообщения фиксированного размера. |
| **Блокировки** | Внутри `std::unordered_map<int,LockInfo> locks` хранится счётчик читателей и ID процесса‑владельца записи. |
| **Обработка запросов** | Читает `Msg`, в зависимости от `op` проверяет, доступна ли запись, изменяет `LockInfo`, при необходимости изменяет запись в `db`, формирует ответ. |
| **Завершение** | После получения `Op::EXIT` выводит финальное состояние, сохраняет файл, закрывает pipe. |

