## 4. Реализация **Client**

```cpp
// ---------------------------------------------------
//  Client.cpp
// ---------------------------------------------------
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <iostream>
#include <string>
#include <cstring>

#pragma comment(lib, "kernel32.lib")

enum class Op : uint8_t { NONE=0, READ_REQ=1, READ_DONE=2, WRITE_REQ=3,
                          WRITE_DATA=4, WRITE_DONE=5, EXIT=255 };
enum class Status : uint8_t { OK=0, BUSY=1, NOTFOUND=2, ERROR=255 };

#pragma pack(push,1)
struct Msg {
    Op      op;
    uint32_t id;
    Status  status;
    int     num;
    char    name[10];
    double  hours;
};
#pragma pack(pop)

static const wchar_t* PIPE_NAME = L"\\\\.\\pipe\\EmpPipe";

void printEmployee(const Msg& m) {
    std::cout << "ID=" << m.num
              << ", name=" << std::string(m.name,10).c_str()
              << ", hours=" << m.hours << "\n";
}

int main()
{
    // 1) открываем канал
    HANDLE hPipe = CreateFileW(
        PIPE_NAME,
        GENERIC_READ | GENERIC_WRITE,
        0,
        NULL,
        OPEN_EXISTING,
        0,
        NULL);
    if (hPipe == INVALID_HANDLE_VALUE) {
        std::cerr << "CreateFile failed, error " << GetLastError() << "\n";
        return 1;
    }

    std::cout << "Подключено к серверу.\n";

    bool run = true;
    while (run) {
        std::cout << "\nВыберите действие:\n"
                  << "1 – чтение записи\n"
                  << "2 – модификация записи\n"
                  << "0 – выход\n"
                  << "Ваш выбор: ";
        int choice = -1;
        std::cin >> choice;
        std::cin.ignore(); // consume newline

        if (choice == 0) {
            // отправляем серверу команду завершения
            Msg exitMsg{};
            exitMsg.op = Op::EXIT;
            DWORD written = 0;
            WriteFile(hPipe, &exitMsg, sizeof(exitMsg), &written, NULL);
            run = false;
            continue;
        }

        // Запрашиваем ID записи
        std::cout << "Введите ID сотрудника: ";
        int id = 0;
        std::cin >> id;
        std::cin.ignore();

        if (choice == 1) { // ---------- ЧТЕНИЕ ----------
            // 1) запросить read
            Msg req{};
            req.op = Op::READ_REQ;
            req.id = id;
            DWORD written = 0;
            WriteFile(hPipe, &req, sizeof(req), &written, NULL);

            // 2) получить ответ
            Msg ans{};
            DWORD read = 0;
            ReadFile(hPipe, &ans, sizeof(ans), &read, NULL);
            if (ans.status == Status::OK) {
                std::cout << "Запись получена:\n";
                printEmployee(ans);
            } else if (ans.status == Status::BUSY) {
                std::cout << "Запись сейчас занята другим клиентом.\n";
                continue;
            } else if (ans.status == Status::NOTFOUND) {
                std::cout << "Запись с таким ID не найдена.\n";
                continue;
            }

            // 3) пользователь закрыл запись – посылаем READ_DONE
            Msg done{};
            done.op = Op::READ_DONE;
            done.id = id;
            WriteFile(hPipe, &done, sizeof(done), &written, NULL);
            // получаем подтверждение (можно игнорировать)
            ReadFile(hPipe, &ans, sizeof(ans), &read, NULL);
        }
        else if (choice == 2) { // ---------- МОДИФИКАЦИЯ ----------
            // 1) запросить write lock
            Msg req{};
            req.op = Op::WRITE_REQ;
            req.id = id;
            DWORD written = 0;
            WriteFile(hPipe, &req, sizeof(req), &written, NULL);

            // 2) ответ сервера
            Msg ans{};
            DWORD read = 0;
            ReadFile(hPipe, &ans, sizeof(ans), &read, NULL);
            if (ans.status != Status::OK) {
                if (ans.status == Status::BUSY)   std::cout << "Запись занята.\n";
                if (ans.status == Status::NOTFOUND) std::cout << "Записи нет.\n";
                continue;
            }

            std::cout << "Текущие данные записи:\n";
            printEmployee(ans);

            // 3) ввод новых данных
            Msg upd{};
            upd.op = Op::WRITE_DATA;
            upd.id = id;
            std::cout << "Введите новое имя (max 9 символов): ";
            std::string newName;
            std::cin >> newName;
            std::cin.ignore();
            memset(upd.name, 0, sizeof(upd.name));
            memcpy(upd.name, newName.c_str(),
                  std::min<size_t>(newName.size(), sizeof(upd.name)-1));
            std::cout << "Введите новые отработанные часы: ";
            std::cin >> upd.hours;
            std::cin.ignore();

            // ID может также измениться – в примере позволим изменить
            std::cout << "Введите новый ID (или тот же): ";
            std::cin >> upd.num;
            std::cin.ignore();

            // 4) посылаем изменённую запись
            WriteFile(hPipe, &upd, sizeof(upd), &written, NULL);
            // получаем подтверждение
            ReadFile(hPipe, &ans, sizeof(ans), &read, NULL);
            if (ans.status != Status::OK) {
                std::cout << "Ошибка при записи данных на сервер.\n";
            } else {
                std::cout << "Запись успешно изменена.\n";
            }

            // 5) освобождаем write‑lock
            Msg done{};
            done.op = Op::WRITE_DONE;
            done.id = id;
            WriteFile(hPipe, &done, sizeof(done), &written, NULL);
            ReadFile(hPipe, &ans, sizeof(ans), &read, NULL); // ACK
        }
        else {
            std::cout << "Неизвестный выбор.\n";
        }
    }

    CloseHandle(hPipe);
    std::cout << "Клиент завершён.\n";
    return 0;
}
