下面给出一个 **最小可运行的示例**，演示 **Linux 用户态进程** 如何通过 **`mmap()`** 与 **内核态模块**（字符设备）共享一段内存。  

> 关键点  
> 1. 内核模块在 `open()` 时为每个打开的文件实例分配一段同页大小的缓冲区（`kmalloc()`），并把这段物理页映射给用户态。  
> 2. `mmap()` 实现中使用 `remap_pfn_range()` 把物理页号（PFN）映射到用户空间 VMA。  
> 3. 用户态程序 `mmap()` 这段设备文件后即可像普通内存一样读写，所有改动直接落在同一块物理页上。  

下面的代码分为两部分：

* **内核空间** – 一个最简的字符设备驱动（`my_mmap_dev.c`）  
* **用户空间** – 一个测试程序（`user_mmap.c`）  

---

## 1. 内核模块（my_mmap_dev.c）

```c
/* SPDX-License-Identifier: GPL-2.0 */
/*
 *  简单的 mmap 演示字符设备
 *  编译:  make -C /lib/modules/$(uname -r)/build M=$(pwd) modules
 */

#include <linux/module.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/mm.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/mutex.h>

#define DEV_NAME "my_mmap_dev"
#define BUF_ORDER 0          /* 2^0 * PAGE_SIZE = 1 page */
#define BUF_SIZE  (PAGE_SIZE << BUF_ORDER)

static dev_t dev_number;
static struct cdev my_cdev;

/* per-open instance data */
struct mmap_dev_priv {
    void *kbuf;               /* kernel buffer (virtual address)   */
    phys_addr_t phy_addr;     /* physical address of the buffer     */
    struct mutex lock;        /* protect concurrent access         */
};

/* ------------------------------------------------------------------ */
/* file operations */
static int mmap_dev_open(struct inode *inode, struct file *filp)
{
    struct mmap_dev_priv *priv;

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    /* 申请一页连续内存，方便映射 */
    priv->kbuf = (void *)__get_free_pages(GFP_KERNEL | GFP_DMA, BUF_ORDER);
    if (!priv->kbuf) {
        kfree(priv);
        return -ENOMEM;
    }

    /* 把虚拟地址转换为物理地址（后面映射要用） */
    priv->phy_addr = virt_to_phys(priv->kbuf);
    mutex_init(&priv->lock);

    filp->private_data = priv;
    pr_info("%s: open, kbuf=%p, phy=0x%llx\n",
            DEV_NAME, priv->kbuf, (unsigned long long)priv->phy_addr);
    return 0;
}

static int mmap_dev_release(struct inode *inode, struct file *filp)
{
    struct mmap_dev_priv *priv = filp->private_data;

    if (priv) {
        if (priv->kbuf)
            free_pages((unsigned long)priv->kbuf, BUF_ORDER);
        mutex_destroy(&priv->lock);
        kfree(priv);
    }
    pr_info("%s: release\n", DEV_NAME);
    return 0;
}

/*
 * mmap 实现
 *   user_vma->vm_start .. vm_end   ---->  这段物理页
 */
static int mmap_dev_mmap(struct file *filp, struct vm_area_struct *vma)
{
    struct mmap_dev_priv *priv = filp->private_data;
    unsigned long pfn;
    size_t size = vma->vm_end - vma->vm_start;

    if (!priv)
        return -ENODEV;

    /* 只允许映射单页（本例），否则返回错误 */
    if (size > BUF_SIZE) {
        pr_err("%s: mmap size too large: %zu > %d\n",
                DEV_NAME, size, BUF_SIZE);
        return -EINVAL;
    }

    /* 物理页号 */
    pfn = priv->phy_addr >> PAGE_SHIFT;

    /* 关闭用户空间对该 VMA 的写回（cache） */
    vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);

    /*
     * 把物理页映射进用户进程。第 3 参数是页帧号 (PFN)。
     * 第 4 参数是映射属性，这里保持 vma 原有的属性 (read/write/exec)
     */
    if (remap_pfn_range(vma, vma->vm_start, pfn,
                        size, vma->vm_page_prot))
        return -EIO;

    pr_info("%s: mmap ok, user addr 0x%lx - 0x%lx, pfn 0x%lx\n",
            DEV_NAME, vma->vm_start, vma->vm_end, pfn);
    return 0;
}

/* 为演示提供一个 ioctl 用来把内核缓冲区填充固定的内容 */
static long mmap_dev_ioctl(struct file *filp, unsigned int cmd,
                           unsigned long arg)
{
    struct mmap_dev_priv *priv = filp->private_data;
    const char pattern[] = "Hello from kernel!\n";

    if (!priv)
        return -ENODEV;

    mutex_lock(&priv->lock);
    memcpy(priv->kbuf, pattern, sizeof(pattern));
    mutex_unlock(&priv->lock);
    return 0;
}

/* file_operations 结构 */
static const struct file_operations mmap_dev_fops = {
    .owner          = THIS_MODULE,
    .open           = mmap_dev_open,
    .release        = mmap_dev_release,
    .mmap           = mmap_dev_mmap,
    .unlocked_ioctl = mmap_dev_ioctl,
};

/* ------------------------------------------------------------------ */
/* module init / exit */
static int __init mmap_dev_init(void)
{
    int ret;

    /* 申请设备号 */
    ret = alloc_chrdev_region(&dev_number, 0, 1, DEV_NAME);
    if (ret) {
        pr_err("%s: failed to allocate chrdev region\n", DEV_NAME);
        return ret;
    }

    cdev_init(&my_cdev, &mmap_dev_fops);
    my_cdev.owner = THIS_MODULE;
    ret = cdev_add(&my_cdev, dev_number, 1);
    if (ret) {
        pr_err("%s: failed to add cdev\n", DEV_NAME);
        unregister_chrdev_region(dev_number, 1);
        return ret;
    }

    pr_info("%s: loaded, major=%d, minor=%d\n",
            DEV_NAME, MAJOR(dev_number), MINOR(dev_number));
    pr_info("%s: use `mknod /dev/%s c %d 0` to create device file\n",
            DEV_NAME, DEV_NAME, MAJOR(dev_number));
    return 0;
}

static void __exit mmap_dev_exit(void)
{
    cdev_del(&my_cdev);
    unregister_chrdev_region(dev_number, 1);
    pr_info("%s: unloaded\n", DEV_NAME);
}

module_init(mmap_dev_init);
module_exit(mmap_dev_exit);

MODULE_AUTHOR("示例代码");
MODULE_DESCRIPTION("使用 mmap 在用户态/内核态共享一页内存的演示");
MODULE_LICENSE("GPL");
```

### 编译 Makefile

```makefile
# Makefile 同目录下
obj-m += my_mmap_dev.o

all:
	make -C /lib/modules/$(shell uname -r)/build M=$(PWD) modules

clean:
	make -C /lib/modules/$(shell uname -r)/build M=$(PWD) clean
```

> **编译 & 加载**  
> ```bash
> $ make
> $ sudo insmod my_mmap_dev.ko
> # 创建设备文件（根据上面打印的 major）
> $ sudo mknod /dev/my_mmap_dev c <major> 0
> $ ls -l /dev/my_mmap_dev
> ```

---

## 2. 用户空间程序（user_mmap.c）

```c
/*
 *  示例：在用户态 mmap 访问内核分配的页面
 *  编译: gcc -Wall -O2 -o user_mmap user_mmap.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <string.h>
#include <errno.h>

#define DEV_PATH "/dev/my_mmap_dev"
#define MAP_SIZE  (4096)          /* 与内核端的 PAGE_SIZE 对齐 */

int main(void)
{
    int fd;
    void *vaddr;

    fd = open(DEV_PATH, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    /* 通过 ioctl 让内核写入一段已知的字符串（可选） */
    if (ioctl(fd, 0, 0) < 0) {   /* cmd = 0, arg = 0，实际不重要 */
        perror("ioctl");
        /* 继续执行也是可以的，只是内核缓冲区里可能是未初始化的 */
    }

    /* mmap 这段设备文件 */
    vaddr = mmap(NULL, MAP_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (vaddr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    printf("User: mapped address = %p\n", vaddr);
    printf("User: content after ioctl (may be empty):\n");
    printf("%s", (char *)vaddr);

    /* 写入新内容到共享页面 */
    const char *msg = "Hello from user space!\n";
    strncpy((char *)vaddr, msg, MAP_SIZE - 1);
    ((char *)vaddr)[MAP_SIZE - 1] = '\0';   /* 确保结尾 */

    printf("User: wrote \"%s\"\n", msg);
    printf("User: reading back from same mapping:\n");
    printf("%s", (char *)vaddr);

    /* 取消映射并关闭 */
    if (munmap(vaddr, MAP_SIZE) < 0)
        perror("munmap");

    close(fd);
    return 0;
}
```

### 运行示例

```bash
$ gcc -Wall -O2 -o user_mmap user_mmap.c
$ sudo ./user_mmap
User: mapped address = 0x7f1e4c300000
User: content after ioctl (may be empty):
Hello from kernel!

User: wrote "Hello from user space!
"
User: reading back from same mapping:
Hello from user space!
```

> **说明**  
> - 通过 `ioctl`（这里的 `cmd=0` 仅作演示）内核把 `"Hello from kernel!\n"` 写入共享页，用户随后读取到该内容。  
> - 用户随后把自己的字符串写回同一页，内核侧（如果你在内核里再读 `priv->kbuf`）会看到相同的数据，说明真正实现了 **零拷贝共享**。  

---

## 3. 关键点回顾与注意事项

| 位置 | 关键要点 |
|------|----------|
| **缓冲区分配** | 必须是页对齐且连续（`__get_free_pages()` / `alloc_pages()`），否则 `remap_pfn_range()` 不能直接映射。 |
| **物理地址** | 使用 `virt_to_phys()` 把内核虚拟地址转为物理地址，然后右移 `PAGE_SHIFT` 得到 PFN。 |
| **`remap_pfn_range()` 参数** | 第 2 参数是用户虚拟地址起点，第 3 参数是 PFN，第 4 参数是映射长度（必须 ≤ 分配的页数），第 5 参数是页属性（`pgprot_noncached` 常用于 I/O 缓冲）。 |
| **同步** | 示例使用 `mutex` 来保护多进程并发读写；真实驱动应根据需求使用原子操作、`semaphore`、`wait_queue` 等。 |
| **安全** | `mmap` 可被任意进程调用，务必检查 `vma->vm_end - vma->vm_start` 是否超过实际缓冲区大小，防止越界映射。 |
| **一致性** | 如果映射的内存需要在 CPU 与 DMA 之间保持一致（比如硬件外设），应使用 `dma_alloc_coherent()` 或 `kmalloc()` + `dma_map_single()` 并在映射时选用 `pgprot_writecombine`/`pgprot_device`。 |
| **错误处理** | 内核 `mmap` 出错要返回 `-EFAULT`、`-EINVAL`、`-EIO` 等合适错误码。 |

---

## 4. 进一步扩展（可选）

1. **多页共享**：把 `BUF_ORDER` 改为 >0，分配多页后在 `mmap` 时循环 `remap_pfn_range`（或使用 `vm_insert_page`）映射完整区域。  
2. **支持 `poll/select`**：在 `file_operations` 中实现 `poll`，结合 `wake_up_interruptible()` 在用户写入时通知。  
3. **使用 `vm_operations_struct`**：如果需要实现页面写回、缺页处理等高级特性，可在 `mmap` 中填充 `vma->vm_ops`。  
4. **使用 `procfs`/`sysfs`**：把设备改写为 `miscdevice` 或 `procfs`，免除手动 `mknod`。  

---

**完整示例**已经可以直接编译、加载、运行，演示了 **用户态进程** 与 **内核模块** 之间利用 `mmap` 进行 **零拷贝共享内存** 的最核心流程。祝你玩得开心！ 🚀

