 * --------------------------------------------------------------*/
static void remove_client(int client_fd,
                          fd_set *all_read_fds,
                          fd_set *all_write_fds)
{
    close(client_fd);
    FD_CLR(client_fd, all_read_fds);
    FD_CLR(client_fd, all_write_fds);
}

/* --------------------------------------------------------------
 * Основная функция
 * --------------------------------------------------------------*/
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    /* ---------- 1. Создание слушающего сокета ----------------- */
    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd < 0) die("socket");

    /* Позволяем быстро переиспользовать порт после завершения */
    int opt = 1;
    if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0)
        die("setsockopt");

    struct sockaddr_in srv_addr;
    memset(&srv_addr, 0, sizeof(srv_addr));
    srv_addr.sin_family = AF_INET;
    srv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    srv_addr.sin_port = htons((uint16_t)atoi(argv[1]));

    if (bind(listen_fd,
             (struct sockaddr *)&srv_addr,
             sizeof(srv_addr)) < 0)
        die("bind");

    if (listen(listen_fd, LISTEN_BACKLOG) < 0)
        die("listen");

    printf("Server started, listening on port %s\n", argv[1]);

    /* ---------- 2. Инициализация наборов fd_set ---------------- */
    fd_set all_read_fds;   // набор всех дескрипторов, из которых требуется чтение
    fd_set all_write_fds;  // набор всех дескрипторов, в которые можно писать
    fd_set read_fds;       // копия для select()
    fd_set write_fds;      // копия для select()

    FD_ZERO(&all_read_fds);
    FD_ZERO(&all_write_fds);

    FD_SET(listen_fd, &all_read_fds);   // будем слушать входящие соединения
    int max_fd = listen_fd;             // максимум среди всех дескрипторов

    /* ---------- 3. Основной цикл сервера ---------------------- */
    while (true) {
        /* select() изменяет переданные наборы, поэтому перед вызовом
           делаем их копию. */
        read_fds  = all_read_fds;
        write_fds = all_write_fds;

        int nready = select(max_fd + 1, &read_fds, &write_fds, NULL, NULL);
        if (nready < 0) {
            if (errno == EINTR)   // прервано сигналом
                continue;
            die("select");
        }

        /* ---- 3.1. Обработка новых входящих соединений --------- */
        if (FD_ISSET(listen_fd, &read_fds)) {
            struct sockaddr_in cli_addr;
            socklen_t cli_len = sizeof(cli_addr);
            int client_fd = accept(listen_fd,
                                   (struct sockaddr *)&cli_addr,
                                   &cli_len);
            if (client_fd < 0) {
                perror("accept");
                continue;   // не фатальная ошибка, продолжаем цикл
            }

            char cli_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &cli_addr.sin_addr, cli_ip, sizeof(cli_ip));
            printf("New connection from %s:%d, fd=%d\n",
                   cli_ip, ntohs(cli_addr.sin_port), client_fd);

            /* Добавляем клиент в наборы */
            add_client(client_fd, &all_read_fds, &all_write_fds, &max_fd);
            nready--;
        }

        /* ---- 3.2. Обработка уже существующих клиентских сокетов ---- */
        for (int fd = 0; fd <= max_fd && nready > 0; ++fd) {
            if (fd == listen_fd)   // уже обработали выше
                continue;

            /* ---------- Чтение из клиента --------------------- */
            if (FD_ISSET(fd, &read_fds)) {
                char buf[BUF_SIZE];
                ssize_t rc = recv(fd, buf, sizeof(buf), 0);
                if (rc < 0) {
                    perror("recv");
                    remove_client(fd, &all_read_fds, &all_write_fds);
                } else if (rc == 0) {
                    /* К клиенту закрыли соединение */
                    printf("Client fd=%d closed connection\n", fd);
                    remove_client(fd, &all_read_fds, &all_write_fds);
                } else {
                    /* Данные получены – отсылаем их обратно (echo) */
                    ssize_t sent = 0;
                    while (sent < rc) {
                        ssize_t ws = send(fd, buf + sent, rc - sent, 0);
                        if (ws < 0) {
                            perror("send");
                            remove_client(fd, &all_read_fds, &all_write_fds);
                            break;
                        }
                        sent += ws;
                    }
                }
                nready--;
            }

            /* Если бы у вас была очередь исходящих сообщений,
               здесь бы проверялся FD_ISSET(fd, &write_fds) */
        }

        /* (Опционально) можно очистить «мертвые» дескрипторы:
           если max_fd больше, чем любой активный fd, сужаем его. */
        while (max_fd > 0 && !FD_ISSET(max_fd, &all_read_fds) &&
               !FD_ISSET(max_fd, &all_write_fds))
            --max_fd;
    }

    /* Никогда не достигается, но на случай изменения кода */
    close(listen_fd);
    return 0;
}
```

### Как это работает?

| Шаг | Что делаем | Как `select` помогает |
|-----|------------|-----------------------|
| **1** | Создаём слушающий TCP‑сокет, привязываем его к порту, ставим `listen`. | — |
| **2** | Инициализируем два набора `fd_set`: `all_read_fds` – все дескрипторы, от которых хотим читать (включая `listen_fd`), и `all_write_fds` – дескрипторы, в которые можно писать (в этом простом примере не используется). | — |
| **3** | В бесконечном цикле копируем наборы в локальные переменные и вызываем `select`. | `select` блокируется, пока хотя бы один из дескрипторов не станет готовым к операции (чтение/запись). |
| **4** | Если готов `listen_fd` → вызываем `accept`, получаем новый клиентский сокет и добавляем его в `all_read_fds`. | Появившийся дескриптор сразу попадает в набор, и в следующей итерации `select` будет отслеживать его. |
| **5** | Для каждого клиентского дескриптора, готового к чтению, вызываем `recv`. Если получены данные – сразу их `send` обратно. Если клиент закрыл соединение – удаляем дескриптор из наборов и закрываем сокет. | `select` сообщает точно, какие клиентские сокеты имеют данные, поэтому мы читаем **только** готовые, без блокировки. |
| **6** | При необходимости можно добавить очередь исходящих сообщений и использовать `write_fds` (в примере опущено, поскольку отправка производится сразу). | `select` также умеет следить за готовностью к записи, позволяя реализовать буферизацию. |

### Что ещё можно улучшить?

* **Буферизация исходящих данных** – вместо `send` сразу, записывать в очередь и включать дескриптор в `write_fds`, чтобы писать только когда сокет не блокируется.  
* **Обработка сигнала SIGINT** (корректное закрытие всех сокетов).  
* **Поддержка больших файловых дескрипторов** – `select` ограничен `FD_SETSIZE` (обычно 1024). Для более масштабных серверов лучше использовать `poll`/`epoll` (Linux) или `kqueue` (BSD).  
* **Таймауты** – третий аргумент `select` позволяет задать периодическое пробуждение (например, для чистки неактивных соединений).  

### Как собрать и запустить

```bash
gcc -Wall -Wextra -O2 -o echo_select_server echo_select_server.c
./echo_select_server 12345   # прослушка порта 12345
```

Подключаемся к серверу из разных терминалов:

```bash
telnet 127.0.0.1 12345
# напишите что‑нибудь → получите то же самое обратно
```

Сервер обслуживает *все* подключённые клиенты одновременно, хотя в процессе работает всего один поток. Всё благодаря системному вызову `select`, который сообщает о готовности ввода‑вывода без блокировки.

