```c
/*
 * prcinfo.c
 *
 * Synopsis
 *   prcinfo  <root_process>  <pid1> [pid2 … pid5]  [OPTION]
 *
 *   root_process – PID of a process that is a descendant of the current
 *                  bash (the parent of this program).
 *   pid1 … pid5 – PIDs that we want to examine (1 … 5 of them).
 *   OPTION      – one of
 *                   -nd  non‑direct descendants of pid1
 *                   -dd  direct (immediate) children of pid1
 *                   -sb  siblings of pid1
 *                   -sz  sibling(s) that are defunct (state ‘Z’)
 *                   -gc  grandchildren of pid1
 *                   -zz  status (defunct / not‑defunct) of pid1
 *                   -zc  direct children of pid1 that are defunct
 *
 * What it does
 *   1. Reads the whole /proc tree once and builds a small in‑memory table
 *      (pid → ppid, state).
 *   2. For each pid supplied on the command line it prints   PID  PPID
 *      only when the pid is a descendant of <root_process>.
 *   3. If an OPTION is present, extra information about the first pid
 *      (pid1) is printed according to the description above.
 *
 * Build
 *     gcc -Wall -Wextra -O2 -o prcinfo prcinfo.c
 *
 * Limitations
 *   * Works only on Linux systems that expose the /proc pseudo‑filesystem.
 *   * The program does not try to keep the table up‑to‑date while it runs;
 *     processes that disappear after the scan are silently ignored.
 *   * No special privileges are required – we only read files that are
 *     world‑readable (the ones we need from /proc).
 */

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <ctype.h>
#include <unistd.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>

/* --------------------------------------------------------------- */
/*  Simple structure that holds the information we need about a   */
/*  process.                                                       */
/* --------------------------------------------------------------- */
typedef struct {
    pid_t pid;          /* process id                                   */
    pid_t ppid;         /* parent pid                                   */
    char  state;        /* process state as shown in /proc/[pid]/stat   */
} ProcInfo;

/* --------------------------------------------------------------- */
/*  Dynamic array of ProcInfo objects.  The size is unknown at     */
/*  compile time, therefore we grow it while scanning /proc.       */
/* --------------------------------------------------------------- */
typedef struct {
    ProcInfo *data;
    size_t    used;
    size_t    size;
} ProcTable;

static void init_table(ProcTable *t)
{
    t->used = 0;
    t->size = 256;                /* start with a reasonable chunk */
    t->data = malloc(t->size * sizeof(ProcInfo));
    if (!t->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
}

static void add_entry(ProcTable *t, ProcInfo pi)
{
    if (t->used == t->size) {
        t->size *= 2;
        t->data = realloc(t->data, t->size * sizeof(ProcInfo));
        if (!t->data) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }
    t->data[t->used++] = pi;
}

/* --------------------------------------------------------------- */
/*  Return a pointer to the ProcInfo for a given pid, or NULL if    */
/*  the pid is not present in the table.                           */
/* --------------------------------------------------------------- */
static ProcInfo *lookup(ProcTable *t, pid_t pid)
{
    for (size_t i = 0; i < t->used; ++i)
        if (t->data[i].pid == pid)
            return &t->data[i];
    return NULL;
}

/* --------------------------------------------------------------- */
/*  Parse the first line of /proc/<pid>/stat.  The format is        */
/*      pid (comm) state ppid ...                                   */
/*  We are interested only in pid, ppid and state.                 */
/* --------------------------------------------------------------- */
static int read_stat(pid_t pid, ProcInfo *pi)
{
    char path[PATH_MAX];
    snprintf(path, sizeof(path), "/proc/%d/stat", pid);

    FILE *f = fopen(path, "r");
    if (!f)
        return -1;                       /* process vanished or permission denied */

    /* The comm field may contain spaces and is surrounded by parentheses.
       The safest way is to read the whole line and then scan it. */
    char line[4096];
    if (!fgets(line, sizeof(line), f)) {
        fclose(f);
        return -1;
    }
    fclose(f);

    /* Extract the three fields we need */
    char comm[256];
    int scanned = sscanf(line,
                         "%d "      /* pid   */
                         "%255s "   /* comm  (including parentheses) */
                         "%c "      /* state */
                         "%d",      /* ppid  */
                         &pi->pid, comm, &pi->state, &pi->ppid);
    if (scanned != 4)    /* malformed line */
        return -1;

    return 0;
}

/* --------------------------------------------------------------- */
/*  Fill the ProcTable with an entry for every numeric directory   */
/*  under /proc.                                                   */
/* --------------------------------------------------------------- */
static void build_proc_table(ProcTable *tbl)
{
    DIR *proc = opendir("/proc");
    if (!proc) {
        perror("opendir /proc");
        exit(EXIT_FAILURE);
    }

    struct dirent *de;
    while ((de = readdir(proc)) != NULL) {
        if (!isdigit(de->d_name[0]))
            continue;               /* not a process directory */

        pid_t pid = (pid_t)strtol(de->d_name, NULL, 10);
        ProcInfo pi = {0};
        if (read_stat(pid, &pi) == 0)
            add_entry(tbl, pi);
        /* silently ignore processes we could not read – they probably exited */
    }
    closedir(proc);
}

/* --------------------------------------------------------------- */
/*  Return 1 if ‘candidate’ is a descendant of ‘root’, otherwise 0.  */
/*  The algorithm walks up the parent chain using the table we     */
/*  built from /proc.                                             */
/* --------------------------------------------------------------- */
static int is_descendant(ProcTable *tbl, pid_t candidate, pid_t root)
{
    if (candidate == root)
        return 1;               /* root is its own descendant for our purposes */

    ProcInfo *info = lookup(tbl, candidate);
    while (info) {
        if (info->ppid == root)
            return 1;
        if (info->ppid == 0)                /* reached the system root */
            break;
        info = lookup(tbl, info->ppid);
    }
    return 0;
}

/* --------------------------------------------------------------- */
/*  Helpers that collect sets of PIDs according to the option     */
/* --------------------------------------------------------------- */

/* recursive walk – fills ‘list’ with every descendant of ‘pid’.
   If ‘skip_direct_children’ is true the direct children are ignored.
   If ‘state_filter’ is non‑zero only processes whose state matches it
   are added (e.g. 'Z' for defunct). */
static void collect_descendants(ProcTable *tbl, pid_t pid,
                                int skip_direct_children,
                                char state_filter,
                                int *list, size_t *cnt, size_t max)
{
    for (size_t i = 0; i < tbl->used; ++i) {
        ProcInfo *pi = &tbl->data[i];
        if (pi->ppid == pid) {
            int direct = 1;
            if (skip_direct_children)
                direct = 0;                     /* we are *not* interested in them */
            if (direct) {
                if (state_filter == 0 || pi->state == state_filter) {
                    if (*cnt < (int)max) list[(*cnt)++] = pi->pid;
                }
                /* still walk deeper to get grandchildren, etc. */
                collect_descendants(tbl, pi->pid, skip_direct_children,
                                    state_filter, list, cnt, max);
            } else {   /* we are asked for “non‑direct” descendants -> go deeper */
                collect_descendants(tbl, pi->pid, 0,
                                    state_filter, list, cnt, max);
            }
        }
    }
}

/* children of a given pid (option –dd, –zc) */
static void collect_children(ProcTable *tbl, pid_t pid,
                             char state_filter,
                             int *list, size_t *cnt, size_t max)
{
    for (size_t i = 0; i < tbl->used; ++i) {
        ProcInfo *pi = &tbl->data[i];
        if (pi->ppid == pid) {
            if (state_filter == 0 || pi->state == state_filter) {
                if (*cnt < (int)max) list[(*cnt)++] = pi->pid;
            }
        }
    }
}

/* siblings of a given pid (option –sb, –sz) */
static void collect_siblings(ProcTable *tbl, pid_t pid,
                             char state_filter,
                             int *list, size_t *cnt, size_t max)
{
    ProcInfo *me = lookup(tbl, pid);
    if (!me) return;                    /* pid vanished while we were scanning */
    pid_t parent = me->ppid;

    for (size_t i = 0; i < tbl->used; ++i) {
        ProcInfo *pi = &tbl->data[i];
        if (pi->ppid == parent && pi->pid != pid) {
            if (state_filter == 0 || pi->state == state_filter) {
                if (*cnt < (int)max) list[(*cnt)++] = pi->pid;
            }
        }
    }
}

/* grandchildren – children of children (option –gc) */
static void collect_grandchildren(ProcTable *tbl, pid_t pid,
                                  int *list, size_t *cnt, size_t max)
{
    int children[1024];
    size_t nchildren = 0;
    collect_children(tbl, pid, 0, children, &nchildren, 1024);
    for (size_t i = 0; i < nchildren; ++i) {
        collect_children(tbl, children[i], 0, list, cnt, max);
    }
}

/* --------------------------------------------------------------- */
/*  Pretty‑print a list of PIDs (or say “none”).                    */
/* --------------------------------------------------------------- */
static void print_pid_list(const char *title, int *list, size_t n)
{
    printf("%s:", title);
    if (n == 0) {
        printf("  none\n");
        return;
    }
    for (size_t i = 0; i < n; ++i)
        printf(" %d", list[i]);
    putchar('\n');
}

/* --------------------------------------------------------------- */
/*  Main – argument handling, table building, output.              */
/* --------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc < 3) {
        fprintf(stderr,
                "Usage: %s <root_process> <pid1> [pid2 … pid5] [OPTION]\n"
                "OPTIONS: -nd -dd -sb -sz -gc -zz -zc\n",
                argv[0]);
        exit(EXIT_FAILURE);
    }

    /* ------ 1. parse arguments ----------------------------------- */
    pid_t root_pid = (pid_t)strtol(argv[1], NULL, 10);
    if (root_pid <= 0) {
        fprintf(stderr, "Invalid root PID: %s\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    /* Collect the list of process IDs that the user asked about.
       They are all arguments after <root_process> until we see an
       argument that starts with '-'. */
    pid_t pids[5];
    size_t npids = 0;
    const char *opt = NULL;

    for (int i = 2; i < argc; ++i) {
        if (argv[i][0] == '-') {
            opt = argv[i];
            break;
        }
        if (npids >= 5) {
            fprintf(stderr, "Too many process IDs – maximum is 5.\n");
            exit(EXIT_FAILURE);
        }
        pid_t p = (pid_t)strtol(argv[i], NULL, 10);
        if (p <= 0) {
            fprintf(stderr, "Invalid PID: %s\n", argv[i]);
            exit(EXIT_FAILURE);
        }
        pids[npids++] = p;
    }

    /* ------------------------------------------------------------ */
    /* 2. Build the process table once (read /proc).                */
    ProcTable table;
    init_table(&table);
    build_proc_table(&table);

    /* ------------------------------------------------------------ */
    /* 3. For each PID supplied on the command line print its PID   */
    /*    and PPID **only** when it belongs to the tree rooted at   */
    /*    <root_process>.                                           */
    printf("PID   PPID\n");
    for (size_t i = 0; i < npids; ++i) {
        pid_t pid = pids[i];
        if (!lookup(&table, pid)) {
            printf("%-5d  (process vanished)\n", pid);
            continue;
        }
        if (is_descendant(&table, pid, root_pid)) {
            ProcInfo *pi = lookup(&table, pid);
            printf("%-5d  %d\n", pi->pid, pi->ppid);
        } else {
            printf("%-5d  (not a descendant of %d)\n", pid, root_pid);
        }
    }

    /* ------------------------------------------------------------ */
    /* 4. If an option was given, produce the extra information     */
    /*    **only** for the first PID in the list (pid1).             */
    if (opt && npids > 0) {
        pid_t pid1 = pids[0];
        ProcInfo *info1 = lookup(&table, pid1);
        if (!info1) {
            fprintf(stderr, "Cannot produce option %s – pid %d no longer exists.\n",
                    opt, pid1);
            exit(EXIT_FAILURE);
        }

        /* common buffers – we never need more than a few thousand PIDs */
        int buffer[8192];
        size_t n = 0;

        if (strcmp(opt, "-nd") == 0) {
            /* non‑direct descendants = all descendants except immediate children */
            collect_descendants(&table, pid1, 1, 0, buffer, (int *)&n, 8192);
            print_pid_list("Non‑direct descendants of", buffer, n);
        } else if (strcmp(opt, "-dd") == 0) {
            collect_children(&table, pid1, 0, buffer, (int *)&n, 8192);
            print_pid_list("Direct children of", buffer, n);
        } else if (strcmp(opt, "-sb") == 0) {
            collect_siblings(&table, pid1, 0, buffer, (int *)&n, 8192);
            print_pid_list("Sibling processes of", buffer, n);
        } else if (strcmp(opt, "-sz") == 0) {
            collect_siblings(&table, pid1, 'Z', buffer, (int *)&n, 8192);
            print_pid_list("Defunct siblings of", buffer, n);
        } else if (strcmp(opt, "-gc") == 0) {
            collect_grandchildren(&table, pid1, buffer, (int *)&n, 8192);
            print_pid_list("Grandchildren of", buffer, n);
        } else if (strcmp(opt, "-zz") == 0) {
            printf("Status of %d: %s\n", pid1,
                   (info1->state == 'Z') ? "Defunct" : "Not Defunct");
        } else if (strcmp(opt, "-zc") == 0) {
            collect_children(&table, pid1, 'Z', buffer, (int *)&n, 8192);
            print_pid_list("Defunct direct children of", buffer, n);
        } else {
            fprintf(stderr, "Unknown option: %s\n", opt);
            exit(EXIT_FAILURE);
        }
    }

    /* ------------------------------------------------------------ */
    free(table.data);
    return 0;
}
