/*********************************************************************
 *  万年历 - 日期调整实验
 *  功能：
 *      1) 通过键盘输入初始日期（年 月 日）。
 *      2) 菜单可对该日期进行 增加/减少 年、月、日。
 *      3) “重置”功能把日期恢复为最初输入的时间（不再需要手动输入）。
 *      4) 自动处理闰年、月份天数等边界情况。
 *
 *  编译（gcc）:  gcc -Wall -Wextra -std=c11 -o calendar calendar.c
 *
 *  作者:  ChatGPT (OpenAI)   日期: 2024‑06
 *********************************************************************/

#include <stdio.h>
#include <time.h>
#include <stdbool.h>

/*--------------------------------------------------------------
 *  把 struct tm 中的年月日标准化（利用 mktime 自动进位/借位）。
 *  返回标准化后的 struct tm（时间部分被置零，仅保留 Y/M/D）。
 *--------------------------------------------------------------*/
static struct tm normalize_date(struct tm t)
{
    /* mktime 会把 t.tm_isdst 设为 -1，表示自行决定夏令时 */
    t.tm_isdst = -1;
    /* 只关心年月日，时分秒设为 0，避免跨日的意外 */
    t.tm_hour = 0;
    t.tm_min  = 0;
    t.tm_sec  = 0;

    /* time_t -> struct tm（会自动进位、处理闰年等） */
    time_t tt = mktime(&t);
    if (tt == (time_t)-1) {
        /* 这几乎不可能发生，除非输入的日期极端错误 */
        fprintf(stderr, "日期标准化失败！\n");
        return t;
    }
    return *localtime(&tt);
}

/*--------------------------------------------------------------
 *  增/减 年、月、日的统一实现
 *  deltaYear / deltaMonth / deltaDay 可以为正或负
 *--------------------------------------------------------------*/
static void add_year(struct tm *date, int deltaYear)
{
    date->tm_year += deltaYear;
    *date = normalize_date(*date);
}

static void add_month(struct tm *date, int deltaMonth)
{
    date->tm_mon += deltaMonth;          /* tm_mon: 0~11 */
    *date = normalize_date(*date);
}

static void add_day(struct tm *date, int deltaDay)
{
    date->tm_mday += deltaDay;           /* tm_mday: 1~31 */
    *date = normalize_date(*date);
}

/*--------------------------------------------------------------
 *  打印日期的统一函数（格式：YYYY-MM-DD）
 *--------------------------------------------------------------*/
static void print_date(const struct tm *date)
{
    printf("%04d-%02d-%02d\n",
           date->tm_year + 1900,
           date->tm_mon  + 1,
           date->tm_mday);
}

/*--------------------------------------------------------------
 *  主程序
 *--------------------------------------------------------------*/
int main(void)
{
    struct tm curDate = {0};   /* 当前操作的日期 */
    struct tm baseDate = {0};  /* 用来“重置”的原始日期 */
    int year, month, day;

    /*------------------- 读取初始日期 ------------------------*/
    printf("请输入初始日期（ 年 月 日，用空格分隔 ）: ");
    if (scanf("%d %d %d", &year, &month, &day) != 3) {
        fprintf(stderr, "输入格式错误！程序退出。\n");
        return 1;
    }

    /* 检查月份、日期的基本合法性（后面会再用 mktime 纠正） */
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        fprintf(stderr, "月份或日期超出常规范围！程序退出。\n");
        return 1;
    }

    /* 把用户输入装进 struct tm 并标准化 */
    curDate.tm_year = year  - 1900;   /* tm_year 从 1900 开始计数 */
    curDate.tm_mon  = month - 1;      /* tm_mon 从 0 开始计数 */
    curDate.tm_mday = day;
    curDate = normalize_date(curDate);
    baseDate = curDate;               /* 保存一份用于“重置” */

    printf("\n--- 初始日期已设为: ");
    print_date(&curDate);
    printf("---\n\n");

    /*------------------- 主循环 ------------------------------*/
    while (true) {
        int choice;
        printf("\n当前日期: ");
        print_date(&curDate);
        printf("\n请选择操作:\n"
               " 1) 增加一年   2) 减少一年\n"
               " 3) 增加一月   4) 减少一月\n"
               " 5) 增加一天   6) 减少一天\n"
               " 7) 重置为最初输入的日期\n"
               " 0) 退出程序\n"
               " 输入选项 (0~7): ");

        if (scanf("%d", &choice) != 1) {
            /* 清除非法输入 */
            int c; while ((c = getchar()) != '\n' && c != EOF) { }
            printf("无效输入，请重新选择。\n");
            continue;
        }

        switch (choice) {
            case 1: add_year(&curDate, +1); break;
            case 2: add_year(&curDate, -1); break;
            case 3: add_month(&curDate, +1); break;
            case 4: add_month(&curDate, -1); break;
            case 5: add_day(&curDate, +1); break;
            case 6: add_day(&curDate, -1); break;
            case 7:
                curDate = baseDate;      /* 重置 */
                printf("已恢复为最初输入的日期。\n");
                break;
            case 0:
                printf("感谢使用！程序退出。\n");
                return 0;
            default:
                printf("选项错误，请重新输入 0~7 之间的数字。\n");
                break;
        }
    }

    return 0;   /* 永远不会到达 */
}
```

