```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *answers;   // cleaned answer line (only o,x,-)
    int   base;      // points before possible doubling
    int   mult;      // 1 or 2
} Cat;

int main(void) {
    int b;                         // first 2‑point question
    if (scanf("%d", &b) != 1) return 0;
    int c;
    while ((c = getchar()) != '\n' && c != EOF) ;   // consume rest of line

    const int MAX_LINE = 1024;
    char line[MAX_LINE];

    Cat *cats = NULL;
    int cat_cnt = 0, cat_cap = 0;

    int joker_used = 0;
    int joker_category = -1;        // index of the category that gets the joker

    while (fgets(line, sizeof line, stdin) != NULL) {
        // ignore completely empty lines (might appear at EOF)
        int has_nonspace = 0;
        for (char *p = line; *p; ++p) if (!isspace((unsigned char)*p)) { has_nonspace = 1; break; }
        if (!has_nonspace) continue;

        // make room for a new category
        if (cat_cnt == cat_cap) {
            cat_cap = cat_cap ? cat_cap * 2 : 4;
            cats = realloc(cats, cat_cap * sizeof *cats);
            if (!cats) { perror("realloc"); exit(EXIT_FAILURE); }
        }

        char tmp[MAX_LINE];
        int tlen = 0;
        int pos = 1;               // question number inside the category (1‑based)
        int base = 0;

        for (char *p = line; *p; ++p) {
            char ch = *p;
            if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r')
                continue;
            if (ch == '$' && !joker_used) {
                joker_used = 1;
                joker_category = cat_cnt;      // current category index
                continue;                     // $ is not a question
            }
            if (ch == 'o' || ch == 'x' || ch == '-') {
                tmp[tlen++] = ch;
                if (ch == 'o') {
                    int val = (pos < b) ? 1 : 2;
                    base += val;
                }
                ++pos;
            }
            /* any other character is silently ignored */
        }
        tmp[tlen] = '\0';

        cats[cat_cnt].answers = malloc(tlen + 1);
        strcpy(cats[cat_cnt].answers, tmp);
        cats[cat_cnt].base = base;
        cats[cat_cnt].mult = 1;          // default, may be changed later
        ++cat_cnt;
    }

    /* decide which category is doubled */
    if (joker_used) {
        cats[joker_category].mult = 2;
    } else if (cat_cnt > 0) {
        cats[cat_cnt - 1].mult = 2;     // last category
    }

    /* output cleaned answer strings */
    for (int i = 0; i < cat_cnt; ++i) {
        puts(cats[i].answers);
    }

    /* compute halftime and total points */
    int total = 0;
    int half = 0;
    int half_limit = (cat_cnt + 1) / 2;          // ceil(cat_cnt/2)

    for (int i = 0; i < cat_cnt; ++i) {
        int pts = cats[i].base * cats[i].mult;
        total += pts;
        if (i < half_limit) half += pts;
    }

    printf("%d %d\n", half, total);

    /* free memory */
    for (int i = 0; i < cat_cnt; ++i) free(cats[i].answers);
    free(cats);
    return 0;
}
```

The program follows exactly the algorithm proven correct above and
conforms to the C 99 standard.

