> ```text
> ws_uv_client/
> ├─ CMakeLists.txt          # CMake 编译脚本（也可以用 Makefile / pkg-config）
> └─ ws_client.c             # 示例程序
> ```

---

## 1️⃣ 环境准备

### 1.1 安装依赖

| 包 | 用途 |
|---|---|
| **libwebsockets-dev** | WebSocket 协议栈 |
| **libuv-dev** | 事件循环库 |
| **cmake** | 编译脚本（可选） |

> **Ubuntu/Debian**  
> ```bash
> sudo apt-get update
> sudo apt-get install -y libwebsockets-dev libuv1-dev cmake
> ```

> **CentOS / RHEL**（使用 EPEL）  
> ```bash
> sudo yum install -y epel-release
> sudo yum install -y libwebsockets-devel libuv-devel cmake
> ```

如果系统的官方仓库没有足够新的 libwebsockets（4.0 以上），建议自行编译：

```bash
git clone https://github.com/warmcat/libwebsockets.git
cd libwebsockets
mkdir build && cd build
cmake .. -DLWS_WITH_LIBUV=ON -DCMAKE_BUILD_TYPE=Release
make -j$(nproc)
sudo make install
sudo ldconfig
```

---

## 2️⃣ 编写代码

下面的 `ws_client.c` 包含 **所有关键点**：

* 使用 **libuv** 创建并运行 `uv_loop_t`。
* 在 LWS 创建 `lws_context_t` 时打开 `LWS_SERVER_OPTION_LIBUV`，让 LWS 把所有套接字事件交给 uv 处理。
* 实现 **WebSocket 协议回调**（`lws_callback_function`），处理连接建立、接收、可写、关闭等事件。
* 在 `LWS_CALLBACK_CLIENT_ESTABLISHED` 中立即发送一条 “Hello” 消息（演示写操作）。
* 在 `uv_signal_t` 捕获 **Ctrl‑C**，优雅关闭连接与 uv 循环。

> **关键 API 说明**  
> * `lws_context_creation_info` – 配置 LWS 上下文。  
> * `info.options = LWS_SERVER_OPTION_LIBUV;` – 开启 libuv 集成。  
> * `lws_client_connect_via_info` – 发起客户端连接。  
> * `lws_callback_on_writable` – 让 LWS 在下次 `uv_poll` 可写时回调 `LWS_CALLBACK_CLIENT_WRITEABLE`。  

```c
/*====================================================================
 *  文件: ws_client.c
 *  描述:  使用 libwebsockets + libuv 实现的最小 WebSocket 客户端
 *===================================================================*/

#define _POSIX_C_SOURCE 200809L   /* 为了使用 strdup() 等 POSIX 函数 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <uv.h>
#include <libwebsockets.h>

/* -----------------------------------------------------------------
 *  1. 业务回调函数
 * ----------------------------------------------------------------- */
static int
ws_client_callback(struct lws *wsi,
                   enum lws_callback_reasons reason,
                   void *user, void *in, size_t len)
{
    (void)user;   /* 本例子中不使用 per‑connection user data */

    switch (reason) {

    /* ---- 连接建立成功 --------------------------------------------------- */
    case LWS_CALLBACK_CLIENT_ESTABLISHED:
        lwsl_user("WebSocket 已连接, wsi=%p\n", wsi);
        /* 立刻把要发送的数据放到发送缓冲区，然后触发可写回调 */
        lws_callback_on_writable(wsi);
        break;

    /* ---- 收到服务器发来的帧 -------------------------------------------- */
    case LWS_CALLBACK_CLIENT_RECEIVE:
        lwsl_user("收到数据: %.*s\n", (int)len, (char *)in);
        /* 这里可以根据业务需求处理收到的文本/二进制帧 */
        break;

    /* ---- 当 libuv 通知 socket 可写时调用（发送数据） ------------------- */
    case LWS_CALLBACK_CLIENT_WRITEABLE: {
        const char *msg = "Hello from libwebsockets + libuv!";
        /* LWS 要求我们在写入前预留 LWS_PRE 个字节的头部空间 */
        unsigned char *buf = lws_malloc(LWS_PRE + strlen(msg) + 1, "write buffer");
        if (!buf) {
            lwsl_err("malloc failed\n");
            return -1;
        }
        memcpy(&buf[LWS_PRE], msg, strlen(msg));
        int n = lws_write(wsi, &buf[LWS_PRE], strlen(msg),
                          LWS_WRITE_TEXT);
        lws_free(buf);
        if (n < (int)strlen(msg)) {
            lwsl_err("lws_write failed, wrote %d/%zu bytes\n", n,
                     strlen(msg));
            return -1;
        }
        lwsl_user("已发送: %s\n", msg);
        /* 发送完后如果想再发送更多，可以再次调用 lws_callback_on_writable */
        break;
    }

    /* ---- 连接关闭 ------------------------------------------------------- */
    case LWS_CALLBACK_CLIENT_CONNECTION_ERROR:
        lwsl_user("连接错误: %s\n", in ? (char *)in : "(null)");
        /* 这里返回非 0 可以让 libuv 停止轮询，实际我们在 signal 里
         * 主动关闭 context，下面会解释。 */
        break;

    case LWS_CALLBACK_CLIENT_CLOSED:
        lwsl_user("WebSocket 已关闭\n");
        break;

    default:
        break;
    }

    return 0;
}

/* -----------------------------------------------------------------
 *  2.  声明协议（可以有多个，这里只有一个）
 * ----------------------------------------------------------------- */
static const struct lws_protocols protocols[] = {
    {
        .name = "example-protocol",
        .callback = ws_client_callback,
        .per_session_data_size = 0,
        .rx_buffer_size = 0,          /* 使用默认值（4 KiB） */
    },
    { NULL, NULL, 0, 0 } /* 结束标记 */
};

/* -----------------------------------------------------------------
 *  3.  主函数：初始化 uv + LWS, 发起连接, 运行循环
 * ----------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "用法: %s ws://host:port/path\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *url = argv[1];
    struct lws_client_connect_info conn_info = {0};

    /* ----------- 1) 初始化 libuv 循环 ------------------------------ */
    uv_loop_t *uv_loop = uv_default_loop();   /* 默认循环，后面 LWS 会使用它 */

    /* ----------- 2) 创建 LWS 上下文（打开 libuv 选项） ----------------- */
    struct lws_context_creation_info ctx_info = {0};
    ctx_info.options = LWS_SERVER_OPTION_LIBUV; /* 关键：让 LWS 使用 libuv */
    ctx_info.port = CONTEXT_PORT_NO_LISTEN;     /* 客户端不监听端口 */
    ctx_info.protocols = protocols;
    ctx_info.fd_limit_per_thread = 1 + 16;      /* 较小的默认值即可 */
    ctx_info.user = uv_loop;                    /* 把 uv_loop 传进去，LWS 会取它 */

    struct lws_context *ctx = lws_create_context(&ctx_info);
    if (!ctx) {
        fprintf(stderr, "Failed to create LWS context\n");
        return EXIT_FAILURE;
    }

    /* ----------- 3) 填写连接信息，发起连接 --------------------------- */
    conn_info.context = ctx;
    conn_info.port = 0;                         /* libwebsockets 会自行解析 URL */
    conn_info.address = NULL;                   /* 由 URL 解析 */
    conn_info.path = NULL;                      /* 由 URL 解析 */
    conn_info.host = NULL;                      /* 由 URL 解析 */
    conn_info.origin = NULL;
    conn_info.protocol = protocols[0].name;     /* 这里使用第一个协议 */
    conn_info.ietf_version_or_minus_one = -1;   /* 使用默认的 RFC6455 */
    conn_info.ssl_connection = 0;               /* 若使用 wss://，这里会自动设置 */
    conn_info.userdata = NULL;
    conn_info.client_exts = NULL;
    conn_info.client_exts_count = 0;
    conn_info.pwsi = NULL;
    conn_info.ws_rx_buf_size = 0;
    conn_info.pathex = NULL;                    /* 让 LWS 自己解析 URL */
    conn_info.ssl_connection = 0;

    /* LWS 提供了一个便利函数直接把 URL 解析为上面的字段 */
    if (lws_client_connect_info_parse(&conn_info, url) < 0) {
        fprintf(stderr, "Invalid URL: %s\n", url);
        lws_context_destroy(ctx);
        return EXIT_FAILURE;
    }

    struct lws *wsi = lws_client_connect_via_info(&conn_info);
    if (!wsi) {
        fprintf(stderr, "Failed to initiate client connection\n");
        lws_context_destroy(ctx);
        return EXIT_FAILURE;
    }

    /* ----------- 4) 捕获 SIGINT / SIGTERM，优雅退出 -------------------- */
    uv_signal_t sigint;
    uv_signal_init(uv_loop, &sigint);
    uv_signal_start(&sigint, (uv_signal_cb)[](uv_signal_t* handle, int signum){
        (void)signum;
        lwsl_user("\n收到信号，准备退出...\n");
        /* 关闭 LWS context，内部会把所有 wsi 关闭并释放资源 */
        if (handle->data) {
            struct lws_context *ctx = (struct lws_context *)handle->data;
            lws_context_destroy(ctx);
        }
