**C program – count the numbers that appear more than once**

The program

1. asks the user how many integers he/she will enter,  
2. reads the numbers,  
3. sorts them (so equal values become neighbours),  
4. walks through the sorted list and finds the groups of equal numbers,  
5. reports  

   * **`distinctRepeated`** – how many *different* values are repeated, and  
   * **`totalRepeated`** – the total number of extra occurrences (e.g. for `5 5 5 2 2` it prints `distinctRepeated = 2` and `totalRepeated = 3` because `5` appears three times → two extra copies, `2` appears twice → one extra copy).

The algorithm is `O(N log N)` because of the sort; the scan itself is linear.

```c
/* --------------------------------------------------------------
   Count repeated numbers in a list entered by the user
   -------------------------------------------------------------- */
#include <stdio.h>
#include <stdlib.h>

/* comparison function required by qsort() */
int cmp_int(const void *a, const void *b)
{
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);   /* returns 1, 0 or -1 */
}

int main(void)
{
    int n;                         /* how many numbers will be entered   */
    int *arr = NULL;               /* dynamic array to hold the numbers   */
    int i;

    /* ----------------------------------------------------------
       1) read the size of the list
       ---------------------------------------------------------- */
    printf("How many numbers will you enter? ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid size. Program terminated.\n");
        return EXIT_FAILURE;
    }

    /* ----------------------------------------------------------
       2) allocate space and read the numbers
       ---------------------------------------------------------- */
    arr = (int *)malloc(n * sizeof(int));
    if (!arr) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    printf("Enter the %d integers (separated by spaces or new lines):\n", n);
    for (i = 0; i < n; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            printf("Invalid input. Program terminated.\n");
            free(arr);
            return EXIT_FAILURE;
        }
    }

    /* ----------------------------------------------------------
       3) sort the array – equal numbers become neighbours
       ---------------------------------------------------------- */
    qsort(arr, (size_t)n, sizeof(int), cmp_int);

    /* ----------------------------------------------------------
       4) scan the sorted array and count repetitions
       ---------------------------------------------------------- */
    int distinctRepeated = 0;   /* how many *different* values are repeated */
    int totalRepeated   = 0;   /* total number of extra copies           */

    i = 0;
    while (i < n) {
        int j = i + 1;                     /* look ahead for equal values */
        while (j < n && arr[j] == arr[i])  /* count how many times arr[i] occurs */
            ++j;

        int freq = j - i;                  /* frequency of arr[i] */
        if (freq > 1) {                    /* this value is repeated */
            ++distinctRepeated;            /* one more distinct repeated value */
            totalRepeated += (freq - 1);   /* all extra copies */
        }

        i = j;                             /* move to the next different value */
    }

    /* ----------------------------------------------------------
       5) print the results
       ---------------------------------------------------------- */
    printf("\n--- Result ------------------------------------------------\n");
    printf("You entered %d numbers.\n", n);
    printf("Distinct numbers that are repeated : %d\n", distinctRepeated);
    printf("Total repeated occurrences (extra copies) : %d\n", totalRepeated);
    printf("-----------------------------------------------------------\n");

    /* clean up */
    free(arr);
    return EXIT_SUCCESS;
}
