#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

/* ---------- singly linked list ---------- */
typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* append a new node at the end of the list */
void append(Node **head, Node **tail, int value) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->next = NULL;
    if (*head == NULL) {          // first element
        *head = *tail = new_node;
    } else {
        (*tail)->next = new_node;
        *tail = new_node;
    }
}

/* reverse the list in‑place (only pointers are changed) */
void reverse(Node **head) {
    Node *prev = NULL;
    Node *cur  = *head;
    while (cur) {
        Node *nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    *head = prev;
}

/* print the list: numbers separated by a single space */
void print_list(const Node *head) {
    const Node *p = head;
    while (p) {
        printf("%d", p->data);
        if (p->next) putchar(' ');
        p = p->next;
    }
    putchar('\n');
}

/* free the whole list */
void free_list(Node *head) {
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
}

/* ---------- input processing ---------- */
void read_and_build(Node **head, Node **tail) {
    int c;
    long acc = 0;          // accumulated absolute value
    int sign = 1;          // current sign
    int in_number = 0;     // flag: we are inside a number

    while ((c = getchar()) != EOF) {
        if (c == '.')                 // terminating dot
            break;

        if (isspace(c)) {            // whitespace ends a number
            if (in_number) {
                append(head, tail, (int)(sign * acc));
                in_number = 0;
                acc = 0;
                sign = 1;
            }
            continue;
        }

        if (c == '+' || c == '-') {   // sign of a new number
            if (in_number) {          // sign inside a number -> treat as invalid, finish previous
                append(head, tail, (int)(sign * acc));
                acc = 0;
            }
            sign = (c == '-') ? -1 : 1;
            in_number = 1;            // start a new number (maybe without digits yet)
            continue;
        }

        if (isdigit(c)) {             // digit
            if (!in_number) {         // start a number without explicit sign
                in_number = 1;
                sign = 1;
                acc = 0;
            }
            acc = acc * 10 + (c - '0');
            continue;
        }

        /* any other character – treat as separator, finish a possibly started number */
        if (in_number) {
            append(head, tail, (int)(sign * acc));
            in_number = 0;
            acc = 0;
            sign = 1;
        }
        /* and ignore the character itself */
    }

    /* input ended (or dot was read) while a number was still being built */
    if (in_number) {
        append(head, tail, (int)(sign * acc));
    }
}

/* ---------- main ---------- */
int main(void) {
    Node *head = NULL;
    Node *tail = NULL;

    read_and_build(&head, &tail);

    if (head == NULL) {
        puts("NULL");
        return 0;
    }

    reverse(&head);
    print_list(head);
    free_list(head);
    return 0;
}
```

The program follows exactly the algorithm proven correct above, complies with
the required time (1 s) and memory (64 MiB) limits, and is robust against
incorrect input characters.

