**Solution Overview**

We have to write a single C program that, once started with a text string on the command line, does three things simultaneously  

1. **Sender** – every second it broadcasts that string on UDP port 2346 to the address `255.255.255.255`.  
2. **Receiver** – constantly listens on UDP port 2346, and when a packet whose payload is **exactly** the same string arrives, it stores the sender’s IP address and UDP‑port in a table.  
3. **Viewer** – every 30 seconds the receiver prints the content of that table.

The easiest way to obtain true concurrency in a single source file is to `fork()` two processes:

* **Parent** – the *sender*.
* **Child**  – the *receiver* + *viewer*.

Both processes need to share the table of discovered peers.  
We will create a small shared memory segment with `mmap()` (anonymous, MAP_SHARED).  
Only the child writes to the table, and only the child reads it for printing, so no complex synchronisation is required (the parent never touches that memory).

Below is a complete, well‑commented program that follows the required specification.

--------------------------------------------------------------------

## Code (`udp_broadcast.c`)

```c
/*
 * udp_broadcast.c
 *
 * Usage: ./udp_broadcast "your string"
 *
 * The program forks in two processes.
 *
 *   - Parent: every second it broadcasts the given string on UDP port 2346
 *             to the broadcast address 255.255.255.255.
 *
 *   - Child : receives UDP packets on port 2346.
 *             If the payload exactly matches the argument string,
 *             the sender's IP address and source UDP port are stored
 *             in a shared table.
 *             Every 30 seconds the table is printed.
 *
 * The table lives in a shared memory segment created with mmap().
 * Only the child accesses it, thus no mutexes are required.
 *
 * Compile:
 *      gcc -Wall -O2 -std=c11 -o udp_broadcast udp_broadcast.c
 *
 * Run (needs root on many systems because of the broadcast send):
 *      sudo ./udp_broadcast "hello world"
 *
 * Press Ctrl‑C to stop the program; both processes exit cleanly.
 */

#define _POSIX_C_SOURCE 200112L   /* For POSIX timers, getaddrinfo, etc. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>

/* ------------------------------------------------------------------ */
/* Configuration constants                                            */
#define BROADCAST_IP      "255.255.255.255"
#define UDP_PORT          2346
#define SEND_INTERVAL     1          /* seconds */
#define DISPLAY_INTERVAL  30         /* seconds */
#define MAX_PEERS         256        /* maximum entries in the table */
#define MAX_MSG_LEN       1024       /* safety buffer for UDP payload */

/* ------------------------------------------------------------------ */
/* Data structures placed in shared memory                           */
typedef struct {
    struct sockaddr_in addr;   /* IP address + source port of a peer */
    bool               used;   /* true when entry contains valid data */
} peer_entry_t;

/* The whole shared region */
typedef struct {
    peer_entry_t peers[MAX_PEERS];
    size_t       count;               /* number of filled entries   */
} shared_data_t;

/* Pointer that will be mmap‑ed */
static shared_data_t *shm = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling – we want a clean shutdown                         */
static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;           /* unused */
    keep_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: print a socket address nicely                               */
static void print_sockaddr(const struct sockaddr_in *sa)
{
    char ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &(sa->sin_addr), ip, sizeof(ip));
    printf("%s:%u", ip, ntohs(sa->sin_port));
}

/* ------------------------------------------------------------------ */
/* Sender implementation (parent)                                     */
static void sender(const char *msg)
{
    int sock;
    struct sockaddr_in broadcast_addr;
    size_t msg_len = strlen(msg);

    if (msg_len == 0 || msg_len > MAX_MSG_LEN) {
        fprintf(stderr, "Message length must be between 1 and %d\n", MAX_MSG_LEN);
        exit(EXIT_FAILURE);
    }

    /* Create a UDP socket */
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket (sender)");
        exit(EXIT_FAILURE);
    }

    /* Enable broadcast sending */
    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_BROADCAST, &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_BROADCAST");
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* Prepare the destination address */
    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_port   = htons(UDP_PORT);
    if (inet_pton(AF_INET, BROADCAST_IP, &broadcast_addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid broadcast address %s\n", BROADCAST_IP);
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* Send every SEND_INTERVAL seconds until termination */
    while (keep_running) {
        ssize_t sent = sendto(sock,
                              msg,
                              msg_len,
                              0,
                              (struct sockaddr *)&broadcast_addr,
                              sizeof(broadcast_addr));
        if (sent < 0) {
            perror("sendto");
            /* we continue, a temporary error should not abort the whole program */
        }
        /* Sleep synchronously (handles SIGINT correctly) */
        struct timespec ts = {.tv_sec = SEND_INTERVAL, .tv_nsec = 0};
        nanosleep(&ts, NULL);
    }

    close(sock);
}

/* ------------------------------------------------------------------ */
/* Receiver + viewer implementation (child)                           */
static void receiver_and_viewer(const char *msg)
{
    int sock;
    struct sockaddr_in recv_addr;
    char buffer[MAX_MSG_LEN];
    ssize_t nbytes;
    socklen_t addrlen;
    struct sockaddr_in sender_addr;

    size_t msg_len = strlen(msg);

    /* ------------------------------------------------------------ */
    /* 1️⃣ Create and bind a UDP socket on UDP_PORT                  */
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket (receiver)");
        exit(EXIT_FAILURE);
    }

    /* Allow multiple processes on the same machine to bind the same port
       (useful when you run several instances for testing). */
    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_REUSEADDR");
        close(sock);
        exit(EXIT_FAILURE);
    }

    memset(&recv_addr, 0, sizeof(recv_addr));
    recv_addr.sin_family = AF_INET;
    recv_addr.sin_addr.s_addr = htonl(INADDR_ANY);   /* listen on all interfaces */
    recv_addr.sin_port = htons(UDP_PORT);

    if (bind(sock, (struct sockaddr *)&recv_addr, sizeof(recv_addr)) < 0) {
        perror("bind");
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* ------------------------------------------------------------ */
    /* 2️⃣ Main loop: receive packets + periodic display             */
    time_t last_display = time(NULL);

    while (keep_running) {
        /* Use select() with a timeout of 1 second so that we can break
           the wait when keep_running becomes 0 (Ctrl‑C). */
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(sock, &fds);

        struct timeval tv = {.tv_sec = 1, .tv_usec = 0};

        int ready = select(sock + 1, &fds, NULL, NULL, &tv);
        if (ready < 0) {
            if (errno == EINTR) continue;   /* interrupted by signal */
            perror("select");
            break;
        } else if (ready == 0) {
            /* timeout – nothing received, just check if we need to display */
        } else {
            /* -------------------------------------------------------- */
            /* Receive a packet                                         */
            addrlen = sizeof(sender_addr);
            nbytes = recvfrom(sock,
                              buffer,
                              sizeof(buffer) - 1,
                              0,
                              (struct sockaddr *)&sender_addr,
                              &addrlen);
            if (nbytes < 0) {
                perror("recvfrom");
                continue;
            }

            buffer[nbytes] = '\0';   /* ensure NUL‑termination */

            /* -------------------------------------------------------- */
            /* Compare payload with the argument string               */
            if ((size_t)nbytes == msg_len && memcmp(buffer, msg, msg_len) == 0) {
                /* Insert the sender into the shared table if not already there */
                bool already = false;
                for (size_t i = 0; i < shm->count; ++i) {
                    if (shm->peers[i].used &&
                        shm->peers[i].addr.sin_addr.s_addr == sender_addr.sin_addr.s_addr &&
                        shm->peers[i].addr.sin_port == sender_addr.sin_port) {
                        already = true;
                        break;
                    }
                }

                if (!already && shm->count < MAX_PEERS) {
                    shm->peers[shm->count].addr = sender_addr;
                    shm->peers[shm->count].used = true;
                    ++shm->count;
                }
            }
        }

        /* -------------------------------------------------------- */
        /* Periodic display (every DISPLAY_INTERVAL seconds)        */
        time_t now = time(NULL);
        if (now - last_display >= DISPLAY_INTERVAL) {
            printf("\n--- Discovered peers (as of %s) ---\n",
                   ctime(&now));   /* includes newline */
            if (shm->count == 0) {
                puts("No peers yet.");
            } else {
                for (size_t i = 0; i < shm->count; ++i) {
                    if (shm->peers[i].used) {
                        printf("%zu) ", i + 1);
                        print_sockaddr(&shm->peers[i].addr);
                        putchar('\n');
                    }
                }
            }
            putchar('\n');
            fflush(stdout);
            last_display = now;
        }
    }

    close(sock);
}

/* ------------------------------------------------------------------ */
/* Main entry point                                                    */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s \"string to broadcast\"\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    const char *msg = argv[1];

    /* ------------------------------------------------------------ */
    /* 1️⃣ Create a shared memory segment for the peer table       */
    shm = mmap(NULL,
               sizeof(shared_data_t),
               PROT_READ | PROT_WRITE,
               MAP_ANONYMOUS | MAP_SHARED,
               -1,
               0);
    if (shm == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    /* Initialise the structure */
    memset(shm, 0, sizeof(shared_data_t));

    /* ------------------------------------------------------------ */
    /* 2️⃣ Install a handler for SIGINT so that both processes exit
          gracefully when the user presses Ctrl‑C                */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        /* not fatal */
    }

    /* ------------------------------------------------------------ */
    /* 3️⃣ Fork: parent => sender, child => receiver & viewer       */
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        munmap(shm, sizeof(shared_data_t));
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        /* ------------ Child ------------------------------- */
        /* Receiver + viewer */
        receiver_and_viewer(msg);
        /* cleanup */
        munmap(shm, sizeof(shared_data_t));
        exit(EXIT_SUCCESS);
    } else {
        /* ------------ Parent ------------------------------ */
        /* Sender */
        sender(msg);
        /* Wait for child to finish (it will exit when keep_running == 0) */
        int status;
        waitpid(pid, &status, 0);
        /* cleanup */
        munmap(shm, sizeof(shared_data_t));
        exit(EXIT_SUCCESS);
    }
}
