/*
 *  resistor.c
 *  Консольная программа для подбора последовательной комбинации резисторов
 *  из ряда E12 под заданное сопротивление.
 *
 *  Компиляция (MSVC):
 *      cl /O2 resistor.c
 *
 *  Запуск:
 *      resistor.exe
 *
 *  Ввод:  требуемое сопротивление в Омах (может быть дробным).
 *  Вывод: набор резисторов, например 2*5.1Ω + 1*1Ω
 */

#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_RESISTORS  512          // Максимальное количество разных резисторов в наборе
#define TOLERANCE      0.001        // Доля (0.1 %) – когда считаем, что «достигли» цели

/* Базовые множители ряда E12 */
static const double e12_base[] = {
    10.0, 12.0, 15.0, 18.0,
    22.0, 27.0, 33.0, 39.0,
    47.0, 56.0, 68.0, 82.0
};
#define E12_COUNT (sizeof(e12_base) / sizeof(e12_base[0]))

/* Структура для хранения найденных резисторов */
typedef struct {
    double value;       // номинал (Ом)
    int    count;       // сколько штук
} ResistorItem;

/* -------------------------------------------------------------
   Формируем список всех резисторов из ряда E12,
   покрывающий диапазон от min_ohm до max_ohm.
   ------------------------------------------------------------- */
static int build_resistor_list(double min_ohm, double max_ohm,
                               double *list, int max_items)
{
    int idx = 0;
    /* мощность 10^exp, где exp от -2 (0.1 Ω) до +6 (10 MΩ) */
    for (int exp = -2; exp <= 6; ++exp) {
        double factor = pow(10.0, exp);
        for (int i = 0; i < E12_COUNT; ++i) {
            double r = e12_base[i] * factor;
            if (r < min_ohm) continue;
            if (r > max_ohm) continue;
            if (idx < max_items) {
                list[idx++] = r;
            } else {
                // переполнение (не должно случиться при разумных параметрах)
                return idx;
            }
        }
    }
    /* Сортируем по убыванию – простым пузырём (массив небольшого размера) */
    for (int i = 0; i < idx - 1; ++i) {
        for (int j = i + 1; j < idx; ++j) {
            if (list[i] < list[j]) {
                double tmp = list[i];
                list[i] = list[j];
                list[j] = tmp;
            }
        }
    }
    return idx;   // количество элементов в массиве list
}

/* -------------------------------------------------------------
   Жадный подбор резисторов.
   На вход: требуемое сопротивление target,
            массив всех доступных резисторов (уже отсортирован по убыванию),
            их количество n_res.
   На выход: массив result (заполняется) и его фактическое число элементов.
   ------------------------------------------------------------- */
static int greedy_pick(double target, const double *avail, int n_res,
                       ResistorItem *result, int max_result)
{
    double rest = target;
    int res_cnt = 0;

    while (rest > target * TOLERANCE && res_cnt < max_result) {
        /* Ищем наибольший резистор <= rest */
        double chosen = 0.0;
        for (int i = 0; i < n_res; ++i) {
            if (avail[i] <= rest + 1e-12) {   // небольшая поправка от ошибок floating‑point
                chosen = avail[i];
                break;
            }
        }
        /* Если ничего не подошло (rest меньше самого маленького резистора) –
           берём самый маленький, чтобы не зацикливаться. */
        if (chosen == 0.0) {
            chosen = avail[n_res - 1];
        }

        /* Добавляем выбранный резистор в result */
        int found = 0;
        for (int i = 0; i < res_cnt; ++i) {
            if (fabs(result[i].value - chosen) < 1e-12) {
                ++result[i].count;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (res_cnt >= max_result) break; // защита от переполнения
            result[res_cnt].value = chosen;
            result[res_cnt].count = 1;
            ++res_cnt;
        }

        rest -= chosen;
    }

    return res_cnt;   // реальное количество различных резисторов в наборе
}

/* -------------------------------------------------------------
   Вывод результата в удобочитаемом виде.
   ------------------------------------------------------------- */
static void print_result(const ResistorItem *items, int n)
{
    for (int i = 0; i < n; ++i) {
        if (i > 0) printf(" + ");
        if (items[i].count > 1) {
            printf("%d*%.3gΩ", items[i].count, items[i].value);
        } else {
            printf("%.3gΩ", items[i].value);
        }
    }
    printf("\n");
}

/* -------------------------------------------------------------
   Главная функция
   ------------------------------------------------------------- */
int main(void)
{
    double target;
    printf("Введите требуемый номинал резистора (Ом): ");
    if (scanf("%lf", &target) != 1) {
        fprintf(stderr, "Ошибка ввода.\n");
        return 1;
    }

    if (target <= 0.0) {
        fprintf(stderr, "Номинал должен быть > 0.\n");
        return 1;
    }

    /* Диапазон, в котором будем искать резисторы.
       Выбираем достаточно широкий: от 0.1 Ω до 10 MΩ. */
    const double MIN_OHM = 0.1;
    const double MAX_OHM = 10e6;

    /* Список всех доступных резисторов */
    double all_resistors[256];
    int n_all = build_resistor_list(MIN_OHM, MAX_OHM,
                                    all_resistors, 256);

    if (n_all == 0) {
        fprintf(stderr, "Не удалось сформировать список резисторов.\n");
        return 1;
    }

    /* Массив для результата */
    ResistorItem result[MAX_RESISTORS];
    int n_result = greedy_pick(target, all_resistors, n_all,
                               result, MAX_RESISTORS);

    /* Вычислим фактическую сумму, чтобы показать погрешность */
    double sum = 0.0;
    for (int i = 0; i < n_result; ++i) {
        sum += result[i].value * result[i].count;
    }

    printf("\nНайденная комбинация:\n");
    print_result(result, n_result);
    printf("Сумма = %.6g Ω (отклонение = %.2f%%)\n",
           sum, 100.0 * (sum - target) / target);

    return 0;
}
```

### Как работает программа

1. **Ввод**  
   Пользователь вводит требуемое сопротивление, например `10.2`.

2. **Формирование списка стандартных резисторов**  
   С помощью функции `build_resistor_list` генерируются все значения из ряда E12 от `0.1 Ω` до `10 MΩ`. Их количество небольшое (≈ 150), поэтому сортировка «пузырьком» полностью приемлема.

