/*  utf8_substr.c  */
#include <stdio.h>
#include <stddef.h>

/* -------------------------------------------------------------
   Возвращает указатель на первый байт n‑го Unicode‑символа.
   Если строка короче n символов – возвращает указатель на '\0'.
   ------------------------------------------------------------- */
static const char *utf8_nth_char(const char *s, int n)
{
    const unsigned char *p = (const unsigned char *)s;

    while (n > 0 && *p) {
        /* 1‑байтовый ASCII символ */
        if ((*p & 0x80) == 0) {
            p += 1;
        }
        /* 2‑байтовый код */
        else if ((*p & 0xE0) == 0xC0) {
            p += 2;
        }
        /* 3‑байтовый код */
        else if ((*p & 0xF0) == 0xE0) {
            p += 3;
        }
        /* 4‑байтовый код (самый высокий Unicode) */
        else if ((*p & 0xF8) == 0xF0) {
            p += 4;
        }
        else {
            /* Некорректный UTF‑8, просто пропустим один байт */
            p += 1;
        }
        --n;
    }
    return (const char *)p;   /* может указывать на '\0' */
}

/* -------------------------------------------------------------
   Печать подстроки s[begin … end-1] (символы, а не байты).
   begin и end – индексы символов, 0‑based.
   ------------------------------------------------------------- */
static void utf8_print_substr(const char *s, int begin, int end)
{
    const char *p_begin = utf8_nth_char(s, begin);
    const char *p_end   = utf8_nth_char(s, end);   /* сразу после последнего */

    /* Длина в байтах */
    size_t len = (size_t)(p_end - p_begin);

    /* printf("%.*s") печатает ровно len байт */
    printf("%.*s\n", (int)len, p_begin);
}

/* ------------------------------------------------------------- */
int main(void)
{
    /* Пример строки, содержащей русские буквы, эмодзи и латиницу */
    const char *txt = u8"Привет, 🌍! Hello!";  /* u8 гарантирует UTF‑8 */

    /* Вывести 3‑й‑5‑й символ (1‑based в вопросе → 2‑4 в 0‑based) */
    /* 3‑й символ = индекс 2, 5‑й символ = индекс 4, а end‑index = 5 */
    utf8_print_substr(txt, 2, 5);   /* ожидание: "ивет" */

    /* Другой пример: эмодзи – он состоит из 4 байт, но считается 1‑м символом */
    const char *emoji = u8"ABC🌟DEF";
    utf8_print_substr(emoji, 3, 5); /* 4‑й‑5‑й символы → "🌟D" (3‑й‑5‑й inclusive) */

    return 0;
}
