    const char *utf8 = u8"Привет, мир!";

    /* Сначала определим требуемую длину в wchar_t */
    size_t wlen = mbstowcs(NULL, utf8, 0);
    wchar_t *wstr = malloc((wlen + 1) * sizeof(wchar_t));
    mbstowcs(wstr, utf8, wlen + 1);        // теперь строка в wchar_t

    /* Вывод 3‑го‑5‑го символа (1‑based → индексы 2‑4) */
    wprintf(L"%.*ls\n", (int)(5 - 3 + 1), wstr + 2); // 3‑й‑5‑й inclusive

    free(wstr);
    return 0;
