```c
/***********************************************************************
 *  Binary search on a list of students (sorted by student number)
 *
 *  1) The file "student.txt" must contain 10 lines, each line:
 *        <student‑number> <name> <grade>
 *     (the lines have to be sorted by the student number)
 *
 *  2) The program reads the file into an array of structures,
 *     asks the user for a student number and prints the matching record.
 *
 *  Compile:  gcc -Wall -Wextra -std=c99 -o stud_search stud_search.c
 ***********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STUDENTS 10          /* we know the file has exactly 10 rows */
#define NAME_LEN     10          /* as used in the original struct */

/*---------------------------------------------------------------*/
/*  Structure that holds a single student's information          */
struct studinfo {
    int  stnr;               /* student number (key for binary search) */
    char name[NAME_LEN];     /* name – up to 9 chars + terminating '\0' */
    int  grade;              /* numeric grade */
};

/*---------------------------------------------------------------*/
/*  Binary‑search routine.
 *  Parameters:
 *        arr   – array of struct studinfo (sorted by stnr)
 *        n     – number of valid elements in arr
 *        key   – student number we are looking for
 *        pos   – output parameter, receives the index if found
 *  Return value:
 *        1  → record found, *pos contains the array index
 *        0  → record not found
 */
int binary_search(const struct studinfo arr[], int n, int key, int *pos)
{
    int low  = 0;
    int high = n - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;          /* avoid overflow */

        if (arr[mid].stnr == key) {               /* found! */
            *pos = mid;
            return 1;
        }
        else if (key < arr[mid].stnr) {           /* search left half */
            high = mid - 1;
        }
        else {                                    /* search right half */
            low = mid + 1;
        }
    }
    return 0;    /* not found */
}

/*---------------------------------------------------------------*/
int main(void)
{
    struct studinfo s[MAX_STUDENTS];
    FILE *stud_file;
    int cnt = 0;                /* how many records were actually read */

    /* ---------- open the data file ----------------------------------- */
    stud_file = fopen("C:\\cmpe231\\2009Spring\\student.txt", "r");
    if (!stud_file) {
        perror("Cannot open student.txt");
        return EXIT_FAILURE;
    }

    /* ---------- read the file (one record per line) ----------------- */
    while (cnt < MAX_STUDENTS &&
           fscanf(stud_file, "%d %9s %d",
                  &s[cnt].stnr, s[cnt].name, &s[cnt].grade) == 3) {
        cnt++;
    }

    fclose(stud_file);

    if (cnt != MAX_STUDENTS) {
        fprintf(stderr,
                "Warning: expected %d records, but read only %d.\n",
                MAX_STUDENTS, cnt);
    }

    /* ---------- ask user for the student number -------------------- */
    int key;
    printf("Enter student number to search: ");
    if (scanf("%d", &key) != 1) {
        fprintf(stderr, "Invalid input.\n");
        return EXIT_FAILURE;
    }

    /* ---------- binary search --------------------------------------- */
    int index;
    if (binary_search(s, cnt, key, &index)) {
        printf("\nRecord found at position %d (array index).\n", index);
        printf("Student number : %d\n", s[index].stnr);
        printf("Name           : %s\n", s[index].name);
        printf("Grade          : %d\n", s[index].grade);
    } else {
        printf("\nStudent number %d not found in the file.\n", key);
    }

    return EXIT_SUCCESS;
}
