// MessageType.java
public enum MessageType {
    // 双方都能发送的普通业务
    TEXT,       // 文字消息
    IMAGE,      // 图片，content 为 Base64 编码的 byte[]
    FILE,       // 任意文件，content 同上

    // 系统内部控制消息
    HELLO,      // 客户端首次连接，携带 clientId
    WELCOME,    // 服务器响应 HELLO，带 status=OK|BUSY
    BUSY,       // 服务器主动告知“客服忙”
    CLOSE,      // 关闭会话
    HEARTBEAT   // 心跳包（用于检测连接是否存活）
}
