    private String sender;             // "USER" / "STAFF"
    private String content;            // 文本或 Base64 编码的二进制数据
    private String fileName;           // 当 type 为 IMAGE / FILE 时有意义
    private long timestamp;            // epoch ms

    // ---------- 业务控制字段（可选） ----------
    private String status;             // 当 type=HELLO/WELCOME 时使用，如 OK、BUSY
    // ---------- 构造、getter / setter ----------
}
