public class ServerUI extends JFrame {
    private final DefaultListModel<String> waitingListModel = new DefaultListModel<>();
    private final JList<String> waitingList = new JList<>(waitingListModel);
    private final Map<String, ChatSession> sessions = new ConcurrentHashMap<>();

    public ServerUI() {
        setTitle("电商客服系统 - 服务器");
        setSize(400, 600);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
    }

    private void initUI() {
        JPanel panel = new JPanel(new BorderLayout(5,5));
        panel.add(new JLabel("待接入用户（双击接受/右键拒绝）"), BorderLayout.NORTH);
        panel.add(new JScrollPane(waitingList), BorderLayout.CENTER);
        setContentPane(panel);

        // 双击接受
        waitingList.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2) {
                    int idx = waitingList.locationToIndex(e.getPoint());
                    if (idx >= 0) {
                        String clientId = waitingListModel.getElementAt(idx);
                        acceptClient(clientId);
                    }
                }
            }
        });
        // 右键弹出菜单（拒绝）
        JPopupMenu menu = new JPopupMenu();
        JMenuItem rejectItem = new JMenuItem("拒绝");
        rejectItem.addActionListener(e -> {
            int idx = waitingList.getSelectedIndex();
            if (idx >= 0) rejectClient(waitingListModel.getElementAt(idx));
        });
        menu.add(rejectItem);
        waitingList.setComponentPopupMenu(menu);
    }

    /** 在 UI 线程中调用 */
    public void addWaitingClient(String clientId, ClientHandler handler) {
        SwingUtilities.invokeLater(() -> {
            if (!waitingListModel.contains(clientId)) {
                waitingListModel.addElement(clientId);
                handler.setPending(true); // 标记为“待处理”
            }
        });
    }

    private void acceptClient(String clientId) {
        // 从列表中删除
        waitingListModel.removeElement(clientId);
        // 创建会话窗口
        ChatSession session = new ChatSession(clientId);
        sessions.put(clientId, session);
        session.show();
        // 通知对应的 ClientHandler 继续会话
        ClientHandler handler = ClientHandler.getHandlerById(clientId);
        if (handler != null) handler.setAccepted(true);
    }

    private void rejectClient(String clientId) {
        waitingListModel.removeElement(clientId);
        ClientHandler handler = ClientHandler.getHandlerById(clientId);
        if (handler != null) handler.sendBusyAndClose();
    }

    /** 方便外部线程投递 UI 更新任务 */
    public static void invokeOnEDT(Runnable r) {
        SwingUtilities.invokeLater(r);
    }
}
```

> **关键点**  
> - **待接入用户列表** (`JList`) 实时展示新来的连接。  
> - 双击或右键菜单分别 **接受**、**拒绝**。  
> - `ChatSession` 用来管理单个用户的聊天窗口、日志文件等。  
> - `ClientHandler` 持有对 `ServerUI` 的引用（通过 `ServerUI.invokeOnEDT`）来把 UI 相关的操作委托到 EDT。  

### 3.3 ClientHandler（单个用户的网络会话）

