## 4. 客户端实现

客户端实现和服务器的逻辑相对更简洁：只需要 **主动发起连接 → 等待服务器响应 → 正式聊天**。

### 4.1 ClientMain（入口）

```java
public class ClientMain {
    public static final String SERVER_HOST = "127.0.0.1";
    public static final int SERVER_PORT = 8888;
    // 客户端唯一标识（可以是登录的手机号、订单号、UUID 等），这里用 UUID
    private static final String CLIENT_ID = UUID.randomUUID().toString().substring(0, 8);

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ClientUI(CLIENT_ID).setVisible(true));
    }
}
```

### 4.2 ClientUI（聊天窗口）

```java
public class ClientUI extends JFrame {
    private final String clientId;
    private Socket socket;
    private BufferedReader in;
    private BufferedWriter out;
    private final JTextArea chatArea = new JTextArea(20, 50);
    private final JTextField inputField = new JTextField(35);
    private final JButton sendBtn = new JButton("发送");
    private final JButton sendImgBtn = new JButton("发送图片/文件");
    private final File logFile;

    public ClientUI(String clientId) {
        this.clientId = clientId;
        this.logFile = new File("client_logs/" + clientId + ".log");
        initUI();
        new Thread(this::connectAndListen, "Client-Listener").start();
    }

    private void initUI() {
        setTitle("用户端 - " + clientId);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setSize(600, 500);
        setLocationRelativeTo(null);
        chatArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(chatArea);
        JPanel bottom = new JPanel(new FlowLayout(FlowLayout.LEFT));
        bottom.add(inputField);
        bottom.add(sendBtn);
        bottom.add(sendImgBtn);
        add(scroll, BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);
        // 发送文字
        sendBtn.addActionListener(e -> sendText());
        // 发送文件/图片
        sendImgBtn.addActionListener(e -> sendFileOrImage());
    }

    /** 连接服务器并启动监听线程 */
    private void connectAndListen() {
        try {
            socket = new Socket(SERVER_HOST, SERVER_PORT);
            in = new BufferedReader(new InputStreamReader(socket.getInputStream(),
                    StandardCharsets.UTF_8));
            out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(),
                    StandardCharsets.UTF_8));

            // ----- 1️⃣ 发送 HELLO -----
            Message hello = new Message();
            hello.setType(MessageType.HELLO);
            hello.setSender(clientId);
            hello.setTimestamp(System.currentTimeMillis());
            sendMessage(hello);

            // ----- 2️⃣ 等待服务端响应（WELCOME / BUSY） -----
            String line = in.readLine(); // 可能收到 BUSY、WELCOME 等
            Message resp = new Gson().fromJson(line, Message.class);
            if (resp.getType() == MessageType.BUSY) {
                showSystemInfo("客服忙，请稍后再试！");
                closeSocket();
                return;
            }
            if (resp.getType() == MessageType.WELCOME && "OK".equals(resp.getStatus())) {
                showSystemInfo("已进入客服聊天，您可以开始对话。");
                loadHistory(); // 加载本地历史（如果有）
                // ------------ 进入正式聊天循环 ------------
                while ((line = in.readLine()) != null) {
                    Message msg = new Gson().fromJson(line, Message.class);
                    if (msg.getType() == MessageType.CLOSE) {
                        showSystemInfo("客服已结束会话。");
                        break;
                    }
                    receiveFromServer(msg);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
            showSystemInfo("网络异常：" + e.getMessage());
        } finally {
            closeSocket();
        }
    }

    /** 发送文字 */
    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        Message msg = new Message();
        msg.setType(MessageType.TEXT);
        msg.setSender("USER");
        msg.setContent(txt);
        msg.setTimestamp(System.currentTimeMillis());
        sendMessage(msg);
        appendToChatArea(msg);
        inputField.setText("");
    }

    /** 发送文件或图片 */
    private void sendFileOrImage() {
        JFileChooser fc = new JFileChooser();
        int rc = fc.showOpenDialog(this);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File f = fc.getSelectedFile();
        try {
            byte[] bytes = Files.readAllBytes(f.toPath());
            String base64 = Base64.getEncoder().encodeToString(bytes);
            Message msg = new Message();
            msg.setSender("USER");
            msg.setTimestamp(System.currentTimeMillis());
            msg.setFileName(f.getName());
            msg.setContent(base64);
            msg.setType(isImageFile(f) ? MessageType.IMAGE : MessageType.FILE);
            sendMessage(msg);
            appendToChatArea(msg);
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this,
                    "读取文件出错：" + ex.getMessage(),
                    "错误", JOptionPane.ERROR_MESSAGE);
        }
    }

    /** 统一的发送方法（线程安全） */
    private synchronized void sendMessage(Message msg) {
        try {
            String json = new Gson().toJson(msg);
            out.write(json);
            out.write("\n");
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
            showSystemInfo("发送失败：" + e.getMessage());
        }
    }

    /** 处理服务器返回的业务消息 */
    private void receiveFromServer(Message msg) {
        // 写日志
        writeLog(msg);
        // UI 展示
        SwingUtilities.invokeLater(() -> appendToChatArea(msg));
    }

    /** 写本地日志（追加） */
    private void writeLog(Message msg) {
        try (FileWriter fw = new FileWriter(logFile, true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            bw.write(new Gson().toJson(msg));
            bw.newLine();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 加载历史（启动后调用） */
    private void loadHistory() {
        if (!logFile.exists()) return;
        try (BufferedReader br = new BufferedReader(new FileReader(logFile))) {
            String line;
            while ((line = br.readLine()) != null) {
                Message msg = new Gson().fromJson(line, Message.class);
                appendToChatArea(msg);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** UI: 把消息渲染到 chatArea */
    private void appendToChatArea(Message msg) {
        String time = new SimpleDateFormat("HH:mm:ss")
                .format(new Date(msg.getTimestamp()));
        String prefix = "[" + time + "] " + (msg.getSender().equals("USER") ? "我" : "客服") + ": ";
        switch (msg.getType()) {
            case TEXT:
                chatArea.append(prefix + msg.getContent() + "\n");
                break;
            case IMAGE:
                byte[] img = Base64.getDecoder().decode(msg.getContent());
                ImageIcon icon = new ImageIcon(img);
                Image scaled = icon.getImage().getScaledInstance(120, -1, Image.SCALE_SMOOTH);
                chatArea.append(prefix);
                chatArea.insertIcon(new ImageIcon(scaled));
                chatArea.append("\n");
                break;
            case FILE:
                chatArea.append(prefix + "[文件] " + msg.getFileName() + "\n");
                // 双击保存文件
                chatArea.addMouseListener(new MouseAdapter() {
                    @Override
                    public void mouseClicked(MouseEvent e) {
                        if (e.getClickCount() == 2) {
                            JFileChooser chooser = new JFileChooser();
                            chooser.setSelectedFile(new File(msg.getFileName()));
                            int rc = chooser.showSaveDialog(ClientUI.this);
                            if (rc == JFileChooser.APPROVE_OPTION) {
                                try {
                                    Files.write(chooser.getSelectedFile().toPath(),
                                            Base64.getDecoder().decode(msg.getContent()));
                                    JOptionPane.showMessageDialog(ClientUI.this,
                                            "文件已保存！", "提示", JOptionPane.INFORMATION_MESSAGE);
                                } catch (IOException ex) {
                                    JOptionPane.showMessageDialog(ClientUI.this,
                                            "保存失败：" + ex.getMessage(),
                                            "错误", JOptionPane.ERROR_MESSAGE);
                                }
                            }
                        }
                    }
                });
                break;
            case SYSTEM:
                // 一般在响应阶段使用，直接弹出提示框
                showSystemInfo(msg.getStatus());
                break;
            default:
                // ignore
        }
        // 自动滚动
        chatArea.setCaretPosition(chatArea.getDocument().getLength());
    }

    private void showSystemInfo(String txt) {
        SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this,
                txt, "系统提示", JOptionPane.INFORMATION_MESSAGE));
    }

    private boolean isImageFile(File f) {
        String n = f.getName().toLowerCase();
        return n.endsWith(".png") || n.endsWith(".jpg") || n.endsWith(".jpeg")
                || n.endsWith(".gif") || n.endsWith(".bmp");
    }

    private void closeSocket() {
        try {
            if (socket != null && !socket.isClosed()) socket.close();
        } catch (IOException ignored) {}
    }
}
```

> **注意**  
> 1. **阻塞读取**：`while ((line = in.readLine()) != null)` 在新线程里运行，不会卡死 UI。  
> 2. **超时与重连**：如果服务器返回 `BUSY`，客户端弹出提示并自行关闭 socket，用户可以稍后重新打开客户端重新尝试。  
> 3. **本地日志**：客户端同样把每条收到的消息写入 `client_logs/<clientId>.log`，实现“再次登录后可以看到历史”。  

