        return a + b;
    }

    public static double soustraction(double a, double b) {
        return a - b;
    }

    public static double multiplication(double a, double b) {
        return a * b;
    }

    public static double division(double a, double b) throws ArithmeticException {
        if (b == 0) {
            throw new ArithmeticException("Division par zéro");
        }
        return a / b;
    }

    /**
     * Évalue une expression au format "operand1 operator operand2".
     * Retourne le résultat sous forme de chaîne (pour être envoyé au client).
     *
     * @param expression la chaîne reçue du client
     * @return le résultat ou un message d’erreur
     */
    public static String evaluer(String expression) {
        if (expression == null) {
            return "Erreur : expression nulle";
        }

        // On enlève les espaces inutiles puis on découpe
        expression = expression.trim();
        if (expression.isEmpty()) {
            return "Erreur : expression vide";
        }

        StringTokenizer st = new StringTokenizer(expression);
        if (st.countTokens() != 3) {
            return "Erreur : format attendu \"operand1 opérateur operand2\"";
        }

        try {
            double op1 = Double.parseDouble(st.nextToken());
            String operateur = st.nextToken();
            double op2 = Double.parseDouble(st.nextToken());

            double resultat;
            switch (operateur) {
                case "+":
                    resultat = addition(op1, op2);
                    break;
                case "-":
                    resultat = soustraction(op1, op2);
                    break;
                case "*":
                case "x":
                case "X":
                    resultat = multiplication(op1, op2);
                    break;
                case "/":
                    resultat = division(op1, op2);
                    break;
                default:
                    return "Erreur : opérateur inconnu \"" + operateur + "\"";
            }
            return Double.toString(resultat);
        } catch (NumberFormatException nfe) {
            return "Erreur : nombres invalides";
        } catch (ArithmeticException ae) {
            return "Erreur : " + ae.getMessage();
        }
    }

    // Méthode main de test rapide (optionnelle)
    public static void main(String[] args) {
        System.out.println(evaluer("12 + 5"));
        System.out.println(evaluer("7.3 * 2"));
        System.out.println(evaluer("10 / 0"));
        System.out.println(evaluer("15 - 4"));
    }
}
```

