## 2. `CalculatriceServer.java`

```java
import java.io.*;
import java.net.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Serveur TCP qui écoute sur un port (par défaut 5000) et attend des
 * requêtes sous forme d'expression texte.
 *
 * Pour chaque connexion client, il crée un thread (via un pool d’exécution)
 * qui lit les lignes envoyées, les transmet à Calculatrice.evaluer()
 * et renvoie le résultat.
 *
 * Le protocole est très simple :
 * - le client envoie une ligne texte contenant l’expression à calculer,
 *   terminée par \n (ou \r\n).
 * - le serveur répond avec le résultat (ou un message d’erreur) suivi de \n.
 * - Quand le client ferme sa connexion, le serveur libère le thread.
 */
public class CalculatriceServer {

    private static final int PORT = 5000;                // Port d’écoute
    private static final int MAX_THREADS = 50;           // Taille du pool de threads

    public static void main(String[] args) {
        System.out.println("=== Lancement du serveur de calculatrice ===");
        System.out.println("Port d'écoute : " + PORT);

        ExecutorService threadPool = Executors.newFixedThreadPool(MAX_THREADS);

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            while (true) {
                // Attente d'un nouveau client
                Socket clientSocket = serverSocket.accept();
                System.out.println("Nouvelle connexion depuis "
                        + clientSocket.getInetAddress() + ":" + clientSocket.getPort());

                // Traitement de la connexion dans un thread séparé
                threadPool.execute(new ClientHandler(clientSocket));
            }
        } catch (IOException ioe) {
            System.err.println("Erreur serveur : " + ioe.getMessage());
        } finally {
            threadPool.shutdown();
        }
    }

    /** Runnable qui gère la conversation avec un seul client */
    private static class ClientHandler implements Runnable {
        private final Socket socket;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            // try‑with‑resources pour fermer automatiquement les flux et la socket
            try (BufferedReader in = new BufferedReader(
                         new InputStreamReader(socket.getInputStream()));
                 PrintWriter out = new PrintWriter(
                         new BufferedWriter(
                                 new OutputStreamWriter(socket.getOutputStream())), true))
            {
                String requete;
                while ((requete = in.readLine()) != null) {
                    System.out.println("Requête de " + socket.getRemoteSocketAddress()
                            + " : \"" + requete + "\"");

                    // On traite la requête grâce à la classe Calculatrice
                    String reponse = Calculatrice.evaluer(requete);
                    out.println(reponse);               // on renvoie le résultat
                }
            } catch (IOException ioe) {
                System.err.println("Erreur I/O avec le client "
                        + socket.getRemoteSocketAddress() + " : " + ioe.getMessage());
            } finally {
                try {
                    socket.close();
                } catch (IOException ignored) {}
                System.out.println("Connexion terminée avec "
                        + socket.getRemoteSocketAddress());
            }
        }
    }
}
```

