### 4.7 业务层

#### 4.7.1 AuthService（登录、注册、刷新）

```java
// AuthService.java
package com.example.vehiclereg.service;

import com.example.vehiclereg.dto.*;
import com.example.vehiclereg.entity.*;
import com.example.vehiclereg.repository.*;
import com.example.vehiclereg.util.JwtUtil;
import lombok.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.crypto.password.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service
@RequiredArgsConstructor
public class AuthService {

    private final AuthenticationManager authenticationManager;
    private final JwtUtil jwtUtil;
    private final UserRepository userRepo;
    private final RoleRepository roleRepo;
    private final PasswordEncoder passwordEncoder;

    @Transactional
    public LoginResponse login(LoginRequest request) {
        Authentication authentication = authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(request.username(), request.password()));
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();

        // 读取角色字符串列表
        Collection<String> roles = userDetails.getAuthorities().stream()
                .map(GrantedAuthority::getAuthority)
                .map(r -> r.replace("ROLE_", ""))
                .toList();

        String accessToken = jwtUtil.generateAccessToken(userDetails.getUsername(), roles);
        String refreshToken = jwtUtil.generateRefreshToken(userDetails.getUsername());

        return new LoginResponse(accessToken, refreshToken, "Bearer");
    }

    @Transactional
    public void register(RegisterRequest request, String creatorUsername) {
        // 只有管理员才能创建 COMPANY/ADMIN，普通注册只能是 USER
        if (!request.role().equalsIgnoreCase("USER")) {
            // 检查 creator 是否为 ADMIN
            User creator = userRepo.findByUsername(creatorUsername)
                    .orElseThrow(() -> new RuntimeException("Creator not found"));
            boolean isAdmin = creator.getRoles().stream()
                    .anyMatch(r -> r.getName().equalsIgnoreCase("ADMIN"));
            if (!isAdmin) {
                throw new RuntimeException("Only ADMIN can create non‑USER accounts");
            }
        }

        if (userRepo.existsByUsername(request.username())) {
            throw new RuntimeException("Username already exists");
        }
        if (userRepo.existsByEmail(request.email())) {
            throw new RuntimeException("Email already registered");
        }

        User user = new User();
        user.setUsername(request.username());
        user.setPassword(passwordEncoder.encode(request.password()));
        user.setEmail(request.email());
        user.setEnabled(true);

        Role role = roleRepo.findByName(request.role().toUpperCase())
                .orElseThrow(() -> new RuntimeException("Role not found: " + request.role()));
        user.setRoles(Set.of(role));

        userRepo.save(user);
    }

    public LoginResponse refresh(String refreshToken) {
        if (!jwtUtil.validateToken(refreshToken)) {
            throw new RuntimeException("Invalid refresh token");
        }
        String username = jwtUtil.getUsernameFromToken(refreshToken);
        User user = userRepo.findByUsername(username)
                .orElseThrow(() -> new RuntimeException("User not found"));

        List<String> roleNames = user.getRoles().stream()
                .map(Role::getName).toList();

        String newAccess = jwtUtil.generateAccessToken(username, roleNames);
        String newRefresh = jwtUtil.generateRefreshToken(username);
        return new LoginResponse(newAccess, newRefresh, "Bearer");
    }
}
```

#### 4.7.2 VehicleService

```java
// VehicleService.java
package com.example.vehiclereg.service;

import com.example.vehiclereg.dto.VehicleDTO;
import com.example.vehiclereg.entity.*;
import com.example.vehiclereg.repository.*;
import lombok.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.stream.*;

@Service
@RequiredArgsConstructor
public class VehicleService {

    private final VehicleRepository vehicleRepo;
    private final UserRepository userRepo;

    @Transactional(readOnly = true)
    public List<VehicleDTO> listMyVehicles(String username) {
        User user = userRepo.findByUsername(username)
                .orElseThrow(() -> new RuntimeException("User not found"));
        return vehicleRepo.findAllByOwner(user).stream()
                .map(this::toDTO)
                .toList();
    }

    @Transactional
    public VehicleDTO addVehicle(String username, VehicleDTO dto) {
        User user = userRepo.findByUsername(username)
                .orElseThrow(() -> new RuntimeException("User not found"));

        Vehicle vehicle = new Vehicle();
        vehicle.setPlateNumber(dto.plateNumber());
        vehicle.setBrand(dto.brand());
        vehicle.setModel(dto.model());
        vehicle.setYear(dto.year());
        vehicle.setOwner(user);
        Vehicle saved = vehicleRepo.save(vehicle);
        return toDTO(saved);
    }

    @Transactional
    public VehicleDTO updateVehicle(String username, VehicleDTO dto) {
        if (dto.id() == null) {
            throw new RuntimeException("Vehicle id required for update");
        }
        Vehicle vehicle = vehicleRepo.findById(dto.id())
                .orElseThrow(() -> new RuntimeException("Vehicle not found"));
        // 权限校验：只能修改自己的车辆，或者 ADMIN 可修改全部
        if (!vehicle.getOwner().getUsername().equals(username) &&
                !hasRole(username, "ADMIN")) {
            throw new RuntimeException("No permission");
        }

        vehicle.setPlateNumber(dto.plateNumber());
        vehicle.setBrand(dto.brand());
        vehicle.setModel(dto.model());
        vehicle.setYear(dto.year());
        Vehicle saved = vehicleRepo.save(vehicle);
        return toDTO(saved);
    }

    @Transactional
    public void deleteVehicle(String username, Long vehicleId) {
        Vehicle vehicle = vehicleRepo.findById(vehicleId)
                .orElseThrow(() -> new RuntimeException("Vehicle not found"));
        if (!vehicle.getOwner().getUsername().equals(username) &&
                !hasRole(username, "ADMIN")) {
            throw new RuntimeException("No permission");
        }
        vehicleRepo.delete(vehicle);
    }

    // ------- 辅助方法 -------
    private VehicleDTO toDTO(Vehicle v) {
        return new VehicleDTO(v.getId(),
                v.getPlateNumber(),
                v.getBrand(),
                v.getModel(),
                v.getYear());
    }

    private boolean hasRole(String username, String roleName) {
        User user = userRepo.findByUsername(username).orElseThrow();
        return user.getRoles().stream()
                .anyMatch(r -> r.getName().equalsIgnoreCase(roleName));
    }
}
