#### 4.8.1 AuthController

```java
// AuthController.java
package com.example.vehiclereg.controller;

import com.example.vehiclereg.dto.*;
import com.example.vehiclereg.service.AuthService;
import jakarta.validation.Valid;
import lombok.*;
import org.springframework.http.*;
import org.springframework.security.core.annotation.*;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthService authService;

    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(@Valid @RequestBody LoginRequest req) {
        return ResponseEntity.ok(authService.login(req));
    }

    @PostMapping("/refresh")
    public ResponseEntity<LoginResponse> refresh(@RequestParam String refreshToken) {
        return ResponseEntity.ok(authService.refresh(refreshToken));
    }

    @PostMapping("/register")
    public ResponseEntity<Void> register(@Valid @RequestBody RegisterRequest req,
                                         @AuthenticationPrincipal(expression = "username") String creator) {
        // 当 creator 为 null（未登录）时，只允许创建 USER 账户
        if (creator == null && !req.role().equalsIgnoreCase("USER")) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
        }
        authService.register(req, creator);
        return ResponseEntity.status(HttpStatus.CREATED).build();
    }
}
```

> **注意**：若要允许匿名注册 `USER`，前端在调用 `register` 时不带 `Authorization` Header，后端 `creator` 为 `null`，只能创建 `USER`。

