#### 5.2.4 Pinia Store（Auth）

```ts
// src/store/auth.ts
import { defineStore } from 'pinia';
import { login, refresh, register } from '@/api/auth';
import router from '@/router';

interface AuthState {
  accessToken: string | null;
  refreshToken: string | null;
  username: string | null;
  roles: string[];
}
export const useAuthStore = defineStore('auth', {
  state: (): AuthState => ({
    accessToken: localStorage.getItem('accessToken'),
    refreshToken: localStorage.getItem('refreshToken'),
    username: localStorage.getItem('username'),
    roles: JSON.parse(localStorage.getItem('roles') || '[]'),
  }),
  getters: {
    isLogged: (state) => !!state.accessToken,
    isAdmin: (state) => state.roles.includes('ADMIN'),
    isCompany: (state) => state.roles.includes('COMPANY'),
  },
  actions: {
    async login(payload: { username: string; password: string }) {
      const resp = await login(payload);
      this.setTokens(resp);
    },

    async register(payload: { username: string; password: string; email: string; role: string }) {
      await register(payload);
      // 注册后直接登录
      await this.login({ username: payload.username, password: payload.password });
    },

    async refreshToken() {
      if (!this.refreshToken) throw new Error('No refresh token');
      const resp = await refresh(this.refreshToken);
      this.setTokens(resp);
    },

    setTokens(data: { accessToken: string; refreshToken: string; tokenType: string }) {
      this.accessToken = data.accessToken;
      this.refreshToken = data.refreshToken;

      // 解析 JWT payload 获取用户名和角色（不安全的只能用于 UI 显示）
      const payload = JSON.parse(atob(data.accessToken.split('.')[1]));
      this.username = payload.sub;
      this.roles = payload.roles || [];

      // 持久化到 localStorage
      localStorage.setItem('accessToken', this.accessToken);
      localStorage.setItem('refreshToken', this.refreshToken);
      localStorage.setItem('username', this.username!);
      localStorage.setItem('roles', JSON.stringify(this.roles));
    },

    logout() {
      this.accessToken = null;
      this.refreshToken = null;
      this.username = null;
      this.roles = [];
      localStorage.clear();
      router.replace({ name: 'Login' });
    },
  },
});
```

#### 5.2.5 路由守卫

```ts
// src/router/index.ts
import { createRouter, createWebHistory } from 'vue-router';
import { useAuthStore } from '@/store/auth';
import LoginView from '@/views/LoginView.vue';
import RegisterView from '@/views/RegisterView.vue';
import HomeView from '@/views/HomeView.vue';
import VehicleManage from '@/views/VehicleManage.vue';
import AdminDashboard from '@/views/AdminDashboard.vue';

const routes = [
  { path: '/', name: 'Home', component: HomeView, meta: { requiresAuth: true } },
  { path: '/login', name: 'Login', component: LoginView },
  { path: '/register', name: 'Register', component: RegisterView },
  { path: '/vehicles', name: 'VehicleManage', component: VehicleManage, meta: { requiresAuth: true } },
  { path: '/admin', name: 'AdminDashboard', component: AdminDashboard, meta: { requiresAuth: true, roles: ['ADMIN'] } },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach((to, from, next) => {
  const auth = useAuthStore();
  if (to.meta.requiresAuth && !auth.isLogged) {
    return next({ name: 'Login', query: { redirect: to.fullPath } });
  }
  if (to.meta.roles) {
    const allowed = (to.meta.roles as string[]).some((r) => auth.roles.includes(r));
    if (!allowed) {
      return next({ name: 'Home' }); // 或者 403 页面
    }
  }
  next();
});

export default router;
```

