<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { useMessage } from 'element-plus';
import { getMyVehicles, addVehicle, updateVehicle, deleteVehicle } from '@/api/vehicle';
import type { VehicleDTO } from '@/types';

const loading = ref(false);
const vehicles = ref<VehicleDTO[]>([]);
const dialogVisible = ref(false);
const editMode = ref(false);
const form = ref<VehicleDTO>({ id: null, plateNumber: '', brand: '', model: '', year: null });
const formRef = ref();
const message = useMessage();

const fetchVehicles = async () => {
  loading.value = true;
  try {
    vehicles.value = await getMyVehicles();
  } finally {
    loading.value = false;
  }
};

onMounted(fetchVehicles);

const showAdd = () => {
  editMode.value = false;
  form.value = { id: null, plateNumber: '', brand: '', model: '', year: null };
  dialogVisible.value = true;
};

const edit = (row: VehicleDTO) => {
  editMode.value = true;
  form.value = { ...row };
  dialogVisible.value = true;
};

const submit = async () => {
  await (formRef.value as any).validate();
  try {
    if (editMode.value && form.value.id) {
      await updateVehicle(form.value.id, form.value);
      message.success('车辆已更新');
    } else {
      await addVehicle(form.value);
      message.success('车辆已添加');
    }
    dialogVisible.value = false;
    fetchVehicles();
  } catch (e) {
    message.error('操作失败');
  }
};

const remove = async (id: number) => {
  try {
    await deleteVehicle(id);
    message.success('已删除');
