## 4.  “Same thing” in higher‑level languages

If Ram prefers **Python** (with `pyOpenSSL`) or **Java** (with `JSSE`), the same constraints can be expressed in a couple of lines. Below are minimal snippets.

### 4.1. Python (pyOpenSSL)

```python
#!/usr/bin/env python3
from OpenSSL import SSL
import socket

# ----- Common objects -------------------------------------------------
def load_context(is_server=False):
    # SSLv3 only (legacy)
    ctx = SSL.Context(SSL.SSLv3_METHOD)
    ctx.set_cipherlist(b'DHE-RSA-AES256-SHA256' if not is_server
                       else b'ADH-DES-CBC3-SHA512')
    ctx.set_options(SSL.OP_NO_TLSv1 | SSL.OP_NO_TLSv1_1 |
                    SSL.OP_NO_TLSv1_2 | SSL.OP_NO_TLSv1_3)

    # Diffie‑Hellman params (both sides)
    ctx.load_tmp_dh('dh4096.pem')

    if not is_server:
        # client cert + RSA key
        ctx.use_certificate_file('client.crt')
        ctx.use_privatekey_file('client.key')
    else:
        # server is anonymous, no cert
        ctx.set_verify(SSL.VERIFY_NONE, lambda *args: True)

    return ctx

# ----- Client ---------------------------------------------------------
def client():
    ctx = load_context(is_server=False)
    sock = socket.create_connection(('127.0.0.1', 4443))
    conn = SSL.Connection(ctx, sock)
    conn.set_connect_state()
    conn.do_handshake()
    print('Negotiated:', conn.get_cipher_name())
    conn.send(b'Hello from Python client!')
    print('Server says:', conn.recv(4096))
    conn.shutdown()
    conn.close()

# ----- Server ---------------------------------------------------------
def server():
    ctx = load_context(is_server=True)
    listen = socket.socket()
    listen.bind(('', 4443))
    listen.listen(1)
    while True:
        client_sock, _ = listen.accept()
        conn = SSL.Connection(ctx, client_sock)
        conn.set_accept_state()
        conn.do_handshake()
        print('Negotiated:', conn.get_cipher_name())
        data = conn.recv(4096)
        print('Client said:', data)
        conn.send(b'Python server greets you!')
        conn.shutdown()
        conn.close()

if __name__ == '__main__':
    import sys
    if sys.argv[1] == 'server':
        server()
    else:
        client()
```

