import javax.net.ssl.*;
import java.io.*;
import java.security.*;
import java.security.cert.CertificateException;

public class SecureClient {
    public static void main(String[] args) throws Exception {
        // 1️⃣  Load RSA client cert+key (PKCS12 keystore)
        KeyStore ks = KeyStore.getInstance("PKCS12");
        ks.load(new FileInputStream("client.p12"), "password".toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, "password".toCharArray());

        // 2️⃣  No truststore needed for this demo (accept any server cert)
        TrustManager[] trustAll = new TrustManager[] {
            new X509TrustManager() {
                public java.security.cert.X509Certificate[] getAcceptedIssuers() {return null;}
                public void checkClientTrusted(java.security.cert.X509Certificate[] certs, String authType) {}
                public void checkServerTrusted(java.security.cert.X509Certificate[] certs, String authType) {}
            }
        };

        SSLContext ctx = SSLContext.getInstance("SSLv3");
        ctx.init(kmf.getKeyManagers(), trustAll, new SecureRandom());

        // 3️⃣  Force cipher suite
        SSLSocketFactory factory = ctx.getSocketFactory();
        try (SSLSocket socket = (SSLSocket) factory.createSocket("localhost", 4443)) {
            socket.setEnabledCipherSuites(new String[] {"TLS_DHE_RSA_WITH_AES_256_CBC_SHA256"});
            socket.startHandshake();

            System.out.println("Cipher: " + socket.getSession().getCipherSuite());

            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            out.println("Hello from Java client!");
            System.out.println("Server replied: " + in.readLine());
        }
    }
}
