## 7️⃣ JWT Filter – **checks token against DB for multiple‑session support**

```java
package com.example.jwt.security;

import com.example.jwt.model.JwtToken;
import com.example.jwt.repository.JwtTokenRepository;
import jakarta.servlet.*;
import jakarta.servlet.http.*;
import lombok.RequiredArgsConstructor;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

import java.io.IOException;

@Component
@RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtUtils jwtUtils;
    private final CustomUserDetailsService userDetailsService;
    private final JwtTokenRepository tokenRepository;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        String jwt = parseJwt(request);
        if (jwt != null && jwtUtils.validateJwt(jwt)) {

            // 1️⃣ Verify that the token exists in DB (i.e. session still active)
            JwtToken stored = tokenRepository.findByToken(jwt)
                    .filter(t -> t.getExpiresAt().isAfter(java.time.Instant.now())) // not expired
                    .orElse(null);

            if (stored != null) {
                // 2️⃣ Load user details & set authentication
                String username = jwtUtils.getUsernameFromJwt(jwt);
                UserDetails userDetails = userDetailsService.loadUserByUsername(username);

                UsernamePasswordAuthenticationToken auth =
                        new UsernamePasswordAuthenticationToken(
                                userDetails,
                                null,
                                userDetails.getAuthorities());

                auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                SecurityContextHolder.getContext().setAuthentication(auth);
            } else {
                // Token not stored → treat as revoked (e.g. logout from another device)
                logger.info("JWT not found in DB (revoked or expired): {}", jwt);
            }
        }
        filterChain.doFilter(request, response);
    }

    // Extract "Bearer <jwt>" from Authorization header
    private String parseJwt(HttpServletRequest request) {
        String headerAuth = request.getHeader("Authorization");
        if (StringUtils.hasText(headerAuth) && headerAuth.startsWith("Bearer ")) {
            return headerAuth.substring(7);
        }
        return null;
    }
}
