## 10️⃣ Auth Service – **handles multiple concurrent sessions**

```java
package com.example.jwt.service;

import com.example.jwt.model.*;
import com.example.jwt.payload.*;
import com.example.jwt.repository.*;
import com.example.jwt.security.JwtUtils;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import org.springframework.security.authentication.*;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.*;

@Service
@RequiredArgsConstructor
public class AuthService {

    private final AuthenticationManager authenticationManager;
    private final JwtUtils jwtUtils;
    private final UserRepository userRepository;
    private final JwtTokenRepository tokenRepository;
    private final PasswordEncoder passwordEncoder;

    // ── Register (simple demo) ────────────────────────────────────────
    @Transactional
    public void register(String username, String rawPassword) {
        if (userRepository.findByUsername(username).isPresent()) {
            throw new IllegalArgumentException("Username already taken");
        }
        User user = User.builder()
                .username(username)
                .password(passwordEncoder.encode(rawPassword))
                .build();
        userRepository.save(user);
    }

    // ── Login – creates a new JWT **and persists it** (multiple sessions) ─
    @Transactional
    public JwtResponse login(LoginRequest req) {
        Authentication auth = authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword()));

        // 1️⃣ Generate JWTs
        String accessToken = jwtUtils.generateAccessToken(req.getUsername(), Map.of());
        String refreshToken = jwtUtils.generateRefreshToken(req.getUsername());

        // 2️⃣ Persist both tokens as "sessions"
        User user = userRepository.findByUsername(req.getUsername())
                .orElseThrow(() -> new IllegalStateException("User disappeared after auth"));

        // Persist Access token
        JwtToken access = JwtToken.builder()
                .token(accessToken)
                .issuedAt(Instant.ofEpochMilli(jwtUtils.getIssuedAtFromJwt(accessToken).getTime()))
                .expiresAt(Instant.ofEpochMilli(jwtUtils.getExpirationFromJwt(accessToken).getTime()))
                .description(Optional.ofNullable(req.getDescription()).orElse("login"))
                .build();
        user.addToken(access);

        // Persist Refresh token (separate row, could be same table)
        JwtToken refresh = JwtToken.builder()
                .token(refreshToken)
                .issuedAt(Instant.ofEpochMilli(jwtUtils.getIssuedAtFromJwt(refreshToken).getTime()))
                .expiresAt(Instant.ofEpochMilli(jwtUtils.getExpirationFromJwt(refreshToken).getTime()))
                .description(Optional.ofNullable(req.getDescription()).orElse("refresh"))
                .build();
        user.addToken(refresh);

        userRepository.save(user); // cascade persists tokens

        return new JwtResponse(accessToken, refreshToken);
    }

    // ── Refresh – lookup stored refresh token, issue new pair, delete old pair ─
    @Transactional
    public JwtResponse refresh(RefreshRequest req) {
        String oldRefresh = req.getRefreshToken();

        // 1️⃣ Verify token is stored and not expired
        JwtToken storedRefresh = tokenRepository.findByToken(oldRefresh)
                .filter(t -> t.getExpiresAt().isAfter(Instant.now()))
                .orElseThrow(() -> new IllegalArgumentException("Invalid or revoked refresh token"));

        // 2️⃣ Get username from token
        String username = jwtUtils.getUsernameFromJwt(oldRefresh);

        // 3️⃣ Generate fresh tokens
        String newAccess = jwtUtils.generateAccessToken(username, Map.of());
        String newRefresh = jwtUtils.generateRefreshToken(username);

        // 4️⃣ Persist new tokens and delete old ones (cleanup)
        User user = storedRefresh.getUser();

        // remove both old tokens (refresh & (maybe) the associated access)
        // We assume each refresh token is paired with a single access token stored earlier.
        // We'll just delete the refresh token; the old access token will expire naturally.
        tokenRepository.delete(storedRefresh);

        // add new pair
        user.addToken(JwtToken.builder()
                .token(newAccess)
                .issuedAt(Instant.ofEpochMilli(jwtUtils.getIssuedAtFromJwt(newAccess).getTime()))
                .expiresAt(Instant.ofEpochMilli(jwtUtils.getExpirationFromJwt(newAccess).getTime()))
                .description("refreshed-access")
                .build());

        user.addToken(JwtToken.builder()
                .token(newRefresh)
                .issuedAt(Instant.ofEpochMilli(jwtUtils.getIssuedAtFromJwt(newRefresh).getTime()))
                .expiresAt(Instant.ofEpochMilli(jwtUtils.getExpirationFromJwt(newRefresh).getTime()))
                .description("refreshed-refresh")
                .build());

        userRepository.save(user);

        return new JwtResponse(newAccess, newRefresh);
    }

    // ── Logout – invalidate a single token (or all tokens) ─────────────────────
    @Transactional
    public void logout(String token) {
        tokenRepository.deleteByToken(token);
    }

    @Transactional
    public void logoutAll(String username) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new IllegalArgumentException("User not found"));
        user.getTokens().clear(); // cascade delete
        userRepository.save(user);
    }

    // ── Helper – list active sessions (useful for UI) ────────────────────────
    @Transactional(readOnly = true)
    public List<JwtToken> listActiveSessions(String username) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new IllegalArgumentException("User not found"));
        Instant now = Instant.now();
        return user.getTokens().stream()
                .filter(t -> t.getExpiresAt().isAfter(now))
                .toList();
    }
}
```

