## 11️⃣ Auth Controller – expose endpoints

```java
package com.example.jwt.controller;

import com.example.jwt.model.JwtToken;
import com.example.jwt.payload.*;
import com.example.jwt.service.AuthService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthService authService;

    // --------------------------------------------------------------------
    @PostMapping("/register")
    public ResponseEntity<String> register(@Valid @RequestBody LoginRequest req) {
        authService.register(req.getUsername(), req.getPassword());
        return ResponseEntity.ok("User registered");
    }

    // --------------------------------------------------------------------
    @PostMapping("/login")
    public ResponseEntity<JwtResponse> login(@Valid @RequestBody LoginRequest req) {
        JwtResponse jwt = authService.login(req);
        return ResponseEntity.ok(jwt);
    }

    // --------------------------------------------------------------------
    @PostMapping("/refresh")
    public ResponseEntity<JwtResponse> refresh(@Valid @RequestBody RefreshRequest req) {
        JwtResponse jwt = authService.refresh(req);
        return ResponseEntity.ok(jwt);
    }

    // --------------------------------------------------------------------
    @PostMapping("/logout")
    public ResponseEntity<String> logout(@RequestHeader("Authorization") String bearer) {
        String token = bearer.replace("Bearer ", "");
        authService.logout(token);
        return ResponseEntity.ok("Logged out (single session)");
    }

    // --------------------------------------------------------------------
    @PostMapping("/logout-all")
    public ResponseEntity<String> logoutAll(@AuthenticationPrincipal UserDetails user) {
        authService.logoutAll(user.getUsername());
        return ResponseEntity.ok("All sessions terminated");
    }

    // --------------------------------------------------------------------
    @GetMapping("/sessions")
    public ResponseEntity<List<Map<String, Object>>> listSessions(@AuthenticationPrincipal UserDetails user) {
        List<JwtToken> tokens = authService.listActiveSessions(user.getUsername());

        // Map to a friendly JSON view (id, description, issuedAt, expiresAt)
        List<Map<String, Object>> resp = new ArrayList<>();
        for (JwtToken t : tokens) {
            Map<String, Object> m = new HashMap<>();
            m.put("id", t.getId());
            m.put("description", t.getDescription());
            m.put("issuedAt", t.getIssuedAt());
            m.put("expiresAt", t.getExpiresAt());
            resp.add(m);
        }
        return ResponseEntity.ok(resp);
    }
}
