## 3. 下载 Controller（核心实现）

```java
package com.example.demo.controller;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.*;
import org.springframework.http.*;
import org.springframework.util.StringUtils;
import org.springframework.web.bind.annotation.*;

import java.io.*;
import java.net.URLEncoder;
import java.nio.file.*;
import java.util.*;

@RestController
@RequestMapping("/files")
public class FileDownloadController {

    private static final Logger log = LoggerFactory.getLogger(FileDownloadController.class);

    /** 文件根目录（外部化配置） */
    @Value("${file.upload-dir}")
    private String uploadDir;

    /** 允许下载的文件后缀（可选） */
    private static final Set<String> ALLOWED_EXT = Set.of(
            "txt", "pdf", "doc", "docx",
            "png", "jpg", "jpeg", "gif", "bmp",
            "zip", "rar", "mp4", "mp3"
    );

    /**
     * 统一下载入口（强制“保存”，适用于所有类型的文件）。
     *   GET /files/download?name=example.txt
     */
    @GetMapping("/download")
    public ResponseEntity<Resource> downloadFile(@RequestParam("name") String fileName) throws IOException {
        // 1️⃣ 参数校验
        if (!StringUtils.hasText(fileName)) {
            return ResponseEntity.badRequest().build();
        }

        // 2️⃣ 防止路径穿越  (../evil.txt)
        Path filePath = Paths.get(uploadDir).resolve(fileName).normalize();

        // 必须仍在根目录下
        Path rootPath = Paths.get(uploadDir).toAbsolutePath().normalize();
        if (!filePath.toAbsolutePath().startsWith(rootPath)) {
            log.warn("非法访问文件: {}", filePath);
            return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
        }

        // 3️⃣ 文件存在性检查
        if (!Files.exists(filePath) || !Files.isRegularFile(filePath)) {
            return ResponseEntity.notFound().build();
        }

        // 4️⃣ 可选：白名单检查（如果只想开放特定后缀）
        String ext = com.google.common.io.Files.getFileExtension(filePath.getFileName().toString()).toLowerCase();
        if (!ALLOWED_EXT.contains(ext)) {
            log.warn("文件后缀不在白名单: {}", ext);
            return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
        }

        // 5️⃣ 读取资源（使用 UrlResource 避免一次性加载到内存）
        Resource resource = new UrlResource(filePath.toUri());

        // 6️⃣ MIME 类型探测
        String contentType = Files.probeContentType(filePath);
        if (contentType == null) {
            // 兜底为二进制流
            contentType = "application/octet-stream";
        }

        // 7️⃣ 处理中文或特殊字符文件名（RFC 5987）
        String encodedFileName = URLEncoder.encode(resource.getFilename(), "UTF-8")
                .replaceAll("\\+", "%20"); // 空格要保留为 %20

        // 8️⃣ 构造响应头
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.parseMediaType(contentType));
        // 这里使用 attachment 强制下载；若想“直接打开”可以改为 inline
        headers.setContentDisposition(ContentDisposition.attachment()
                .filename(encodedFileName, StandardCharsets.UTF_8)
                .build());

        // 9️⃣ 返回响应体（流式、不占用大量内存）
        return ResponseEntity.ok()
                .headers(headers)
                .body(resource);
    }

    /**
     * 预览图片/文本等（inline），适合浏览器直接显示。
     *   GET /files/preview?name=example.png
     */
    @GetMapping("/preview")
    public ResponseEntity<Resource> previewFile(@RequestParam("name") String fileName) throws IOException {
        // 与 downloadFile 中的前 5 步相同，这里抽取共用方法（略）
        Path filePath = Paths.get(uploadDir).resolve(fileName).normalize();
        Path rootPath = Paths.get(uploadDir).toAbsolutePath().normalize();
        if (!filePath.toAbsolutePath().startsWith(rootPath) ||
                !Files.isRegularFile(filePath)) {
            return ResponseEntity.notFound().build();
        }

        Resource resource = new UrlResource(filePath.toUri());

        // 探测 Content-Type；若为 null 则使用通用二进制
        String contentType = Files.probeContentType(filePath);
        if (contentType == null) {
            contentType = "application/octet-stream";
        }

        // inline => 浏览器尝试直接渲染
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.parseMediaType(contentType));
        headers.setContentDisposition(ContentDisposition.inline()
                .filename(resource.getFilename(), StandardCharsets.UTF_8)
                .build());

        return ResponseEntity.ok()
                .headers(headers)
                .body(resource);
    }

    /**
     * 多文件压缩后下载（可选功能）。将 userIds 对应的文件打成 zip，直接返回 zip 流。
     *   GET /files/download-zip?names=file1.txt,file2.jpg
