    @GetMapping("/download-zip")
    public ResponseEntity<Resource> downloadAsZip(@RequestParam("names") List<String> names) throws IOException {
        // 校验 & 构造 zip 临时文件
        Path zipPath = Files.createTempFile("download-", ".zip");
        try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(zipPath))) {
            for (String name : names) {
                Path filePath = Paths.get(uploadDir).resolve(name).normalize();
