## 4️⃣ 公共工具类

### 4.1 `Message.java`（协议包装/解析）

```java
package com.ecommerce.cs;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

/**
 * Message 协议封装/解析工具
 *   - MAGIC = 0xCAFEBABE
 *   - TYPE  : 0=text,1=image,2=file,3=system
 */
public class Message {
    public static final int MAGIC = 0xCAFEBABE;

    public static final byte TYPE_TEXT   = 0;
    public static final byte TYPE_IMAGE  = 1;
    public static final byte TYPE_FILE   = 2;
    public static final byte TYPE_SYSTEM = 3;

    /** 系统子类型（仅在 TYPE_SYSTEM 时使用） */
    public static final byte SYS_BUSY    = 0;
    public static final byte SYS_ACCEPT  = 1;
    public static final byte SYS_REJECT  = 2;

    // ---------- 发送 ----------
    public static void sendText(DataOutputStream out, String text) throws IOException {
        byte[] body = text.getBytes(StandardCharsets.UTF_8);
        writeHeader(out, TYPE_TEXT, body.length);
        out.write(body);
        out.flush();
    }

    public static void sendImage(DataOutputStream out, File imgFile) throws IOException {
        String name = imgFile.getName();
        byte[] nameBytes = name.getBytes(StandardCharsets.UTF_8);
        byte[] data = Files.readAllBytes(imgFile.toPath());

        int bodyLen = 4 + nameBytes.length + data.length; // nameLen + name + data
        writeHeader(out, TYPE_IMAGE, bodyLen);

        out.writeInt(nameBytes.length);
        out.write(nameBytes);
        out.write(data);
        out.flush();
    }

    public static void sendFile(DataOutputStream out, File file) throws IOException {
        String name = file.getName();
        byte[] nameBytes = name.getBytes(StandardCharsets.UTF_8);
        byte[] data = Files.readAllBytes(file.toPath());

        int bodyLen = 4 + nameBytes.length + data.length;
        writeHeader(out, TYPE_FILE, bodyLen);

        out.writeInt(nameBytes.length);
        out.write(nameBytes);
        out.write(data);
        out.flush();
    }

    public static void sendSystem(DataOutputStream out, byte sysType, String extra) throws IOException {
        // extra 例如 "BUSY"、"ACCEPT"、"REJECT"
        byte[] extraBytes = extra.getBytes(StandardCharsets.UTF_8);
        int bodyLen = 1 + extraBytes.length; // sysType + extra
        writeHeader(out, TYPE_SYSTEM, bodyLen);
        out.writeByte(sysType);
        out.write(extraBytes);
        out.flush();
    }

    private static void writeHeader(DataOutputStream out, byte type, int bodyLen) throws IOException {
        out.writeInt(MAGIC);
        out.writeByte(type);
        out.writeInt(bodyLen);
    }

    // ---------- 接收 ----------
    public static ReceivedMessage receive(DataInputStream in) throws IOException {
        // 读取头部
        int magic = in.readInt();
        if (magic != MAGIC) {
            throw new IOException("Invalid magic number!");
        }
        byte type = in.readByte();
        int len = in.readInt();

        // 读取 body
        byte[] body = new byte[len];
        in.readFully(body);
        return new ReceivedMessage(type, body);
    }

    /** 内部包装，统一返回体 */
    public static class ReceivedMessage {
        public final byte type;
        public final byte[] body;

        public ReceivedMessage(byte type, byte[] body) {
            this.type = type;
            this.body = body;
        }

        /** 仅当 type == TYPE_TEXT 时调用 */
        public String getText() {
            return new String(body, StandardCharsets.UTF_8);
        }

        /** 仅当 type == TYPE_IMAGE 或 TYPE_FILE 时调用 */
        public FileData getFileData() throws IOException {
            ByteArrayInputStream bis = new ByteArrayInputStream(body);
            DataInputStream dis = new DataInputStream(bis);
            int nameLen = dis.readInt();
            byte[] nameBytes = new byte[nameLen];
            dis.readFully(nameBytes);
            String filename = new String(nameBytes, StandardCharsets.UTF_8);
            byte[] data = new byte[body.length - 4 - nameLen];
            dis.readFully(data);
            return new FileData(filename, data);
        }

        /** 仅当 type == TYPE_SYSTEM 时调用 */
        public SystemMessage getSystemMessage() {
            byte sub = body[0];
            String extra = new String(body, 1, body.length - 1, StandardCharsets.UTF_8);
            return new SystemMessage(sub, extra);
        }
    }

    /** 文件/图片返回包装 */
    public static class FileData {
        public final String filename;
        public final byte[] data;

        public FileData(String filename, byte[] data) {
            this.filename = filename;
            this.data = data;
        }

        /** 保存至磁盘 */
        public void writeTo(File destDir) throws IOException {
            if (!destDir.exists()) destDir.mkdirs();
            File out = new File(destDir, filename);
            try (FileOutputStream fos = new FileOutputStream(out)) {
                fos.write(data);
            }
        }
    }

    /** 系统消息包装 */
    public static class SystemMessage {
        public final byte subType;
        public final String extra;

        public SystemMessage(byte subType, String extra) {
            this.subType = subType;
            this.extra = extra;
        }
    }
}
```

> **说明**  
> - `Message.sendXxx` 系列方法负责把**业务对象**编码为二进制流并写入 `DataOutputStream`。  
> - `Message.receive` 把网络流解析成 `ReceivedMessage`，随后根据 `type` 调用对应的 getter。  
> - 为了避免 TCP 粘包、半包问题，这里使用 **固定长度头部 + body** 方式，`readFully` 能确保一次读取完整。

