### 2.2 `PriceInfo` – une valeur immuable

```java
import java.math.BigDecimal;
import java.util.Objects;

/**
 * Représente le prix offert par un marchand pour une skin.
 * La plupart du temps on ne garde que le prix “le plus bas” (selling price).
 */
public final class PriceInfo {
    private final BigDecimal price;          // prix en euros (ou USD) – peut être null
    private final BigDecimal instantSale;    // prix instant‑sale (bitskins, buff…)
    private final String rawSource;          // valeur brute du JSON (pour le debug)

    private PriceInfo(BigDecimal price, BigDecimal instantSale, String rawSource) {
        this.price = price;
        this.instantSale = instantSale;
        this.rawSource = rawSource;
    }

    /** Factory method – s’occupe de la conversion depuis String/Number */
    public static PriceInfo of(Object jsonValue) {
        if (jsonValue == null) return new PriceInfo(null, null, "null");
        if (jsonValue instanceof Number n) {
            return new PriceInfo(toBigDecimal(n), null, n.toString());
        }
        if (jsonValue instanceof String s) {
            try {
                return new PriceInfo(new BigDecimal(s), null, s);
            } catch (NumberFormatException e) {
                // valeur non numérique (ex. "null") → on renvoie null
                return new PriceInfo(null, null, s);
            }
        }
        // si c’est un objet (ex. {"price":"949.99","instant_sale_price":null})
        // le parsing sera fait dans le parser dédié (voir plus bas)
        throw new IllegalArgumentException("Unsupported price representation: " + jsonValue);
    }

    public static PriceInfo of(BigDecimal price) {
        return new PriceInfo(price, null, price.toString());
    }

    /** Retourne le prix le plus « favorable » (le plus bas) */
    public BigDecimal effectivePrice() {
        // on privilégie instantSale si présent, sinon price
        return instantSale != null ? instantSale : price;
    }

    // getters
    public BigDecimal price() { return price; }
    public BigDecimal instantSale() { return instantSale; }
    public String rawSource() { return rawSource; }

    private static BigDecimal toBigDecimal(Number n) {
        return new BigDecimal(n.toString());
    }

    @Override
    public String toString() {
        return "PriceInfo{price=%s, instantSale=%s}".formatted(price, instantSale);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof PriceInfo that)) return false;
        return Objects.equals(price, that.price) &&
               Objects.equals(instantSale, that.instantSale);
    }

    @Override
    public int hashCode() {
        return Objects.hash(price, instantSale);
    }
}
```

