### 2.4 `Skin` – agrège toutes les offres

```java
import java.util.Collections;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;

public final class Skin {
    private final String name;                     // ex. "★ M9 Bayonet | Damascus Steel (Factory New)"
    private final Map<MerchantId, Offer> offers;   // map immutable

    private Skin(String name, Map<MerchantId, Offer> offers) {
        this.name = name;
        this.offers = Collections.unmodifiableMap(offers);
    }

    /** Factory – créé à partir du fragment JSON d’une skin */
    public static Skin fromJson(String skinName, Map<String, Object> merchantMap) {
        var offers = merchantMap.entrySet().stream()
                .collect(Collectors.toMap(
                        e -> MerchantId.fromJsonKey(e.getKey()),
                        e -> OfferParser.parse(e.getKey(), e.getValue())
                ));
        return new Skin(skinName, offers);
    }

    public String name() { return name; }

    /** Toutes les offres (readonly) */
    public Map<MerchantId, Offer> offers() { return offers; }

    /** Retourne l’offre la plus chère (à vendre) */
    public Offer highestOffer() {
        return offers.values().stream()
                .filter(o -> o.effectivePrice() != null)
                .max((a, b) -> a.effectivePrice().compareTo(b.effectivePrice()))
                .orElse(null);
    }

    /** Retourne l’offre la moins chère (à acheter) */
    public Offer lowestOffer() {
        return offers.values().stream()
                .filter(o -> o.effectivePrice() != null)
                .min((a, b) -> a.effectivePrice().compareTo(b.effectivePrice()))
                .orElse(null);
    }

    @Override
    public String toString() {
        return "Skin{name='%s', offers=%s}".formatted(name, offers);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Skin skin)) return false;
        return Objects.equals(name, skin.name) && Objects.equals(offers, skin.offers);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, offers);
    }
}
```

