import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.File;
import java.io.IOException;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Charge le JSON et le transforme en liste de Skin.
 */
public class JsonSkinRepository implements SkinRepository {
    private final ObjectMapper mapper = new ObjectMapper();

    private final File sourceFile;   // peut être une URL ou InputStream

    public JsonSkinRepository(File sourceFile) {
        this.sourceFile = sourceFile;
    }

    @Override
    public List<Skin> findAll() throws IOException {
        // Le JSON racine est un objet : { "skin name": { merchant… }, … }
        TypeReference<Map<String, Map<String, Object>>> typeRef =
                new TypeReference<>() {};

        Map<String, Map<String, Object>> root = mapper.readValue(sourceFile, typeRef);

        return root.entrySet().stream()
                .map(entry -> Skin.fromJson(entry.getKey(), entry.getValue()))
                .collect(Collectors.toList());
    }
}
