package com.example.jira;

import com.fasterxml.jackson.annotation.JsonAlias;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;

/**
 * Simple POJO that models the fields we usually care about.
 *
 * The annotations are tolerant – if a field is missing the parser will just leave the
 * Java field null (no exception is thrown).
 */
@JsonIgnoreProperties(ignoreUnknown = true) // ignore anything we didn't map
public class JiraIssue {

    /** The issue key, e.g. "PROJ-123" */
    @JsonProperty("key")
    private String key;

    /** Human readable summary / title */
    @JsonProperty("summary")
    private String summary;

    /** Full description (might be HTML or markdown) */
    @JsonProperty("description")
    private String description;

    /** Current status, e.g. "Open", "Done" */
    @JsonProperty("status")
    private String status;

    /** Name of the assignee (or null if unassigned) */
    @JsonProperty("assignee")
    private String assignee;

    /** Who reported the issue */
    @JsonProperty("reporter")
    private String reporter;

    /** Creation timestamp, ISO‑8601 */
    @JsonProperty("created")
    private String created;

    /** Last update timestamp, ISO‑8601 */
    @JsonProperty("updated")
    private String updated;

    /** Priority (e.g. "Major", "Critical") */
    @JsonProperty("priority")
    private String priority;

    // -----------------------------------------------------------------------
    // Getters & Setters – IDE can generate them automatically.
    // -----------------------------------------------------------------------
    public String getKey() { return key; }
    public void setKey(String key) { this.key = key; }

    public String getSummary() { return summary; }
    public void setSummary(String summary) { this.summary = summary; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }

    public String getAssignee() { return assignee; }
    public void setAssignee(String assignee) { this.assignee = assignee; }

    public String getReporter() { return reporter; }
    public void setReporter(String reporter) { this.reporter = reporter; }

    public String getCreated() { return created; }
    public void setCreated(String created) { this.created = created; }

    public String getUpdated() { return updated; }
    public void setUpdated(String updated) { this.updated = updated; }

    public String getPriority() { return priority; }
    public void setPriority(String priority) { this.priority = priority; }

    @Override
    public String toString() {
        return "JiraIssue{" +
                "key='" + key + '\'' +
                ", summary='" + summary + '\'' +
                ", status='" + status + '\'' +
                ", assignee='" + assignee + '\'' +
                ", priority='" + priority + '\'' +
                '}';
    }
}
```

> **Tip** – If your export contains additional fields you care about, simply add new `private` members with `@JsonProperty("fieldNameInExport")` (or `@JsonAlias` for multiple possible names). Jackson will map them automatically.

