 */
public class Main {

    private static final Logger LOG = LoggerFactory.getLogger(Main.class);

    public static void main(String[] args) {
        if (args.length == 0) {
            System.err.println("Usage: java Main <jira-export-file>");
            System.exit(1);
        }

        File exportFile = new File(args[0]);
        LOG.info("Parsing Jira export: {}", exportFile.getAbsolutePath());

        List<JiraIssue> issues;
        try {
