            LOG.error("Failed to parse the export file", e);
            System.exit(2);
            return; // unreachable but keeps the compiler happy
        }

        LOG.info("Successfully parsed {} issues.", issues.size());

        // Print a short summary for each issue – you can of course do anything else.
        for (JiraIssue issue : issues) {
