## 4️⃣ RESTful Web Services – JAX‑RS (Standard) and Spring Boot (de‑facto)

### 4.1️⃣ Defining a Resource (JAX‑RS)

```java
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;

@Path("/books")
@Produces(MediaType.APPLICATION_JSON)
@Consumes(MediaType.APPLICATION_JSON)
public class BookResource {

    private static final Map<Long, Book> DB = new ConcurrentHashMap<>();

    @GET
    public Collection<Book> list() {
        return DB.values();
    }

    @GET
    @Path("{id}")
    public Book get(@PathParam("id") long id) {
        Book b = DB.get(id);
        if (b == null) throw new NotFoundException();
        return b;
    }

    @POST
    public Response create(Book book, @Context UriInfo uriInfo) {
        long id = System.nanoTime(); // cheap unique id for demo
        book.setId(id);
        DB.put(id, book);
        return Response.created(uriInfo.getAbsolutePathBuilder().path(Long.toString(id)).build())
                       .entity(book)
                       .build();
    }

    @PUT
    @Path("{id}")
    public Book update(@PathParam("id") long id, Book book) {
        if (!DB.containsKey(id)) throw new NotFoundException();
        book.setId(id);
        DB.put(id, book);
        return book;
    }

    @DELETE
    @Path("{id}")
    public void delete(@PathParam("id") long id) {
        DB.remove(id);
    }
}
```

