package com.example.demo;

import org.springframework.stereotype.Repository;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

@Repository
public class BookRepository {
    private final Map<Long, Book> store = new ConcurrentHashMap<>();
    private final AtomicLong seq = new AtomicLong(1);

    public List<Book> findAll() { return new ArrayList<>(store.values()); }

    public Optional<Book> findById(Long id) { return Optional.ofNullable(store.get(id)); }

    public Book save(Book book) {
        Long id = (book.id() == null) ? seq.getAndIncrement() : book.id();
        Book saved = new Book(id, book.title(), book.author());
        store.put(id, saved);
        return saved;
    }

    public void delete(Long id) { store.remove(id); }
}
