            // INVALID – log for manual review
            LOG.warning("Invalid IPN: " + ipnMessage);
            resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
        }
    }

    private void processVerifiedIPN(String raw) {
        // parse raw into a map
        Map<String, String> params = Arrays.stream(raw.split("&"))
                .map(s -> s.split("=", 2))
                .collect(Collectors.toMap(a -> URLDecoder.decode(a[0], StandardCharsets.UTF_8),
                                          a -> a.length > 1 ? URLDecoder.decode(a[1], StandardCharsets.UTF_8) : ""));
        // Example checks:
        String txnId = params.get("txn_id");
        String paymentStatus = params.get("payment_status");
        String receiver = params.get("receiver_email");
        // ... business logic ...
    }
}
```

**Key points in the servlet version:**

- **Never use `request.getParameter()`** for IPN verification – it can alter the payload (duplicate parameters, different decoding).  
- **Read the raw body** once, reuse it both for verification and for your own processing.  
- **Log everything** (raw payload + verification result) – essential for troubleshooting later.  

