```java
package com.example.jwtauthdemo.service;

import com.example.jwtauthdemo.model.User;
import com.example.jwtauthdemo.payload.RegisterRequest;
import com.example.jwtauthdemo.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

import java.util.Collections;

@Service
@RequiredArgsConstructor
public class RegistrationService {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;

    public User registerUser(RegisterRequest request) {
        // проверка уникальности
        if (userRepository.existsByUsername(request.username())) {
            throw new RuntimeException("Username is already taken!");
        }
        if (userRepository.existsByEmail(request.email())) {
            throw new RuntimeException("Email is already in use!");
        }

        User user = User.builder()
                .email(request.email())
                .username(request.username())
                .password(passwordEncoder.encode(request.password()))
                .roles(Collections.singleton("ROLE_USER")) // по‑умолчанию обычный пользователь
                .build();

        return userRepository.save(user);
    }
}
