## 9. Полный примера «Hello World» с Spring Boot и полной трассировкой

```java
// src/main/java/com/example/DemoApplication.java
package com.example;

import io.sentry.spring.tracing.SentrySpan;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;

@SpringBootApplication
@RestController
@RequestMapping("/api")
public class DemoApplication {

    public static void main(String[] args) {
        // При наличии sentry-spring-boot-starter отдельная инициализация не нужна,
        // но можно задать дополнительные опции:
        // Sentry.init(options -> { ... });
        SpringApplication.run(DemoApplication.class, args);
    }

    @GetMapping("/calc/{a}/{b}")
    @SentrySpan // создаст спан с именем "DemoApplication.calc"
    public int calc(@PathVariable int a, @PathVariable int b) {
        // Демонстрируем вложенный спан
        var transaction = io.sentry.Sentry.getSpan(); // текущая транзакция
        var inner = transaction.startChild("custom.loop", "intensive-loop");
        try {
            int sum = 0;
            for (int i = 0; i < 1_000_000; i++) {
                sum += (a * b);
            }
            return sum;
        } finally {
            inner.finish();
        }
    }
}
```

