## 6️⃣ Sending the Request – Java 11 HttpClient  

### 6.1 Common configuration

```java
package com.mycompany.fiskal.http;

import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import javax.net.ssl.SSLContext;
import java.util.Map;

public final class FiscalHttpClient {

    private static final HttpClient CLIENT = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(10))
            .sslContext(KeystoreUtil.defaultSslContext())
            .version(HttpClient.Version.HTTP_1_1) // the endpoint still uses 1.1
            .build();

    private FiscalHttpClient() {}

    /** Sends a POST request with the given payload + headers */
    public static HttpResponse<String> post(String url,
                                            String payload,
                                            Map<String, String> extraHeaders) throws Exception {

        HttpRequest.Builder builder = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .timeout(Duration.ofSeconds(30))
                .header("Content-Type", "application/xml") // or application/json for JSON API
                .POST(HttpRequest.BodyPublishers.ofString(payload, java.nio.charset.StandardCharsets.UTF_8));

        // add any custom headers (e.g. X-Request-ID)
        extraHeaders.forEach(builder::header);

        HttpRequest request = builder.build();

        return CLIENT.send(request, HttpResponse.BodyHandlers.ofString());
    }
}
```

