## 9️⃣ Full End‑to‑End Example (JSON path)  

Below is a **single method** that puts everything together. It can be called from a REST controller or a POS service.

```java
package com.mycompany.fiskal.service;

import com.mycompany.fiskal.model.json.FiscalDocument;
import com.mycompany.fiskal.model.json.FiscalDocument.Item;
import com.mycompany.fiskal.sign.JsonSigner;
import com.mycompany.fiskal.http.FiscalHttpClient;
import com.mycompany.fiskal.util.KeystoreUtil;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.OffsetDateTime;
import java.util.*;

public class FiscalisationService {

    private static final String ENDPOINT = "https://www.apis-it.hr:8443/rn-ftp/v1/";
    private static final ObjectMapper MAPPER = new ObjectMapper();

    private final KeystoreUtil.KeyAndCert keyAndCert;

    public FiscalisationService(String pkcs12Path, char[] pkcs12Pwd) throws Exception {
        this.keyAndCert = KeystoreUtil.loadKeyAndCert(pkcs12Path, pkcs12Pwd);
    }

    /**
     * Sends a fiscal receipt to Fina and returns the JIR.
     */
    public String sendReceipt(String oib,
                              List<Item> items) throws Exception {

        // ---- build the POJO -------------------------------------------------
        FiscalDocument doc = new FiscalDocument();
        doc.oib = oib;
        doc.dateTime = OffsetDateTime.now();
        doc.items = items;

        // ---- convert to JSON node (without signature) -----------------------
        ObjectNode nodeWithoutSig = (ObjectNode) MAPPER.valueToTree(doc);
        // The spec requires the field `signature` to be **absent** when we compute it.
        nodeWithoutSig.remove("signature");

        // ---- sign ------------------------------------------------------------
        ObjectNode signedNode = JsonSigner.sign(nodeWithoutSig, keyAndCert.privateKey);
        String payload = MAPPER.writeValueAsString(signedNode);

        // ---- send ------------------------------------------------------------
        HttpResponse<String> response = FiscalHttpClient.post(
                ENDPOINT,
                payload,
                Map.of(
                        "Accept", "application/json",
                        "Content-Type", "application/json"
                )
        );

        if (response.statusCode() != 200) {
            // you should store the failure and maybe retry later
            throw new IllegalStateException("Fiscalisation failed, HTTP " + response.statusCode()
                    + ": " + response.body());
        }

        // ---- parse success response -----------------------------------------
        JsonResponse jsonResp = MAPPER.readValue(response.body(), JsonResponse.class);
        if (jsonResp.jir == null) {
            throw new IllegalStateException("No JIR returned – response: " + response.body());
        }

        // ---- persist receipt + JIR  -----------------------------------------
        saveToDatabase(doc, payload, response.body(), jsonResp.jir);

        return jsonResp.jir;
    }

    private void saveToDatabase(FiscalDocument doc,
                                String requestJson,
                                String responseJson,
                                String jir) {
        // Insert into your DB – see the schema example in section 8.
        // This method is left abstract because it depends on your persistence stack.
    }
}
```

**Calling the service**

```java
