## 3. Client（用户端）实现

### 3.1 主要类

| 类 | 作用 |
|----|------|
| `ChatClient` | 主 UI + 发起会话请求、发送文字/图片/文件、展示历史记录 |
| `ClientReceiver` | 读取服务器推送（包括客服响应、聊天内容），在 UI 中追加显示 |
| `Message/MessageType` | 同 Server 端共用（在 `common` 包） |

### 3.2 `ChatClient.java`

```java
package com.ecommerce.chat.client;

import com.ecommerce.chat.common.*;

import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.Socket;
import java.util.Base64;
import java.util.Date;

public class ChatClient extends JFrame {

    // 服务器地址/端口
    private static final String SERVER_HOST = "localhost";
    private static final int SERVER_PORT = 8888;

    // 本地保存聊天记录的文件前缀
    private static final String LOG_PREFIX = "chat_user_";

    // UI 组件
    private JTextArea taChat;       // 聊天记录展示区
    private JTextField tfInput;     // 输入框
    private JButton btnSend;
    private JButton btnImg;
    private JButton btnFile;
    private JLabel lblStatus;       // 状态栏（客服忙、已连接之类）

    // 网络
    private Socket socket;
    private ObjectOutputStream oos;
    private ObjectInputStream ois;
    private ClientReceiver receiver;

    // 当前用户名（模拟登陆，实际系统可从登录系统获取）
    private final String userName;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            // 为了演示，直接弹出输入框让用户填写昵称
            String name = JOptionPane.showInputDialog(null, "请输入用户名（昵称）：");
            if (name == null || name.trim().isEmpty()) {
                System.exit(0);
            }
            new ChatClient(name.trim()).setVisible(true);
        });
    }

    public ChatClient(String name) {
        this.userName = name;
        setTitle("电商客服系统（用户） - " + userName);
        setSize(600, 500);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        // 启动连线流程
        requestService();
    }

    /**------------------- UI -----------------------**/
    private void initUI() {
        taChat = new JTextArea();
        taChat.setEditable(false);
        taChat.setLineWrap(true);
        taChat.setWrapStyleWord(true);
        JScrollPane spChat = new JScrollPane(taChat);

        tfInput = new JTextField();
        btnSend = new JButton("发送");
        btnImg = new JButton("图片");
        btnFile = new JButton("文件");
        lblStatus = new JLabel("未连接");

        JPanel panelBottom = new JPanel(new BorderLayout());
        JPanel panelBtns = new JPanel();
        panelBtns.add(btnImg);
        panelBtns.add(btnFile);
        panelBtns.add(btnSend);
        panelBottom.add(tfInput, BorderLayout.CENTER);
        panelBottom.add(panelBtns, BorderLayout.EAST);

        Container c = getContentPane();
        c.setLayout(new BorderLayout());
        c.add(spChat, BorderLayout.CENTER);
        c.add(panelBottom, BorderLayout.SOUTH);
        c.add(lblStatus, BorderLayout.NORTH);

        // 事件
        btnSend.addActionListener(e -> sendText());
        tfInput.addActionListener(e -> sendText());

        btnImg.addActionListener(e -> sendImage());
        btnFile.addActionListener(e -> sendFile());

        // 窗口关闭时关闭 socket
        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                closeConnection();
            }
        });
    }

    /**------------------- 网络流程 -------------------**/
    /** 发起“请求客服” */
    private void requestService() {
        lblStatus.setText("正在请求客服，请稍候…");
        SwingWorker<Void, Void> worker = new SwingWorker<>() {
            @Override
            protected Void doInBackground() throws Exception {
                socket = new Socket(SERVER_HOST, SERVER_PORT);
                oos = new ObjectOutputStream(socket.getOutputStream());
                ois = new ObjectInputStream(socket.getInputStream());

                // 发送 REQUEST（text = userName）
                Message req = new Message(MessageType.REQUEST, userName, "Server",
                        userName, null, null, System.currentTimeMillis());
                oos.writeObject(req);
                oos.flush();

                // 等待客服响应，设超时 10 秒
                socket.setSoTimeout(10000);
                try {
                    Message resp = (Message) ois.readObject();
                    if (resp.getType() == MessageType.RESPONSE && "ACCEPT".equals(resp.getText())) {
                        // 通过
                        lblStatus.setText("已连接客服，开始聊天");
                        // 启动后台接收线程
                        receiver = new ClientReceiver(ois, taChat);
                        new Thread(receiver).start();
                        // 读取历史记录
                        loadHistory();
                    } else {
                        // 拒绝
                        lblStatus.setText("客服忙，稍后再试");
                        closeConnection();
                    }
                } catch (java.net.SocketTimeoutException te) {
                    lblStatus.setText("客服未响应，显示“客服忙”");
                    closeConnection();
                }
                return null;
            }
        };
        worker.execute();
    }

    /** 读取本地历史记录（如果有） */
    private void loadHistory() {
        File f = new File(LOG_PREFIX + userName + ".log");
        if (!f.exists()) return;
        try (BufferedReader br = new BufferedReader(new FileReader(f))) {
            String line;
            while ((line = br.readLine()) != null) {
                // 简单解析行：时间|type|from|to|内容
                if (line.startsWith("DATA:")) continue; // 二进制行，不展示
                String[] parts = line.split("\\|", 5);
                if (parts.length < 5) continue;
                long ts = Long.parseLong(parts[0]);
                MessageType type = MessageType.valueOf(parts[1]);
                String from = parts[2];
                String textOrFile = parts[4];
                String prefix = String.format("[%s] %s: ", new Date(ts), from);
                if (type == MessageType.TEXT) {
                    taChat.append(prefix + textOrFile + "\n");
                } else if (type == MessageType.IMAGE) {
                    taChat.append(prefix + "[图片: " + textOrFile + "]\n");
                } else if (type == MessageType.FILE) {
                    taChat.append(prefix + "[文件: " + textOrFile + "]\n");
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 发送文字 */
    private void sendText() {
        String txt = tfInput.getText().trim();
        if (txt.isEmpty() || oos == null) return;
        Message m = new Message(MessageType.TEXT, userName, "Server",
                txt, null, null, System.currentTimeMillis());
        try {
            oos.writeObject(m);
            oos.flush();
            tfInput.setText("");
            // 本地也直接显示（服务器回显会再次显示，这里为了即时感受）
            appendSelfMessage(m);
        } catch (IOException ex) {
            showError("发送失败：" + ex.getMessage());
        }
    }

    /** 发送图片（选择本地文件，转为 byte[]） */
    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new FileNameExtensionFilter("图片文件", ImageIO.getReaderFileSuffixes()));
        int ret = fc.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        File imgFile = fc.getSelectedFile();
        try {
            byte[] data = readFileBytes(imgFile);
            Message m = new Message(MessageType.IMAGE, userName, "Server",
                    null, data, imgFile.getName(), System.currentTimeMillis());
            oos.writeObject(m);
            oos.flush();
            appendSelfMessage(m);
        } catch (IOException ex) {
            showError("发送图片失败：" + ex.getMessage());
        }
    }

    /** 发送任意文件 */
    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        int ret = fc.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        File file = fc.getSelectedFile();
        try {
            byte[] data = readFileBytes(file);
            Message m = new Message(MessageType.FILE, userName, "Server",
                    null, data, file.getName(), System.currentTimeMillis());
            oos.writeObject(m);
            oos.flush();
            appendSelfMessage(m);
        } catch (IOException ex) {
            showError("发送文件失败：" + ex.getMessage());
        }
    }

    /** 将本机文件读取为 byte[] */
    private byte[] readFileBytes(File f) throws IOException {
        try (FileInputStream fis = new FileInputStream(f);
             ByteArrayOutputStream bos = new ByteArrayOutputStream()) {
            byte[] buf = new byte[8192];
            int len;
            while ((len = fis.read(buf)) != -1) {
                bos.write(buf, 0, len);
            }
            return bos.toByteArray();
        }
    }

    /** 在本地 UI 中追加自己发送的消息（仅文字/图片/文件略显） */
    private void appendSelfMessage(Message m) {
        SwingUtilities.invokeLater(() -> {
            String prefix = String.format("[我] %s: ", new Date(m.getTime()));
            if (m.getType() == MessageType.TEXT) {
                taChat.append(prefix + m.getText() + "\n");
            } else if (m.getType() == MessageType.IMAGE) {
                taChat.append(prefix + "[图片: " + m.getFileName() + "]\n");
            } else if (m.getType() == MessageType.FILE) {
                taChat.append(prefix + "[文件: " + m.getFileName() + "]\n");
            }
        });
    }

    /**------------------- 关闭连接 ----------------------**/
    private void closeConnection() {
        try {
            if (oos != null) {
                Message close = new Message(MessageType.CLOSE, userName, "Server",
                        null, null, null, System.currentTimeMillis());
                oos.writeObject(close);
                oos.flush();
            }
            if (receiver != null) receiver.stop();
            if (socket != null) socket.close();
        } catch (Exception ignored) {}
    }

    /**------------------- 辅助 -----------------------**/
    private void showError(String msg) {
        JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE);
    }
}
```

> 代码说明  

* **发起请求**：在 `requestService()` 中，先 `CONNECT → send REQUEST → wait RESPONSE`。  
* **超时处理**：`socket.setSoTimeout(10000)`，若 10 秒内未收到 `RESPONSE`，会抛 `SocketTimeoutException`，此时 UI 显示 “客服忙”。  
* **接收线程** `ClientReceiver`（下面给出）负责把服务器推送的所有消息写入聊天框，并把收到的二进制文件保存到本地（演示仅保存到 `download/` 目录）。  
* **发送图片/文件**：把文件读取为 `byte[]`，填入 `Message.data`。  
* **聊天记录**：`loadHistory()` 在连接成功后读取本地日志文件 `chat_user_<username>.log` 并在 UI 中追加。  

### 3.3 `ClientReceiver.java`

```java
package com.ecommerce.chat.client;

import com.ecommerce.chat.common.*;

import javax.swing.*;
import java.io.*;
import java.util.Base64;

/**
 * 负责从服务器读取 Message 并实时显示到聊天框。
 * 还会把二进制文件保存到本地（download/ 目录），并记录日志文件。
 */
public class ClientReceiver implements Runnable {

    private final ObjectInputStream ois;
    private final JTextArea chatArea;
    private volatile boolean running = true;

    // 本地聊天记录文件
    private final File logFile;

    public ClientReceiver(ObjectInputStream ois, JTextArea chatArea) {
        this.ois = ois;
        this.chatArea = chatArea;
        this.logFile = new File("chat_user_" + System.getProperty("user.name") + ".log"); // 简单示例
        if (!logFile.exists()) {
            try { logFile.createNewFile(); } catch (IOException ignored) {}
        }
    }

    @Override
    public void run() {
        try {
            while (running) {
                Message msg = (Message) ois.readObject();
                if (msg.getType() == MessageType.CLOSE) {
                    break;
                }
                // 追加聊天记录
                appendLog(msg);
                // UI 更新
                SwingUtilities.invokeLater(() -> displayMessage(msg));
            }
        } catch (Exception e) {
            // 读取异常（如服务器关闭）直接退出
        }
    }

    /** 关闭线程 */
    public void stop() {
        running = false;
        try { ois.close(); } catch (IOException ignored) {}
    }

    /** 将消息写入本地日志（追加） */
    private synchronized void appendLog(Message msg) {
        try (FileWriter fw = new FileWriter(logFile, true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            String line = String.format("%d|%s|%s|%s|%s",
                    msg.getTime(),
                    msg.getType(),
                    msg.getFrom(),
                    msg.getTo(),
                    msg.getType() == MessageType.TEXT ? msg.getText() : msg.getFileName());
            bw.write(line);
            bw.newLine();
            // 对于二进制数据，写一行 Base64（与服务器保持一致）
            if (msg.getData() != null && msg.getData().length > 0) {
                bw.write("DATA:" + Base64.getEncoder().encodeToString(msg.getData()));
                bw.newLine();
            }
            bw.flush();
        } catch (IOException ignored) {}
    }

    /** 把收到的 Message 渲染到聊天框 */
    private void displayMessage(Message msg) {
        String prefix = String.format("[%s] %s: ", new Date(msg.getTime()), msg.getFrom());
        switch (msg.getType()) {
            case TEXT -> chatArea.append(prefix + msg.getText() + "\n");
            case IMAGE -> {
                chatArea.append(prefix + "[图片: " + msg.getFileName() + "]\n");
                // 保存图片到本地 download/ 目录，方便后期浏览
                saveBinary(msg, "download/img");
            }
            case FILE -> {
                chatArea.append(prefix + "[文件: " + msg.getFileName() + "]\n");
                saveBinary(msg, "download/file");
            }
            default -> { /* ignore */ }
        }
    }

    /** 保存二进制文件（图片/文件） */
    private void saveBinary(Message msg, String subDir) {
        try {
            File dir = new File(subDir);
            if (!dir.exists()) dir.mkdirs();
            File out = new File(dir, msg.getFileName());
            try (FileOutputStream fos = new FileOutputStream(out)) {
                fos.write(msg.getData());
                fos.flush();
            }
            chatArea.append("   已保存至: " + out.getAbsolutePath() + "\n");
        } catch (IOException e) {
            chatArea.append("   保存文件失败: " + e.getMessage() + "\n");
        }
    }
}
```

> 关键点  

* `ClientReceiver` **阻塞读取** `ObjectInputStream`，把每条 `Message` 写入本地日志、更新 UI。  
* 对于 `IMAGE` / `FILE`，把二进制数据保存到本地 `download/` 目录并在聊天框里提示保存路径。  
* 为了实现“**聊天记录持久化**”，每条消息（包括二进制）都追加写入 `chat_user_<username>.log`，后续再次登录时 `ChatClient.loadHistory()` 会把它们读取出来。  

