package com.example.betgamedemo;

import android.content.Context;
import android.content.SharedPreferences;

/**
 * Simple wrapper over SharedPreferences to store the player's virtual balance.
 */
public class BalanceManager {
    private static final String PREF_NAME = "BetGamePrefs";
    private static final String KEY_BALANCE = "balance";

    private final SharedPreferences prefs;

    public BalanceManager(Context context) {
        prefs = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE);
    }

    /** Returns the stored balance, defaulting to startBalance if none stored yet. */
    public int getBalance(int startBalance) {
        return prefs.getInt(KEY_BALANCE, startBalance);
    }

    /** Saves the balance. */
    public void setBalance(int balance) {
        prefs.edit().putInt(KEY_BALANCE, balance).apply();
    }

    /** Resets the balance to the provided start amount (useful for testing). */
    public void reset(int startBalance) {
        setBalance(startBalance);
    }
}
