import java.util.Random;

/**
 * Very small betting game – all logic lives inside this activity.
 *
 * Game rules (re‑stated):
 * • Player starts with a virtual balance (default 1000 credits).
 * • Player enters a bet amount and a guess (1‑10).
 * • If guess == random number → win 9×bet (total 10×bet return).
 * • Else → lose the bet amount.
 */
public class MainActivity extends AppCompatActivity {

    private static final int START_BALANCE = 1000;
    private static final int MIN_GUESS = 1;
    private static final int MAX_GUESS = 10;

    private TextView tvBalance, tvResult;
    private EditText etBetAmount, etGuess;
    private Button btnPlay;

    private BalanceManager balanceManager;
    private Random random = new Random();

    // ------------------------------------------------------------------------
    // Lifecycle
    // ------------------------------------------------------------------------
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

		// UI bindings
        tvBalance = findViewById(R.id.tvBalance);
        tvResult  = findViewById(R.id.tvResult);
        etBetAmount = findViewById(R.id.etBetAmount);
        etGuess   = findViewById(R.id.etGuess);
        btnPlay   = findViewById(R.id.btnPlay);

        // initialise balance manager
        balanceManager = new BalanceManager(this);
        updateBalanceUI();

        // button click
        btnPlay.setOnClickListener(v -> playRound());
    }

    // ------------------------------------------------------------------------
    // Game logic
    // ------------------------------------------------------------------------
    private void playRound() {
        // 1️⃣ Validate bet amount
        String betStr = etBetAmount.getText().toString().trim();
        if (TextUtils.isEmpty(betStr)) {
            toast("Enter a bet amount");
            return;
        }
        int bet;
        try {
            bet = Integer.parseInt(betStr);
        } catch (NumberFormatException e) {
            toast("Bet must be a number");
            return;
        }
        if (bet <= 0) {
            toast("Bet must be > 0");
            return;
        }

        // 2️⃣ Validate guess
        String guessStr = etGuess.getText().toString().trim();
        if (TextUtils.isEmpty(guessStr)) {
            toast("Enter your guess");
            return;
        }
        int guess;
        try {
            guess = Integer.parseInt(guessStr);
        } catch (NumberFormatException e) {
            toast("Guess must be a number");
            return;
        }
        if (guess < MIN_GUESS || guess > MAX_GUESS) {
            toast("Guess must be between " + MIN_GUESS + " and " + MAX_GUESS);
            return;
        }

        // 3️⃣ Check if player has enough balance
        int currentBalance = balanceManager.getBalance(START_BALANCE);
        if (bet > currentBalance) {
            toast("Not enough balance");
            return;
        }

        // 4️⃣ Generate random number & decide outcome
        int generated = random.nextInt(MAX_GUESS) + MIN_GUESS; // inclusive 1‑10
        boolean win = (guess == generated);

        // 5️⃣ Update balance
        int newBalance;
        if (win) {
            // Win 9×bet (total 10×bet return)
            newBalance = currentBalance + (bet * 9);
        } else {
            newBalance = currentBalance - bet;
        }
        balanceManager.setBalance(newBalance);

        // 6️⃣ Show result
        String resultMsg = win
                ? "🎉 You guessed " + generated + "! You win " + (bet * 9) + " credits."
                : "❌ Wrong! It was " + generated + ". You lose " + bet + " credits.";
        tvResult.setText(resultMsg);
        tvResult.setTextColor(getResources().getColor(win ?
                android.R.color.holo_green_dark : android.R.color.holo_red_dark));

        // 7️⃣ Update UI
        updateBalanceUI();

        // Reset input fields (optional)
        etBetAmount.setText("");
        etGuess.setText("");
    }

    // ------------------------------------------------------------------------
    // Helper methods
    // ------------------------------------------------------------------------
    private void updateBalanceUI() {
        int balance = balanceManager.getBalance(START_BALANCE);
        tvBalance.setText("Balance: " + balance);
    }

    private void toast(String msg) {
        Toast.makeText(this, msg, Toast.LENGTH_SHORT).show();
    }
}
