```java
public class MainActivity extends AppCompatActivity {

    private static final String URL = "https://postman-echo.com/post";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // 1️⃣ HttpURLConnection
        findViewById(R.id.btn_httpurl).setOnClickListener(v -> {
            new Thread(() -> {
                try {
                    String json = "{\"type\":\"httpurl\",\"msg\":\"Hello\"}";
                    String resp = HttpUtil.postString(URL, json);
                    runOnUiThread(() -> showResult("HttpURLConnection", resp));
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }).start();
        });

        // 2️⃣ Volley
        findViewById(R.id.btn_volley).setOnClickListener(v -> {
            String json = "{\"type\":\"volley\",\"msg\":\"World\"}";
            VolleyUtil.postStringWithVolley(this, URL, json,
                    response -> showResult("Volley", response),
                    error -> showResult("Volley", "Error: " + error));
        });

        // 3️⃣ OkHttp
        findViewById(R.id.btn_okhttp).setOnClickListener(v -> {
            String json = "{\"type\":\"okhttp\",\"msg\":\"Android\"}";
            OkHttpUtil.postStringWithOkHttpAsync(URL, json, new Callback() {
                @Override public void onFailure(Call call, IOException e) {
                    runOnUiThread(() -> showResult("OkHttp", "Fail: " + e));
                }
                @Override public void onResponse(Call call, Response response) throws IOException {
                    final String body = response.body() != null ? response.body().string() : "";
                    runOnUiThread(() -> showResult("OkHttp", body));
                }
            });
        });

        // 4️⃣ Retrofit
        findViewById(R.id.btn_retrofit).setOnClickListener(v -> {
            String json = "{\"type\":\"retrofit\",\"msg\":\"Thanks\"}";
            RequestBody body = RequestBody.create(json,
                    MediaType.parse("application/json; charset=utf-8"));
            MyApiService api = ApiClient.createService(MyApiService.class);
            api.postRawString(body).enqueue(new Callback<String>() {
                @Override public void onResponse(Call<String> call, Response<String> response) {
                    String txt = response.isSuccessful() ? response.body() : "HTTP " + response.code();
                    showResult("Retrofit", txt);
                }
                @Override public void onFailure(Call<String> call, Throwable t) {
                    showResult("Retrofit", "Fail: " + t);
                }
            });
        });
    }

    private void showResult(String tag, String msg) {
        Toast.makeText(this, tag + " => " + msg, Toast.LENGTH_LONG).show();
        Log.d("POST_DEMO", tag + ": " + msg);
    }
}
```

