import java.io.*;
import java.net.*;
import java.util.concurrent.*;

/**
 * Server that receives a {@link Packet} object, prints it and answers with an ACK
 * packet.  Listens on TCP port 1024.
 *
 * The server is multithreaded – each client connection is handled in its own
 * worker thread taken from a fixed thread pool (size = 10).
 */
public class TCPPacketServer {

    private static final int PORT = 1024;
    private static final ExecutorService POOL = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        System.out.println("TCPPacketServer – listening on port " + PORT);
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            while (true) {
                Socket client = serverSocket.accept();
                POOL.execute(new ClientHandler(client));
            }
        } catch (IOException e) {
            System.err.println("Server error: " + e.getMessage());
        } finally {
            POOL.shutdown();
        }
    }

    /** Handles a single client connection. */
    private static class ClientHandler implements Runnable {
        private final Socket socket;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            System.out.println("Connected to client " + socket.getRemoteSocketAddress());

            try (ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
                 ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream())) {

                // 1. Receive the client packet
                Packet inPkt = (Packet) ois.readObject();
                System.out.printf("FROM CLIENT %s: Packet serialNo#%d, data='%s'%n",
                        socket.getRemoteSocketAddress(),
                        inPkt.getSerialNo(),
                        inPkt.getData());

                // 2. Send ACK packet back
                Packet ack = new Packet(inPkt.getSerialNo(), "ACK");
                oos.writeObject(ack);
                oos.flush();

                System.out.println("ACK sent to client " + socket.getRemoteSocketAddress());

            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Communication error with " + socket.getRemoteSocketAddress()
                                   + ": " + e.getMessage());
            } finally {
                try {
                    socket.close();
                } catch (IOException ignored) { }
                System.out.println("Connection closed for client " + socket.getRemoteSocketAddress());
            }
        }
    }
}
```

