import java.io.*;
import java.net.*;

/**
 * Simple “Message‑Transform” server.  For each line received it sends back the same
 * line converted to upper‑case.  Terminates when the client sends the line
 * {@code CLOSE}.
 *
 * Listens on TCP port 8080.
 */
public class MTServer {

    private static final int PORT = 8080;

    public static void main(String[] args) {
        System.out.println("MTServer – listening on port " + PORT);
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            while (true) {
                Socket client = serverSocket.accept();
                System.out.println("MTServer: new client " + client.getRemoteSocketAddress());
                handleClient(client);
            }
        } catch (IOException e) {
            System.err.println("MTServer error: " + e.getMessage());
        }
    }

    private static void handleClient(Socket client) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(client.getInputStream()));
             PrintStream ps = new PrintStream(client.getOutputStream())) {

            String line;
            while ((line = br.readLine()) != null) {
                System.out.println("MTServer received: " + line);
                if ("CLOSE".equalsIgnoreCase(line)) {
                    System.out.println("MTServer – client requested termination.");
                    break;
                }
                String upper = line.toUpperCase();
                ps.println(upper);               // send back upper‑cased line
                System.out.println("MTServer replied: " + upper);
            }
        } catch (IOException e) {
            System.err.println("MTServer communication error: " + e.getMessage());
        } finally {
            try { client.close(); } catch (IOException ignored) {}
            System.out.println("MTServer: connection closed.");
        }
    }
}
```

