public class Md5Util {

    /**
     * 计算 md5
     *
     * @param wmPoiId  第一个 long 参数
     * @param noticeId 第二个 long 参数
     * @param extraStr 第三个 String 参数
     * @return 32 位十六进制 md5 字符串（小写）
     */
    public static String md5OfCombined(long wmPoiId, long noticeId, String extraStr) {
        // 1️⃣ 先把两个 long 做求和
        long sum = wmPoiId + noticeId;

        // 2️⃣ 再把求和结果和字符串拼接在一起（这里采用 StringBuilder，防止产生临时的中间对象）
        StringBuilder sb = new StringBuilder();
        sb.append(sum);           // 把数值转成十进制字符串再拼接
        sb.append(extraStr);      // 再拼接传入的字符串

        // 3️⃣ 计算 MD5
        byte[] md5Bytes = md5(sb.toString());

        // 4️⃣ 把二进制结果转成十六进制字符串返回
        return bytesToHex(md5Bytes);
    }

    /**
     * 计算字符串的 MD5（返回原始字节数组）
     */
    private static byte[] md5(String data) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            // 使用 UTF-8 编码将字符串转成字节数组
            return md.digest(data.getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException e) {
            // MD5 在所有标准 JDK 中必定存在，这里仅做兜底
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    /**
     * 把字节数组转成十六进制字符串（常用的 32 位小写形式）
     */
    private static String bytesToHex(byte[] bytes) {
        // 每个字节占两个十六进制字符，总长度 2 * bytes.length
        char[] hexArray = "0123456789abcdef".toCharArray();
        char[] hexChars = new char[bytes.length * 2];
        for (int j = 0; j < bytes.length; j++) {
            int v = bytes[j] & 0xFF;          // 取低 8 位
            hexChars[j * 2] = hexArray[v >>> 4];    // 高 4 位
            hexChars[j * 2 + 1] = hexArray[v & 0x0F]; // 低 4 位
        }
        return new String(hexChars);
    }

    // -------------------   测试 Demo   -------------------
    public static void main(String[] args) {
        long wmPoiId = 123456789012345L;
        long noticeId = 98765432109876L;
        String extra = "HelloWorld";

        String md5 = md5OfCombined(wmPoiId, noticeId, extra);
        System.out.println("MD5 = " + md5);
        // 示例输出（仅供参考，实际值随输入不同而变化）
        // MD5 = 4e3c0f1a4b1c5e9e1d4a2e5c4f0b9d3a
    }
}
