package com.example.service;

import com.example.model.Task;
import com.example.model.Status;

import java.io.IOException;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Сервис, отвечающий за бизнес‑логику и хранение задач в файле.
 */
public class TaskService {

    private static final DateTimeFormatter DTF = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    private static final String DELIMITER = "│";          // символ «разделитель», почти наверняка не встречается в тексте
    private final Path storageFile;

    /** Список задач в памяти */
    private final List<Task> tasks = new ArrayList<>();

    public TaskService(Path storageFile) {
        this.storageFile = storageFile;
        load(); // попытаемся загрузить данные при старте
    }

    /* ---------- CRUD ---------- */

    public Task addTask(String title, String description) {
        var task = Task.create(title, description);
        tasks.add(task);
        save();
        return task;
    }

    public List<Task> listAll() {
        // возвращаем копию, чтобы UI не мог изменить внутренний список напрямую
        return new ArrayList<>(tasks);
    }

    public Optional<Task> findById(UUID id) {
        return tasks.stream()
                .filter(t -> t.id().equals(id))
                .findFirst();
    }

    public boolean deleteTask(UUID id) {
        boolean removed = tasks.removeIf(t -> t.id().equals(id));
        if (removed) save();
        return removed;
    }

    public Optional<Task> updateStatus(UUID id, Status newStatus) {
        var opt = findById(id);
        opt.ifPresent(old -> {
            var updated = old.withStatus(newStatus);
            replace(old, updated);
            save();
        });
        return opt.map(t -> t.withStatus(newStatus));
    }

    public Optional<Task> editTask(UUID id, String newTitle, String newDescription) {
        var opt = findById(id);
        opt.ifPresent(old -> {
            var updated = old.withTitleAndDescription(newTitle, newDescription);
            replace(old, updated);
            save();
        });
        return opt.map(t -> t.withTitleAndDescription(newTitle, newDescription));
    }

    private void replace(Task oldTask, Task newTask) {
        int idx = tasks.indexOf(oldTask);
        if (idx >= 0) {
            tasks.set(idx, newTask);
        }
    }

    /* ---------- ПERSISTENCE ---------- */

    private void load() {
        if (!Files.exists(storageFile)) {
            // файл ещё не существует – ничего не грузим
            return;
        }

        try {
            List<String> lines = Files.readAllLines(storageFile);
            for (String line : lines) {
                // Формат: id│title│description│status│createdAt│updatedAt
                String[] parts = line.split(DELIMITER, -1);
                if (parts.length != 6) continue; // защищаем от повреждённого файла

                var task = new Task(
                        UUID.fromString(parts[0]),
                        parts[1],
                        parts[2],
                        Status.fromString(parts[3]),
                        LocalDateTime.parse(parts[4], DTF),
                        LocalDateTime.parse(parts[5], DTF)
                );
                tasks.add(task);
            }
        } catch (IOException e) {
            System.err.println("⚠️ Не удалось загрузить задачи: " + e.getMessage());
        }
    }

    private void save() {
        // Сериализуем каждую задачу в одну строку
        List<String> lines = tasks.stream()
                .map(t -> String.join(DELIMITER,
                        t.id().toString(),
                        t.title(),
                        t.description(),
                        t.status().name(),
                        t.createdAt().format(DTF),
                        t.updatedAt().format(DTF)))
                .collect(Collectors.toList());

        try {
            Files.createDirectories(storageFile.getParent());
            Files.write(storageFile, lines, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        } catch (IOException e) {
            System.err.println("⚠️ Не удалось сохранить задачи: " + e.getMessage());
        }
    }
}
