```java
package com.example;

import com.example.model.Task;
import com.example.model.Status;
import com.example.service.TaskService;

import java.nio.file.Path;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Scanner;
import java.util.UUID;

/**
 * Точка входа: простое текстовое меню.
 */
public class Main {

    private static final Scanner SC = new Scanner(System.in);
    private static final DateTimeFormatter DISP_FMT = DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm");
    private static final TaskService service = new TaskService(Path.of("data", "tasks.txt"));

    public static void main(String[] args) {
        System.out.println("🗒️  Task Manager – 2024 edition");
        while (true) {
            printMenu();
            String choice = SC.nextLine().trim();
            switch (choice) {
                case "1" -> listTasks();
                case "2" -> addTask();
                case "3" -> editTask();
                case "4" -> changeStatus();
                case "5" -> deleteTask();
                case "0" -> {
                    System.out.println("👋  Пока!");
                    return;
                }
                default -> System.out.println("❓ Неизвестный пункт, попробуйте снова.");
            }
        }
    }

    private static void printMenu() {
        System.out.println("\n=== Меню ===");
        System.out.println("1 – Показать все задачи");
        System.out.println("2 – Добавить задачу");
        System.out.println("3 – Редактировать задачу");
        System.out.println("4 – Сменить статус");
        System.out.println("5 – Удалить задачу");
        System.out.println("0 – Выход");
        System.out.print("Выбор: ");
    }

    private static void listTasks() {
        List<Task> tasks = service.listAll();
        if (tasks.isEmpty()) {
            System.out.println("🚫 Нет задач.");
            return;
        }
        System.out.println("\n📋 Список задач:");
        for (Task t : tasks) {
            System.out.printf("""
                    ID: %s
                    Заголовок: %s
                    Описание : %s
                    Статус   : %s
                    Создано : %s
                    Обновлено: %s
                    ----------------------------
                    """,
                    t.id(),
                    t.title(),
                    t.description(),
                    t.status(),
                    t.createdAt().format(DISP_FMT),
                    t.updatedAt().format(DISP_FMT));
        }
    }

    private static void addTask() {
        System.out.print("Введите заголовок: ");
        String title = SC.nextLine().trim();
        System.out.print("Введите описание (можно оставить пустым): ");
        String desc = SC.nextLine().trim();

        Task task = service.addTask(title, desc);
        System.out.println("✅ Добавлена задача с ID " + task.id());
    }

    private static void editTask() {
        UUID id = askId();
        if (id == null) return;

        System.out.print("Новый заголовок (оставьте пустым, чтобы не менять): ");
        String newTitle = SC.nextLine().trim();
        System.out.print("Новое описание (оставьте пустым, чтобы не менять): ");
        String newDesc = SC.nextLine().trim();

        service.findById(id).ifPresentOrElse(
                old -> {
                    String title = newTitle.isEmpty() ? old.title() : newTitle;
                    String desc  = newDesc.isEmpty() ? old.description() : newDesc;
                    service.editTask(id, title, desc);
                    System.out.println("✅ Задача обновлена.");
                },
                () -> System.out.println("❌ Задача с таким ID не найдена.")
        );
    }

    private static void changeStatus() {
        UUID id = askId();
        if (id == null) return;

        System.out.println("Возможные статусы:");
        for (Status s : Status.values()) {
            System.out.println("- " + s);
        }
        System.out.print("Введите новый статус: ");
        String txt = SC.nextLine().trim();

        try {
            Status newStatus = Status.fromString(txt);
            service.updateStatus(id, newStatus);
            System.out.println("✅ Статус обновлён.");
        } catch (IllegalArgumentException e) {
            System.out.println("❌ Некорректный статус.");
        }
    }

    private static void deleteTask() {
        UUID id = askId();
        if (id == null) return;

        boolean removed = service.deleteTask(id);
        System.out.println(removed ? "🗑️  Задача удалена." : "❌ Задача не найдена.");
    }

    /** Утилита: запросить у пользователя UUID задачи */
    private static UUID askId() {
        System.out.print("Введите ID задачи (UUID): ");
        String s = SC.nextLine().trim();
        try {
            return UUID.fromString(s);
        } catch (IllegalArgumentException e) {
            System.out.println("❌ Некорректный UUID.");
            return null;
        }
    }
}
