## 1️⃣  Parallel Dense Matrix Multiplication  

### 1.1  Java version (`MatrixMul.java`)

```java
import java.util.concurrent.*;
import java.util.*;
import java.io.*;

public class MatrixMul {

    /* ------------------- PARAMETERS ------------------- */
    // Size of the square matrices (feel free to change)
    static final int N = 2048;   // 2048×2048 → ~32 MiB double data

    // Number of repetitions → average out jitter
    static final int REPEAT = 5;

    // Thread counts we will test
    static final int[] THREADS = {1,2,4,6,8,10,12,14,16};

    /* --------------------------------------------------- */

    // Simple matrix generator (deterministic for reproducibility)
    private static double[][] randomMatrix(int n) {
        double[][] m = new double[n][n];
        Random rng = new Random(0xDEADBEEF);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                m[i][j] = rng.nextDouble();
        return m;
    }

    /** Multiply A·B → C using `numThreads` rows per task. */
    private static void multiply(double[][] A, double[][] B, double[][] C,
                                 int numThreads) throws InterruptedException {

        ExecutorService pool = Executors.newFixedThreadPool(numThreads);
        int rowsPerTask = (N + numThreads - 1) / numThreads;   // ceiling

        List<Future<?>> futures = new ArrayList<>();

        for (int start = 0; start < N; start += rowsPerTask) {
            final int r0 = start;
            final int r1 = Math.min(start + rowsPerTask, N);
            futures.add(pool.submit(() -> {
                for (int i = r0; i < r1; ++i) {
                    double[] aRow = A[i];
                    double[] cRow = C[i];
                    for (int j = 0; j < N; ++j) {
                        double sum = 0.0;
                        for (int k = 0; k < N; ++k) {
                            sum += aRow[k] * B[k][j];
                        }
                        cRow[j] = sum;
                    }
                }
            }));
        }

        // wait for everything
        for (Future<?> f : futures) f.get();   // propagates exceptions
        pool.shutdown();
    }

    /** Helper: wall‑clock in seconds using System.nanoTime(). */
    private static double nowSec() {
        return System.nanoTime() * 1e-9;
    }

    public static void main(String[] args) throws Exception {
        double[][] A = randomMatrix(N);
        double[][] B = randomMatrix(N);
        double[][] C = new double[N][N];   // result buffer (re‑used)

        System.out.println("size,threads,sec, speedup");
        double baseline = -1.0;

        for (int t : THREADS) {
            // Warm‑up run (to trigger JIT, page‑faults, etc.)
            multiply(A, B, C, t);
            // -----------------------------------------------------------------
            double best = Double.MAX_VALUE;
            for (int rep = 0; rep < REPEAT; ++rep) {
                // reset result buffer (not strictly needed for timing)
                for (int i = 0; i < N; ++i) Arrays.fill(C[i], 0.0);
                double start = nowSec();
                multiply(A, B, C, t);
                double elapsed = nowSec() - start;
                best = Math.min(best, elapsed);
            }
            // -----------------------------------------------------------------
            if (baseline < 0) baseline = best;           // 1‑thread time
            double speedup = baseline / best;
            System.out.printf("%d,%d,%.4f,%.3f%n", N, t, best, speedup);
        }
    }
}
```

#### How to compile / run

```bash
# Compile
javac MatrixMul.java

# Run (will print CSV on stdout)
java -Xms4g -Xmx4g MatrixMul > matrix_mul.csv
```

*We give the JVM a generous heap (`-Xmx4g`) so that a 2048×2048 double matrix (~32 MiB) fits comfortably together with all thread stacks.*

