### 1.2  C++ version (`matrix_mul.cpp`)

```cpp
/********************************************************************
 *  Parallel dense matrix multiplication (C = A × B)
 *
 *  Build   : g++ -O3 -std=c++17 -march=native -pthread matrix_mul.cpp -o matrix_mul
 *  Run     : ./matrix_mul > matrix_mul.csv
 *
 *  Output format (CSV):
 *      size,threads,sec,speedup
 ********************************************************************/

#include <iostream>
#include <vector>
#include <random>
#include <thread>
#include <future>
#include <chrono>
#include <sys/time.h>
#include <iomanip>
#include <algorithm>

constexpr int N = 2048;           // matrix dimension
constexpr int REPEAT = 5;         // repetitions for timing
constexpr int THREADS[] = {1,2,4,6,8,10,12,14,16};

using matrix = std::vector<std::vector<double>>;

/* ------------------------------------------------------------------ */
matrix random_matrix(int n)
{
    matrix m(n, std::vector<double>(n));
    std::mt19937_64 rng(0xDEADBEEFULL);
    std::uniform_real_distribution<double> dist(0.0, 1.0);
    for (auto &row : m)
        for (auto &x : row)
            x = dist(rng);
    return m;
}

/* ------------------------------------------------------------------ */
double now_sec()
{
    struct timeval tv{};
    gettimeofday(&tv, nullptr);
    return tv.tv_sec + tv.tv_usec * 1e-6;
}

/* ------------------------------------------------------------------ */
/* Multiply A·B → C using `num_threads`.  Work is split by rows.       */
void multiply(const matrix &A, const matrix &B, matrix &C, int num_threads)
{
    std::vector<std::future<void>> workers;
    int rows_per_task = (N + num_threads - 1) / num_threads;  // ceil

    for (int start = 0; start < N; start += rows_per_task) {
        int r0 = start;
        int r1 = std::min(start + rows_per_task, N);
        workers.emplace_back(
            std::async(std::launch::async,
                [&A,&B,&C,r0,r1](){
                    for (int i = r0; i < r1; ++i) {
                        const auto &aRow = A[i];
                        auto &cRow = C[i];
                        for (int j = 0; j < N; ++j) {
                            double sum = 0.0;
                            for (int k = 0; k < N; ++k) {
                                sum += aRow[k] * B[k][j];
                            }
                            cRow[j] = sum;
                        }
                    }
                })
        );
    }

    for (auto &f : workers) f.get();   // re‑throw any exception
}

/* ------------------------------------------------------------------ */
int main()
{
    matrix A = random_matrix(N);
    matrix B = random_matrix(N);
    matrix C(N, std::vector<double>(N));

    std::cout << "size,threads,sec,speedup\n";
    double baseline = -1.0;

    for (int num_thr : THREADS) {
        // Warm‑up (JIT not a factor in C++, but caches/page‑faults are)
        multiply(A, B, C, num_thr);

        double best = std::numeric_limits<double>::max();
        for (int rep = 0; rep < REPEAT; ++rep) {
            // reset output matrix (optional)
            for (auto &row : C) std::fill(row.begin(), row.end(), 0.0);
            double t0 = now_sec();
            multiply(A, B, C, num_thr);
            double elapsed = now_sec() - t0;
            best = std::min(best, elapsed);
        }

        if (baseline < 0) baseline = best;
        double speedup = baseline / best;
        std::cout << N << ',' << num_thr << ',' << std::fixed << std::setprecision(4)
                  << best << ',' << std::setprecision(3) << speedup << '\n';
    }
    return 0;
}
```

#### How to compile / run

```bash
g++ -O3 -std=c++17 -march=native -pthread matrix_mul.cpp -o matrix_mul
./matrix_mul > matrix_mul.csv
```

*`-march=native` enables AVX/AVX2 (or AVX‑512 if the processor supports it), which gives you the best possible single‑core throughput. The algorithm itself does **not** use any explicit SIMD intrinsics – the compiler will auto‑vectorize the inner `k` loop.*

