## 2️⃣  Parallel Monte‑Carlo π Estimation  

### 2.1  Java version (`MonteCarloPi.java`)

```java
import java.util.concurrent.*;
import java.util.*;

public class MonteCarloPi {

    // Number of random points generated in total (per repetition)
    static final long TOTAL_SAMPLES = 200_000_000L; // 2·10^8 → ~1 s per thread

    static final int REPEAT = 5;
    static final int[] THREADS = {1,2,4,6,8,10,12,14,16};

    /** Run a single Monte‑Carlo trial using `t` threads. */
    private static double estimatePi(int t) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(t);
        long perThread = TOTAL_SAMPLES / t;
        List<Future<Long>> futures = new ArrayList<>();

        for (int i = 0; i < t; ++i) {
            futures.add(pool.submit(() -> {
                Random rng = new Random(Thread.currentThread().getId() ^ System.nanoTime());
                long inside = 0;
                for (long j = 0; j < perThread; ++j) {
                    double x = rng.nextDouble();
                    double y = rng.nextDouble();
                    if (x * x + y * y <= 1.0) ++inside;
                }
                return inside;
            }));
        }

        long totalInside = 0;
        for (Future<Long> f : futures) totalInside += f.get();
        pool.shutdown();

        double ratio = (double) totalInside / (double) TOTAL_SAMPLES;
        return 4.0 * ratio;
    }

    private static double nowSec() { return System.nanoTime() * 1e-9; }

    public static void main(String[] args) throws Exception {
        System.out.println("samples,threads,sec,speedup,pi_estimate");
        double baseline = -1.0;

        for (int t : THREADS) {
            // Warm‑up
            estimatePi(t);

            double best = Double.MAX_VALUE;
            double piResult = Double.NaN;
            for (int r = 0; r < REPEAT; ++r) {
                double start = nowSec();
                double pi = estimatePi(t);
                double elapsed = nowSec() - start;
                if (elapsed < best) {
                    best = elapsed;
                    piResult = pi;
                }
            }
            if (baseline < 0) baseline = best;
            double speedup = baseline / best;
            System.out.printf("%d,%d,%.4f,%.3f,%.10f%n",
                    TOTAL_SAMPLES, t, best, speedup, piResult);
        }
    }
}
```

Compile & run exactly as before:

```bash
javac MonteCarloPi.java
java -Xmx2g MonteCarloPi > monte_carlo_pi.csv
```

