### 2.2  C++ version (`monte_carlo_pi.cpp`)

```cpp
/********************************************************************
 *  Parallel Monte‑Carlo π estimation.
 *
 *  Build   : g++ -O3 -std=c++17 -march=native -pthread monte_carlo_pi.cpp -o monte_carlo_pi
 *  Run     : ./monte_carlo_pi > monte_carlo_pi.csv
 *
 *  CSV columns: samples,threads,sec,speedup,pi_estimate
 ********************************************************************/

#include <iostream>
#include <vector>
#include <random>
#include <future>
#include <chrono>
#include <sys/time.h>
#include <iomanip>
#include <algorithm>

constexpr long long TOTAL_SAMPLES = 200'000'000LL;   // 2e8
constexpr int REPEAT = 5;
constexpr int THREADS[] = {1,2,4,6,8,10,12,14,16};

double now_sec()
{
    struct timeval tv{};
    gettimeofday(&tv, nullptr);
    return tv.tv_sec + tv.tv_usec * 1e-6;
}

/* ------------------------------------------------------------------ */
double monte_carlo_pi(int num_threads)
{
    long long per_thread = TOTAL_SAMPLES / num_threads;
    std::vector<std::future<long long>> workers;

    for (int i = 0; i < num_threads; ++i) {
        workers.emplace_back(
            std::async(std::launch::async,
                [per_thread]() -> long long {
                    std::mt19937_64 rng(
                       std::chrono::high_resolution_clock::now().time_since_epoch().count()
                       ^ std::hash<std::thread::id>{}(std::this_thread::get_id()));
                    std::uniform_real_distribution<double> dist(0.0, 1.0);
                    long long inside = 0;
                    for (long long j = 0; j < per_thread; ++j) {
                        double x = dist(rng);
                        double y = dist(rng);
                        if (x*x + y*y <= 1.0) ++inside;
                    }
                    return inside;
                })
        );
    }

    long long total_inside = 0;
    for (auto &f : workers) total_inside += f.get();

    double ratio = static_cast<double>(total_inside) / static_cast<double>(TOTAL_SAMPLES);
    return 4.0 * ratio;
}

/* ------------------------------------------------------------------ */
int main()
{
    std::cout << "samples,threads,sec,speedup,pi_estimate\n";
    double baseline = -1.0;

    for (int thr : THREADS) {
        // Warm‑up
        monte_carlo_pi(thr);

        double best = std::numeric_limits<double>::max();
        double pi_val = 0.0;
        for (int r = 0; r < REPEAT; ++r) {
            double t0 = now_sec();
            double pi = monte_carlo_pi(thr);
            double elapsed = now_sec() - t0;
            if (elapsed < best) {
                best = elapsed;
                pi_val = pi;
            }
        }

        if (baseline < 0) baseline = best;
        double speedup = baseline / best;

        std::cout << TOTAL_SAMPLES << ',' << thr << ','
                  << std::fixed << std::setprecision(4) << best << ','
                  << std::setprecision(3) << speedup << ','
                  << std::setprecision(10) << pi_val << '\n';
    }
    return 0;
}
```

Compile & run:

```bash
g++ -O3 -std=c++17 -march=native -pthread monte_carlo_pi.cpp -o monte_carlo_pi
./monte_carlo_pi > monte_carlo_pi.csv
```

