## 3. 解码器封装（JavaCV + FFmpeg）

### 3.1 为什么不直接使用 `FFmpegFrameGrabber`？

`FFmpegFrameGrabber` 的典型用法是：

```java
FFmpegFrameGrabber grabber = new FFmpegFrameGrabber("rtsp://....");
grabber.start();
```

它会 **自行打开网络流**、**解析容器**（如 RTSP、MP4），但在我们这里 **已经自己把码流切分好**，只想直接喂 **裸 H.264 NALU**，这时候需要更底层的 API——**`avcodec`**。

### 3.2 直接使用 `avcodec`（码流解码）

下面封装一个 **`H264Decoder`** 类，它内部维护：

- `AVCodecContext`（解码器上下文）  
- `AVPacket`（输入）  
- `AVFrame`（解码后原始 YUV）  
- `SwsContext`（YUV → RGB 转换）  

```java
import org.bytedeco.ffmpeg.avcodec.AVCodec;
import org.bytedeco.ffmpeg.avcodec.AVCodecContext;
import org.bytedeco.ffmpeg.avcodec.AVPacket;
import org.bytedeco.ffmpeg.avutil.AVFrame;
import org.bytedeco.ffmpeg.global.avcodec;
import org.bytedeco.ffmpeg.global.avutil;
import org.bytedeco.ffmpeg.global.swscale;
import org.bytedeco.ffmpeg.swscale.SwsContext;
import org.bytedeco.javacv.Frame;
import org.bytedeco.javacv.OpenCVFrameConverter;

import java.awt.image.BufferedImage;
import java.nio.ByteBuffer;

import static org.bytedeco.ffmpeg.global.avutil.*;

/**
 * H.264 裸码流（Annex‑B）解码器。
 *
 * 使用方式：
 *   H264Decoder decoder = new H264Decoder();
 *   decoder.open();
 *   BufferedImage img = decoder.decode(naluBytes);
 *   decoder.close();
 */
public class H264Decoder implements AutoCloseable {

    private AVCodec codec;
    private AVCodecContext codecCtx;
    private AVPacket packet;
    private AVFrame frameYUV;          // 解码得到的 YUV420P 帧
    private AVFrame frameRGB;          // 转成 BGR24（Java BufferedImage 使用的色彩顺序）

    private SwsContext swsCtx;         // 颜色空间转换上下文

    public H264Decoder() {
        // 初始化 FFmpeg
        avcodec.avcodec_register_all(); // (新版 FFmpeg 可不必显式调用)
    }

    /** 打开解码器（准备内部结构） */
    public void open() throws Exception {
        codec = avcodec.avcodec_find_decoder(avcodec.AV_CODEC_ID_H264);
        if (codec == null) {
            throw new IllegalStateException("H.264 decoder not found");
        }

        codecCtx = avcodec.avcodec_alloc_context3(codec);
        if (codecCtx == null) {
            throw new IllegalStateException("Could not allocate AVCodecContext");
        }

        // 设置解码参数（可根据业务需要调节）
        codecCtx.width(1920);   // 可不必设置，FFmpeg 会在 SPS 中自动更新
        codecCtx.height(1080);
        codecCtx.pix_fmt(AV_PIX_FMT_YUV420P);
        codecCtx.time_base().num(1).den(25); // 假设 25 fps，可随意

        // 为了让 decoder 能够接受 “Annex‑B” 包 (start‑code 0x000001)，
        // 设置 `AV_CODEC_FLAG2_CHUNKS`，让它把每一次的 packet 当成完整 NALU 处理。
        codecCtx.flags2(avcodec.AV_CODEC_FLAG2_CHUNKS);

        if (avcodec.avcodec_open2(codecCtx, codec, (org.bytedeco.ffmpeg.avutil.AVDictionary) null) < 0) {
            throw new IllegalStateException("Failed to open H.264 decoder");
        }

        packet = avcodec.av_packet_alloc();
        frameYUV = avutil.av_frame_alloc();
        frameRGB = avutil.av_frame_alloc();

        // 为 RGB 帧分配 buffer（后面用 sws_scale 转换）
        // 我们使用 BGR24（每个像素 3 字节），因为 Java BufferedImage 支持 TYPE_3BYTE_BGR
        int bufferSize = avutil.av_image_get_buffer_size(AV_PIX_FMT_BGR24,
                codecCtx.width(), codecCtx.height(), 1);
        BytePointer buffer = new BytePointer(avutil.av_malloc(bufferSize));
        avutil.av_image_fill_arrays(frameRGB.data(), frameRGB.linesize(),
                buffer, AV_PIX_FMT_BGR24,
                codecCtx.width(), codecCtx.height(), 1);
    }

    /**
     * 把一帧 NALU（裸码流）解码为 BufferedImage。
     *
     * @param nalBytes 单个完整的 NALU（包含 start‑code 或长度前缀都可以，只要是完整的数据）
     * @return BufferedImage（BGR）或者 null（当前 NALU 不产生可视帧，如 SPS/PPS、空帧等）
     */
    public BufferedImage decode(byte[] nalBytes) throws Exception {
        // 1️⃣ 把数据放进 AVPacket
        avcodec.av_packet_unref(packet); // 清空旧数据
        avcodec.av_init_packet(packet);
        packet.data(new BytePointer(nalBytes));
        packet.size(nalBytes.length);

        // 2️⃣ 调用解码（发送 + 接收）
        // ffmpeg 4+ 的新 API 推荐使用 avcodec_send_packet / avcodec_receive_frame
        int ret = avcodec.avcodec_send_packet(codecCtx, packet);
        if (ret < 0) {
            // 常见错误是 “Invalid data” → 可能是 SPS/PPS，直接返回 null
            // 也可能是缓冲区满（EAGAIN），但这里我们每次只送一帧，忽略
            return null;
        }

        // 读取所有可用的 frame（在 B‑frame 的情况下，一个 packet 可能产生多帧）
        while ((ret = avcodec.avcodec_receive_frame(codecCtx, frameYUV)) == 0) {
            // 3️⃣ YUV → BGR
            if (swsCtx == null) {
                // 第一次创建 swsContext，随后复用
                swsCtx = swscale.sws_getContext(
                        codecCtx.width(), codecCtx.height(), codecCtx.pix_fmt(),
                        codecCtx.width(), codecCtx.height(), AV_PIX_FMT_BGR24,
                        swscale.SWS_BILINEAR, null, null, (DoublePointer) null);
            }
            swscale.sws_scale(swsCtx,
                    frameYUV.data(), frameYUV.linesize(),
                    0, codecCtx.height(),
                    frameRGB.data(), frameRGB.linesize());

            // 4️⃣ 把 frameRGB 转成 BufferedImage
            BufferedImage img = avFrameToBufferedImage(frameRGB, codecCtx.width(), codecCtx.height());
            // 如果需要继续读取后面可能的帧，这里直接返回第一帧（大多数实时流每个 NALU 只产生一帧）。
            return img;
        }

        // 如果返回的不是 AVERROR_EOF、AVERROR(EAGAIN) 之外的错误，这里可以打印
        if (ret != avutil.AVERROR_EAGAIN() && ret != avutil.AVERROR_EOF()) {
            System.err.println("avcodec_receive_frame error: " + ret);
        }
        return null;
    }

    /** 把已经是 BGR24 的 AVFrame 直接包装成 BufferedImage（不拷贝） */
    private static BufferedImage avFrameToBufferedImage(AVFrame frame, int width, int height) {
        // BGR24 对应 Java 的 TYPE_3BYTE_BGR（3 bytes 每像素）
        // 这里直接使用底层 BytePointer 的 buffer，创建不拷贝的 BufferedImage
        // 注意：返回的 BufferedImage **共享** native buffer，务必在使用完后不要再释放 AVFrame。
        BytePointer data = frame.data(0);
        int stride = frame.linesize(0); // 一行实际占用的字节数（可能 > width*3 ）

        // 创建 DataBuffer 并包装
        DataBufferByte db = new DataBufferByte(data.getStringBytes(0, stride * height), stride * height);
        // SampleModel：每像素 3 byte，BGR 顺序
        SampleModel sm = new ComponentSampleModel(DataBuffer.TYPE_BYTE,
                width, height, 3, stride, new int[]{2, 1, 0}); // 注意 BGR => {2,1,0}
        // Raster
        WritableRaster raster = Raster.createWritableRaster(sm, db, null);
        // BufferedImage （TYPE_3BYTE_BGR）
        BufferedImage bi = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
        bi.setData(raster);
        return bi;
    }

    /** 关闭所有 native 资源 */
    @Override
    public void close() {
        if (packet != null) avcodec.av_packet_free(packet);
        if (frameYUV != null) avutil.av_frame_free(frameYUV);
        if (frameRGB != null) avutil.av_frame_free(frameRGB);
        if (codecCtx != null) avcodec.avcodec_free_context(codecCtx);
        if (swsCtx != null) swscale.sws_freeContext(swsCtx);
    }
}
```

#### 关键点解读

| 步骤 | 解释 |
|------|------|
| `AV_CODEC_FLAG2_CHUNKS` | 告诉解码器 **每次 `avcodec_send_packet` 只包含完整的 NALU**（而不是容器封装），适用于 **裸 H.264**。 |
| `avcodec_send_packet / avcodec_receive_frame` | FFmpeg 3.0+ 推荐的 **解码管线**（异步），兼容 B‑frame、延迟帧（DPB）等。 |
| `SwsContext` + `sws_scale` | 把 YUV420P → BGR24（Java `BufferedImage` 可直接使用）。如果你想要 **RGB** 或 **GRAY**，只调整 `AV_PIX_FMT_...` 参数。 |
| `BufferedImage` 创建方式 | 通过 `DataBufferByte` **共享**底层 native 缓冲区，避免每帧拷贝，提高帧率。| 
| **多帧** | 某些 NALU（如 `IDR` 大块）可能触发 **多帧**（例如 B‑frame 重排序），我们这里在收到第一帧后直接返回，足够实时显示。若想完整保留所有帧，可把 `while (receive_frame)` 的循环结果放进 **帧队列**。|

> **如果你想把解码过程包装成 `javax.swing.Timer` 或 `java.util.concurrent` 的生产者‑消费者**，只需要把 `decode` 方法放在一个后台线程中，然后把 `BufferedImage` 丢到 **阻塞队列**（例如 `LinkedBlockingQueue<BufferedImage>`），渲染线程从队列里弹出即可。

