package com.ecom.chat;

import java.io.Serializable;

/**
 * 所有在 Socket 上传输的对象都使用这个类。
 * 采用 Serializable 方式，简化协议实现。
 */
public class Message implements Serializable {

    private static final long serialVersionUID = 1L;

    /** 消息的种类 */
    private MessageType type;

    /** 发送方标识（用户ID、客服ID） */
    private String from;

    /** 接收方标识（客服ID、用户ID） */
    private String to;

    /** 文本内容（若是 TEXT、SYSTEM 类型） */
    private String text;

    /** 文件名（若是 IMAGE、FILE 类型） */
    private String fileName;

    /** 文件/图片的字节数组（若是 IMAGE、FILE 类型） */
    private byte[] fileData;

    /** 构造函数 */
    public Message(MessageType type, String from, String to) {
        this.type = type;
        this.from = from;
        this.to   = to;
    }

    /* ---------- getter / setter ---------- */
    public MessageType getType()   { return type; }
    public void setType(MessageType t) { this.type = t; }

    public String getFrom() { return from; }
    public String getTo()   { return to; }

    public String getText() { return text; }
    public void setText(String txt) { this.text = txt; }

    public String getFileName() { return fileName; }
    public void setFileName(String fn) { this.fileName = fn; }

    public byte[] getFileData() { return fileData; }
    public void setFileData(byte[] data) { this.fileData = data; }

    @Override
    public String toString() {
        return "Message{" +
                "type=" + type +
                ", from='" + from + '\'' +
                ", to='" + to + '\'' +
                ", text='" + text + '\'' +
                ", fileName='" + fileName + '\'' +
                '}';
    }
}
```

### 说明
* `MessageType`（后面定义）告诉接收端如何解释该对象。  
* 对于文字消息，只需要 `type = TEXT`、`text` 字段即可。  
* 对于图片/文件，使用 `fileName` + `fileData`（二进制）。  
* `from / to` 用来区分不同会话（尤其在客服端同时服务多个用户时必不可少）。

