package com.ecom.chat;

import java.io.*;
import java.nio.charset.StandardCharsets;

/**
 * 简单的文件读写工具，使用 UTF‑8 文本保存聊天记录。
 * 每一行记录的格式示例：
 *   [2023-09-01 13:45:12] USER: Hello, 我想咨询……
 *   [2023-09-01 13:45:45] CS: 您好，请问有什么可以帮助您？
 *
 * 为了演示，这里不保存图片/文件的二进制，只记录文件名。
 */
public class ChatUtils {

    /** 保存聊天记录（追加写入） */
    public static synchronized void appendLog(String userId, String line) {
        File f = new File("chat_" + userId + ".log");
        try (Writer w = new BufferedWriter(new OutputStreamWriter(
                new FileOutputStream(f, true), StandardCharsets.UTF_8))) {
            w.write(line + System.lineSeparator());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 读取完整聊天记录（返回所有行） */
    public static synchronized String loadLog(String userId) {
        File f = new File("chat_" + userId + ".log");
        if (!f.exists()) return "";
        StringBuilder sb = new StringBuilder();
        try (BufferedReader r = new BufferedReader(new InputStreamReader(
                new FileInputStream(f), StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                sb.append(line).append('\n');
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return sb.toString();
    }

    /** 生成时间戳字符串 */
    public static String timestamp() {
        return java.time.LocalDateTime.now()
                .format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
    }
}
