### 4.2 ServerUI.java – 客服端 Swing 界面

```java
package com.ecom.chat;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.Map;

/**
 * 客服端主窗口。
 * 左侧列出已接入的用户，每个用户对应一个独立的聊天 Tab。
 * 新用户请求时会弹出对话框询问是否接受。
 *
 * 为了简化代码，这里使用 JTabbedPane 来组织多用户会话。
 */
public class ServerUI extends JFrame {

    /** 用于在不同线程之间发送消息的全局队列（静态） */
    private static final Map<String, Server.ClientHandler> sessions = 
            new java.util.concurrent.ConcurrentHashMap<>();

    /** 主标签页容器，动态添加/删除 tab */
    private final JTabbedPane tabbedPane = new JTabbedPane();

    /** 保存用户 ID → 聊天面板的映射，便于后续查找 */
    private final Map<String, ChatPanel> chatPanels = 
            new java.util.HashMap<>();

    /** 构造函数 */
    public ServerUI(Map<String, Server.ClientHandler> activeSessions) {
        setTitle("客服端（Customer Service）");
        setSize(800, 600);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        add(tabbedPane, BorderLayout.CENTER);
    }

    /** 显示窗口 */
    public void showUI() {   // 避免与 JFrame.show() 冲突
        SwingUtilities.invokeLater(() -> setVisible(true));
    }

    /** 弹出“是否接受用户”对话框（阻塞式） */
    public boolean askAcceptUser(String userId) {
        final boolean[] answer = new boolean[1];
        try {
            SwingUtilities.invokeAndWait(() -> {
                int opt = JOptionPane.showConfirmDialog(
                        ServerUI.this,
                        "有新用户请求聊天，用户ID：" + userId + "\n是否接收？",
                        "新请求",
                        JOptionPane.YES_NO_OPTION);
                answer[0] = (opt == JOptionPane.YES_OPTION);
            });
        } catch (Exception e) {
            e.printStackTrace();
            answer[0] = false;
        }
        return answer[0];
    }

    /** 为新接入的用户创建一个 Tab 并关联会话处理器 */
    public void addUserTab(String userId, Server.ClientHandler handler) {
        SwingUtilities.invokeLater(() -> {
            ChatPanel panel = new ChatPanel(userId, handler);
            tabbedPane.addTab(userId, panel);
            chatPanels.put(userId, panel);
            // 加载历史记录
            String history = ChatUtils.loadLog(userId);
            panel.appendLog(history);
            // 自动切换到新建的 Tab
            tabbedPane.setSelectedComponent(panel);
        });
    }

    /** 移除用户 Tab（在会话结束或异常时调用） */
    public void removeUserTab(String userId) {
        SwingUtilities.invokeLater(() -> {
            ChatPanel panel = chatPanels.remove(userId);
            if (panel != null) {
                tabbedPane.remove(panel);
            }
        });
    }

    /** 从任何线程分发收到的消息到对应的聊天面板 */
    public static void dispatchMessage(String userId, Message msg) {
        SwingUtilities.invokeLater(() -> {
            ChatPanel panel = null;
            // 这里使用一个简化的全局映射（实际项目中可通过观察者模式）
            for (Component c : ((ServerUI) SwingUtilities.getWindowAncestor(
                    SwingUtilities.getRootPane(new JPanel()))).tabbedPane.getComponents()) {
                if (c instanceof ChatPanel && ((ChatPanel) c).getUserId().equals(userId)) {
                    panel = (ChatPanel) c;
                    break;
                }
            }
            if (panel != null) {
                panel.receiveMessage(msg);
            }
        });
    }

    /* ------------------- 内部类：每个用户的聊天面板 ------------------- */
    private static class ChatPanel extends JPanel {
        private final String userId;
        private final Server.ClientHandler handler;
        private final JTextArea textArea = new JTextArea();
        private final JTextField inputField = new JTextField();
        private final JButton sendBtn = new JButton("发送");
        private final JButton sendFileBtn = new JButton("发送文件/图片");

        ChatPanel(String userId, Server.ClientHandler handler) {
            this.userId = userId;
            this.handler = handler;
            setLayout(new BorderLayout());

            textArea.setEditable(false);
            textArea.setLineWrap(true);
            textArea.setWrapStyleWord(true);
            JScrollPane scroll = new JScrollPane(textArea);
            add(scroll, BorderLayout.CENTER);

            JPanel bottom = new JPanel(new BorderLayout(5, 5));
            bottom.add(inputField, BorderLayout.CENTER);
            JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
            btnPanel.add(sendFileBtn);
            btnPanel.add(sendBtn);
            bottom.add(btnPanel, BorderLayout.EAST);
            add(bottom, BorderLayout.SOUTH);

            // 发送文字
            sendBtn.addActionListener(e -> sendText());

            // 回车键也可以发送
            inputField.addActionListener(e -> sendText());

            // 发送文件/图片
            sendFileBtn.addActionListener(e -> sendFileOrImage());
        }

        public String getUserId() { return userId; }

        /** 追加日志（历史记录） */
        public void appendLog(String txt) {
            textArea.append(txt);
        }

        /** 将收到的 Message 转为可读的文字并显示 */
        public void receiveMessage(Message msg) {
            String prefix = "[" + ChatUtils.timestamp() + "] USER: ";
            switch (msg.getType()) {
                case TEXT:
                    textArea.append(prefix + msg.getText() + "\n");
                    break;
                case IMAGE:
                    textArea.append(prefix + "[图片] " + msg.getFileName() + "\n");
                    // 展示图片（弹出一个大图框）
                    showImage(msg);
                    break;
                case FILE:
                    textArea.append(prefix + "[文件] " + msg.getFileName() + "\n");
                    // 可在这里提供“保存”按钮，省略实现细节
                    break;
                default:
                    textArea.append(prefix + "[未知消息]\n");
            }
            // 自动滚动到最底部
            textArea.setCaretPosition(textArea.getDocument().getLength());
        }

        /** 发送文字消息 */
        private void sendText() {
            String txt = inputField.getText().trim();
            if (txt.isEmpty()) return;
            Message msg = new Message(MessageType.TEXT, "CS", userId);
            msg.setText(txt);
            handler.send(msg);
            // 在本地 UI 中同步显示（模拟客服自己的发言）
            textArea.append("[" + ChatUtils.timestamp() + "] CS: " + txt + "\n");
            inputField.setText("");
        }

        /** 发送文件或图片 */
        private void sendFileOrImage() {
            JFileChooser chooser = new JFileChooser();
            chooser.setFileSelectionMode(JFileChooser.FILES_ONLY);
            int ret = chooser.showOpenDialog(this);
            if (ret != JFileChooser.APPROVE_OPTION) return;
            java.io.File file = chooser.getSelectedFile();
            try {
                byte[] data = java.nio.file.Files.readAllBytes(file.toPath());
                MessageType type = isImageFile(file) ? MessageType.IMAGE : MessageType.FILE;
                Message msg = new Message(type, "CS", userId);
                msg.setFileName(file.getName());
                msg.setFileData(data);
                handler.send(msg);
                // 本地 UI 同步显示
                String label = (type == MessageType.IMAGE) ? "[图片]" : "[文件]";
                textArea.append("[" + ChatUtils.timestamp() + "] CS: " + label + " " + file.getName() + "\n");
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(this, "发送失败：" + ex.getMessage());
            }
        }

        /** 简单判断是否为图片文件（后缀） */
        private boolean isImageFile(java.io.File f) {
            String name = f.getName().toLowerCase();
            return name.endsWith(".png") || name.endsWith(".jpg") ||
                    name.endsWith(".jpeg") || name.endsWith(".gif") || name.endsWith(".bmp");
        }

        /** 展示收到的图片（弹出对话框） */
        private void showImage(Message imgMsg) {
            if (imgMsg.getFileData() == null) return;
            ImageIcon icon = new ImageIcon(imgMsg.getFileData());
            JLabel label = new JLabel(icon);
            JScrollPane sp = new JScrollPane(label);
            sp.setPreferredSize(new Dimension(400, 300));
            JOptionPane.showMessageDialog(this, sp, imgMsg.getFileName(), JOptionPane.PLAIN_MESSAGE);
        }
    }
}
```

### 说明
* **askAcceptUser**：使用 `SwingUtilities.invokeAndWait` 在 UI 线程弹出对话框，阻塞后返回客服的选择。  
* **addUserTab / removeUserTab**：动态在 `JTabbedPane` 中增删 Tab，每个 Tab 用 `ChatPanel` 表示一个用户的会话。  
* **ChatPanel**：内部负责发送文字、图片/文件，显示收到的消息，自动滚动，保存日志（通过 `handler.send`）。  
* **dispatchMessage**：静态方法，用于在 `ClientHandler`（读取线程）把收到的消息分发到对应的 UI 面板。这里通过遍历 `tabbedPane` 找到对应的 `ChatPanel`（实现上可以更高效，这里为演示简化）。  

