### 5.2 ClientUI.java – 用户端 Swing 界面

```java
package com.ecom.chat;

import javax.swing.*;
import java.awt.*;
import java.io.*;
import java.util.*;
import java.awt.event.*;

/**
 * 用户端聊天窗口。
 * • 左侧显示聊天记录（包括历史）  
 * • 底部提供文字输入框、发送按钮、发送文件/图片按钮  
 * • 接收服务器发送的文字、图片、文件  
 */
public class ClientUI extends JFrame {

    private final String userId;
    private final ObjectOutputStream oos;
    private final ObjectInputStream  ois;

    private final JTextArea textArea = new JTextArea();
    private final JTextField inputField = new JTextField();
    private final JButton sendBtn = new JButton("发送");
    private final JButton sendFileBtn = new JButton("发送文件/图片");

    /** 用于在后台接收服务器消息的线程 */
    private Thread receiveThread;
    private volatile boolean running = true;

    public ClientUI(String userId, ObjectOutputStream oos, ObjectInputStream ois) {
        this.userId = userId;
        this.oos    = oos;
        this.ois    = ois;

        setTitle("用户端 – 您的ID：" + userId);
        setSize(600, 500);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        // ---------- 显示区 ----------
        textArea.setEditable(false);
        textArea.setLineWrap(true);
        textArea.setWrapStyleWord(true);
        JScrollPane scroll = new JScrollPane(textArea);
        add(scroll, BorderLayout.CENTER);

        // ---------- 输入区 ----------
        JPanel bottom = new JPanel(new BorderLayout(5, 5));
        bottom.add(inputField, BorderLayout.CENTER);
        JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        btnPanel.add(sendFileBtn);
        btnPanel.add(sendBtn);
        bottom.add(btnPanel, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        // ---------- 事件监听 ----------
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());
        sendFileBtn.addActionListener(e -> sendFileOrImage());

        // ---------- 加载历史聊天 ----------
        String history = ChatUtils.loadLog(userId);
        if (!history.isEmpty()) {
            textArea.append(history);
        }

        // ---------- 启动接收线程 ----------
        receiveThread = new Thread(this::receiveLoop);
        receiveThread.start();
    }

    public void showUI() {
        SwingUtilities.invokeLater(() -> setVisible(true));
    }

    /** 发送文字 */
    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        Message msg = new Message(MessageType.TEXT, userId, "CS");
        msg.setText(txt);
        try {
            oos.writeObject(msg);
            oos.flush();
            appendSelfMessage(txt);
        } catch (IOException e) {
            showError("发送失败：" + e.getMessage());
        }
        inputField.setText("");
    }

    /** 发送文件或图片 */
    private void sendFileOrImage() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileSelectionMode(JFileChooser.FILES_ONLY);
        int ret = chooser.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        java.io.File f = chooser.getSelectedFile();
        try {
            byte[] data = java.nio.file.Files.readAllBytes(f.toPath());
            MessageType type = isImageFile(f) ? MessageType.IMAGE : MessageType.FILE;
            Message msg = new Message(type, userId, "CS");
            msg.setFileName(f.getName());
            msg.setFileData(data);
            oos.writeObject(msg);
            oos.flush();
            // 本地 UI 同步显示
            String label = (type == MessageType.IMAGE) ? "[图片]" : "[文件]";
            appendSelfMessage(label + " " + f.getName());
        } catch (Exception ex) {
            showError("发送失败：" + ex.getMessage());
        }
    }

    /** 接收服务器消息的循环（在独立线程） */
    private void receiveLoop() {
        try {
            while (running) {
                Message msg = (Message) ois.readObject(); // 阻塞
                SwingUtilities.invokeLater(() -> handleMessage(msg));
            }
        } catch (EOFException eof) {
            // 服务器关闭
            showError("客服已下线，聊天结束。");
        } catch (Exception e) {
            if (running) showError("接收异常：" + e.getMessage());
        } finally {
            closeResources();
        }
    }

    /** 处理收到的各种消息 */
    private void handleMessage(Message msg) {
        String prefix = "[" + ChatUtils.timestamp() + "] CS: ";
        switch (msg.getType()) {
            case TEXT:
                appendChat(prefix + msg.getText() + "\n");
                break;
            case IMAGE:
                appendChat(prefix + "[图片] " + msg.getFileName() + "\n");
                showImage(msg);
                break;
            case FILE:
                appendChat(prefix + "[文件] " + msg.getFileName() + "\n");
                // 可提供“保存到本地”按钮，这里省略
                break;
            case SYSTEM:
                appendChat("[系统] " + msg.getText() + "\n");
                break;
            default:
                appendChat("[未知消息]\n");
        }
    }

    /** 在聊天框中追加本方（用户）发送的文字 */
    private void appendSelfMessage(String txt) {
        String line = "[" + ChatUtils.timestamp() + "] 我: " + txt + "\n";
        appendChat(line);
        // 同时写入本地日志文件
        ChatUtils.appendLog(userId, line);
    }

    /** 常规追加文本并滚动 */
    private void appendChat(String line) {
        textArea.append(line);
        textArea.setCaretPosition(textArea.getDocument().getLength());
        // 同时写入本地日志文件（用户视角）
        ChatUtils.appendLog(userId, line);
    }

    /** 弹出错误对话框 */
    private void showError(String msg) {
        JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE);
    }

    /** 简单判断是否为图片文件 */
    private boolean isImageFile(java.io.File f) {
        String name = f.getName().toLowerCase();
        return name.endsWith(".png") || name.endsWith(".jpg") ||
                name.endsWith(".jpeg") || name.endsWith(".gif") || name.endsWith(".bmp");
    }

    /** 展示收到的图片（弹窗） */
    private void showImage(Message imgMsg) {
        if (imgMsg.getFileData() == null) return;
        ImageIcon icon = new ImageIcon(imgMsg.getFileData());
        JLabel lbl = new JLabel(icon);
        JScrollPane sp = new JScrollPane(lbl);
        sp.setPreferredSize(new Dimension(400, 300));
        JOptionPane.showMessageDialog(this, sp, imgMsg.getFileName(), JOptionPane.PLAIN_MESSAGE);
    }

    /** 关闭网络资源 */
    private void closeResources() {
        running = false;
        try { if (ois != null) ois.close(); } catch (IOException ignored) {}
        try { if (oos != null) oos.close(); } catch (IOException ignored) {}
        try { if (socket != null) socket.close(); } catch (IOException ignored) {}
    }
}
```

### 说明
* **UI 结构** 与客服端相同，都是 `JTextArea + JTextField + Buttons`。  
* **发送文字/文件** 与客服端的实现几乎一样，只是把 `from` 换成用户的 `userId`、`to` 为 `"CS"`。  
* **接收线程** `receiveLoop` 用 `ObjectInputStream` 不断读取 `Message`，并通过 `SwingUtilities.invokeLater` 把 UI 更新交给 EDT。  
* **聊天记录** 使用同一个 `ChatUtils`，文件名基于 `userId`（`chat_<userId>.log`），因此无论是客服端还是用户端都能看到自己的完整日志。  
* **超时机制** 已经在 `Client` 主入口里实现，若 10 秒内收不到 `SERVICE_RESPONSE`，弹出 “客服忙”。  

