### 1️⃣1️⃣ Контроллер аутентификации

```java
package com.example.jwtsecuritydemo.controller;

import com.example.jwtsecuritydemo.model.User;
import com.example.jwtsecuritydemo.payload.*;
import com.example.jwtsecuritydemo.security.JwtUtils;
import com.example.jwtsecuritydemo.service.UserService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final UserService userService;
    private final JwtUtils jwtUtils;

    // ----------------- Регистрация -----------------
    @PostMapping("/register")
    public ResponseEntity<?> registerUser(@Validated @RequestBody RegisterRequest signUpRequest) {

        // Простая проверка на уникальность (можно вынести в сервис)
        if (userService.findByEmail(signUpRequest.getEmail()) != null) {
            return ResponseEntity
                    .badRequest()
                    .body(new MessageResponse("Error: Email is already in use!"));
        }

        User user = userService.registerUser(
                signUpRequest.getUsername(),
                signUpRequest.getEmail(),
                signUpRequest.getPassword());

        return ResponseEntity.ok(new MessageResponse("User registered successfully!"));
    }

    // ----------------- Авторизация -----------------
    @PostMapping("/login")
    public ResponseEntity<?> authenticateUser(@Validated @RequestBody LoginRequest loginRequest) {

        Authentication authentication = authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(
                        loginRequest.getEmail(),
                        loginRequest.getPassword()));

        SecurityContextHolder.getContext().setAuthentication(authentication);
        String jwt = jwtUtils.generateJwtToken(authentication.getPrincipal() instanceof UserDetails
                ? (UserDetails) authentication.getPrincipal()
                : null);

        UserDetails userDetails = (UserDetails) authentication.getPrincipal();
        User user = userService.findByEmail(userDetails.getUsername());

        return ResponseEntity.ok(new JwtResponse(jwt,
                "Bearer",
                user.getId(),
                user.getUsername(),
                user.getEmail()));
    }

    // Простой эндпоинт для проверки
    @GetMapping("/test")
    public ResponseEntity<String> test() {
        return ResponseEntity.ok("Secured endpoint works!");
    }
}
```

