import java.time.LocalDate;   // just a date, no time‑of‑day or zone
import java.time.format.DateTimeFormatter;

public class MyEvent {
    private LocalDate eventDate;          // ← the field that holds the date

    // ---------- Constructors ----------
    public MyEvent() {                     // no‑arg → today
        this.eventDate = LocalDate.now();
    }

    public MyEvent(LocalDate date) {       // give a LocalDate directly
        this.eventDate = date;
    }

    public MyEvent(String isoDate) {       // give a string like "2024‑03‑15"
        this.eventDate = LocalDate.parse(isoDate); // ISO‑8601 is default
    }

    // ---------- Getters / Setters ----------
    public LocalDate getEventDate() {
        return eventDate;
    }

    /** Set the date from a LocalDate instance */
    public void setEventDate(LocalDate date) {
        this.eventDate = Objects.requireNonNull(date);
    }

    /** Set the date from a text representation (any pattern you like) */
    public void setEventDate(String text, DateTimeFormatter fmt) {
        this.eventDate = LocalDate.parse(text, fmt);
    }

    // ---------- Convenience helpers ----------
    /** Returns the date formatted with a custom pattern */
    public String getEventDateFormatted(DateTimeFormatter fmt) {
        return eventDate.format(fmt);
    }

    @Override
    public String toString() {
        return "MyEvent{eventDate=" + eventDate + '}';
    }
}
```

### How to use it

```java
public class Demo {
    public static void main(String[] args) {
        // 1️⃣  Set to *today* (no‑arg constructor)
        MyEvent today = new MyEvent();
        System.out.println(today); // MyEvent{eventDate=2024-06-24}

        // 2️⃣  Set with an explicit LocalDate
        MyEvent christmas = new MyEvent(LocalDate.of(2024, 12, 25));
        System.out.println(christmas); // MyEvent{eventDate=2024-12-25}

        // 3️⃣  Set from an ISO‑8601 string ("yyyy-MM-dd")
        MyEvent newYear = new MyEvent("2025-01-01");
        System.out.println(newYear); // MyEvent{eventDate=2025-01-01}

        // 4️⃣  Set from a custom formatted string, e.g. "15/03/2024"
        DateTimeFormatter euroFmt = DateTimeFormatter.ofPattern("dd/MM/yyyy");
        MyEvent custom = new MyEvent();
        custom.setEventDate("15/03/2024", euroFmt);
