    private final RoleRepository roleRepo;
    private final UserRepository userRepo;
    private final PasswordEncoder passwordEncoder;

    @Override
    public void run(String... args) {
        // 创建角色
        Role admin = roleRepo.findByName("ROLE_ADMIN")
                .orElseGet(() -> roleRepo.save(new Role(null, "ROLE_ADMIN", null)));
        Role user = roleRepo.findByName("ROLE_USER")
                .orElseGet(() -> roleRepo.save(new Role(null, "ROLE_USER", null)));

        // 创建管理员用户（若不存在）
        if (userRepo.findByUsername("admin").isEmpty()) {
            User adminUser = new User();
            adminUser.setUsername("admin");
            adminUser.setPassword(passwordEncoder.encode("admin123"));
            adminUser.setRoles(Set.of(admin, user));
            adminUser.setEnabled(true);
            userRepo.save(adminUser);
        }

        // 创建普通用户
        if (userRepo.findByUsername("john").isEmpty()) {
            User normal = new User();
            normal.setUsername("john");
            normal.setPassword(passwordEncoder.encode("john456"));
            normal.setRoles(Set.of(user));
            normal.setEnabled(true);
            userRepo.save(normal);
        }
    }
}
