## 6️⃣ 登录接口 – `AuthenticationController`

登录成功后返回 **JWT**（包含过期时间、用户信息、权限），前端把 token 存入 `localStorage` / `sessionStorage` 并在后续请求的 `Authorization` 头部携带。  

```java
// src/main/java/com/example/securitydemo/controller/AuthController.java
package com.example.securitydemo.controller;

import com.example.securitydemo.dto.*;
import com.example.securitydemo.util.JwtUtil;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authenticationManager; // 由 Spring 自动注入
    private final JwtUtil jwtUtil;

    /**
     * 登录入口，POST /api/auth/login
     * 请求体示例: { "username":"admin", "password":"admin123" }
     */
    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(@RequestBody LoginRequest req) {
        try {
            // 交给 AuthenticationManager 去校验用户名/密码
            Authentication authentication = authenticationManager.authenticate(
                    new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword()));

            UserDetails userDetails = (UserDetails) authentication.getPrincipal();

            // 生成 JWT（带有过期时间）
            String token = jwtUtil.generateToken(userDetails);

            LoginResponse resp = new LoginResponse(token, jwtUtil.getExpirationInMs());
            return ResponseEntity.ok(resp);
        } catch (BadCredentialsException ex) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new LoginResponse("Invalid username or password", 0));
        }
    }
}
```

