## 7️⃣ JWT 工具类

我们使用 `io.jsonwebtoken.Jwts`（jjwt）来生成、解析、校验 token。  

```java
// src/main/java/com/example/securitydemo/util/JwtUtil.java
package com.example.securitydemo.util;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.*;
import org.springframework.security.core.*;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import java.security.Key;
import java.util.*;
import java.util.stream.Collectors;

/**
 * JWT 生成与校验工具类
 */
@Slf4j
@Component
public class JwtUtil {

    /** 读取配置：密钥、失效时间（毫秒） */
    @Value("${jwt.secret}")
    private String secret;                       // 必须是 256 位的 Base64 字符串

    @Value("${jwt.expirationMs}")
    private long expirationMs;                    // 如 30 * 60 * 1000 (30 分钟)

    private Key key;                               // JJWT 使用的密钥对象

    @PostConstruct
    public void init() {
        // 这里直接把 secret 转成 HMAC SHA-256 密钥
        this.key = Keys.hmacShaKeyFor(Base64.getDecoder().decode(secret));
    }

    /** 
     * 生成 token，默认放入 username 和 authorities
     */
    public String generateToken(UserDetails userDetails) {
        Map<String, Object> claims = new HashMap<>();
        // 把 authorities（ROLE_XXX）写入 claims，方便后面解析
        List<String> roles = userDetails.getAuthorities()
                .stream()
                .map(GrantedAuthority::getAuthority)
                .collect(Collectors.toList());
        claims.put("roles", roles);

        long now = System.currentTimeMillis();
        Date expiryDate = new Date(now + expirationMs);

        return Jwts.builder()
                .setClaims(claims)
                .setSubject(userDetails.getUsername())
                .setIssuedAt(new Date(now))
                .setExpiration(expiryDate)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    /** 解析 token，返回 Username */
    public String getUsernameFromToken(String token) {
        return parseClaims(token).getSubject();
    }

    /** 从 token 中拿到权限集合（List<String>） */
    @SuppressWarnings("unchecked")
    public List<String> getRolesFromToken(String token) {
        Claims claims = parseClaims(token);
        return (List<String>) claims.get("roles", List.class);
    }

    /** 检查 token 是否已过期 */
    public boolean isTokenExpired(String token) {
        try {
            Date expiration = parseClaims(token).getExpiration();
            return expiration.before(new Date());
        } catch (JwtException e) {
            return true; // 解析错误同样视为过期/无效
        }
    }

    /** 校验 token 与 UserDetails 是否匹配（用户名相同且未过期） */
    public boolean validateToken(String token, UserDetails userDetails) {
        final String username = getUsernameFromToken(token);
        return (username.equals(userDetails.getUsername()) && !isTokenExpired(token));
    }

    /** 把 token 解析为 Claims（内部方法） */
    private Claims parseClaims(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody();
    }

    /** 暴露失效时间（外部需要） */
    public long getExpirationInMs() {
        return expirationMs;
    }
}
```

