## 8️⃣ Spring Security 配置

下面的配置实现 **：

1️⃣ **无状态**（Stateless）请求——不使用 HTTP Session。  
2️⃣ **每次请求**都经过 **JwtAuthenticationFilter** 拦截，解析 token、校验、放入 `SecurityContext`。  
3️⃣ **异常处理**：未登录或 token 失效返回 401。  
4️⃣ **授权**：基于 `@PreAuthorize` 注解或 URL 匹配。  

### 8.1 JwtAuthenticationFilter

```java
// src/main/java/com/example/securitydemo/filter/JwtAuthenticationFilter.java
package com.example.securitydemo.filter;

import com.example.securitydemo.util.JwtUtil;
import lombok.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;
import org.springframework.web.filter.OncePerRequestFilter;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.*;
import java.util.stream.Collectors;

@Component
@RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtUtil jwtUtil;
    private final UserDetailsService userDetailsService; // 注入我们自己的实现

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        try {
            String jwt = resolveToken(request);
            if (jwt != null && !jwtUtil.isTokenExpired(jwt)) {
                // 通过 token 里的用户名加载 UserDetails（可选：直接把角色写在 token 中）
                String username = jwtUtil.getUsernameFromToken(jwt);
                UserDetails userDetails = userDetailsService.loadUserByUsername(username);

                // 这里再次校验 token 与 userDetails 是否匹配（防止 token 被篡改）
                if (jwtUtil.validateToken(jwt, userDetails)) {
                    UsernamePasswordAuthenticationToken authentication =
                            new UsernamePasswordAuthenticationToken(
                                    userDetails, null, userDetails.getAuthorities());

                    authentication.setDetails(
                            new WebAuthenticationDetailsSource().buildDetails(request));

                    SecurityContextHolder.getContext().setAuthentication(authentication);
                }
            }
        } catch (Exception ex) {
            // 任何异常都不阻止请求继续，只是不会设置 Authentication
            logger.error("Could not set user authentication in security context", ex);
        }

        filterChain.doFilter(request, response);
    }

    /** 从 Header 中读取 "Bearer xxx" */
    private String resolveToken(HttpServletRequest request) {
        String bearerToken = request.getHeader("Authorization");
        if (StringUtils.hasText(bearerToken) && bearerToken.startsWith("Bearer ")) {
            return bearerToken.substring(7);
        }
        return null;
    }
}
```

### 8.2 AuthorizationEntryPoint（统一返回 401）

```java
// src/main/java/com/example/securitydemo/exception/RestAuthenticationEntryPoint.java
package com.example.securitydemo.exception;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.*;
import org.springframework.security.core.*;
import org.springframework.security.web.AuthenticationEntryPoint;
import org.springframework.stereotype.Component;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.*;

@Component
public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {

    private final ObjectMapper mapper = new ObjectMapper();

    @Override
    public void commence(HttpServletRequest request,
                         HttpServletResponse response,
                         AuthenticationException authException) throws IOException {

        // 统一返回 JSON，方便前端处理
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);

        Map<String, Object> body = new LinkedHashMap<>();
        body.put("timestamp", new Date());
        body.put("status", HttpServletResponse.SC_UNAUTHORIZED);
        body.put("error", "Unauthorized");
        body.put("message", authException.getMessage());
        body.put("path", request.getRequestURI());

        mapper.writeValue(response.getOutputStream(), body);
    }
}
```

### 8.3 SecurityConfig

```java
// src/main/java/com/example/securitydemo/config/SecurityConfig.java
package com.example.securitydemo.config;

import com.example.securitydemo.exception.RestAuthenticationEntryPoint;
import com.example.securitydemo.filter.JwtAuthenticationFilter;
import com.example.securitydemo.service.CustomUserDetailsService;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.*;
import org.springframework.http.HttpMethod;
import org.springframework.security.authentication.*;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.*;
import org.springframework.security.config.http.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableMethodSecurity(prePostEnabled = true)   // 开启 @PreAuthorize
@RequiredArgsConstructor
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtAuthenticationFilter;
    private final RestAuthenticationEntryPoint restAuthenticationEntryPoint;
    private final CustomUserDetailsService userDetailsService;
    private final PasswordEncoder passwordEncoder;

    /** 暴露 AuthenticationManager 供 AuthController 使用 */
    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration authConfig)
            throws Exception {
        return authConfig.getAuthenticationManager();
    }

    /** 这里使用 HttpSecurity DSL（Spring Security 5.7+ 推荐） */
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {

        // 1. 关闭不需要的功能
        http.csrf().disable()   // 采用 JWT 的无状态API，一般关闭 CSRF
            .cors().and()        // 如需跨域，可自行配置 CorsConfigurationSource
            .sessionManagement()
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS) // 不创建 HttpSession
            .and()
            .exceptionHandling()
                .authenticationEntryPoint(restAuthenticationEntryPoint); // 统一返回401

        // 2. 公开接口（登录、注册等）
        http.authorizeHttpRequests()
                .requestMatchers(HttpMethod.POST, "/api/auth/**").permitAll()
                .requestMatchers("/h2-console/**").permitAll() // 测试环境打开 H2 console
                // 其余的接口需要认证
                .anyRequest().authenticated();

        // 3. 将自定义的 JWT Filter 放在 UsernamePasswordAuthenticationFilter 前面
        http.addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

        // 4. 为了能在 H2 console 正常显示，关闭 X‑Frame-Options（生产环境请删除）
        http.headers().frameOptions().disable();

        return http.build();
    }

    /** 让 Spring 使用我们自定义的 UserDetailsService + PasswordEncoder */
    @Bean
    public DaoAuthenticationProvider daoAuthenticationProvider() {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
        provider.setUserDetailsService(userDetailsService);
        provider.setPasswordEncoder(passwordEncoder);
        return provider;
    }
}
```

> **关键点**  
> - `SessionCreationPolicy.STATELESS` 把 **Session** 完全关闭，所有安全信息都靠 **JWT**。  
> - `JwtAuthenticationFilter` 是 **一次性**（`OncePerRequestFilter`），每次请求都会尝试解析 token 并放入 `SecurityContext`。  
> - `RestAuthenticationEntryPoint` 捕获未通过认证的请求并返回 **401 JSON**，而不是默认的 HTML 登录页。  

