```java
package com.example.fileupload.service;

import jakarta.annotation.PostConstruct;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.*;

@Service
public class StorageService {

    /** Папка, где будут храниться файлы. Можно вынести в конфиг. */
    private final Path storageLocation = Paths.get("uploaded-files");

    @PostConstruct
    public void init() throws IOException {
        Files.createDirectories(storageLocation);
    }

    /** Сохраняет один файл и возвращает путь к нему (относительно storageLocation). */
    public String store(MultipartFile file) throws IOException {
        if (file.isEmpty()) {
            throw new IllegalArgumentException("Файл пустой");
        }

        // Очищаем имя (удаляем .. и т.п.)
        String originalFilename = StringUtils.cleanPath(file.getOriginalFilename());

        // Чтобы избежать конфликтов, добавляем UUID к имени
        String filename = System.currentTimeMillis() + "_" + originalFilename;

        // Проверяем, что файл не «выходит» наружу (security check)
        if (filename.contains("..")) {
            throw new IllegalArgumentException("Недопустимое имя файла: " + filename);
        }

        Path target = storageLocation.resolve(filename);
        Files.copy(file.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);

        // Возвращаем относительный путь, который потом можно отправить клиенту
        return filename;
    }

    /** Возвращает файл как Resource (для скачивания). */
    public Path load(String filename) {
        return storageLocation.resolve(filename).normalize();
    }
}
```

