## 4️⃣ REST‑контроллер

```java
package com.example.fileupload.controller;

import com.example.fileupload.service.StorageService;
import org.springframework.core.io.PathResource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Path;

@RestController
@RequestMapping("/api/files")
public class FileController {

    private final StorageService storageService;

    public FileController(StorageService storageService) {
        this.storageService = storageService;
    }

    // ---------- Загрузка одного файла ----------
    @PostMapping("/upload")
    public ResponseEntity<?> uploadFile(@RequestParam("file") MultipartFile file) {
        try {
            String savedFilename = storageService.store(file);
            // Можно вернуть DTO с URL для скачивания
            String downloadUrl = "/api/files/" + savedFilename;
            return ResponseEntity.ok().body(
                    new UploadResponse(savedFilename, downloadUrl, file.getSize())
            );
        } catch (IOException e) {
            return ResponseEntity.status(500).body("Ошибка при сохранении файла: " + e.getMessage());
        }
    }

    // ---------- Загрузка нескольких файлов ----------
    @PostMapping("/upload-multiple")
    public ResponseEntity<?> uploadMultiple(@RequestParam("files") MultipartFile[] files) {
        try {
            var results = new java.util.ArrayList<UploadResponse>();
            for (MultipartFile f : files) {
                String saved = storageService.store(f);
                results.add(new UploadResponse(saved, "/api/files/" + saved, f.getSize()));
            }
            return ResponseEntity.ok(results);
        } catch (IOException e) {
            return ResponseEntity.status(500).body("Ошибка при сохранении файлов: " + e.getMessage());
        }
    }

    // ---------- Скачивание ----------
    @GetMapping("/{filename:.+}")
    public ResponseEntity<?> download(@PathVariable String filename) {
        Path file = storageService.load(filename);
        if (!java.nio.file.Files.exists(file) || !java.nio.file.Files.isRegularFile(file)) {
            return ResponseEntity.notFound().build();
        }

        PathResource resource = new PathResource(file);
        String contentType = "application/octet-stream";

        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(contentType))
                .header(HttpHeaders.CONTENT_DISPOSITION,
                        "attachment; filename=\"" + resource.getFilename() + "\"")
                .body(resource);
    }

    // DTO для ответа
    static record UploadResponse(String filename,
                                 String downloadUrl,
                                 long size) {}
}
```

**Пояснения:**
* `@RequestParam("file") MultipartFile file` – Spring автоматически привязывает часть `multipart/form-data` к объекту `MultipartFile`.
* Для нескольких файлов используем массив `MultipartFile[]`.
* В методе скачивания возвращаем `PathResource`, который умеет отдавать файл без необходимости читать его в память.
* В URL‑шаблоне `/{filename:.+}` точка (`.`) в имени файла сохраняется (иначе Spring обрезает её как расширение).

