```java
package com.example.admin.service.impl;

import com.example.admin.dao.AdminDao;
import com.example.admin.entity.Admin;
import com.example.admin.service.AdminService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

/**
 * 业务层实现
 */
@Service
public class AdminServiceImpl implements AdminService {

    @Autowired
    private AdminDao adminDao;

    // BCrypt 加密器（Spring‑Security 中提供）
    private final BCryptPasswordEncoder passwordEncoder = new BCryptPasswordEncoder();

    @Override
    public Admin login(String username, String rawPassword) {
        if (!StringUtils.hasText(username) || !StringUtils.hasText(rawPassword)) {
            return null; // 参数为空直接返回
        }

        // 1️⃣ 根据用户名查询管理员信息（包括加密后的密码）
        Admin admin = adminDao.findByUsername(username);
        if (admin == null) {
            return null; // 用户不存在
        }

        // 2️⃣ 使用 BCrypt 校验密码
        boolean matches = passwordEncoder.matches(rawPassword, admin.getPassword());
        if (!matches) {
            return null; // 密码错误
        }

        // 登录成功，返回一个不带密码的对象，避免泄露给前端
        Admin safeAdmin = new Admin();
        safeAdmin.setId(admin.getId());
        safeAdmin.setUsername(admin.getUsername());
        safeAdmin.setName(admin.getName());
        // 不复制 password
        return safeAdmin;
    }
}
```

> **密码加密**：  
> - `BCryptPasswordEncoder` 是 Spring Security 提供的实现，默认强度为 10。  
> - **创建管理员账号时**，应使用 `passwordEncoder.encode(rawPwd)` 将明文密码加密后存入 `admin_user.password`。  
> - 生产环境建议把 `BCryptPasswordEncoder` 声明为 `@Bean` 注入，以便统一管理。

