                          @SessionAttribute(value = "admin", required = false) Admin sessionAdmin,
                          @SessionAttribute(name = "admin", required = false) Admin adminFromSession,
                          @SessionAttribute(value = "admin", required = false) Admin existingAdmin,
                          javax.servlet.http.HttpSession httpSession) {

        // 防止已经登录的用户再次登录（可选）
        if (sessionAdmin != null) {
            return "redirect:/admin/home";
        }

        Admin admin = adminService.login(username, password);
        if (admin == null) {
            // 登录失败，返回登录页面并显示错误信息
            model.addAttribute("errorMsg", "用户名或密码错误");
            return "login";
        }

        // 登录成功，放入 Session
        httpSession.setAttribute("admin", admin);

        // 重定向到管理员首页
        return "redirect:/admin/home";
    }

    /**
     * GET /admin/home → 管理员主界面（需要登录）
     */
    @GetMapping("/home")
    public String home(@SessionAttribute(value = "admin", required = false) Admin admin,
                       Model model) {
        if (admin == null) {
            // 未登录则跳转回登录页
            return "redirect:/admin/login";
        }
        model.addAttribute("adminName", admin.getName());
        return "admin_home"; // 对应 /WEB-INF/jsp/admin_home.jsp
    }

    /**
     * GET /admin/logout → 退出登录
     */
    @GetMapping("/logout")
    public String logout(javax.servlet.http.HttpSession session) {
        session.invalidate(); // 销毁会话
        return "redirect:/admin/login";
    }
}
```

> **要点解释**  
> 1. **页面映射**：`login.jsp` 与 `admin_home.jsp` 放在 `/WEB-INF/jsp/`，通过 `InternalResourceViewResolver` 解析。  
> 2. **Session 维护**：登录成功后把 `Admin`（不含密码）放入 `HttpSession`，后续请求通过 `@SessionAttribute` 取出。  
> 3. **错误提示**：登录失败时把错误信息放进 `Model`，在 `login.jsp` 中显示。  
> 4. **防止重复登录**：如果已经有 `admin` 对象在 Session 中，直接跳转首页。  

