## 3. Detect all root drives  

```java
package dev.example.fileindex;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Small utility that abstracts away OS differences.
 * On Unix/Linux/macOS it returns "/", on Windows it returns every
 * root returned by `File.listRoots()` (C:\, D:\, …).
 */
public final class DriveDetector {
    private DriveDetector() { }

    /** @return an immutable list of root directories */
    public static List<File> listRootDrives() {
        File[] roots = File.listRoots();
        // Guard against a null return (should never happen, but be defensive)
        return roots == null ? List.of() : List.of(roots);
    }

    /** @return the same list as strings – convenient for logging */
    public static List<String> listRootDriveNames() {
        return listRootDrives().stream()
                .map(File::getAbsolutePath)
                .collect(Collectors.toList());
    }
}
```

