## 5. Persisting the index  

We store the JSON file next to the executable (or wherever you like).  
Jackson is very efficient – even a few hundred thousand entries are written in < 1 s.

```java
package dev.example.fileindex;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.*;
import java.nio.file.*;
import java.util.Map;

/**
 * Serialises / deserialises the index to a JSON file.
 * The JSON format is deliberately simple:
 *   { "/absolute/path/to/file.txt": { "path": "...", "size": 1234, "lastModified": 1689876543210, ... }, … }
 *
 * If the file does not exist, {@link #load(Path)} returns an empty map.
 */
public final class IndexPersistence {
    private static final ObjectMapper MAPPER = new ObjectMapper()
            // cosmetically nice – not required for functionality
            .writerWithDefaultPrettyPrinter()
            .withDefaultPrettyPrinter();

    private IndexPersistence() { }

    /** Write the current index to disk (overwrites if exists). */
    public static void save(Map<String, FileMeta> index, Path targetFile) throws IOException {
        // Ensure parent directory exists
        Files.createDirectories(targetFile.getParent());
        try (BufferedWriter writer = Files.newBufferedWriter(targetFile,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE)) {
            MAPPER.writeValue(writer, index);
        }
    }

    /** Load an index from disk. If the file is missing or malformed we return an empty map. */
    public static Map<String, FileMeta> load(Path sourceFile) throws IOException {
        if (!Files.isRegularFile(sourceFile)) {
            System.out.println("Index file not found – starting with an empty index.");
            return new java.util.concurrent.ConcurrentHashMap<>();
        }
        try (BufferedReader reader = Files.newBufferedReader(sourceFile)) {
            // Using TypeReference so Jackson knows the concrete generic types
            return MAPPER.readValue(reader,
                    new TypeReference<java.util.concurrent.ConcurrentHashMap<String, FileMeta>>() {});
        } catch (Exception e) {
            System.err.println("Failed to read index file – starting with empty index. Reason: " + e);
            return new java.util.concurrent.ConcurrentHashMap<>();
        }
    }
}
```

