## 3️⃣ 服务器端实现（Server）

### 3️⃣1 主类 `ServerMain`

```java
public class ServerMain {
    private static final int PORT = 7777;
    // 保存所有正在等待服务的用户会话
    private static final ConcurrentMap<String, UserSession> waitingMap = new ConcurrentHashMap<>();

    // 线程池：负责每个用户会话的收发
    private static final ExecutorService workerPool = Executors.newCachedThreadPool();
    // 用来定时检查“客服忙”超时的调度器
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);

    public static void main(String[] args) throws IOException {
        ServerSocket ss = new ServerSocket(PORT);
        System.out.println("客服服务器已启动，端口：" + PORT);
        // 启动客服 UI（在 EDT 中）
        SwingUtilities.invokeLater(() -> new StaffFrame(waitingMap));

        while (true) {
            Socket client = ss.accept();
            workerPool.submit(() -> handleNewUser(client));
        }
    }

    private static void handleNewUser(Socket socket) {
        try {
            // 第一次消息一定是 SERVICE_REQUEST，拿到用户 ID
            Message first = MessageCodec.decode(socket.getInputStream());
            if (first.getType() != MessageType.SERVICE_REQUEST) {
                socket.close();
                return;
            }
            ServiceRequestMsg req = (ServiceRequestMsg) first;
            String userId = req.getUserId();

            UserSession session = new UserSession(userId, socket);
            waitingMap.put(userId, session);               // 让客服端看到
            // 启动超时检测（30 秒没有被接受就标记 BUSY）
            scheduler.schedule(() -> {
                if (waitingMap.containsKey(userId) && !session.isServed()) {
                    try {
                        MessageCodec.encode(new BusyNoticeMsg(userId), socket.getOutputStream());
                    } catch (IOException ignored) {}
                    // 自动关闭该会话
                    session.close();
                }
            }, 30, TimeUnit.SECONDS);

            // 启动接收线程（从用户方向接受消息转发给客服 UI）
            new Thread(() -> receiveFromUser(session)).start();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 只负责把用户发来的消息转发给客服 UI（使用回调机制） */
    private static void receiveFromUser(UserSession session) {
        try {
            InputStream in = session.getSocket().getInputStream();
            while (!session.isClosed()) {
                Message msg = MessageCodec.decode(in);
                // 把消息交给客服 UI 处理（在 EDT 中更新聊天框）
                SwingUtilities.invokeLater(() -> StaffFrame.dispatchUserMsg(session, msg));
            }
        } catch (IOException e) {
            // 用户掉线或会话关闭
            waitingMap.remove(session.getUserId());
        }
    }
}
```

### ③2 `UserSession`（服务器端对单个用户的封装）

```java
class UserSession {
    private final String userId;
    private final Socket socket;
    private volatile boolean served = false;   // 是否已经被客服接收
    private volatile boolean closed = false;

    UserSession(String userId, Socket socket) {
        this.userId = userId;
        this.socket = socket;
    }
    // getters / setters ...

    public void send(Message msg) throws IOException {
        MessageCodec.encode(msg, socket.getOutputStream());
    }

    public void close() {
        closed = true;
        try { socket.close(); } catch (IOException ignored) {}
    }
}
```

### ③3 `StaffFrame`（客服端 Swing UI）

```java
public class StaffFrame extends JFrame {
    // 所有待处理会话的列表
    private final ConcurrentMap<String, UserSession> waitingMap;
    private final JList<String> waitList;          // 显示 userId
    private final JTextArea chatArea;
    private final JTextField inputField;
    private final JButton sendTextBtn, sendFileBtn, sendImgBtn;
    // 当前正在会话的用户
    private volatile UserSession currentSession = null;

    public StaffFrame(ConcurrentMap<String, UserSession> waitingMap) {
        this.waitingMap = waitingMap;
        setTitle("客服端（Staff）");
        setSize(800, 600);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        setVisible(true);

        // 定时刷新待处理列表（亦可监听 map 变更）
        new Timer(1000, e -> refreshWaitList()).start();
    }

    private void initUI() {
        setLayout(new BorderLayout());

        // 左侧 – 待处理用户列表
        waitList = new JList<>(new DefaultListModel<>());
        waitList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        waitList.addMouseListener(new MouseAdapter() {
            @Override public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2) { // 双击 → 接受/拒绝
                    String uid = waitList.getSelectedValue();
                    if (uid != null) { showAcceptDialog(uid); }
                }
            }
        });
        add(new JScrollPane(waitList), BorderLayout.WEST);

        // 中间 – 聊天显示区
        chatArea = new JTextArea();
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        // 底部 – 输入框+发送按钮
        JPanel bottom = new JPanel(new BorderLayout());
        inputField = new JTextField();
        sendTextBtn = new JButton("发送文字");
        sendFileBtn = new JButton("发送文件");
        sendImgBtn  = new JButton("发送图片");
        bottom.add(inputField, BorderLayout.CENTER);
        JPanel btnPanel = new JPanel();
        btnPanel.add(sendTextBtn);
        btnPanel.add(sendImgBtn);
        btnPanel.add(sendFileBtn);
        bottom.add(btnPanel, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        // 按钮事件
        sendTextBtn.addActionListener(e -> sendText());
        sendImgBtn .addActionListener(e -> sendImage());
        sendFileBtn.addActionListener(e -> sendFile());
    }

    /** 刷新左侧待处理用户列表 */
    private void refreshWaitList() {
        DefaultListModel<String> model = (DefaultListModel<String>) waitList.getModel();
        Set<String> ids = waitingMap.keySet();
        // 简单同步（列表不大）  →   实际可以用 JList 的 ListModel + Listener
        SwingUtilities.invokeLater(() -> {
            model.clear();
            ids.forEach(model::addElement);
        });
    }

    /** 双击用户后弹出接受/拒绝对话框 */
    private void showAcceptDialog(String userId) {
        int ret = JOptionPane.showConfirmDialog(
                this,
                "是否接受用户 " + userId + " 的请求？",
                "接收请求",
                JOptionPane.YES_NO_OPTION);
        UserSession sess = waitingMap.remove(userId);
        if (sess == null) return; // 已被其他客服收走

        if (ret == JOptionPane.YES_OPTION) {
            sess.setServed(true);
            currentSession = sess;
            chatArea.setText(""); // 清空聊天框
            // 读取历史记录
            List<String> history = FileUtil.readChatLog(userId);
            history.forEach(line -> chatArea.append(line + "\n"));

            try {
                sess.send(new ServiceAcceptMsg(userId));
            } catch (IOException ignored) {}
        } else {
            try { sess.send(new ServiceRejectMsg(userId)); } catch (IOException ignored) {}
            sess.close();
        }
    }

    /** 向当前会话用户发送文字 */
    private void sendText() {
        if (currentSession == null) {
            JOptionPane.showMessageDialog(this, "请先接受一个用户的会话！");
            return;
        }
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            currentSession.send(new TextMsg(txt));
            // 保存本地记录
            FileUtil.appendChatLog(currentSession.getUserId(),
                    "[客服] " + txt);
            chatArea.append("[客服] " + txt + "\n");
            inputField.setText("");
        } catch (IOException e) {
            showErrorAndClose("发送失败，已关闭会话", e);
        }
    }

    /** 发送图片 */
    private void sendImage() {
        if (currentSession == null) return;
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new FileNameExtensionFilter("图片文件", "png","jpg","jpeg","gif"));
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File imgFile = fc.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(imgFile.toPath());
                currentSession.send(new ImageMsg(imgFile.getName(), data));
                // 保存记录（只记录文件名，实际文件保存在本地同名文件夹）
                FileUtil.appendChatLog(currentSession.getUserId(),
                        "[客服] <发送图片> " + imgFile.getName());
                chatArea.append("[客服] <发送图片> " + imgFile.getName() + "\n");
            } catch (IOException ex) { showErrorAndClose("图片发送失败", ex); }
        }
    }

    /** 发送任意文件 */
