            try {
                byte[] data = Files.readAllBytes(file.toPath());
                currentSession.send(new FileMsg(file.getName(), data));
                FileUtil.appendChatLog(currentSession.getUserId(),
                        "[客服] <发送文件> " + file.getName());
                chatArea.append("[客服] <发送文件> " + file.getName() + "\n");
            } catch (IOException ex) { showErrorAndClose("文件发送失败", ex); }
        }
    }

