            if (staff.currentSession == null || !staff.currentSession.getUserId().equals(session.getUserId())) {
                // 不是当前会话的消息 → 只在左侧列表做提示（这里直接弹框示例）
                JOptionPane.showMessageDialog(staff,
                        "用户 " + session.getUserId() + " 发来新消息！",
                        "新消息", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
            // 正常聊天显示
            if (msg instanceof TextMsg) {
                String txt = ((TextMsg) msg).getText();
                staff.chatArea.append("[用户] " + txt + "\n");
                FileUtil.appendChatLog(session.getUserId(),
                        "[用户] " + txt);
            } else if (msg instanceof ImageMsg) {
                ImageMsg im = (ImageMsg) msg;
                // 保存到本地一个 “downloads/<userId>/” 目录
                File dir = new File("downloads/" + session.getUserId());
                dir.mkdirs();
                File out = new File(dir, im.getFileName());
                try (FileOutputStream fos = new FileOutputStream(out)) {
                    fos.write(im.getData());
                } catch (IOException e) {
                    e.printStackTrace();
                }
                staff.chatArea.append("[用户] <图片> " + im.getFileName() + "\n");
                FileUtil.appendChatLog(session.getUserId(),
                        "[用户] <图片> " + im.getFileName());
            } else if (msg instanceof FileMsg) {
                // 同上，保存到 downloads 目录
                FileMsg fm = (FileMsg) msg;
                File dir = new File("downloads/" + session.getUserId());
                dir.mkdirs();
                File out = new File(dir, fm.getFileName());
                try (FileOutputStream fos = new FileOutputStream(out)) {
                    fos.write(fm.getData());
                } catch (IOException e) {
                    e.printStackTrace();
                }
                staff.chatArea.append("[用户] <文件> " + fm.getFileName() + "\n");
                FileUtil.appendChatLog(session.getUserId(),
                        "[用户] <文件> " + fm.getFileName());
            }
        });
    }

    private void showErrorAndClose(String tip, Exception e) {
        JOptionPane.showMessageDialog(this, tip + "\n" + e.getMessage(),
                "错误", JOptionPane.ERROR_MESSAGE);
        if (currentSession != null) {
            currentSession.close();
            currentSession = null;
        }
    }

    // ---- 单例模式（方便 static 调用）----
    private static StaffFrame instance;
    public StaffFrame(ConcurrentMap<String, UserSession> waitingMap) {
        this.waitingMap = waitingMap;
        instance = this;
        // UI 初始化见上...
    }
    public static StaffFrame getInstance() { return instance; }
}
```

> **要点说明**  

| 功能 | 实现关键点 |
|------|------------|
| **多用户并发** | `ConcurrentHashMap` 保存待服务用户；每个 `UserSession` 独立线程收发；`ThreadPoolExecutor` 动态伸缩 |
| **客服忙提示** | `ScheduledExecutorService` 为每个新用户启动 30 s 超时任务，未被接收则发送 `BUSY_NOTICE` |
| **文件/图片传输** | 把二进制数据放在 `Message` 的 `byte[]` 中，使用 `int length` 前缀；发送前读取为 `byte[]`，接收后写入本地文件 |
| **聊天记录持久化** | `FileUtil.appendChatLog(userId, line)` 把每条发送/接收的文字（文件/图片只记录文件名）追加到 `chatlogs/<userId>.log`；打开时 `FileUtil.readChatLog(userId)` 读取全部行 |

