### 4️⃣2 `UserFrame`（用户端 UI）

```java
public class UserFrame extends JFrame {
    private final Socket socket;
    private final JTextArea chatArea;
    private final JTextField inputField;
    private final JButton sendBtn, sendImgBtn, sendFileBtn;
    private volatile boolean serviceAccepted = false; // 是否已得到客服响应

    public UserFrame(Socket socket) throws IOException {
        this.socket = socket;
        setTitle("用户端（User）");
        setSize(600, 500);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();

        // 1️⃣ 发送客服请求（第一次必须是 SERVICE_REQUEST）
        String userId = UUID.randomUUID().toString().substring(0, 8);
        MessageCodec.encode(new ServiceRequestMsg(userId), socket.getOutputStream());

        // 2️⃣ 启动接收线程
        new Thread(this::receiveLoop).start();
        setVisible(true);
    }

    private void initUI() {
        setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        inputField = new JTextField();
        sendBtn = new JButton("发送文字");
        sendImgBtn = new JButton("发送图片");
        sendFileBtn = new JButton("发送文件");
        bottom.add(inputField, BorderLayout.CENTER);
        JPanel btnPanel = new JPanel();
        btnPanel.add(sendBtn);
        btnPanel.add(sendImgBtn);
        btnPanel.add(sendFileBtn);
        bottom.add(btnPanel, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        sendBtn.addActionListener(e -> sendText());
        sendImgBtn.addActionListener(e -> sendImage());
        sendFileBtn.addActionListener(e -> sendFile());
    }

    /** 发送文字（只有在客服已接受后才可发送） */
    private void sendText() {
        if (!serviceAccepted) {
            JOptionPane.showMessageDialog(this,
                    "客服尚未接受，不能发送消息！", "提示", JOptionPane.WARNING_MESSAGE);
            return;
        }
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            MessageCodec.encode(new TextMsg(txt), socket.getOutputStream());
            chatArea.append("[我] " + txt + "\n");
            inputField.setText("");
        } catch (IOException e) {
            showErrorAndClose("发送失败", e);
        }
    }

    /** 发送图片 */
    private void sendImage() {
        if (!serviceAccepted) return;
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new FileNameExtensionFilter("图片文件", "png","jpg","jpeg","gif"));
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File img = fc.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(img.toPath());
                MessageCodec.encode(new ImageMsg(img.getName(), data), socket.getOutputStream());
                chatArea.append("[我] <发送图片> " + img.getName() + "\n");
            } catch (IOException ex) { showErrorAndClose("图片发送失败", ex); }
        }
    }

    /** 发送文件 */
    private void sendFile() {
        if (!serviceAccepted) return;
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File f = fc.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(f.toPath());
                MessageCodec.encode(new FileMsg(f.getName(), data), socket.getOutputStream());
                chatArea.append("[我] <发送文件> " + f.getName() + "\n");
            } catch (IOException ex) { showErrorAndClose("文件发送失败", ex); }
        }
    }

    /** 接收线程循环 */
    private void receiveLoop() {
        try {
            InputStream in = socket.getInputStream();
            while (true) {
                Message msg = MessageCodec.decode(in);
                SwingUtilities.invokeLater(() -> handleMessage(msg));
            }
        } catch (IOException e) {
            SwingUtilities.invokeLater(() -> {
                JOptionPane.showMessageDialog(this,
                        "与客服的连接已断开：" + e.getMessage(),
                        "连接关闭", JOptionPane.ERROR_MESSAGE);
                dispose();
            });
        }
    }

    /** 处理各种服务器返回的消息 */
    private void handleMessage(Message msg) {
        switch (msg.getType()) {
            case TEXT:
                TextMsg txt = (TextMsg) msg;
                chatArea.append("[客服] " + txt.getText() + "\n");
                break;
            case IMAGE:
                ImageMsg im = (ImageMsg) msg;
                // 存到 downloads 目录并提示
                File dir = new File("downloads");
                dir.mkdirs();
                File out = new File(dir, im.getFileName());
                try (FileOutputStream fos = new FileOutputStream(out)) {
                    fos.write(im.getData());
                } catch (IOException e) { e.printStackTrace(); }
                chatArea.append("[客服] <图片> " + im.getFileName() + "\n");
                break;
            case FILE:
                FileMsg fm = (FileMsg) msg;
                File dir2 = new File("downloads");
                dir2.mkdirs();
                File out2 = new File(dir2, fm.getFileName());
                try (FileOutputStream fos = new FileOutputStream(out2)) {
                    fos.write(fm.getData());
                } catch (IOException e) { e.printStackTrace(); }
                chatArea.append("[客服] <文件> " + fm.getFileName() + "\n");
                break;
            case SERVICE_ACCEPT:
                serviceAccepted = true;
                JOptionPane.showMessageDialog(this,
                        "已连接客服，您可以开始聊天！", "已连接", JOptionPane.INFORMATION_MESSAGE);
                break;
            case SERVICE_REJECT:
                JOptionPane.showMessageDialog(this,
                        "很抱歉，客服拒绝了您的请求。", "被拒绝", JOptionPane.WARNING_MESSAGE);
                closeSocket();
                break;
            case BUSY_NOTICE:
                JOptionPane.showMessageDialog(this,
                        "当前客服忙碌，请稍后再试！", "忙碌提示", JOptionPane.WARNING_MESSAGE);
                closeSocket();
                break;
            case HEARTBEAT:
                // 心跳无需处理，可做活跃检测
                break;
            default:
                System.out.println("未知消息类型：" + msg.getType());
        }
    }

    private void showErrorAndClose(String tip, Exception e) {
        JOptionPane.showMessageDialog(this, tip + "\n" + e.getMessage(),
                "错误", JOptionPane.ERROR_MESSAGE);
        closeSocket();
    }

    private void closeSocket() {
        try { socket.close(); } catch (IOException ignored) {}
        dispose();
    }
}
```

