## 5️⃣ 公共抽象模型（Message）

```java
/* ---------- MessageType ---------- */
public enum MessageType {
    TEXT((byte)0x01),
    IMAGE((byte)0x02),
    FILE((byte)0x03),
    SERVICE_REQUEST((byte)0x10),
    SERVICE_ACCEPT((byte)0x11),
    SERVICE_REJECT((byte)0x12),
    BUSY_NOTICE((byte)0x13),
    HEARTBEAT((byte)0x20);

    private final byte code;
    MessageType(byte code){ this.code=code; }
    public byte getCode(){ return code; }
    public static MessageType from(byte code){
        for(MessageType t: values()) if(t.code==code) return t;
        throw new IllegalArgumentException("unknown type "+code);
    }
}

/* ---------- 抽象父类 ---------- */
public abstract class Message {
    private final MessageType type;
    protected Message(MessageType type){ this.type = type; }
    public MessageType getType(){ return type; }
    // 子类实现对 payload 的读写
    abstract void writePayload(DataOutputStream out) throws IOException;
}

/* ---------- TextMsg ---------- */
public class TextMsg extends Message {
    private final String text;
    public TextMsg(String text){ super(MessageType.TEXT); this.text=text; }
    public String getText(){ return text; }

    @Override
    void writePayload(DataOutputStream out) throws IOException {
        out.writeUTF(text);
    }

    // 读取构造器（MessageFactory 调用）
    static TextMsg read(DataInputStream in) throws IOException {
        return new TextMsg(in.readUTF());
    }
}

/* ---------- ImageMsg ---------- */
public class ImageMsg extends Message {
    private final String fileName;
    private final byte[] data;
    public ImageMsg(String fileName, byte[] data){
        super(MessageType.IMAGE);
        this.fileName=fileName;
        this.data=data;
    }
    public String getFileName(){ return fileName; }
    public byte[] getData(){ return data; }

    @Override
    void writePayload(DataOutputStream out) throws IOException {
        out.writeUTF(fileName);
        out.writeInt(data.length);
        out.write(data);
    }

    static ImageMsg read(DataInputStream in) throws IOException {
        String name = in.readUTF();
        int len = in.readInt();
        byte[] d = new byte[len];
        in.readFully(d);
        return new ImageMsg(name, d);
    }
}

/* ---------- FileMsg ---------- */
public class FileMsg extends Message {
    private final String fileName;
    private final byte[] data;
    public FileMsg(String fileName, byte[] data){
        super(MessageType.FILE);
        this.fileName=fileName; this.data=data;
    }
    public String getFileName(){ return fileName; }
    public byte[] getData(){ return data; }

    @Override
    void writePayload(DataOutputStream out) throws IOException {
        out.writeUTF(fileName);
        out.writeInt(data.length);
        out.write(data);
    }

    static FileMsg read(DataInputStream in) throws IOException {
        String name = in.readUTF();
        int len = in.readInt();
        byte[] d = new byte[len];
        in.readFully(d);
        return new FileMsg(name, d);
    }
}

/* ---------- 控制指令如 ServiceRequestMsg ---------- */
public class ServiceRequestMsg extends Message {
    private final String userId;
    public ServiceRequestMsg(String userId){ super(MessageType.SERVICE_REQUEST); this.userId=userId; }
    public String getUserId(){ return userId; }

    @Override
    void writePayload(DataOutputStream out) throws IOException { out.writeUTF(userId); }
    static ServiceRequestMsg read(DataInputStream in) throws IOException { return new ServiceRequestMsg(in.readUTF()); }
}

/* ---------- 另外的控制指令（Accept、Reject、Busy、Heartbeat）类似实现 ---------- */
```

### 5.1 `MessageFactory`

```java
public class MessageFactory {
    public static Message create(byte typeCode, DataInputStream in) throws IOException {
        MessageType type = MessageType.from(typeCode);
        switch (type) {
            case TEXT:   return TextMsg.read(in);
            case IMAGE:  return ImageMsg.read(in);
            case FILE:   return FileMsg.read(in);
            case SERVICE_REQUEST: return ServiceRequestMsg.read(in);
            case SERVICE_ACCEPT:  return ServiceAcceptMsg.read(in);
            case SERVICE_REJECT:  return ServiceRejectMsg.read(in);
            case BUSY_NOTICE:    return BusyNoticeMsg.read(in);
            case HEARTBEAT:      return HeartbeatMsg.read(in);
            default: throw new IllegalArgumentException("Unsupported type "+type);
        }
    }
}
