```java
package com.example;

import com.sun.net.httpserver.*;

import java.io.*;
import java.net.InetSocketAddress;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class SimpleImageServer {

    // 保存图片的目录（请自行确保有写权限）
    private static final Path UPLOAD_DIR = Paths.get("uploaded_images");

    public static void main(String[] args) throws IOException {
        // 确保目录存在
        if (!Files.exists(UPLOAD_DIR)) {
            Files.createDirectories(UPLOAD_DIR);
        }

        // 创建 HttpServer，监听 0.0.0.0:8080
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        System.out.println("Server started at http://0.0.0.0:8080");

        // /upload 路径只接受 POST 请求
        server.createContext("/upload", new ImageUploadHandler());

        // 为了让请求能够并发处理，使用默认线程池
        server.setExecutor(null);
        server.start();
    }

    /** 负责处理图片上传的 Handler */
    static class ImageUploadHandler implements HttpHandler {

        // 限制单个文件的最大大小（这里示例 10 MB，可自行调大/调小）
        private static final long MAX_SIZE = 10L * 1024 * 1024;

        @Override
        public void handle(HttpExchange exchange) throws IOException {
            // 只允许 POST
            if (!"POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                sendResponse(exchange, 405, "Method Not Allowed");
                return;
            }

            // 检查 Content-Type（这里要求 application/octet-stream，若想兼容 multipart，可自行改造）
            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.startsWith("application/octet-stream")) {
                sendResponse(exchange, 400, "Invalid Content-Type. Expect application/octet-stream");
                return;
            }

            // ---------- 读取请求体 ----------
            InputStream is = exchange.getRequestBody();

            // 采用临时文件先写，防止一次性把大文件全部加载到内存
            Path tmpFile = Files.createTempFile("upload-", ".tmp");
            long totalRead = 0;
            try (OutputStream os = Files.newOutputStream(tmpFile, StandardOpenOption.WRITE)) {
                byte[] buffer = new byte[8192];
                int read;
                while ((read = is.read(buffer)) != -1) {
                    totalRead += read;
                    if (totalRead > MAX_SIZE) {
                        sendResponse(exchange, 413, "Payload Too Large");
                        Files.deleteIfExists(tmpFile);
                        return;
                    }
                    os.write(buffer, 0, read);
                }
            } finally {
                is.close();
            }

            // ---------- 生成真实文件名 ----------
            // 可以根据实际业务自行决定文件名，这里使用时间戳+随机数
            String fileExt = guessExtensionFromContentType(contentType);
            String fileName = DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss_SSS")
                    .format(LocalDateTime.now()) + "_" + UUID.randomUUID().toString().substring(0, 8) + fileExt;
            Path target = UPLOAD_DIR.resolve(fileName);
            Files.move(tmpFile, target, StandardCopyOption.REPLACE_EXISTING);

            // ---------- 响应 ----------
            String json = String.format("{\"code\":0,\"msg\":\"ok\",\"filename\":\"%s\"}", fileName);
            sendResponse(exchange, 200, json, "application/json");
        }

        /** 简单根据 Content-Type 猜测文件后缀，若无法判断返回 .dat */
        private String guessExtensionFromContentType(String ct) {
            // 这里仅列举了常见的图片 MIME
            return switch (ct) {
                case "image/jpeg", "application/octet-stream" -> ".jpg";
                case "image/png" -> ".png";
                case "image/gif" -> ".gif";
                case "image/bmp" -> ".bmp";
                default -> ".dat";
            };
        }

        /** 统一返回文本 */
        private void sendResponse(HttpExchange exchange, int status, String body) throws IOException {
            sendResponse(exchange, status, body, "text/plain; charset=utf-8");
        }

        private void sendResponse(HttpExchange exchange, int status, String body, String contentType) throws IOException {
            byte[] bytes = body.getBytes("UTF-8");
            exchange.getResponseHeaders().set("Content-Type", contentType);
            exchange.sendResponseHeaders(status, bytes.length);
            try (OutputStream os = exchange.getResponseBody()) {
                os.write(bytes);
            }
        }
    }
}
```

