package com.example;

import org.eclipse.jetty.server.Server;
import org.eclipse.jetty.servlet.*;

public class EmbeddedJettyServer {
    public static void main(String[] args) throws Exception {
        Server server = new Server(8080);               // 监听 8080 端口

        // 创建 ServletContext，挂载我们的 UploadServlet
        ServletContextHandler ctx = new ServletContextHandler(ServletContextHandler.SESSIONS);
        ctx.setContextPath("/");                       // 根路径
        server.setHandler(ctx);

        // 注册 servlet，映射到 /upload
        ServletHolder uploadHolder = new ServletHolder(new ImageUploadServlet());
        // 为了让 FileUpload 能解析 multipart，需要声明下面两个 init 参数
        uploadHolder.getRegistration().setMultipartConfig(new MultipartConfigElement(
                null,               // location (null -> use default temp dir)
                10L * 1024 * 1024, // max file size (10 MB)
                20L * 1024 * 1024, // max request size (20 MB)
                1024 * 1024));     // file size threshold before writing to Disk

        ctx.addServlet(uploadHolder, "/upload");

        System.out.println("Jetty server started at http://localhost:8080");
        server.start();
        server.join();
    }
}
```

#### 2.2.2 ImageUploadServlet.java

```java
package com.example;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import org.apache.commons.fileupload.*;
import org.apache.commons.fileupload.disk.*;
import org.apache.commons.io.FilenameUtils;

import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.time.format.*;
import java.util.*;

public class ImageUploadServlet extends HttpServlet {

    // 保存目录（相对路径，项目根目录下）
    private static final Path UPLOAD_DIR = Paths.get("uploaded_images");

    @Override
    public void init() throws ServletException {
        try {
            if (!Files.exists(UPLOAD_DIR)) {
                Files.createDirectories(UPLOAD_DIR);
            }
        } catch (IOException e) {
            throw new ServletException("无法创建上传目录", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        // 检查是否是 multipart/form-data
        if (!ServletFileUpload.isMultipartContent(req)) {
            resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            resp.getWriter().write("{\"code\":1,\"msg\":\"Not multipart request\"}");
            return;
        }

        // ① 创建 FileItemFactory（使用磁盘缓存）
        DiskFileItemFactory factory = new DiskFileItemFactory();
        factory.setSizeThreshold(1 * 1024 * 1024); // 1 MB 内存缓存，超过写磁盘临时文件
        factory.setRepository(File.createTempFile("upload_", "").getParentFile());

        // ② 解析请求
        ServletFileUpload upload = new ServletFileUpload(factory);
        upload.setFileSizeMax(10L * 1024 * 1024); // 单文件最大 10 MB
        upload.setSizeMax(20L * 1024 * 1024);    // 整体请求最大 20 MB

        List<FileItem> items;
        try {
            items = upload.parseRequest(req);
        } catch (FileUploadException e) {
            resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            resp.getWriter().write("{\"code\":2,\"msg\":\"Parse multipart error: " + e.getMessage() + "\"}");
            return;
        }

        // ③ 处理每个表单字段
        List<String> savedFiles = new ArrayList<>();
        for (FileItem item : items) {
            if (item.isFormField()) {
                // 若有其它普通字段，可在这里读取，如 "username"、"description" 等
                continue;
            }

            // ---------- 保存文件 ----------
            String originalFileName = FilenameUtils.getName(item.getName());
            String ext = "." + FilenameUtils.getExtension(originalFileName);
            if (ext.equals(".")) ext = ""; // 没有后缀则保持空

            // 用时间戳 + 随机数生成唯一文件名
            String newFileName = DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss_SSS")
                    .format(LocalDateTime.now()) + "_" + UUID.randomUUID().toString().substring(0, 8) + ext;

            Path target = UPLOAD_DIR.resolve(newFileName);
            try (InputStream in = item.getInputStream();
                 OutputStream out = Files.newOutputStream(target, StandardOpenOption.CREATE_NEW)) {
                in.transferTo(out);
            }

            savedFiles.add(newFileName);
        }

        // ---------- 返回结果 ----------
        resp.setContentType("application/json;charset=UTF-8");
        resp.setStatus(HttpServletResponse.SC_OK);
        String json = "{\"code\":0,\"msg\":\"ok\",\"files\":" + toJsonArray(savedFiles) + "}";
        resp.getWriter().write(json);
    }

    /** 简单把 List<String> 转成 JSON 数组（不依赖任何 JSON 库） */
    private String toJsonArray(List<String> list) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < list.size(); i++) {
            sb.append("\"").append(list.get(i).replace("\"", "\\\"")).append("\"");
            if (i < list.size() - 1) sb.append(",");
        }
        sb.append("]");
        return sb.toString();
    }
}
```

