## 5. Утилита для работы с JWT

```java
// src/main/java/com/example/demo/security/JwtTokenProvider.java
package com.example.demo.security;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.util.Date;

@Slf4j
@Component
public class JwtTokenProvider {

    private final SecretKey secretKey;
    private final long validityInMs;

    public JwtTokenProvider(@Value("${jwt.secret}") String secret,
                            @Value("${jwt.expirationMs}") long validityInMs) {
        this.secretKey = Keys.hmacShaKeyFor(secret.getBytes());   // HMAC‑SHA256
        this.validityInMs = validityInMs;
    }

    /** Генерация токена после успешного логина */
    public String createToken(String username, String role) {
        Claims claims = Jwts.claims().setSubject(username);
        claims.put("role", role);   // необязательно, но удобно

        Date now = new Date();
        Date expiry = new Date(now.getTime() + validityInMs);

        return Jwts.builder()
                .setClaims(claims)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(secretKey, SignatureAlgorithm.HS256)
                .compact();
    }

    /** Выдача username из токена */
    public String getUsername(String token) {
        return parseClaims(token).getBody().getSubject();
    }

    /** Выдача роли (или любых кастомных клеймов) */
    public String getRole(String token) {
        return (String) parseClaims(token).getBody().get("role");
    }

    /** Валидность токена (с проверкой подписи и даты истечения) */
    public boolean validateToken(String token) {
        try {
            parseClaims(token);
            return true;
        } catch (ExpiredJwtException e) {
            log.warn("JWT expired: {}", e.getMessage());
        } catch (JwtException | IllegalArgumentException e) {
            log.warn("Invalid JWT: {}", e.getMessage());
        }
        return false;
    }

    /** Внутренний парсер, чтобы не дублировать код */
    private Jws<Claims> parseClaims(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(secretKey)
                .build()
                .parseClaimsJws(token);
    }
}
```

> **Плюсы:**  
> * Храним только подпись и payload (не используем RSA, но можно заменить `Keys` на `KeyPair`).  
> * Токен подписывается HMAC‑SHA256 – достаточно просто и быстро.  

