## 7. Конфигурация Spring Security

```java
// src/main/java/com/example/demo/security/SecurityConfig.java
package com.example.demo.security;

import jakarta.servlet.http.*;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.*;
import org.springframework.http.HttpMethod;
import org.springframework.security.authentication.*;
import org.springframework.security.config.annotation.authentication.configuration.*;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.*;
import org.springframework.security.config.http.*;
import org.springframework.security.crypto.bcrypt.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.*;

@Configuration
@EnableMethodSecurity   // включаем @PreAuthorize, @Secured и т.д.
@RequiredArgsConstructor
public class SecurityConfig {

    private final CustomUserDetailsService userDetailsService;
    private final JwtTokenProvider jwtProvider;
    private final JwtAuthenticationEntryPoint authEntryPoint; // обработка 401
    private final JwtAccessDeniedHandler accessDeniedHandler; // обработка 403

    @Value("${jwt.tokenHeader}")
    private String header;

    @Value("${jwt.tokenPrefix}")
    private String prefix;

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {

        // 1️⃣ Отключаем всё, что нам не нужно (csrf, sessions, http basic)
        http.csrf(csrf -> csrf.disable())
            .sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .exceptionHandling(eh -> eh
                    .authenticationEntryPoint(authEntryPoint)
                    .accessDeniedHandler(accessDeniedHandler)
            );

        // 2️⃣ Открытые эндпоинты (логин, регистрация, swagger и т.д.)
        http.authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers(HttpMethod.GET, "/public/**").permitAll()
                .anyRequest().authenticated()
        );

        // 3️⃣ Добавляем наш фильтр **до** UsernamePasswordAuthenticationFilter
        http.addFilterBefore(
                new JwtAuthenticationFilter(jwtProvider, userDetailsService, header, prefix),
                UsernamePasswordAuthenticationFilter.class
        );

        return http.build();
    }

    // ───── authentication manager ─────
    @Bean
    public AuthenticationManager authenticationManager(
            AuthenticationConfiguration authConfig) throws Exception {
        return authConfig.getAuthenticationManager();
    }

    // ───── password encoder (BCrypt) ─────
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
```

