## 8. Контроллер аутентификации  

```java
// src/main/java/com/example/demo/controller/AuthController.java
package com.example.demo.controller;

import com.example.demo.model.*;
import com.example.demo.repository.UserRepository;
import com.example.demo.security.JwtTokenProvider;
import lombok.*;
import org.springframework.http.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authManager;
    private final JwtTokenProvider jwtProvider;
    private final UserRepository userRepo;
    private final PasswordEncoder passwordEncoder;

    /** Регистрация (по желанию) */
    @PostMapping("/register")
    public ResponseEntity<?> register(@Valid @RequestBody RegisterRequest req) {
        if (userRepo.findByUsername(req.getUsername()).isPresent()) {
            return ResponseEntity.status(HttpStatus.CONFLICT)
                    .body(new ApiError("Username already taken"));
        }

        User user = User.builder()
                .username(req.getUsername())
                .password(passwordEncoder.encode(req.getPassword()))
                .role("ROLE_USER")
                .build();

        userRepo.save(user);
        return ResponseEntity.ok(new ApiMessage("User registered"));
    }

    /** Логин – выдача JWT */
    @PostMapping("/login")
    public ResponseEntity<?> login(@Valid @RequestBody LoginRequest req) {
        try {
            // 1) Проверяем имя/пароль
            Authentication auth = authManager.authenticate(
                    new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword())
            );

            // 2) Получаем UserDetails (и роль) из auth
            UserDetails userDetails = (UserDetails) auth.getPrincipal();
            String role = userDetails.getAuthorities().iterator().next().getAuthority();

            // 3) Генерируем токен
            String token = jwtProvider.createToken(userDetails.getUsername(), role);

            return ResponseEntity.ok(new LoginResponse(token));
        } catch (BadCredentialsException ex) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new ApiError("Invalid username or password"));
        }
    }

    // ----------------- DTO -----------------
    @Data
    static class RegisterRequest {
        @NonNull private String username;
        @NonNull private String password;
    }

    @Data
    static class LoginRequest {
        @NonNull private String username;
        @NonNull private String password;
    }

    @Data @AllArgsConstructor
    static class LoginResponse {
        private String token;
    }

    @Data @AllArgsConstructor
    static class ApiError {
        private String error;
    }

    @Data @AllArgsConstructor
    static class ApiMessage {
        private String message;
    }
}
```

> **Что происходит:**  
> * `AuthenticationManager` использует наш `UserDetailsService` + `PasswordEncoder`.  
> * При успехе создаём токен, включающий `role`.  

