#### Android client code (plain Java class, can be started from a Service)

```java
package com.example.android;

import android.util.Log;

import com.example.clustering.*;
import com.example.clustering.net.SocketHelper;

import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class AndroidTaskClient {

    private static final String TAG = "AndroidTaskClient";

    private final String host;
    private final int port;
    private final TaskProcessor processor; // same impl you used on the desktop
    private final ExecutorService workerPool;
    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;

    // inbound tasks come from the desktop; we push results back.
    private final BlockingQueue<Task> inboundTaskQueue = new LinkedBlockingQueue<>();

    public AndroidTaskClient(String host, int port, TaskProcessor processor, int workerThreads) {
        this.host = host;
        this.port = port;
        this.processor = processor;
        this.workerPool = Executors.newFixedThreadPool(workerThreads);
    }

    /** Call from a background thread (e.g. Service.startCommand) */
    public void start() {
        new Thread(this::runConnectionLoop, "Android-Client-Connector").start();
        // start a pool that continuously pulls from inboundTaskQueue
        for (int i = 0; i < ((ThreadPoolExecutor) workerPool).getMaximumPoolSize(); i++) {
            workerPool.submit(this::taskConsumer);
        }
    }

    private void runConnectionLoop() {
        while (true) {
            try {
                Log.i(TAG, "Connecting to " + host + ":" + port);
                socket = new Socket(host, port);
                out = new ObjectOutputStream(socket.getOutputStream());
                in = new ObjectInputStream(socket.getInputStream());

                // Simple heartbeat thread (optional)
                new Thread(this::sendHeartbeats, "Android-Heartbeat").start();

                // Main read loop
                while (!socket.isClosed()) {
                    Message msg = SocketHelper.readMessage(in);
                    if (msg.getType() == MessageType.TASK) {
                        Task task = (Task) msg.getPayload();
                        inboundTaskQueue.offer(task);
                    } else if (msg.getType() == MessageType.SHUTDOWN) {
                        Log.i(TAG, "Remote asked to shutdown");
                        break;
                    }
                }
            } catch (IOException | ClassNotFoundException e) {
                Log.w(TAG, "Connection lost – retrying in 5s", e);
                try { Thread.sleep(5000); } catch (InterruptedException ignored) {}
            } finally {
                closeQuietly();
            }
        }
    }

    private void taskConsumer() {
        try {
            while (true) {
                Task task = inboundTaskQueue.take(); // blocks
                try {
                    Result r = processor.process(task);
                    // send back the result
                    SocketHelper.writeMessage(out, new Message(MessageType.RESULT, r));
                } catch (Exception ex) {
                    Log.e(TAG, "Error processing task " + task.getTaskId(), ex);
                }
            }
        } catch (InterruptedException ignored) {
        }
    }

    /** Very cheap keep‑alive – helps detect dead sockets */
    private void sendHeartbeats() {
        try {
            while (!socket.isClosed()) {
                Thread.sleep(10_000);
                SocketHelper.writeMessage(out, new Message(MessageType.HEARTBEAT, null));
            }
        } catch (InterruptedException | IOException ignored) {
        }
    }

    private void closeQuietly() {
        try { if (socket != null) socket.close(); } catch (IOException ignored) {}
        try { if (out != null) out.close(); } catch (IOException ignored) {}
        try { if (in != null) in.close(); } catch (IOException ignored) {}
    }

    /** Call from Service.onDestroy() or similar */
    public void stop() {
        closeQuietly();
        workerPool.shutdownNow();
    }
}
```

