public class VideoServer implements Runnable {
    private final int port;
    private final OutputStream out;   // 发送给解码器的管道输出

    public VideoServer(int port, OutputStream out) {
        this.port = port;
        this.out = out;
    }

    @Override
    public void run() {
        ServerSocket server = null;
        Socket client = null;
        InputStream in = null;
        try {
            server = new ServerSocket(port);
            System.out.println("[Server] Listening on " + port + " ...");
            client = server.accept(); // 阻塞等待客户端
            System.out.println("[Server] Client connected: " + client.getRemoteSocketAddress());

            in = client.getInputStream();
            byte[] buffer = new byte[4096];
            int len;
            while ((len = in.read(buffer)) != -1) {
                // 直接写入管道，让解码器消费
                out.write(buffer, 0, len);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            // 关闭资源
            try { if (in != null) in.close(); } catch (Exception ignored) {}
            try { if (out != null) out.close(); } catch (Exception ignored) {}
            try { if (client != null) client.close(); } catch (Exception ignored) {}
            try { if (server != null) server.close(); } catch (Exception ignored) {}
        }
    }
}
