## 3. The Server – `GameServer.java`

```java
package server;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class GameServer {

    private static final int PORT = 5555;

    // Game representation: 0 = empty, 1 = X, 2 = O
    private final int[][] board = new int[3][3];
    private final List<ClientHandler> clients = new ArrayList<>(2);
    private volatile int currentPlayer = 1; // 1 = X, 2 = O
    private volatile boolean gameRunning = false;

    public static void main(String[] args) throws IOException {
        new GameServer().run();
    }

    private void run() throws IOException {
        ServerSocket server = new ServerSocket(PORT);
        System.out.println("Tic‑Tac‑Toe server listening on port " + PORT);

        // Accept exactly two clients
        while (clients.size() < 2) {
            Socket socket = server.accept();
            ClientHandler ch = new ClientHandler(socket);
            clients.add(ch);
            new Thread(ch).start();
            System.out.println("Client connected (" + clients.size() + "/2)");
        }

        // Both are connected → start the match
        startGame();
    }

    /** Broadcast a line to every client */
    private void broadcast(String line) {
        for (ClientHandler c : clients) {
            c.send(line);
        }
    }

    /** Send the board after a move: MOVE r c X/O */
    private void broadcastMove(int r, int c) {
        String symbol = (board[r][c] == 1) ? "X" : "O";
        broadcast("MOVE " + r + " " + c + " " + symbol);
    }

    /** Check win/draw after a move and inform the clients */
    private void checkGameStatus() {
        int winner = getWinner();
        if (winner != 0) {
            broadcast("WIN " + (winner == 1 ? "X" : "O"));
            gameRunning = false;
        } else if (isBoardFull()) {
            broadcast("DRAW");
            gameRunning = false;
        }
    }

    /** Start a fresh game, give each client its symbol and who starts */
    private void startGame() {
        resetBoard();
        gameRunning = true;
        currentPlayer = 1; // X always starts

        // Assign symbols
        clients.get(0).setPlayerId(1); // X
        clients.get(1).setPlayerId(2); // O

        // Notify clients
        clients.get(0).send("START X");
        clients.get(1).send("START O");
    }

    /** Reset the board to all zeroes */
    private void resetBoard() {
        for (int[] row : board) Arrays.fill(row, 0);
    }

    /** Returns 0 = none, 1 = X wins, 2 = O wins */
    private int getWinner() {
        // rows / cols
        for (int i = 0; i < 3; i++) {
            if (board[i][0] != 0 &&
                board[i][0] == board[i][1] && board[i][1] == board[i][2])
                return board[i][0];
            if (board[0][i] != 0 &&
                board[0][i] == board[1][i] && board[1][i] == board[2][i])
                return board[0][i];
        }
        // diagonals
        if (board[0][0] != 0 &&
            board[0][0] == board[1][1] && board[1][1] == board[2][2])
            return board[0][0];
        if (board[0][2] != 0 &&
            board[0][2] == board[1][1] && board[1][1] == board[2][0])
            return board[0][2];
        return 0;
    }

    private boolean isBoardFull() {
        for (int[] row : board) for (int v : row) if (v == 0) return false;
        return true;
    }

    /** --------------------------------------------------------------
     *  Inner class handling one client connection
     *  -------------------------------------------------------------- */
    private class ClientHandler implements Runnable {

        private final Socket socket;
        private final BufferedReader in;
        private final BufferedWriter out;
        private int playerId; // 1 = X, 2 = O

        ClientHandler(Socket socket) throws IOException {
            this.socket = socket;
            this.in = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
            this.out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));
        }

        void setPlayerId(int id) { this.playerId = id; }

        void send(String line) {
            try {
                out.write(line);
                out.write("\n");
                out.flush();
            } catch (IOException e) {
                System.err.println("Failed to send to client " + playerId + ": " + e);
            }
        }

        @Override
        public void run() {
            try {
                String line;
                while ((line = in.readLine()) != null) {
                    // System.out.println("Received from client " + playerId + ": " + line);
                    handle(line.trim());
                }
            } catch (IOException e) {
                System.err.println("Client " + playerId + " disconnected.");
            } finally {
                try { socket.close(); } catch (IOException ignored) {}
            }
        }

        /** Process a single message from the client */
        private void handle(String msg) {
            if (!gameRunning) return; // ignore stray messages

            if (msg.startsWith("MOVE")) {
                // Syntax: MOVE r c   (client never sends symbol)
                String[] parts = msg.split("\\s+");
                if (parts.length != 3) return; // ignore malformed

                int r = Integer.parseInt(parts[1]);
                int c = Integer.parseInt(parts[2]);

                // Is it this player's turn?
                if (playerId != currentPlayer) {
                    // illegal turn, silently ignore
                    return;
                }

                // Is the cell empty?
                if (board[r][c] != 0) {
                    // illegal move, ignore
                    return;
                }

                // Accept the move
                board[r][c] = playerId;
                broadcastMove(r, c);
                checkGameStatus();

                // Switch turn (if still running)
                if (gameRunning) {
                    currentPlayer = (currentPlayer == 1) ? 2 : 1;
                }
            } else if (msg.equalsIgnoreCase("QUIT")) {
                // Nothing special – just break out of loop in run()
                try { socket.close(); } catch (IOException ignored) {}
            }
        }
    }
}
```

### How the server works

* **Main thread** opens a `ServerSocket` and waits until **exactly two** clients connect.
* Each client is wrapped into a `ClientHandler` that runs on its own thread, reading lines from the socket.
* After the second client connects, `startGame()` is called:
  * The board is cleared.
  * Client 0 receives `START X`, client 1 receives `START O`.
* When a client sends `MOVE r c`, the handler validates:
  * Is it that client’s turn?
  * Is the cell vacant?
* If validation passes, the move is stored, then **both** clients receive `MOVE r c X|O`. Afterwards the server checks for win/draw, broadcasting `WIN …` or `DRAW` if the game is over.

> **Note** – The server does **not** enforce a timeout or reconnect logic – it is intentionally simple. Feel free to add those features later.

