## 4. The Client – `GameClient.java`

```java
package client;

import javafx.application.*;
import javafx.geometry.*;
import javafx.scene.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class GameClient {

    // -----------------------------------------------------------------
    // UI elements (created by the JavaFX Application)
    // -----------------------------------------------------------------
    private final Button[][] cells = new Button[3][3];
    private final Label statusLabel = new Label("Connecting…");
    private Stage primaryStage;

    // -----------------------------------------------------------------
    // Network fields
    // -----------------------------------------------------------------
    private Socket socket;
    private BufferedReader in;
    private BufferedWriter out;
    private ExecutorService executor = Executors.newSingleThreadExecutor();

    // -----------------------------------------------------------------
    // Game state
    // -----------------------------------------------------------------
    private String mySymbol;      // "X" or "O"
    private boolean myTurn = false;

    // -----------------------------------------------------------------
    // PUBLIC entry point – called from JavaFX Application start()
    // -----------------------------------------------------------------
    public void start(Stage stage, String host, int port) {
        this.primaryStage = stage;
        initUI();
        connect(host, port);
    }

    // -----------------------------------------------------------------
    // Build a tiny 3×3 grid of buttons
    // -----------------------------------------------------------------
    private void initUI() {
        GridPane grid = new GridPane();
        grid.setAlignment(Pos.CENTER);
        grid.setHgap(5);
        grid.setVgap(5);
        grid.setPadding(new Insets(10));

        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                Button b = new Button(" ");
                b.setPrefSize(80, 80);
                final int row = r, col = c;
                b.setOnAction(e -> onCellClicked(row, col));
                cells[r][c] = b;
                grid.add(b, c, r);
            }
        }

        VBox root = new VBox(10, statusLabel, grid);
        root.setAlignment(Pos.CENTER);
        root.setPadding(new Insets(10));

        primaryStage.setScene(new Scene(root));
        primaryStage.setTitle("Tic‑Tac‑Toe – client");
        primaryStage.setOnCloseRequest(e -> shutdown());
        primaryStage.show();
    }

    // -----------------------------------------------------------------
    // Button click handler – only sends a move when it is our turn.
    // -----------------------------------------------------------------
    private void onCellClicked(int r, int c) {
        if (!myTurn) {
            statusLabel.setText("Not your turn.");
            return;
        }
        if (!cells[r][c].getText().equals(" ")) {
            statusLabel.setText("Cell already occupied.");
            return;
        }
        send("MOVE " + r + " " + c);
    }

    // -----------------------------------------------------------------
    // Open the TCP connection and start a background listener.
    // -----------------------------------------------------------------
    private void connect(String host, int port) {
        executor.submit(() -> {
            try {
                socket = new Socket(host, port);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
                out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));
                Platform.runLater(() -> statusLabel.setText("Connected – waiting for opponent…"));
                listenLoop();
            } catch (IOException e) {
                Platform.runLater(() -> statusLabel.setText("Failed to connect: " + e.getMessage()));
            }
        });
    }

    /** Send a line to the server */
    private void send(String line) {
        executor.submit(() -> {
            try {
                out.write(line);
                out.write("\n");
                out.flush();
            } catch (IOException e) {
                Platform.runLater(() -> statusLabel.setText("Error sending: " + e.getMessage()));
            }
        });
    }

    /** Continuously read messages from the server */
    private void listenLoop() {
        try {
            String line;
            while ((line = in.readLine()) != null) {
                String msg = line.trim();
                // System.out.println("SERVER → " + msg);
                Platform.runLater(() -> handleServerMessage(msg));
            }
        } catch (IOException e) {
            Platform.runLater(() -> statusLabel.setText("Connection lost."));
        }
    }

    // -----------------------------------------------------------------
    // Process a single line received from the server.
    // -----------------------------------------------------------------
    private void handleServerMessage(String msg) {
        if (msg.startsWith("START")) {
            mySymbol = msg.split("\\s+")[1];
            myTurn = mySymbol.equals("X"); // X always starts
            statusLabel.setText(myTurn ? "Your turn (you are " + mySymbol + ")" : "Opponent's turn (you are " + mySymbol + ")");
            clearBoard();
        } else if (msg.startsWith("MOVE")) {
            // MESSAGE: MOVE r c X|O
            String[] parts = msg.split("\\s+");
            int r = Integer.parseInt(parts[1]);
            int c = Integer.parseInt(parts[2]);
            String sym = parts[3];
            cells[r][c].setText(sym);
            // Toggle turn if game still active
            if (sym.equals(mySymbol)) {
                // I just placed my mark – now opponent's turn
                myTurn = false;
                statusLabel.setText("Opponent's turn");
            } else {
                // Opponent just placed – my turn now
                myTurn = true;
                statusLabel.setText("Your turn");
            }
        } else if (msg.startsWith("WIN")) {
            String winner = msg.split("\\s+")[1];
            if (winner.equals(mySymbol))
                statusLabel.setText("You win! (" + winner + ")");
            else
                statusLabel.setText("You lose. (" + winner + " won)");
            myTurn = false;
        } else if (msg.equals("DRAW")) {
            statusLabel.setText("Draw!");
            myTurn = false;
        } else if (msg.equals("RESET")) {
            clearBoard();
            statusLabel.setText("Game reset – waiting for start...");
        }
    }

    /** Empty all cells */
    private void clearBoard() {
        for (Button[] row : cells) {
            for (Button b : row) {
                b.setText(" ");
            }
        }
    }

    /** Clean shutdown – close socket and thread pool */
    private void shutdown() {
        try {
            if (out != null) send("QUIT");
            if (socket != null) socket.close();
        } catch (IOException ignored) { }
        executor.shutdownNow();
        Platform.exit();
    }
}
```

### What the client does

1. **UI** – a 3×3 grid of `Button`s, each representing a cell, and a `Label` for status messages.  
2. **Networking** – opens a socket to the server on a background thread (`ExecutorService`).  
3. **Message handling** – updates the UI on the JavaFX Application Thread (`Platform.runLater`).  
4. **Turn management** – the client only sends a `MOVE` when `myTurn == true`. The server enforces the rule as well, so a stray click is harmless.  

> **Tip** – The client code deliberately does **not** use `javafx.concurrent.Task` because a single `ExecutorService` is enough for this very light protocol.

