## 3️⃣ Server 端代码（实时捕获 + TCP 发送）

```java
package com.example.videostream;

import org.bytedeco.javacv.*;
import org.bytedeco.opencv.global.opencv_imgcodecs;
import org.bytedeco.opencv.opencv_core.Mat;

import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.ByteBuffer;

public class VideoServer {

    /** TCP 端口（客户端需要用同一个端口） */
    private static final int PORT = 9999;
    /** 摄像头设备序号（0 为默认摄像头），也可以是视频文件路径 */
    private static final String INPUT_SOURCE = "0";   // "0" => webcam, "video.mp4" => file

    /** 是否对每帧做 JPEG 压缩（推荐） */
    private static final boolean USE_JPEG = true;
    /** JPEG 质量（0~100），越大文件越大、画质越好 */
    private static final int JPEG_QUALITY = 80;

    public static void main(String[] args) throws Exception {
        // 1️⃣ 启动 ServerSocket
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println("[Server] Listening on port " + PORT + " ...");

        // 2️⃣ 等待客户端连接（阻塞）
        Socket client = serverSocket.accept();
        System.out.println("[Server] Client connected: " + client.getRemoteSocketAddress());

        // 3️⃣ 打开视频源 (FFmpegFrameGrabber 支持摄像头、文件、rtsp、rtmp 等)
        FFmpegFrameGrabber grabber = createGrabber(INPUT_SOURCE);
        grabber.start();

        // 4️⃣ 用 DataOutputStream 进行“长度+数据”写入
        try (DataOutputStream dos = new DataOutputStream(new BufferedOutputStream(client.getOutputStream()))) {
            Frame frame;
            int frameIdx = 0;
            while ((frame = grabber.grabImage()) != null) { // 只抓取图像帧，忽略音频
                // 5️⃣ Frame -> Mat
                OpenCVFrameConverter.ToMat matConv = new OpenCVFrameConverter.ToMat();
                Mat mat = matConv.convert(frame);
                if (mat == null) continue; // 有时会出现 null

                // 6️⃣ 编码为 JPEG（或直接取 raw 数据）
                byte[] imageBytes;
                if (USE_JPEG) {
                    // imencode 会返回一个 Mat (1xN) 保存 JPEG 数据
                    Mat buf = new Mat();
                    // [int] params: [IMWRITE_JPEG_QUALITY, quality]
                    opencv_imgcodecs.imencode(".jpg", mat, buf, new int[]{opencv_imgcodecs.IMWRITE_JPEG_QUALITY, JPEG_QUALITY});
                    imageBytes = buf.data().getStringBytes();
                } else {
                    // raw BGR24（每像素 3 字节），不建议直接传输，体积太大
                    imageBytes = new byte[mat.arraySize()];
                    mat.data().get(imageBytes);
                }

                // 7️⃣ 发送 “长度(4B) + 数据”
                dos.writeInt(imageBytes.length);   // 大端 byteorder（DataOutputStream 固定）
                dos.write(imageBytes);
                dos.flush(); // 立即把数据写出，避免长时间缓冲

                // 8️⃣ 计数/日志
                frameIdx++;
                if (frameIdx % 30 == 0) { // 每 30 帧打印一次（约 1 秒）
                    System.out.printf("[Server] Sent %d frames, last size=%d B%n", frameIdx, imageBytes.length);
                }

                // 9️⃣ 控制帧率（可选），这里限制为 30 FPS
                Thread.sleep(33); // 1000ms/30 ≈ 33ms
            }
        } finally {
            // 10️⃣ 资源释放
            grabber.stop();
            client.close();
            serverSocket.close();
            System.out.println("[Server] stopped.");
        }
    }

    /** 创建并配置 FFmpegFrameGrabber */
    private static FFmpegFrameGrabber createGrabber(String src) throws Exception {
        FFmpegFrameGrabber grabber;
        // “0” / “1” 等字符串会被当作摄像头编号；否则视为文件/URL
        try {
            int deviceIdx = Integer.parseInt(src);
            grabber = new FFmpegFrameGrabber(deviceIdx);
        } catch (NumberFormatException e) {
            grabber = new FFmpegFrameGrabber(src);
        }

        // 常见的抓取参数（根据实际需求可调）
        grabber.setImageWidth(640);
        grabber.setImageHeight(480);
        grabber.setFormat("dshow"); // windows 摄像头；Linux 用 "v4l2"，Mac 用 "avfoundation"
        // 以下两行在文件/rtsp 场景下可能更有用：
        // grabber.setOption("rtsp_transport", "tcp");
        // grabber.setVideoCodec(avutil.AV_CODEC_ID_H264);
        return grabber;
    }
}
```

### 关键点解释

| 步骤 | 说明 |
|------|------|
| `FFmpegFrameGrabber` | 支持摄像头、文件、RTSP、RTMP、HLS 等多种输入源。可通过 `setFormat` 指定平台（`dshow`、`v4l2`、`avfoundation`）。 |
| `grabber.grabImage()` | 只抓图像帧（不解码音频），返回 `Frame`。 |
| `OpenCVFrameConverter.ToMat` | 把 JavaCV `Frame` 转成 OpenCV `Mat`，便于 `imencode`。 |
| `imencode(".jpg", mat, buf, ...)` | 将 `Mat` JPEG 编码到 `buf`（单行 `Mat`），再取出 `byte[]`。压缩比高、传输流量小。 |
| `DataOutputStream.writeInt(len)` + `write(byte[])` | 使用 **4 Byte big‑endian** 长度前缀，客户端可以准确读完一帧。 |
| `Thread.sleep(33)` | 限速至 30 FPS，防止 CPU 持续 100%（如果抓取本身已经限速，可去掉）。 |

> **如果想要更低延迟**：  
> - 用 **UDP** 替代 TCP（自己实现分片 + 丢包处理），或使用 **Netty**、**RTP**。  
> - 直接把 **H.264 NALU** 发出去（不再 JPEG），这样带宽更低，解码端用 `FFmpegFrameGrabber` 读取流。  
> - 采用 **WebSocket** + **Canvas** 在浏览器端显示（后面会提到）。  

