## 3️⃣ 客服端（Server）代码

### 3.1 主入口 + UI

```java
package com.ecom.server;

import com.ecom.common.Message;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class ChatServer {

    // 端口
    private static final int PORT = 9999;
    // 线程池（最大 50 条并发连接，实际业务可调）
    private final ExecutorService threadPool = Executors.newFixedThreadPool(50);
    private ServerSocket serverSocket;

    // UI 相关
    private JFrame frame;
    private DefaultListModel<ClientSession> listModel = new DefaultListModel<>();

    // 会话映射 <sessionId, ClientSession>
    private final Map<Integer, ClientSession> sessions = new ConcurrentHashMap<>();

    // 用于生成递增的 sessionId
    private final AtomicInteger sessionIdGenerator = new AtomicInteger(1000);

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try {
                new ChatServer().start();
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
    }

    // -------------------------------------------------------
    private void start() throws IOException {
        // ---- UI 初始化 ----
        initUI();

        // ---- 启动服务器监听线程 ----
        serverSocket = new ServerSocket(PORT);
        new Thread(this::acceptLoop, "Accept-Thread").start();
        logSystem("服务器已启动，监听端口 " + PORT);
    }

    // -------------------------------------------------------
    private void initUI() {
        frame = new JFrame("电商客服系统 - 服务器端");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(400, 600);
        frame.setLocationRelativeTo(null);

        JList<ClientSession> clientList = new JList<>(listModel);
        clientList.setCellRenderer(new SessionCellRenderer());

        // 双击打开聊天窗口
        clientList.addMouseListener(new MouseAdapter() {
            public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2) {
                    ClientSession cs = clientList.getSelectedValue();
                    if (cs != null) {
                        SwingUtilities.invokeLater(() -> new ChatWindow(cs).setVisible(true));
                    }
                }
            }
        });

        frame.add(new JScrollPane(clientList), BorderLayout.CENTER);
        frame.setVisible(true);
    }

    // -------------------------------------------------------
    /** 接受新客户端的连接 */
    private void acceptLoop() {
        while (!serverSocket.isClosed()) {
            try {
                Socket client = serverSocket.accept();   // 阻塞
                // 为每个新连接创建一个唯一的 sessionId
                int sessionId = sessionIdGenerator.incrementAndGet();
                ClientSession session = new ClientSession(sessionId, client);
                sessions.put(sessionId, session);

                // UI 提示客服是否接受
                SwingUtilities.invokeLater(() -> {
                    int opt = JOptionPane.showConfirmDialog(frame,
                            "新用户请求服务 (id=" + sessionId + ")\n是否接受？",
                            "新用户请求", JOptionPane.YES_NO_OPTION);
                    if (opt == JOptionPane.YES_OPTION) {
                        // 加入列表，开始接收消息
                        listModel.addElement(session);
                        threadPool.submit(() -> handleClient(session));
                        sendSystemMessage(session, "客服已接受，您可以开始聊天。");
                    } else {
                        // 拒绝后直接关闭
                        sendSystemMessage(session, "客服暂时忙碌，已拒绝本次聊天。");
                        session.close();
                        sessions.remove(sessionId);
                    }
                });

            } catch (IOException ex) {
                ex.printStackTrace();
            }
        }
    }

    // -------------------------------------------------------
    /** 与单个客户的通信循环（阻塞读取） */
    private void handleClient(ClientSession session) {
        try (InputStream in = session.getSocket().getInputStream()) {
            while (!session.isClosed()) {
                Message msg = Message.readFrom(in); // 阻塞读取一条完整消息
                // 把消息写入本地聊天记录（统一保存的 log 文件）
                ChatHistory.append(session.getSessionId(), msg);
                // 发送到对应的 ChatWindow（如果已经打开）
                session.dispatchMessage(msg);
            }
        } catch (EOFException eof) {
            logSystem("用户 (id=" + session.getSessionId() + ") 已离线。");
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            // 清理工作
            session.close();
            SwingUtilities.invokeLater(() -> listModel.removeElement(session));
            sessions.remove(session.getSessionId());
        }
    }

    // -------------------------------------------------------
    private void sendSystemMessage(ClientSession session, String txt) {
        try {
            Message sys = new Message(Message.SYSTEM, session.getSessionId(),
                    txt.getBytes("UTF-8"));
            session.send(sys);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void logSystem(String txt) {
        System.out.println("[SERVER] " + txt);
    }

    // -------------------------------------------------------
    /** 客户端会话对象（保存 socket、id、窗口引用） */
    static class ClientSession {
        private final int sessionId;
        private final Socket socket;
        private volatile boolean closed = false;
        private ChatWindow window; // 可能为 null

        ClientSession(int id, Socket s) {
            this.sessionId = id;
            this.socket = s;
        }

        int getSessionId() { return sessionId; }
        Socket getSocket() { return socket; }
        boolean isClosed() { return closed; }

        /** 发送消息给客户端 */
        void send(Message msg) throws IOException {
            OutputStream out = socket.getOutputStream();
            msg.writeTo(out);
        }

        /** 关闭会话 */
        void close() {
            closed = true;
            try { socket.close(); } catch (IOException ignored) {}
        }

        /** 当收到新消息时，转发给已经打开的聊天窗口 */
        void dispatchMessage(Message msg) {
            if (window != null) {
                window.receiveMessage(msg);
            }
        }

        void setChatWindow(ChatWindow win) { this.window = win; }
    }

    // -------------------------------------------------------
    /** 左侧列表的渲染（显示会话 ID、是否在线等） */
    static class SessionCellRenderer extends DefaultListCellRenderer {
        public Component getListCellRendererComponent(
                JList<?> list, Object value, int index,
                boolean isSelected, boolean cellHasFocus) {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof ClientSession cs) {
                setText("用户 #" + cs.getSessionId());
            }
            return this;
        }
    }

    // =======================================================
    /** 聊天窗口（单个会话的 UI） */
    class ChatWindow extends JFrame {

        private final ClientSession session;
        private final JTextPane chatArea = new JTextPane();
        private final JTextField inputField = new JTextField();
        private final JButton sendBtn = new JButton("发送");
        private final JButton fileBtn = new JButton("文件/图片");

        ChatWindow(ClientSession sess) {
            super("客服与用户 #" + sess.getSessionId());
            this.session = sess;
            sess.setChatWindow(this); // 关联

            setSize(500, 600);
            setLocationRelativeTo(frame);
            setLayout(new BorderLayout());

            chatArea.setEditable(false);
            chatArea.setContentType("text/html"); // 支持图片 & 链接
            JScrollPane scroll = new JScrollPane(chatArea);
            add(scroll, BorderLayout.CENTER);

            JPanel bottom = new JPanel(new BorderLayout(5,5));
            bottom.add(inputField, BorderLayout.CENTER);
            bottom.add(sendBtn, BorderLayout.EAST);
            bottom.add(fileBtn, BorderLayout.WEST);
            add(bottom, BorderLayout.SOUTH);

            // 加载历史记录（如果有）
            loadHistory();

            // 发送文字
            sendBtn.addActionListener(e -> sendText());
            inputField.addActionListener(e -> sendText());

            // 发送图片/文件
            fileBtn.addActionListener(e -> sendFileOrImage());

            // 窗口关闭时解除关联
            addWindowListener(new WindowAdapter() {
                public void windowClosing(WindowEvent e) {
                    session.setChatWindow(null);
                    dispose();
                }
            });
        }

        /** 读取历史记录并在 UI 中展示 */
        private void loadHistory() {
            List<Message> history = ChatHistory.load(session.getSessionId());
            for (Message msg : history) {
                displayMessage(msg);
            }
        }

        /** 发送文字 */
        private void sendText() {
            String txt = inputField.getText().trim();
            if (txt.isEmpty()) return;
            try {
                Message m = new Message(Message.TEXT, session.getSessionId(),
                        txt.getBytes("UTF-8"));
                session.send(m);
                displayMessage(m);               // 本端立即显示
                ChatHistory.append(session.getSessionId(), m);
                inputField.setText("");
            } catch (IOException e) {
                showError(e.getMessage());
            }
        }

        /** 发送图片或文件 */
        private void sendFileOrImage() {
            JFileChooser chooser = new JFileChooser();
            chooser.setMultiSelectionEnabled(false);
            int ret = chooser.showOpenDialog(this);
            if (ret != JFileChooser.APPROVE_OPTION) return;

            File file = chooser.getSelectedFile();
            try {
                byte[] data = java.nio.file.Files.readAllBytes(file.toPath());
                int type = isImage(file) ? Message.IMAGE : Message.FILE;
                Message m = new Message(type, session.getSessionId(), data);
                session.send(m);
                displayMessage(m);
                ChatHistory.append(session.getSessionId(), m);
            } catch (IOException e) {
                showError(e.getMessage());
            }
        }

        /** 判断文件是否为图片（最简单的依据拓展名） */
        private boolean isImage(File f) {
            String name = f.getName().toLowerCase();
            return name.endsWith(".png") || name.endsWith(".jpg")
                    || name.endsWith(".jpeg") || name.endsWith(".gif")
                    || name.endsWith(".bmp");
        }

        /** 收到远端消息的回调（由 ClientSession 调用） */
        public void receiveMessage(Message msg) {
            SwingUtilities.invokeLater(() -> displayMessage(msg));
        }

        /** 将 Message 按类型渲染到 chatArea */
        private void displayMessage(Message msg) {
            try {
                String html;
                switch (msg.getType()) {
                    case Message.TEXT -> {
                        String txt = new String(msg.getData(), "UTF-8");
                        html = "<div style='color:blue; margin:5px;'>"
                                + "<b>用户 #"+msg.getSessionId()+":</b> "
                                + escapeHtml(txt) + "</div>";
                    }
                    case Message.IMAGE -> {
                        // 将字节数组写入临时文件再生成 src
                        String path = saveTempFile(msg.getData(),
                                "img_"+System.currentTimeMillis()+".png");
                        html = "<div style='margin:5px;'><b>用户 #"+msg.getSessionId()+":</b><br>"
                                + "<img src='file:" + path + "' width='200'/></div>";
                    }
                    case Message.FILE -> {
                        String path = saveTempFile(msg.getData(),
                                "file_"+System.currentTimeMillis());
                        html = "<div style='margin:5px;'><b>用户 #"+msg.getSessionId()+":</b>"
                                + " <a href='file:" + path + "'>下载文件</a></div>";
                    }
                    case Message.SYSTEM -> {
                        String txt = new String(msg.getData(), "UTF-8");
                        html = "<div style='color:gray; margin:5px; font-style:italic;'>"
                                + escapeHtml(txt) + "</div>";
                    }
                    default -> html = "";
                }
                // 追加到 JTextPane
                javax.swing.text.Document doc = chatArea.getDocument();
                ((javax.swing.text.html.HTMLDocument) doc).insertAfterEnd(
                        doc.getDefaultRootElement(), html);
                // 自动滚动到底部
                chatArea.setCaretPosition(chatArea.getDocument().getLength());
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        /** 将二进制写成临时文件，返回绝对路径 */
        private String saveTempFile(byte[] data, String suffix) throws IOException {
            File tmp = File.createTempFile("chat_", "_" + suffix);
            try (FileOutputStream fos = new FileOutputStream(tmp)) {
                fos.write(data);
            }
            tmp.deleteOnExit(); // 程序结束后自动清理
            return tmp.getAbsolutePath();
        }

        private String escapeHtml(String s) {
            return s.replace("&","&amp;")
                    .replace("<","&lt;")
                    .replace(">","&gt;")
                    .replace("\n","<br/>");
        }

        private void showError(String msg) {
            JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE);
        }
    }
}
```

> **核心流程解释**  
> 1. **`acceptLoop()`**：服务器监听端口，每有新连接就产生一个 `ClientSession` 并立刻弹框询问客服是否接收。  
> 2. **`handleClient()`**：为每个接受的会话启动一个 **独立线程**（线程池），负责 `Message.readFrom()` 循环读取客户端发来的数据。  
> 3. **聊天记录**：每收到一条 `Message`，立即调用 `ChatHistory.append()` 将其追加到本地文件（后面会给出实现）。  
> 4. **UI 与会话的桥接**：`ClientSession` 持有 `ChatWindow` 的引用，收到新消息时直接调用 `window.receiveMessage(msg)` 在 Swing 线程中渲染。  

