    // 网络
    private Socket socket;
    private ExecutorService exec = Executors.newSingleThreadExecutor();
    private volatile boolean connected = false;
    private int sessionId; // 本客户端的唯一 id（由服务器分配）

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ChatClient().showUI());
    }

    // -------------------------------------------------------
    private void showUI() {
        frame = new JFrame("电商客服系统 - 用户端");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(500, 600);
        frame.setLocationRelativeTo(null);
        frame.setLayout(new BorderLayout());

        chatArea.setEditable(false);
        chatArea.setContentType("text/html");
        frame.add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout(5,5));
        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(sendBtn, BorderLayout.EAST);
        bottom.add(fileBtn, BorderLayout.WEST);
        frame.add(bottom, BorderLayout.SOUTH);

        // 绑定事件
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());
        fileBtn.addActionListener(e -> sendFileOrImage());

        // 启动连接流程
        connectToServer();

        frame.setVisible(true);
    }

    // -------------------------------------------------------
    /** 建立到服务器的 TCP 连接并启动接收线程 */
    private void connectToServer() {
        exec.submit(() -> {
            try {
                socket = new Socket();
                socket.connect(new InetSocketAddress(SERVER_IP, SERVER_PORT), CONNECT_TIMEOUT);
                connected = true;
                logSystem("已连接到客服服务器，等待客服响应…");

                // 等待服务器发送的系统消息，里面会携带分配给本客户端的 sessionId
                InputStream in = socket.getInputStream();
                Message first = Message.readFrom(in);
                if (first.getType() == Message.SYSTEM) {
                    String txt = new String(first.getData(), "UTF-8");
                    // 这里的协议约定：系统消息内容形如 "SESSION_ID:1234"
                    if (txt.startsWith("SESSION_ID:")) {
                        sessionId = Integer.parseInt(txt.substring(11));
                        logSystem("客服已接受本次会话（sessionId=" + sessionId + "），可开始聊天。");
                        // 加载历史记录（如果有）
                        loadHistory();
                    } else {
                        // 业务层可能返回 “客服忙碌” 之类的信息
                        logSystem("系统提示：" + txt);
                        socket.close();
                        connected = false;
                        return;
                    }
                }

                // 启动接收循环
                while (connected && !socket.isClosed()) {
                    Message msg = Message.readFrom(in);
                    // 保存到本地历史文件
                    ChatHistory.append(sessionId, msg);
                    // UI 渲染
                    SwingUtilities.invokeLater(() -> displayMessage(msg));
                }

            } catch (SocketTimeoutException toe) {
                logSystem("连接超时（" + CONNECT_TIMEOUT/1000 + " 秒），客服可能忙碌。");
                showBusyDialog();
            } catch (IOException e) {
                logSystem("网络异常：" + e.getMessage());
                e.printStackTrace();
            } finally {
                connected = false;
            }
        });
    }

    // -------------------------------------------------------
    private void loadHistory() {
        List<Message> history = ChatHistory.load(sessionId);
        for (Message m : history) {
            displayMessage(m);
        }
    }

    // -------------------------------------------------------
    private void sendText() {
        if (!connected) {
            showError("未连接到客服，请稍后重试。");
            return;
        }
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message m = new Message(Message.TEXT, sessionId,
                    txt.getBytes("UTF-8"));
            m.writeTo(socket.getOutputStream());
            displayMessage(m); // 自己也要展示
            ChatHistory.append(sessionId, m);
            inputField.setText("");
        } catch (IOException e) {
            showError(e.getMessage());
        }
    }

    private void sendFileOrImage() {
        if (!connected) {
            showError("未连接到客服，请稍后重试。");
            return;
        }
        JFileChooser chooser = new JFileChooser();
        chooser.setMultiSelectionEnabled(false);
        int ret = chooser.showOpenDialog(frame);
        if (ret != JFileChooser.APPROVE_OPTION) return;

        File file = chooser.getSelectedFile();
        try {
            byte[] data = java.nio.file.Files.readAllBytes(file.toPath());
            int type = isImage(file) ? Message.IMAGE : Message.FILE;
            Message m = new Message(type, sessionId, data);
            m.writeTo(socket.getOutputStream());
            displayMessage(m);
            ChatHistory.append(sessionId, m);
        } catch (IOException e) {
            showError(e.getMessage());
        }
    }

    private boolean isImage(File f) {
        String n = f.getName().toLowerCase();
        return n.endsWith(".png") || n.endsWith(".jpg") || n.endsWith(".jpeg")
                || n.endsWith(".gif") || n.endsWith(".bmp");
    }

    // -------------------------------------------------------
    /** 将从服务器收到的 Message 渲染到聊天窗口 */
    private void displayMessage(Message m) {
        try {
            String html;
            switch (m.getType()) {
                case Message.TEXT -> {
                    String txt = new String(m.getData(), "UTF-8");
                    html = "<div style='color:green;margin:5px;'><b>客服:</b> "
                            + escapeHtml(txt) + "</div>";
                }
                case Message.IMAGE -> {
                    String path = saveTempFile(m.getData(),
                            "img_"+System.currentTimeMillis()+".png");
                    html = "<div style='margin:5px;'><b>客服:</b><br>"
                            + "<img src='file:" + path + "' width='200'/></div>";
                }
                case Message.FILE -> {
                    String path = saveTempFile(m.getData(),
                            "file_"+System.currentTimeMillis());
                    html = "<div style='margin:5px;'><b>客服:</b>"
                            + " <a href='file:" + path + "'>下载文件</a></div>";
                }
                case Message.SYSTEM -> {
                    String txt = new String(m.getData(), "UTF-8");
                    html = "<div style='color:gray;font-style:italic;margin:5px;'>"
                            + escapeHtml(txt) + "</div>";
                }
                default -> html = "";
            }
            javax.swing.text.Document doc = chatArea.getDocument();
            ((javax.swing.text.html.HTMLDocument) doc).insertAfterEnd(
                    doc.getDefaultRootElement(), html);
            chatArea.setCaretPosition(chatArea.getDocument().getLength());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private String saveTempFile(byte[] data, String suffix) throws IOException {
        File tmp = File.createTempFile("chat_", "_" + suffix);
        try (FileOutputStream fos = new FileOutputStream(tmp)) {
            fos.write(data);
        }
        tmp.deleteOnExit();
        return tmp.getAbsolutePath();
    }

    private String escapeHtml(String s) {
        return s.replace("&","&amp;")
                .replace("<","&lt;")
                .replace(">","&gt;")
                .replace("\n","<br/>");
    }

    // -------------------------------------------------------
    private void showBusyDialog() {
        SwingUtilities.invokeLater(() ->
                JOptionPane.showMessageDialog(frame,
                        "客服当前繁忙，请稍后再试。",
                        "忙碌提示", JOptionPane.INFORMATION_MESSAGE));
    }

    private void showError(String msg) {
        SwingUtilities.invokeLater(() ->
                JOptionPane.showMessageDialog(frame, msg, "错误", JOptionPane.ERROR_MESSAGE));
    }

    private void logSystem(String txt) {
        System.out.println("[CLIENT] " + txt);
    }
}
```

> **说明**  
> * **连接 & 超时**：`connectToServer()` 使用 `Socket.connect(..., timeout)`，若在 `CONNECT_TIMEOUT` 内没有收到服务器系统应答，则弹出“客服忙碌”提示。  
> * **系统消息协议**：服务器的第一条消息必须是 `SYSTEM`，内容形如 `SESSION_ID:1234`（或 `BUSY`），本客户端依据此判断是否进入聊天。  
> * **聊天记录**：与服务器端同样使用 `ChatHistory` 实现，文件保存在本地 `chat_history/` 目录，文件名为 `session_<id>.log`。

---

## 5️⃣ 聊天记录持久化（通用类）

> **文件格式**：采用 **对象序列化**（`ObjectOutputStream`）+ **追加写入**。  
> 每条记录完整保存 `Message` 对象，读取时直接反序列化为 `Message` 列表。  
> 也可以改为 JSON、SQLite 等，这里只演示最简实现。

```java
package com.ecom.common;

import java.io.*;
import java.nio.file.*;
import java.util.*;

/**
 * 简单的聊天记录持久化工具。
 * 文件目录: ./chat_history/
 * 文件名: session_<sessionId>.log
 */
public class ChatHistory {

    private static final Path ROOT = Paths.get("chat_history");

    static {
        try {
            if (!Files.exists(ROOT)) Files.createDirectory(ROOT);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 追加一条消息到相应会话的日志文件 */
    public static synchronized void append(int sessionId, Message msg) {
        Path p = fileOf(sessionId);
        try (ObjectOutputStream oos = new AppendableObjectOutputStream(
                new BufferedOutputStream(Files.newOutputStream(p,
                        StandardOpenOption.CREATE, StandardOpenOption.APPEND)))) {
            oos.writeObject(msg);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 读取完整的历史记录（如果文件不存在返回空集合） */
    public static synchronized List<Message> load(int sessionId) {
        Path p = fileOf(sessionId);
        List<Message> list = new ArrayList<>();
        if (!Files.exists(p)) return list;
        try (ObjectInputStream ois = new ObjectInputStream(
                new BufferedInputStream(Files.newInputStream(p)))) {
            while (true) {
                Object obj = ois.readObject();
                if (obj instanceof Message m) {
                    list.add(m);
                }
            }
        } catch (EOFException eof) {
            // 正常结束
        } catch (Exception e) {
            e.printStackTrace();
        }
        return list;
    }

    /** 生成日志文件路径 */
    private static Path fileOf(int sessionId) {
        return ROOT.resolve("session_" + sessionId + ".log");
    }

    /**
     * 为了实现 **追加写入**，ObjectOutputStream 必须在每次打开时 **不写入头部**，
     * 否则文件会在中间出现多个流头导致读取错误。下面的类在第 1 次写入后，
     * 之后的实例化会跳过写入头部。
     */
    private static class AppendableObjectOutputStream extends ObjectOutputStream {
        AppendableObjectOutputStream(OutputStream out) throws IOException {
            super(out);
        }

        @Override
        protected void writeStreamHeader() throws IOException {
            // 只在文件为空时写头，追加时跳过
            if (((FileOutputStream)out).getChannel().position() == 0) {
                super.writeStreamHeader();
            } else {
                reset(); // 防止写入额外的 header
            }
        }
    }
}
```

> **关键点**  
> 1. **同步**：`append`、`load` 都使用 `synchronized`，防止多线程并发写导致文件损坏。  
> 2. **追加写**：自定义 `AppendableObjectOutputStream`，确保每条记录后面没有多余的流头。  
> 3. **目录**：第一次运行会自动创建 `chat_history` 目录。  

---

## 6️⃣ 程序运行步骤（完整流程）

| 步骤 | 操作 |
|------|------|
| 1️⃣ | **编译**：把 `com.ecom.common`、`com.ecom.server` 放在同一个工程或两个 Maven 项目，确保 `Message.java` 与 `ChatHistory.java` 被两端共享。 |
| 2️⃣ | **启动服务器**：运行 `ChatServer.main`，弹出主窗体（左侧用户列表）。 |
| 3️⃣ | **启动客户端**：运行 `ChatClient.main`（可以打开多个实例模拟多个用户）。 |
| 4️⃣ | **等待客服响应**：客户端会显示 `等待客服响应…`，如果服务器弹窗 “接受” → 客服端会弹出 `新用户请求` 对话框，点 **是** 即进入聊天。 |
| 5️⃣ | **发送文字/图片/文件**：双方均可在输入框、文件按钮发送对应数据。发送后立即在本地 UI 中显示，并且会被追加到对应的 `session_*.log`。 |
| 6️⃣ | **关闭/重连**：关闭聊天窗口或关闭客户端，记录仍保留。下次同一用户再次连接（使用相同 `sessionId` 逻辑，服务器会重新分配），客户端会自动读取历史记录并展示。 |
| 7️⃣ | **异常处理**：网络断开、文件读写异常均会弹出对话框或在控制台输出，系统不会崩溃。 |

> **备注**：本示例使用 **阻塞 I/O**，适合教学/小规模演示。若业务量大或需要更低延迟，可改为 **NIO + Selector**，只需把 `Message.readFrom`/`writeTo` 换成 `ByteBuffer` + `Channel` 即可。

---

## 7️⃣ 常见问题 & 进阶建议

| 场景 | 解决思路 |
|------|----------|
| **客户端长时间没有收到客服的响应** | 本例使用 `CONNECT_TIMEOUT` 判定；若想更细致，可在服务端发送 `SYSTEM` 消息 `"BUSY"`，客户端收到后弹出“客服忙碌”。 |
| **图片/文件太大导致阻塞** | 在 `Message` 中先发送 **长度**，接收端使用 `DataInputStream.readFully` 读取指定长度；如果文件 > 10 MB，建议分块发送（自行实现 `ChunkedMessage`）。 |
| **多用户聊天记录文件冲突** | 每个会话单独文件 (`session_<id>.log`) 保证互不干扰。|
| **界面卡顿** | 所有网络 I/O 均放在 **独立线程**（`ExecutorService`），Swing 只负责 UI 更新（`SwingUtilities.invokeLater`）。|
| **想要持久化到数据库** | 把 `ChatHistory.append/load` 改为使用 **JDBC**（SQLite、MySQL）保存 `sessionId、timestamp、type、content`。|
| **想要客服端主动推送“离线消息”** | 在 `ClientSession` 中维护 **心跳**（如每 30 s 发送 `SYSTEM` 心跳），服务器检测不到心跳即标记离线。|

---

## 8️⃣ 完整代码结构（便于复制）

```
src/
 └─ com/
     └─ ecom/
         ├─ common/
         │   ├─ Message.java          // 协议
         │   └─ ChatHistory.java      // 持久化
         ├─ server/
         │   └─ ChatServer.java       // 服务器入口 + UI
         └─ client/
             └─ ChatClient.java       // 客户端入口 + UI
```

> 只要把以上 **7** 个 `.java` 文件编译运行，即可得到一个 **基于 Socket 的电商客服系统**，满足题目所列的全部功能：  
> * 多用户并发、客服接收/拒绝、文字/图片/文件双向传输、聊天记录持久化、超时/忙碌提示、异常处理、Swing 界面**。  

祝你玩得开心 🎉，如果后续想要加入语音、表情、群聊等高级特性，只需要在 **Message.type** 再扩展即可！如果还有细节实现或改进需求，欢迎随时提问。

