import java.io.*;
import java.util.*;

public class Admin {

    private static final String ADMIN_FILE   = "admin.txt";
    private static final String PLAYERS_FILE = "players.bin";

    private String adminHash;                 // SHA‑256 hash of admin password
    private List<Player> players;             // in‑memory list of all players

    /* ------------------------------------------------------------------ */
    /*  Constructor – loads admin password and player list from files      */
    /* ------------------------------------------------------------------ */
    public Admin() {
        loadAdminPassword();
        loadPlayers();
    }

    /* ------------------------------------------------------------------ */
    /*  1️⃣  ADMIN PASSWORD                                                            */
    /* ------------------------------------------------------------------ */
    private void loadAdminPassword() {
        File f = new File(ADMIN_FILE);
        if (!f.exists()) {
            // First‑time run – create a default admin password "admin"
            adminHash = Utility.getHash("admin");
            saveAdminPassword();
            System.out.println("admin.txt not found – created default admin password (admin)");
        } else {
            try (BufferedReader br = new BufferedReader(new FileReader(f))) {
                adminHash = br.readLine().trim();    // one line file
            } catch (IOException e) {
                throw new RuntimeException("Cannot read admin file", e);
            }
        }
    }

    private void saveAdminPassword() {
        try (PrintWriter out = new PrintWriter(new FileWriter(ADMIN_FILE))) {
            out.println(adminHash);
        } catch (IOException e) {
            throw new RuntimeException("Cannot write admin file", e);
        }
    }

    public boolean loginAdmin() {
        System.out.println("\n=== ADMIN LOGIN ===");
        String password = Keyboard.readString("Enter admin password > ");
        return adminHash.equals(Utility.getHash(password));
    }

    public void changeAdminPassword() {
        String newPass = Keyboard.readString("Enter new admin password > ");
        adminHash = Utility.getHash(newPass);
        saveAdminPassword();
        System.out.println("Admin password updated.");
    }

    /* ------------------------------------------------------------------ */
    /*  2️⃣  PLAYERS – binary file handling                                 */
    /* ------------------------------------------------------------------ */
    @SuppressWarnings("unchecked")
    private void loadPlayers() {
        File f = new File(PLAYERS_FILE);
        if (!f.exists()) {
            players = new ArrayList<>();
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            Object obj = ois.readObject();
            if (obj instanceof List) {
                players = (List<Player>) obj;
            } else {
                players = new ArrayList<>();
            }
        } catch (EOFException e) {
            // empty file – keep empty list
            players = new ArrayList<>();
        } catch (Exception e) {
            throw new RuntimeException("Cannot load players", e);
        }
    }

    private void savePlayers() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYERS_FILE))) {
            oos.writeObject(players);
        } catch (IOException e) {
            throw new RuntimeException("Cannot save players", e);
        }
    }

    /* ------------------------------------------------------------------ */
    /*  3️⃣  ADMIN MENU – loop until logout                               */
    /* ------------------------------------------------------------------ */
    public void run() {
        if (!loginAdmin()) {
            System.out.println("Wrong admin password – exiting.");
            return;
