        boolean stay = true;
        while (stay) {
            System.out.println("\n=== ADMIN MENU ===");
            String[] menu = {
                "Create a player",
                "Delete a player",
                "View all players",
                "Issue more chips to a player",
                "Reset a player's password",
                "Change administrator password",
                "Logout"
            };
            int choice = Keyboard.getUserOption("Select an option", menu);

            switch (choice) {
                case 1 -> createPlayer();
                case 2 -> deletePlayer();
                case 3 -> viewAllPlayers();
                case 4 -> issueChips();
                case 5 -> resetPlayerPassword();
                case 6 -> changeAdminPassword();
                case 7 -> {
                    stay = false;
                    System.out.println("Logging out admin.");
                }
                default -> System.out.println("Invalid choice");
            }
        }
    }

    /* ------------------------------------------------------------------ */
    /*  MENU ACTIONS                                                       */
    /* ------------------------------------------------------------------ */
    private void createPlayer() {
        String login = Keyboard.readString("Enter new player login name > ");
        // check duplicate
        if (findPlayer(login) != null) {
