        Player p = findPlayer(login);
        if (p == null) {
            System.out.println("Player not found.");
            return;
        }
        players.remove(p);
        savePlayers();
        System.out.println("Player '" + login + "' deleted.");
    }

    private void viewAllPlayers() {
        System.out.println("\n=== PLAYER LIST ===");
        if (players.isEmpty()) {
            System.out.println("(no players)");
            return;
        }
        for (Player p : players) {
