    private void issueChips() {
        String login = Keyboard.readString("Enter player login name > ");
        Player p = findPlayer(login);
        if (p == null) {
            System.out.println("Player not found.");
            return;
        }
        int amount = Keyboard.readInt("How many chips to give? > ");
        if (amount <= 0) {
            System.out.println("Amount must be positive.");
            return;
        }
        p.addChips(amount);
        savePlayers();
        System.out.println("Added " + amount + " chips to '" + login + "'. New total: " + p.getChips());
    }

    private void resetPlayerPassword() {
        String login = Keyboard.readString("Enter player login name > ");
        Player p = findPlayer(login);
        if (p == null) {
            System.out.println("Player not found.");
            return;
        }
        String newPass = Keyboard.readString("Enter new password > ");
        p.setPassword(newPass);
        savePlayers();
        System.out.println("Password for '" + login + "' has been reset.");
    }

    /* ------------------------------------------------------------------ */
    /*  Utility ----------------------------------------------------------- */
    /* ------------------------------------------------------------------ */
    private Player findPlayer(String login) {
        for (Player p : players) {
            if (p.getLoginName().equalsIgnoreCase(login))
                return p;
        }
        return null;
    }

    /* ------------------------------------------------------------------ */
    /*  MAIN – just start the admin module                                 */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) {
        new Admin().run();
    }
}
