    @SuppressWarnings("unchecked")
    private static List<Player> loadAllPlayers() {
        File f = new File(PLAYERS_FILE);
        if (!f.exists())
            return new ArrayList<>();

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            Object obj = ois.readObject();
            return (obj instanceof List) ? (List<Player>) obj : new ArrayList<>();
        } catch (EOFException e) {
            return new ArrayList<>();
        } catch (Exception e) {
            throw new RuntimeException("Cannot load players.bin", e);
        }
    }

    private static void saveAllPlayers(List<Player> players) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYERS_FILE))) {
            oos.writeObject(players);
        } catch (IOException e) {
            throw new RuntimeException("Cannot save players.bin", e);
        }
    }
