    /*  Simple printing utilities (you already have)                       */
    /* ------------------------------------------------------------------ */
    public static void printLine(int num) { printLine(num, '-'); }
    public static void printDoubleLine(int num) { printLine(num, '='); }
    public static void printLine(int num, char pattern) {
        for (int i = 0; i < num; i++) System.out.print(pattern);
        System.out.println();
    }
}
```

