                .setIssuedAt(new Date())
                .setExpiration(Date.from(Instant.now().plus(2, ChronoUnit.HOURS)))
                .signWith(Keys.hmacShaKeyFor(jwtUtil.secret.getBytes(StandardCharsets.UTF_8)),
                         SignatureAlgorithm.HS256)
                .compact();
        return ResponseEntity.ok(Map.of("token", token));
    }
}
```

> 前端拿到 token 后，用 `ws://example.com/ws?token=xxxx`（或在 Header 里 `Authorization: Bearer xxxx`）建立连接。

### 6.6 前端（简易示例）

```html
<script src="https://cdn.jsdelivr.net/npm/sockjs-client@1/dist/sockjs.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/stompjs@2.3.3/lib/stomp.min.js"></script>
<script>
let token = localStorage.getItem('jwt'); // 登录后存储

let socket = new SockJS('/ws?token=' + token);
let stompClient = Stomp.over(socket);

stompClient.connect({}, frame => {
    console.log('Connected: ' + frame);
    stompClient.subscribe('/topic/public', msg => {
        const chat = JSON.parse(msg.body);
        console.log('Public:', chat);
    });
    // 私聊示例
    stompClient.subscribe('/user/queue/private', msg => {
        console.log('Private:', JSON.parse(msg.body));
    });
}, err => console.error(err));
</script>
```

