package com.example.dao;

import com.example.model.Unit;
import com.example.util.DBUtil;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class UnitDao {

    /** 根据 parentId 查询子单位（包括一级的 parentId 为 null） */
    public List<Unit> findByParentId(Integer parentId) throws SQLException {
        String sql = "SELECT id, name, parent_id FROM unit WHERE parent_id "
                + (parentId == null ? "IS NULL" : "= ?");
        List<Unit> list = new ArrayList<>();
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            if (parentId != null) {
                ps.setInt(1, parentId);
            }
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    Unit u = new Unit();
                    u.setId(rs.getInt("id"));
                    u.setName(rs.getString("name"));
                    int pid = rs.getInt("parent_id");
                    u.setParentId(rs.wasNull() ? null : pid);
                    list.add(u);
                }
            }
        }
        return list;
    }

    /** 根据 id 查询单个单位（只返回本身） */
    public Unit findById(int id) throws SQLException {
        String sql = "SELECT id, name, parent_id FROM unit WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    Unit u = new Unit();
                    u.setId(rs.getInt("id"));
                    u.setName(rs.getString("name"));
                    int pid = rs.getInt("parent_id");
                    u.setParentId(rs.wasNull() ? null : pid);
                    return u;
                }
            }
        }
        return null;
    }
}
```

