public class CustomerDao {

    /** 新增 */
    public void add(Customer c) throws SQLException {
        String sql = "INSERT INTO customer (unit_id, name, phone, mobile, qq, email) "
                + "VALUES (?,?,?,?,?,?)";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, c.getUnitId());
            ps.setString(2, c.getName());
            ps.setString(3, c.getPhone());
            ps.setString(4, c.getMobile());
            ps.setString(5, c.getQq());
            ps.setString(6, c.getEmail());
            ps.executeUpdate();
        }
    }

    /** 更新 */
    public void update(Customer c) throws SQLException {
        String sql = "UPDATE customer SET unit_id=?, name=?, phone=?, mobile=?, qq=?, email=? "
                + "WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, c.getUnitId());
            ps.setString(2, c.getName());
            ps.setString(3, c.getPhone());
            ps.setString(4, c.getMobile());
            ps.setString(5, c.getQq());
            ps.setString(6, c.getEmail());
            ps.setInt(7, c.getId());
            ps.executeUpdate();
        }
    }

    /** 删除 */
    public void delete(int id) throws SQLException {
        String sql = "DELETE FROM customer WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, id);
            ps.executeUpdate();
        }
    }

    /** 按条件查询（支持模糊） */
    public List<Customer> search(String name, Integer unitId, boolean fuzzy) throws SQLException {
        StringBuilder sb = new StringBuilder(
                "SELECT id, unit_id, name, phone, mobile, qq, email FROM customer WHERE 1=1");
        List<Object> params = new ArrayList<>();

        if (name != null && !name.trim().isEmpty()) {
            sb.append(" AND name ").append(fuzzy ? "LIKE ?" : "= ?");
            params.add(fuzzy ? "%" + name.trim() + "%" : name.trim());
        }
        if (unitId != null) { // 只考虑三级单位的完整匹配
            sb.append(" AND unit_id = ?");
            params.add(unitId);
        }

        List<Customer> list = new ArrayList<>();
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sb.toString())) {
            for (int i = 0; i < params.size(); i++) {
                ps.setObject(i + 1, params.get(i));
            }
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    Customer c = new Customer();
                    c.setId(rs.getInt("id"));
                    c.setUnitId(rs.getInt("unit_id"));
                    c.setName(rs.getString("name"));
                    c.setPhone(rs.getString("phone"));
                    c.setMobile(rs.getString("mobile"));
                    c.setQq(rs.getString("qq"));
                    c.setEmail(rs.getString("email"));
                    list.add(c);
                }
            }
        }
        return list;
    }

    /** 根据 id 查询单条 */
    public Customer findById(int id) throws SQLException {
        String sql = "SELECT id, unit_id, name, phone, mobile, qq, email FROM customer WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    Customer c = new Customer();
