```java
package com.example.servlet;

import com.example.dao.CustomerDao;
import com.example.dao.UnitDao;
import com.example.model.Customer;
import com.example.model.Unit;
import com.example.util.JsonUtil;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;
import java.io.IOException;
import java.sql.SQLException;
import java.util.*;

@WebServlet("/customer")
public class CustomerServlet extends HttpServlet {
    private final CustomerDao customerDao = new CustomerDao();
    private final UnitDao unitDao = new UnitDao();

    // -------------------- 入口 --------------------
    // /customer?action=add|edit|del|list|detail
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        // 所有页面跳转或查询均通过 GET，表单提交（新增/修改）走 POST
        String action = req.getParameter("action");
        if (action == null) action = "list";

        try {
            switch (action) {
                case "add":   // 跳转到编辑页，空对象
                    forwardToEdit(req, resp, null);
                    break;
                case "edit":
                    int editId = Integer.parseInt(req.getParameter("id"));
                    Customer editCustomer = customerDao.findById(editId);
                    forwardToEdit(req, resp, editCustomer);
                    break;
                case "del":
                    int delId = Integer.parseInt(req.getParameter("id"));
                    customerDao.delete(delId);
                    resp.sendRedirect(req.getContextPath() + "/customer?action=list");
                    break;
                case "detail":
                    int viewId = Integer.parseInt(req.getParameter("id"));
                    Customer viewCustomer = customerDao.findById(viewId);
                    req.setAttribute("customer", viewCustomer);
                    // 为了演示，这里直接转到同一个编辑页，只是只读
                    req.getRequestDispatcher("/WEB-INF/jsp/customer_edit.jsp").forward(req, resp);
                    break;
                case "list":
                default:
                    handleList(req, resp);
                    break;
            }
        } catch (SQLException e) {
            throw new ServletException(e);
        }
    }

    // -------------------- POST（新增 / 修改） --------------------
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        // 参数统一读取
        req.setCharacterEncoding("UTF-8");
        String idStr = req.getParameter("id"); // 若为空表示新增
        String unit1 = req.getParameter("unit1"); // 一级
        String unit2 = req.getParameter("unit2"); // 二级
        String unit3 = req.getParameter("unit3"); // 三级（必须）
        String name   = req.getParameter("name");
        String phone  = req.getParameter("phone");
        String mobile = req.getParameter("mobile");
        String qq     = req.getParameter("qq");
        String email  = req.getParameter("email");

        // 基本校验（实际项目请加入更完整的校验和错误信息返回）
        List<String> errMsg = new ArrayList<>();
        if (unit3 == null || unit3.isEmpty()) errMsg.add("必须选择完整的三级单位");
        if (name == null || name.trim().isEmpty()) errMsg.add("姓名不能为空");

        if (!errMsg.isEmpty()) {
            req.setAttribute("errors", errMsg);
            // 若是编辑，携带原始对象回页面
            Customer c = new Customer();
            c.setId(safeParseInt(idStr));
            c.setUnitId(safeParseInt(unit3));
            c.setName(name);
            c.setPhone(phone);
            c.setMobile(mobile);
            c.setQq(qq);
            c.setEmail(email);
            req.setAttribute("customer", c);
            forwardToEdit(req, resp, c);
            return;
        }

        // 组装 Customer 对象
        Customer c = new Customer();
        c.setUnitId(Integer.parseInt(unit3));
        c.setName(name.trim());
        c.setPhone(phone);
        c.setMobile(mobile);
        c.setQq(qq);
        c.setEmail(email);

        try {
            if (idStr == null || idStr.isEmpty()) {
                // 新增
                customerDao.add(c);
            } else {
                // 修改
                c.setId(Integer.parseInt(idStr));
                customerDao.update(c);
            }
            // 成功后跳回列表
            resp.sendRedirect(req.getContextPath() + "/customer?action=list");
        } catch (SQLException e) {
            throw new ServletException(e);
        }
    }

    // -------------------- 辅助方法 --------------------
    private void forwardToEdit(HttpServletRequest req, HttpServletResponse resp, Customer c) throws ServletException, IOException, SQLException {
        // 需要把一级、二级、三级单位的 ID 放到请求属性，页面渲染级联下拉框
        Integer unit3 = (c != null) ? c.getUnitId() : null;
        Integer unit2 = null, unit1 = null;
        if (unit3 != null) {
            Unit third = unitDao.findById(unit3);
            if (third != null) {
                unit2 = third.getParentId();
                if (unit2 != null) {
                    Unit second = unitDao.findById(unit2);
                    if (second != null) unit1 = second.getParentId();
                }
            }
        }
        req.setAttribute("unit1Selected", unit1);
        req.setAttribute("unit2Selected", unit2);
        req.setAttribute("unit3Selected", unit3);
        req.setAttribute("customer", c);
        req.getRequestDispatcher("/WEB-INF/jsp/customer_edit.jsp").forward(req, resp);
    }

    /** 处理列表页（分页演示可自行扩展） */
    private void handleList(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException, SQLException {
        String name = req.getParameter("name");
        String unit3 = req.getParameter("unit3"); // 只支持三级单位精确查询
        String fuzzy = req.getParameter("fuzzy"); // "true" 表示模糊

        Integer unit3Id = (unit3 != null && !unit3.isEmpty()) ? Integer.valueOf(unit3) : null;
        boolean isFuzzy = "true".equalsIgnoreCase(fuzzy);

        List<Customer> result = customerDao.search(name, unit3Id, isFuzzy);
        req.setAttribute("customers", result);
        // 为了让下拉框仍可选单位，这里把一级、二级、三级的选中值保存（如果有的话）
        req.setAttribute("unit1Selected", (Object) null);
        req.setAttribute("unit2Selected", (Object) null);
        req.setAttribute("unit3Selected", unit3Id);
        req.getRequestDispatcher("/WEB-INF/jsp/customer_list.jsp").forward(req, resp);
    }

    private int safeParseInt(String s) {
        try {
            return Integer.parseInt(s);
        } catch (Exception e) {
            return 0;
        }
    }
}
