    $(function () {
        loadUnits(null, "#unit1", ${unit1Selected == null ? 'null' : unit1Selected});
    });

    function loadUnits(parentId, $target, selectedId) {
        // AJAX 调用 /unit?parentId=xxx
        $.getJSON("${pageContext.request.contextPath}/unit", {parentId: parentId}, function (data) {
            $target.empty();
            $target.append('<option value="">请选择</option>');
            $.each(data, function (i, unit) {
                var selected = (selectedId != null && selectedId == unit.id) ? ' selected' : '';
                $target.append('<option value="' + unit.id + '"' + selected + '>' + unit.name + '</option>');
            });
        });
    }

    // ----- 级联触发 -----
    $(document).on('change', '#unit1', function () {
        var pid = $(this).val();
        $('#unit2').html('<option>请选择</option>');
        $('#unit3').html('<option>请选择</option>');
        if (pid) {
            loadUnits(pid, "#unit2", ${unit2Selected == null ? 'null' : unit2Selected});
        }
    });

    $(document).on('change', '#unit2', function () {
        var pid = $(this).val();
        $('#unit3').html('<option>请选择</option>');
        if (pid) {
            loadUnits(pid, "#unit3", ${unit3Selected == null ? 'null' : unit3Selected});
        }
    });
</script>

