## 2. Обработчик, который будет получать **полные** запросы

```java
public class GameRequestHandler extends SimpleChannelInboundHandler<String> {

    // Ваши массивы ключей и прочие поля
    private final int[] _keys = {1,2,3,4,5,6,7,8,9};   // пример, должно совпадать с клиентом
    private int _lastKey = 0;                         // последний валидный ключ

    private final StringBuilder badRequest = new StringBuilder();

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, String msg) throws Exception {
        // msg уже без "end~", а потому делим на отдельные запросы,
        // если клиент склеил несколько подряд.
        // В клиенте каждый запрос заканчивается "end~", т.е. после делимитера
        // мы получаем ровно один запрос, но на случай «склейки» делим на ';'
        // (по вашему формату: тип;arg1;arg2;…)
        decryptProtocol(msg, ctx);
    }

    /** Обертка, сохраняет совместимость с вашим оригинальным кодом. */
    private void decryptProtocol(String protocol, ChannelHandlerContext ctx) {
        // Весь ваш прежний код почти без изменений, только заменили
        // работу с каналом и теперь используем уже готовую строку.
        this.inputRequest = new StringBuffer(protocol);

        if (inputRequest.length() > 0) {
            // В данном варианте делим на "запросы", которые могут быть
            // собраны в одну строку, если клиент отправил несколько подряд.
            // На клиенте каждый запрос выглядит как: <key><payload> (без "end~")
            // Поэтому просто обрабатываем всё целиком:
            String[] requests = parseCryptRequests(); // ваш парсер разбивает по ';'

            for (String request : requests) {
                // ---------- проверка ключа ----------
                int key;
                try {
                    key = Integer.parseInt(String.valueOf(request.charAt(0)));
                } catch (Exception e) {
                    Logger.log("[EXCEPTION] Detected cheater (replace protocol): " + ctx.channel().remoteAddress());
                    blockAndClose(ctx);
                    return;
                }

                // повторный ключ → cheat
                if (key == _lastKey) {
                    Logger.log("Detected cheater (repeat key): " + ctx.channel().remoteAddress());
                    blockAndClose(ctx);
                    return;
                }

                // ожидаемый следующий ключ
                int nextKey = (_lastKey + 1) % _keys.length;
                if (nextKey == 0) nextKey = 1;
                if (key != nextKey) {
                    Logger.log("[WRONG QUEUE KEY " + nextKey + "] Detected cheater: " + ctx.channel().remoteAddress());
                    blockAndClose(ctx);
                    return;
                }

                // ---------- дешифрование ----------
                String clear = decrypt(request.substring(1), key);
                _lastKey = key; // запоминаем, что ключ уже использован

                // передаём дальше в ваш бизнес‑логика (например, менеджерам)
                sendRequestToManagers(clear);
            }

            // после полного успешного прохода сбрасываем «плохой» буфер
            badRequest.setLength(0);
        } else {
            // Если вдруг пришёл пустой запрос – просто сохраняем в буфер
            badRequest.append(protocol);
        }
    }

    // ----------------- вспомогательные методы -----------------

    private void blockAndClose(ChannelHandlerContext ctx) {
        NettyUsersHandler.block(ctx.channel().remoteAddress().toString().split(":")[0]);
        ctx.close();
    }

    /** Ваш старый метод декодирования */
    private String decrypt(String request, int key) {
        this._lastKey = key;
        char[] chars = request.toCharArray();
        for (int i = 0; i < chars.length; ++i) {
            chars[i] = (char) (chars[i] - (key + 1));
        }
        return new String(chars);
    }

    /** Пример парсинга «криптованных» запросов. <br>
     *  Ваша оригинальная реализация могла выглядеть иначе.
     *  Ниже простейший вариант – разбиваем по ';' и собираем массив.
     */
    private String[] parseCryptRequests() {
        // Убираем возможные лишние ';' в начале/конце
        String s = inputRequest.toString();
        if (s.startsWith(";")) s = s.substring(1);
        if (s.endsWith(";")) s = s.substring(0, s.length() - 1);
        return s.split(";");
    }

    /** Отправка в менеджеры – замените на ваш реальный код */
