1. **Mostrare un menù** nella console ad ogni iterazione.  
2. **Leggere la scelta** dell’utente (0 = esci, 1 = register, 2 = login, …).  
3. **Chiedere i parametri necessari** (username, password, nome hotel, città, ecc.).  
4. **Inviare al server** il comando nella forma che il tuo protocollo si aspetta (es. `REGISTER <user> <pass>`).  
5. **Stampare la risposta** che arriva dal server.  

Di seguito trovi il **codice aggiornato** del client con un menù completamente interattivo.  
È stato scritto in maniera leggibile, con costanti per i comandi, un metodo di stampa del menù e una piccola **estrazione dei parametri** in modo da non far “saltare” il programma se l’utente inserisce qualcosa di sbagliato.

```java
import java.io.IOException;
import java.io.PrintWriter;
import java.net.Socket;
import java.net.UnknownHostException;
import java.util.Scanner;

/**
 * Client console‑based con menù interattivo.
 * Le stringhe inviate al server sono del tipo:
 *
 *   REGISTER <username> <password>
 *   LOGIN    <username> <password>
 *   LOGOUT   <username>
 *   SEARCH   <hotelName> <city>
 *   SEARCHALL <city>
 *   BADGES   <username>
 *
 * Il server deve conoscere ed interpretare questi comandi.
 */
public class ClientMain {

    // ---------- costanti del menù ----------
    private static final int EXIT          = 0;
    private static final int REGISTER      = 1;
    private static final int LOGIN         = 2;
    private static final int LOGOUT        = 3;
    private static final int SEARCH_HOTEL  = 4;
    private static final int SEARCH_ALL    = 5;
    private static final int SHOW_BADGES   = 6;

    // ---------- comandi da inviare al server ----------
    private static final String CMD_REGISTER = "REGISTER";
    private static final String CMD_LOGIN    = "LOGIN";
    private static final String CMD_LOGOUT   = "LOGOUT";
    private static final String CMD_SEARCH   = "SEARCH";
    private static final String CMD_SEARCHALL= "SEARCHALL";
    private static final String CMD_BADGES   = "BADGES";

    public static void main(String[] args) {
        String serverIP = "127.0.0.1";
        final int serverPort = 10000;

        Scanner console = null;          // per leggere da CLI
        Scanner serverIn = null;         // per leggere dal socket
        PrintWriter serverOut = null;    // per scrivere sul socket

        try (Socket socket = new Socket(serverIP, serverPort)) {

            console   = new Scanner(System.in);
            serverIn = new Scanner(socket.getInputStream());
            serverOut = new PrintWriter(socket.getOutputStream(), true); // auto‑flush

            System.out.println("Connesso al server (" + serverIP + ":" + serverPort + ")");
            System.out.println("-------------------------------------------------");

            boolean running = true;
            while (running) {
                // 1️⃣ stampa il menù e ottieni la scelta
                int choice = readMenuChoice(console);

                // 2️⃣ costruisci il messaggio da inviare (se non è EXIT)
                String messageToServer = null;
                switch (choice) {
                    case EXIT:
                        running = false;
                        System.out.println("Chiusura client…");
                        break;

                    case REGISTER:
                        messageToServer = buildRegisterMessage(console);
                        break;

                    case LOGIN:
                        messageToServer = buildLoginMessage(console);
                        break;

                    case LOGOUT:
                        messageToServer = buildLogoutMessage(console);
                        break;

                    case SEARCH_HOTEL:
                        messageToServer = buildSearchHotelMessage(console);
                        break;

                    case SEARCH_ALL:
                        messageToServer = buildSearchAllMessage(console);
                        break;

                    case SHOW_BADGES:
                        messageToServer = buildShowBadgesMessage(console);
                        break;

                    default:
                        // questo caso non dovrebbe capitare perché readMenuChoice lo gestisce,
                        // ma è una buona pratica avere un ramo di fallback.
                        System.out.println("Scelta non valida. Riprova.");
                }

                // 3️⃣ se abbiamo un messaggio da inviare, mandiamolo e stampiamo la risposta
                if (messageToServer != null) {
                    serverOut.println(messageToServer);       // invia al server
                    String reply = serverIn.nextLine();       // attende la risposta
                    System.out.println("Risposta server: " + reply);
                }
            }

        } catch (UnknownHostException e) {
            System.err.println("Indirizzo IP del server non trovato: " + e.getMessage());
        } catch (IOException e) {
            System.err.println("Errore di I/O: " + e.getMessage());
        } finally {
            // chiusura risorse CLI
            if (console != null) {
                console.close();
            }
            if (serverIn != null) {
                serverIn.close();
            }
            // PrintWriter non necessita di close se è stato creato dentro il try‑with‑resources,
            // ma possiamo chiuderlo esplicitamente se lo avessimo dichiarato fuori.
        }
    }

    // -------------------------------------------------
    //  👇 METODI DI SUPPORTO (menu, lettura parametri, costruzione messaggi)
    // -------------------------------------------------

    /** Stampa il menù e ritorna l’intero scelto dall’utente (0‑6). */
    private static int readMenuChoice(Scanner console) {
        System.out.println("\n=== MENU CLIENT ===");
        System.out.println(EXIT + " - Esci");
        System.out.println(REGISTER + " - Register (username, password)");
        System.out.println(LOGIN + " - Login (username, password)");
        System.out.println(LOGOUT + " - Logout (username)");
        System.out.println(SEARCH_HOTEL + " - Search hotel (nome, città)");
        System.out.println(SEARCH_ALL + " - Search all hotels in a city");
        System.out.println(SHOW_BADGES + " - Show my badges");
        System.out.print("Inserisci la tua scelta: ");

        // Gestione input non numerico
        while (!console.hasNextInt()) {
            System.out.print("Devi inserire un numero tra " + EXIT + " e " + SHOW_BADGES + ". Riprova: ");
            console.next(); // scarta token non numerico
        }
        int choice = console.nextInt();
        console.nextLine(); // consuma l'eventuale newline rimasta

        if (choice < EXIT || choice > SHOW_BADGES) {
            System.out.println("Scelta fuori dal range. Riprova.");
            return readMenuChoice(console); // ricorsione semplice per ripetere
        }
        return choice;
