```java
package server;

import common.*;
import server.ui.ServerUI;
import server.util.ChatLog;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class ChatServer {
    private final int port;
    private ServerSocket serverSocket;
    private final ExecutorService pool = Executors.newCachedThreadPool();
    // key: userId
    private final Map<String, ClientHandler> onlineClients = new ConcurrentHashMap<>();
    private ServerUI ui;

    public ChatServer(int port) {
        this.port = port;
    }

    public void start() {
        try {
            serverSocket = new ServerSocket(port);
            ui = new ServerUI(this);
            ui.showUI();

            // 接受新连接的线程
            new Thread(() -> {
                while (!serverSocket.isClosed()) {
                    try {
                        Socket socket = serverSocket.accept();
                        // 每个 socket 单独交给 ClientHandler 处理
                        ClientHandler handler = new ClientHandler(socket, this);
                        pool.execute(handler);
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }, "Accept-Thread").start();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 被 ClientHandler 调用：用户已请求客服 */
    public void onUserRequest(String userId, ClientHandler handler) {
        // 首先把 handler 加入 map（即使未被接受，也先登记），方便后续删除
        onlineClients.put(userId, handler);
        // 在 UI 线程弹窗，等待客服接受/拒绝
        ui.promptUserRequest(userId, accepted -> {
            try {
                // 响应给客户端
                handler.sendMessage(new ResponseMessage(accepted, userId));
                if (accepted) {
                    // 打开聊天窗口（从日志读取历史）
                    ui.openChatWindow(userId, handler);
                } else {
                    // 拒绝后立即关闭连接
                    handler.close();
                    onlineClients.remove(userId);
                }
            } catch (IOException ex) {
                ex.printStackTrace();
            }
        });
    }

    /** 被 ClientHandler 调用：收到用户发送的消息，需要转发到对应的聊天窗口 */
    public void deliverMessage(String userId, Message msg) {
        ui.appendMessage(userId, msg);
        // 同步写入聊天记录
        ChatLog.append(userId, msg);
    }

    /** 客服窗口发送消息时调用 */
    public void sendToUser(String userId, Message msg) throws IOException {
        ClientHandler handler = onlineClients.get(userId);
        if (handler != null) {
            handler.sendMessage(msg);
            // 同步写入聊天记录
            ChatLog.append(userId, msg);
        } else {
            ui.showInfo("用户已下线：" + userId);
        }
    }

    /** 当用户断开或被强制关闭时 */
    public void onUserQuit(String userId) {
        onlineClients.remove(userId);
        ui.notifyUserOffline(userId);
    }
}
```

### 4.3 `ClientHandler.java`

```java
package server;

import common.*;

import java.io.*;
import java.net.*;

public class ClientHandler implements Runnable {
    private final Socket socket;
    private final ChatServer server;
    private DataInputStream in;
    private DataOutputStream out;
    private String userId; // 客服端通过 REQUEST 获得

    public ClientHandler(Socket socket, ChatServer server) throws IOException {
        this.socket = socket;
        this.server = server;
        this.in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
        this.out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
    }

    @Override
    public void run() {
        try {
            // 第一步：必须先收到请求报文
            Message first = Protocol.readMessage(in);
            if (first == null || !(first instanceof RequestMessage)) {
                close();
                return;
            }
            RequestMessage req = (RequestMessage) first;
            this.userId = req.getUserId();

            // 把请求交给 server（弹窗询问接受/拒绝）
            server.onUserRequest(userId, this);

            // 接下来循环读取用户发送的各种消息
            Message msg;
            while ((msg = Protocol.readMessage(in)) != null) {
                // 只要是用户发来的，就转发到 UI
                server.deliverMessage(userId, msg);
            }
        } catch (SocketException se) {
            // 客户端主动断开
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            server.onUserQuit(userId);
            close();
        }
    }

    /** 发送消息给用户 */
    public synchronized void sendMessage(Message msg) throws IOException {
        Protocol.writeMessage(out, msg);
    }

    public void close() {
        try { socket.close(); } catch (IOException ignored) {}
    }
}
```

