import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.HashMap;
import java.util.Map;

public class ServerUI {
    private final ChatServer server;
    private JFrame frame;
    private JList<String> onlineList; // 显示在线用户 id
    private DefaultListModel<String> listModel = new DefaultListModel<>();
    // 每个用户对应的聊天窗口
    private final Map<String, ChatWindow> chatWindows = new HashMap<>();

    public ServerUI(ChatServer server) {
        this.server = server;
    }

    public void showUI() {
        SwingUtilities.invokeLater(() -> {
            frame = new JFrame("电商客服系统 - 服务端");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setSize(300, 500);
            frame.setLocationRelativeTo(null);

            onlineList = new JList<>(listModel);
            onlineList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
            onlineList.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    if (e.getClickCount() == 2) {
                        String userId = onlineList.getSelectedValue();
                        if (userId != null) openChatWindow(userId, null);
                    }
                }
            });

            frame.add(new JScrollPane(onlineList), BorderLayout.CENTER);
            frame.setVisible(true);
        });
    }

    /** 弹窗让客服决定是否接受用户请求 */
    public void promptUserRequest(String userId, java.util.function.Consumer<Boolean> callback) {
        SwingUtilities.invokeLater(() -> {
            int opt = JOptionPane.showConfirmDialog(frame,
                    "新用户请求聊天（ID=" + userId + "），是否接受？",
                    "新请求", JOptionPane.YES_NO_OPTION);
            callback.accept(opt == JOptionPane.YES_OPTION);
        });
    }

    /** 打开（或返回已有）聊天窗口 */
    public void openChatWindow(String userId, ClientHandler handler) {
        SwingUtilities.invokeLater(() -> {
            ChatWindow win = chatWindows.get(userId);
            if (win == null) {
                win = new ChatWindow(userId, server);
                chatWindows.put(userId, win);
                win.showWindow();
                // 加载历史记录（ChatLog 会自行读取）
                java.util.List<Message> history = server.util.ChatLog.readHistory(userId);
                history.forEach(win::appendMessage);
            } else {
                win.bringToFront();
            }
            if (!listModel.contains(userId)) {
                listModel.addElement(userId);
            }
        });
    }

    /** 将收到的消息追加到对应聊天窗口 */
    public void appendMessage(String userId, Message msg) {
        SwingUtilities.invokeLater(() -> {
            ChatWindow win = chatWindows.get(userId);
            if (win != null) {
                win.appendMessage(msg);
            }
        });
    }

    /** 当用户下线时从列表中移除 */
    public void notifyUserOffline(String userId) {
        SwingUtilities.invokeLater(() -> listModel.removeElement(userId));
    }

    /** 简单提示 */
    public void showInfo(String msg) {
        SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(frame, msg));
    }
