### 5.2 `ChatClient.java`

```java
package client;

import common.*;
import client.ui.ChatWindow;
import client.util.ChatLog;

import javax.swing.*;
import java.io.*;
import java.net.*;
import java.util.Timer;
import java.util.TimerTask;

public class ChatClient {
    private final String host;
    private final int port;
    private final String userId;
    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private ChatWindow ui;
    private Timer timeoutTimer;

    public ChatClient(String host, int port, String userId) {
        this.host = host;
        this.port = port;
        this.userId = userId;
    }

    public void start() {
        SwingUtilities.invokeLater(() -> ui = new ChatWindow(userId, this));
        new Thread(this::connectAndListen, "Client-Thread").start();
    }

    /** 建立连接并发送请求报文 */
    private void connectAndListen() {
        try {
            socket = new Socket();
            socket.connect(new InetSocketAddress(host, port), 5000);
            in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
            out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));

            // 发送请求
            Protocol.writeMessage(out, new RequestMessage(userId));

            // 启动超时检测（5 秒未收到 RESPONSE 则视为忙）
            startTimeoutTimer();

            // 循环读取服务器发来的消息
            Message msg;
            while ((msg = Protocol.readMessage(in)) != null) {
                if (msg instanceof ResponseMessage) {
                    cancelTimeoutTimer();
                    ResponseMessage resp = (ResponseMessage) msg;
                    if (resp.isAccept()) {
                        // 接受成功，加载历史记录
                        SwingUtilities.invokeLater(() -> {
                            ui.appendSystemInfo("客服已接受，您可以开始聊天。");
                            ChatLog.readHistory(userId).forEach(ui::appendMessage);
                        });
                    } else {
                        SwingUtilities.invokeLater(() -> ui.appendSystemInfo("客服拒绝了本次会话。"));
                        close();
                        break;
                    }
                } else {
                    // 其它消息直接转发到 UI
                    ui.appendMessage(msg);
                    ChatLog.append(userId, msg);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
            SwingUtilities.invokeLater(() -> ui.appendSystemInfo("连接异常：" + e.getMessage()));
        } finally {
            close();
        }
    }

    /** 给服务器发送任意 Message */
    public synchronized void sendMessage(Message msg) throws IOException {
        Protocol.writeMessage(out, msg);
        // 同步写入本地日志
        ChatLog.append(userId, msg);
    }

    /** 关闭资源 */
    private void close() {
        cancelTimeoutTimer();
        try { if (socket != null) socket.close(); } catch (IOException ignored) {}
    }

    // ------------------- 超时检测 ---------------------------
    private void startTimeoutTimer() {
        timeoutTimer = new Timer();
        timeoutTimer.schedule(new TimerTask() {
            @Override public void run() {
                SwingUtilities.invokeLater(() -> {
                    ui.appendSystemInfo("客服忙，请稍后再试或换一个客服。");
                    close();
                });
            }
        }, 5000); // 5 秒
    }

    private void cancelTimeoutTimer() {
        if (timeoutTimer != null) {
            timeoutTimer.cancel();
            timeoutTimer = null;
        }
    }
}
```

