> 为方便复制，下面把所有核心类的源码一次性贴出（已在章节 3‑5 中分块展示），只需要把它们放到对应的包路径即可。  

```java
// ===================== common/Protocol.java =====================
package common;

import java.io.*;

public class Protocol {
    public static final byte TYPE_REQUEST  = 0;
    public static final byte TYPE_RESPONSE = 1;
    public static final byte TYPE_TEXT     = 2;
    public static final byte TYPE_IMAGE    = 3;
    public static final byte TYPE_FILE     = 4;

    public static Message readMessage(DataInputStream in) throws IOException {
        int totalLen;
        try {
            totalLen = in.readInt();
        } catch (EOFException e) {
            return null;
        }
        byte type = in.readByte();
        int payloadLen = in.readInt();
        byte[] payload = new byte[payloadLen];
        in.readFully(payload);
        DataInputStream din = new DataInputStream(new ByteArrayInputStream(payload));

        switch (type) {
            case TYPE_REQUEST:
                return new RequestMessage(din.readUTF());
            case TYPE_RESPONSE:
                boolean accept = din.readBoolean();
                String uid = din.readUTF();
                return new ResponseMessage(accept, uid);
            case TYPE_TEXT:
                return new TextMessage(din.readUTF());
            case TYPE_IMAGE:
                String imgName = din.readUTF();
                byte[] imgData = din.readAllBytes();
                return new ImageMessage(imgName, imgData);
            case TYPE_FILE:
                String fileName = din.readUTF();
                byte[] fileData = din.readAllBytes();
                return new FileMessage(fileName, fileData);
            default:
                throw new IOException("Unknown type: " + type);
        }
    }

    public static void writeMessage(DataOutputStream out, Message msg) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(baos);
        msg.writePayload(dos);
        dos.flush();
        byte[] payload = baos.toByteArray();

        int totalLen = 1 + 4 + payload.length;
        out.writeInt(totalLen);
        out.writeByte(msg.getType());
        out.writeInt(payload.length);
        out.write(payload);
        out.flush();
    }
}

