package common;

import java.io.*;

public abstract class Message {
    public abstract byte getType();
    public abstract void writePayload(DataOutputStream out) throws IOException;
}

/* ---------- 子类 ---------- */
class RequestMessage extends Message {
    private final String userId;
    public RequestMessage(String userId) { this.userId = userId; }
    public String getUserId() { return userId; }
    @Override public byte getType() { return Protocol.TYPE_REQUEST; }
    @Override public void writePayload(DataOutputStream out) throws IOException { out.writeUTF(userId); }
}

class ResponseMessage extends Message {
    private final boolean accept;
    private final String userId;
    public ResponseMessage(boolean accept, String userId) { this.accept = accept; this.userId = userId; }
    public boolean isAccept() { return accept; }
    public String getUserId() { return userId; }
    @Override public byte getType() { return Protocol.TYPE_RESPONSE; }
    @Override public void writePayload(DataOutputStream out) throws IOException {
        out.writeBoolean(accept);
        out.writeUTF(userId);
    }
}

class TextMessage extends Message {
    private final String text;
    public TextMessage(String text) { this.text = text; }
    public String getText() { return text; }
    @Override public byte getType() { return Protocol.TYPE_TEXT; }
    @Override public void writePayload(DataOutputStream out) throws IOException { out.writeUTF(text); }
}

class ImageMessage extends Message {
    private final String fileName;
    private final byte[] data;
    public ImageMessage(String fileName, byte[] data) { this.fileName = fileName; this.data = data; }
    public String getFileName() { return fileName; }
    public byte[] getData() { return data; }
    @Override public byte getType() { return Protocol.TYPE_IMAGE; }
    @Override public void writePayload(DataOutputStream out) throws IOException {
        out.writeUTF(fileName);
        out.write(data);
    }
}

class FileMessage extends Message {
    private final String fileName;
    private final byte[] data;
    public FileMessage(String fileName, byte[] data) { this.fileName = fileName; this.data = data; }
    public String getFileName() { return fileName; }
    public byte[] getData() { return data; }
    @Override public byte getType() { return Protocol.TYPE_FILE; }
    @Override public void writePayload(DataOutputStream out) throws IOException {
        out.writeUTF(fileName);
        out.write(data);
    }
}

