            frame.setSize(300, 500);
            frame.setLocationRelativeTo(null);
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

            userList = new JList<>(listModel);
            userList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
            userList.addMouseListener(new java.awt.event.MouseAdapter() {
                @Override public void mouseClicked(java.awt.event.MouseEvent e) {
                    if (e.getClickCount() == 2) {
                        String uid = userList.getSelectedValue();
                        if (uid != null) openChatWindow(uid, null);
                    }
                }
            });
            frame.add(new JScrollPane(userList), BorderLayout.CENTER);
            frame.setVisible(true);
        });
    }

    /** 弹框，让客服决定是否接受 */
    public void promptUserRequest(String userId, java.util.function.Consumer<Boolean> cb) {
        SwingUtilities.invokeLater(() -> {
            int opt = JOptionPane.showConfirmDialog(frame,
                    "用户 " + userId + " 请求聊天，是否接受？",
                    "新请求", JOptionPane.YES_NO_OPTION);
            cb.accept(opt == JOptionPane.YES_OPTION);
        });
    }

    /** 打开（或返回已有）聊天窗口 */
    public void openChatWindow(String userId, ClientHandler handler) {
        SwingUtilities.invokeLater(() -> {
            ChatWindow win = windows.computeIfAbsent(userId, uid -> {
                ChatWindow w = new ChatWindow(uid, server);
                w.showWindow();
                return w;
            });
            win.bringToFront();

            if (!listModel.contains(userId)) listModel.addElement(userId);
        });
    }

    /** 将收到的消息追加到对应聊天窗口 */
    public void appendMessage(String userId, Message msg) {
        SwingUtilities.invokeLater(() -> {
            ChatWindow win = windows.get(userId);
            if (win != null) win.appendMessage(msg);
        });
    }

    public void notifyUserOffline(String userId) {
        SwingUtilities.invokeLater(() -> listModel.removeElement(userId));
    }

    public void showInfo(String txt) {
        SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(frame, txt));
    }
}

