    private JTextArea area;
    private JTextField input;
    private JButton sendBtn, imgBtn, fileBtn;

    public ChatWindow(String userId, ChatServer server) {
        this.userId = userId;
        this.server = server;
        init();
    }

    private void init() {
        frame = new JFrame("客服 - " + userId);
        frame.setSize(500, 400);
        frame.setLocationRelativeTo(null);
        frame.setLayout(new BorderLayout());

        area = new JTextArea();
        area.setEditable(false);
        area.setLineWrap(true);
        frame.add(new JScrollPane(area), BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        input = new JTextField();
        bottom.add(input, BorderLayout.CENTER);

        JPanel btns = new JPanel();
        sendBtn = new JButton("发送");
        imgBtn = new JButton("图片");
        fileBtn = new JButton("文件");
        btns.add(sendBtn);
        btns.add(imgBtn);
        btns.add(fileBtn);
        bottom.add(btns, BorderLayout.EAST);
        frame.add(bottom, BorderLayout.SOUTH);

        // 事件 -------------------------------------------------
        sendBtn.addActionListener(e -> sendText());
        input.addActionListener(e -> sendText());

        imgBtn.addActionListener(e -> sendImage());
        fileBtn.addActionListener(e -> sendFile());

        frame.setDefaultCloseOperation(JFrame.HIDE_ON_CLOSE);
    }

    public void showWindow() {
        SwingUtilities.invokeLater(() -> frame.setVisible(true));
    }

    public void bringToFront() {
        SwingUtilities.invokeLater(() -> {
            if (!frame.isVisible()) frame.setVisible(true);
            frame.toFront();
        });
    }

    /** 将 Message 渲染到聊天框 */
    public void appendMessage(Message msg) {
        SwingUtilities.invokeLater(() -> {
            try {
                if (msg instanceof TextMessage) {
                    area.append("[用户] " + ((TextMessage) msg).getText() + "\n");
                } else if (msg instanceof ImageMessage) {
                    ImageMessage im = (ImageMessage) msg;
                    area.append("[用户] 发送图片: " + im.getFileName() + "\n");
                    File tmp = new File("tmp_" + im.getFileName());
                    try (FileOutputStream fos = new FileOutputStream(tmp)) {
                        fos.write(im.getData());
                    }
                    ImageIcon icon = new ImageIcon(tmp.getAbsolutePath());
                    area.insertIcon(icon);
                    area.append("\n");
                    tmp.delete();
                } else if (msg instanceof FileMessage) {
                    FileMessage fm = (FileMessage) msg;
                    area.append("[用户] 发送文件: " + fm.getFileName() + "\n");
                    File dir = new File("download");
                    dir.mkdirs();
                    File out = new File(dir, fm.getFileName());
                    try (FileOutputStream fos = new FileOutputStream(out)) {
                        fos.write(fm.getData());
                    }
                }
            } catch (IOException e) { e.printStackTrace(); }
        });
    }

    // ------------------- 发送 -------------------------
    private void sendText() {
        String txt = input.getText().trim();
        if (txt.isEmpty()) return;
        try {
            TextMessage tm = new TextMessage(txt);
            server.sendToUser(userId, tm);
            area.append("[客服] " + txt + "\n");
            input.setText("");
        } catch (IOException e) {
            showErr("发送失败：" + e.getMessage());
        }
    }

    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter(
                "图片", "png","jpg","jpeg","gif"));
        int ret = chooser.showOpenDialog(frame);
        if (ret == JFileChooser.APPROVE_OPTION) {
            File f = chooser.getSelectedFile();
            try {
                byte[] data = java.nio.file.Files.readAllBytes(f.toPath());
                ImageMessage im = new ImageMessage(f.getName(), data);
                server.sendToUser(userId, im);
                area.append("[客服] 发送图片: " + f.getName() + "\n");
                ImageIcon icon = new ImageIcon(f.getAbsolutePath());
                area.insertIcon(icon);
                area.append("\n");
            } catch (IOException e) { showErr("读取图片失败：" + e.getMessage()); }
        }
    }

    private void sendFile() {
        JFileChooser chooser = new JFileChooser();
        int ret = chooser.showOpenDialog(frame);
        if (ret == JFileChooser.APPROVE_OPTION) {
            File f = chooser.getSelectedFile();
            try {
                byte[] data = java.nio.file.Files.readAllBytes(f.toPath());
                FileMessage fm = new FileMessage(f.getName(), data);
                server.sendToUser(userId, fm);
                area.append("[客服] 发送文件: " + f.getName() + "\n");
            } catch (IOException e) { showErr("读取文件失败：" + e.getMessage()); }
        }
    }

    private void showErr(String msg) {
        JOptionPane.showMessageDialog(frame, msg, "错误", JOptionPane.ERROR_MESSAGE);
    }
}

