            } catch (IOException e) { showErr("读取文件失败：" + e.getMessage()); }
        }
    }

    private void showErr(String msg) {
        JOptionPane.showMessageDialog(frame, msg, "错误", JOptionPane.ERROR_MESSAGE);
    }
}

