### 3.2 前端核心：逐字追加函数

```javascript
/**
 * 把字符逐个加入到最新的 bot 气泡中
 * @param {string} char 单字符
 */
function addCharToChat(char) {
    // 找到最后一个 bot 气泡（如果没有则新建一个）
    let lastBotBubble = document.querySelector('#messages .bubble.bot:last-child');
    if (!lastBotBubble) {
        lastBotBubble = document.createElement('div');
        lastBotBubble.className = 'bubble bot';
        document.getElementById('messages').appendChild(lastBotBubble);
    }

    // 移除上一次的光标
    const cursor = lastBotBubble.querySelector('.typing-cursor');
    if (cursor) cursor.remove();

    // 添加字符
    lastBotBubble.textContent += char;

    // 添加光标（让用户感觉还在“打字”）
    const blink = document.createElement('span');
    blink.className = 'typing-cursor';
    lastBotBubble.appendChild(blink);

    // 自动滚动到底部
    lastBotBubble.scrollIntoView({block: 'nearest', behavior: 'smooth'});
}
```

### 3.3 读取方式 A – **EventSource (SSE)**

```javascript
// chat.js (SSE 版)

document.getElementById('sendBtn').addEventListener('click', () => {
    const question = document.getElementById('question').value.trim();
    if (!question) return;

    // 把用户提问显示为左侧气泡
    addUserBubble(question);
    document.getElementById('question').value = '';

    // 创建 SSE 连接（GET 请求，URL中带参数）
    const source = new EventSource(`/api/chat/stream?question=${encodeURIComponent(question)}`);

    source.onmessage = (event) => {
        const char = event.data;   // 服务器发送的单字符
        if (char) addCharToChat(char);
    };

    source.onerror = (err) => {
        console.error('SSE错误', err);
        source.close();
        // 结束光标
        finishBotBubble();
    };
});

function addUserBubble(text) {
    const div = document.createElement('div');
    div.className = 'bubble user';
    div.textContent = text;
    document.getElementById('messages').appendChild(div);
    div.scrollIntoView({behavior: 'smooth'});
}
function finishBotBubble() {
    const cursor = document.querySelector('#messages .bubble.bot .typing-cursor');
    if (cursor) cursor.remove();
}
```

> **SSE 小技巧**  
> - `EventSource` 会自动 **重新连接**（默认 3s），但如果后端已 `complete()`，浏览器会收到 **`readyState === 2 (closed)`** 并停止。  
> - 当后端完成后，我们在 `source.onopen`/`source.onerror` 里手动 `source.close()` 以移除光标。

### 3.4 读取方式 B – **Fetch + ReadableStream**（适用于 `text/plain`）

```javascript
// chat.js (Fetch + ReadableStream 版)

document.getElementById('sendBtn').addEventListener('click', async () => {
    const question = document.getElementById('question').value.trim();
    if (!question) return;
    addUserBubble(question);
    document.getElementById('question').value = '';

    const response = await fetch(`/api/chat/stream?question=${encodeURIComponent(question)}`);
    if (!response.body) {
        console.error('ReadableStream not supported');
        return;
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder('utf-8');

    // 读取循环
    while (true) {
        const {done, value} = await reader.read();
        if (done) {
            finishBotBubble();
            break;
        }
        const chunk = decoder.decode(value);
        // 这里 chunk 可能是一串字符（取决于网络层），我们逐个遍历
        for (const ch of chunk) {
            addCharToChat(ch);
        }
    }
});
```

> **Browser Support**  
> - `ReadableStream` 在所有现代浏览器（Chrome、Edge、Firefox、Safari）均已实现。  
> - 如果你要兼容 **IE**，只能退回 SSE（用 polyfill）或 WebSocket。

### 3.5 读取方式 C – **WebSocket (STOMP / SockJS)**

```javascript
// chat.js (WebSocket + Stomp.js)

let stompClient = null;

function connectWs() {
    const socket = new SockJS('/ws-chat'); // 与后端 @EnableWebSocketMessageBroker 配置保持一致
    stompClient = StompJs.Stomp.over(socket);
    stompClient.connect({}, frame => {
        console.log('Connected: ' + frame);
        stompClient.subscribe('/topic/answer', message => {
            // 服务器返回的内容是 "data:a" 之类的
            const ch = message.body.replace(/^data:/, '');
            addCharToChat(ch);
        });
    }, err => {
        console.error('WebSocket error', err);
    });
}

// 调用一次即可（页面加载时）
connectWs();

document.getElementById('sendBtn').addEventListener('click', () => {
    const q = document.getElementById('question').value.trim();
    if (!q) return;
    addUserBubble(q);
    document.getElementById('question').value = '';
    stompClient.send('/app/ask', {}, q);
});
```

