### 5.3 `ChatController.java`（SSE）

```java
package com.example.chatdemo.controller;

import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.method.annotation.ResponseBodyEmitter;

import java.util.concurrent.*;

@RestController
@RequestMapping("/api/chat")
public class ChatController {

    private final ExecutorService executor = Executors.newCachedThreadPool();

    @GetMapping(value = "/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public ResponseBodyEmitter stream(@RequestParam String question) {
        ResponseBodyEmitter emitter = new ResponseBodyEmitter();

        executor.submit(() -> {
            try {
                String answer = "这是一段示例回答，您输入的是：" + question;
                for (char ch : answer.toCharArray()) {
                    // 对 SSE 必须加上 `data:` 前缀并换行
                    emitter.send("data:" + ch + "\n\n");
                    emitter.flush();
                    Thread.sleep(70);
                }
                emitter.complete();
            } catch (Exception e) {
                emitter.completeWithError(e);
            }
        });

        return emitter;
    }
}
```

