## 3. Recorder – `MouseRecorder.java`

```java
package com.example.mouserecorder;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * The actual worker thread that samples the mouse position
 * every 10 ms (adjustable) while {@code recording} is true.
 */
public class MouseRecorder implements Runnable {

    private volatile boolean recording = false;
    private final List<MouseRecord> buffer = new ArrayList<>();
    private long startTimeMs;

    /** Called by the GUI when the user presses Shift+P */
    public void startRecording() {
        if (recording) return;
        buffer.clear();
        startTimeMs = System.currentTimeMillis();
        recording = true;
        System.out.println("Recording started …");
    }

    /** Called by the GUI when the user presses Shift+L */
    public void stopRecording() {
        recording = false;
        System.out.println("Recording stopped – " + buffer.size() + " points captured.");
    }

    /** Returns a copy of the recorded points (used when saving). */
    public List<MouseRecord> getRecordedData() {
        return new ArrayList<>(buffer);
    }

    @Override
    public void run() {
        try {
            Robot robot = new Robot();               // for getting mouse position
            while (true) {
                if (recording) {
                    Point p = MouseInfo.getPointerInfo().getLocation();
                    long elapsed = System.currentTimeMillis() - startTimeMs;
                    synchronized (buffer) {
                        buffer.add(new MouseRecord(p.x, p.y, elapsed));
                    }
                }
                Thread.sleep(10);                     // sampling rate → 100 Hz
            }
        } catch (AWTException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

