package com.example.mouserecorder;

import java.awt.*;
import java.util.List;

/**
 * Replays a captured list of MouseRecord objects.
 */
public class MousePlayer {

    private final List<MouseRecord> data;
    private final Dimension screenSize;          // to avoid moving outside the monitor

    public MousePlayer(List<MouseRecord> data, Dimension screenSize) {
        this.data = data;
        this.screenSize = screenSize;
    }

    /** Blocking call – moves the mouse exactly as it was recorded. */
    public void play() {
        if (data.isEmpty()) return;
        try {
            Robot robot = new Robot();
            long start = System.currentTimeMillis();

            for (MouseRecord rec : data) {
                long targetTime = start + rec.getTimeDelta();
                long now = System.currentTimeMillis();
                if (targetTime > now) {
                    Thread.sleep(targetTime - now);
                }
                // keep the pointer inside the detected screen bounds
                int x = Math.min(Math.max(rec.getX(), 0), screenSize.width - 1);
                int y = Math.min(Math.max(rec.getY(), 0), screenSize.height - 1);
                robot.mouseMove(x, y);
            }

        } catch (AWTException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

