## 5. Persistent storage – `RecordingStore.java`

```java
package com.example.mouserecorder;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;

import java.io.*;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.List;

/**
 * Serialises / deserialises the whole HashMap<String, List<MouseRecord>>
 * to a JSON file named "recordings.json" placed beside the JAR.
 */
public class RecordingStore {

    private static final String FILE_NAME = "recordings.json";
    private final Gson gson = new GsonBuilder()
            .setPrettyPrinting()
            .create();

    /** Load the file – returns an empty map if the file does not exist or is malformed. */
    public HashMap<String, List<MouseRecord>> load() {
        File f = new File(FILE_NAME);
        if (!f.exists()) {
            return new HashMap<>();
        }

        try (Reader r = new FileReader(f)) {
            Type mapType = new TypeToken<HashMap<String, List<MouseRecord>>>() {}.getType();
            HashMap<String, List<MouseRecord>> map = gson.fromJson(r, mapType);
            return map != null ? map : new HashMap<>();
        } catch (IOException | JsonSyntaxException e) {
            e.printStackTrace();
            return new HashMap<>();
        }
    }

    /** Write the given map to disk (overwrites the old file). */
    public void save(HashMap<String, List<MouseRecord>> map) {
        try (Writer w = new FileWriter(FILE_NAME)) {
            gson.toJson(map, w);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
