```java
package com.example.mouserecorder;

import org.jnativehook.GlobalScreen;
import org.jnativehook.NativeHookException;
import org.jnativehook.keyboard.*;

import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Listens for Shift+P (start) and Shift+L (stop) **anywhere** on the system.
 * Calls back to the supplied MouseRecorder instance.
 */
public class GlobalKeyListener implements NativeKeyListener {

    private final MouseRecorder recorder;

    public GlobalKeyListener(MouseRecorder recorder) {
        this.recorder = recorder;
    }

    /** Register the listener – must be called once on start‑up. */
    public static void install() {
        // suppress the noisy logger that JNativeHook ships with
        Logger logger = Logger.getLogger(GlobalScreen.class.getPackage().getName());
        logger.setLevel(Level.WARNING);
        logger.setUseParentHandlers(false);
    }

    public void start() throws NativeHookException {
        GlobalScreen.registerNativeHook();
        GlobalScreen.addNativeKeyListener(this);
    }

    public void stop() throws NativeHookException {
        GlobalScreen.removeNativeKeyListener(this);
        GlobalScreen.unregisterNativeHook();
    }

    @Override
    public void nativeKeyPressed(NativeKeyEvent e) {
        // Shift + P  => start
        // Shift + L  => stop
        if ((e.getModifiers() & NativeKeyEvent.SHIFT_MASK) != 0) {
            if (e.getKeyCode() == NativeKeyEvent.VC_P) {
                recorder.startRecording();
            } else if (e.getKeyCode() == NativeKeyEvent.VC_L) {
                recorder.stopRecording();
            }
        }
    }

    @Override public void nativeKeyReleased(NativeKeyEvent e) {}
    @Override public void nativeKeyTyped(NativeKeyEvent e) {}
}
```

