## 7. The Swing GUI – `MainWindow.java`

```java
package com.example.mouserecorder;

import org.jnativehook.NativeHookException;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;

/**
 * The single window that shows:
 *  * screen size
 *  * a table with all recordings (name | #points)
 *  * buttons: Save current, Delete, Play
 *  * status bar
 */
public class MainWindow extends JFrame {

    private final MouseRecorder recorder = new MouseRecorder();
    private final RecordingStore store = new RecordingStore();
    private final HashMap<String, List<MouseRecord>> recordings; // in‑memory map
    private final JTable table;
    private final DefaultTableModel tableModel;
    private final JLabel statusLabel = new JLabel("Ready");
    private final Dimension screenSize;

    public MainWindow() throws NativeHookException {
        super("Mouse Recorder / Player");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        // ── Detect screen size ───────────────────────────────────────
        screenSize = Toolkit.getDefaultToolkit().getScreenSize();
        add(new JLabel("Screen size: " + screenSize.width + "×" + screenSize.height), BorderLayout.NORTH);

        // ── Load persisted recordings ─────────────────────────────────
        recordings = store.load();

        // ── Table UI ───────────────────────────────────────────────────
        tableModel = new DefaultTableModel(new Object[]{"Name", "Points"}, 0) {
            @Override public boolean isCellEditable(int row, int column) { return false; }
        };
        table = new JTable(tableModel);
        refreshTableModel();

        JScrollPane scroll = new JScrollPane(table);
        add(scroll, BorderLayout.CENTER);

        // ── Bottom panel (buttons + status) ───────────────────────────
        JPanel bottom = new JPanel(new BorderLayout());

        JPanel buttons = new JPanel();
        JButton saveBtn = new JButton("Save current (Shift+P/Shift+L)");
        JButton deleteBtn = new JButton("Delete");
        JButton playBtn = new JButton("Play");

        buttons.add(saveBtn);
        buttons.add(deleteBtn);
        buttons.add(playBtn);
        bottom.add(buttons, BorderLayout.WEST);
        bottom.add(statusLabel, BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);

        // ── Action listeners ───────────────────────────────────────────
        saveBtn.addActionListener(e -> onSaveCurrent());
        deleteBtn.addActionListener(e -> onDelete());
        playBtn.addActionListener(e -> onPlay());

        // double‑click on a row = play
        table.addMouseListener(new MouseAdapter() {
            public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2) {
                    onPlay();
                }
            }
        });

        // ── Background thread that does the actual sampling ─────────────
        Thread recThread = new Thread(recorder, "Mouse‑Recorder‑Thread");
        recThread.setDaemon(true);
        recThread.start();

        // ── Install global hot‑keys (Shift+P / Shift+L) ──────────────────
        GlobalKeyListener.install();
        GlobalKeyListener keyListener = new GlobalKeyListener(recorder);
        keyListener.start();

        // ── Window size & centre ───────────────────────────────────────
        setSize(500, 400);
        setLocationRelativeTo(null);
    }

    /** Refresh the table view from the in‑memory HashMap. */
    private void refreshTableModel() {
        SwingUtilities.invokeLater(() -> {
            tableModel.setRowCount(0);
            for (Map.Entry<String, List<MouseRecord>> e : recordings.entrySet()) {
                tableModel.addRow(new Object[]{e.getKey(), e.getValue().size()});
            }
        });
    }

    /** Prompt for a name and store the last‑recorded data. */
    private void onSaveCurrent() {
        List<MouseRecord> data = recorder.getRecordedData();
        if (data.isEmpty()) {
            showStatus("No data to save – record something first.");
            return;
        }

        String name = JOptionPane.showInputDialog(
                this,
                "Enter a name for this recording:",
                "Save recording",
                JOptionPane.QUESTION_MESSAGE);

        if (name == null || name.trim().isEmpty()) {
            showStatus("Save cancelled.");
            return;
        }

        recordings.put(name.trim(), data);
        store.save(recordings);
        refreshTableModel();
        showStatus("Saved recording \"" + name + "\" (" + data.size() + " points).");
    }

    /** Delete the selected entry (after confirmation). */
    private void onDelete() {
        int row = table.getSelectedRow();
        if (row < 0) {
            showStatus("Select a row to delete.");
            return;
        }
        String name = (String) tableModel.getValueAt(row, 0);
        int confirm = JOptionPane.showConfirmDialog(
                this,
                "Delete recording \"" + name + "\" ?",
                "Confirm delete",
                JOptionPane.YES_NO_OPTION);
        if (confirm == JOptionPane.YES_OPTION) {
            recordings.remove(name);
            store.save(recordings);
            refreshTableModel();
            showStatus("Deleted \"" + name + "\".");
        }
    }

    /** Play the selected recording (in a background thread). */
    private void onPlay() {
        int row = table.getSelectedRow();
        if (row < 0) {
            showStatus("Select a recording to play.");
            return;
        }
        String name = (String) tableModel.getValueAt(row, 0);
        List<MouseRecord> data = recordings.get(name);
        if (data == null) {
            showStatus("Record not found – weird!");
            return;
        }

        // disable UI while playing
        setControlsEnabled(false);
        showStatus("Playing \"" + name + "\" …");

        new Thread(() -> {
            new MousePlayer(data, screenSize).play();
            SwingUtilities.invokeLater(() -> {
                setControlsEnabled(true);
                showStatus("Finished playing \"" + name + "\".");
            });
        }, "Player‑Thread").start();
    }

    private void setControlsEnabled(boolean enabled) {
        table.setEnabled(enabled);
    }

    private void showStatus(String msg) {
        statusLabel.setText(msg);
    }

    /** Entry‑point */
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try {
                new MainWindow().setVisible(true);
            } catch (NativeHookException e) {
                JOptionPane.showMessageDialog(
                        null,
                        "Failed to install global hot‑keys:\n" + e.getMessage(),
                        "Error",
                        JOptionPane.ERROR_MESSAGE);
                System.exit(1);
            }
        });
    }
}
```

