import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.Mat;
import org.bytedeco.opencv.global.opencv_imgcodecs;
import org.bytedeco.opencv.global.opencv_imgproc;

import java.awt.image.BufferedImage;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 简易的 H.264 Socket Server
 *
 * 1. 监听端口 (默认 9999)，接受客户端推送的裸 H.264（含 start code 0x000001/0x00000001）。
 * 2. 把读取到的字节写入 PipedOutputStream，另一端的 PipedInputStream 交给 FFmpegFrameGrabber 解码。
 * 3. 解码得到 Frame → BufferedImage → CanvasFrame 显示。
 *
 * 注意：
 *   - 为了兼容网络抖动，使用了 BlockingQueue 做缓冲（上限 30 帧）。
 *   - 若客户端发送的是 “长度前缀” 的 H.264（4‑byte length），请自行把 length 解析后再写入流。
 *   - 关闭时会释放所有资源。
 */
public class H264SocketServer {

    // ------------------- 配置 -------------------
    private static final int SERVER_PORT = 9999;            // 监听端口
    private static final int QUEUE_CAPACITY = 30;           // 解码前帧队列（控制延迟/内存）
    // ------------------------------------------------

    private final ServerSocket serverSocket;
    private final ExecutorService clientExecutor = Executors.newSingleThreadExecutor();
    private final ExecutorService decoderExecutor = Executors.newSingleThreadExecutor();
    private final BlockingQueue<byte[]> frameQueue = new ArrayBlockingQueue<>(QUEUE_CAPACITY);
    private final AtomicBoolean running = new AtomicBoolean(true);

    public H264SocketServer(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        System.out.println("[Server] Listening on port " + port);
    }

    /** 启动 Server：接受客户端、启动解码、显示 */
    public void start() {
        // 1. 接受客户端
        clientExecutor.submit(this::acceptClient);

        // 2. 启动解码线程
        decoderExecutor.submit(this::decodeAndShow);
    }

    /** 接受唯一一个客户端（示例代码只处理单连接） */
    private void acceptClient() {
        try (Socket socket = serverSocket.accept()) {
            System.out.println("[Server] Client connected from " + socket.getRemoteSocketAddress());

            // 把网络流直接写入 frameQueue（会把 start‑code 解析为完整 NAL 单元）
            try (InputStream in = new BufferedInputStream(socket.getInputStream())) {
                // 读取并拆分 NAL 单元（这里我们直接按 start code 分割）
                while (running.get()) {
                    byte[] nal = readNextNal(in);
                    if (nal == null) break; // EOF

                    // 只保留完整 NAL（含 start code），放入队列
                    if (!frameQueue.offer(nal)) {
                        // 队列满了，直接丢帧（避免阻塞网络读取）
                        System.out.println("[Server] Dropping frame (queue full)");
                    }
                }
            }
        } catch (IOException e) {
            if (running.get()) {
                e.printStackTrace();
            }
        } finally {
            shutdown();
        }
    }

    /**
     * 从 InputStream 中读取下一个 NAL 单元（以 0x000001 / 0x00000001 start code 为边界）。
     * 返回的 byte[] 包含完整的 start code + NAL 数据。
     * 若流结束返回 null。
     */
    private byte[] readNextNal(InputStream in) throws IOException {
        // 用循环读取，检测 start code
        ByteArrayOutputStream baos = new ByteArrayOutputStream();

        // 读取到第一个 start code
        int b;
        // state machine to detect start code (0,0,0,1) or (0,0,1)
        int zeroCount = 0;
        while ((b = in.read()) != -1) {
            if (b == 0) {
                zeroCount++;
                continue;
            }
            if (b == 1 && zeroCount >= 2) {
                // start code found, push the leading zeros + 0x01
                for (int i = 0; i < zeroCount; i++) baos.write(0);
                baos.write(1);
                break;
            }
            // we have seen some non‑zero bytes before start code -> treat as data
            for (int i = 0; i < zeroCount; i++) baos.write(0);
            baos.write(b);
            zeroCount = 0;
        }
        if (b == -1) {
            // EOF 前可能已经累计了部分数据，返回 null
            return null;
        }

        // Now read the NAL payload until the next start code (which we will *peek*)
        ByteArrayOutputStream payload = new ByteArrayOutputStream();
        zeroCount = 0;
        while ((b = in.read()) != -1) {
            if (b == 0) {
                zeroCount++;
                payload.write(0);
                continue;
            }
            if (b == 1 && zeroCount >= 2) {
                // reached the next start code: rewind the bytes belonging to start code (2~4 zeros + 1)
                int startCodeLen = zeroCount >= 3 ? 4 : 3;
                // 把多余的 zeros（>=2）从 payload 中去掉，使其只保留前面的 NAL 数据
                byte[] raw = payload.toByteArray();
                int cut = raw.length - (zeroCount - (startCodeLen - 1));
                byte[] nalWithoutNextStart = new byte[cut];
                System.arraycopy(raw, 0, nalWithoutNextStart, 0, cut);
                baos.write(nalWithoutNextStart);
                // 把本次 start code 重新写回流首部，以便下一次读取时捕捉到
                // 这里我们使用 PushbackInputStream 更优雅，但为了简化直接把 start code 前缀留给下次读取
                // 所以把已经读取的 start code (zeros+1) 放回 “peek” 缓冲区：
                ((PushbackInputStream) in).unread(buildStartCode(startCodeLen));
                break;
            }
            // regular byte
            payload.write(b);
            zeroCount = 0;
        }

        // Append the payload we collected (if we exited because EOF, payload may be non‑empty)
        baos.write(payload.toByteArray());
        return baos.toByteArray();
    }

    /** 构造对应长度的 start code（3 或 4 字节） */
    private byte[] buildStartCode(int len) {
        if (len == 3) return new byte[]{0, 0, 1};
        else return new byte[]{0, 0, 0, 1};
    }

    /** 解码线程：把 NAL 数据喂给 FFmpegFrameGrabber，渲染到 Canvas */
    private void decodeAndShow() {
        // 使用 Piped流把 NAL 数据“伪装”成普通 InputStream，供 Grabber 拉取
        try (PipedOutputStream pipedOut = new PipedOutputStream();
             PipedInputStream pipedIn = new PipedInputStream(pipedOut);
             FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(pipedIn)) {

            // 指定输入格式为裸 H264
            grabber.setFormat("h264");
            grabber.setOption("rtsp_transport", "tcp"); // (optional)
            grabber.start();

            // Canvas 用来显示帧
            CanvasFrame canvas = new CanvasFrame("H.264 Live", CanvasFrame.getDefaultGamma() / grabber.getGamma());
            canvas.setDefaultCloseOperation(javax.swing.JFrame.EXIT_ON_CLOSE);
            canvas.setCanvasSize(grabber.getImageWidth(), grabber.getImageHeight());

            // 主循环：从队列取 NAL 写进 pipedOut → Grabber 拉取 → 渲染
            while (running.get() && canvas.isVisible()) {
                byte[] nal = frameQueue.poll(100, TimeUnit.MILLISECONDS);
                if (nal == null) continue; // 超时，继续循环

                // 写入管道（阻塞），相当于把裸流喂给 FFmpeg
                pipedOut.write(nal);
                pipedOut.flush();

                // 拉帧（非阻塞）
                Frame frame = grabber.grabImage(); // 只抓 video
                if (frame != null) {
                    // 转 BufferedImage 并显示
                    Java2DFrameConverter converter = new Java2DFrameConverter();
                    BufferedImage img = converter.convert(frame);
                    canvas.showImage(img);
                }
            }

            // 收尾
            canvas.dispose();
            grabber.stop();
            grabber.release();

        } catch (Exception e) {
            if (running.get())
                e.printStackTrace();
        } finally {
            shutdown();
        }
    }

    /** 关闭全部资源 */
    public void shutdown() {
        if (!running.compareAndSet(true, false)) {
            return; // 已经关闭
        }
        try {
            serverSocket.close();
        } catch (IOException ignored) {
        }
        clientExecutor.shutdownNow();
        decoderExecutor.shutdownNow();
        System.out.println("[Server] Shut down.");
    }

    // ------------------------------------------------------------------------
    // 主入口（演示）
    // ------------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        H264SocketServer server = new H264SocketServer(SERVER_PORT);
        server.start();

        // 按下 <Enter> 键退出
        System.out.println("Press <Enter> to stop the server...");
        System.in.read();
        server.shutdown();
    }
}
```

### 关键实现说明

| 步骤 | 代码片段 | 目的 |
|------|----------|------|
| **① 创建 ServerSocket** | `new ServerSocket(port)` | 监听端口，接受客户端 TCP 连接 |
| **② 把网络流拆成 NAL 单元** | `readNextNal(InputStream)` | 检测 **0x000001 / 0x00000001** start code，确保每次向解码器喂入完整 NAL（含 SPS / PPS） |
| **③ 使用阻塞队列** | `ArrayBlockingQueue<byte[]>` | 防止网络读取过快导致内存暴涨，控制最大延迟（`QUEUE_CAPACITY`） |
| **④ 把 NAL 写入 PipedOutputStream** | `pipedOut.write(nal)` | 把 NAL 流转成 `InputStream`，交给 `FFmpegFrameGrabber`（FFmpeg 会把它当成 **裸 h264** 来解码） |
| **⑤ 初始化 Grabber** | `grabber.setFormat("h264")` | 告诉 FFmpeg 输入是 **raw H.264**（非容器） |
| **⑥ 把 Frame 转 BufferedImage** | `Java2DFrameConverter` | OpenCV `CanvasFrame` 只接受 `BufferedImage` |
| **⑦ 渲染** | `canvas.showImage(img)` | 实时把每帧画到窗口 |
| **⑧ 结束清理** | `shutdown()` | 关闭 socket、线程池、FFmpeg 等资源 |

> **为什么要使用 `PipedInputStream/OutputStream` ？**  
> `FFmpegFrameGrabber` 只能直接读取 `InputStream`。我们把网络解包后的 NAL 放进 `BlockingQueue`，再逐帧写到 `PipedOutputStream`，这样解码器会像读取本地文件一样顺序拉取数据，而不需要一次性把全部流装进内存。

