        // 1️⃣ Открываем документ
        WordprocessingMLPackage wordPackage = WordprocessingMLPackage.load(sourceDocx);
        MainDocumentPart mdp = wordPackage.getMainDocumentPart();

        // 2️⃣ Конвертируем в PDF, получаем поток в памяти
        ByteArrayOutputStream pdfOut = new ByteArrayOutputStream();
        PdfConversion conversion = new Conversion(wordPackage);
        conversion.output(pdfOut, new org.docx4j.convert.out.pdf.PdfSettings());

        // 3️⃣ Считаем количество страниц в получившемся PDF
        int pageCount;
        try (PDDocument pdfDoc = PDDocument.load(new ByteArrayInputStream(pdfOut.toByteArray()))) {
            pageCount = pdfDoc.getNumberOfPages();
        }

        System.out.println("Найдено страниц в PDF: " + pageCount);

        // 4️⃣ Обновляем все поля NUMPAGES (и PAGE, если нужно) внутри docx
        updateNumPagesFields(mdp, pageCount);

        // 5️⃣ Сохраняем изменённый документ
        wordPackage.save(targetDocx);
        System.out.println("Обновлённый файл сохранён в: " + targetDocx.getAbsolutePath());
    }

    /**
     * Пробегаем все {@link org.docx4j.wml.SdtElement} и {@link org.docx4j.wml.R}
     * в поисках полей типа NUMPAGES. Как только нашли – заменяем их результатом.
     */
    private void updateNumPagesFields(MainDocumentPart mdp, int pageCount) throws Exception {
        // В docx4j есть готовый утилитный класс FieldUpdater,
        // но он рассчитывает только простые поля (PAGE, NUMPAGES и т.д.) без макетов.
        // Мы используем его, предварительно задав нужный totalPageCount.

        // Переопределяем виртуальный обработчик, который будет возврашать наш pageCount.
        FieldUpdater fieldUpdater = new FieldUpdater() {
            @Override
            public String evaluate(String instr) throws Exception {
                // instr – то, что стоит в атрибуте w:instr, например " NUMPAGES ".
                String trimmed = instr.trim().toUpperCase();
                if ("NUMPAGES".equals(trimmed)) {
                    return Integer.toString(pageCount);
                }
                // Если захотим поддержать PAGE (текущий номер), можно вернуть "1" сейчас,
                // а позже при реальной разметке он будет заменён.
                if ("PAGE".equals(trimmed)) {
                    return "1"; // placeholder – реальное значение будет пересчитано в Word
                }
                // Для остальных полей – делегируем базовую реализацию
                return super.evaluate(instr);
            }
        };

        // Обходим весь контент документа
        List<Object> bodyElements = mdp.getJaxbElement().getBody().getContent();
        for (Object element : bodyElements) {
            // Рекурсивно обновляем поля во всех вложенных объектах
            updateFieldsRecursively(element, fieldUpdater);
        }
    }

    /** Рекурсивный обход JAXB‑дерева и обновление полей */
    @SuppressWarnings("unchecked")
    private void updateFieldsRecursively(Object obj, FieldUpdater updater) throws Exception {
        if (obj == null) return;

        if (obj instanceof JAXBElement) {
            obj = ((JAXBElement<?>) obj).getValue();
        }

        // 1️⃣ Если это SimpleField (w:fldSimple) – заменяем её содержимое
        if (obj instanceof CTSimpleField) {
            CTSimpleField simpleField = (CTSimpleField) obj;
            String instr = simpleField.getInstr();
            String newValue = updater.evaluate(instr);
            // Создаём простой run <w:r><w:t>value</w:t></w:r>
            R run = new R();
            Text txt = new Text();
            txt.setValue(newValue);
            run.getContent().add(txt);
            // Очищаем старый контент и вставляем наш run
            simpleField.getContent().clear();
            simpleField.getContent().add(run);
            return;
        }

        // 2️⃣ Если это ComplexField (FieldChar + FieldCode + FieldResult)
        if (obj instanceof R) {
            R run = (R) obj;
            // Поиск вложенных элементов, среди которых могут быть FieldChar и т.д.
            for (Object inner : run.getContent()) {
                if (inner instanceof JAXBElement) {
                    inner = ((JAXBElement<?>) inner).getValue();
                }
                if (inner instanceof CTSimpleField) {
                    // уже обработали выше – пропускаем
                }
                // прочие типы игнорируем
            }
        }

        // 3️⃣ Для контейнерных объектов (Paragraph, Table, etc.) рекурсивно обходим их дочерние элементы
        if (obj instanceof ContentAccessor) {
            List<Object> children = ((ContentAccessor) obj).getContent();
            for (Object child : children) {
                updateFieldsRecursively(child, updater);
            }
        }

        // 4️⃣ Специально обрабатываем Structured Document Tags (SdtBlock, SdtRun), т.к. они могут скрывать поле внутри
        if (obj instanceof SdtBlock) {
            SdtBlock sdt = (SdtBlock) obj;
            updateFieldsRecursively(sdt.getSdtContent(), updater);
        } else if (obj instanceof SdtRun) {
            SdtRun sdt = (SdtRun) obj;
            updateFieldsRecursively(sdt.getSdtContent(), updater);
        } else if (obj instanceof SdtContent) {
            SdtContent sdtContent = (SdtContent) obj;
            updateFieldsRecursively(sdtContent.getContent(), updater);
        }
    }

    // -----------------------------------------------------------------------
    // Точка входа – простой запуск из командной строки
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        if (args.length != 2) {
            System.err.println("Usage: java -jar NumPagesResolver.jar <source.docx> <target.docx>");
            System.exit(1);
        }

        File src = new File(args[0]);
        File dst = new File(args[1]);

        if (!src.exists()) {
            System.err.println("Source file does not exist: " + src);
            System.exit(2);
        }

        new NumPagesResolver(src, dst).execute();
    }
}
```

### Как работает код

| Шаг | Что делаем | Зачем |
|-----|-----------|------|
| **1.** `WordprocessingMLPackage.load` | Открываем `docx` в виде объекта `docx4j`. | Позволяет работать с XML‑структурой без ручного парсинга. |
| **2.** `PdfConversion` → `ByteArrayOutputStream` | Конвертируем документ в PDF через `docx4j` (XSL‑FO). | При конвертации движок делает layout → знает реальное число страниц. |
| **3.** `PDDocument.load(...).getNumberOfPages()` | Считываем количество страниц из готового PDF. | PDFBox умеет точно посчитать страницы. |
| **4.** `FieldUpdater` (переопределённый) | Заменяем все встреченные `NUMPAGES` на найденное число. | Поле `NUMPAGES` в `docx` заменяется реальным значением, а не оставляется «поле‑заглушка». |
| **5.** `wordPackage.save` | Сохраняем изменённый `docx`. | Получаем файл, готовый к дальнейшему использованию (печати, отправки, …). |

