## 3️⃣ Spring‑Security 配置

### 3.1 `MyAuthenticationSuccessHandler`

```java
// src/main/java/com/example/demo/handler/MyAuthenticationSuccessHandler.java
package com.example.demo.handler;

import jakarta.servlet.ServletException;
import jakarta.servlet.http.*;
import java.io.IOException;
import java.util.Collection;
import org.springframework.security.core.*;
import org.springframework.security.web.authentication.AuthenticationSuccessHandler;
import org.springframework.stereotype.Component;

/**
 * 登录成功后根据拥有的角色重定向。
 *
 * 约定：
 *   - ADMIN → /admin
 *   - USER  → /user
 *   - 其它   → /home（或者 403/错误页面）
 *
 * 如果用户拥有多个角色，优先级可自行定义（这里先检查 ADMIN，再 USER）。
 */
@Component
public class MyAuthenticationSuccessHandler implements AuthenticationSuccessHandler {

    @Override
    public void onAuthenticationSuccess(HttpServletRequest request,
                                        HttpServletResponse response,
                                        Authentication authentication)
            throws IOException, ServletException {

        // 获取所有 GrantedAuthority
        Collection<? extends GrantedAuthority> authorities = authentication.getAuthorities();

        // 这里演示最常见的“角色优先级”写法
        String redirectUrl = null;
        if (authorities.stream().anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN"))) {
            redirectUrl = "/admin";
        } else if (authorities.stream().anyMatch(a -> a.getAuthority().equals("ROLE_USER"))) {
            redirectUrl = "/user";
        } else {
            redirectUrl = "/home";   // 默认页面（或 throw new AccessDeniedException）
        }

        // 防止缓存旧页面
        response.setStatus(HttpServletResponse.SC_FOUND);
        response.sendRedirect(redirectUrl);
    }
}
```

### 3.2 `SecurityConfig`

```java
// src/main/java/com/example/demo/config/SecurityConfig.java
package com.example.demo.config;

import org.springframework.context.annotation.*;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.*;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.crypto.password.*;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.*;
import com.example.demo.handler.MyAuthenticationSuccessHandler;
import com.example.demo.service.MyUserDetailsService;

/**
 * Spring Security 主配置（基于 SecurityFilterChain，Spring Security 6 推荐写法）。
 *
 * 关键点：
 *   1. 使用 `MyAuthenticationSuccessHandler` 实现登录后跳转。
 *   2. 用 `requestMatchers(...).hasRole(...)` 定义不同路径只能被对应角色访问。
 *   3. 开启方法安全（@PreAuthorize、@Secured、@RolesAllowed）。
 */
@Configuration
@EnableWebSecurity
@EnableMethodSecurity   // 为 @PreAuthorize 等注解做好准备
public class SecurityConfig {

    /** 1️⃣ 注入我们自己实现的 UserDetailsService */
    @Bean
    public UserDetailsService userDetailsService(MyUserDetailsService service) {
        return service;
    }

    /** 2️⃣ PasswordEncoder（这里使用明文，仅示例） */
    @Bean
    public PasswordEncoder passwordEncoder() {
        // 为了演示直接返回 NoOpPasswordEncoder，生产请使用 BCryptPasswordEncoder
        return NoOpPasswordEncoder.getInstance();
        // return new BCryptPasswordEncoder(); // 若改成 Bcrypt，请把用户密码改为 BCrypt 加密串
    }

    /** 3️⃣ DAO Authentication Provider（把上面两个 Bean 组合） */
    @Bean
    public DaoAuthenticationProvider authenticationProvider(UserDetailsService uds,
                                                             PasswordEncoder encoder) {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
        provider.setUserDetailsService(uds);
        provider.setPasswordEncoder(encoder);
        return provider;
    }

    /** 4️⃣ 业务核心 —— SecurityFilterChain */
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http,
                                           MyAuthenticationSuccessHandler successHandler) throws Exception {

        // 关闭 CSRF（演示用），实际生产请视情况保留或自定义
        http.csrf(csrf -> csrf.disable());

        // ---------- 登录页面 ----------
        http.formLogin(form -> form
                .loginPage("/login")          // 自定义登录页
                .loginProcessingUrl("/perform_login")
                .successHandler(successHandler) // <-- 关键：成功后交给我们自定义的 handler
                .failureUrl("/login?error=true")
                .permitAll());

        // ---------- 登出 ----------
        http.logout(logout -> logout
                .logoutUrl("/logout")
                .logoutSuccessUrl("/login?logout")
                .invalidateHttpSession(true)
                .deleteCookies("JSESSIONID")
                .permitAll());

        // ---------- 页面访问控制 ----------
        http.authorizeHttpRequests(auth -> auth
                // 允许所有人访问登录相关页面、静态资源、根路径等
                .requestMatchers("/", "/index", "/login", "/css/**", "/js/**", "/images/**")
                    .permitAll()

                // ADMIN 角色专属页面（/admin/**）
                .requestMatchers("/admin/**")
                    .hasRole("ADMIN")   // Spring Security 默认会在角色前加 "ROLE_"

                // USER 角色专属页面（/user/**）
                .requestMatchers("/user/**")
                    .hasRole("USER")

                // 其它请求必须登录（登录后凭角色决定是否可以访问）
                .anyRequest()
                    .authenticated()
        );

        // ---------- 记住我（可选） ----------
        http.rememberMe(rememberMe -> rememberMe
                .key("uniqueAndSecret")   // 必须保持唯一
                .tokenValiditySeconds(7 * 24 * 60 * 60) // 7 天
        );

        // ---------- 异常处理 ----------
        http.exceptionHandling(exc -> exc
                .accessDeniedPage("/access-denied")
        );

        // ---------- 启用 HTTP Basic（仅用于调试或 API） ----------
        // http.httpBasic(Customizer.withDefaults());

        // ---------- 使用我们自定义的 AuthenticationProvider ----------
        http.authenticationProvider(authenticationProvider(
                userDetailsService(http.getSharedObject(UserDetailsService.class)),
                passwordEncoder()
        ));

        return http.build();
    }
}
```

> **解释**  
> - `requestMatchers("/admin/**").hasRole("ADMIN")`：只有拥有 `ROLE_ADMIN` 的用户才能访问 `/admin/**`。  
> - `successHandler`：负责登录成功后 **把用户根据角色送到对应的首页**（`/admin`、`/user`、`/home`）。  
> - `@EnableMethodSecurity` + `@PreAuthorize`：如果你想在 **业务层** 再防一次，可以在 Controller/Service 方法上标注 `@PreAuthorize("hasRole('ADMIN')")`。  

