## 6. MyBatis Mapper 接口 & XML

> 为了演示关联查询，这里 **UserMapper** 使用 **resultMap** 把 `unit` 与 `role` 自动映射进 `User` 对象。

### 6.1 `UserMapper.java`

```java
package com.example.login.dao;

import com.example.login.entity.User;
import org.apache.ibatis.annotations.Param;

public interface UserMapper {
    // 根据用户名查询（登录时使用）
    User selectByUsername(@Param("username") String username);

    // 通过 ID 查询，连带 Unit、Role
    User selectById(@Param("id") Long id);
}
```

### 6.2 `UserMapper.xml`

```xml
<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE mapper PUBLIC "-//mybatis.org//DTD Mapper 3.0//EN"
        "http://mybatis.org/dtd/mybatis-3-mapper.dtd">

<mapper namespace="com.example.login.dao.UserMapper">

    <!-- resultMap：把 Unit、Role 关联进 User -->
    <resultMap id="UserResultMap" type="com.example.login.entity.User">
        <id property="id" column="id"/>
        <result property="username" column="username"/>
        <result property="password" column="password"/>
        <result property="salt" column="salt"/>
        <result property="realName" column="real_name"/>
        <result property="email" column="email"/>
        <result property="unitId" column="unit_id"/>
        <result property="roleId" column="role_id"/>

        <!-- 嵌套查询填充关联对象 -->
        <association property="unit" javaType="com.example.login.entity.Unit">
            <id property="id" column="unit_id"/>
            <result property="name" column="unit_name"/>
            <result property="address" column="unit_address"/>
        </association>

        <association property="role" javaType="com.example.login.entity.Role">
            <id property="id" column="role_id"/>
            <result property="name" column="role_name"/>
        </association>
    </resultMap>

    <!-- 登录查询（只返回基础列，后面手动再查询完整信息） -->
    <select id="selectByUsername" parameterType="String" resultMap="UserResultMap">
        SELECT 
            u.*, 
            un.name AS unit_name, un.address AS unit_address,
            r.name AS role_name
        FROM user u
        LEFT JOIN unit un ON u.unit_id = un.id
        LEFT JOIN role r ON u.role_id = r.id
        WHERE u.username = #{username}
    </select>

    <!-- 通过 ID 完整查询（和上面的 SELECT 相同） -->
    <select id="selectById" parameterType="Long" resultMap="UserResultMap">
        SELECT 
            u.*, 
            un.name AS unit_name, un.address AS unit_address,
            r.name AS role_name
        FROM user u
        LEFT JOIN unit un ON u.unit_id = un.id
        LEFT JOIN role r ON u.role_id = r.id
        WHERE u.id = #{id}
    </select>

</mapper>
```

> **说明**  
> * `association` 里把 `unit_*`、`role_*` 列映射到 `User` 的嵌套对象。  
> * 如果你只想查询用户基本信息而不关联对象，可以另写 `selectSimpleByUsername`，这里直接把完整信息返回，省去二次查询。

