## 8. Spring MVC 控制器

### 8.1 `LoginController.java`

```java
package com.example.login.controller;

import com.example.login.entity.User;
import com.example.login.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;

import jakarta.servlet.http.HttpSession;

@Controller
public class LoginController {

    @Autowired
    private UserService userService;

    /** 登录页 */
    @GetMapping({"/", "/login"})
    public String loginPage() {
        return "login"; // /WEB-INF/jsp/login.jsp
    }

    /** 登录提交 */
    @PostMapping("/login")
    public String login(@RequestParam String username,
                        @RequestParam String password,
                        HttpSession session,
                        Model model) {
        User user = userService.login(username, password);
        if (user == null) {
            model.addAttribute("msg", "用户名或密码错误");
            return "login";
        }
        // 登录成功，把 User 放进 Session
        session.setAttribute("CURRENT_USER", user);
        return "redirect:/home";
    }

    /** 首页（登录后可访问） */
    @GetMapping("/home")
    public String home(HttpSession session, Model model) {
        User cur = (User) session.getAttribute("CURRENT_USER");
        if (cur == null) {
            return "redirect:/login";
        }
        model.addAttribute("user", cur);
        return "home";
    }

    /** 退出 */
    @GetMapping("/logout")
    public String logout(HttpSession session) {
        session.invalidate();
        return "redirect:/login";
    }
}
```

> **注**：  
> * `home.jsp` 将展示 **用户真实姓名、所属单位、角色** 信息。  
> * `CURRENT_USER` 是我们自己定义的 Session 键，实际项目可封装到统一的 **登录态** 结构里。  

