import javax.servlet.*;

public class WebAppInitializer implements WebApplicationInitializer {
    @Override
    public void onStartup(ServletContext sc) throws ServletException {
        AnnotationConfigWebApplicationContext root = new AnnotationConfigWebApplicationContext();
        root.register(com.example.login.config.MyBatisConfig.class);
        sc.addListener(new ContextLoaderListener(root));

        AnnotationConfigWebApplicationContext mvc = new AnnotationConfigWebApplicationContext();
        mvc.register(com.example.login.config.WebMvcConfig.class);

        ServletRegistration.Dynamic ds = sc.addServlet("dispatcher", new DispatcherServlet(mvc));
        ds.setLoadOnStartup(1);
        ds.addMapping("/");
    }
}
