package com.example.login.service.impl;

import com.example.login.dao.UserMapper;
import com.example.login.entity.User;
import com.example.login.service.UserService;
import org.apache.commons.codec.digest.DigestUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class UserServiceImpl implements UserService {

    @Autowired private UserMapper userMapper;

    private String encrypt(String plain, String salt) {
        return DigestUtils.md5Hex(plain + salt);
    }

    @Override
    @Transactional(readOnly = true)
    public User login(String username, String plainPwd) {
        User db = userMapper.selectByUsername(username);
        if (db == null) return null;
        if (!encrypt(plainPwd, db.getSalt()).equalsIgnoreCase(db.getPassword())) {
            return null;
        }
        // db 已经包含 unit、role（因为 selectByUsername 已经关联查询）
        return db;
    }
}
```

