## Пример простого сетевого чата на TCP  
Ниже – два небольших Java‑приложения:  

* **ChatServer** – сервер, принимает подключения от произвольного количества клиентов и рассылaет каждое полученное сообщение всем подключённым.  
* **ChatClient** – клиент, который соединяется с сервером, отправляет вводимые в консоль строки и выводит полученные от сервера сообщения.

Оба проекта работают в консоли, используют только стандартную библиотеку JDK ( `java.net`, `java.io`, `java.util.concurrent` ) и одинаково компилируются любой версией Java 8+.

---

## 1. Сервер (ChatServer.java)

```java
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/**
 * Простой TCP‑сервер чата.
 * Принимает произвольное количество подключений,
 * каждое полученное сообщение рассылает всем клиентам.
 */
public class ChatServer {

    // Порт, на котором слушает сервер
    private static final int PORT = 12345;

    // Потокобезопасный набор всех активных клиентских соединений
    private final Set<ClientHandler> clients = ConcurrentHashMap.newKeySet();

    public static void main(String[] args) throws IOException {
        new ChatServer().start();
    }

    /** Запуск сервера */
    public void start() throws IOException {
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println("Сервер запущен, слушает порт " + PORT);

        // Основной цикл – принимаем новые подключения
        while (true) {
            Socket socket = serverSocket.accept();           // блокирует до появления клиента
            System.out.println("Подключился клиент: " + socket);
            ClientHandler handler = new ClientHandler(socket);
            clients.add(handler);
            new Thread(handler).start();                     // отдельный поток для каждого клиента
        }
    }

    /** Отправить сообщение всем подключённым клиентам */
    private void broadcast(String message, ClientHandler exclude) {
        for (ClientHandler client : clients) {
            // Можно исключить отправителя, если не хотим, чтобы он получал своё же сообщение
            if (client != exclude) {
                client.send(message);
            }
        }
    }

    /** Обработчик соединения с одним клиентом */
    private class ClientHandler implements Runnable {
        private final Socket socket;
        private BufferedReader in;
        private PrintWriter out;
        private String clientName = "Аноним";

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                // Инициализируем потоки ввода/вывода
                in = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
                out = new PrintWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"), true);

                // Первая строка – это имя клиента (можно просто ввести в клиенте)
                out.println("Введите своё имя:");
                clientName = in.readLine();
                if (clientName == null || clientName.trim().isEmpty()) {
                    clientName = "Аноним";
                }
                broadcast("** " + clientName + " присоединился к чату **", this);
                System.out.println(clientName + " подключён.");

                // Чтение сообщений от клиента
                String line;
                while ((line = in.readLine()) != null) {
                    if (line.trim().isEmpty()) continue;
                    String formatted = clientName + ": " + line;
                    System.out.println(formatted);
                    broadcast(formatted, this);   // рассылаем всем, включая отправителя (можно убрать this)
                }
            } catch (IOException e) {
                System.err.println("Ошибка связи с клиентом: " + e.getMessage());
            } finally {
                // Отключаем клиента
                try {
                    socket.close();
                } catch (IOException ignored) {}
                clients.remove(this);
                broadcast("** " + clientName + " вышел из чата **", this);
                System.out.println(clientName + " отключён.");
            }
        }

        /** Отправить сообщение конкретному клиенту */
        void send(String message) {
            out.println(message);
        }
    }
}
```

### Как работает сервер  

1. **ServerSocket** слушает указанный порт (`12345`).  
2. При подключении создаётся объект `ClientHandler`, который получает отдельный поток.  
3. Внутри `ClientHandler` читаем строку с именем клиента, а затем в бесконечном цикле — каждое сообщение от него.  
4. Метод `broadcast` рассылает полученное сообщение всем остальным клиентам (можно включить и отправителя).  
5. При разрыве соединения клиент удаляется из общего набора, а всем клиентам отправляется сообщение о выходе.

---

## 2. Клиент (ChatClient.java)

```java
import java.io.*;
import java.net.*;
import java.util.Scanner;

/**
 * Простой TCP‑клиент чата.
 * Читает ввод пользователя в консоли и передаёт его серверу.
 * Параллельно выводит входящие сообщения от сервера.
 */
public class ChatClient {

    // Адрес и порт сервера (по умолчанию localhost)
    private static final String SERVER_HOST = "localhost";
    private static final int SERVER_PORT = 12345;

    public static void main(String[] args) {
        new ChatClient().start();
    }

    /** Запуск клиентского приложения */
    public void start() {
        try (Socket socket = new Socket(SERVER_HOST, SERVER_PORT)) {
            System.out.println("Подключены к серверу " + SERVER_HOST + ":" + SERVER_PORT);

            // Открываем потоки ввода/вывода
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
            PrintWriter out = new PrintWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"), true);

            // Поток чтения сообщений от сервера (в отдельном потоке)
            Thread readerThread = new Thread(() -> {
                try {
                    String line;
                    while ((line = in.readLine()) != null) {
                        System.out.println(line);
                    }
                } catch (IOException e) {
                    System.err.println("Соединение с сервером потеряно.");
                }
            });
            readerThread.setDaemon(true);
            readerThread.start();

            // Основной ввод пользователя
            Scanner scanner = new Scanner(System.in, "UTF-8");
            while (true) {
                if (!scanner.hasNextLine()) break;          // EOF (Ctrl+D)
                String msg = scanner.nextLine();
                out.println(msg);
                // Можно добавить локальный вывод, если не хотите ждать эхо от сервера:
                // System.out.println("Вы: " + msg);
            }
        } catch (IOException e) {
            System.err.println("Не удалось подключиться к серверу: " + e.getMessage());
        }
    }
}
```

### Как работает клиент  

1. Создаёт `Socket` и подключается к серверу.  
2. Открывает `BufferedReader` (вход от сервера) и `PrintWriter` (выход к серверу).  
3. Запускает отдельный поток, который читает строки от сервера и выводит их в консоль.  
4. В главном потоке читает ввод пользователя (`Scanner`) и отправляет каждую строку серверу.  

