    LineBasedClient client = new LineBasedClient("127.0.0.1", 9001);
    client.connect();

    new Thread(() -> {
        try { client.readLoop(); } catch (IOException e) { e.printStackTrace(); }
    }).start();

    client.sendLine("First message");
    client.sendLine("第二条消息");
    // 连续发送多行…
}
```

