package com.example.mailreader;

import jakarta.mail.*;
import jakarta.mail.search.FlagTerm;

import java.util.Hashtable;
import java.util.Properties;

/**
 * Fetches e‑mail messages from an IMAP server and stores
 * the subject (assumed to be a number) together with the body
 * (also assumed to be a number) into a Hashtable.
 */
public class ImapNumberCollector {

    /** Holds subject → body mapping */
    private final Hashtable<String, String> numberTable = new Hashtable<>();

    /** Configuration – replace with your own values */
    private final String host = "imap.example.com";    // IMAP server host
    private final int port = 993;                     // 993 for IMAPS, 143 for plain IMAP
    private final String username = "myuser@example.com";
    private final String password = "mySuperSecretPassword";

    /** Whether to use SSL (IMAPS) */
    private final boolean useSsl = true;

    public static void main(String[] args) {
        ImapNumberCollector collector = new ImapNumberCollector();
        collector.run();
        collector.printResult();
    }

    /** Entry point – open the folder, read messages and close everything */
    public void run() {
        Store store = null;
        Folder inbox = null;
        try {
            // 1️⃣ Build a Session
            Session session = Session.getInstance(createSessionProperties());
            // 2️⃣ Connect to the store (IMAP or IMAPS)
            store = session.getStore(useSsl ? "imaps" : "imap");
            store.connect(host, port, username, password);

            // 3️⃣ Open INBOX in READ‑ONLY mode (use READ_WRITE if you want to set flags)
            inbox = store.getFolder("INBOX");
            inbox.open(Folder.READ_ONLY);

            // 4️⃣ Find only UNSEEN messages – change the search term if you need everything
            Message[] messages = inbox.search(new FlagTerm(new Flags(Flags.Flag.SEEN), false));
            System.out.println("Found " + messages.length + " unread message(s).");

            // 5️⃣ Process each message
            for (Message msg : messages) {
                processMessage(msg);
            }

        } catch (Exception e) {
            System.err.println("Error while reading mail: " + e.getMessage());
            e.printStackTrace();
        } finally {
            // 6️⃣ Clean‑up
            try {
                if (inbox != null && inbox.isOpen()) inbox.close(false);
                if (store != null) store.close();
            } catch (MessagingException me) {
                // ignore – we are shutting down anyway
            }
        }
    }

    /** Returns a Properties object configured for IMAP/IMAPS */
    private Properties createSessionProperties() {
        Properties props = new Properties();
        if (useSsl) {
            props.put("mail.imap.ssl.enable", "true");
            props.put("mail.imap.starttls.enable", "true");
        }
        // Optional – debug output (set to true if you need to troubleshoot)
        props.put("mail.debug", "false");
        return props;
    }

    /** Extracts the subject and (plain‑text) body, then stores them in the Hashtable */
    private void processMessage(Message msg) {
        try {
            // --- 1️⃣ Subject ----------------------------------------------------
            String subject = msg.getSubject();
            if (subject == null) subject = "";
            subject = subject.trim();

            // --- 2️⃣ Body --------------------------------------------------------
            String body = extractPlainText(msg);
            if (body == null) body = "";
            body = body.trim();

            // You can add any validation you like, e.g. make sure both strings look like numbers
            // For demonstration we just store whatever we got.
            numberTable.put(subject, body);
            System.out.println("Stored: [" + subject + "] → [" + body + "]");

        } catch (Exception e) {
            System.err.println("Failed to process a message: " + e.getMessage());
        }
    }

    /**
     * Walks through the content of a Message and returns the first plain‑text
     * part it encounters. Handles simple text messages as well as multipart
     * (e.g. “text/plain + text/html”).
     */
    private String extractPlainText(Part part) throws Exception {
        if (part.isMimeType("text/plain")) {
            return (String) part.getContent();
        }

        if (part.isMimeType("multipart/*")) {
            Multipart mp = (Multipart) part.getContent();
            for (int i = 0; i < mp.getCount(); i++) {
                String s = extractPlainText(mp.getBodyPart(i));
                if (s != null && !s.isEmpty()) {
                    return s; // return first non‑empty plain text part
                }
            }
        }

        // For other MIME types (e.g., text/html) you can optionally strip HTML,
        // but the question asked for a simple number, so we ignore them.
        return null;
    }

    /** Just prints the whole Hashtable to STDOUT – replace with your own logic */
    private void printResult() {
        System.out.println("\n=== Final Hashtable Content ===");
        numberTable.forEach((k, v) -> System.out.println("Subject: [" + k + "]  Body: [" + v + "]"));
    }

    // -------------------------------------------------------------------------
    // ── If you prefer a modern, non‑synchronized Map, replace the Hashtable   │
    // ── with:                                                                  │
    //     private final Map<String,String> numberMap = new ConcurrentHashMap<>(); │
    // ── The rest of the code works unchanged.                                 │
    // -------------------------------------------------------------------------
}
