    private val SERVER_HOST = "192.168.1.100"   // IP или домен
    private val SERVER_PORT = 12345            // порт

    private lateinit var etMessage: EditText
    private lateinit var btnSend: Button
    private lateinit var tvResult: TextView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        etMessage = findViewById(R.id.etMessage)
        btnSend = findViewById(R.id.btnSend)
        tvResult = findViewById(R.id.tvResult)

        btnSend.setOnClickListener {
            val msg = etMessage.text.toString()
            if (msg.isBlank()) {
                tvResult.text = "Введите сообщение"
                return@setOnClickListener
            }
            // Запускаем работу в фоновой корутине
            lifecycleScope.launch {
                sendMessageToServer(msg)
            }
        }
    }

    /**
     * Открывает сокет, отправляет сообщение, читает ответ (если нужен)
     */
    private suspend fun sendMessageToServer(message: String) = withContext(Dispatchers.IO) {
        var socket: Socket? = null
        var writer: BufferedWriter? = null
        var reader: BufferedReader? = null

        try {
            // 1️⃣ Подключаемся (таймаут 5 сек)
            socket = Socket()
            socket.connect(InetSocketAddress(SERVER_HOST, SERVER_PORT), 5_000)

            // 2️⃣ Открываем потоки ввода/вывода
            writer = BufferedWriter(OutputStreamWriter(socket.getOutputStream()))
            reader = BufferedReader(InputStreamReader(socket.getInputStream()))

            // 3️⃣ Отправляем строку + перевод строки, если сервер ждёт line‑delimited данные
            writer.write(message)
            writer.newLine()
            writer.flush()

            // 4️⃣ (Опционально) Читаем ответ сервера
            val response = reader.readLine() ?: "Нет ответа"
            // Обновляем UI (переключаемся обратно в Main‑поток)
            runOnUiThread {
                tvResult.text = "Ответ сервера: $response"
            }

        } catch (e: IOException) {
            e.printStackTrace()
            runOnUiThread {
                tvResult.text = "Ошибка: ${e.localizedMessage}"
            }
        } finally {
            // 5️⃣ Чистим ресурсы
            try { writer?.close() } catch (ignored: IOException) {}
            try { reader?.close() } catch (ignored: IOException) {}
            try { socket?.close() } catch (ignored: IOException) {}
        }
    }
}
