public class ResourcePackageValidator {

    private static final Log LOG = LogFactory.get();

    // -----------------------------------------------------------------------
    // 1️⃣  Constants (converted to enums for compile‑time safety
    // -----------------------------------------------------------------------

    private enum ResourceFolder {
        PANORAMA("全景图片"),
        LOCAL("局部图片"),
        VIDEO("视频");

        private final String displayName;

        ResourceFolder(String displayName) {
            this.displayName = displayName;
        }

        public String displayName() {
            return displayName;
        }

        /** reverse‑lookup by display name */
        static Optional<ResourceFolder> of(String name) {
            return Arrays.stream(values())
                    .filter(r -> r.displayName.equals(name))
                    .findFirst();
        }
    }

    /** allowed image extensions (lower‑case, no leading dot) */
    private static final Set<String> IMG_EXT = Set.of("jpg", "jpeg", "png", "gif", "bmp", "webp");

    /** allowed video extensions */
    private static final Set<String> VIDEO_EXT = Set.of("mp4", "avi", "mov", "wmv", "flv", "mkv");

    // -----------------------------------------------------------------------
    // 2️⃣  Public entry point
    // -----------------------------------------------------------------------

    /**
     * Validates a list of uploaded zip files.
     *
     * @param zipList list of multipart zip files coming from the client
     * @return a list of discovered resource‑names (the folder names under the zip root)
     * @throws BaseException on the first validation failure
     */
    public List<String> validateAndCollectNames(List<MultipartFile> zipList) {
        Objects.requireNonNull(zipList, "zipList must not be null");

        List<String> resourceNames = new ArrayList<>();

        for (MultipartFile multipartFile : zipList) {
            // 1️⃣ Guard clause – ensure we really got a zip
            if (!isZipFile(multipartFile)) {
                String name = FileUtil.getName(multipartFile.getOriginalFilename());
                reject(name + "格式不正确，请上传zip格式的文件");
            }

            // 2️⃣ Unzip into a *temporary* directory and guarantee cleanup
            try (TemporaryUnzipFolder tmp = unzipToTempFolder(multipartFile)) {
                Path root = tmp.getRoot();   // this must be a directory

                // 3️⃣ Validate top‑level structure and collect resource‑name folders
                List<Path> nameDirs = listDirectories(root);
                if (nameDirs.isEmpty()) {
                    reject(tmp.getOriginalName() + "文件为空");
                }

                for (Path nameDir : nameDirs) {
                    String resourceName = nameDir.getFileName().toString();
                    resourceNames.add(resourceName);
                    validateResourceNameFolder(nameDir);
                }
            } catch (IOException e) {
                // Wrap any IO problem into our domain exception – we do NOT leak stack‑traces to the client.
                LOG.error("Failed to process zip file {}", multipartFile.getOriginalFilename(), e);
                reject("处理文件时发生错误，请稍后重试或联系管理员。");
            }
        }

