    // 3️⃣  Low‑level helpers – each does ONE thing and throws BaseException
    // -----------------------------------------------------------------------

    /** Guard‑clause for validation errors – never returns. */
    private static void reject(String msg) {
        throw new BaseException(msg);
    }

    /** Check that a multipart file is a zip (by magic bytes). */
    private static boolean isZipFile(MultipartFile file) {
        try (InputStream is = file.getInputStream()) {
            // Hutool's FileTypeUtil probes the first few bytes – it works for zip.
            String type = FileTypeUtil.getType(is);
            return "zip".equalsIgnoreCase(type);
        } catch (IOException e) {
            LOG.warn("Unable to read uploaded file {} for type detection", file.getOriginalFilename(), e);
            return false;
        }
    }

    /**
     * Unzip a MultipartFile into a **temporary directory**.
     *
     * <p>
     *   The returned {@link TemporaryUnzipFolder} implements {@link AutoCloseable}
     *   and will delete the folder automatically when the try‑with‑resources block ends.
     * </p>
     */
    private static TemporaryUnzipFolder unzipToTempFolder(MultipartFile multipartFile) throws IOException {
        // Create a temp directory that will be deleted later
        Path tempDir = Files.createTempDirectory("uploaded-zip-");

        // Retrieve original file name (without extension) for better error messages
        String originalBaseName = FileUtil.getName(multipartFile.getOriginalFilename());

        // Unzip using Hutool – it accepts a Charset; we keep the original GBK behaviour,
        // but you may switch to UTF‑8 if you control the client side.
        Charset zipCharset = Charset.forName("GBK");
        try (InputStream zipIs = multipartFile.getInputStream()) {
            // Hutool's unzip returns the *folder* it extracted to (or the file itself if not a zip)
            File extracted = ZipUtil.unzip(zipIs, tempDir.toFile(), zipCharset);
            if (!extracted.isDirectory()) {
                reject(originalBaseName + "目录不正确，解压后没有得到文件夹");
            }
            return new TemporaryUnzipFolder(tempDir, originalBaseName);
        }
    }

    /** Simple wrapper around a temporary folder that auto‑deletes on close. */
    private static final class TemporaryUnzipFolder implements AutoCloseable {
        private final Path root;
        private final String originalName;

        TemporaryUnzipFolder(Path root, String originalName) {
            this.root = root;
            this.originalName = originalName;
        }

        Path getRoot()   { return root; }
        String getOriginalName() { return originalName; }

        @Override
        public void close() {
            try {
                Files.walk(root)
                        .sorted(Comparator.reverseOrder())
                        .forEach(p -> {
                            try {
                                Files.deleteIfExists(p);
                            } catch (IOException e) {
                                LOG.warn("Failed to delete temporary file {}", p, e);
                            }
                        });
            } catch (IOException e) {
                LOG.warn("Failed to clean up temporary directory {}", root, e);
            }
        }
    }

    /** Return only *sub‑directories* of a given folder (throws BaseException if none). */
    private static List<Path> listDirectories(Path dir) {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, Files::isDirectory)) {
            List<Path> dirs = new ArrayList<>();
            for (Path p : stream) {
                dirs.add(p);
            }
            return dirs;
        } catch (IOException e) {
            reject("无法读取目录 " + dir + "，请检查文件完整性");
            return Collections.emptyList(); // unreachable, but compiler likes it
        }
    }

    /** Validate a single resource‑name folder (the second level of the zip). */
    private static void validateResourceNameFolder(Path resourceNameDir) {
        // Defensive check – must be a directory
        if (!Files.isDirectory(resourceNameDir)) {
            reject(resourceNameDir.getFileName() + "目录不正确");
        }

        // Inside the resource‑name folder we expect the three *type* folders.
        List<Path> typeFolders = listDirectories(resourceNameDir);
        if (typeFolders.isEmpty()) {
            reject(resourceNameDir.getFileName() + "目录为空，请上传全景图片/局部图片/视频子目录");
        }

        for (Path typeFolder : typeFolders) {
            String typeName = typeFolder.getFileName().toString();

            // 1️⃣ Verify that we recognise the type (panorama, local, video)
            ResourceFolder typeEnum = ResourceFolder.of(typeName)
                    .orElseThrow(() -> new BaseException(resourceNameDir.getFileName() + "目录不正确，未知子目录 “" + typeName + "”"));

            // 2️⃣ Gather all files under this type folder (no deeper nesting allowed)
            List<Path> files = listFiles(typeFolder);
            if (files.isEmpty()) {
                // It’s okay to have an empty folder – you may decide otherwise.
                continue;
            }

            // 3️⃣ Validate each file according to the type
            for (Path file : files) {
                String ext = FileUtil.extName(file.toFile()).toLowerCase(Locale.ROOT);
                if (typeEnum == ResourceFolder.VIDEO) {
                    if (!VIDEO_EXT.contains(ext)) {
                        reject(buildInvalidMessage(resourceNameDir, typeEnum, file, VIDEO_EXT));
                    }
                } else { // PANORAMA or LOCAL – both are image types
                    if (!IMG_EXT.contains(ext)) {
                        reject(buildInvalidMessage(resourceNameDir, typeEnum, file, IMG_EXT));
                    }
                }
            }
        }
    }

    /** List regular files (not directories) inside a folder – throws BaseException on error. */
    private static List<Path> listFiles(Path dir) {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir, Files::isRegularFile)) {
            List<Path> list = new ArrayList<>();
            for (Path p : stream) {
                list.add(p);
            }
            return list;
        } catch (IOException e) {
            reject("无法读取文件列表：" + dir);
            return Collections.emptyList(); // unreachable
        }
    }

    /** Build a uniform error message for an invalid file extension. */
    private static String buildInvalidMessage(Path resourceNameDir,
                                              ResourceFolder type,
                                              Path offendingFile,
                                              Set<String> allowed) {
        String allowedStr = allowed.stream()
                .sorted()
                .collect(Collectors.joining(", "));
        return String.format("%s-%s的%s文件格式不正确，请上传 %s",
                resourceNameDir.getFileName(),
                type.displayName(),
                offendingFile.getFileName(),
                allowedStr);
    }
}
