import org.jcodec.api.SequenceEncoder;
import org.jcodec.api.awt.AWTSequenceEncoder8Bit;
import org.jcodec.common.io.NIOUtils;
import org.jcodec.common.model.Rational;
import org.jcodec.containers.mp4.MP4Muxer;
import org.jcodec.containers.mp4.boxes.Fragment;
import org.jcodec.containers.mp4.boxes.MovieFragmentBox;

import javax.websocket.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

/**
 * 1）从外部线程把 BufferedImage 放入 queue
 * 2）EncoderThread 从 queue 读取、编码并把每个 fragment 写入 ByteBuffer
 * 3）把 ByteBuffer 通过 WebSocket binaryMessage 发送
 */
public class H264WebSocketServer {

    // ---------- WebSocket 部分 ----------
    @ServerEndpoint("/video")
    public static class VideoEndpoint {
        private static final BlockingQueue<Session> sessions = new LinkedBlockingQueue<>();

        @OnOpen
        public void onOpen(Session session) {
            sessions.offer(session);
        }

        @OnClose
        public void onClose(Session session) {
            sessions.remove(session);
        }

        /** 推送一个 fragment（byte[]）给所有在线客户端 */
        static void broadcast(byte[] data) {
            for (Session s : sessions) {
                if (s.isOpen()) {
                    s.getAsyncRemote().sendBinary(ByteBuffer.wrap(data));
                }
            }
        }
    }

    // ---------- 编码线程 ----------
    public static class EncoderThread extends Thread {
        private final BlockingQueue<BufferedImage> imgQueue = new LinkedBlockingQueue<>();
        private final int fps;
        private final int width;
        private final int height;

        public EncoderThread(int width, int height, int fps) {
            this.width = width;
            this.height = height;
            this.fps = fps;
        }

        /** 外部调用：投喂一帧图片 */
        public void offer(BufferedImage img) throws InterruptedException {
            imgQueue.put(img);
        }

        @Override
        public void run() {
            try {
                // 1) 创建一个 “内存” MP4Muxer → 写入到 OutputChannel（ByteBuffer）
                SeekableByteChannel out = NIOUtils.writableChannel(new java.io.ByteArrayOutputStream());
                MP4Muxer muxer = MP4Muxer.createMP4Muxer(out);
                // 2) 创建 H.264 编码器（AVCEncoder在JCodec内部），并把它绑定到 MP4Muxer
                AWTSequenceEncoder8Bit encoder = AWTSequenceEncoder8Bit.createWithMuxer(
                        out, Rational.R(fps, 1), muxer, width, height);
                // 启用 fragmented MP4 (fmp4) 模式
                encoder.setFragmented(true);
                encoder.setChunkSize(1); // 每帧产生一个 fragment（便于 WebSocket 逐帧推送）

                while (true) {
                    BufferedImage img = imgQueue.take(); // 阻塞等待下一帧
                    encoder.encodeImage(img);
                    // 3) 每次 encodeImage() 会产生一个 fragment，立刻 flush 并读取
                    encoder.flush(); // 把内部 buffer 写入 out

                    // 读取已写出的数据
                    out.setPosition(0);
                    ByteBuffer frag = NIOUtils.readFromChannel(out, (int) out.size());

                    // 4) 通过 WebSocket 推送
                    VideoEndpoint.broadcast(frag.array());

                    // 为下一帧清空 out（要把写指针归零）
                    out.truncate(0);
                }
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
