            java.awt.Graphics2D g = img.createGraphics();
            g.setColor(java.awt.Color.getHSBColor((i % 360) / 360f, 0.8f, 0.8f));
            g.fillRect(0, 0, w, h);
            g.setColor(java.awt.Color.WHITE);
