    -pix_fmt yuv420p             # h264 要求的像素格式
    -f mp4                       # 输出 mp4（后面加 frag 参数）
    -movflags frag_keyframe+empty_moov+default_base_moof \
    -metadata:s:v:0 title="live" \
    -   # 把输出也写到 stdout
