        ffmpeg = pb.start();
        ffmpegIn = new BufferedOutputStream(ffmpeg.getOutputStream());
        ffmpegOut = new BufferedInputStream(ffmpeg.getInputStream());
    }

    /** 外部调用投喂一帧图片 */
    public void offer(BufferedImage img) throws InterruptedException {
        imgQueue.put(img);
    }

    @Override
    public void run() {
        try {
            // 单独线程读 ffmpeg stdout → WebSocket
            Thread reader = new Thread(() -> {
                try {
                    byte[] buf = new byte[64 * 1024];
                    int read;
                    while ((read = ffmpegOut.read(buf)) != -1) {
                        // 将读取到的完整 fragment 直接广播
                        byte[] fragment = new byte[read];
                        System.arraycopy(buf, 0, fragment, 0, read);
                        LiveWsEndpoint.broadcast(fragment);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }, "ffmpeg-stdout-reader");
            reader.setDaemon(true);
            reader.start();

            // 主循环：把 BufferedImage 按 JPEG 写入 ffmpeg stdin
            while (true) {
                BufferedImage img = imgQueue.take();   // 阻塞等待下一帧

