```java
package com.example.datasource;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.datasource.lookup.AbstractRoutingDataSource;

import javax.sql.DataSource;
import java.util.HashMap;
import java.util.Map;

/**
 * 1️⃣ 创建真实的 DataSource（这里用 HikariCP）<br>
 * 2️⃣ 把它们交给自定义的 RoutingDataSource
 */
@Configuration
public class DataSourceConfig {

    /** 真实的数据源（示例），可以在 application.yml 中用列表方式统一配置 */
    @Bean("dsDeviceA")
    @ConfigurationProperties(prefix = "datasource.device-a")
    public DataSource dsDeviceA() {
        return new HikariDataSource();
    }

    @Bean("dsDeviceB")
    @ConfigurationProperties(prefix = "datasource.device-b")
    public DataSource dsDeviceB() {
        return new HikariDataSource();
    }

    @Bean("defaultDs")
    @ConfigurationProperties(prefix = "datasource.default")
    public DataSource defaultDs() {
        return new HikariDataSource();
    }

    /** 3️⃣ 路由数据源 */
    @Primary
    @Bean
    public DataSource routingDataSource(
            @Qualifier("dsDeviceA") DataSource dsDeviceA,
            @Qualifier("dsDeviceB") DataSource dsDeviceB,
            @Qualifier("defaultDs") DataSource defaultDs) {

        Map<Object, Object> targetDataSources = new HashMap<>();
        // key 为业务层面约定的 lookupKey
        targetDataSources.put("DEVICE_A", dsDeviceA);
        targetDataSources.put("DEVICE_B", dsDeviceB);

        RoutingDataSource routing = new RoutingDataSource();
        routing.setDefaultTargetDataSource(defaultDs);
        routing.setTargetDataSources(targetDataSources);
        routing.afterPropertiesSet(); // 必须调用，否则内部 map 为 null

        return routing;
    }

    /** 4️⃣ 自定义的 AbstractRoutingDataSource */
    static class RoutingDataSource extends AbstractRoutingDataSource {
        @Override
        protected Object determineCurrentLookupKey() {
            // 从 ThreadLocal 中拿到当前线程应该使用的 key
            return DataSourceContextHolder.getLookupKey();
        }
    }
}
