## 4️⃣ Server 端代码改造（核心实现）

```java
package com.example.server;

import com.example.datasource.DataSourceContextHolder;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Map;
import java.util.concurrent.*;

@Slf4j
@Component
public class SocketServer implements ApplicationRunner {

    /** 监听端口（固定 9000） */
    private static final int PORT = 9000;

    /** IP → 数据源 lookupKey 的映射（这里直接写死，实际可放到配置文件） */
    private static final Map<String, String> IP_TO_DS_KEY = Map.of(
            "192.168.1.10", "DEVICE_A",
            "192.168.1.20", "DEVICE_B"
            // … 其他设备
    );

    /** 线程池：每个客户端独立线程，避免阻塞 accept() */
    private final ExecutorService executor = new ThreadPoolExecutor(
            4,                                   // core pool size
            50,                                  // max pool size
            60L, TimeUnit.SECONDS,               // idle thread keep-alive
            new SynchronousQueue<>(),
            new ThreadFactory() {
                private final ThreadFactory defaultFactory = Executors.defaultThreadFactory();
                private int counter = 0;
                @Override
                public Thread newThread(Runnable r) {
                    Thread t = defaultFactory.newThread(r);
                    t.setName("socket-client-" + (++counter));
                    t.setDaemon(true);
                    return t;
                }
            });

    @Override
    public void run(ApplicationArguments args) {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            log.info("🚀 Server started, listening on port {}", PORT);

            while (!executor.isShutdown()) {
                Socket socket = serverSocket.accept(); // 阻塞等待客户端
                log.info("🔗 Client connected: {}", socket.getInetAddress());

                // 为每个连接提交一个独立任务
                executor.submit(() -> processClient(socket));
            }
        } catch (IOException e) {
            log.error("Server socket error", e);
        } finally {
            shutdownExecutor();
        }
    }

    /** 处理单个 client 的完整流程（包括切换数据源） */
    private void processClient(Socket socket) {
        String clientIp = socket.getInetAddress().getHostAddress();
        try {
            // ① 根据 IP 选出 lookupKey
            String lookupKey = IP_TO_DS_KEY.getOrDefault(clientIp, null);
            if (lookupKey != null) {
                DataSourceContextHolder.setLookupKey(lookupKey);
                log.debug("🧭 Set datasource key [{}] for client {}", lookupKey, clientIp);
            } else {
                log.warn("⚠️ No datasource mapping for client {}, will use default DS", clientIp);
                DataSourceContextHolder.clear(); // 使用默认库
            }

            // ② 真正的业务处理（这里保持原有签名不变）
            handleClient(socket);

        } catch (Exception ex) {
            log.error("Error while handling client {}", clientIp, ex);
        } finally {
            // ③ 清理 ThreadLocal，防止泄漏
            DataSourceContextHolder.clear();
            try {
                socket.close();
            } catch (IOException ignored) {
            }
        }
    }

    /** ------------------- 业务处理保持原样 ------------------- */
    private void handleClient(Socket socket) {
        // 这里可以直接注入你的 Service / Repository 并使用 DB
        // 例：int cnt = deviceDataRepository.countRows();
        //       socket.getOutputStream().write(("Rows: " + cnt).getBytes());

        // 示例实现（原来的 System.out.print）
        try {
            socket.getOutputStream().write(("Hello, your IP is " + socket.getInetAddress() + "\n")
                    .getBytes());
            socket.getOutputStream().flush();
        } catch (IOException e) {
            log.error("IO error on client socket", e);
        }
    }

    /** 正常关闭线程池 */
    private void shutdownExecutor() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException ignored) {
            executor.shutdownNow();
        }
    }
}
```

### 关键点拆解

| 位置 | 代码片段 | 作用 |
|------|----------|------|
|`IP_TO_DS_KEY`|`Map.of("192.168.1.10","DEVICE_A", …)`|把 **客户端 IP** 与 **DataSource lookupKey** 关联起来，实际可以放在 `application.yml` 中读取|
|`processClient()`|`DataSourceContextHolder.setLookupKey(lookupKey)`|在进入业务层之前把对应的 key 写入 ThreadLocal，之后所有 DAO 会走到对应的库|
|`finally`|`DataSourceContextHolder.clear()`|防止线程复用时把旧的 key 泄漏到下一个请求|
|`executor`|线程池|每个客户端用独立线程，`accept()` 不会被阻塞|
|`handleClient(socket)`|保持原有业务实现|业务层可以直接注入 `@Repository`/`@Service`，不需要关心切库细节|

