```java
@Component
@RequiredArgsConstructor
public class SocketServer implements ApplicationRunner {

    private final Environment env; // 或者 @ConfigurationProperties

    private final Map<String, String> clientMapping = new HashMap<>();

    @PostConstruct
    public void initMapping() {
        // 读取 application.yml 中的 client-datasource-mapping
        // 注意：Spring Boot 会把点号 "." 替换为 "_"，这里用 Environment 直接取
        for (String ip : env.getProperty("client-datasource-mapping", Map.class).keySet()) {
            clientMapping.put(ip, env.getProperty("client-datasource-mapping." + ip));
        }
    }
    // …后面使用 clientMapping 替代硬编码的 IP_TO_DS_KEY
}
```

