package com.mediaworld.apimanager.configuration.redis;

import org.reactivestreams.Publisher;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.connection.ReactiveRedisConnection;
import org.springframework.data.redis.connection.ReactiveRedisConnectionFactory;
import org.springframework.data.redis.core.ReactiveRedisCallback;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.data.redis.serializer.GenericToStringSerializer;
import org.springframework.data.redis.serializer.JdkSerializationRedisSerializer;
import org.springframework.data.redis.serializer.RedisSerializationContext;
import org.springframework.data.redis.serializer.StringRedisSerializer;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.server.HandlerFilterFunction;
import org.springframework.web.reactive.function.server.HandlerFunction;
import org.springframework.web.reactive.function.server.ServerRequest;
import org.springframework.web.reactive.function.server.ServerResponse;
import reactor.core.publisher.Mono;

import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.time.Duration;
import java.time.LocalTime;
import java.util.List;
import java.util.Optional;

/**
 * A **functional‑endpoint** filter that implements a fixed‑window rate limiter
 * using a reactive Redis transaction (MULTI/EXEC emulated with a single connection).
 *
 * <p>NOTE:
 * <ul>
 *   <li>`@Value` cannot be used on a static field – it must be an instance field.</li>
 *   <li>The `ReactiveRedisTemplate` bean is **not** created inside this class; it will be
 *       provided by a @Configuration class (see below).</li>
 * </ul>
 */
@Component   // so that it can be @Autowired wherever you need it
public class RateLimiterHandlerFilterFunction
        implements HandlerFilterFunction<ServerResponse, ServerResponse> {

    /** configurable via `application.yml` (or `application.properties`) */
    @Value("${app.rate-limit.max-requests-per-minute:20}")
    private long maxRequestsPerMinute = 20L;          // default = 20

    private final ReactiveRedisTemplate<String, Long> redisTemplate;

    public RateLimiterHandlerFilterFunction(ReactiveRedisTemplate<String, Long> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    @Override
    public Mono<ServerResponse> filter(ServerRequest request,
                                       HandlerFunction<ServerResponse> next) {

        // 1️⃣  Build the per‑minute key: rl_<client-ip>:<minute>
        int currentMinute = LocalTime.now().getMinute();
        String key = String.format("rl_%s:%s",
                requestAddress(request.remoteAddress()), currentMinute);

        // 2️⃣  Read the current counter and decide:
        return redisTemplate.opsForValue()
                .get(key)
                .flatMap(currentValue ->
                        currentValue != null && currentValue >= maxRequestsPerMinute
                                // ❌ limit exceeded → 429 Too Many Requests
                                ? ServerResponse.status(HttpStatus.TOO_MANY_REQUESTS).build()
                                // ✅ otherwise increment + set expiry and continue
                                : incrAndExpireKey(key, request, next))
                // If the key does not exist yet → treat as count == 0
                .switchIfEmpty(incrAndExpireKey(key, request, next));
    }

    /** Helper – extracts a host name (or empty string) from the optional remote address */
    private String requestAddress(Optional<InetSocketAddress> maybeAddress) {
        return maybeAddress.map(InetSocketAddress::getHostString).orElse("");
    }

    /**
     * Atomically <code>INCR</code> the key and <code>EXPIRE</code> it after 59 seconds.
     * The API does *not* expose a true MULTI/EXEC transaction but the callback guarantees
     * that both commands run on the **same** connection, which is enough for a fixed‑window
     * limiter.
     */
    private Mono<ServerResponse> incrAndExpireKey(String key,
                                                  ServerRequest request,
                                                  HandlerFunction<ServerResponse> next) {

        return redisTemplate.execute(new ReactiveRedisCallback<List<Object>>() {
            @Override
            public Publisher<List<Object>> doInRedis(ReactiveRedisConnection connection)
                    throws DataAccessException {

                ByteBuffer bbKey = ByteBuffer.wrap(key.getBytes());

                // The two commands are executed sequentially on the same connection.
                // (Redis guarantees atomicity for INCR+EXPIRE on a single key.)
                return Mono.zip(
                        connection.numberCommands().incr(bbKey),
                        connection.keyCommands().expire(bbKey, Duration.ofSeconds(59L))
                ).then(); // we discard the results, we only need the side‑effects
            }
        }).then(next.handle(request));
    }

    /** ------------------------------------------------------------------- *
     *  The bean that creates the ReactiveRedisTemplate belongs in a @Configuration
     *  class (see the next code block).  It is *not* placed here because this
     *  class is a Component that will be instantiated **after** the template is
     *  ready.
     *  ------------------------------------------------------------------- */
}
```

> **Why move the `@Bean` out of the filter?**  
> `@Bean` methods are only processed on `@Configuration` classes. If you keep the method inside a component, Spring will **not** invoke it and you’ll end up with a `null` template. The configuration class shown below solves that.

