import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.ReactiveRedisConnectionFactory;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.core.ReactiveRedisTemplate;
import org.springframework.data.redis.serializer.*;

@Configuration
public class ReactiveRedisConfig {

    /** 
     *  Adjust host/port (or pick them up from `spring.redis.*` properties)
     *  – Spring Boot already creates this bean if you have the `spring-boot-starter-data-redis-reactive`
     *    dependency on the classpath and you set the usual `spring.redis.*` properties.
     *  If you want to customise it manually you can use the following:
     */
    @Bean
    public ReactiveRedisConnectionFactory reactiveRedisConnectionFactory() {
        // Default: localhost:6379 – you can also bind it to properties
        return new LettuceConnectionFactory();
    }

    /**
     *  Template that stores **String** keys and **Long** values.
     */
    @Bean
    public ReactiveRedisTemplate<String, Long> reactiveRedisTemplate(ReactiveRedisConnectionFactory factory) {

        // Key → UTF‑8 String
        StringRedisSerializer keySerializer = new StringRedisSerializer();

        // Value → a simple Long → turn into its textual representation
        GenericToStringSerializer<Long> valueSerializer = new GenericToStringSerializer<>(Long.class);

        // Build the serialization context (key + value)
        RedisSerializationContext<String, Long> serializationContext =
                RedisSerializationContext.<String, Long>newSerializationContext()
                        .key(keySerializer)
                        .value(valueSerializer)
                        .hashKey(keySerializer)
                        .hashValue(valueSerializer)
                        .build();

        return new ReactiveRedisTemplate<>(factory, serializationContext);
    }
}
```

If you already have `spring.redis.host`, `spring.redis.port`, etc. in `application.yml`, the `LettuceConnectionFactory` bean can be omitted – Spring Boot will auto‑configure it for you.

