## 2. Java (Android) – encrypt / decrypt + write to an NFC tag

> The Java code assumes you are running inside an Android activity/service that already has the **`android.permission.NFC`** permission and the device supports **NDEF** tags.

### 2.1. Utility class for AES‑GCM

```java
package com.example.nfcencrypt;

import android.util.Base64;
import java.nio.ByteBuffer;
import java.security.SecureRandom;
import java.security.GeneralSecurityException;
import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

/**
 * Simple AES‑256‑GCM helper.
 *
 * Payload format (binary):
 *   [12‑byte IV] [cipher‑text] [16‑byte tag]
 *
 * All operations use raw bytes. If you need a String (e.g. to store in NDEF),
 * Base64‑encode the whole payload.
 */
public final class AesGcm {

    private static final int KEY_SIZE = 256;                // bits
    private static final int IV_SIZE = 12;                  // bytes (96‑bit) — GCM default
    private static final int TAG_SIZE = 16;                 // bytes (128‑bit) — authentication tag
    private static final String ALG = "AES/GCM/NoPadding";

    private AesGcm() { /* utility class */ }

    /** Convert a hex string (64 chars) → 32‑byte secret key */
    public static SecretKeySpec hexToKey(String hex) {
        if (hex.length() != 64) {
            throw new IllegalArgumentException("Key hex must be 64 chars (256‑bit)");
        }
        byte[] keyBytes = hexStringToByteArray(hex);
        return new SecretKeySpec(keyBytes, "AES");
    }

    /** Encrypt raw data. Returns IV‖cipher‖tag (binary) */
    public static byte[] encrypt(byte[] plaintext, SecretKeySpec key) throws GeneralSecurityException {
        SecureRandom rng = new SecureRandom();
        byte[] iv = new byte[IV_SIZE];
        rng.nextBytes(iv);                     // random nonce

        Cipher cipher = Cipher.getInstance(ALG);
        GCMParameterSpec spec = new GCMParameterSpec(TAG_SIZE * 8, iv);
        cipher.init(Cipher.ENCRYPT_MODE, key, spec);
        // (optional) cipher.updateAAD(...);   // add AAD if you want
        byte[] cipherText = cipher.doFinal(plaintext); // includes tag at the end

        // Build payload: IV + cipherText (cipherText already contains tag)
        ByteBuffer buffer = ByteBuffer.allocate(iv.length + cipherText.length);
        buffer.put(iv);
        buffer.put(cipherText);
        return buffer.array();
    }

    /** Decrypt payload created by {@link #encrypt}. */
    public static byte[] decrypt(byte[] payload, SecretKeySpec key) throws GeneralSecurityException {
        ByteBuffer buf = ByteBuffer.wrap(payload);
        byte[] iv = new byte[IV_SIZE];
        buf.get(iv);
        byte[] cipherAndTag = new byte[buf.remaining()];
        buf.get(cipherAndTag);                 // ciphertext||tag

        Cipher cipher = Cipher.getInstance(ALG);
        GCMParameterSpec spec = new GCMParameterSpec(TAG_SIZE * 8, iv);
        cipher.init(Cipher.DECRYPT_MODE, key, spec);
        // (optional) cipher.updateAAD(...);
        return cipher.doFinal(cipherAndTag);
    }

    /** Helper: hex string → byte[] (uppercase/lowercase ok) */
    private static byte[] hexStringToByteArray(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                    + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    /** Optional: convenience to get a Base64 string (for NDEF) */
    public static String encryptBase64(String plain, SecretKeySpec key) throws GeneralSecurityException {
        byte[] enc = encrypt(plain.getBytes(java.nio.charset.StandardCharsets.US_ASCII), key);
        return Base64.encodeToString(enc, Base64.NO_WRAP);
    }

    public static String decryptBase64(String b64, SecretKeySpec key) throws GeneralSecurityException {
        byte[] payload = Base64.decode(b64, Base64.NO_WRAP);
        byte[] plain = decrypt(payload, key);
        return new String(plain, java.nio.charset.StandardCharsets.US_ASCII);
    }
}
```

