import jwt from 'jsonwebtoken';
import { config } from '../config';

export interface IAccessPayload {
  uid: string;        // 用户唯一 ID
  role: string[];     // 角色数组
  // 你想在 token 里放的其它信息
}

export const generateAccessToken = (payload: IAccessPayload) => {
  return jwt.sign(payload, config.jwt.accessSecret, {
    expiresIn: config.jwt.accessExpires,
  });
};

export const generateRefreshToken = (payload: IAccessPayload) => {
  return jwt.sign(payload, config.jwt.refreshSecret, {
    expiresIn: config.jwt.refreshExpires,
  });
};

export const verifyAccessToken = (token: string): IAccessPayload => {
  return jwt.verify(token, config.jwt.accessSecret) as IAccessPayload;
};

export const verifyRefreshToken = (token: string): IAccessPayload => {
  return jwt.verify(token, config.jwt.refreshSecret) as IAccessPayload;
};
