import { Request, Response, NextFunction } from 'express';
import Joi from 'joi';
import { logger } from '../utils/logger';

export const loginSchema = Joi.object({
  // 支持三种登录方式之一
  username: Joi.string().optional(),
  email: Joi.string().email().optional(),
  mobile: Joi.string().pattern(/^\d{10,15}$/).optional(),

  password: Joi.string().min(6).max(30).required(),

  // 可选验证码字段
  captcha: Joi.object({
    challenge: Joi.string().required(),
    validate: Joi.string().required(),
    seccode: Joi.string().required(),
  }).optional(),

  // 其它业务字段（如 deviceId、loginType）
  deviceId: Joi.string().optional(),
  loginType: Joi.string().valid('MANUAL', 'OAUTH').default('MANUAL'),
});

export const validateLogin = (req: Request, _res: Response, next: NextFunction) => {
  const { error, value } = loginSchema.validate(req.body, { abortEarly: false, allowUnknown: true });
  if (error) {
    logger.warn('Login validation failed', { errors: error.details });
    return next({
      status: 400,
      code: 'VALIDATION_ERROR',
      message: '请求参数不合法',
      details: error.details.map(d => d.message),
    });
  }
  req.body = value; // 已经是安全的对象
  next();
};
```

