### 7️⃣ `src/middlewares/rateLimiter.ts` – 防暴力登录（基于 Redis 简易限流）

```ts
import { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';
import { config } from '../config';
import { logger } from '../utils/logger';

const redis = new Redis({
  host: config.redis.host,
  port: config.redis.port,
  password: config.redis.password || undefined,
});

const PREFIX = 'login_rate:';
const MAX_ATTEMPTS = 5;          // 5 次
const WINDOW_SECONDS = 60 * 5;  // 5 分钟

export const loginRateLimiter = async (req: Request, _res: Response, next: NextFunction) => {
  const ip = (req.headers['x-forwarded-for'] as string) || req.ip;
  const key = `${PREFIX}${ip}`;

  const attempts = await redis.incr(key);
  if (attempts === 1) {
    // 第一次请求设置过期时间
    await redis.expire(key, WINDOW_SECONDS);
  }

  if (attempts > MAX_ATTEMPTS) {
    logger.warn('Login rate limit exceeded', { ip, attempts });
    return next({
      status: 429,
      code: 'TOO_MANY_REQUESTS',
      message: `登录尝试过于频繁，请 ${WINDOW_SECONDS / 60} 分钟后再试`,
    });
  }

  // 将次数写回 req，后面业务可自行决定是否进行更细粒度锁定
  (req as any).loginAttempts = attempts;
  next();
};
```

> **思考**：如果业务要求对同一账户的暴力破解进行锁定，可在 **用户模型** 中维护 `loginAttempts` + `lockUntil`（示例代码后会提到）。

