### 9️⃣ `src/controllers/auth.controller.ts` – **登录核心业务**（最关键）

```ts
import { Request, Response, NextFunction } from 'express';
import bcrypt from 'bcryptjs';
import { UserModel, IUser } from '../models/user.model';
import { generateAccessToken, generateRefreshToken } from '../services/token.service';
import { verifyGeetest } from '../services/captcha.service';
import { logger } from '../utils/logger';

// ---------- 辅助函数 ----------
const MAX_PASSWORD_ATTEMPTS = 10;
const LOCK_TIME_MS = 30 * 60 * 1000; // 30 分钟

/** 记录登录日志（示例） */
const logLogin = async (uid: string, ip: string, success: boolean, reason?: string) => {
  logger.info('LoginAttempt', { uid, ip, success, reason, time: new Date().toISOString() });
  // 业务里可以写入 db、ES、Kafka 等
};

/** 锁定/解锁用户 */
const checkLock = async (user: IUser) => {
  if (user.lockUntil && user.lockUntil > new Date()) {
    return true; // 仍然被锁
  }
  // 已过期则清除锁定
  if (user.lockUntil && user.lockUntil <= new Date()) {
    user.lockUntil = undefined;
    user.loginAttempts = 0;
    await user.save();
  }
  return false;
};

/** 增加登录失败次数 */
const increaseFailed = async (user: IUser) => {
  user.loginAttempts += 1;
  if (user.loginAttempts >= MAX_PASSWORD_ATTEMPTS) {
    user.lockUntil = new Date(Date.now() + LOCK_TIME_MS);
    logger.warn('User locked due to repeated failures', { uid: user._id });
  }
  await user.save();
};

/** 成功登录后，重置计数 */
const resetLoginAttempts = async (user: IUser) => {
  user.loginAttempts = 0;
  user.lockUntil = undefined;
  await user.save();
};

// ---------- 登录入口 ----------
export const login = async (req: Request, res: Response, next: NextFunction) => {
  const { username, email, mobile, password, captcha, deviceId, loginType } = req.body;
  const ip = (req.headers['x-forwarded-for'] as string) || req.ip;

  // 1️⃣ 先找出用户（任意一种标识均可）
  const criteria: any = {};
  if (username) criteria.username = username;
  if (email) criteria.email = email;
  if (mobile) criteria.mobile = mobile;

  const user = await UserModel.findOne(criteria);
  if (!user) {
    await logLogin('UNKNOWN', ip, false, 'User not found');
    return next({ status: 401, code: 'AUTH_FAILED', message: '用户名或密码错误' });
  }

  // 2️⃣ 检查账户状态 & 是否被锁
  if (user.status !== 'ACTIVE') {
    await logLogin(user._id.toString(), ip, false, `Account ${user.status}`);
    return next({ status: 403, code: 'ACCOUNT_DISABLED', message: '账户已被禁用' });
  }

  if (await checkLock(user)) {
    await logLogin(user._id.toString(), ip, false, 'Account locked');
    return next({ status: 423, code: 'ACCOUNT_LOCKED', message: '账户已被锁定，请稍后再试' });
  }

  // 3️⃣ 如前端要求，可强制验证码校验（仅在手动登录或安全等级高时）
  if (loginType === 'MANUAL' && captcha) {
    const ok = await verifyGeetest(captcha.challenge, captcha.validate, captcha.seccode, ip);
    if (!ok) {
      await logLogin(user._id.toString(), ip, false, 'Captcha validation failed');
      return next({ status: 400, code: 'CAPTCHA_FAILED', message: '验证码校验失败' });
    }
  }

  // 4️⃣ 密码比对
  const pwdMatch = await bcrypt.compare(password, user.password);
  if (!pwdMatch) {
    await increaseFailed(user);
    await logLogin(user._id.toString(), ip, false, 'Password mismatch');
    return next({ status: 401, code: 'AUTH_FAILED', message: '用户名或密码错误' });
  }

  // 5️⃣ 登录成功 → 清空计数、生成 token
  await resetLoginAttempts(user);
  await logLogin(user._id.toString(), ip, true);

  const payload = { uid: user._id.toString(), role: user.role };
  const accessToken = generateAccessToken(payload);
  const refreshToken = generateRefreshToken(payload);

  // 6️⃣ 可将 refresh token 写入 Redis（或 DB）做单点登录、强制下线等
  // 示例：redis.set(`refresh:${user._id}`, refreshToken, 'EX', 7 * 24 * 60 * 60)

  // 7️⃣ 响应
  res.json({
    success: true,
    data: {
      accessToken,
      refreshToken,
      expiresIn: config.jwt.accessExpires,
      user: {
        id: user._id,
        username: user.username,
        email: user.email,
        mobile: user.mobile,
        role: user.role,
        // 业务需要的其它信息
        deviceId: deviceId || null,
      },
    },
  });
};
```

**要点说明**：

| 步骤 | 目的 | 细节 |
|------|------|------|
| **1️⃣** | 查找用户 | 支持 **username / email / mobile** 任意一种。 |
| **2️⃣** | 账户状态 & 锁定 | `status !== 'ACTIVE'` → 禁用；`lockUntil` → 暂时锁定防爆破。 |
| **3️⃣** | 可选验证码 | 仅在手动登录或高风险场景启用。 |
| **4️⃣** | 密码比对 | 使用 **bcrypt**（安全且性能合适）。 |
| **5️⃣** | 成功后清空计数 | 防止误锁。 |
| **6️⃣** | 生成 Token | **Access**（短期）+ **Refresh**（长期），可自行决定是否返回刷新 token。 |
| **7️⃣** | 响应结构 | 统一返回 `success:true`，前端只需要关心 `data.accessToken` 即可。 |

