import java.util.*;
import java.io.*;

public class AdminModule {

    private ArrayList<Player> players;
    private final String PLAYERS_FILENAME = "players.bin";

    public AdminModule() {
        players = new ArrayList<>();
        loadPlayers();
    }

    /* --------------------------------------------------------------
       ADMIN LOGIN
       -------------------------------------------------------------- */
    public void login() {
        System.out.println("\n=== ADMIN LOGIN ===");
        while (true) {
            String pwd = Keyboard.readString("Enter admin password: ");
            if (AdminFile.checkPassword(pwd)) {
                System.out.println("Login successful.\n");
                return;
            }
            System.out.println("Incorrect password! Try again.\n");
        }
    }

    /* --------------------------------------------------------------
       LOAD / SAVE PLAYERS (binary serialization)
       -------------------------------------------------------------- */
    private void loadPlayers() {
        File f = new File(PLAYERS_FILENAME);
        if (!f.exists()) {
            System.out.println("No player file found – starting with an empty list.");
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            while (true) {
                try {
                    Player p = (Player) ois.readObject();
                    players.add(p);
                } catch (EOFException eof) {
                    break; // end of file reached
                }
            }
        } catch (Exception e) {
            System.out.println("Error loading players: " + e.getMessage());
        }
        System.out.println("Players information loaded.\n");
    }

    private void savePlayers() {
        try (ObjectOutputStream oos = new ObjectOutputStream(
                new FileOutputStream(PLAYERS_FILENAME))) {
            for (Player p : players) {
                oos.writeObject(p);
            }
        } catch (IOException e) {
            System.out.println("Failed to save players: " + e.getMessage());
        }
    }

    /* --------------------------------------------------------------
       ADMIN OPERATIONS
       -------------------------------------------------------------- */
    private void displayPlayers() {
        System.out.println("\n--- PLAYER LIST ---");
        if (players.isEmpty()) {
            System.out.println("[none]");
        } else {
            for (Player p : players) {
                p.display();          // prints loginName,hashPassword
                System.out.println("Chips: " + p.getChips());
                System.out.println();
            }
        }
    }

    private void createNewPlayer() {
        String name = Keyboard.readString("\nEnter new player name: ");
        if (getPlayerByName(name) != null) {
            System.out.println("Error: a player with that name already exists");
            return;
        }
        String pwd = Keyboard.readString("Enter password for the player: ");
        String hash = Utility.getHash(pwd);
        int chips = Keyboard.readInt("Initial chips: ");
        Player p = new Player(name, hash, chips);
        players.add(p);
        savePlayers();
        System.out.println("Player created.\n");
    }

    private void deletePlayer() {
        String name = Keyboard.readString("\nEnter player name to delete: ");
        Player p = getPlayerByName(name);
        if (p == null) {
            System.out.println("Error: no player with that name exists");
            return;
        }
        players.remove(p);
        savePlayers();
        System.out.println("Player deleted.\n");
    }

    private void updatePlayersChip() {
        String name = Keyboard.readString("\nEnter player name to issue chips: ");
        Player p = getPlayerByName(name);
        if (p == null) {
            System.out.println("Error: no player with that name exists");
            return;
        }
        int chips = Keyboard.readInt("Number of chips to add: ");
        p.addChips(chips);
        savePlayers();
        System.out.println("Chips issued.\n");
    }

    private void resetPlayerPassword() {
        String name = Keyboard.readString("\nEnter player name to reset password: ");
        Player p = getPlayerByName(name);
        if (p == null) {
            System.out.println("Error: no player with that name exists");
            return;
        }
        String newPwd = Keyboard.readString("Enter new password: ");
        p.setHashPassword(Utility.getHash(newPwd));
        savePlayers();
        System.out.println("Password reset.\n");
    }

    private void changeAdminPassword() {
        System.out.println("\n--- CHANGE ADMIN PASSWORD ---");
        String current = Keyboard.readString("Enter current admin password: ");
        if (!AdminFile.checkPassword(current)) {
            System.out.println("Error: incorrect password");
            return;
        }
        String newPwd = Keyboard.readString("Enter new admin password: ");
        String newHash = Utility.getHash(newPwd);
        AdminFile.writeAdminHash(newHash);
        System.out.println("Admin password changed.\n");
    }

    /* --------------------------------------------------------------
       HELPER
       -------------------------------------------------------------- */
    private Player getPlayerByName(String name) {
        for (Player p : players) {
            if (p.getLoginName().equals(name)) {
                return p;
            }
        }
        return null;
    }

    public void logout() {
        System.out.println("Logging out... Goodbye.\n");
    }

    /* --------------------------------------------------------------
       MAIN LOOP (menu driven)
       -------------------------------------------------------------- */
    public void run() {
        login();
        boolean exit = false;
        while (!exit) {
            int choice = Keyboard.getUserOption("ADMIN MENU", new String[]{
                    "Create a player",
                    "Delete a player",
                    "View all players",
                    "Issue more chips to a player",
                    "Reset player's password",
                    "Change administrator's password",
                    "Logout"
            });

            switch (choice) {
                case 1 -> createNewPlayer();
                case 2 -> deletePlayer();
                case 3 -> displayPlayers();
                case 4 -> updatePlayersChip();
                case 5 -> resetPlayerPassword();
                case 6 -> changeAdminPassword();
                case 7 -> {
                    logout();
                    exit = true;
                }
                default -> System.out.println("Invalid choice");
            }
        }
    }

    public static void main(String[] args) {
        new AdminModule().run();
    }
}
```

### What changed?

