### 2.1 `Message` – 协议工具类

```java
package com.example.kefu;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

/**
 * 简化的协议帧工具
 */
public final class Message {

    // 类型标识
    public static final byte TEXT      = 0x01;
    public static final byte IMAGE     = 0x02;
    public static final byte FILE      = 0x03;
    public static final byte REQUEST   = 0x10;
    public static final byte ACCEPT    = 0x11;
    public static final byte REJECT    = 0x12;
    public static final byte BUSY      = 0x13;

    private Message() {}

    /* ---------- 发送端 ---------- */
    /** 发送文字 */
    public static void sendText(DataOutputStream out, String txt) throws IOException {
        byte[] data = txt.getBytes(StandardCharsets.UTF_8);
        writeFrame(out, TEXT, data);
    }

    /** 发送文件/图片（type = IMAGE or FILE） */
    public static void sendFile(DataOutputStream out, byte type,
                                String fileName, byte[] fileContent) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        // 文件名长度 + 文件名
        byte[] nameBytes = fileName.getBytes(StandardCharsets.UTF_8);
        buf.write(ByteBuffer.allocate(4).putInt(nameBytes.length).array());
        buf.write(nameBytes);
        // 文件内容
        buf.write(fileContent);
        writeFrame(out, type, buf.toByteArray());
    }

    /** 发送请求/响应（只含类型） */
    public static void sendSimple(DataOutputStream out, byte type) throws IOException {
        writeFrame(out, type, new byte[0]);
    }

    /** 内部统一帧写入 */
    private static void writeFrame(DataOutputStream out, byte type, byte[] payload) throws IOException {
        int len = 1 + payload.length;                // type(1) + payload
        out.writeInt(len);                           // 4-byte 长度字段
        out.writeByte(type);                         // 1-byte 类型
        if (payload.length > 0) out.write(payload); // payload
        out.flush();
    }

    /* ---------- 接收端 ---------- */
    /** 从流中读取完整帧（阻塞） */
    public static Frame readFrame(DataInputStream in) throws IOException {
        int len = in.readInt();               // 读取长度字段
        if (len <= 0) throw new IOException("Invalid frame length: " + len);
        byte type = in.readByte();            // 读取类型
        byte[] payload = new byte[len - 1];
        if (payload.length > 0) {
            in.readFully(payload);
        }
        return new Frame(type, payload);
    }

    /** 读取文件帧内部的文件名和内容 */
    public static FilePayload decodeFilePayload(byte[] payload) throws IOException {
        DataInputStream din = new DataInputStream(new ByteArrayInputStream(payload));
        int nameLen = din.readInt();
        byte[] nameBytes = new byte[nameLen];
        din.readFully(nameBytes);
        String filename = new String(nameBytes, StandardCharsets.UTF_8);
        byte[] fileData = din.readAllBytes();
        return new FilePayload(filename, fileData);
    }

    /** 简单封装的帧对象 */
    public static final class Frame {
        public final byte type;
        public final byte[] payload;
        public Frame(byte type, byte[] payload) {
            this.type = type;
            this.payload = payload;
        }
    }

    /** 用于文件帧的返回值 */
    public static final class FilePayload {
        public final String fileName;
        public final byte[] data;
        public FilePayload(String fileName, byte[] data) {
            this.fileName = fileName;
            this.data = data;
        }
    }
}
```

