package com.example.kefu;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class HistoryManager {
    private static final Path ROOT = Paths.get("history");

    static {
        try {
            Files.createDirectories(ROOT);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 追加文字记录到用户日志 */
    public static void appendText(String userId, String who, String txt) {
        String line = String.format("[%s] %s: %s%n", java.time.LocalDateTime.now(), who, txt);
        Path file = ROOT.resolve(userId + ".log");
        try {
            Files.writeString(file, line, StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 读取完整文字日志（返回整段文字） */
    public static String readLog(String userId) {
        Path file = ROOT.resolve(userId + ".log");
        if (!Files.exists(file)) return "";
        try {
            return Files.readString(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            e.printStackTrace();
            return "";
        }
    }

    /** 保存收到的二进制文件（图片/其他） */
    public static Path saveFile(String userId, String fileName, byte[] data) throws IOException {
        Path dir = ROOT.resolve(userId + "_files");
        Files.createDirectories(dir);
        Path out = dir.resolve(fileName);
        Files.write(out, data);
        return out;
    }
}
