 */
public class ClientHandler implements Runnable {

    private final Socket socket;
    private final ChatServer server; // 用于回调 UI
    private final String userId;     // 简单使用远端 IP+Port 作为唯一标识

    private DataInputStream in;
    private DataOutputStream out;
    /** 标记客服是否已接受该会话 */
    private final AtomicBoolean accepted = new AtomicBoolean(false);

    public ClientHandler(Socket socket, ChatServer server) {
        this.socket = socket;
        this.server = server;
        this.userId = socket.getRemoteSocketAddress().toString();
    }

    public String getUserId() { return userId; }

    /** 向客户端发送文字 */
    public void sendText(String txt) throws IOException {
        Message.sendText(out, txt);
        HistoryManager.appendText(userId, "客服", txt);
    }

    /** 向客户端发送文件（图片或普通文件） */
    public void sendFile(byte type, File file) throws IOException {
        byte[] data = Files.readAllBytes(file.toPath());
        Message.sendFile(out, type, file.getName(), data);
        // 记录日志：文件名 + 类型
        HistoryManager.appendText(userId, "客服", "[文件] " + file.getName());
    }

    /** 给前端 UI 回调用户发来的文字 */
    private void forwardText(String txt) {
        HistoryManager.appendText(userId, "用户", txt);
        server.handleIncomingText(this, txt);
    }

    /** 给前端 UI 回调用户发来的文件 */
    private void forwardFile(byte type, Message.FilePayload fp) {
        try {
            Path saved = HistoryManager.saveFile(userId, fp.fileName, fp.data);
            HistoryManager.appendText(userId, "用户",
                    String.format("[文件] %s (%s)", fp.fileName, type == Message.IMAGE ? "图片" : "文件"));
            server.handleIncomingFile(this, type, saved.toFile());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** Server 主动通知“接受”会话 */
    public void acceptSession() {
        accepted.set(true);
        try {
            Message.sendSimple(out, Message.ACCEPT);
        } catch (IOException e) {
            e.printStackTrace();
            close();
        }
    }

    /** Server 主动通知“拒绝”会话 */
    public void rejectSession() {
        try {
            Message.sendSimple(out, Message.REJECT);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            close();
        }
    }

    @Override
    public void run() {
        try (Socket s = socket;
             DataInputStream din = new DataInputStream(s.getInputStream());
             DataOutputStream dout = new DataOutputStream(s.getOutputStream())) {

            this.in = din;
            this.out = dout;

            // 第一步：用户发送 REQUEST，请求接入客服
            Message.Frame first = Message.readFrame(in);
            if (first.type != Message.REQUEST) {
                System.err.println("Invalid first packet from " + userId);
                return;
            }

            // 把请求转交给 Server 主线程（UI）处理，弹出“是否接收”对话框
            server.notifyNewCustomer(this);

            // 等待客服决定（接受/拒绝）——另一个线程会调用 acceptSession()/rejectSession()
            while (!accepted.get() && !socket.isClosed()) {
                Thread.sleep(100); // 简单轮询，实际可使用 CountDownLatch 等更优
            }
            if (!accepted.get()) {
                // 被拒绝或超时，直接返回
                return;
            }

            // 会话正式开始，循环读取消息
            while (true) {
                Message.Frame frame = Message.readFrame(in);
                switch (frame.type) {
                    case Message.TEXT:
                        String txt = new String(frame.payload, StandardCharsets.UTF_8);
                        forwardText(txt);
                        break;
                    case Message.IMAGE:
                    case Message.FILE:
                        Message.FilePayload fp = Message.decodeFilePayload(frame.payload);
                        forwardFile(frame.type, fp);
                        break;
                    default:
                        System.err.println("Unknown frame type " + frame.type);
                }
            }

        } catch (EOFException eof) {
            System.out.println("客户 " + userId + " 已下线");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            close();
        }
    }

    /** 关闭连接并从 Server 中移除 */
    private void close() {
        server.removeHandler(this);
        try {
            socket.close();
        } catch (IOException ignore) {}
    }
}
```

### 2.4 `ChatServer` – 主入口 + UI

> **UI 采用 Swing，左侧列表显示当前等待/已接入的用户，右侧为聊天窗口**。每个会话对应一个 `ChatPanel`（内部类），实现文字/文件发送、历史加载、滚动显示。

```java
package com.example.kefu;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.io.File;
import java.net.ServerSocket;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;

public class ChatServer extends JFrame {

    // ==================== 网络 ====================
    private static final int PORT = 8888;
    private ServerSocket serverSocket;
    private final ExecutorService pool = Executors.newFixedThreadPool(20);

    // 维护活跃的 ClientHandler（key = userId）
    private final Map<String, ClientHandler> handlers = new ConcurrentHashMap<>();

    // ==================== UI ====================
    private final DefaultListModel<ClientHandler> waitingModel = new DefaultListModel<>();
    private final JList<ClientHandler> waitingList = new JList<>(waitingModel);
    private final JTabbedPane chatTabs = new JTabbedPane();

    public ChatServer() {
        setTitle("客服端（Server） - 基于 Socket 的即时聊天");
        setSize(900, 600);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        startServer();
    }

    private void initUI() {
        // 左侧：等待列表
        JPanel leftPanel = new JPanel(new BorderLayout(5,5));
        leftPanel.setBorder(new EmptyBorder(5,5,5,5));
        leftPanel.add(new JLabel("等待接入的用户:"), BorderLayout.NORTH);
        waitingList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        leftPanel.add(new JScrollPane(waitingList), BorderLayout.CENTER);
        JButton btnAccept = new JButton("接收");
        JButton btnReject = new JButton("拒绝");
        JPanel btnPanel = new JPanel(new GridLayout(1,2,5,5));
        btnPanel.add(btnAccept);
        btnPanel.add(btnReject);
        leftPanel.add(btnPanel, BorderLayout.SOUTH);
        // 右侧：聊天窗口（Tab）
        JPanel rightPanel = new JPanel(new BorderLayout());
        rightPanel.add(chatTabs, BorderLayout.CENTER);

        // 主框架
        JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, leftPanel, rightPanel);
        split.setDividerLocation(250);
        add(split);

        // 按钮事件
        btnAccept.addActionListener(e -> {
            ClientHandler ch = waitingList.getSelectedValue();
            if (ch != null) {
                ch.acceptSession();
                // 在 Tab 中打开会话
                ChatPanel panel = new ChatPanel(ch);
                chatTabs.addTab(ch.getUserId(), panel);
                waitingModel.removeElement(ch);
            }
        });

        btnReject.addActionListener(e -> {
            ClientHandler ch = waitingList.getSelectedValue();
            if (ch != null) {
                ch.rejectSession();
                waitingModel.removeElement(ch);
            }
        });
    }

    // ==================== 网络线程 ====================
    private void startServer() {
        new Thread(() -> {
            try (ServerSocket ss = new ServerSocket(PORT)) {
                serverSocket = ss;
                System.out.println("客服端启动，监听端口 " + PORT);
                while (!ss.isClosed()) {
                    Socket client = ss.accept();
                    ClientHandler handler = new ClientHandler(client, this);
                    handlers.put(handler.getUserId(), handler);
                    pool.submit(handler);  // 让 handler 先进入 run()，它会先发送 REQUEST
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "Server-Accept-Thread").start();
    }

    /** 当 ClientHandler 接收到用户的第一次 REQUEST 时调用 */
    public void notifyNewCustomer(ClientHandler handler) {
        SwingUtilities.invokeLater(() -> {
            waitingModel.addElement(handler);
            // 可在此弹出系统托盘提示或声音提示
        });
    }

    /** 客服收到用户文字消息后调用（在 UI 主线程） */
    public void handleIncomingText(ClientHandler handler, String txt) {
        SwingUtilities.invokeLater(() -> {
            // 找到相对应的 Tab，如果没有则自动创建
            ChatPanel panel = getChatPanel(handler);
            if (panel != null) panel.appendFromUser(txt);
        });
    }

    /** 客服收到用户文件（图片/普通文件）后调用 */
    public void handleIncomingFile(ClientHandler handler, byte type, File savedFile) {
        SwingUtilities.invokeLater(() -> {
            ChatPanel panel = getChatPanel(handler);
            if (panel != null) panel.appendFileFromUser(type, savedFile);
        });
    }

    /** 根据 handler 查找/创建对应的聊天 Tab */
    private ChatPanel getChatPanel(ClientHandler handler) {
        for (int i = 0; i < chatTabs.getTabCount(); i++) {
            Component c = chatTabs.getComponentAt(i);
            if (c instanceof ChatPanel && ((ChatPanel) c).boundHandler == handler) {
                return (ChatPanel) c;
            }
        }
        // 未打开的会话自动打开（如果客服已经接受了会话则应该已在 Tab 中，这里是防御性代码）
        ChatPanel panel = new ChatPanel(handler);
        chatTabs.addTab(handler.getUserId(), panel);
        return panel;
    }

    /** 从 handlers map 中删除已经关闭的连接 */
    public void removeHandler(ClientHandler handler) {
        handlers.remove(handler.getUserId());
        SwingUtilities.invokeLater(() -> waitingModel.removeElement(handler));
    }

    // ==================== ChatPanel（内部类）====================
    private class ChatPanel extends JPanel {
        private final ClientHandler boundHandler;
        private final JTextArea chatArea = new JTextArea();
        private final JTextField inputField = new JTextField();
        private final JButton btnSend = new JButton("发送");
        private final JButton btnFile = new JButton("发送文件");

        ChatPanel(ClientHandler handler) {
            this.boundHandler = handler;
            setLayout(new BorderLayout(5,5));
            // 上部聊天记录（只读）
            chatArea.setEditable(false);
            chatArea.setLineWrap(true);
            chatArea.setWrapStyleWord(true);
            add(new JScrollPane(chatArea), BorderLayout.CENTER);
            // 底部输入区
            JPanel inputPanel = new JPanel(new BorderLayout(5,5));
            inputPanel.add(inputField, BorderLayout.CENTER);
            JPanel btns = new JPanel(new GridLayout(1,2,5,5));
            btns.add(btnSend);
            btns.add(btnFile);
            inputPanel.add(btns, BorderLayout.EAST);
            add(inputPanel, BorderLayout.SOUTH);

            // 加载历史记录
            chatArea.setText(HistoryManager.readLog(handler.getUserId()));

            // 发送文字
            btnSend.addActionListener(e -> sendText());
            inputField.addActionListener(e -> sendText());

            // 发送文件
            btnFile.addActionListener(e -> chooseAndSendFile());
        }

        private void sendText() {
            String txt = inputField.getText().trim();
            if (txt.isEmpty()) return;
            try {
                boundHandler.sendText(txt);
                appendFromServer(txt);
                inputField.setText("");
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(this, "发送失败：" + ex.getMessage(),
                        "错误", JOptionPane.ERROR_MESSAGE);
            }
        }

        private void chooseAndSendFile() {
            JFileChooser chooser = new JFileChooser();
            int opt = chooser.showOpenDialog(this);
            if (opt != JFileChooser.APPROVE_OPTION) return;
            File file = chooser.getSelectedFile();
            try {
                byte type = isImage(file) ? Message.IMAGE : Message.FILE;
                boundHandler.sendFile(type, file);
                appendFileFromServer(type, file);
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(this, "发送文件失败：" + ex.getMessage(),
                        "错误", JOptionPane.ERROR_MESSAGE);
            }
        }

        // ----------------- UI 更新 -----------------
        private void appendFromUser(String txt) {
            chatArea.append("\n[用户] " + txt);
        }
        private void appendFromServer(String txt) {
            chatArea.append("\n[客服] " + txt);
        }
        private void appendFileFromUser(byte type, File f) {
            chatArea.append("\n[用户] 发送了 " + (type == Message.IMAGE ? "图片" : "文件") + "：" + f.getName());
            if (type == Message.IMAGE) {
                // 在聊天区直接显示缩略图（可选）
                try {
                    Image img = Toolkit.getDefaultToolkit().createImage(f.getAbsolutePath());
                    ImageIcon icon = new ImageIcon(img.getScaledInstance(150, -1, Image.SCALE_SMOOTH));
                    chatArea.insert(icon.getDescription(), chatArea.getDocument().getLength());
                } catch (Exception ignored){}
            }
        }
        private void appendFileFromServer(byte type, File f) {
            chatArea.append("\n[客服] 发送了 " + (type == Message.IMAGE ? "图片" : "文件") + "：" + f.getName());
        }

        private boolean isImage(File f) {
            String name = f.getName().toLowerCase();
            return name.endsWith(".png") || name.endsWith(".jpg") ||
                    name.endsWith(".jpeg") || name.endsWith(".gif") || name.endsWith(".bmp");
        }
    }

    // ==================== 程序入口 =====================
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ChatServer().setVisible(true));
    }
}
```

**关键点说明**

1. **`ClientHandler` 负责协议细节**，在收到 `REQUEST` 后把自身交给 `ChatServer.notifyNewCustomer`，后者把它放进左侧 `JList`，客服可以点击 **“接收”** 或 **“拒绝”**。  
2. 当客服点击 “接收” 时，`ChatServer` 调用 `handler.acceptSession()`，该方法向客户端发送 `ACCEPT` 帧并把 `accepted` 标记置位，从而让 `ClientHandler` 继续进入消息循环。  
3. **倒计时（客服忙）**：客户端在发送 `REQUEST` 后启动一个 `ScheduledExecutorService`（15 秒后如果未收到 `ACCEPT` 则弹出忙提示）。代码在客户端章节中实现。  
4. **文件保存**：所有收到的二进制文件统一保存到 `history/<userId>_files/` 目录，文件名保持原样。  
5. **聊天记录**：每条文字消息实时追加到 `history/<userId>.log`，打开会话时一次性读取并显示。  

