## 2️⃣ 数据模型 & 队列

我们使用 **`BlockingQueue<BufferedImage>`** 充当生产者‑消费者的桥梁。  
生产者可以是 **REST 接口**（接收上传的图片）或 **本地定时抓图**。

```java
package com.example.h264demo.queue;

import java.awt.image.BufferedImage;
import java.util.concurrent.BlockingDeque;
import java.util.concurrent.LinkedBlockingDeque;
import org.springframework.stereotype.Component;

/**
 * 单例的帧队列，生产者往这里放 BufferedImage，编码器（消费者）从这里拿。
 */
@Component
public class FrameQueue {

    /** 队列深度 100，防止 OOM，可根据业务调节 */
    private final BlockingDeque<BufferedImage> queue = new LinkedBlockingDeque<>(100);

    /** 生产者入口 */
    public void offer(BufferedImage img) {
        // 如果队列已满，丢弃最旧的帧保证实时性
        if (!queue.offer(img)) {
            queue.pollFirst(); // 丢掉最旧
            queue.offer(img);
        }
    }

    /** 消费者入口（阻塞） */
    public BufferedImage take() throws InterruptedException {
        return queue.take();
    }

    /** 用于监控的大小 */
    public int size() {
        return queue.size();
    }
}
```

