## 3️⃣ 图片接收（REST 端点）

下面的 `ImageController` 接收 **Base64** 编码的 JPEG（也可以直接 `MultipartFile`），把解码后的 `BufferedImage` 放入 `FrameQueue`。

```java
package com.example.h264demo.controller;

import com.example.h264demo.queue.FrameQueue;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Base64;
import javax.imageio.ImageIO;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/frame")
@RequiredArgsConstructor
public class ImageController {

    private final FrameQueue frameQueue;

    /**
     * POST /api/frame
     * Body: {"data":"data:image/jpeg;base64,/9j/4AAQSkZJRgABAQ..."}
     */
    @PostMapping
    public ResponseEntity<String> receive(@RequestBody FrameDto dto) {
        try {
            // 去掉可能的 "data:image/jpeg;base64," 前缀
            String base64 = dto.getData().replaceAll("^data:image/[^;]+;base64,", "");
            byte[] bytes = Base64.getDecoder().decode(base64);
            BufferedImage img = ImageIO.read(new ByteArrayInputStream(bytes));

            if (img == null) {
                return ResponseEntity.badRequest().body("Invalid image data");
            }

            frameQueue.offer(img);
            return ResponseEntity.ok("Accepted");
        } catch (Exception e) {
            return ResponseEntity.badRequest().body("Error: " + e.getMessage());
        }
    }

    public static class FrameDto {
        private String data;
        public String getData() { return data; }
        public void setData(String data) { this.data = data; }
    }
}
```

> **小技巧**：如果你是前端直接抓取摄像头画面（`canvas.toDataURL('image/jpeg')`），直接把这段 Base64 发到这个接口即可。

