## 5️⃣ 基于 NIO 的 TCP Socket 服务

这里使用 **Java NIO（ServerSocketChannel）** 实现一个 **单连接多帧** 的推送服务。  

> **注意**：如果要支持 **多客户端**，推荐改用 **Netty**（示例略）或在 `accept()` 循环里为每个 `SocketChannel` 启动一条编码线程。

```java
package com.example.h264demo.socket;

import com.example.h264demo.encode.H264Encoder;
import com.example.h264demo.encode.H264Encoder.FrameProvider;
import com.example.h264demo.encode.H264Encoder.OutputHandler;
import com.example.h264demo.queue.FrameQueue;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
public class H264TcpServer {

    private final FrameQueue frameQueue;
    private final H264Encoder encoder;

    /** 服务器端口，可在 application.yml 中配置 */
    private static final int PORT = 9999;

    public void start() {
        new Thread(this::runServer, "H264-TCP-Server").start();
    }

    private void runServer() {
        try (ServerSocketChannel server = ServerSocketChannel.open()) {
            server.bind(new InetSocketAddress(PORT));
            server.configureBlocking(false);
            Selector selector = Selector.open();
            server.register(selector, SelectionKey.OP_ACCEPT);
            System.out.println("H264 TCP server listening on port " + PORT);

            while (true) {
                selector.select(); // 阻塞等待事件
                Iterator<SelectionKey> it = selector.selectedKeys().iterator();
                while (it.hasNext()) {
                    SelectionKey key = it.next();
                    it.remove();

                    if (key.isAcceptable()) {
                        SocketChannel client = server.accept();
                        client.configureBlocking(false);
                        client.register(selector, SelectionKey.OP_WRITE);
                        System.out.println("Client connected: " + client.getRemoteAddress());

                        // 为每个新客户端启动独立的编码任务
                        startEncodingTask(client);
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 为单个客户端启动 H.264 编码并把 NAL 写入该 SocketChannel */
    private void startEncodingTask(SocketChannel client) {
        // FrameProvider 从共享队列读取帧
        FrameProvider provider = () -> frameQueue.take();

        // OutputHandler 把 NAL 写到 SocketChannel（采用非阻塞方式）
        OutputHandler out = nal -> {
            ByteBuffer buf = ByteBuffer.wrap(nal);
            while (buf.hasRemaining()) {
                client.write(buf); // 这里阻塞写（因为是单线程），实际生产环境请使用 selector + OP_WRITE
            }
        };

        encoder.startEncoding(provider, out);
    }
}
```

