     * Устанавливает размер скидки. Значение будет «откликнуто» к диапазону 0‑100.
     */
    public void setDiscount(int discount) {
        this.discount = Math.max(0, Math.min(100, discount));
    }

    /**
     * Возвращает цену с учётом текущей скидки.
     * <p>
     * Формула: {@code price * (100 - discount) / 100}.
     * Результат округляется в сторону вниз (целочисленное деление).
     * </p>
     */
    public int getDiscountedPrice() {
        if (discount == 0) {
            return price;
        }
        return price * (100 - discount) / 100;
    }

    /* ---------- Прочие методы ---------- */

    /**
     * Формирует уникальный ID с учётом модификации.
     */
    public String getId() {
        return StringUtils.concatStrings(this.id, "_m", String.valueOf(this.modificationIndex));
    }

    /**
     * Глубокое копирование предмета. Все поля (включая скидку) копируются.
     */
    @Override
    public Item clone() {
        return new Item(this.id,
                this.description,
                this.isInventory,
                this.index,
                this.propetys,
                this.itemType,
                this.modificationIndex,
                this.name,
                this.nextProperty,
                this.nextPrice,
                this.nextRankId,
                this.price,
                this.rankId,
                this.modifications,
                this.specialItem,
                this.count,
                this.addable,
                this.multicounted,
                this.discount);
    }

    /**
     * Дамп объекта – удобный вывод в консоль/лог.
     */
    @Override
    public String dump() {
        return StringUtils.concatStrings(
                "-------DUMP GARAGE ITEM------\n",
                "\tid: ", this.id, "\n",
                "\tinventoryItem: ", String.valueOf(this.isInventory), "\n",
                "\tindex: ", String.valueOf(this.index), "\n",
                "\tname: ", this.name.localizatedString(Localization.RU), "\n",
                "\tprice (base): ", String.valueOf(this.price), "\n",
                "\tprice (with discount): ", String.valueOf(getDiscountedPrice()), "\n",
                "\tdiscount: ", String.valueOf(this.discount), "%\n",
                "\trandId: ", String.valueOf(this.rankId), "\n",
                "\tspecialItem: ", String.valueOf(this.specialItem), "\n",
                "\tmulticounted: ", String.valueOf(this.multicounted), "\n",
                "-------------------------------\n"
        );
    }

    /* ---------- equals / hashCode (опционально) ---------- */

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Item)) return false;
        Item item = (Item) o;
        return Objects.equals(id, item.id) &&
                modificationIndex == item.modificationIndex &&
                discount == item.discount;
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, modificationIndex, discount);
    }
}
