        System.out.println("=== 客服端启动，监听端口 " + PORT + " ===");
        try (ServerSocket ss = new ServerSocket(PORT)) {
            while (true) {
                Socket client = ss.accept(); // 阻塞等待用户连接
                System.out.println("[新连接] " + client.getRemoteSocketAddress());
