### 5️⃣2 `ClientHandler.java`

```java
package com.ecom.cs.server;

import com.ecom.cs.common.*;

import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class ClientHandler implements Runnable {
    private final Socket socket;
    private final DataInputStream in;
    private final DataOutputStream out;
    private String userId;               // 简单起见，用 IP + Port 代替
    private final ChatHistory history;   // 本地聊天记录

    public ClientHandler(Socket socket) throws IOException {
        this.socket = socket;
        this.in  = new DataInputStream(socket.getInputStream());
        this.out = new DataOutputStream(socket.getOutputStream());
        this.userId = socket.getRemoteSocketAddress().toString().replace("/", "");
        this.history = new ChatHistory(userId);
    }

    @Override
    public void run() {
        try {
            // 1. 读取用户的 SERVICE_REQUEST，模拟“排队”
            Message request = Message.readFrom(in);
            if (request == null || request.getType() != MessageType.SERVICE_REQUEST) {
                close();
                return;
            }
            System.out.println("[用户请求] " + userId);
            // 2. 弹出客服选择框（这里用控制台模拟）
            boolean accepted = ServiceRequestListener.askAccept(userId);
            // 3. 返回响应
            Message resp = new Message(MessageType.SERVICE_RESPONSE,
                    new byte[]{ (byte) (accepted ? 1 : 0) });
            resp.writeTo(out);
            if (!accepted) {
                System.out.println("[已拒绝] " + userId);
                close();
                return;
            }
            System.out.println("[已接入] " + userId);
            // 4. 开始消息循环
            while (true) {
                Message msg = Message.readFrom(in);
                if (msg == null) break; // 对端关闭
                handleMessage(msg);
            }
        } catch (IOException e) {
            System.err.println("[异常] " + e.getMessage());
        } finally {
            close();
        }
    }

    /** 处理来自用户的各种消息 */
    private void handleMessage(Message msg) throws IOException {
        switch (msg.getType()) {
            case TEXT -> {
                String txt = new String(msg.getPayload(), StandardCharsets.UTF_8);
                System.out.println("[用户 " + userId + "] 文本: " + txt);
                history.append("USER", txt);
                // 回显（业务上可以转发给其他客服等）
                sendText("收到: " + txt);
            }
            case IMAGE -> {
                // payload: 4 bytes 文件名长度 + 文件名 UTF-8 + 图片二进制
                ByteArrayInputStream bis = new ByteArrayInputStream(msg.getPayload());
                DataInputStream dis = new DataInputStream(bis);
                int nameLen = dis.readInt();
                byte[] nameBytes = new byte[nameLen];
                dis.readFully(nameBytes);
                String fileName = new String(nameBytes, StandardCharsets.UTF_8);
                byte[] imgData = dis.readAllBytes();
                // 保存到本地（目录 ./images/）
                File dir = new File("server_images");
                dir.mkdirs();
                File imgFile = new File(dir, fileName);
                Utils.writeAllBytes(imgFile, imgData);
                System.out.println("[收到图片] " + imgFile.getAbsolutePath());
                history.append("USER", "[图片] " + fileName);
                // 直接转发给客服
                sendImage(fileName, imgData);
            }
            case FILE -> {
                // payload 同 IMAGE，只是文件可能不是图片
                ByteArrayInputStream bis = new ByteArrayInputStream(msg.getPayload());
                DataInputStream dis = new DataInputStream(bis);
                int nameLen = dis.readInt();
                byte[] nameBytes = new byte[nameLen];
                dis.readFully(nameBytes);
                String fileName = new String(nameBytes, StandardCharsets.UTF_8);
                byte[] fileData = dis.readAllBytes();

                File dir = new File("server_files");
                dir.mkdirs();
                File f = new File(dir, fileName);
                Utils.writeAllBytes(f, fileData);
                System.out.println("[收到文件] " + f.getAbsolutePath());
                history.append("USER", "[文件] " + fileName);
                // 回显
                sendFile("已收到文件 " + fileName, fileName, fileData);
            }
            default -> System.out.println("[未处理] " + msg.getType());
        }
    }

    /** 发送文字给客户端 */
    private void sendText(String txt) throws IOException {
        Message m = new Message(MessageType.TEXT,
                txt.getBytes(StandardCharsets.UTF_8));
        m.writeTo(out);
        history.append("CSR", txt);
    }

    /** 发送图片给客户端（复用协议） */
    private void sendImage(String fileName, byte[] data) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(bos);
        byte[] nameBytes = fileName.getBytes(StandardCharsets.UTF_8);
        dos.writeInt(nameBytes.length);
        dos.write(nameBytes);
        dos.write(data);
        dos.flush();
        Message m = new Message(MessageType.IMAGE, bos.toByteArray());
        m.writeTo(out);
        history.append("CSR", "[图片] " + fileName);
    }

    /** 发送文件给客户端 */
    private void sendFile(String note, String fileName, byte[] data) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(bos);
        byte[] nameBytes = fileName.getBytes(StandardCharsets.UTF_8);
        dos.writeInt(nameBytes.length);
        dos.write(nameBytes);
        dos.write(data);
        dos.flush();
        Message m = new Message(MessageType.FILE, bos.toByteArray());
        m.writeTo(out);
        history.append("CSR", "[文件] " + fileName);
    }

    /** 关闭资源 */
    private void close() {
        try { in.close(); } catch (Exception ignored) {}
        try { out.close(); } catch (Exception ignored) {}
        try { socket.close(); } catch (Exception ignored) {}
        System.out.println("[连接关闭] " + userId);
    }
}
```

