    public ChatHistory(String userId) throws IOException {
        File dir = new File("history");
        dir.mkdirs();
        this.file = new File(dir, "chat_" + sanitize(userId) + ".log");
        if (!file.exists()) file.createNewFile();
    }

    /** 过滤文件系统非法字符 */
    private static String sanitize(String s) {
        return s.replaceAll("[^a-zA-Z0-9_.-]", "_");
    }

    /** 追加一行记录 */
    public synchronized void append(String role, String content) {
        String line = String.format("[%s] %s: %s%n",
                Utils.now(), role, content);
        try (FileWriter fw = new FileWriter(file, true)) {
            fw.write(line);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 读取全部记录（用于 UI 加载） */
    public synchronized String readAll() {
        try {
            return Files.readString(file.toPath());
        } catch (IOException e) {
            e.printStackTrace();
            return "";
        }
    }
}
