```java
package com.ecom.cs.client;

import com.ecom.cs.common.*;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class LoginDialog extends JDialog {
    private JTextField tfHost, tfPort;
    private JButton btnConnect;
    private JLabel lblStatus;

    public LoginDialog() {
        setTitle("电商客服系统 - 登录");
        setModal(true);
        setSize(350, 200);
        setLocationRelativeTo(null);
        setLayout(new GridBagLayout());

        tfHost = new JTextField("127.0.0.1", 15);
        tfPort = new JTextField("7777", 6);
        btnConnect = new JButton("连接客服");
        lblStatus = new JLabel(" ");

        GridBagConstraints c = new GridBagConstraints();
        c.insets = new Insets(5,5,5,5);
        c.gridx = 0; c.gridy = 0; add(new JLabel("服务器IP:"), c);
        c.gridx = 1; add(tfHost, c);
        c.gridx = 0; c.gridy = 1; add(new JLabel("端口:"), c);
        c.gridx = 1; add(tfPort, c);
        c.gridx = 0; c.gridy = 2; c.gridwidth = 2; add(btnConnect, c);
        c.gridy = 3; add(lblStatus, c);

        btnConnect.addActionListener(e -> connectToServer());
    }

    /** 连接 → 发送 SERVICE_REQUEST → 等待响应（5 秒） */
    private void connectToServer() {
        String host = tfHost.getText().trim();
        int port = Integer.parseInt(tfPort.getText().trim());

        btnConnect.setEnabled(false);
        lblStatus.setText("正在连接...");

        // 使用线程池防止阻塞 UI
        ExecutorService exec = Executors.newSingleThreadExecutor();
        Future<Boolean> future = exec.submit(() -> {
            try (Socket socket = new Socket()) {
                socket.connect(new InetSocketAddress(host, port), 5000); // 5s 连接超时
                DataInputStream in = new DataInputStream(socket.getInputStream());
                DataOutputStream out = new DataOutputStream(socket.getOutputStream());

                // 1️⃣ 发送 SERVICE_REQUEST
                Message request = new Message(MessageType.SERVICE_REQUEST, null);
                request.writeTo(out);

                // 2️⃣ 等待响应，最多 5 秒（业务上可调）
                socket.setSoTimeout(5000);
                Message resp = Message.readFrom(in);
                if (resp == null || resp.getType() != MessageType.SERVICE_RESPONSE) {
                    return false;
                }
                boolean accepted = resp.getPayload().length > 0 && resp.getPayload()[0] == 1;
                return accepted;
            } catch (IOException ex) {
                ex.printStackTrace();
                return false;
            }
        });

        // 处理超时/结果
        exec.shutdown();
        new Thread(() -> {
            try {
                boolean ok = future.get(7, TimeUnit.SECONDS);
                SwingUtilities.invokeLater(() -> {
                    if (ok) {
                        lblStatus.setText("客服已接受，进入聊天界面");
                        // 打开 ChatFrame 并把 socket 交给它（这里重新建立一次连接，实际可以共享）
                        ChatFrame chat = new ChatFrame(host, port);
                        chat.setVisible(true);
                        dispose(); // 关闭登录框
                    } else {
                        lblStatus.setText("客服忙或拒绝，稍后再试");
                        btnConnect.setEnabled(true);
                    }
                });
            } catch (TimeoutException te) {
                SwingUtilities.invokeLater(() -> {
                    lblStatus.setText("等待客服响应超时，客服可能正忙");
                    btnConnect.setEnabled(true);
                });
            } catch (Exception ex) {
                SwingUtilities.invokeLater(() -> {
                    lblStatus.setText("连接出错：" + ex.getMessage());
                    btnConnect.setEnabled(true);
                });
            }
        }).start();
    }
}
