```java
package com.ecom.cs.client;

import com.ecom.cs.common.*;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class ChatFrame extends JFrame {
    private final JTextArea taChat;
    private final JTextField tfInput;
    private final JButton btnSend, btnFile, btnImg;
    private final Socket socket;
    private final DataInputStream in;
    private final DataOutputStream out;
    private final ExecutorService exec = Executors.newSingleThreadExecutor();

    private final ChatHistory history; // 客户端本地记录

    public ChatFrame(String host, int port) throws IOException {
        setTitle("客服聊天窗口");
        setSize(600, 500);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);

        // UI 组件
        taChat = new JTextArea();
        taChat.setEditable(false);
        taChat.setLineWrap(true);
        JScrollPane sp = new JScrollPane(taChat);
        tfInput = new JTextField();
        btnSend = new JButton("发送");
        btnFile = new JButton("发送文件");
        btnImg  = new JButton("发送图片");

        JPanel bottom = new JPanel(new BorderLayout(5,5));
        bottom.add(tfInput, BorderLayout.CENTER);
        JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT,5,0));
        btnPanel.add(btnImg);
        btnPanel.add(btnFile);
        btnPanel.add(btnSend);
        bottom.add(btnPanel, BorderLayout.EAST);
        bottom.setBorder(new EmptyBorder(5,5,5,5));

        add(sp, BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);

        // 初始化 socket (复用登录时建立的 socket，或者重新建立)
        this.socket = new Socket(host, port);
        this.in = new DataInputStream(socket.getInputStream());
        this.out = new DataOutputStream(socket.getOutputStream());

        // 本地聊天记录
        history = new ChatHistory("client_user"); // 简化为固定 ID，实际可用登录名
        taChat.append(history.readAll());

        // 按钮事件
        btnSend.addActionListener(e -> sendText());
        tfInput.addActionListener(e -> sendText());
        btnImg.addActionListener(e -> sendImage());
        btnFile.addActionListener(e -> sendFile());

        // 启动读取线程
        exec.submit(this::receiveLoop);

        // 窗口关闭时清理资源
        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                try {
                    socket.close();
                } catch (IOException ignored) {}
                exec.shutdownNow();
            }
        });
    }

    /** 发送文字 */
    private void sendText() {
        String txt = tfInput.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message m = new Message(MessageType.TEXT,
                    txt.getBytes(StandardCharsets.UTF_8));
            m.writeTo(out);
            appendChat("我", txt);
            tfInput.setText("");
        } catch (IOException ex) {
            showError("发送失败: " + ex.getMessage());
        }
    }

    /** 发送图片（png/jpg） */
    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter(
                "图片文件", "png", "jpg", "jpeg", "bmp"));
        int rc = chooser.showOpenDialog(this);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File img = chooser.getSelectedFile();
        try {
            byte[] data = Utils.readAllBytes(img);
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            DataOutputStream dos = new DataOutputStream(bos);
            byte[] nameBytes = img.getName().getBytes(StandardCharsets.UTF_8);
            dos.writeInt(nameBytes.length);
            dos.write(nameBytes);
            dos.write(data);
            dos.flush();
            Message m = new Message(MessageType.IMAGE, bos.toByteArray());
            m.writeTo(out);
            appendChat("我", "[图片] " + img.getName());
        } catch (IOException ex) {
            showError("发送图片失败: " + ex.getMessage());
        }
    }

    /** 发送任意文件 */
    private void sendFile() {
        JFileChooser chooser = new JFileChooser();
        int rc = chooser.showOpenDialog(this);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File f = chooser.getSelectedFile();
        try {
            byte[] data = Utils.readAllBytes(f);
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            DataOutputStream dos = new DataOutputStream(bos);
            byte[] nameBytes = f.getName().getBytes(StandardCharsets.UTF_8);
            dos.writeInt(nameBytes.length);
            dos.write(nameBytes);
            dos.write(data);
            dos.flush();
            Message m = new Message(MessageType.FILE, bos.toByteArray());
            m.writeTo(out);
            appendChat("我", "[文件] " + f.getName());
        } catch (IOException ex) {
            showError("发送文件失败: " + ex.getMessage());
        }
    }

    /** 接收线程循环 */
    private void receiveLoop() {
        try {
            while (true) {
                Message msg = Message.readFrom(in);
                if (msg == null) break; // 对端关闭
                SwingUtilities.invokeLater(() -> handleIncoming(msg));
            }
        } catch (IOException e) {
            SwingUtilities.invokeLater(() -> showError("连接中断: " + e.getMessage()));
        }
    }

    /** 处理收到的消息并显示 */
    private void handleIncoming(Message msg) {
        switch (msg.getType()) {
            case TEXT -> {
                String txt = new String(msg.getPayload(), StandardCharsets.UTF_8);
                appendChat("客服", txt);
            }
            case IMAGE -> {
                // payload: 4B nameLen + name + imgData
                try (DataInputStream dis = new DataInputStream(
                        new ByteArrayInputStream(msg.getPayload()))) {
                    int nameLen = dis.readInt();
                    byte[] nameBytes = new byte[nameLen];
                    dis.readFully(nameBytes);
                    String name = new String(nameBytes, StandardCharsets.UTF_8);
                    byte[] imgData = dis.readAllBytes();

                    // 保存到本地临时文件
                    File dir = new File("client_images");
                    dir.mkdirs();
                    File imgFile = new File(dir, name);
                    Utils.writeAllBytes(imgFile, imgData);
                    appendChat("客服", "[图片] " + name);
                } catch (IOException e) {
                    showError("解析图片失败: " + e.getMessage());
                }
            }
            case FILE -> {
                try (DataInputStream dis = new DataInputStream(
                        new ByteArrayInputStream(msg.getPayload()))) {
                    int nameLen = dis.readInt();
                    byte[] nameBytes = new byte[nameLen];
                    dis.readFully(nameBytes);
                    String name = new String(nameBytes, StandardCharsets.UTF_8);
                    byte[] fileData = dis.readAllBytes();

                    File dir = new File("client_files");
                    dir.mkdirs();
                    File f = new File(dir, name);
                    Utils.writeAllBytes(f, fileData);
                    appendChat("客服", "[文件] " + name);
                } catch (IOException e) {
                    showError("解析文件失败: " + e.getMessage());
                }
            }
            default -> System.out.println("[未识别] " + msg.getType());
        }
    }

    /** UI 追加并写入本地历史记录 */
    private void appendChat(String who, String content) {
        String line = String.format("[%s] %s: %s%n",
                Utils.now(), who, content);
        taChat.append(line);
        taChat.setCaretPosition(taChat.getDocument().getLength());
        history.append(who, content);
    }

    private void showError(String msg) {
        JOptionPane.showMessageDialog(this, msg,
                "错误", JOptionPane.ERROR_MESSAGE);
    }
}
