import java.util.Random;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveAction;

public class ParallelQuickSort extends RecursiveAction {

    private static final int THRESHOLD = 1_000;   // optional: stop splitting for small arrays
    private final int left;
    private final int right;
    private final int[] arr;
    private static final Random RAND = new Random();

    public ParallelQuickSort(int left, int right, int[] arr) {
        this.left = left;
        this.right = right;
        this.arr = arr;
    }

    @Override
    protected void compute() {
        // Base case – nothing (or a single element) to sort
        if (left >= right) {
            return;
        }

        // For very small sub‑arrays it is cheaper to sort sequentially.
        if (right - left + 1 <= THRESHOLD) {
            sequentialQuickSort(left, right);
            return;
        }

        // Partition the array around a random pivot
        int pivotIdx = partition(left, right);

        // Create two sub‑tasks: left part and right part
        ParallelQuickSort leftTask  = new ParallelQuickSort(left, pivotIdx - 1, arr);
        ParallelQuickSort rightTask = new ParallelQuickSort(pivotIdx + 1, right, arr);

        // Fork the left task and compute the right one in the current thread
        leftTask.fork();      // run left part asynchronously
        rightTask.compute(); // run right part synchronously
        leftTask.join();      // wait for left part to finish
    }

    /* --------------------------------------------------------------
     * Partition routine (Lomuto scheme with a random pivot)
     * -------------------------------------------------------------- */
    private int partition(int low, int high) {
        // Choose a random index in [low,high] and move it to the end
        int pivotIdx = low + RAND.nextInt(high - low + 1);
        swap(pivotIdx, high);

        int pivot = arr[high];   // now the pivot is at position 'high'
        int i = low - 1;         // index of smaller element

        for (int j = low; j < high; j++) {
            if (arr[j] <= pivot) {
                i++;
                swap(i, j);
            }
        }
        // place pivot after the last smaller element
        swap(i + 1, high);
        return i + 1;  // new pivot position
    }

    /* --------------------------------------------------------------
     * Simple sequential quick‑sort used for tiny sub‑arrays.
     * -------------------------------------------------------------- */
    private void sequentialQuickSort(int low, int high) {
        if (low >= high) return;
        int p = partition(low, high);
        sequentialQuickSort(low, p - 1);
        sequentialQuickSort(p + 1, high);
    }

    /* --------------------------------------------------------------
     * Utility: swap two positions in the array.
     * -------------------------------------------------------------- */
    private void swap(int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    /* --------------------------------------------------------------
     * Test driver
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        int[] arr = {54, 64, 95, 82, 12, 32, 63};

        // Create a ForkJoinPool (using the common pool here)
        ForkJoinPool pool = ForkJoinPool.commonPool();

        // Launch the parallel quick‑sort
        pool.invoke(new ParallelQuickSort(0, arr.length - 1, arr));

        // Print the sorted array
        for (int v : arr) {
            System.out.print(v + " ");
        }
        System.out.println();
    }
}
```

### What was changed / why it works

| Issue in the original code | Fix applied | Reason |
|----------------------------|-------------|--------|
| Miss‑spelled variable names (`pivote`, `pivoted`) | Replaced with a single, correctly‑named `pivotIdx` | Guarantees the compiler can resolve the identifier. |
| Wrong random range (`nextInt(j‑i) + i`) | `low + RAND.nextInt(high - low + 1)` | `nextInt(bound)` is exclusive, so we add `+1` to include the upper bound. |
| Swapped the pivot with the *end* element but then used `arr[end]` while `end` was later decremented (`j--`) | Properly move the random pivot to `high` (the end) and keep it there until the final swap. | Makes the partition logic correct and easy to follow. |
| `RecursiveTask<Integer>` returning `null` | Switched to `RecursiveAction` (no result) | QuickSort does not need to return a value; `RecursiveAction` is the idiomatic choice. |
| No base case for very small sub‑arrays (lots of tiny tasks) | Added an optional `THRESHOLD` to fall‑back to sequential quick‑sort | Improves performance by avoiding overhead of creating many tasks. |
| Overall readability & style | Added comments, extracted helper methods (`swap`, `sequentialQuickSort`) | Makes the code maintainable and easier to understand. |

Compile and run the program (e.g. `javac ParallelQuickSort.java && java ParallelQuickSort`) and you will see the output:

```
12 32 54 63 64 82 95 
```

which confirms that the array is correctly sorted using a parallel QuickSort implementation.

