```java
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class TCPPacketServer {

    private static final int PORT = 1024;
    private static final ExecutorService POOL = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        System.out.println("Opening port…");               // <‑‑ required message

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {

            while (true) {
                Socket clientSocket = serverSocket.accept();   // block until a client connects
                POOL.execute(new ClientHandler(clientSocket));
            }

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            POOL.shutdown();
        }
    }

    /** Handles a single client connection */
    private static class ClientHandler implements Runnable {
        private final Socket socket;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
                 PrintWriter   out = new PrintWriter(socket.getOutputStream(), true)) {

                while (true) {
                    // ----- read the Packet object sent by the client -----
                    Packet packet = (Packet) ois.readObject();

                    // ----- print the required server‑side information -----
                    System.out.println(
                            "Recieving From Clients Packet’s serialNo#" + packet.getSerialNo() + "\n"
                                    + "and packet’s Data is " + packet.getData());

                    // ----- if client asked to close the connection, exit loop -----
                    if ("CLOSE".equalsIgnoreCase(packet.getData())) {
                        break;
                    }

                    // ----- send a tiny text acknowledgment back to the client -----
                    out.println("Packet SerialNo#" + packet.getSerialNo() + " is recieved");
                }

            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            } finally {
                try {
                    socket.close();
                } catch (IOException ignored) {
                }
            }
        }
    }
}
```

### What changed / why?

| Old code | New code | Reason |
|----------|----------|--------|
| Printed nothing before the `accept` loop | `System.out.println("Opening port…");` | Required start‑up message |
| Read raw bytes, created a new `ObjectInputStream` **inside** the loop | One `ObjectInputStream` created once (outside the loop) | Faster, avoids stream‑header corruption |
| After receiving a packet, created a **response `Packet`** with `data.toUpperCase()` and sent the raw bytes back | Only a **text acknowledgment** (`PrintWriter.println`) is sent | The specification only asks for “Packet SerialNo#X is recieved” – no data modifications |
| Used `PrintStream` for sending raw bytes | Used `PrintWriter` for sending a line of text | Simpler for the required one‑line ACK |
| Printed *“FROM CLIENT …”* | Printed *“Recieving From Clients …”* exactly as requested | Correct wording and format |

