import java.io.*;
import java.net.*;

public class TCPPacketClient {

    private static final String PROMPT = "Enter the data packet: ";

    public static void main(String[] args) {
        try (Socket socket = new Socket("localhost", 1024);
             // to send the Packet object
             ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
             // to read the one‑line ACK from the server
             BufferedReader serverIn = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             // to read user input from console
             BufferedReader userIn = new BufferedReader(new InputStreamReader(System.in))) {

            String line;
            int serialNo = 1;

            while (true) {
                System.out.print(PROMPT);
                line = userIn.readLine();               // user types something

                // Build and send the packet
                Packet packet = new Packet(serialNo++, line);
                oos.writeObject(packet);
                oos.flush();

                // If the user typed CLOSE we stop after receiving the server ACK
                if ("CLOSE".equalsIgnoreCase(line)) {
                    // still wait for the ACK so that the server can finish cleanly
                    String ack = serverIn.readLine();
                    System.out.println("FROM SERVER:" + ack);
                    break;
                }

                // ----- read the server's acknowledgment line -----
                String ack = serverIn.readLine();        // e.g. "Packet SerialNo#1 is recieved"
                System.out.println("FROM SERVER:" + ack);
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

### What changed / why?

| Old code | New code | Reason |
|----------|----------|--------|
| Created a new `ObjectOutputStream` **inside** the loop and sent raw byte array via `PrintStream` | One `ObjectOutputStream` created once, `writeObject(packet)` used directly | Simpler and less error‑prone |
| Expected a *`Packet`* back from the server and printed its data | Reads a **single line** (`BufferedReader.readLine()`) and prints it as “FROM SERVER:…”. | Matches required output (`Packet SerialNo#X is recieved`) |
| Printed `"FROM SERVER: Packet SerialNo#X, Data: …"` | Prints exactly `"FROM SERVER:Packet SerialNo#X is recieved"` | Required format |
| Used `PrintStream` and manual byte‑array handling | Uses `BufferedReader`/`PrintWriter` for line‑oriented communication | Easier to read/write the tiny acknowledgment string |

