package com.example.websocket.server;

import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * WebSocket 服务器端点（接收图片二进制并保存）。
 */
@ServerEndpoint(value = "/image")
public class ImageWebSocketServer {

    /** 用于把分片累加的 ByteArrayOutputStream（每个会话独立） */
    private ByteArrayOutputStream baos = new ByteArrayOutputStream();

    /** 是否已经收到完整图片（一个示例协议：客户端只发送一次完整二进制） */
    private AtomicBoolean finished = new AtomicBoolean(false);

    @OnOpen
    public void onOpen(Session session) {
        System.out.println("[Server] New connection, id=" + session.getId());
        // 可自行限制每个 Session 最大接受字节数
        //session.setMaxBinaryMessageBufferSize(10 * 1024 * 1024); // 10 MB
    }

    /** 接收二进制块（可能是分片） */
    @OnMessage
    public void onBinaryMessage(ByteBuffer message, Session session) throws IOException {
        // 把本块写入 ByteArrayOutputStream
        byte[] bytes = new byte[message.remaining()];
        message.get(bytes);
        baos.write(bytes);

        // 这里演示仅接收一次完整图片（客户端一次发送完毕），因此直接保存
        // 实际业务请自行约定结束标志或使用分块协议
        if (!finished.getAndSet(true)) {
            // 保存图片
            File outFile = new File("received_from_" + session.getId() + ".png");
            try (FileOutputStream fos = new FileOutputStream(outFile)) {
                baos.writeTo(fos);
            }
            System.out.println("[Server] Image saved to " + outFile.getAbsolutePath());

            // 向客户端发送确认
            session.getBasicRemote().sendText("OK");
        }
    }

    @OnClose
    public void onClose(Session session, CloseReason reason) {
        System.out.println("[Server] Session closed: " + reason);
        // 资源回收
        try {
            baos.close();
        } catch (IOException ignored) {
        }
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        System.err.println("[Server] Error on session " + session.getId() + ": " + throwable);
    }
}
