```java
package com.example.socketreceiver.server;

import lombok.extern.slf4j.Slf4j;

import java.io.*;
import java.net.Socket;
import java.net.SocketException;
import java.net.SocketTimeoutException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * 处理单个客户端的 IO，示例中按行读取（文本协议）。
 */
@Slf4j
public class ClientHandler implements Runnable {

    private final Socket socket;
    private final int readTimeoutMs; // -1 表示不超时

    private static final String CHARSET = "UTF-8";

    public ClientHandler(Socket socket, int readTimeoutMs) throws SocketException {
        this.socket = socket;
        this.readTimeoutMs = readTimeoutMs;
        if (readTimeoutMs > 0) {
            socket.setSoTimeout(readTimeoutMs);
        }
        socket.setTcpNoDelay(true);
    }

    @Override
    public void run() {
        String clientId = socket.getRemoteSocketAddress().toString();
        log.info("[{}] ✅ 新客户端连接，准备读取数据", clientId);
        try (InputStream in = socket.getInputStream();
             OutputStream out = socket.getOutputStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(in, CHARSET));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(out, CHARSET))) {

            String line;
            while ((line = reader.readLine()) != null) {
                log.info("[{}] 📥 收到数据: {}", clientId, line);

                // 简单回写 ACK，帮助客户端确认
                String ack = "ACK " + LocalDateTime.now()
                        .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")) + "\n";
                writer.write(ack);
                writer.flush();
            }

            log.info("[{}] ❎ 客户端已关闭连接", clientId);
        } catch (SocketTimeoutException ste) {
            log.warn("[{}] ⏰ 读取超时（{} ms），关闭连接", clientId, readTimeoutMs);
        } catch (IOException e) {
            log.error("[{}] ❌ IO 异常，关闭连接", clientId, e);
        } finally {
            try {
                socket.close();
                log.info("[{}] 🔌 连接已关闭", clientId);
            } catch (IOException e) {
                log.warn("[{}] 关闭 Socket 时异常", clientId, e);
            }
        }
    }
}
