    private static final String[] FRIDA_MODULES = {
            "libfrida-gadget.so", "libfrida-gadget64.so"
    };

    public static boolean isFridaDetected() {
        try (BufferedReader br = new BufferedReader(new FileReader("/proc/self/maps"))) {
            String line;
            while ((line = br.readLine()) != null) {
                for (String lib : FRIDA_MODULES) {
                    if (line.contains(lib)) return true;
                }
            }
        } catch (IOException ignored) {}
        return false;
    }

    // 2. 检测 root
    public static boolean isRooted() {
        String[] paths = {"/system/xbin/su", "/system/bin/su", "/system/app/Superuser.apk"};
        for (String p : paths) if (new File(p).exists()) return true;
        return false;
    }

    // 3. 完整性校验（apk hash 与服务器端存的对比）
    public static boolean checkApkHash(Context ctx) throws Exception {
        String pkg = ctx.getPackageName();
        PackageInfo pi = ctx.getPackageManager().getPackageInfo(pkg, 0);
        String sourceDir = pi.applicationInfo.sourceDir;
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new FileInputStream(sourceDir)) {
            byte[] buf = new byte[8192];
            int len;
            while ((len = is.read(buf)) != -1) md.update(buf, 0, len);
        }
        String localHash = Base64.encodeToString(md.digest(), Base64.NO_WRAP);
        // 向安全服务器请求合法 hash（示例）
        String officialHash = ServerApi.getApkHash(pkg);
        return localHash.equals(officialHash);
    }

    // 4. 合并检测：若任意异常 → 中断网络并上报
    public static void enforceGuard(Context ctx) {
        if (isRooted() || isFridaDetected()) {
            // 关闭业务网络、弹出警告、上报日志
            NetworkManager.shutdown();
            Log.e("Guard", "Security check failed!");
        }
    }
}
