## 2️⃣ Java 代码（核心实现）

```java
package com.example.json2xml;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.nio.charset.StandardCharsets;

/**
 * JSON → XML 转换工具
 *
 * <p>使用方法（命令行）：
 * <pre>
 *   java -jar json2xml-demo-1.0.0.jar [input.json] [output.xml]
 * </pre>
 * 若不指定参数，则默认读取 classpath 下的 {@code sample.json}
 * 并把结果输出到 {@code result.xml}（同目录）。
 *
 * <p>核心思路：
 * <ol>
 *   <li>使用 {@link ObjectMapper} 把 JSON 解析成 {@link JsonNode}（树结构）。</li>
 *   <li>使用 {@link XmlMapper} 把同一个 {@link JsonNode} 写成 XML。</li>
 *   <li>默认根标签为 {@code root}，可通过 {@link XmlMapper#setDefaultUseWrapper(boolean)} 调整。</li>
 * </ol>
 */
public class Json2XmlConverter {

    private static final Logger log = LoggerFactory.getLogger(Json2XmlConverter.class);

    /** 默认根标签名称（Jackson 默认是 "root"） */
    private static final String DEFAULT_ROOT_NAME = "root";

    private final ObjectMapper jsonMapper;
    private final XmlMapper xmlMapper;

    public Json2XmlConverter() {
        // JSON 解析器
        this.jsonMapper = new ObjectMapper();

        // XML 序列化器
        this.xmlMapper = new XmlMapper();

        // 让 XmlMapper 使用 “root” 作为根节点（也可以自行改成其它名字）
        xmlMapper.setDefaultUseWrapper(false); // 不自动包装 List 为 <item>，保持结构一致
    }

    /**
     * 将 JSON 字符串转换为 XML 字符串
     *
     * @param jsonStr JSON 内容
     * @return XML 内容
     * @throws JsonProcessingException 解析或序列化异常
     */
    public String convert(String jsonStr) throws JsonProcessingException {
        // 1️⃣ 解析 JSON 为 JsonNode（树结构）
        JsonNode node = jsonMapper.readTree(jsonStr);

        // 2️⃣ 把 JsonNode 写成 XML。这里使用默认的根节点名 "root"
        //    如果想要自定义根节点，可在写 XML 前包装一个 ObjectNode
        return xmlMapper.writer()
                .withRootName(DEFAULT_ROOT_NAME) // 指定根标签名
                .writeValueAsString(node);
    }

    /**
     * 将文件中的 JSON 转换为 XML 并写入目标文件
     *
     * @param inputJsonFile  输入 JSON 文件（支持 .json 或 .txt）
     * @param outputXmlFile  输出 XML 文件
     * @throws IOException 读写异常
     */
    public void convertFile(File inputJsonFile, File outputXmlFile) throws IOException {
        // 读取整个文件内容（假设文件不是超大文件，如是大文件请改为流式处理）
        String json = readFileAsString(inputJsonFile);
        String xml;
        try {
            xml = convert(json);
        } catch (JsonProcessingException e) {
            throw new IOException("JSON 解析错误：" + e.getMessage(), e);
        }

        // 写入目标文件（使用 UTF-8）
        try (Writer writer = new OutputStreamWriter(new FileOutputStream(outputXmlFile), StandardCharsets.UTF_8)) {
            writer.write(xml);
        }
    }

    /** 简单读取文件为字符串（UTF-8） */
    private static String readFileAsString(File file) throws IOException {
        try (InputStream in = new FileInputStream(file);
             Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8);
             StringWriter sw = new StringWriter()) {

            char[] buf = new char[4096];
            int len;
            while ((len = reader.read(buf)) != -1) {
                sw.write(buf, 0, len);
            }
            return sw.toString();
        }
    }

    /** 程序入口 */
    public static void main(String[] args) {
        Json2XmlConverter converter = new Json2XmlConverter();

        try {
            if (args.length == 2) {
                // 通过命令行参数指定输入/输出文件
                File in = new File(args[0]);
                File out = new File(args[1]);
                log.info("读取 JSON: {}", in.getAbsolutePath());
                log.info("写入 XML: {}", out.getAbsolutePath());
                converter.convertFile(in, out);
                log.info("转换成功！");
            } else {
                // 演示模式：使用 classpath 中的 sample.json
                InputStream sampleStream = Json2XmlConverter.class.getClassLoader()
                        .getResourceAsStream("sample.json");
                if (sampleStream == null) {
                    log.error("找不到 classpath:/sample.json，请自行准备测试文件或使用命令行参数指定路径。");
                    System.exit(1);
                }

                String json = new BufferedReader(new InputStreamReader(sampleStream, StandardCharsets.UTF_8))
                        .lines()
                        .reduce("", (a, b) -> a + "\n" + b);

                String xml = converter.convert(json);
                // 打印到控制台，同时保存到 result.xml
                System.out.println("=== 转换后的 XML ===");
                System.out.println(xml);

                File outFile = new File("result.xml");
                try (Writer writer = new OutputStreamWriter(new FileOutputStream(outFile), StandardCharsets.UTF_8)) {
                    writer.write(xml);
                }
                log.info("默认样例已保存到 {}", outFile.getAbsolutePath());
            }
        } catch (Exception e) {
            log.error("转换过程出错：", e);
            System.exit(1);
        }
    }
}
```

### 关键点解释

| 步骤 | 代码片段 | 说明 |
|------|----------|------|
| **1️⃣ 读取 JSON** | `jsonMapper.readTree(jsonStr)` | `ObjectMapper` 能把任意合法 JSON（对象、数组、数值、布尔等）解析为 `JsonNode`，树结构非常通用。 |
| **2️⃣ 设置根标签** | `.withRootName(DEFAULT_ROOT_NAME)` | 默认根标签为 `root`，如果你想自己定义，请修改 `DEFAULT_ROOT_NAME`。 |
| **3️⃣ 写 XML** | `xmlMapper.writer().writeValueAsString(node)` | `XmlMapper` 把 `JsonNode` 按照 Jackson 的映射规则序列化为 XML。<br>*数组会变成连续的同名子元素；对象属性会变成子标签；简单值会直接写在标签体里。* |
| **4️⃣ 控制 List 包装** | `xmlMapper.setDefaultUseWrapper(false)` | 默认情况下，Jackson 为 `List` 包装 `<item>` 标签，这行代码关闭包装，使得 JSON 中的数组直接映射为同名标签序列。|
| **5️⃣ 文件 I/O** | `readFileAsString`、`convertFile` | 简单的读取/写入实现，使用 UTF‑8 编码，适用于中小文件。如果要处理 GB 级大文件，请改为 **流式**（`JsonParser` + `XmlGenerator`）的方式。 |

