### 11.2 `FileUploadServlet.java`

```java
package com.example.upload;

import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.MultipartConfig;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;

import org.apache.commons.fileupload.FileItem;
import org.apache.commons.fileupload.disk.*;
import org.apache.commons.fileupload.servlet.*;

import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.util.List;

@WebServlet("/upload")
@MultipartConfig // optional – enables request.getParts() if you prefer that API
public class FileUploadServlet extends HttpServlet {

    // Load from servlet init‑param or system property in real apps
    private final Path uploadDir = Paths.get("uploads").toAbsolutePath().normalize();

    @Override
    public void init() throws ServletException {
        try {
            Files.createDirectories(uploadDir);
        } catch (IOException e) {
            throw new ServletException("Could not create upload directory", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // Check that we have a file upload request
        if (!ServletFileUpload.isMultipartContent(request)) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Form must has enctype=multipart/form-data.");
            return;
        }

        DiskFileItemFactory factory = new DiskFileItemFactory();
        // Set temporary location to store files larger than the buffer size
        factory.setRepository(new File(System.getProperty("java.io.tmpdir")));

        ServletFileUpload upload = new ServletFileUpload(factory);
        // You can set file size limits here if you want:
        // upload.setFileSizeMax(10 * 1024 * 1024); // 10 MB

        try {
            List<FileItem> formItems = upload.parseRequest(request);
            for (FileItem item : formItems) {
                // Process only file fields
                if (!item.isFormField()) {
                    // Sanitize the file name
                    String fileName = Paths.get(item.getName()).getFileName().toString();
                    if (fileName.contains("..")) {
                        throw new SecurityException("Invalid file name");
                    }

                    Path target = uploadDir.resolve(fileName);
                    // To avoid overwriting, you could generate a UUID prefix:
                    // String unique = java.util.UUID.randomUUID().toString();
                    // Path target = uploadDir.resolve(unique + "_" + fileName);

                    // Write the file
                    Files.copy(item.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);

                    // Simple text response
                    response.setContentType("text/plain");
                    response.getWriter().println("File uploaded successfully: " + target);
                }
            }
        } catch (Exception ex) {
            throw new ServletException("File upload failed", ex);
        }
    }
}
```

**Deploy:**  
* Add the servlet class (`FileUploadServlet`) to your web application `WEB-INF/classes` (or compile with Maven/Gradle).  
* Add a simple HTML form (same as the one from the Spring example) that posts to `/upload`.  

The servlet does the same sanitisation and storage steps, but without Spring’s abstractions.

