 └─ city      : String
 └─ address   : String
 └─ rank      : double    (media pesata delle review)
 └─ reviews   : List<Review>

Review
 └─ user      : String   (username)
 └─ globalScore : int    (0‑10)
 └─ singleScores : int[] (es. [pulizia, posizione, personale, rapportoQualitàPrezzo])
 └─ timestamp   : long   (epoch ms)
