### 5.1 `ClientHandler`

1. Legge **una riga** JSON dalla connessione.  
2. Converte in oggetto `Request` (campo `action` + `payload`).  
3. Instrada la chiamata verso `Service`.  
4. Costruisce `Response` (status, msg, eventuale payload) → JSON → invia al client.  
5. Loop fino a `quit` o chiusura socket.

```java
class ClientHandler implements Runnable {
    private final Socket socket;
    private final Service service = Service.getInstance();
    private UserSession session = new UserSession(); // initially not logged

    @Override
    public void run() {
        try (BufferedReader in = new BufferedReader(
                 new InputStreamReader(socket.getInputStream()));
             PrintWriter out = new PrintWriter(
                 new OutputStreamWriter(socket.getOutputStream()), true)) {

            String line;
            while ((line = in.readLine()) != null) {
                Request req = JsonUtil.fromJson(line, Request.class);
                Response resp = handle(req);
                out.println(JsonUtil.toJson(resp));
                if (resp.getStatus() == ResponseStatus.QUIT) break;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private Response handle(Request req) {
        switch (req.getAction()) {
            case "register":   return service.register(req.getPayload(), session);
            case "login":      return service.login   (req.getPayload(), session);
            case "logout":     return service.logout  (session);
            case "searchHotel":return service.searchHotel(req.getPayload());
            case "searchAllHotels":return service.searchAll(req.getPayload());
            case "insertReview": return service.insertReview(req.getPayload(), session);
            case "showMyBadges": return service.showBadge(session);
            case "quit":       return new Response(ResponseStatus.QUIT, "Bye!");
            default:           return new Response(ResponseStatus.ERROR, "Action not supported");
        }
    }
}
```

### 5.2 `Service`

```java
public class Service {
    private static final Service INSTANCE = new Service();
    private final Map<String,User> users = new ConcurrentHashMap<>();
    private final Map<String,Hotel> hotels = new ConcurrentHashMap<>();

    private Service() {
        loadFromDisk(); // read JSON files
    }

    public static Service getInstance() { return INSTANCE; }

    /* ---------- REGISTER ---------- */
    public synchronized Response register(JsonObject payload, UserSession sess) {
        String username = payload.get("username").getAsString().trim();
        String password = payload.get("password").getAsString();

        if (username.isEmpty() || password.isEmpty())
            return Response.error(1, "Username or password empty");

        if (users.containsKey(username))
            return Response.error(2, "Username already exists");

        String pwdHash = Crypto.sha256(password);
        User u = new User(username, pwdHash);
        users.put(username, u);
        persistUsers();   // write to file
        return Response.ok("Registered successfully");
    }

    /* ---------- LOGIN ---------- */
    public synchronized Response login(JsonObject payload, UserSession sess) {
        String username = payload.get("username").getAsString();
        String password = payload.get("password").getAsString();

        User u = users.get(username);
        if (u == null)
            return Response.error(3, "User not registered");

        if (!u.getPasswordHash().equals(Crypto.sha256(password)))
            return Response.error(4, "Wrong password");

        if (sess.isLogged())
            return Response.error(5, "User already logged in on this client");

        sess.setUser(u);
        u.setLoggedIn(true);
        return Response.ok("Login successful");
    }

    /* ---------- LOGOUT ---------- */
    public synchronized Response logout(UserSession sess) {
        if (!sess.isLogged())
            return Response.error(6, "Not logged in");

        sess.getUser().setLoggedIn(false);
        sess.clear();
        return Response.ok("Logout successful");
    }

    /* ---------- SEARCH HOTEL ---------- */
    public Response searchHotel(JsonObject payload) {
        String name = payload.get("nomeHotel").getAsString();
        String city = payload.get("città").getAsString();

        String key = makeHotelKey(name, city);
        Hotel h = hotels.get(key);
        if (h == null) return Response.error(7, "Hotel not found");
        return Response.okWithData(h);
    }

    /* ---------- SEARCH ALL ---------- */
    public Response searchAll(JsonObject payload) {
        String city = payload.get("città").getAsString();
        List<Hotel> list = hotels.values().stream()
                .filter(h -> h.getCity().equalsIgnoreCase(city))
                .sorted(Comparator.comparingDouble(Hotel::getRank).reversed())
                .collect(Collectors.toList());

        if (list.isEmpty())
            return Response.error(8, "No hotels in that city");
        return Response.okWithData(list);
    }

    /* ---------- INSERT REVIEW ---------- */
    public synchronized Response insertReview(JsonObject payload, UserSession sess) {
        if (!sess.isLogged())
            return Response.error(9, "Login required");

        String hotelName = payload.get("nomeHotel").getAsString();
        String city      = payload.get("nomeCittà").getAsString();
        int globalScore  = payload.get("GlobalScore").getAsInt();
        JsonArray arr    = payload.getAsJsonArray("SingleScores");
        int[] singles = new int[arr.size()];
        for (int i = 0; i < arr.size(); i++) singles[i] = arr.get(i).getAsInt();

        String key = makeHotelKey(hotelName, city);
        Hotel h = hotels.get(key);
        if (h == null) return Response.error(10, "Hotel not found");

        Review r = new Review(sess.getUsername(), globalScore, singles, System.currentTimeMillis());
        h.addReview(r);
        // update rank
        h.recalculateRank();

        // update badge del revisore
        User u = sess.getUser();
        u.incrementReviews();
        u.updateBadge();

        persistAll(); // write hotels + users again
        return Response.ok("Review inserted");
    }

    /* ---------- SHOW BADGE ---------- */
    public Response showBadge(UserSession sess) {
        if (!sess.isLogged())
            return Response.error(11, "Login required");

        Badge badge = sess.getUser().getBadge();
        return Response.ok("Your badge: " + badge.name());
    }

    /* ---------------- HELPERS ---------------- */
    private String makeHotelKey(String name, String city) {
        return name.toLowerCase() + "#" + city.toLowerCase();
    }

    // Persist/Load methods (using Gson)
    private void persistUsers() { JsonUtil.toFile("users.json", users.values()); }
    private void persistHotels(){ JsonUtil.toFile("hotels.json", hotels.values()); }
    private void persistAll()   { persistUsers(); persistHotels(); }

    private void loadFromDisk() {
        Type userList = new TypeToken<List<User>>(){}.getType();
        List<User> ul = JsonUtil.fromFile("users.json", userList);
        if (ul != null) ul.forEach(u -> users.put(u.getUsername(), u));

        Type hotelList = new TypeToken<List<Hotel>>(){}.getType();
        List<Hotel> hl = JsonUtil.fromFile("hotels.json", hotelList);
        if (hl != null) hl.forEach(h -> hotels.put(makeHotelKey(h.getName(), h.getCity()), h));
    }
}
```

*Le funzioni di persistenza* usano una classe `JsonUtil` che incapsula `Gson.fromJson` / `toJson`.  
Sono **sincronizzate** per non corrompere i file quando più thread scrivono contemporaneamente.

