```java
private static Response send(PrintWriter out, BufferedReader in, Request req) throws IOException {
    out.println(JsonUtil.toJson(req));
    String line = in.readLine();               // il server risponde con una riga JSON
    return JsonUtil.fromJson(line, Response.class);
}
