### 6.6 `UIPrinter`

```java
public class UIPrinter {

    public static void print(Response resp, ClientState state) {
        if (resp.getStatus() != 0) {
            System.out.println("Errore (" + resp.getStatus() + "): " + resp.getMessage());
            return;
        }

        switch (resp.getAction()) {
            case "register":
            case "login":
                System.out.println(resp.getMessage());
                if (resp.getAction().equals("login"))
                    state.login(((JsonObject)resp.getPayload()).get("username").getAsString());
                break;

            case "logout":
                System.out.println(resp.getMessage());
                state.logout();
                break;

            case "searchHotel":
                Hotel h = JsonUtil.fromJson(resp.getPayload().toString(), Hotel.class);
                System.out.println("Hotel trovato:");
                System.out.println(h);
                break;

            case "searchAllHotels":
                Type listType = new TypeToken<List<Hotel>>(){}.getType();
                List<Hotel> list = JsonUtil.fromJson(resp.getPayload().toString(), listType);
                System.out.println("Hotel nella città (" + list.size() + "):");
                list.forEach(System.out::println);
                break;

            case "insertReview":
                System.out.println(resp.getMessage());
                break;

            case "showMyBadges":
                System.out.println(resp.getMessage());
                break;

            default:
                System.out.println(resp.getMessage());
        }
    }
}
```

