```java
package sondage;

import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicIntegerArray;

/**
 * Modèle partagé du sondage.
 * Toutes les méthodes sont thread‑safe.
 */
public final class Sondage {

    /** Propositions (indexées à partir de 0). */
    private final List<String> propositions;

    /** Compteur de votes, un AtomicInteger par proposition. */
    private final AtomicIntegerArray votes;

    /**
     * Crée un sondage à partir d'une liste de propositions.
     *
     * @param propositions liste non‑null, non vide
     */
    public Sondage(List<String> propositions) {
        if (propositions == null || propositions.isEmpty())
            throw new IllegalArgumentException("la liste des propositions ne peut être vide");

        // Copie immuable pour éviter les modifications extérieures
        this.propositions = Collections.unmodifiableList(new ArrayList<>(propositions));
        this.votes = new AtomicIntegerArray(this.propositions.size());
    }

    /** @return copie immutable de la liste des propositions */
    public List<String> getCandidats() {
        return propositions;
    }

    /**
     * Enregistre un vote.
     *
     * @param n indice (1‑based) de la proposition demandée par le client
     * @return true si le vote a été comptabilisé, false si n est invalide
     */
    public boolean vote(int n) {
        // le protocole utilise 1‑based -> conversion en 0‑based
        int idx = n - 1;
        if (idx < 0 || idx >= votes.length())
            return false;
        votes.incrementAndGet(idx);
        return true;
    }

    /**
     * Retourne la proposition la plus votée.
     * En cas d’égalité, on renvoie la première rencontrée.
     *
     * @return texte de la proposition gagnante (ou null si aucune proposition)
     */
    public String getResultat() {
        int max = -1;
        int idxMax = -1;
        for (int i = 0; i < votes.length(); i++) {
            int cur = votes.get(i);
            if (cur > max) {
                max = cur;
                idxMax = i;
            }
        }
        return (idxMax >= 0) ? propositions.get(idxMax) : null;
    }

    /** Méthode de diagnostic (facultative) */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("Sondage {\n");
        for (int i = 0; i < propositions.size(); i++) {
            sb.append("  ").append(i + 1).append(". ")
              .append(propositions.get(i)).append(" -> ")
              .append(votes.get(i)).append(" votes\n");
        }
        sb.append('}');
        return sb.toString();
    }
}
```

