package sondage;

import java.io.*;
import java.net.*;
import java.util.List;
import java.util.concurrent.*;

/**
 * Serveur TCP multi‑clients qui expose le sondage.
 * Le port d’écoute est fourni en argument (ex. 5000).
 */
public class Serveur {

    private final int port;
    private final Sondage sondage;
    private final ExecutorService pool;

    public Serveur(int port, Sondage sondage) {
        this.port = port;
        this.sondage = sondage;
        // Un pool fixe de 10 threads (modifiable selon la charge attendue)
        this.pool = Executors.newFixedThreadPool(10);
    }

    /** Démarre le serveur et attend les connexions. */
    public void start() throws IOException {
        try (ServerSocket ss = new ServerSocket(port)) {
            System.out.println("Serveur sondage démarré sur le port " + port);
            while (!Thread.currentThread().isInterrupted()) {
                Socket client = ss.accept();               // Bloquant
                System.out.println("Nouvelle connexion depuis " + client.getRemoteSocketAddress());
                pool.submit(new Worker(client, sondage));
            }
        } finally {
            shutdown();
        }
    }

    /** Arrêt propre du thread‑pool. */
    public void shutdown() {
        pool.shutdownNow();
        System.out.println("Serveur arrêté.");
    }

    /** Thread de service dédié à un client. */
    private static class Worker implements Runnable {
        private final Socket socket;
        private final Sondage sondage;

        Worker(Socket socket, Sondage sondage) {
            this.socket = socket;
            this.sondage = sondage;
        }

        @Override
        public void run() {
            try (BufferedReader in = new BufferedReader(
                     new InputStreamReader(socket.getInputStream()));
                 PrintWriter out = new PrintWriter(
                     new BufferedWriter(
                     new OutputStreamWriter(socket.getOutputStream())), true)) {

                String line;
                while ((line = in.readLine()) != null) {
                    line = line.trim();
                    if (line.isEmpty())
                        continue;

                    String response = handleCommand(line);
                    out.println(response);
                    // Optionnel : sortir si le client envoie "quit"
                    if ("quit".equalsIgnoreCase(line))
                        break;
                }
            } catch (IOException e) {
                System.err.println("Erreur I/O avec le client " + socket.getRemoteSocketAddress()
                                   + " : " + e.getMessage());
            } finally {
                try { socket.close(); } catch (IOException ignored) {}
                System.out.println("Connexion terminée : " + socket.getRemoteSocketAddress());
            }
        }

        /** Interprète la ligne reçue et génère la réponse texte. */
        private String handleCommand(String cmd) {
            if (cmd.equalsIgnoreCase("candidats")) {
                List<String> cand = sondage.getCandidats();
                // On renvoie les candidats séparés par '#'
                return "CANDIDATS " + String.join("#", cand);
            }

            if (cmd.toLowerCase().startsWith("vote ")) {
                try {
                    int n = Integer.parseInt(cmd.substring(5).trim());
                    boolean ok = sondage.vote(n);
                    return ok ? "OK" : "ERR";
                } catch (NumberFormatException e) {
                    return "ERR";
                }
            }

            if (cmd.equalsIgnoreCase("resultat")) {
                String best = sondage.getResultat();
                return (best != null) ? "RESULTAT " + best : "RESULTAT (aucun vote)";
            }

            // Commande non reconnue
            return "UNKNOWN COMMAND";
        }
    }

    /** Point d’entrée (classe de test). */
    public static void main(String[] args) throws IOException {
        if (args.length < 1) {
            System.err.println("Usage : java Serveur <port>");
            System.exit(1);
        }
        int port = Integer.parseInt(args[0]);

        // Ex. de propositions
        List<String> propositions = List.of(
                "Pizza", "Sushi", "Hamburger", "Salade", "Tacos"
        );

        Sondage sondage = new Sondage(propositions);
        Serveur serveur = new Serveur(port, sondage);
        serveur.start();        // Bloque tant que le serveur tourne
    }
}
