/**
 * Client console simple.
 * Usage : java Client <host> <port>
 */
public class Client {

    private final String host;
    private final int port;

    public Client(String host, int port) {
        this.host = host;
        this.port = port;
    }

    public void run() {
        try (Socket socket = new Socket(host, port);
             BufferedReader in = new BufferedReader(
                     new InputStreamReader(socket.getInputStream()));
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(
                     new OutputStreamWriter(socket.getOutputStream())), true);
             Scanner stdin = new Scanner(System.in)) {

            System.out.println("Connecté au serveur de sondage " + host + ":" + port);
            System.out.println("Commandes : candidats | vote N | resultat | quit");

            while (true) {
                System.out.print("> ");
                String userCmd = stdin.nextLine().trim();
                if (userCmd.isEmpty())
                    continue;

                out.println(userCmd);                // Envoie au serveur
                String answer = in.readLine();        // Attente de la réponse
                if (answer == null) {
                    System.out.println("Serveur déconnecté.");
                    break;
                }

                System.out.println("< " + answer);

                if (userCmd.equalsIgnoreCase("quit")) {
                    System.out.println("Fin du client.");
                    break;
                }
            }
        } catch (IOException e) {
            System.err.println("Erreur de connexion : " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage : java Client <host> <port>");
            System.exit(1);
        }
        String host = args[0];
        int port = Integer.parseInt(args[1]);

        new Client(host, port).run();
    }
