import android.annotation.SuppressLint;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.security.GeneralSecurityException;
import java.security.SecureRandom;
import java.security.cert.CertificateException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import javax.net.SocketFactory;
import javax.net.ssl.HostnameVerifier;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLHandshakeException;
import javax.net.ssl.SSLParameters;
import javax.net.ssl.SSLSession;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;

/**
 * Simple, reusable TCP‑over‑TLS client for Android.
 *
 * <p>Features:
 * <ul>
 *   <li>Works on the UI thread – internally uses a single‑thread executor.</li>
 *   <li>Configurable timeout, hostname verification and custom trust manager.</li>
 *   <li>Callback interface for connection, data‑receive, error and close events.</li>
 *   <li>Optional “trust‑all” mode for development / self‑signed certificates.</li>
 * </ul>
 *
 * <p>Typical usage:
 *
 * <pre>{@code
 * SecureTcpClient client = new SecureTcpClient(
 *         "example.com", 443,
 *         new SecureTcpClient.Callback() {
 *             @Override public void onConnected() { Log.d(TAG, "connected"); }
 *             @Override public void onDataReceived(byte[] data, int len) { … }
 *             @Override public void onError(Throwable t) { … }
 *             @Override public void onDisconnected() { … }
 *         });
 *
 * // If you need to accept a self‑signed cert:
 * client.setTrustAllCertificates(true);
 *
 * client.connect();          // non‑blocking, callbacks run on main thread
 * client.send("Hello".getBytes(StandardCharsets.UTF_8));
 * }</pre>
 */
public final class SecureTcpClient {

    private static final String TAG = "SecureTcpClient";

    /** Default socket timeout (ms). */
    private static final int DEFAULT_TIMEOUT_MS = 15_000;

    /** Default TCP receive buffer size. */
    private static final int DEFAULT_READ_BUFFER_SIZE = 4 * 1024; // 4 KB

    /** The server host name (or IP) and port. */
    private final String host;
    private final int port;

    /** Listener for all events – must be set before {@link #connect()}. */
    private final Callback callback;

    /** Optional custom trust manager (null = platform default). */
    private X509TrustManager customTrustManager = null;

    /** Whether hostname verification should be performed (default = true). */
    private boolean verifyHostname = true;

    /** If true we accept every certificate (useful for dev only). */
    private boolean trustAllCertificates = false;

    /** Connection timeout (ms). */
    private int timeoutMs = DEFAULT_TIMEOUT_MS;

    /** Internal resources – single‑threaded executor guarantees order. */
    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    /** A handler that posts callbacks on the main (UI) thread. */
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    /** The underlying socket (null until connected). */
    private volatile SSLSocket socket;

    /** I/O streams – cached after the socket is created. */
    private volatile InputStream in;
    private volatile OutputStream out;

    /** Flag that tells the read‑loop to stop. */
    private volatile boolean keepReading = false;

    // -------------------------------------------------------------------------
    // Construction & configuration
    // -------------------------------------------------------------------------

    /**
     * Creates a client instance.
     *
     * @param host     remote host name or IP address.
     * @param port     remote TLS port.
     * @param callback callbacks. Must be non‑null.
     */
    public SecureTcpClient(String host, int port, Callback callback) {
        if (host == null || host.isEmpty())
            throw new IllegalArgumentException("host must not be null/empty");
        if (port <= 0 || port > 65535)
            throw new IllegalArgumentException("invalid port: " + port);
        if (callback == null)
            throw new IllegalArgumentException("callback must not be null");

        this.host = host;
        this.port = port;
        this.callback = callback;
    }

    /** Sets a custom X509TrustManager (e.g. a pinned‑certificate trust manager). */
    public SecureTcpClient setCustomTrustManager(X509TrustManager trustManager) {
        this.customTrustManager = trustManager;
        return this;
    }

    /** Enables/disables hostname verification. Default = true (recommended). */
    public SecureTcpClient setVerifyHostname(boolean verify) {
        this.verifyHostname = verify;
        return this;
    }

    /** Enables “trust‑all” mode – accepts every server cert (dangerous!). */
    public SecureTcpClient setTrustAllCertificates(boolean trustAll) {
        this.trustAllCertificates = trustAll;
        return this;
    }

    /** Overrides the default connection timeout (ms). */
    public SecureTcpClient setTimeoutMs(int timeoutMs) {
        if (timeoutMs <= 0) throw new IllegalArgumentException("timeout must be >0");
        this.timeoutMs = timeoutMs;
        return this;
    }

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /**
     * Connects to the remote host. The call returns immediately; all heavy work is
     * performed off the UI thread and the result is delivered via {@link Callback#onConnected()}
     * or {@link Callback#onError(Throwable)}.
     */
    public void connect() {
        executor.execute(() -> {
            try {
                // 1️⃣ Build the SSL socket factory
                SSLSocketFactory factory = createSslSocketFactory();

                // 2️⃣ Open a plain TCP socket and set timeouts
                Socket rawSocket = new Socket();
                rawSocket.connect(new InetSocketAddress(host, port), timeoutMs);
                rawSocket.setSoTimeout(timeoutMs);
                rawSocket.setTcpNoDelay(true);

                // 3️⃣ Wrap it in SSL
                socket = (SSLSocket) factory.createSocket(
                        rawSocket,
                        host,
                        port,
                        true); // autoClose the underlying raw socket when SSL socket closes

                // 4️⃣ Enforce TLS‑v1.2+ & optional hostname verification
                SSLParameters sslParams = socket.getSSLParameters();
                sslParams.setEndpointIdentificationAlgorithm(
                        verifyHostname ? "HTTPS" : null        // null = skip verification
                );
                socket.setSSLParameters(sslParams);

                // 5️⃣ Start handshake (this also validates the certificate)
                socket.startHandshake();

                // 6️⃣ Obtain streams
                in = socket.getInputStream();
                out = socket.getOutputStream();

                // 7️⃣ Signal successful connection
                postToMain(() -> callback.onConnected());

                // 8️⃣ Start the read loop
                keepReading = true;
                readLoop();

            } catch (Throwable e) {
                // Anything that went wrong during the connect process
                safeCloseQuietly();
                postToMain(() -> callback.onError(e));
            }
        });
    }

    /**
     * Sends data to the remote server. This method is thread‑safe; you can call it
     * from any thread (including the UI thread). Errors are reported via {@link Callback#onError(Throwable)}.
     *
     * @param data the byte array to send (must not be null)
     */
    public void send(final byte[] data) {
        if (data == null) throw new IllegalArgumentException("data must not be null");
        executor.execute(() -> {
            try {
                OutputStream os = out;
                if (os == null) throw new IOException("socket not connected");
                os.write(data);
                os.flush();
            } catch (Throwable e) {
                postToMain(() -> callback.onError(e));
                // Not a fatal error – just report it; the read‑loop still runs.
            }
        });
    }

    /**
     * Gracefully disconnects from the server. After the call the client can be
     * re‑used by invoking {@link #connect()} again.
     */
    public void disconnect() {
        executor.execute(() -> {
            keepReading = false;
            safeCloseQuietly();
            postToMain(() -> callback.onDisconnected());
        });
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    /** Creates an {@link SSLSocketFactory} according to the current configuration. */
    private SSLSocketFactory createSslSocketFactory() throws GeneralSecurityException {
        if (trustAllCertificates) {
            // ***** Development only – accepts any cert *****
            TrustManager[] trustAll = new TrustManager[]{new X509TrustManager() {
                @Override public java.security.cert.X509Certificate[] getAcceptedIssuers() { return new java.security.cert.X509Certificate[0]; }
                @Override public void checkClientTrusted(java.security.cert.X509Certificate[] chain, String authType) throws CertificateException { }
                @Override public void checkServerTrusted(java.security.cert.X509Certificate[] chain, String authType) throws CertificateException { }
            }};
            SSLContext ctx = SSLContext.getInstance("TLS");
            ctx.init(null, trustAll, new SecureRandom());
            return ctx.getSocketFactory();
        }

        // Normal mode – either platform default or a custom trust manager
        TrustManager[] trustManagers;
        if (customTrustManager != null) {
            trustManagers = new TrustManager[]{customTrustManager};
        } else {
            // Use default system TrustManager (validates against device keystore)
            trustManagers = null; // passing null -> uses default
        }

        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(null, trustManagers, new SecureRandom());
        return ctx.getSocketFactory();
    }

    /** Continuous read loop – runs on the background executor. */
    private void readLoop() {
        byte[] buffer = new byte[DEFAULT_READ_BUFFER_SIZE];
        while (keepReading && socket != null && !socket.isClosed()) {
            try {
                int read = in.read(buffer);
                if (read == -1) {
                    // End‑of‑stream – remote closed connection
                    break;
                }
                // Defensive copy because the buffer will be re‑used
                final byte[] data = new byte[read];
                System.arraycopy(buffer, 0, data, 0, read);
                postToMain(() -> callback.onDataReceived(data, read));
            } catch (IOException e) {
                // Something went wrong while reading – report and exit loop
                postToMain(() -> callback.onError(e));
                break;
            }
        }
        // Normal termination (remote closed) or error; clean up
        keepReading = false;
        safeCloseQuietly();
        postToMain(() -> callback.onDisconnected());
    }

    /** Closes the socket/streams without throwing. */
    private void safeCloseQuietly() {
        try {
            if (in != null) in.close();
        } catch (Exception ignored) { }
        try {
            if (out != null) out.close();
        } catch (Exception ignored) { }
        try {
            if (socket != null) socket.close();
        } catch (Exception ignored) { }
        in = null;
        out = null;
        socket = null;
    }

    /** Utility – posts a Runnable on the main (UI) thread. */
    private void postToMain(Runnable r) {
        if (Looper.myLooper() == Looper.getMainLooper()) {
            r.run();
        } else {
            mainHandler.post(r);
        }
    }

    // -------------------------------------------------------------------------
    // Callback interface
    // -------------------------------------------------------------------------

    /** All communication with the client is performed via this listener. */
    public interface Callback {
        /** Called once the TLS handshake completed successfully. */
        void onConnected();

        /**
         * Called each time a block of data arrives from the server.
         *
         * @param data the exact bytes received (length == len)
         * @param len  number of valid bytes in {@code data}
         */
        void onDataReceived(byte[] data, int len);

        /** Called when the connection is closed (either by you or by the remote side). */
        void onDisconnected();

        /** Called for any error that occurs during connect, send, or receive. */
        void onError(Throwable t);
    }
}
