public static SSLSocket createBlockingSslSocket(String host, int port) throws Exception {
    SSLContext ctx = SSLContext.getInstance("TLS");
    ctx.init(null, null, new SecureRandom());   // default trust manager
    SSLSocketFactory factory = ctx.getSocketFactory();

    SSLSocket socket = (SSLSocket) factory.createSocket(host, port);
    socket.setEnabledProtocols(new String[]{"TLSv1.2", "TLSv1.3"});
    socket.startHandshake();   // throws if cert validation fails
    return socket;
}
