package repository;

import java.util.List;
import java.util.Optional;
import java.util.function.Predicate;

/**
 * Generic repository interface.
 *
 * @param <T> the type of stored objects
 */
public interface Repository<T> {

    /** Store a new element; returns false if an element with the same key already exists. */
    boolean add(T element);

    /** Remove an element that matches the supplied predicate. Returns true if something was removed. */
    boolean remove(Predicate<T> filter);

    /** Update an existing element. Returns true if the element existed and was replaced. */
    boolean update(T element, Predicate<T> matcher);

    /** Find a single element that matches the predicate; Optional.empty() if none. */
    Optional<T> find(Predicate<T> filter);

    /** Find all elements that match the predicate. */
    List<T> findAll(Predicate<T> filter);

    /** Return a shallow copy of all stored elements. */
    List<T> findAll();

    /** Return total number of stored elements. */
    long count();
}
