### 2.3 `repository/StudentRepository.java`

```java
package repository;

import model.Student;

import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Concrete repository for Student objects.
 *
 * Internally it keeps:
 *   - a Map<Integer,Student> for O(1) look‑ups by ID
 *   - a List<Student> to preserve insertion order (useful for reporting)
 *
 * Both collections are kept in sync.
 */
public class StudentRepository implements Repository<Student> {

    private final Map<Integer, Student>   byId   = new HashMap<>();
    private final List<Student>           all    = new ArrayList<>();

    @Override
    public boolean add(Student s) {
        Objects.requireNonNull(s, "Student cannot be null");
        if (byId.containsKey(s.getId())) {
            return false; // duplicate ID
        }
        byId.put(s.getId(), s);
        all.add(s);
        return true;
    }

    @Override
    public boolean remove(Predicate<Student> filter) {
        Objects.requireNonNull(filter);
        // Find the first matching element
        Optional<Student> opt = all.stream().filter(filter).findFirst();
        if (opt.isEmpty()) {
            return false;
        }
        Student s = opt.get();
        byId.remove(s.getId());
        all.remove(s);
        return true;
    }

    @Override
    public boolean update(Student newStudent, Predicate<Student> matcher) {
        Objects.requireNonNull(newStudent);
        Objects.requireNonNull(matcher);
        for (int i = 0; i < all.size(); i++) {
            Student current = all.get(i);
            if (matcher.test(current)) {
                // If the ID is changed, we must keep the map consistent
                if (!current.getId().equals(newStudent.getId())) {
                    // New ID must not already exist
                    if (byId.containsKey(newStudent.getId())) {
                        return false; // conflict
                    }
                    byId.remove(current.getId());
                }
                byId.put(newStudent.getId(), newStudent);
                all.set(i, newStudent);
                return true;
            }
        }
        return false;
    }

    @Override
    public Optional<Student> find(Predicate<Student> filter) {
        Objects.requireNonNull(filter);
        return all.stream().filter(filter).findFirst();
    }

    @Override
    public List<Student> findAll(Predicate<Student> filter) {
        Objects.requireNonNull(filter);
        return all.stream().filter(filter).collect(Collectors.toList());
    }

    @Override
    public List<Student> findAll() {
        return new ArrayList<>(all);
    }

    @Override
    public long count() {
        return all.size();
    }
}
```

### 2.4 `service/StudentService.java`

```java
package service;

import model.Student;
import repository.StudentRepository;

import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Business‑logic layer. Keeps UI code clean.
 */
public class StudentService {

    private final StudentRepository repo = new StudentRepository();

    // ---------- CRUD ----------
    public boolean addStudent(Student s) {
        return repo.add(s);
    }

    public boolean removeStudentById(Integer id) {
        return repo.remove(st -> st.getId().equals(id));
    }

    public boolean updateStudent(Student updated) {
        // matcher = same ID (the record we want to replace)
        return repo.update(updated, st -> st.getId().equals(updated.getId()));
    }

    // ---------- Search ----------
    public Optional<Student> findById(Integer id) {
        return repo.find(st -> st.getId().equals(id));
    }

    public List<Student> findByName(String namePart) {
        String lower = namePart.toLowerCase();
        return repo.findAll(st -> st.getName().toLowerCase().contains(lower));
    }

    // ---------- Reporting ----------
    public List<Student> listAllStudentsSortedByName() {
        List<Student> copy = repo.findAll();
        Collections.sort(copy);   // uses Student.compareTo()
        return copy;
    }

    public long totalStudents() {
        return repo.count();
    }

    public double averageGPA() {
        return repo.findAll().stream()
                .mapToDouble(Student::getGpa)
                .average()
                .orElse(0.0);
    }

    public Map<String, Long> gradeDistribution() {
        // e.g., "A" = GPA >= 3.5, "B" = 3.0–3.49, etc.
        return repo.findAll().stream()
                .collect(Collectors.groupingBy(this::gradeLetter,
                        Collectors.counting()));
    }

    private String gradeLetter(Student s) {
        double gpa = s.getGpa();
        if (gpa >= 3.5) return "A";
        if (gpa >= 3.0) return "B";
        if (gpa >= 2.5) return "C";
        if (gpa >= 2.0) return "D";
        return "F";
    }
}
