        public Integer getId() { return id; }
        public String getName() { return name; }
        public void setName(String n) { this.name = Objects.requireNonNull(n); }
        public int getAge() { return age; }
        public void setAge(int a) { this.age = a; }
        public double getGpa() { return gpa; }
        public void setGpa(double g) { this.gpa = g; }

        @Override public boolean equals(Object o) {
            return (o instanceof Student) && id.equals(((Student) o).id);
        }
        @Override public int hashCode() { return Objects.hash(id); }
        @Override public int compareTo(Student o) {
            int cmp = name.compareToIgnoreCase(o.name);
            return (cmp != 0) ? cmp : id.compareTo(o.id);
        }
        @Override public String toString() {
            return String.format("Student{id=%d, name='%s', age=%d, GPA=%.2f}",
                    id, name, age, gpa);
        }
    }

    /* ------------------------ Generic Repository ------------------------ */
    public interface Repository<T> {
        boolean add(T element);
        boolean remove(Predicate<T> filter);
        boolean update(T element, Predicate<T> matcher);
        Optional<T> find(Predicate<T> filter);
        List<T> findAll(Predicate<T> filter);
        List<T> findAll();
        long count();
    }

    /* ------------------------ Student Repository ------------------------ */
    public static class StudentRepository implements Repository<Student> {
        private final Map<Integer, Student> byId = new HashMap<>();
        private final List<Student> all = new ArrayList<>();

        @Override public boolean add(Student s) {
            if (byId.containsKey(s.getId())) return false;
            byId.put(s.getId(), s);
            all.add(s);
            return true;
        }
        @Override public boolean remove(Predicate<Student> f) {
            Optional<Student> o = all.stream().filter(f).findFirst();
            if (o.isEmpty()) return false;
            Student s = o.get();
            byId.remove(s.getId());
            all.remove(s);
            return true;
        }
        @Override public boolean update(Student newS, Predicate<Student> matcher) {
            for (int i = 0; i < all.size(); i++) {
                Student cur = all.get(i);
                if (matcher.test(cur)) {
                    if (!cur.getId().equals(newS.getId())) {
                        if (byId.containsKey(newS.getId())) return false;
                        byId.remove(cur.getId());
                    }
                    byId.put(newS.getId(), newS);
                    all.set(i, newS);
                    return true;
                }
            }
            return false;
        }
        @Override public Optional<Student> find(Predicate<Student> f) {
            return all.stream().filter(f).findFirst();
        }
        @Override public List<Student> findAll(Predicate<Student> f) {
            return all.stream().filter(f).collect(Collectors.toList());
        }
        @Override public List<Student> findAll() {
            return new ArrayList<>(all);
        }
        @Override public long count() { return all.size(); }
    }

    /* ------------------------ Service Layer ------------------------ */
    public static class StudentService {
        private final StudentRepository repo = new StudentRepository();

        public boolean addStudent(Student s) { return repo.add(s); }
        public boolean removeStudentById(Integer id) { return repo.remove(st -> st.getId().equals(id)); }
        public boolean updateStudent(Student s) { return repo.update(s, st -> st.getId().equals(s.getId())); }

        public Optional<Student> findById(Integer id) { return repo.find(st -> st.getId().equals(id)); }
        public List<Student> findByName(String part) {
            String lower = part.toLowerCase();
            return repo.findAll(st -> st.getName().toLowerCase().contains(lower));
        }

        public List<Student> listAllSorted() {
            List<Student> copy = repo.findAll();
            Collections.sort(copy);
            return copy;
        }
        public long totalStudents() { return repo.count(); }
        public double averageGPA() {
            return repo.findAll().stream()
                    .mapToDouble(Student::getGpa)
                    .average()
                    .orElse(0);
        }
        public Map<String, Long> gradeDistribution() {
            return repo.findAll().stream()
                    .collect(Collectors.groupingBy(this::gradeLetter, Collectors.counting()));
        }
        private String gradeLetter(Student s) {
            double g = s.getGpa();
            if (g >= 3.5) return "A";
            if (g >= 3.0) return "B";
            if (g >= 2.5) return "C";
            if (g >= 2.0) return "D";
            return "F";
        }
    }

    /* ------------------------ UI (Console) ------------------------ */
    public static void main(String[] args) {
        StudentService service = new StudentService();
        Scanner sc = new Scanner(System.in);
        boolean quit = false;

        while (!quit) {
            System.out.println("\n===== MENU =====");
            System.out.println("1) Add student");
            System.out.println("2) Remove student (by ID)");
            System.out.println("3) Update student");
            System.out.println("4) Search by ID");
            System.out.println("5) Search by name");
            System.out.println("6) Report");
            System.out.println("0) Quit");
            System.out.print("Choice? ");

            int ch = readInt(sc);
            switch (ch) {
                case 1 -> addStudent(sc, service);
                case 2 -> removeStudent(sc, service);
                case 3 -> updateStudent(sc, service);
                case 4 -> searchById(sc, service);
                case 5 -> searchByName(sc, service);
                case 6 -> printReport(service);
                case 0 -> quit = true;
                default -> System.out.println("Invalid option.");
            }
        }
        System.out.println("Bye!");
        sc.close();
    }

    /* ---------- helper input methods ---------- */
    private static int readInt(Scanner sc) {
        while (true) {
            try { return Integer.parseInt(sc.nextLine().trim()); }
            catch (NumberFormatException e) { System.out.print("Enter an integer: "); }
        }
    }

    private static double readDouble(Scanner sc, double min, double max) {
        while (true) {
            try {
                double d = Double.parseDouble(sc.nextLine().trim());
                if (d < min || d > max) {
                    System.out.printf("Value must be between %.2f and %.2f: ", min, max);
                } else { return d; }
            } catch (NumberFormatException e) {
                System.out.print("Enter a valid number: ");
            }
        }
    }

    private static String readNonEmpty(Scanner sc, String prompt) {
        System.out.print(prompt);
        while (true) {
            String line = sc.nextLine().trim();
            if (!line.isEmpty()) return line;
            System.out.print("Input cannot be empty – try again: ");
        }
    }

    /* ---------- UI actions ---------- */
    private static void addStudent(Scanner sc, StudentService svc) {
        System.out.println("\n--- Add Student ---");
        int id   = readInt(sc);
        String name = readNonEmpty(sc, "Name: ");
        int age   = readInt(sc);
        double gpa = readDouble(sc, 0.0, 4.0);
        Student s = new Student(id, name, age, gpa);
        System.out.println(svc.addStudent(s) ? "Added." : "ID already exists.");
    }

    private static void removeStudent(Scanner sc, StudentService svc) {
        System.out.println("\n--- Remove Student ---");
        int id = readInt(sc);
        System.out.println(svc.removeStudentById(id) ? "Removed." : "Not found.");
    }

    private static void updateStudent(Scanner sc, StudentService svc) {
        System.out.println("\n--- Update Student ---");
        int id = readInt(sc);
        Optional<Student> opt = svc.findById(id);
        if (opt.isEmpty()) {
            System.out.println("Student not found.");
            return;
        }
        Student cur = opt.get();
        System.out.println("Current: " + cur);
        String name = readNonEmpty(sc, "New name (or press ENTER to keep): ");
        System.out.print("New age (or -1 to keep): ");
        int age = readInt(sc);
        System.out.print("New GPA (or -1 to keep): ");
        double gpa = readDouble(sc, -1, 4.0);

        Student upd = new Student(
                id,
                name.isEmpty() ? cur.getName() : name,
                age < 0 ? cur.getAge() : age,
                gpa < 0 ? cur.getGpa() : gpa);
        System.out.println(svc.updateStudent(upd) ? "Updated." : "Update failed.");
    }

    private static void searchById(Scanner sc, StudentService svc) {
        System.out.println("\n--- Search By ID ---");
        int id = readInt(sc);
        svc.findById(id).ifPresentOrElse(
                s -> System.out.println("Found: " + s),
                () -> System.out.println("No student with that ID."));
    }

    private static void searchByName(Scanner sc, StudentService svc) {
        System.out.println("\n--- Search By Name ---");
        String part = readNonEmpty(sc, "Enter part of name: ");
        List<Student> matches = svc.findByName(part);
        if (matches.isEmpty()) System.out.println("No matches.");
        else matches.forEach(System.out::println);
    }

    private static void printReport(StudentService svc) {
        System.out.println("\n--- Report ---");
        System.out.printf("Total students : %d%n", svc.totalStudents());
        System.out.printf("Average GPA    : %.2f%n", svc.averageGPA());

        System.out.println("\nGrade distribution:");
        svc.gradeDistribution().forEach((g, cnt) -> System.out.printf("%s : %d%n", g, cnt));

        System.out.println("\nAll students (sorted by name):");
        svc.listAllSorted().forEach(System.out::println);
    }
}
