 */
public class AgentUI {

    private JFrame frame;
    private JTabbedPane tabbedPane;               // 每个用户一个标签页
    /** key：userId，value：对应的聊天面板 */
    private Map<String, ChatPanel> sessions = new HashMap<>();

    public AgentUI() {
        initUI();
    }

    private void initUI() {
        frame = new JFrame("电商客服系统 - 客服端");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(800, 600);
        frame.setLocationRelativeTo(null);

        tabbedPane = new JTabbedPane();
        frame.getContentPane().add(tabbedPane, BorderLayout.CENTER);
    }

    /** 展示 UI（在主线程中调用） */
    public void show() {
        SwingUtilities.invokeLater(() -> frame.setVisible(true));
    }

    public JFrame getFrame() { return frame; }

    /**
     * 当有新用户（userId）接入时，创建对应的标签页并返回面板对象。
     */
    public synchronized ChatPanel createSession(String userId) {
        if (sessions.containsKey(userId)) return sessions.get(userId);
        ChatPanel panel = new ChatPanel(userId);
        sessions.put(userId, panel);
        tabbedPane.addTab(userId, panel);
        return panel;
    }

    /**
     * 在对应的标签页中显示收到的消息（来自用户或本地发送）。
     */
    public void showMessage(String userId, Message msg) {
        SwingUtilities.invokeLater(() -> {
            ChatPanel p = sessions.computeIfAbsent(userId, this::createSession);
            p.appendMessage(msg);
        });
    }

    /* ---------- 内部类：每个会话的聊天面板 ---------- */
    class ChatPanel extends JPanel {

        private final String userId;
        private JTextArea chatArea;
        private JTextField inputField;
        private JButton sendBtn, imgBtn, fileBtn;
        private ObjectOutputStream out; // 该会话对应的输出流

        public ChatPanel(String userId) {
            this.userId = userId;
            initComponents();
        }

        /** 把该面板的 out 设置为对应的 SessionHandler 中的 out（在 SessionHandler 创建后回调） */
        public void setOutputStream(ObjectOutputStream out) {
            this.out = out;
        }

        private void initComponents() {
            setLayout(new BorderLayout(5,5));
            setBorder(new EmptyBorder(5,5,5,5));

            chatArea = new JTextArea();
            chatArea.setEditable(false);
            chatArea.setLineWrap(true);
            JScrollPane scroll = new JScrollPane(chatArea);
            add(scroll, BorderLayout.CENTER);

            JPanel bottom = new JPanel(new BorderLayout(5,5));
            inputField = new JTextField();
            bottom.add(inputField, BorderLayout.CENTER);

            sendBtn = new JButton("发送");
            imgBtn = new JButton("图片");
            fileBtn = new JButton("文件");
            JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
            btnPanel.add(imgBtn);
            btnPanel.add(fileBtn);
            btnPanel.add(sendBtn);
            bottom.add(btnPanel, BorderLayout.EAST);
            add(bottom, BorderLayout.SOUTH);

            // ---------- 事件 ----------
            sendBtn.addActionListener(e -> sendText());
            inputField.addActionListener(e -> sendText());

            imgBtn.addActionListener(e -> sendFile(MessageType.IMAGE));
            fileBtn.addActionListener(e -> sendFile(MessageType.FILE));
        }

        /** 将 Message 对象追加到聊天框（本地） */
        public void appendMessage(Message msg) {
            chatArea.append(formatMessage(msg) + "\n");
            chatArea.setCaretPosition(chatArea.getDocument().getLength());

            // 如果是图片或文件，自动保存到本地（已在 ChatHistory.append 里完成），
            // 并在 UI 中提供一个 “打开” 链接（略）——这里仅演示文字提示
        }

        private String formatMessage(Message msg) {
            String prefix = msg.getFrom().equals("USER") ? "您: " : "客服: ";
            switch (msg.getType()) {
                case TEXT:   return prefix + msg.getText();
                case IMAGE:  return prefix + "[图片] " + msg.getFileName();
                case FILE:   return prefix + "[文件] " + msg.getFileName();
                case COMMAND:return prefix + "[系统] " + msg.getText();
                default:     return prefix + "[未知]";
            }
        }

        /** 发送文字 */
        private void sendText() {
            String txt = inputField.getText().trim();
            if (txt.isEmpty() || out == null) return;
            try {
                Message m = new Message(MessageType.TEXT, txt, "AGENT");
                out.writeObject(m);
                out.flush();
                ChatHistory.append(m); // 本地保存
                appendMessage(m);      // 本地显示
                inputField.setText("");
            } catch (Exception ex) {
                showError("发送文字失败：" + ex.getMessage());
            }
        }

        /** 发送图片或文件 */
        private void sendFile(MessageType type) {
            if (out == null) return;
            JFileChooser chooser = new JFileChooser();
            chooser.setFileSelectionMode(type == MessageType.IMAGE ?
                    JFileChooser.FILES_ONLY : JFileChooser.FILES_ONLY);
            int ret = chooser.showOpenDialog(frame);
            if (ret != JFileChooser.APPROVE_OPTION) return;
            File file = chooser.getSelectedFile();
            try {
                byte[] data = java.nio.file.Files.readAllBytes(file.toPath());
                Message m = new Message(type, data, file.getName(), "AGENT");
                out.writeObject(m);
                out.flush();
                ChatHistory.append(m);
                appendMessage(m);
            } catch (Exception ex) {
                showError("发送文件失败：" + ex.getMessage());
            }
        }

        private void showError(String msg) {
            JOptionPane.showMessageDialog(frame, msg, "错误", JOptionPane.ERROR_MESSAGE);
        }
    }
}
