## 6. Client（用户端入口）

```java
package com.ecom.chat;

import java.io.*;
import java.net.*;
import java.util.concurrent.*;

import javax.swing.*;

public class Client {

    private static final String SERVER_HOST = "127.0.0.1";
    private static final int SERVER_PORT = 8888;
    private Socket socket;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private UserUI ui;
    private String userId; // 本例中使用本机 IP+端口做唯一标识

    public Client() {
        ui = new UserUI(this);
    }

    /** 启动客户端（连接服务器） */
    public void start() {
        ui.show();

        // 1) 异步建立连接，防止 UI 卡死
        CompletableFuture.runAsync(() -> {
            try {
                socket = new Socket();
                socket.connect(new InetSocketAddress(SERVER_HOST, SERVER_PORT), 5000);
                out = new ObjectOutputStream(socket.getOutputStream());
                out.flush();
                in = new ObjectInputStream(socket.getInputStream());

                userId = socket.getLocalAddress().toString().replaceAll("[/:]", "_");

                // 2) 等待服务器的接单/忙碌指令（10 秒超时）
                ScheduledExecutorService timer = Executors.newSingleThreadScheduledExecutor();
                CompletableFuture<Message> cmdFuture = new CompletableFuture<>();

                // 计时器：10 秒后如果还未收到指令，则视为“忙碌”
                timer.schedule(() -> {
                    if (!cmdFuture.isDone()) {
                        cmdFuture.complete(new Message(MessageType.COMMAND, "AGENT_BUSY", "AGENT"));
                    }
                }, 10, TimeUnit.SECONDS);

                // 单独线程读取第一条消息（指令或历史记录）
                new Thread(() -> {
                    try {
                        Message first = (Message) in.readObject();
                        cmdFuture.complete(first);
                    } catch (Exception e) {
                        cmdFuture.completeExceptionally(e);
                    }
                }).start();

                // 等待指令
                Message cmd = cmdFuture.get();

                if (cmd.getType() == MessageType.COMMAND && "AGENT_BUSY".equals(cmd.getText())) {
                    ui.showBusy();
                    close();
                    return;
                } else if (cmd.getType() == MessageType.COMMAND && "AGENT_ACCEPT".equals(cmd.getText())) {
                    ui.appendSystemMsg("已成功接入客服，开始聊天……");
                } else {
                    // 服务器直接发送历史记录（这里是一条 TEXT 消息）
                    ui.appendMessage(cmd);
                }

                // 3) 开启后台线程持续读取后续消息
                new Thread(this::receiveLoop).start();

            } catch (Exception e) {
                e.printStackTrace();
                ui.appendSystemMsg("连接失败：" + e.getMessage());
            }
        });
    }

    /** 持续读取来自服务器的消息 */
    private void receiveLoop() {
        try {
            while (true) {
                Message msg = (Message) in.readObject();
                if (msg == null) break;
                // 保存到本地历史
                ChatHistory.append(msg);
                // UI 展示
                ui.appendMessage(msg);
            }
        } catch (EOFException eof) {
            ui.appendSystemMsg("客服已下线");
        } catch (Exception e) {
            e.printStackTrace();
            ui.appendSystemMsg("读取异常: " + e.getMessage());
        } finally {
            close();
        }
    }

    /** 发送文字 */
    public void sendText(String txt) {
        if (out == null) return;
        try {
            Message m = new Message(MessageType.TEXT, txt, "USER");
            out.writeObject(m);
            out.flush();
            ChatHistory.append(m);
        } catch (Exception e) {
            ui.appendSystemMsg("发送失败：" + e.getMessage());
        }
    }

    /** 发送图片或文件 */
    public void sendFile(MessageType type, File file) {
        if (out == null) return;
        try {
            byte[] data = java.nio.file.Files.readAllBytes(file.toPath());
            Message m = new Message(type, data, file.getName(), "USER");
            out.writeObject(m);
            out.flush();
            ChatHistory.append(m);
        } catch (Exception e) {
            ui.appendSystemMsg("发送失败：" + e.getMessage());
        }
    }

    /** 关闭所有资源 */
    private void close() {
        try { if (in != null) in.close(); } catch (Exception ignored) {}
        try { if (out != null) out.close(); } catch (Exception ignored) {}
        try { if (socket != null && !socket.isClosed()) socket.close(); } catch (Exception ignored) {}
    }

    /** 程序入口 */
    public static void main(String[] args) {
        new Client().start();
    }
}
```

*说明*  

- 客户端首先 **异步** 连接服务器，随后等待服务器的指令（`AGENT_ACCEPT` 或 `AGENT_BUSY`），若 **10 秒** 没收到指令则视为忙碌并在 UI 中显示 “客服忙”。  
- 接收到 **历史记录**（服务器在接单成功后会一次性发送），随后进入 **持续读取** 循环，把每条消息写入本地 `ChatHistory` 并交给 UI。  
- `sendText` / `sendFile` 方法直接把 `Message` 写入 `ObjectOutputStream`，并同步保存本地历史。  

