## 3. Server Implementation (EncyclopediaImpl.java)

```java
package rmi;

import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

/**
 * Implements the remote methods.
 *
 * The class creates a random 300‑word text once (in the constructor) and
 * re‑uses it for every client call – this mimics an “encyclopedia”.
 *
 * Two flavours are offered:
 *   • non‑threaded – everything runs sequentially.
 *   • threaded    – each analysis runs in its own Callable.
 */
public class EncyclopediaImpl extends UnicastRemoteObject implements Encyclopedia {

    private static final long serialVersionUID = 1L;

    /** The 300‑word encyclopedia – a single string with spaces between words. */
    private final String encyclopediaText;

    /** Cached list of the 300 words (splitting the string once). */
    private final List<String> words;

    /** Random word generator constants. */
    private static final String[] WORD_BANK = {
            "cat","dog","tree","house","river","mountain","computer","java","thread",
            "socket","cloud","star","planet","galaxy","mouse","keyboard","phone",
            "window","door","garden","flower","bird","fish","lion","tiger","bear",
            "snake","frog","apple","banana","orange","grape","peach","lemon","cherry",
            "book","paper","pen","pencil","eraser","chair","table","lamp","candle",
            "clock","watch","phone","camera","guitar","piano","drum","violin","song",
            "music","movie","theater","city","village","road","bridge","airport",
            "station", "train", "bus", "car", "bike", "boat", "ship", "plane", "rocket",
            "robot", "engine", "fuel", "oil", "water", "fire", "earth", "wind", "rain",
            "snow", "cloud", "storm", "space", "sun", "moon", "star", "galaxy", "universe"
    };
    private static final Random RAND = new Random();

    /** -------------------------------------------------------
     *  Constructor – creates a random 300‑word sentence.
     *  ------------------------------------------------------- */
    protected EncyclopediaImpl() throws RemoteException {
        super();
        this.encyclopediaText = generateRandomText(300);
        this.words = Arrays.asList(encyclopediaText.split("\\s+"));
    }

    /** -------------------------------------------------------
     *  Remote method implementations (just delegate to local helpers)
     *  ------------------------------------------------------- */
    @Override
    public int Count() {
        // spaces are already present in the original string
        return encyclopediaText.length();
    }

    @Override
    public List<String> repeatedwords() {
        return findRepeated(words);
    }

    @Override
    public String longest() {
        return words.stream()
                .max(Comparator.comparingInt(String::length))
                .orElse("");
    }

    @Override
    public String shortest() {
        return words.stream()
                .min(Comparator.comparingInt(String::length))
                .orElse("");
    }

    @Override
    public Map<String,Integer> Repeat() {
        return countOccurrences(words);
    }

    /** -------------------------------------------------------
     *  The two wrapper methods used by the client GUI.
     *  ------------------------------------------------------- */
    @Override
    public ResultWrapper runNonThreaded() throws RemoteException {
        long start = System.nanoTime();

        int      count      = Count();
        List<String> repeated = repeatedwords();
        String   longest    = longest();
        String   shortest   = shortest();
        Map<String,Integer> repeatMap = Repeat();

        long elapsed = (System.nanoTime() - start) / 1_000_000L;
        return new ResultWrapper("Non‑threaded", elapsed,
                count, repeated, longest, shortest, repeatMap);
    }

    @Override
    public ResultWrapper runThreaded() throws RemoteException {
        long start = System.nanoTime();

        // 5 independent tasks → one Callable per analysis
        ExecutorService exec = Executors.newFixedThreadPool(5);
        try {
            List<Callable<Object>> tasks = new ArrayList<>();

            tasks.add(() -> Count());                       // returns Integer
            tasks.add(() -> repeatedwords());               // returns List<String>
            tasks.add(() -> longest());                     // returns String
            tasks.add(() -> shortest());                    // returns String
            tasks.add(() -> Repeat());                      // returns Map<String,Integer>

            List<Future<Object>> futures = exec.invokeAll(tasks);

            int      count      = (Integer) futures.get(0).get();
            @SuppressWarnings("unchecked")
            List<String> repeated = (List<String>) futures.get(1).get();
            String   longest    = (String) futures.get(2).get();
            String   shortest   = (String) futures.get(3).get();
            @SuppressWarnings("unchecked")
            Map<String,Integer> repeatMap = (Map<String,Integer>) futures.get(4).get();

            long elapsed = (System.nanoTime() - start) / 1_000_000L;
            return new ResultWrapper("Threaded", elapsed,
                    count, repeated, longest, shortest, repeatMap);
        } catch (InterruptedException | ExecutionException e) {
            throw new RemoteException("Threaded execution failed", e);
        } finally {
            exec.shutdown();
        }
    }

    /** -------------------------------------------------------
     *  Helper methods – pure Java, no RMI stuff.
     *  ------------------------------------------------------- */

    /** Generates a single string containing *n* random words separated by spaces. */
    private static String generateRandomText(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String w = WORD_BANK[RAND.nextInt(WORD_BANK.length)];
            sb.append(w);
            if (i < n - 1) sb.append(' ');
        }
        return sb.toString();
    }

    /** Returns a list of distinct words that appear more than once. */
    private static List<String> findRepeated(List<String> list) {
        Map<String,Long> freq = list.stream()
                .collect(Collectors.groupingBy(w -> w, Collectors.counting()));
        return freq.entrySet().stream()
                .filter(e -> e.getValue() > 1)
                .map(Map.Entry::getKey)
                .sorted()
                .collect(Collectors.toList());
    }

    /** Returns a map word → occurrence count. */
    private static Map<String,Integer> countOccurrences(List<String> list) {
        Map<String,Integer> map = new HashMap<>();
        for (String w : list) {
            map.merge(w, 1, Integer::sum);
        }
        return map;
    }
}
```

### What the code does

1. **Construction** – `EncyclopediaImpl()` builds a **300‑word random string** exactly once.  
   The same string is used for every client request, which mimics a read‑only encyclopedia.

2. **Non‑threaded analysis** – simply calls the five helper methods one after another.

3. **Threaded analysis** – launches **five callables** in a **fixed‑size pool of 5 threads**; each callable runs one of the analyses.  
   When all futures complete we collect the results and compute the elapsed time.

4. Both `runNonThreaded()` and `runThreaded()` return a **`ResultWrapper`** that holds the data **and** the time (ms). This keeps the client UI very clean.

