 */
public class EncyclopediaServer {

    public static void main(String[] args) {
        try {
            // 1. Start (or obtain) the RMI registry on the default port 1099
            Registry registry;
            try {
                registry = LocateRegistry.createRegistry(1099);
                System.out.println("Created new RMI registry on port 1099.");
            } catch (RemoteException e) {
                // If the registry already exists, just obtain it
                registry = LocateRegistry.getRegistry(1099);
                System.out.println("Found existing RMI registry on port 1099.");
            }

            // 2. Create the remote object
            Encyclopedia impl = new EncyclopediaImpl();

            // 3. Bind it with a name the client will look up
            String bindName = "EncyclopediaService";
            registry.bind(bindName, impl);
            System.out.println("Encyclopedia service bound as '" + bindName + "'.");
            System.out.println("Server ready – press Ctrl+C to stop.");

        } catch (RemoteException | AlreadyBoundException e) {
            System.err.println("Server exception: " + e.toString());
            e.printStackTrace();
        }
    }
}
