        super("RMI Encyclopedia – Analysis");
        this.remoteService = remote;
        initGui();
    }

    /** -----------------------------------------------------------------
     *  Build the Swing UI.
     *  ----------------------------------------------------------------- */
    private void initGui() {
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        // Toolbar with the two action buttons
        JPanel toolbar = new JPanel();
        JButton btnNonThreaded = new JButton("Run NON‑Threaded");
        JButton btnThreaded    = new JButton("Run THREADed");

        btnNonThreaded.addActionListener(this::runNonThreaded);
        btnThreaded.addActionListener(this::runThreaded);

        toolbar.add(btnNonThreaded);
        toolbar.add(btnThreaded);
        add(toolbar, BorderLayout.NORTH);

        // Result area
        outputArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(outputArea);
        add(scroll, BorderLayout.CENTER);

        // Bottom panel with timings
        JPanel bottom = new JPanel(new GridLayout(1, 3));
        bottom.add(lblNonThreaded);
        bottom.add(lblThreaded);
        bottom.add(lblSpeedup);
        add(bottom, BorderLayout.SOUTH);

        pack();
        setLocationRelativeTo(null); // centre on screen
    }

    /** -----------------------------------------------------------------
     *  Action listeners – invoke the remote methods and display everything.
     *  ----------------------------------------------------------------- */
    private void runNonThreaded(ActionEvent e) {
        try {
            ResultWrapper res = remoteService.runNonThreaded();
            displayResult(res);
            lblNonThreaded.setText("Non‑threaded time: " + res.elapsedMs + " ms");
            computeSpeedup();
        } catch (RemoteException ex) {
            showError("Remote error (non‑threaded): " + ex.getMessage());
        }
    }

    private void runThreaded(ActionEvent e) {
        try {
            ResultWrapper res = remoteService.runThreaded();
            displayResult(res);
            lblThreaded.setText("Threaded time: " + res.elapsedMs + " ms");
            computeSpeedup();
        } catch (RemoteException ex) {
            showError("Remote error (threaded): " + ex.getMessage());
        }
    }

    /** -----------------------------------------------------------------
     *  Helper to put the data into the big text area.
     *  ----------------------------------------------------------------- */
    private void displayResult(ResultWrapper r) {
        StringBuilder sb = new StringBuilder();
        sb.append("=== ").append(r.description).append(" RESULT ===\n\n");
        sb.append("Total characters (including spaces) : ").append(r.count).append('\n');
        sb.append("Longest word                         : ").append(r.longest).append('\n');
        sb.append("Shortest word                        : ").append(r.shortest).append('\n');
        sb.append("\nRepeated words (").append(r.repeated.size()).append("):\n");
        sb.append(String.join(", ", r.repeated)).append("\n\n");
        sb.append("Word frequencies:\n");
        for (Map.Entry<String,Integer> e : r.repeatMap.entrySet()) {
            sb.append(String.format("%-12s : %d%n", e.getKey(), e.getValue()));
        }
        sb.append("\n\n");

        outputArea.append(sb.toString());
        outputArea.setCaretPosition(outputArea.getDocument().getLength());
    }

    /** -----------------------------------------------------------------
     *  Compute speed‑up when we have both times.
     *  ----------------------------------------------------------------- */
    private void computeSpeedup() {
        String nonStr = lblNonThreaded.getText().replaceAll("[^0-9]", "");
        String thrStr = lblThreaded.getText().replaceAll("[^0-9]", "");

        try {
            long non = Long.parseLong(nonStr);
            long thr = Long.parseLong(thrStr);
            if (non > 0 && thr > 0) {
                long speed = non - thr;
                lblSpeedup.setText("Speed‑up: " + speed + " ms");
            }
        } catch (NumberFormatException ignored) {
            // timing labels not yet filled
        }
    }

    /** -----------------------------------------------------------------
     *  Small dialog for errors.
     *  ----------------------------------------------------------------- */
    private void showError(String msg) {
        JOptionPane.showMessageDialog(this, msg, "Error", JOptionPane.ERROR_MESSAGE);
    }

    /** -----------------------------------------------------------------
     *  Main – locate the remote service and launch UI.
     *  ----------------------------------------------------------------- */
    public static void main(String[] args) {
        try {
            // Look up the remote object (default host = localhost)
            Registry registry = LocateRegistry.getRegistry("localhost", 1099);
            Encyclopedia service = (Encyclopedia) registry.lookup("EncyclopediaService");

            SwingUtilities.invokeLater(() -> {
                EncyclopediaClient client = new EncyclopediaClient(service);
                client.setVisible(true);
            });

        } catch (RemoteException | NotBoundException ex) {
            System.err.println("Could not locate remote service: " + ex.getMessage());
            ex.printStackTrace();
            System.exit(1);
        }
    }
}
