    // 2. 处理单个客户端隧道
    static async Task HandleClientAsync(TcpClient client, X509Certificate2 cert)
    {
        using var network = client.GetStream();
        // TLS 握手（双向加密）
        using var ssl = new SslStream(network, false);
        await ssl.AuthenticateAsServerAsync(cert, clientCertificateRequired: false,
                                            enabledSslProtocols: System.Security.Authentication.SslProtocols.Tls13,
                                            checkCertificateRevocation: false);
        Console.WriteLine($"[+] TLS handshake completed with {client.Client.RemoteEndPoint}");

        // 隧道协议非常简洁：读取一段 4 字节长度 + payload，直接转发到目标
        while (true)
        {
            // 读取 4B 长度 (网络序)
            var lenBuf = new byte[4];
            int read = await ssl.ReadAsync(lenBuf, 0, 4);
            if (read == 0) break;          // 客户端关闭
            if (read != 4) throw new IOException("Invalid length prefix");

            int payloadLen = IPAddress.NetworkToHostOrder(BitConverter.ToInt32(lenBuf, 0));
            if (payloadLen <= 0 || payloadLen > 64 * 1024) throw new IOException("Bad payload size");

            // 读取 payload
            var payload = new byte[payloadLen];
            int offset = 0;
            while (offset < payloadLen)
            {
                int r = await ssl.ReadAsync(payload, offset, payloadLen - offset);
                if (r == 0) throw new IOException("Unexpected EOF");
                offset += r;
            }

            // Payload = <4B destIp><2B destPort><remaining: TCP data>
            // 这里使用 IPv4 + TCP，仅仅演示
            var destIp = new IPAddress(payload[..4]);
            var destPort = (ushort)IPAddress.NetworkToHostOrder(BitConverter.ToInt16(payload, 4));
            var data = payload[6..];

            // 与目标建立 TCP 连接（若已有则复用，这里每次新建，简化实现）
            using var target = new TcpClient();
            await target.ConnectAsync(destIp, destPort);
            using var targetStream = target.GetStream();

            // 把 data 写入目标
            await targetStream.WriteAsync(data, 0, data.Length);
            await targetStream.FlushAsync();

            // 读取目标返回的数据（一次读取 64KB，实际可以循环读取直到 EOF）
            var respBuf = new byte[64 * 1024];
            int respLen = await targetStream.ReadAsync(respBuf, 0, respBuf.Length);

            // 把响应封装回隧道（同样的 4B 长度 + payload）
            // payload = <4B srcIp><2B srcPort><response>
            var srcIp = ((IPEndPoint)target.Client.LocalEndPoint).Address.GetAddressBytes();
            var srcPort = ((IPEndPoint)target.Client.LocalEndPoint).Port;
            using var ms = new MemoryStream();
            ms.Write(srcIp, 0, 4);
            ms.Write(BitConverter.GetBytes(IPAddress.HostToNetworkOrder((short)srcPort)), 0, 2);
            ms.Write(respBuf, 0, respLen);
            var outPayload = ms.ToArray();

            // 写回长度 + payload
            var outLen = IPAddress.HostToNetworkOrder(outPayload.Length);
            var outLenBytes = BitConverter.GetBytes(outLen);
            await ssl.WriteAsync(outLenBytes, 0, 4);
            await ssl.WriteAsync(outPayload, 0, outPayload.Length);
            await ssl.FlushAsync();
        }

