## 3️⃣ Node‑Bridge – Kotlin Wrapper Around a Child Process

```kotlin
package com.example.advancedforgemod

import com.google.gson.Gson
import com.google.gson.JsonObject
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.net.ServerSocket
import java.net.Socket
import java.util.concurrent.Executors

/**
 * Starts a Node.js process that listens on a local TCP socket.
 * Provides a tiny API for sending log‑messages (and any future RPC).
 */
class NodeBridge {

    // -----------------------------------------------------------------------
    // 1️⃣ Network configuration (loopback + random free port)
    // -----------------------------------------------------------------------
    private val server = ServerSocket(0) // 0 == pick any free port
    private val port: Int = server.localPort

    // -----------------------------------------------------------------------
    // 2️⃣ Process handling
    // -----------------------------------------------------------------------
    private var nodeProcess: Process? = null
    private var nodeSocket: Socket? = null
    private var writer: OutputStreamWriter? = null
    private val gson = Gson()

    // -----------------------------------------------------------------------
    // 3️⃣ Thread pool for reading async messages from Node (not used now, but handy)
    // -----------------------------------------------------------------------
    private val executor = Executors.newSingleThreadExecutor()

    /**
     * Starts the Node process **once**. Throws if the executable cannot be found.
     */
    @Throws(Exception::class)
    fun start() {
        // Build the command – we expect "node" to be on PATH.
        val command = listOf("node", "-e", NODE_SCRIPT_CONTENT, "--port=$port")
        // Using ProcessBuilder gives us direct access to stdio.
        val pb = ProcessBuilder(command)
        pb.redirectError(ProcessBuilder.Redirect.INHERIT) // keep Node's errors on console
        nodeProcess = pb.start()

        // Wait for the child to open its socket
        nodeSocket = server.accept()
        writer = OutputStreamWriter(nodeSocket!!.getOutputStream(), Charsets.UTF_8)

        // Optional: start a read‑loop to handle inbound messages later
        startReaderThread()
    }

    /**
     * Send a simple `log` message to the Node side.
     */
    fun sendLog(message: String) {
        // JSON packet format required by node_bridge.js:
        // { "type": "log", "payload": "your text" }
        val packet = JsonObject()
        packet.addProperty("type", "log")
        packet.addProperty("payload", message)
        sendPacket(packet)
    }

    /** Low‑level sender – synchronously writes a line‑delimited JSON message. */
    private fun sendPacket(obj: JsonObject) {
        val json = gson.toJson(obj)
        writer?.apply {
            write(json)
            write('\n')
            flush()
        } ?: error("Node bridge not started")
    }

    /** Shut everything down cleanly – called from the mod's `serverStopping` event. */
    fun stop() {
        try { writer?.close() } catch (ignored: Exception) {}
        try { nodeSocket?.close() } catch (ignored: Exception) {}
        try { server.close() } catch (ignored: Exception) {}
        try { nodeProcess?.destroy() } catch (ignored: Exception) {}
        executor.shutdownNow()
    }

    // -----------------------------------------------------------------------
    // 4️⃣ (Optional) Reader – handy if you later want Node → Kotlin callbacks
    // -----------------------------------------------------------------------
    private fun startReaderThread() {
        executor.submit {
            BufferedReader(InputStreamReader(nodeSocket!!.getInputStream(), Charsets.UTF_8)).useLines { lines ->
                lines.forEach { line ->
                    // Each line is a JSON object coming from Node.
                    // For now we just print it; you can also route it to listeners.
                    println("[Node ↔ Mod] $line")
                }
            }
        }
    }

    companion object {
        /**
         * This is the tiny Node script that runs inside the child process.
         * It accepts a `--port=XXXX` argument, opens a TCP socket back to the mod,
         * and prints any messages of type "log" to its own stdout.
         *
         * The script is embedded here to keep the whole project self‑contained.
         * If you prefer an external file, replace `-e` with the path.
         */
        private const val NODE_SCRIPT_CONTENT = """
            const net = require('net');
            const args = require('minimist')(process.argv.slice(2));
            const port = args.port;
            const client = net.createConnection({ port: port, host: '127.0.0.1' }, () => {
                console.log('[Node] Connected to JVM bridge on port', port);
            });

            client.setEncoding('utf8');
            let buffer = '';
            client.on('data', chunk => {
                buffer += chunk;
                let idx;
                while ((idx = buffer.indexOf('\n')) >= 0) {
                    const line = buffer.slice(0, idx);
                    buffer = buffer.slice(idx + 1);
                    try {
                        const msg = JSON.parse(line);
                        if (msg.type === 'log') {
                            // Forward to the node console (will appear in the terminal you launched `node` from)
                            console.log('[From JVM]', msg.payload);
                        } else {
                            console.warn('[Node] Unknown packet type', msg.type);
                        }
                    } catch (e) {
                        console.error('[Node] Failed to parse JSON:', line, e);
                    }
                }
            });

            client.on('end', () => console.log('[Node] JVM disconnected.'));
            client.on('error', err => console.error('[Node] Socket error', err));
        """
    }
}
```

### How it works

* **Port negotiation** – The Kotlin side opens a `ServerSocket` on a random free port, tells the child node process which port to connect to (`--port=$port`), then waits for the connection.
* **Message format** – All traffic is line‑delimited JSON. This is trivial to extend (e.g. `{type:"event", name:"playerJoin", data:{...}}`).
* **Logging** – `node.log("hello")` in a JS module will be translated into a packet with `type:"log"` that the Node script prints to its own console, so you see it in the terminal that started the node process.

> **Tip** – If you are on Windows and `node` is not on the `%PATH%`, replace `"node"` with the full path in the `command` list.

