## 4️⃣ Nashorn Script Manager (`ScriptManager.kt`)

```kotlin
package com.example.advancedforgemod

import java.io.File
import java.io.FileReader
import javax.script.Invocable
import javax.script.ScriptEngine
import javax.script.ScriptEngineManager
import javax.script.SimpleBindings

/**
 * Loads `.js` files from a configurable folder, evaluates them with Nashorn,
 * and gives each script a `node` object that proxies to the [NodeBridge].
 *
 * The scripts can export symbols via the global `exports` object:
 *
 *   // mymod.js
 *   exports.onInit = function() {
 *       node.log("mod loaded!");
 *   };
 *
 *   exports.add = (a, b) => a + b;
 *
 * Afterwards you can retrieve a handle from Kotlin:
 *
 *   val add = scriptManager.getFunction("myMod", "add") as (Int, Int) -> Int
 */
class ScriptManager(private val nodeBridge: NodeBridge) {

    private val engine: ScriptEngine = ScriptEngineManager().getEngineByName("nashorn")
    // Keep a map: moduleName -> exports object (which is just a JS object)
    private val moduleExports = mutableMapOf<String, Any>()

    // -----------------------------------------------------------------------
    // 1️⃣ Load all *.js files under <config>/advancedforgemod/modules/
    // -----------------------------------------------------------------------
    fun loadAllModules(configDir: File) {
        // Create the folder if it does not exist
        val modulesDir = File(configDir, "advancedforgemod/modules")
        if (!modulesDir.exists()) modulesDir.mkdirs()

        // Scan for .js files
        val jsFiles = modulesDir.listFiles { _, name -> name.endsWith(".js") } ?: emptyArray()
        if (jsFiles.isEmpty()) {
            // Seed a simple demo module for newcomers
            createDemoModule(modulesDir)
        }

        for (file in jsFiles) {
            loadModule(file)
        }
    }

    // -----------------------------------------------------------------------
    // 2️⃣ Individual module loading
    // -----------------------------------------------------------------------
    private fun loadModule(file: File) {
        val moduleName = file.nameWithoutExtension
        val bindings = SimpleBindings().apply {
            // ----- expose a tiny `node` namespace -----
            put("node", NodeProxy(nodeBridge))
            // ----- provide a simple `require` implementation -----
            put("require", RequireFunction(this@ScriptManager, file.parentFile))
            // ----- an empty `exports` object that the script can fill -----
            put("exports", engine.eval("({})"))
        }

        // Evaluate the script with the prepared bindings
        engine.eval(FileReader(file), bindings)

        // Store the populated `exports` for later lookup
        val exportsObj = bindings["exports"] ?: error("Module $moduleName didn't define exports")
        moduleExports[moduleName] = exportsObj
        println("[ScriptManager] Loaded module '$moduleName' from ${file.path}")
    }

    // -----------------------------------------------------------------------
    // 3️⃣ Helper to call a function from a loaded module
    // -----------------------------------------------------------------------
    fun invokeFunction(moduleName: String, functionName: String, vararg args: Any?): Any? {
        val exports = moduleExports[moduleName] ?: error("No module named $moduleName")
        val inv = engine as Invocable
        // The exported function lives on the `exports` object
        return inv.invokeMethod(exports, functionName, *args)
    }

    /** Invoke the given function on **every** loaded module, ignoring missing functions. */
    fun invokeAll(functionName: String) {
        val inv = engine as Invocable
        for ((modName, exports) in moduleExports) {
            try {
                inv.invokeMethod(exports, functionName)
            } catch (e: NoSuchMethodException) {
                // Silently ignore modules that don't implement the hook
            }
        }
    }

    /** Retrieve the raw `exports` object (useful for reflection‑like access). */
    fun getExports(moduleName: String): Any = moduleExports[moduleName]
        ?: error("Module $moduleName not loaded")

    // -----------------------------------------------------------------------
    // 4️⃣ Demo module auto‑creation (runs once on a fresh install)
    // -----------------------------------------------------------------------
    private fun createDemoModule(dir: File) {
        val demo = File(dir, "demo_module.js")
        demo.writeText(
            """
            // --------------------------------------------------------------
            // Example module – all code runs inside Nashorn, not Node!
            // --------------------------------------------------------------
            // The global `node` object proxies to the child Node process.
            // Every `node.log` ends up printed in the Node terminal.
            // --------------------------------------------------------------

            exports.onInit = function() {
                node.log("🚀 Demo module loaded! You can see this message in the node console.");
            };

            // Simple arithmetic export – we can call it from Kotlin later.
            exports.add = (a, b) => {
                node.log(`Adding ${a} + ${b}`);
                return a + b;
            };

            // Demonstrate a custom `require` – load a sibling file
            // (uncomment the next lines if you add `helper.js` next to this file)
            // const helper = require("./helper.js");
            // node.log("Helper says: " + helper.getMessage());

            """.trimIndent()
        )
        println("[ScriptManager] Created demo module at ${demo.path}")
    }

    // -----------------------------------------------------------------------
    // 5️⃣ Inner classes – Node proxy and a tiny `require`
    // -----------------------------------------------------------------------
    /** Called from JS as `node.log("text")`. */
    private class NodeProxy(private val bridge: NodeBridge) {
        @JvmOverloads
        fun log(message: Any?, level: String = "info") {
            bridge.sendLog(message?.toString() ?: "null")
        }

        // You can add extra RPC methods here, e.g. node.sendEvent(...)
    }

    /** Very small `require` that only supports relative paths and plain `.js` files. */
    private class RequireFunction(
        private val manager: ScriptManager,
        private val baseDir: File
    ) : java.util.function.Function<String, Any> {
        override fun apply(path: String): Any {
            // Resolve relative to the module that called `require`
            val file = File(baseDir, path).let {
                if (it.isDirectory) File(it, "index.js") else it
            }

            if (!file.exists()) throw IllegalArgumentException("Cannot require non‑existent file $path")

            // Load the file into a fresh binding so it cannot pollute other modules
            val bindings = SimpleBindings().apply {
                put("node", NodeProxy(manager.nodeBridge))
                put("exports", manager.engine.eval("({})"))
                put("require", this) // allow nested requires
            }

            manager.engine.eval(FileReader(file), bindings)
            return bindings["exports"]!!
        }
    }
}
```

### Key Points

| Feature | How it’s achieved |
|---------|-------------------|
| **`node.log`** inside JS | `NodeProxy.log` forwards to `NodeBridge.sendLog` → printed by Node. |
| **`require`** | Very small recursive loader that returns the `exports` object of the required file. |
| **Exported functions** | Modules assign to the global `exports` object; Kotlin accesses them via `Invocable.invokeMethod`. |
| **Automatic demo** | First launch creates `config/advancedforgemod/modules/demo_module.js` so you have a working example instantly. |
| **Thread‑safety** | All Nashorn calls happen on the main Forge thread (no extra thread pools). If you need background work, spin off a new thread yourself – just remember Nashorn isn’t thread‑safe per engine instance. |

