### b. 可选：对图片做进一步处理（压缩、裁剪、加水印等）

```java
import javax.imageio.ImageIO;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;

@PostMapping("/uploadAndProcess")
public ResponseEntity<byte[]> uploadAndProcess(@RequestParam("file") MultipartFile file) throws IOException {
    // 把上传的二进制转成 BufferedImage
    BufferedImage srcImg = ImageIO.read(new ByteArrayInputStream(file.getBytes()));

    // -------- 示例：在图片右下角加文字水印 ----------
    Graphics2D g = srcImg.createGraphics();
    g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
    g.setFont(new Font("Arial", Font.BOLD, 20));
    g.setColor(new Color(255, 255, 255, 128)); // 半透明白色
    String watermark = "Demo";
    FontMetrics fm = g.getFontMetrics();
    int x = srcImg.getWidth() - fm.stringWidth(watermark) - 10;
    int y = srcImg.getHeight() - fm.getHeight() + 20;
    g.drawString(watermark, x, y);
    g.dispose();

    // 把 BufferedImage 再转成 byte[]（这里保持 PNG，也可以改成 JPEG 并调压缩质量）
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    ImageIO.write(srcImg, "png", baos);
    byte[] processedBytes = baos.toByteArray();

    HttpHeaders headers = new HttpHeaders();
    headers.setContentType(MediaType.IMAGE_PNG);
    return ResponseEntity.ok().headers(headers).body(processedBytes);
}
```

