## 2️⃣ Сервис‑провайдер, который «склеивает» два блока логики  

```java
package com.ncs.api.service;

import com.ncs.company.security.NcsAuthenticationProvider;
import com.ncs.security.service.AuthServiceImpl;
import com.ncs.security.service.dto.AuthResult;          // предполагаемый пакет
import com.ncs.security.model.Token;                    // сущность токена
import com.ncs.company.model.Employee;                  // сущность сотрудника
import com.ncs.company.service.EmployeeService;         // сервис поиска сотрудника
import jakarta.servlet.http.HttpServletRequest;
import lombok.RequiredArgsConstructor;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;

/**
 * Объединяет две бизнес‑логики:
 *  1) проверка логина/пароля (AuthServiceImpl)
 *  2) дополнительные проверки партнёрской привязки (NcsAuthenticationProvider)
 *
 * Если всё прошло – в SecurityContext помещаем готовый Authentication‑token.
 */
@Component
@RequiredArgsConstructor
public class FrontAuthProcessor {

    private final AuthServiceImpl authService;
    private final EmployeeService employeeService;
    private final NcsAuthenticationProvider ncsAuthenticationProvider;

    /**
     * Выполняет полную аутентификацию и (при успехе) сохраняет токен в SecurityContext.
     *
     * @return AuthResult, в котором уже находится сгенерированный токен.
     */
    public AuthResult authenticate(LoginRequestDto request, HttpServletRequest http) {
        String ip = extractClientIp(http);

        // 1️⃣ проверка логина/пароля
        AuthResult authResult = authService.auth(request.login(), request.password(), ip);

        // если пароль/логин не прошли – сразу возвращаем результат
        if (!authResult.isValid() || authResult.getToken() == null) {
            return authResult;
        }

        // 2️⃣ поиск Employee‑а, который сопоставлен пользователю (по userId)
        Employee employee = employeeService.findByUserId(authResult.getUserId())
                .orElseThrow(() -> new IllegalStateException("Employee not found for userId=" + authResult.getUserId()));

        // 3️⃣ дополнительные проверки, реализованные в NcsAuthenticationProvider#getAuthToken
        UsernamePasswordAuthenticationToken springAuth =
                ncsAuthenticationProvider.getAuthToken(
                        employee.getEmail(),          // principal (можно любой идентификатор)
                        request.password(),          // credentials (не используется дальше)
                        employee);                   // объект Employee, в котором хранятся связи с партнёрами

        // 4️⃣ кладём токен в SecurityContext – дальше в цепочке фильтров будет считаться «авторизованным»
        SecurityContextHolder.getContext().setAuthentication(springAuth);

        return authResult;
    }

    /** Получаем реальный IP клиентского запроса (может быть за прокси). */
    private String extractClientIp(HttpServletRequest request) {
        String header = request.getHeader("X-Forwarded-For");
        if (header != null && !header.isBlank()) {
            // X-Forwarded-For может содержать несколько IP через запятую, берём первый
            return header.split(",")[0].trim();
        }
        return request.getRemoteAddr();
    }

    /** Простой DTO, который нужен только внутри процессора (не экспортируем наружу). */
    public record LoginRequestDto(String login, String password) {}
}
```

> **Почему создаём отдельный компонент?**  
> * Позволяет писать юнит‑тесты, не дергая контроллер.  
> * Выделяет бизнес‑логика (два разных сервиса) из контроллера – контроллер остаётся «тонким».  

