## 3️⃣ Контроллер (в пакете `com.ncs.api.controller`)

```java
package com.ncs.api.controller;

import com.ncs.api.dto.ErrorResponse;
import com.ncs.api.dto.LoginRequest;
import com.ncs.api.dto.LoginResponse;
import com.ncs.api.service.FrontAuthProcessor;
import com.ncs.security.service.dto.AuthResult;      // в проекте может быть другой пакет
import com.ncs.security.model.Token;                // сущность токена
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.time.Instant;

/**
 * API‑уровень, предназначенный для UI‑приложения.
 *
 * При успешной аутентификации возвращает JSON:
 * {
 *   "token":"xxxx",
 *   "expiresAt":"2024‑12‑31T23:59:59Z",
 *   "userId":123
 * }
 *
 * При ошибке – статус 401 и тело:
 * {
 *   "error":"Не указан логин",
 *   "description":"Ваш логин введен неверно",
 *   "help":"В случае возникновения вопросов, обратитесь в службу поддержки клиентов по телефону"
 * }
 */
@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final FrontAuthProcessor frontAuthProcessor;

    @PostMapping("/login")
    public ResponseEntity<?> login(@Valid @RequestBody LoginRequest request,
                                   jakarta.servlet.http.HttpServletRequest http) {

        // Обёртка, которую будет использовать процессор
        FrontAuthProcessor.LoginRequestDto dto = new FrontAuthProcessor.LoginRequestDto(
                request.login(), request.password());

        AuthResult result = frontAuthProcessor.authenticate(dto, http);

        // ---- Ошибка ------------------------------------------------------
        if (!result.isValid() || result.getToken() == null) {
            // В методе auth формируются сообщения через `invalidAuthResult`.
            // Переносим их в HTTP‑ответ.
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new ErrorResponse(
                            result.getMessage(),          // «Ошибка аутентификации» или “Не верный пароль”
                            result.getDescription(),     // более подробный текст
                            result.getHelp()              // справка/контакт службы поддержки
                    ));
        }

        // ---- Успех --------------------------------------------------------
        Token token = result.getToken();
        LoginResponse response = new LoginResponse(
                token.getToken(),
                token.getTokenValidity().toInstant(),
                result.getUserId(),
                null
        );

        return ResponseEntity.ok(response);
    }
}
```

> **Что делает контроллер?**  
> * Принимает запрос, проверяет валидацию полей (`@Valid`).  
> * Делегирует работу `FrontAuthProcessor`.  
> * Если `AuthResult` содержит ошибки – возвращаем `401 Unauthorized` с читаемым JSON‑сообщением.  
> * Если всё ОК – формируем `LoginResponse` (токен + время жизни).  

