package com.ncs.api.exception;

import com.ncs.api.dto.ErrorResponse;
import com.ncs.company.security.NcsAuthenticationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestControllerAdvice
public class RestExceptionHandler {

    @ExceptionHandler(NcsAuthenticationException.class)
    public ResponseEntity<ErrorResponse> handleNcsAuth(NcsAuthenticationException ex) {
        ErrorResponse body = new ErrorResponse(
                ex.getMessage(),
                ex.getDescription(),
                ex.getHelp()
        );
        return ResponseEntity.status(HttpStatus.FORBIDDEN).body(body);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleOther(Exception ex) {
        ErrorResponse body = new ErrorResponse(
                "Внутренняя ошибка сервера",
                ex.getMessage(),
                null
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }
}
