package com.example;

import java.io.IOException;
import java.io.PrintWriter;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

/**
 * 处理除法运算的 Servlet
 * URL 映射路径为 /divide（与 HTML 表单的 action 同名）
 */
@WebServlet(name = "DivideServlet", urlPatterns = {"/divide"})
public class DivideServlet extends HttpServlet {

    /**
     * 统一使用 POST 方式处理（如果你也想支持 GET，只需要在 doGet 中调用 doPost 即可）。
     */
    @Override
    protected void doPost(HttpServletRequest request,
                          HttpServletResponse response) throws ServletException, IOException {

        // 为了防止中文乱码（如果页面使用 UTF-8）
        request.setCharacterEncoding("UTF-8");
        response.setContentType("text/html;charset=UTF-8");

        // 1. 读取表单参数（字符串）
        String strNum1 = request.getParameter("num1");
        String strNum2 = request.getParameter("num2");

        // 2. 构造返回页面的 HTML 头部
        PrintWriter out = response.getWriter();
        out.println("<!DOCTYPE html>");
        out.println("<html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><title>除法结果</title></head><body>");

        // 3. 参数合法性校验 + 类型转换
        if (strNum1 == null || strNum2 == null ||
                strNum1.trim().isEmpty() || strNum2.trim().isEmpty()) {
            out.println("<h3 class='msg'>错误：请同时填写被除数和除数！</h3>");
        } else {
            try {
                // 可以使用 double 进行浮点运算；如果只想整数除法，用 int
                double num1 = Double.parseDouble(strNum1.trim());
                double num2 = Double.parseDouble(strNum2.trim());

                // 4. 除数为 0 的判断
                if (Math.abs(num2) < 1e-12) {   // 这里用一个很小的阈值来避免精度问题
                    out.println("<h3 class='msg'>错误：除数不能为 0！</h3>");
                } else {
                    double result = num1 / num2;
                    out.println("<h2>运算结果</h2>");
                    out.printf("<p>%.4f ÷ %.4f = <strong>%.4f</strong></p>%n",
                               num1, num2, result);
                }
            } catch (NumberFormatException e) {
                // 捕获非数字输入
                out.println("<h3 class='msg'>错误：请输入合法的数字！</h3>");
            }
        }

        // 5. 给一个返回链接，方便回到表单页面
        out.println("<p><a href=\"divide.html\">返回重新计算</a></p>");
        out.println("</body></html>");
        out.flush();
    }

    // 若想也支持 GET，只需要把 GET 重定向到 POST
    @Override
    protected void doGet(HttpServletRequest request,
                         HttpServletResponse response) throws ServletException, IOException {
        doPost(request, response);
    }
}
```

### 关键点解释

| 步骤 | 代码片段 | 说明 |
|------|----------|------|
| **读取参数** | `request.getParameter("num1")` | 从请求体中取出字符串，注意 `null` 与空字符串的情况 |
| **字符编码** | `request.setCharacterEncoding("UTF-8")` | 防止中文或特殊字符乱码（必须在读取参数前调用） |
| **类型转换** | `Double.parseDouble(strNum1.trim())` | 把字符串转成 `double`，如果输入不是合法数字会抛 `NumberFormatException` |
