        } else {
            try {
                double num1 = Double.parseDouble(strNum1.trim());
                double num2 = Double.parseDouble(strNum2.trim());

                if (Math.abs(num2) < 1e-12) {
                    out.println("<h3 class='msg'>错误：除数不能为 0！</h3>");
                } else {
                    double result = num1 / num2;
                    out.println("<h2>运算结果</h2>");
