// ---------------------------------------------------------------
//  XmlDemo.java  –  self‑contained demonstration of XmlExtractor
// ---------------------------------------------------------------
import javax.xml.parsers.*;
import javax.xml.xpath.*;
import javax.xml.transform.*;
import javax.xml.transform.dom.*;
import javax.xml.transform.stream.*;
import org.w3c.dom.*;
import org.xml.sax.InputSource;
import java.io.*;
import java.util.*;

public class XmlDemo {

    // ---------- Simple NamespaceContext ----------
    static class SimpleNamespaceContext implements NamespaceContext {
        private final Map<String, String> map = new HashMap<>();
        SimpleNamespaceContext add(String prefix, String uri) {
            map.put(prefix, uri);
            return this;
        }
        @Override public String getNamespaceURI(String prefix) {
            return map.getOrDefault(prefix, XMLConstants.NULL_NS_URI);
        }
        @Override public String getPrefix(String uri) {
            for (var e : map.entrySet())
                if (e.getValue().equals(uri)) return e.getKey();
            return null;
        }
        @Override public Iterator<String> getPrefixes(String uri) { return null; }
    }

    // ---------- Core extractor (same as XmlExtractor class) ----------
    static class XmlExtractor {

        private static Document parse(String xml) throws Exception {
            DocumentBuilderFactory f = DocumentBuilderFactory.newInstance();
            f.setNamespaceAware(true);
            f.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            f.setFeature("http://xml.org/sax/features/external-general-entities", false);
            f.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            DocumentBuilder b = f.newDocumentBuilder();
            try (StringReader r = new StringReader(xml)) {
                return b.parse(new InputSource(r));
            }
        }

        private static XPathExpression compile(String expr, NamespaceContext ns) throws XPathExpressionException {
            XPath xpath = XPathFactory.newInstance().newXPath();
            if (ns != null) xpath.setNamespaceContext(ns);
            return xpath.compile(expr);
        }

        static String extractFirst(String xml, String xpathExpr, NamespaceContext ns) throws Exception {
            Document doc = parse(xml);
            XPathExpression x = compile(xpathExpr, ns);
            Node n = (Node) x.evaluate(doc, XPathConstants.NODE);
            return n == null ? null : nodeToString(n);
        }

        static List<String> extractAll(String xml, String xpathExpr, NamespaceContext ns) throws Exception {
            Document doc = parse(xml);
            XPathExpression x = compile(xpathExpr, ns);
            NodeList nl = (NodeList) x.evaluate(doc, XPathConstants.NODESET);
            List<String> out = new ArrayList<>(nl.getLength());
            for (int i = 0; i < nl.getLength(); i++) {
                out.add(nodeToString(nl.item(i)));
            }
            return out;
        }

        private static String nodeToString(Node node) throws Exception {
            Transformer tf = TransformerFactory.newInstance().newTransformer();
            tf.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
            tf.setOutputProperty(OutputKeys.INDENT, "yes");
            tf.setOutputProperty("{http://xml.apache.org/xslt}indent-amount", "2");

            DOMSource src = new DOMSource(node);
            StringWriter sw = new StringWriter();
            tf.transform(src, new StreamResult(sw));
            return sw.toString().trim();
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) throws Exception {
        String xml = """
                <?xml version="1.0" encoding="UTF-8"?>
                <library xmlns:bk="http://example.com/book">
                  <bk:book id="b1">
                    <bk:title>Effective Java</bk:title>
                    <bk:author>Joshua Bloch</bk:author>
                  </bk:book>
                  <bk:book id="b2">
                    <bk:title>Java Concurrency in Practice</bk:title>
                    <bk:author>Brian Goetz</bk:author>
                  </bk:book>
                  <bk:book id="b3">
                    <bk:title>Clean Code</bk:title>
                    <bk:author>Robert C. Martin</bk:author>
                  </bk:book>
                </library>
                """;

        // Prepare namespace mapping for the prefix used in XPath
        SimpleNamespaceContext ns = new SimpleNamespaceContext()
                .add("bk", "http://example.com/book");

        // 1️⃣ Extract a single fragment (book id='b2')
        String first = XmlExtractor.extractFirst(xml,
                "//bk:book[@id='b2']", ns);
        System.out.println("=== Single fragment ===");
        System.out.println(first);
        System.out.println();

        // 2️⃣ Extract all books whose title starts with "C"
        List<String> all = XmlExtractor.extractAll(xml,
                "//bk:book[bk:title[starts-with(., 'C')]]", ns);
        System.out.println("=== All matching fragments ===");
        for (String frag : all) {
            System.out.println(frag);
            System.out.println("---");
        }
    }
}
