/**
 * Rappresenta un singolo hotel.
 *
 * La classe è **POJO** (Plain Old Java Object) e serve sia per la
 * deserializzazione GSON sia per la logica di business.
 */
public class Hotel {
    int id;
    String name;
    String description;
    String city;
    String phone;
    List<String> services;

    /** Punteggio sintetico (media dei rating delle categorie). */
    int rate;               // 0 ⇒ valore non ancora valutato

    /** Rating per ciascuna categoria (0…5). */
    Ratings ratings;

