    public Hotel() {}

    /** Costruttore di utilità (facoltativo, per test). */
    public Hotel(int id, String name) {
        this.id = id;
        this.name = name;
        this.rate = 0;
        this.ranking = 0;
        this.ratings = new Ratings();
    }

    /* ------------------------------------------------------------------ */
    /*                     CLASSI INTERNE (rating)                        */
    /* ------------------------------------------------------------------ */
    public static class Ratings {
        int cleaning;
        int position;
        int services;
        int quality;

