        public Ratings() {
            this.cleaning = 0;
            this.position = 0;
            this.services = 0;
            this.quality = 0;
        }

        /** Calcola la media aritmetica dei quattro rating. */
        public double average() {
            return (cleaning + position + services + quality) / 4.0;
        }

        /** Restituisce true se tutti i rating sono > 0 (cioè l’hotel è stato valutato). */
        public boolean isRated() {
