        @Override
        public String toString() {
            return String.format("[cleaning=%d, position=%d, services=%d, quality=%d]",
                    cleaning, position, services, quality);
        }
    }

    /* ------------------------------------------------------------------ */
    /*                     METODI DI UTILS (business)                     */
    /* ------------------------------------------------------------------ */

    /** Aggiorna i rating della singola categoria; se il valore è fuori range (1‑5) lancia IllegalArgumentException. */
    public void setRating(String category, int value) {
        if (value < 0 || value > 5) {
            throw new IllegalArgumentException("Rating must be between 0 and 5");
        }
        switch (category.toLowerCase()) {
            case "cleaning":  ratings.cleaning = value; break;
            case "position":  ratings.position = value; break;
            case "services":  ratings.services = value; break;
            case "quality":   ratings.quality = value; break;
            default:
                throw new IllegalArgumentException("Unknown category: " + category);
        }
        // Aggiorna subito il punteggio sintetico
        recalculateSyntheticScore();
    }

    /** Ricalcola e salva il punteggio sintetico (media arrotondata all’intero più vicino). */
    public void recalculateSyntheticScore() {
        double avg = ratings.average();
        this.rate = (int) Math.round(avg);
    }

    /** Convenience: restituisce una stringa riassuntiva. */
    @Override
    public String toString() {
        return String.format("Hotel{id=%d, name='%s', city='%s', rate=%d, ranking=%d, ratings=%s}",
                id, name, city, rate, ranking, ratings);
    }

    /** Equality basata sull’id (che è unico). */
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Hotel)) return false;
        Hotel other = (Hotel) o;
        return this.id == other.id;
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }
}
```

### Cosa è cambiato?

| Campo | Scopo |
|-------|------|
| `rate` | Punteggio sintetico (media dei quattro rating). |
| `ranking` | Posizione dell’hotel nella classifica locale (calcolata dal server). |
| Costruttore di default + costruttori di utilità | Garantiscono che, se il JSON non contiene i campi, l’oggetto venga creato con valori **0**. |
| Metodi `setRating` / `recalculateSyntheticScore` | Incapsulano la logica di aggiornamento e mantengono coerenti *rate* e *ratings*. |
| `equals`/`hashCode` | Facilitano l’uso di collezioni (`Set`, `Map`). |

