## 3️⃣ `HOTELIERServer` – Implementazione completa

```java
import com.google.gson.*;
import com.google.gson.reflect.TypeToken;

import java.io.*;
import java.lang.reflect.Type;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Server di gestione degli hotel.
 *
 * - Carica gli hotel da file JSON (se il file non esiste, crea una lista vuota). <br>
 * - Aggiorna i rating, ricalcola i punteggi sintetici e le posizioni di ranking. <br>
 * - Persiste le modifiche su disco (salvataggio manuale o automatico a shutdown). <br>
 *
 * La classe è pensata per essere **thread‑safe** (usiamo una `ReentrantReadWriteLock`).
 */
public class HOTELIERServer {

    /* ------------------------------------------------------------------ */
    /*                         CAMPI DI CLASSE                            */
    /* ------------------------------------------------------------------ */

    /** Lista modificabile degli hotel (ordine interno non importa; il ranking è calcolato al volo). */
    private final List<Hotel> hotels = new ArrayList<>();

    /** Path assoluto del file JSON di persistenza. */
    private final Path jsonFilePath;

    /** Lock per garantire consistenza in ambiente multithread. */
    private final java.util.concurrent.locks.ReadWriteLock rwLock =
            new java.util.concurrent.locks.ReentrantReadWriteLock();

    /* ------------------------------------------------------------------ */
    /*                         COSTRUTTORI                                 */
    /* ------------------------------------------------------------------ */

    /** Crea un server a partire da un file JSON. */
    public HOTELIERServer(String jsonFilePath) {
        this.jsonFilePath = Paths.get(jsonFilePath).toAbsolutePath();
        loadHotelsFromJson();   // carica all’avvio
        // Calcola ranking e rating sintetico anche se i valori erano già presenti
        recalculateAllSyntheticScores();
        updateRanking();
    }

    /* ------------------------------------------------------------------ */
    /*                         CARICAMENTO JSON                           */
    /* ------------------------------------------------------------------ */

    /** Legge gli hotel dal file JSON, creando la lista interna. */
    private void loadHotelsFromJson() {
        // Se il file non esiste → lista vuota (il server può funzionare comunque)
        if (!Files.isRegularFile(jsonFilePath)) {
            System.out.println("[INFO] File JSON non trovato. Avvio con lista vuota.");
            return;
        }

        Gson gson = new GsonBuilder()
                .setLenient()                 // accetta anche JSON “non perfetto”
                .registerTypeAdapter(Hotel.class, new HotelDeserializer())
                .create();

        Type hotelListType = new TypeToken<ArrayList<Hotel>>() {}.getType();

        try (Reader reader = Files.newBufferedReader(jsonFilePath)) {
            List<Hotel> loaded = gson.fromJson(reader, hotelListType);
            if (loaded != null) {
                rwLock.writeLock().lock();
                try {
                    hotels.clear();
                    hotels.addAll(loaded);
                } finally {
                    rwLock.writeLock().unlock();
                }
            }
            System.out.println("[INFO] " + hotels.size() + " hotel caricati da " + jsonFilePath);
        } catch (IOException | JsonSyntaxException e) {
            System.err.println("[ERROR] Impossibile leggere il file JSON:");
            e.printStackTrace();
        }
    }

    /**
     * **Deserializer custom** per gestire i casi in cui il JSON non contiene i campi
     * `rate`, `ranking` o `ratings`.  Permette di impostare i valori di default a 0.
     */
    private static class HotelDeserializer implements JsonDeserializer<Hotel> {
        @Override
        public Hotel deserialize(JsonElement json, Type typeOfT,
                                 JsonDeserializationContext context) throws JsonParseException {
            JsonObject obj = json.getAsJsonObject();

            Hotel hotel = new Hotel();
            hotel.id = obj.get("id").getAsInt();
            hotel.name = getAsStringOrEmpty(obj, "name");
            hotel.description = getAsStringOrEmpty(obj, "description");
            hotel.city = getAsStringOrEmpty(obj, "city");
            hotel.phone = getAsStringOrEmpty(obj, "phone");
            hotel.services = context.deserialize(obj.get("services"),
                    new TypeToken<List<String>>() {}.getType());

            // rate & ranking: se mancano, li impostiamo a 0
            hotel.rate = obj.has("rate") ? obj.get("rate").getAsInt() : 0;
            hotel.ranking = obj.has("ranking") ? obj.get("ranking").getAsInt() : 0;

            // ratings (può mancare del tutto)
            if (obj.has("ratings") && !obj.get("ratings").isJsonNull()) {
                JsonObject r = obj.getAsJsonObject("ratings");
                Hotel.Ratings rating = new Hotel.Ratings();
                rating.cleaning = r.has("cleaning") ? r.get("cleaning").getAsInt() : 0;
                rating.position = r.has("position") ? r.get("position").getAsInt() : 0;
                rating.services = r.has("services") ? r.get("services").getAsInt() : 0;
                rating.quality  = r.has("quality")  ? r.get("quality").getAsInt()  : 0;
                hotel.ratings = rating;
            } else {
                hotel.ratings = new Hotel.Ratings(); // tutti a 0
            }

            return hotel;
        }

        private static String getAsStringOrEmpty(JsonObject obj, String member) {
            return obj.has(member) && !obj.get(member).isJsonNull()
                    ? obj.get(member).getAsString()
                    : "";
        }
    }

    /* ------------------------------------------------------------------ */
    /*                         SALVATAGGIO JSON                            */
    /* ------------------------------------------------------------------ */

    /** Salva *tutta* la lista hotel sul file JSON (sovrascrive). */
    public void saveHotelsToJson() {
        Gson gson = new GsonBuilder()
                .setPrettyPrinting()
                .create();

        rwLock.readLock().lock();
        try (Writer writer = Files.newBufferedWriter(jsonFilePath)) {
            gson.toJson(hotels, writer);
            System.out.println("[INFO] Dati salvati su " + jsonFilePath);
        } catch (IOException e) {
            System.err.println("[ERROR] Impossibile scrivere su file JSON:");
            e.printStackTrace();
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /* ------------------------------------------------------------------ */
    /*                     METODI DI GESTIONE HOTEL                        */
    /* ------------------------------------------------------------------ */

    /** Restituisce una *copia* della lista (immutabile) di tutti gli hotel. */
    public List<Hotel> getAllHotels() {
        rwLock.readLock().lock();
        try {
            return Collections.unmodifiableList(new ArrayList<>(hotels));
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /** Ricerca un hotel per ID (null ⇒ non trovato). */
    public Hotel findById(int id) {
        rwLock.readLock().lock();
        try {
            return hotels.stream()
                    .filter(h -> h.id == id)
                    .findFirst()
                    .orElse(null);
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /** Aggiunge un nuovo hotel, garantendo l’unicità dell’ID. */
    public boolean addHotel(Hotel newHotel) {
        Objects.requireNonNull(newHotel, "Hotel cannot be null");
        rwLock.writeLock().lock();
        try {
            if (findById(newHotel.id) != null) {
                System.err.println("[WARN] Hotel con ID " + newHotel.id + " già presente.");
                return false;
            }
            // rating e rank a 0 per default (in caso il client non li abbia inizializzati)
            newHotel.rate = 0;
            newHotel.ranking = 0;
            if (newHotel.ratings == null) newHotel.ratings = new Hotel.Ratings();

            hotels.add(newHotel);
            // Aggiorna ranking e punteggio sintetico dopo l’inserimento
            recalculateAllSyntheticScores();
            updateRanking();
            return true;
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /** Rimuove un hotel per ID. */
    public boolean removeHotel(int id) {
        rwLock.writeLock().lock();
        try {
            boolean removed = hotels.removeIf(h -> h.id == id);
            if (removed) {
                updateRanking(); // ri‑classifica gli hotel rimasti
            }
            return removed;
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /**
     * Aggiorna il rating di una specifica categoria per l’hotel indicato.
     *
     * @param hotelId   ID dell’hotel da aggiornare
     * @param category  Nome della categoria (cleaning, position, services, quality)
     * @param value     Nuovo valore (0…5)
     * @return true se l’aggiornamento è stato effettuato, false se l’hotel non esiste.
     */
    public boolean updateRating(int hotelId, String category, int value) {
        rwLock.writeLock().lock();
        try {
            Hotel h = findById(hotelId);
            if (h == null) return false;
            h.setRating(category, value); // dentro setRating il valore “rate” viene ricalcato
            // Dopo la modifica di un rating, il ranking di tutti gli hotel può cambiare
            updateRanking();
            return true;
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /* ------------------------------------------------------------------ */
    /*                     CALCOLO DEL PUNTEGGIO E RANKING                */
    /* ------------------------------------------------------------------ */

    /** Ricalcola il punteggio sintetico per *tutti* gli hotel. */
    private void recalculateAllSyntheticScores() {
        rwLock.writeLock().lock();
        try {
            for (Hotel h : hotels) {
                h.recalculateSyntheticScore();
            }
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /**
     * Aggiorna la posizione (ranking) di tutti gli hotel in base al punteggio sintetico.
     * In caso di pareggio, il ranking è determinato **alfabeticamente** da `name`.
     *
     * Posizione 1 = hotel con punteggio più alto.
     */
    private void updateRanking() {
        rwLock.writeLock().lock();
        try {
            // Ordinamento decrescente per `rate`, poi ascendente per `name`
            List<Hotel> sorted = hotels.stream()
                    .sorted(Comparator.comparingInt((Hotel h) -> h.rate).reversed()
                            .thenComparing(h -> h.name))
                    .collect(Collectors.toList());

            int pos = 1;
            for (Hotel h : sorted) {
                h.ranking = pos++;
            }
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /** Ritorna la lista ordinata per ranking (più alto per primi). */
    public List<Hotel> getHotelsOrderedByRanking() {
        rwLock.readLock().lock();
        try {
            return hotels.stream()
                    .sorted(Comparator.comparingInt(h -> h.ranking))
                    .collect(Collectors.toUnmodifiableList());
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /* ------------------------------------------------------------------ */
    /*                         SHUTDOWN / CLEANUP                          */
    /* ------------------------------------------------------------------ */

    /** Da chiamare prima di terminare il programma (salva i dati). */
    public void shutdown() {
        saveHotelsToJson();
        System.out.println("[INFO] HOTELIERServer shut down.");
    }

    /* ------------------------------------------------------------------ */
    /*                         MAIN (demo)                                 */
    /* ------------------------------------------------------------------ */

    public static void main(String[] args) {
        // Percorso di default: nella cartella corrente
        String jsonPath = "Hotels.json";

        // Inizializza il server
        HOTELIERServer server = new HOTELIERServer(jsonPath);

        // ------------------- DEMO FUNZIONI -------------------
        System.out.println("\n=== LISTA HOTEL (ordinata per ranking) ===");
        server.getHotelsOrderedByRanking()
                .forEach(System.out::println);

        // Aggiungiamo un nuovo hotel (solo a scopo dimostrativo)
        Hotel newHotel = new Hotel(999, "Sunrise Boutique");
        newHotel.city = "Napoli";
        newHotel.phone = "+39 081 1234567";
        newHotel.services = List.of("wifi", "breakfast", "parking");
        server.addHotel(newHotel);
        System.out.println("\n[+] Aggiunto: " + newHotel.name);

        // Aggiorniamo qualche rating
        server.updateRating(999, "cleaning", 4);
        server.updateRating(999, "position", 5);
        server.updateRating(999, "services", 3);
        server.updateRating(999, "quality", 4);

        System.out.println("\n=== HOTEL APPENA VALUTATO ===");
        System.out.println(server.findById(999));

        // Visualizziamo di nuovo la classifica
        System.out.println("\n=== CLASSIFICA AGGIORNATA ===");
        server.getHotelsOrderedByRanking()
                .forEach(System.out::println);

        // Salvataggio finale (viene anche chiamato dallo shutdown)
        server.shutdown();
    }
}
```

