        Long id;
        @Column(nullable = false, unique = true) String username;
        @Column(nullable = false) String password;
    }

    // ---------- Repository ----------
    interface UserRepository extends JpaRepository<User, Long> {
        Optional<User> findByUsername(String username);
    }

    // ---------- JWT Util ----------
    @Component
    static class JwtUtil {
        private final Key key;
        private final long expireSec;
        JwtUtil(@Value("${jwt.secret}") String secret,
                @Value("${jwt.expiration}") long exp) {
            this.key = Keys.hmacShaKeyFor(secret.getBytes());
            this.expireSec = exp;
        }
        String generate(String username) {
