            Date exp = new Date(now.getTime() + expireSec*1000);
            return Jwts.builder()
                    .setSubject(username)
                    .setIssuedAt(now)
                    .setExpiration(exp)
                    .signWith(key, SignatureAlgorithm.HS256)
                    .compact();
        }
        String extract(String token) {
            return Jwts.parserBuilder().setSigningKey(key).build()
                    .parseClaimsJws(token).getBody().getSubject();
        }
        boolean validate(String token) {
            try {
                Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token);
                return true;
            } catch (JwtException e) { return false; }
        }
    }

    // ---------- Service ----------
    @Service
    @RequiredArgsConstructor
    static class AuthService {
        private final UserRepository repo;
        private final JwtUtil jwtUtil;
        private final PasswordEncoder encoder;
        String login(String username, String rawPwd) {
            User u = repo.findByUsername(username)
                    .orElseThrow(() -> new RuntimeException("Invalid"));
            if (!encoder.matches(rawPwd, u.getPassword())) {
                throw new RuntimeException("Invalid");
            }
            return jwtUtil.generate(u.getUsername());
        }
    }

    // ---------- Controller ----------
    @RestController @RequestMapping("/api/auth")
    @RequiredArgsConstructor
    static class AuthController {
        private final AuthService service;
        @PostMapping("/login")
        public ResponseEntity<Map<String,Object>> login(@RequestBody Map<String,String> body){
            String token = service.login(body.get("username"), body.get("password"));
            return ResponseEntity.ok(Map.of("token",token,"tokenType","Bearer"));
        }
    }

    // ---------- Security ----------
    @Component
    @RequiredArgsConstructor
    static class JwtFilter extends OncePerRequestFilter {
        private final JwtUtil jwtUtil;
        private final UserDetailsService uds;
        @Override
        protected void doFilterInternal(HttpServletRequest req, HttpServletResponse resp,
                                        FilterChain chain) throws ServletException, IOException {
            String auth = req.getHeader("Authorization");
            if (auth != null && auth.startsWith("Bearer ")) {
                String token = auth.substring(7);
                if (jwtUtil.validate(token)) {
                    String username = jwtUtil.extract(token);
                    UserDetails ud = uds.loadUserByUsername(username);
                    UsernamePasswordAuthenticationToken at =
                            new UsernamePasswordAuthenticationToken(ud, null, ud.getAuthorities());
                    SecurityContextHolder.getContext().setAuthentication(at);
                }
            }
            chain.doFilter(req, resp);
        }
    }

    @Service
    @RequiredArgsConstructor
    static class MyUserDetails implements UserDetailsService {
        private final UserRepository repo;
        @Override
        public UserDetails loadUserByUsername(String username) {
            User u = repo.findByUsername(username)
                    .orElseThrow(() -> new UsernameNotFoundException("Not"));
            return new org.springframework.security.core.userdetails.User(
                    u.getUsername(), u.getPassword(),
                    List.of(new SimpleGrantedAuthority("ROLE_USER")));
        }
    }

    @Configuration
    @RequiredArgsConstructor
    static class SecConfig {
        private final JwtFilter filter;
        @Bean
        SecurityFilterChain chain(HttpSecurity http) throws Exception {
