## 5. 完整示例：统一工具类（支持 TCP、HTTP、UDP）

下面把常用的几种检测封装进一个 **`PortUtil`** 类，供实际项目直接引用。

```java
package com.example.util;

import java.io.IOException;
import java.net.*;
import java.nio.channels.*;
import java.util.AbstractMap;
import java.util.Map;
import java.util.concurrent.*;

public final class PortUtil {

    private PortUtil() {} // 私有构造，防止实例化

    /** ------------------------------------------------------------
     *  1. TCP 端口检测（阻塞 Socket，推荐用于单次检测）
     * ------------------------------------------------------------- */
    public static boolean isTcpPortOpen(String host, int port, int timeoutMillis) {
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(host, port), timeoutMillis);
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    /** ------------------------------------------------------------
     *  2. TCP 端口检测（NIO 非阻塞，可用于批量并发检查）
     * ------------------------------------------------------------- */
    public static boolean isTcpPortOpenNio(String host, int port, int timeoutMillis) {
        try (SocketChannel sc = SocketChannel.open()) {
            sc.configureBlocking(false);
            sc.connect(new InetSocketAddress(host, port));

            try (Selector selector = Selector.open()) {
                sc.register(selector, SelectionKey.OP_CONNECT);
                long deadline = System.currentTimeMillis() + timeoutMillis;

                while (System.currentTimeMillis() < deadline) {
                    long remaining = deadline - System.currentTimeMillis();
                    if (selector.select(remaining) == 0) continue;
                    for (SelectionKey key : selector.selectedKeys()) {
                        if (key.isConnectable()) {
                            SocketChannel ch = (SocketChannel) key.channel();
                            if (ch.finishConnect()) return true;
                        }
                    }
                    selector.selectedKeys().clear();
                }
            }
        } catch (IOException ignored) {}
        return false;
    }

    /** ------------------------------------------------------------
     *  3. HTTP/HTTPS 可用性检测（只请求 HEAD）
     * ------------------------------------------------------------- */
    public static boolean isHttpAlive(String urlString, int timeoutMillis) {
        try {
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setConnectTimeout(timeoutMillis);
            conn.setReadTimeout(timeoutMillis);
            conn.setRequestMethod("HEAD");
            int rc = conn.getResponseCode();
            return rc >= 200 && rc < 400;
        } catch (IOException e) {
            return false;
        }
    }

    /** ------------------------------------------------------------
     *  4. UDP 端口检测（发送数据并等待任意响应）
     * ------------------------------------------------------------- */
    public static boolean isUdpPortOpen(String host, int port, int timeoutMillis) {
        try (DatagramSocket ds = new DatagramSocket()) {
            ds.setSoTimeout(timeoutMillis);
            byte[] data = "ping".getBytes();
            DatagramPacket out = new DatagramPacket(data, data.length,
                    InetAddress.getByName(host), port);
            ds.send(out);
            // 等待回应
            byte[] buf = new byte[256];
            DatagramPacket in = new DatagramPacket(buf, buf.length);
            ds.receive(in);
            return true;
        } catch (SocketTimeoutException e) {
            // 没收到任何数据（可能端口关闭或防火墙过滤）
            return false;
        } catch (IOException e) {
            return false;
        }
    }

    /** ------------------------------------------------------------
     *  5. 批量并发检测（示例：检查多个 host:port 的 TCP 状态）
     * ------------------------------------------------------------- */
    public static Map<String, Boolean> checkBulkTcp(
            Map<String, Integer> hostPortMap, int timeoutMillis) {

        ExecutorService pool = Executors.newFixedThreadPool(
                Math.min(hostPortMap.size(), Runtime.getRuntime().availableProcessors() * 2));

        try {
            List<CompletableFuture<Map.Entry<String, Boolean>>> futures = hostPortMap.entrySet()
                    .stream()
                    .map(entry -> CompletableFuture.supplyAsync(() -> {
                        String key = entry.getKey() + ":" + entry.getValue();
                        boolean ok = isTcpPortOpen(entry.getKey(), entry.getValue(), timeoutMillis);
                        return new AbstractMap.SimpleEntry<>(key, ok);
                    }, pool))
                    .toList();

            return futures.stream()
                    .map(CompletableFuture::join)
                    .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
        } finally {
            pool.shutdown();
        }
    }
}
```

### 使用方式（示例）

```java
public class Demo {
    public static void main(String[] args) {
        // 1️⃣ TCP 检测
        System.out.println("TCP 80 reachable? " +
                PortUtil.isTcpPortOpen("www.google.com", 80, 3000));

        // 2️⃣ HTTP 检测
        System.out.println("HTTPS alive? " +
                PortUtil.isHttpAlive("https://www.google.com", 3000));

        // 3️⃣ UDP 检测（假设有回显服务）
        System.out.println("UDP 53 reachable? " +
                PortUtil.isUdpPortOpen("8.8.8.8", 53, 2000));

        // 4️⃣ 批量检查
        Map<String, Integer> targets = Map.of(
                "www.google.com", 80,
                "www.github.com", 443,
                "localhost", 22);
        System.out.println("Bulk result: " + PortUtil.checkBulkTcp(targets, 2000));
    }
}
```

