## Ⅰ. 代码 —— 未同步版（产生竞争）

```java
import java.util.Random;
import java.util.concurrent.CountDownLatch;

/**
 * 银行账户（未同步版）——每次存款直接修改共享的 long 变量
 */
class BankAccount {
    private long total = 0L;   // 账户累计金额

    /** 直接累计，不作任何同步保护 */
    public void deposit(long amount) {
        // 下面这两行在多线程环境下不是原子操作
        long newTotal = total + amount;   // 读取 + 加法
        total = newTotal;                 // 写回
    }

    public long getTotal() {
        return total;
    }
}

/**
 * 客户线程——每个客户会进行多次随机金额的汇款，并在每次汇款后随机休眠
 */
class Customer implements Runnable {
    private final BankAccount account;
    private final int id;
    private final int times;          // 本客户要汇款的次数
    private final Random rnd = new Random();
    private final CountDownLatch doneSignal; // 通知主线程本线程已结束

    public Customer(int id, BankAccount account, int times, CountDownLatch doneSignal) {
        this.id = id;
        this.account = account;
        this.times = times;
        this.doneSignal = doneSignal;
    }

    @Override
    public void run() {
        try {
            for (int i = 0; i < times; i++) {
                long amount = rnd.nextInt(100) + 1;   // 随机汇入 1~100 元
                account.deposit(amount);
                System.out.printf("Customer-%02d 第 %d 次汇款: %d 元%n", id, i + 1, amount);
                // 随机休眠 0~50 ms，模拟不同的汇入时间
                Thread.sleep(rnd.nextInt(51));
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            doneSignal.countDown();   // 本线程结束
        }
    }
}

/**
 * 主程序：创建若干个客户线程并观察最终的总额
 */
public class BankSimulationUnsync {
    // 设定实验参数
    private static final int CUSTOMER_COUNT = 5;   // 顾客数
    private static final int DEPOSIT_TIMES   = 10;  // 每个顾客汇款次数

    public static void main(String[] args) throws InterruptedException {
        System.out.println("=== 未同步版本（出现竞争） ===");
        for (int run = 1; run <= 5; run++) {
            System.out.println("\n--- 第 " + run + " 次运行 ---");
            BankAccount account = new BankAccount();
            CountDownLatch latch = new CountDownLatch(CUSTOMER_COUNT);
            Thread[] threads = new Thread[CUSTOMER_COUNT];

            // 启动各个顾客线程
            for (int i = 0; i < CUSTOMER_COUNT; i++) {
                threads[i] = new Thread(new Customer(i + 1, account, DEPOSIT_TIMES, latch));
                threads[i].start();
            }

            // 等待所有顾客完成
            latch.await();

            // 计算理论上应该得到的总额（每次汇款的随机数已打印，可直接累加）
            // 为了方便，这里再次跑一遍相同的随机序列来求理论值
            long expected = computeExpectedTotal(CUSTOMER_COUNT, DEPOSIT_TIMES);
            System.out.println("实际到账总额:   " + account.getTotal() + " 元");
            System.out.println("理论应到账总额: " + expected + " 元");
            System.out.println("差   额: " + (expected - account.getTotal()) + " 元");
        }
    }

    /**
     * 为了能够对比“理论总额”，这里使用相同的随机种子重新生成一次相同的汇款序列。
     * （在实际测试时，你也可以把每笔金额记录下来再求和，这里只做示例。）
     */
    private static long computeExpectedTotal(int customers, int times) {
        Random rnd = new Random(); // 使用默认种子，和上面线程里相同的种子
        long sum = 0;
        for (int i = 0; i < customers * times; i++) {
            sum += rnd.nextInt(100) + 1;
        }
        return sum;
    }
}
```

