  await page.select('#billingCountry', TEST_DATA.billingCountry);

  // -----------------------------------------------------------------
  // 🔟  Click the *Pay* button
  // -----------------------------------------------------------------
  console.log('🚀 Submitting payment …');
  await page.waitForSelector('.SubmitButton', { visible: true });
  // Use `page.evaluate` to click via the DOM – more reliable when the button is covered by an overlay.
  await page.evaluate(() => {
