### 3.5 Contrôleur d’affectation (logique métier)

```js
// src/controllers/housingController.js
const Housing = require('../models/Housing');
const User = require('../models/User');

// … autres fonctions getAll / createHousing …

exports.assignStudent = async (req, res, next) => {
  try {
    const housingId = req.params.id;
    const { studentId } = req.body; // id du user (student)

    const housing = await Housing.findById(housingId);
    if (!housing) return res.status(404).json({ message: 'Logement inconnu' });
    if (housing.available <= 0) return res.status(400).json({ message: 'Plus de place disponible' });

    const student = await User.findById(studentId);
    if (!student || student.role !== 'student')
      return res.status(400).json({ message: 'Étudiant invalide' });
    if (student.housing) return res.status(400).json({ message: 'Déjà logé' });

    // mise à jour
    housing.occupied += 1;
    await housing.save();

    student.housing = housing._id;
    await student.save();

    res.json({ message: 'Étudiant assigné', housing });
  } catch (err) {
    next(err);
  }
};

exports.releaseStudent = async (req, res, next) => {
  try {
    const housingId = req.params.id;
    const { studentId } = req.body;

    const housing = await Housing.findById(housingId);
    const student = await User.findById(studentId);

    if (!housing || !student) return res.status(404).json({ message: 'Pas trouvé' });
    if (!student.housing?.equals(housing._id))
      return res.status(400).json({ message: 'L’étudiant n’est pas dans ce logement' });

    housing.occupied -= 1;
    await housing.save();

    student.housing = undefined;
    await student.save();

    res.json({ message: 'Étudiant libéré', housing });
  } catch (err) {
    next(err);
  }
};
```

