// src/pages/ManagerDashboard.jsx
import { useEffect, useState } from 'react';
import axios from 'axios';
import {
  Container,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  TextField,
} from '@mui/material';

export const ManagerDashboard = () => {
  const [housings, setHousings] = useState([]);
  const [students, setStudents] = useState([]);
  const [assignDialog, setAssignDialog] = useState({ open: false, housingId: null });

  const fetchData = async () => {
    const [{ data: h }, { data: s }] = await Promise.all([
      axios.get('/housings'),
      axios.get('/users?role=student&housing=null'), // endpoint à créer côté API
    ]);
    setHousings(h);
    setStudents(s);
  };

  useEffect(() => { fetchData(); }, []);

  const openAssign = (housingId) => setAssignDialog({ open: true, housingId });
  const closeAssign = () => setAssignDialog({ open: false, housingId: null });

  const handleAssign = async (studentId) => {
    await axios.post(`/housings/${assignDialog.housingId}/assign`, { studentId });
    closeAssign();
    fetchData();
  };

  return (
    <Container sx={{ mt: 4 }}>
      <Typography variant="h4" gutterBottom>
        Gestion des logements
      </Typography>

      <Grid container spacing={3}>
        {housings.map((h) => (
