                <Typography variant="h6">{h.name}</Typography>
                <Typography>Capacité : {h.capacity}</Typography>
                <Typography>Occupé : {h.occupied}</Typography>
                <Typography>Disponible : {h.capacity - h.occupied}</Typography>
                <Button
                  variant="contained"
                  sx={{ mt: 1 }}
                  disabled={h.capacity - h.occupied === 0}
                  onClick={() => openAssign(h._id)}
                >
                  Affecter un étudiant
                </Button>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* ---------- Dialogue d’affectation ---------- */}
      <Dialog open={assignDialog.open} onClose={closeAssign}>
        <DialogTitle>Choisir l’étudiant à loger</DialogTitle>
        <DialogContent>
          {students.map((s) => (
            <Button
              key={s._id}
              fullWidth
              sx={{ mb: 1 }}
              onClick={() => handleAssign(s._id)}
            >
              {s.firstName} {s.lastName} ({s.studentId})
            </Button>
          ))}
          {students.length === 0 && <Typography>Aucun étudiant disponible</Typography>}
        </DialogContent>
      </Dialog>
    </Container>
  );
};
