<body>
<canvas id="c"></canvas>

<div id="vmcMenu" class="menu"><button id="addLineBtn">Add line</button></div>
<div id="status">Mode: <span id="modeLabel">draw</span> | Rot: <span id="rotLabel">0,0</span></div>

<script>
/* ============================================================= *
 * 3‑D Wireframe Matrix Constructor – pure JavaScript + Canvas   *
 * ============================================================= */

const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const vmcMenu = document.getElementById('vmcMenu');
const addLineBtn = document.getElementById('addLineBtn');
const modeLabel = document.getElementById('modeLabel');
const rotLabel = document.getElementById('rotLabel');

let w, h;
function resize(){
    w = canvas.width = innerWidth;
    h = canvas.height = innerHeight;
}
window.addEventListener('resize', resize);
resize();

/* ------------------- 3‑D data structures -------------------- */
const GRID_SIZE = 8;          // from -GRID_SIZE … +GRID_SIZE
const GRID_STEP = 2;          // distance between consecutive points
const POINT_RADIUS = 4;       // screen radius for snap points
const SNAP_DIST = 12;         // max pixel distance to consider a snap

let gridPoints = [];          // {x,y,z}
let modelLines = [];          // {a:{x,y,z}, b:{x,y,z}}
let tempLine = null;          // {a:{x,y,z}, b:{x,y,z}} while drawing
let unsnapMode = false;       // true → can start from any screen point
let drawing = false;          // true while a line is being drawn
let startSnap = null;         // point where current line started

/* ------------------- Build the grid ------------------------ */
for(let x=-GRID_SIZE;x<=GRID_SIZE;x+=GRID_STEP){
    for(let y=-GRID_SIZE;y<=GRID_SIZE;y+=GRID_STEP){
        for(let z=-GRID_SIZE;z<=GRID_SIZE;z+=GRID_STEP){
            gridPoints.push({x,y,z});
        }
    }
}

/* ------------------- Camera & projection ------------------- */
let rotX = 0.4;               // initial rotation (radians)
let rotY = -0.6;
let rotZ = 0;
const FOCAL = 400;            // perspective focal length

function rotate(p){
    // simple Euler rotation: Y → X → Z (Z not used but kept for completeness)
    const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
    const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
    const cosZ = Math.cos(rotZ), sinZ = Math.sin(rotZ);

    // rotate around Y
    let x1 =  p.x*cosY - p.z*sinY;
    let z1 =  p.x*sinY + p.z*cosY;
    let y1 =  p.y;

    // rotate around X
    let y2 =  y1*cosX - z1*sinX;
    let z2 =  y1*sinX + z1*cosX;
    let x2 =  x1;

    // rotate around Z (optional – not needed for this demo)
    let x3 =  x2*cosZ - y2*sinZ;
    let y3 =  x2*sinZ + y2*cosZ;
    let z3 =  z2;

    return {x:x3, y:y3, z:z3};
}

function project(p){
    // perspective divide
    const scale = FOCAL/(FOCAL + p.z);
    return {
        x: p.x*scale,
        y: p.y*scale
    };
}

function worldToScreen(p){
    const r = rotate(p);
