function drawTemp(){
    if(!tempLine) return;
    const a = worldToScreen(tempLine.a);
    const b = worldToScreen(tempLine.b);
    ctx.strokeStyle = '#ff0';
    ctx.lineWidth = 2;
    ctx.setLineDash([5,5]);
    ctx.beginPath();
