    drawTemp();
    rotLabel.textContent = `${rotX.toFixed(2)},${rotY.toFixed(2)}`;
}

/* ------------------- Interaction --------------------------- */
let mouse = {x:0,y:0};
let lastMouse = {x:0,y:0};
let dragging = false;           // true while right‑mouse rotates

canvas.addEventListener('mousemove', e=>{
