        vmcMenu.style.display = 'block';
        startSnap = nearest;   // store for Add‑line click
    }else{
        if(!drawing) vmcMenu.style.display='none';
    }

    // while rotating with right button
    if(dragging && !drawing){
        const dx = mouse.x - lastMouse.x;
        const dy = mouse.y - lastMouse.y;
        rotY += dx*0.005;
        rotX += dy*0.005;
    }
    lastMouse.x = mouse.x;
    lastMouse.y = mouse.y;

