  const { email, password } = req.body;

  // prosta walidacja
  if (!email || !password) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  // sprawdź, czy e‑mail już istnieje
  const existing = await db('users').where({ email }).first();
  if (existing) {
    return res.status(409).json({ error: 'E‑mail already used' });
  }

  const passwordHash = await bcrypt.hash(password, 12);
  const token = generateToken();
  const tokenExpires = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 h

  // zapisujemy rekord z is_verified = false
  const [userId] = await db('users')
    .insert({
      email,
      password_hash: passwordHash,
      verification_token: token,
      token_expires_at: tokenExpires,
    })
    .returning('id');

  // wysyłamy e‑mail weryfikacyjny
  const verifyUrl = `${process.env.APP_URL}/api/verify?token=${token}`;
  await transporter.sendMail({
    from: `"No‑Reply" <${process.env.SMTP_USER}>`,
    to: email,
    subject: 'Potwierdź swój adres e‑mail',
    html: `
      <p>Dziękujemy za rejestrację! Kliknij poniższy link, aby aktywować konto:</p>
      <a href="${verifyUrl}">${verifyUrl}</a>
      <p>Link ważny jest przez 24 h.</p>
    `,
  });

  res.json({ message: 'Registered – check your email' });
});

// ---------- 2. Weryfikacja linku ----------
app.get('/api/verify', async (req, res) => {
  const { token } = req.query;
  if (!token) return res.status(400).send('Missing token');

  // Znajdujemy użytkownika po tokenie i sprawdzamy datę ważności
  const user = await db('users')
    .where({ verification_token: token })
    .andWhere('token_expires_at', '>', db.fn.now())
    .first();

  if (!user) return res.status(400).send('Invalid or expired token');

  // Aktualizujemy status – TO JEST KLUCZOWY MOMENT NA ZAPISANIE "ZAREJESTROWANY"
  await db('users')
    .where({ id: user.id })
    .update({
      is_verified: true,
      verification_token: null,
      token_expires_at: null,
      updated_at: db.fn.now(),
    });

  // Tworzymy JWT, który będzie ciasteczkiem HttpOnly
  const payload = { id: user.id, email: user.email, is_verified: true };
  const accessToken = jwt.sign(payload, process.env.JWT_SECRET, {
    expiresIn: '7d',
  });

  // Ustawiamy ciasteczko i przekierowujemy do panelu
  res
    .cookie('auth_token', accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 dni
    })
    .redirect('/dashboard.html'); // plik HTML z UI po zalogowaniu
});

// ---------- 3. Endpoint "me" – informacja o aktualnym użytkowniku ----------
app.get(
  '/api/me',
  expressjwt({
    secret: process.env.JWT_SECRET,
    algorithms: ['HS256'],
    getToken: (req) => req.cookies.auth_token,
    credentialsRequired: false, // może być nieautoryzowany – zwrócimy 401
  }),
  (req, res) => {
    if (!req.auth) {
      return res.status(401).json({ error: 'Not authenticated' });
    }
    // w payloadzie już jest is_verified
    res.json({ email: req.auth.email, is_verified: req.auth.is_verified });
  }
);

// ---------- 4. Przykładowy chroniony zasób ----------
app.get(
  '/api/profile',
  expressjwt({ secret: process.env.JWT_SECRET, algorithms: ['HS256'], getToken: req => req.cookies.auth_token }),
  (req, res) => {
    if (!req.auth.is_verified) {
      return res.status(403).json({ error: 'Account not verified' });
    }
    // zwróć dowolne dane profilu
    res.json({ message: `Witaj ${req.auth.email}!` });
  }
);

// ---------- 5. Logout ----------
app.post('/api/logout', (req, res) => {
  res.clearCookie('auth_token').json({ message: 'Logged out' });
});

// ---------- Uruchomienie serwera ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
```

