Below is a **ready‑to‑use, opinionated Axios HTTP client** that you can drop into any React (or React‑Native) project.  

It includes:

1. **A singleton Axios instance** (`api`) with a base URL that automatically picks up your environment (`.env`).
2. **Request interceptor** – attaches an auth token (if you store it in `localStorage`, `sessionStorage`, or a React context) and serialises query parameters.
3. **Response interceptor** – unwraps the API payload, normalises error handling, and optionally triggers a global “logout” on 401.
4. **Typed helper functions** (`get`, `post`, `put`, `patch`, `del`) that return the `data` field directly (so you don’t have to write `response.data` everywhere).
5. **A React hook (`useApi`)** for quick use inside components (optional but handy).
6. **Full TypeScript definitions** (but you can strip the types if you’re using plain JavaScript).

---

## 1️⃣ Project Setup

```bash
# If you haven’t installed axios yet:
npm i axios

# If you are using TypeScript:
npm i -D @types/axios
```

Add a `.env` (or `.env.development`, `.env.production`) file at the root of your project:

```dotenv
# .env
REACT_APP_API_BASE_URL=https://api.example.com/v1
REACT_APP_AUTH_HEADER=Authorization   # optional – header name you prefer
```

> **Tip** – In a Create‑React‑App (CRA) or Vite project, any env variable that starts with `REACT_APP_` (CRA) or `VITE_` (Vite) will be exposed to the client bundle. Adjust the prefix as needed for your bundler.

---

## 2️⃣ `src/api/apiClient.ts` – The core Axios client

```ts
// src/api/apiClient.ts
import axios, {
  AxiosInstance,
  AxiosRequestConfig,
  AxiosResponse,
  InternalAxiosRequestConfig,
} from 'axios';

/**
 * --------------------------------------------------------------
 * 1️⃣   CONFIGURATION
 * --------------------------------------------------------------
 */
const BASE_URL = process.env.REACT_APP_API_BASE_URL ?? '';

const instance: AxiosInstance = axios.create({
  baseURL: BASE_URL,
  timeout: 12_000,                     // 12 seconds – adjust to your needs
  headers: {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  },
});

/**
 * --------------------------------------------------------------
 * 2️⃣   REQUEST INTERCEPTOR
 * --------------------------------------------------------------
 *
 * Typical responsibilities:
 *   - Attach JWT / Bearer token
 *   - Serialize GET params (optional)
 *   - Log request in dev
 */
instance.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    // ----- Auth token -------------------------------------------------
    const token = localStorage.getItem('access_token'); // or read from context/state
    const authHeader = process.env.REACT_APP_AUTH_HEADER ?? 'Authorization';

    if (token) {
      config.headers[authHeader] = `Bearer ${token}`;
    }

    // ----- Optional: pretty‑print query params for GET requests -----
    if (config.method?.toLowerCase() === 'get' && config.params) {
      // Axios already serialises params, but you can customise if needed.
      // Example: encode arrays as comma‑separated values:
      // config.paramsSerializer = params => qs.stringify(params, { arrayFormat: 'comma' });
    }

    // ----- Dev logging -------------------------------------------------
    if (process.env.NODE_ENV === 'development') {
      console.debug('[API REQUEST]', config.method?.toUpperCase(), config.url, config);
    }

    return config;
  },
  (error) => {
    // Something went wrong before the request was sent
    return Promise.reject(error);
  }
);

/**
 * --------------------------------------------------------------
 * 3️⃣   RESPONSE INTERCEPTOR
 * --------------------------------------------------------------
 *
 * We assume the API returns a consistent envelope, e.g.
 *   { data: <payload>, error?: null, message?: string }
 *
 * You can adjust this part to match your backend contract.
 */
interface ApiEnvelope<T = unknown> {
  data: T;
  error?: string | null;
  message?: string;
}

instance.interceptors.response.use(
  (response: AxiosResponse<ApiEnvelope>) => {
    // ---- Unwrap payload -------------------------------------------------
    // If your API returns raw data (no envelope), simply `return response`.
    const { data } = response;
    // You now have { data, error, message }
    if (data?.error) {
      // Normalize "business error" to a rejected promise
      return Promise.reject(
        Object.assign(new Error(data.error ?? 'API error'), { response })
      );
    }
    return data.data; // <<< Returns the actual payload
  },

  (error) => {
    // ---- Global error handling -----------------------------------------
    const { response } = error;

    if (!response) {
      // Network error (timeout, DNS, CORS, etc.)
      console.error('[API] Network error', error);
      return Promise.reject(new Error('Network error – please try again.'));
    }

    // 401 → maybe token expired → force logout
    if (response.status === 401) {
      // Example: a simple logout helper
      // logout(); // you can import a store action, context, etc.
      console.warn('[API] Unauthorized – logging out');
    }

    // 403, 404, 500… customize as you need
    const msg = response?.data?.message ?? response.statusText;
    console.error(`[API] ${response.status} – ${msg}`, response);

    // Attach the original response for downstream handling
    return Promise.reject(Object.assign(new Error(msg), { response }));
  }
);

/**
 * --------------------------------------------------------------
 * 4️⃣   SIMPLE METHOD WRAPPERS
 * --------------------------------------------------------------
 *
 * These functions return the unwrapped `data` payload directly.
 * Use them exactly like the native fetch API – they also accept a generic
 * to get proper typing.
 */

export const api = {
  /**
   * GET /resource?query=…
   */
  get: <T = unknown>(url: string, config?: AxiosRequestConfig) =>
    instance.get<T, T>(url, config),

  /**
   * POST /resource   (body: any)
   */
  post: <T = unknown, B = unknown>(url: string, body?: B, config?: AxiosRequestConfig) =>
    instance.post<T, T>(url, body, config),

  /**
   * PUT /resource/:id
   */
  put: <T = unknown, B = unknown>(url: string, body?: B, config?: AxiosRequestConfig) =>
    instance.put<T, T>(url, body, config),

  /**
   * PATCH /resource/:id
   */
  patch: <T = unknown, B = unknown>(url: string, body?: B, config?: AxiosRequestConfig) =>
    instance.patch<T, T>(url, body, config),

  /**
   * DELETE /resource/:id
   */
  del: <T = unknown>(url: string, config?: AxiosRequestConfig) =>
    instance.delete<T, T>(url, config),

  /**
   * The raw Axios instance (if you need something extra)
   */
  raw: instance,
};

/**
 * --------------------------------------------------------------
 * 5️⃣   OPTIONAL: A tiny React hook for on‑the‑fly calls
 * --------------------------------------------------------------
 *
 * Usage:
 *   const { data, error, loading, fetch } = useApi('/users', { method: 'GET' });
 */
import { useState, useCallback } from 'react';

export const useApi = <T = unknown>(
  url: string,
  {
    method = 'GET',
    body = null,
    immediate = true,
    ...axiosConfig
  }: {
    method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
    body?: any;
    immediate?: boolean;
  } & AxiosRequestConfig = {}
) => {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState(immediate);

  const fetch = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await instance.request<T>({
        url,
        method,
        data: body,
        ...axiosConfig,
      });
      setData(response);
    } catch (err: any) {
      setError(err);
    } finally {
      setLoading(false);
    }
  }, [url, method, body, axiosConfig]);

  // Auto‑run on mount if `immediate === true`
  if (immediate) {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    // (Rare case: this call lives inside a component, not a custom hook)
    // In a real hook you’d use `useEffect(() => { fetch(); }, [fetch]);`
  }

  return { data, error, loading, fetch };
};

export default api; // easier to import as `import api from './api/apiClient'`
```

