## 3️⃣ How to **use** the client in a component

### a) Simple one‑off request

```tsx
// src/components/UserList.tsx
import React, { useEffect, useState } from 'react';
import api from '../api/apiClient';

interface User {
  id: string;
  name: string;
  email: string;
}

export const UserList: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    api
      .get<User[]>('/users')
      .then(setUsers)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Loading users…</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>
          {u.name} – {u.email}
        </li>
      ))}
    </ul>
  );
};
```

### b) Using the **`useApi`** hook (great for forms, buttons, etc.)

```tsx
// src/components/CreateUserForm.tsx
import React, { useState } from 'react';
import { useApi } from '../api/apiClient';

interface NewUser {
  name: string;
  email: string;
  password: string;
}

export const CreateUserForm: React.FC = () => {
  const [form, setForm] = useState<NewUser>({ name: '', email: '', password: '' });
  const { data, error, loading, fetch } = useApi<{ id: string }>(`/users`, {
    method: 'POST',
    body: form,
    immediate: false, // we’ll call it manually on submit
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await fetch(); // triggers the request
    if (data?.id) {
      alert(`User created! ID: ${data.id}`);
      setForm({ name: '', email: '', password: '' });
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* ...form fields (omitted for brevity) */}
      <input
        placeholder="Name"
        value={form.name}
        onChange={(e) => setForm({ ...form, name: e.target.value })}
        required
      />
      <input
        placeholder="Email"
        type="email"
        value={form.email}
        onChange={(e) => setForm({ ...form, email: e.target.value })}
        required
      />
      <input
        placeholder="Password"
        type="password"
        value={form.password}
        onChange={(e) => setForm({ ...form, password: e.target.value })}
        required
      />

      <button type="submit" disabled={loading}>
        {loading ? 'Creating…' : 'Create user'}
      </button>

      {error && <p style={{ color: 'red' }}>{error.message}</p>}
    </form>
  );
};
```

