    }
    return Promise.reject(err);
  }
);

/* Helper methods – return payload directly */
export const client = {
  get: <T>(url: string, cfg?: AxiosRequestConfig) => api.get<T, T>(url, cfg),
  post: <T, B>(url: string, body?: B, cfg?: AxiosRequestConfig) =>
    api.post<T, T>(url, body, cfg),
  put: <T, B>(url: string, body?: B, cfg?: AxiosRequestConfig) =>
    api.put<T, T>(url, body, cfg),
  patch: <T, B>(url: string, body?: B, cfg?: AxiosRequestConfig) =>
    api.patch<T, T>(url, body, cfg),
  del: <T>(url: string, cfg?: AxiosRequestConfig) => api.delete<T, T>(url, cfg),
  raw: api,
};

export default client;
```

Now you have a **single, type‑safe, centrally‑configured Axios client** that can be imported anywhere:

```tsx
import api from '@/api/apiClient';

api.get<User[]>('/users').then(setUsers);
```

Happy coding! 🚀

