### TL;DR  
* **`multer` already puts every non‑file part of a multipart request into `req.body`.**  
* The JSON‑string you send in the **`data`** field can be turned into a real object with `JSON.parse`.  
* To get a **Base‑64 representation of the uploaded file** you either (a) store the file in memory (`multer.memoryStorage()`) and call `file.buffer.toString('base64')` or (b) read the file from disk (`fs.readFileSync(file.path, 'base64')`).  

Below is a complete, ready‑to‑copy example that shows:

1. How to configure Multer (memory vs. disk).  
2. How to extract `orderId`, `LabID` (and any other fields) from the `data` part.  
3. How to turn the file into a Base‑64 string.  
4. A clean, async/await‑friendly error handling pattern.

---

## 1️⃣  Set‑up Multer

```js
// ──────────────────────────────────────────────────────────────
//  Choose ONE of the following storage strategies
// ──────────────────────────────────────────────────────────────

// 1️⃣  In‑memory (no temp files on disk) – perfect for Base64 conversion
const multer = require('multer');
const upload = multer({ storage: multer.memoryStorage() });

// ──────────────────────────────────────────────────────────────
// 2️⃣  Disk‑based (stores a temp file under /tmp or a custom folder)
// const upload = multer({ dest: 'uploads/' });   // <-- comment out #1 if you use this
// ──────────────────────────────────────────────────────────────
```

> **Why memory storage?**  
> When you only need the file to be turned into a Base64 string there’s no reason to write it to disk first – it saves an I/O round‑trip and automatically cleans up after the request ends.

---

## 2️⃣  The Express route

```js
const express   = require('express');
const fs        = require('fs');
const logger    = require('./logger');           // whatever logger you use

const router = express.Router();

router.post(
  '/api/lab/accept-lab-reports',
  upload.single('file'),          // <-- “file” matches the name in the curl form
  async (req, res) => {
    try {
      // ------------------------------------------------------------
      // 2️⃣  1️⃣  Grab the uploaded file (multer guarantees it exists)
      // ------------------------------------------------------------
      const file = req.file;                     // { originalname, mimetype, buffer, etc. }

      if (!file) {
        return res.status(400).json({ error: 'No file supplied' });
      }

      // ------------------------------------------------------------
      // 2️⃣  2️⃣  Extract the JSON that you sent under the "data" field
      // ------------------------------------------------------------
      // Multer puts every non‑file part into req.body as a *string*.
      // In your curl you called that part "data".
      const rawData = req.body.data;           // => '{"orderId":"2023/270/4","LabID":"RN885181"}'

      if (!rawData) {
        return res.status(400).json({ error: 'Missing `data` field' });
      }

      let payload;
      try {
        payload = JSON.parse(rawData);
      } catch (e) {
        return res.status(400).json({ error: 'Invalid JSON in `data` field' });
      }

      const { orderId, LabID, reportStatus } = payload;   // reportStatus is optional

      // ------------------------------------------------------------
      // 2️⃣  3️⃣  Validate the mandatory fields
      // ------------------------------------------------------------
      if (!orderId || !LabID) {
        const msg = 'orderId and LabID are required';
        logger.error(msg);
        return res.status(400).json({ error: msg });
      }

      // ------------------------------------------------------------
      // 2️⃣  4️⃣  Create the Base64 string
      // ------------------------------------------------------------
      //   • If you used memoryStorage → file.buffer already holds the whole file.
      //   • If you used disk storage   → file.path points to the temp file.
      let base64String;

      if (file.buffer) {                         // memory storage case
        base64String = file.buffer.toString('base64');
      } else {                                   // disk storage case
        base64String = fs.readFileSync(file.path, { encoding: 'base64' });
      }

      // ------------------------------------------------------------
      // 2️⃣  5️⃣  Pass the data wherever you need (your postReceivedAttachment)
      // ------------------------------------------------------------
      // Example signature you already have:
      // await postReceivedAttachment(orderId, LabID, file);
      // → modify it to accept the Base64 string if you need it there:
      await postReceivedAttachment(orderId, LabID, {
        originalname: file.originalname,
        mimetype:     file.mimetype,
        base64:       base64String,
        // any other meta you want to keep
      });

      // ------------------------------------------------------------
      // 2️⃣  6️⃣  Respond success
      // ------------------------------------------------------------
      return res.json({
        Status:        'SUCCESS',
        StatusMessage: 'Attachment received',
        StatusCode:    0,
        orderId,
        LabID,
      });

    } catch (err) {
      // ------------------------------------------------------------
      // 2️⃣  7️⃣  Centralised error handling
      // ------------------------------------------------------------
      console.error('Error during Lab Result Attachment processing:', err);
      logger.error(err);
      return res.status(500).json({
        Status:        'FAILED',
        StatusMessage: 'Internal Server Error',
        StatusCode:    1,
      });
    }
  }
);

module.exports = router;
```

### What changed / why it works

| Step | What you had | What you need now | Explanation |
|------|--------------|-------------------|-------------|
| **Reading `orderId` & `LabID`** | `const { orderId, LabID, reportStatus } = req.body;` | `const { orderId, LabID, reportStatus } = JSON.parse(req.body.data);` | The request body is *multipart/form‑data*, not JSON. Multer only parses the **file**; the other parts are left as plain strings in `req.body`. The JSON you placed in the `data` part must be parsed manually. |
| **Getting the file** | `req.file` | Same (`req.file`) | Multer already populated `req.file`. No extra work. |
| **Base64** | – | `file.buffer.toString('base64')` **or** `fs.readFileSync(file.path, 'base64')` | With `memoryStorage` the whole file lives in `file.buffer`. `toString('base64')` converts it. With `diskStorage` you read the persisted temporary file. |
| **Error handling** | Some `return res.status(...).json(...)` | Consistent early‑return pattern + a single `catch` at the end | Makes the flow easier to read and guarantees you always send a response. |

---

## 3️⃣  How to call it from `curl`

You can keep the same `curl` you posted – it already sends a multipart payload with one file part (`file`) and a JSON‑string part (`data`).  

```bash
curl --location 'http://localhost:3462/api/lab/accept-lab-reports' \
  --header 'vendor: Anandlabs' \
  --header 'vendor_token: f441c3c7-ab5d-4e8c-8774-d3627c0acf69' \
  --form 'file=@"/Users/sai/Downloads/1716.pdf"' \
  --form 'data="{\"orderId\": \"2023/270/4\", \"LabID\": \"RN885181\"}";type=application/json'
```

> **Tip:** If you ever want to avoid having to wrap JSON inside a string, you can simply send each field as its own form part:

```bash
curl ... \
  --form 'file=@"/Users/sai/Downloads/1716.pdf"' \
  --form 'orderId=2023/270/4' \
  --form 'LabID=RN885181' \
  --form 'reportStatus=RECEIVED'
```

Then in Express you would just read `req.body.orderId`, `req.body.LabID`, etc., **without** any `JSON.parse`.

---

## 4️⃣  Full Minimal Example (run it in a single file)

```js
// server.js
const express = require('express');
const multer  = require('multer');

const upload  = multer({ storage: multer.memoryStorage() });
const app     = express();
const PORT    = 3462;

// Dummy implementation of your business‑logic function
async function postReceivedAttachment(orderId, LabID, fileInfo) {
  // e.g. store in DB, send to another service, etc.
  console.log('>>> Received:', { orderId, LabID, fileInfo: {size: fileInfo.base64.length} });
}

// Route
app.post(
  '/api/lab/accept-lab-reports',
  upload.single('file'),
  async (req, res) => {
    try {
      const file = req.file;
      if (!file) return res.status(400).json({ error: 'file missing' });

      const raw = req.body.data;
      if (!raw) return res.status(400).json({ error: '`data` field missing' });

      let payload;
      try { payload = JSON.parse(raw); }
      catch { return res.status(400).json({ error: 'invalid JSON in data' }); }

      const { orderId, LabID } = payload;
      if (!orderId || !LabID) return res.status(400).json({ error: 'orderId & LabID required' });

      const base64 = file.buffer.toString('base64');

      await postReceivedAttachment(orderId, LabID, {
        originalname: file.originalname,
        mimetype: file.mimetype,
        base64,
      });

      return res.json({ Status: 'SUCCESS' });
    } catch (e) {
      console.error(e);
      return res.status(500).json({ Status: 'FAILED' });
    }
  }
);

app.listen(PORT, () => console.log(`🚀 listening on ${PORT}`));
```

Just `node server.js` and hit the same `curl` command – you’ll see the Base‑64 string printed (its length, not the whole data, to keep the console tidy).

---

## 5️⃣  Recap – What you need to do

1. **Configure Multer** (memory storage is easiest for Base64).  
2. **Read the non‑file part** (`req.body.data`) and `JSON.parse` it.  
3. **Convert the uploaded file to Base64** using the buffer (`file.buffer.toString('base64')`).  
4. **Pass the data** to your downstream function (`postReceivedAttachment`).  
5. **Return a proper JSON response** and handle errors centrally.

That’s it! 🎉 Now you can accept the multipart request, grab the JSON payload, turn the PDF (or any other file) into a Base‑64 string, and process it however your service requires.

