// -------------------
bot.on('message', async ctx => {
  // Принимаем только сообщения из **приватных** чатов
  if (ctx.chat?.type !== 'private') return;

  // Если не указаны целевые группы – ничего не делаем
  if (targetGroups.length === 0) {
    await ctx.reply('⚙️ Не настроены целевые группы. Обратитесь к администратору.');
    return;
  }

  // Пересылаем оригинальное сообщение в каждую группу
  for (const groupId of targetGroups) {
