        });
      } else {
        // Прямой форвард сохраняет фото, документы, стикеры и т.д.
        await bot.api.forwardMessage(
          groupId,
          ctx.chat.id,
          ctx.message.message_id
        );
      }
    } catch (err) {
      // Ошибки будем логировать, но не падать
      console.error(`❗ Не удалось отправить сообщение в ${groupId}:`, err);
