## 8️⃣ Graceful shutdown & process signals

A production server must close DB connections, release the lock and stop accepting new requests **before** the process exits.

```js
// src/server.js
const http = require('http');
const app = require('./app');
const config = require('./config');
const logger = require('./services/logger')('porting-server');
const lock = require('./services/lock/lockManager');
const { closeMongoClient } = require('./services/db/mongodb');

const server = http.createServer(app);

function start() {
  server.listen(config.serverPort, () => {
    logger.info(`🚀 Server listening on ${config.serverPort}`);
  });
}

// ------------ graceful shutdown ------------
function shutdown(signal) {
  logger.info(`🛑 Received ${signal}. Closing server...`);
  server.close(async (err) => {
    if (err) {
      logger.error('Error while closing server', err);
      process.exit(1);
    }
    try {
      await lock.release();
      await closeMongoClient();
      logger.info('✅ Graceful shutdown complete');
      process.exit(0);
    } catch (e) {
      logger.error('Error during shutdown', e);
      process.exit(1);
    }
  });
}

// Capture termination signals
['SIGINT', 'SIGTERM', 'SIGQUIT'].forEach(sig => {
  process.on(sig, () => shutdown(sig));
});

// Catch uncaught exceptions / rejections (fallback)
process.on('uncaughtException', (err) => {
  logger.error('❗️ Uncaught Exception', err);
  shutdown('uncaughtException');
});
process.on('unhandledRejection', (reason) => {
  logger.error('❗️ Unhandled Rejection', reason);
  shutdown('unhandledRejection');
});

start();
```

**Why this matters**

* `server.close()` stops new connections while allowing existing ones to finish (`keep-alive` sockets).  
* The lock is explicitly released – otherwise a stale lock could block subsequent deployments.  
* Mongo client is closed to free resources.  
* Process exits **once** everything is cleaned up (no `process.exit(1)` in normal flow).

