```js
const { MongoClient } = require('mongodb');
const logger = require('../logger')('mongodb');

let client;

async function connect(url) {
  if (client) return client; // singleton

  const options = {
    useNewUrlParser: true,
    useUnifiedTopology: true,
    // poolSize, connectTimeoutMS, socketTimeoutMS can be tweaked
  };

  client = new MongoClient(url, options);
  await client.connect();
  logger.info('✅ Connected to MongoDB');
  return client;
}

function getDb(dbName) {
  if (!client) {
    throw new Error('Mongo client not initialized');
  }
  return client.db(dbName);
}

async function close() {
  if (client) {
    await client.close();
    logger.info('🔌 MongoDB connection closed');
    client = null;
  }
}

module.exports = { connect, getDb, close };
```

*Use this service inside `app.js` (or `initializeApp`) and inject the DB instance into models instead of letting each model open its own connection.*

