## Implementacja krok po kroku

Poniżej znajduje się kompletny, ale **czytelny** kod, który możesz wkleić do swojego pliku `decode.js`.  
Zawiera on wszystkie potrzebne zmiany oraz dodatkowe komentarze.

```js
/* --------------------------------------------------------------
   IMPORTY I PODSTAWOWA KONFIGURACJA
   -------------------------------------------------------------- */
const fs = require('fs');
const path = './nieistotne/05.06.js';   // <‑‑ zmień na własny plik

/* --------------------------------------------------------------
   GŁÓWNA FUNKCJA – uruchamia cały proces
   -------------------------------------------------------------- */
readAndDecodeAll()
  .then(results => {
    console.log('\n=== DECODED VALUES ===');
    results.forEach(r => {
      console.log(`${r.functionName}(${r.argValue}) => ${r.decoded}`);
    });
  })
  .catch(err => console.error(err));

/* --------------------------------------------------------------
   1️⃣  ODCZYT PLIKU + WYTWORZENIE LISTY FUNKCJI DO ODKODOWANIA
   -------------------------------------------------------------- */
function readAndDecodeAll() {
  return new Promise((resolve, reject) => {
    fs.readFile(path, 'utf-8', async (err, data) => {
      if (err) return reject(err);

      // ---- 1. Wyciągamy wszystkie deklaracje funkcji ---------------------------------
      const allFunctions = extractAllFunctions(data);

      // ---- 2. Filtrujemy te, które spełniają warunek „2 argumenty, jeden jest liczbą hex”
      const candidates = allFunctions.filter(fn => {
        // liczba argumentów = 2 ?
        const args = fn.args.split(',').map(a => a.trim()).filter(Boolean);
        if (args.length !== 2) return false;

        // czy któryś argument jest stałą szesnastkową?
        const hexRegex = /^0x[0-9a-f]+$/i;
        return args.some(arg => hexRegex.test(arg));
      });

      // ---- 3. Pobieramy dodatkowe informacje – tablicę i funkcję pomocniczą -----
      const { arr, func } = await getHelperStuff(); // zwraca e.arr i e.func

      // ---- 4. Dla każdego dopasowanego wywołujemy odkodowanie ----------------------
      const results = [];
      for (const fn of candidates) {
        const fpValue = extractFPValue(fn.body); // to, co w Twoim kodzie było w extractFPValue
        if (!fpValue) continue;                   // brak FP → pomijamy

        // argument (hex) – użyjemy pierwszego napotkanego numeru w liście argumentów
        const argHex = fn.args.split(',').find(a => /^0x[0-9a-f]+$/i.test(a)).trim();

        // wykonać faktyczne odkodowanie (eval – tak jak w Twoim pierwotnym kodzie)
        const decoded = await runDecoder({
          helperFunc: func,
          helperArr: arr,
          fpDeclaration: fn.declaration,   // cała linijka, bo eval potrzebuje kontekstu
          fpValue,
          argHex,
        });

        results.push({
          functionName: fn.name,
          argValue: argHex,
          decoded,
        });
      }

      resolve(results);
    });
  });
}

/* --------------------------------------------------------------
   2️⃣  WYCIĄGNIJ WSZYSTKIE DEKLARACJE FUNKCJI Z KODU
   -------------------------------------------------------------- */
function extractAllFunctions(source) {
  // dopasowujemy:
  //   <nazwa> = function (<arg1>, <arg2>) { <ciało> }
  //   (lub arrow‑function, ale w Twoim pliku są tylko tradycyjne)
  const regex = /(\w+)\s*=\s*function\s*\(([^)]*)\)\s*{([\s\S]*?)}/gm;
  const functions = [];

  let match;
  while ((match = regex.exec(source)) !== null) {
    const [, name, args, body] = match;
    functions.push({
      name,
      args,
      body,
      declaration: match[0], // cała linijka (przydatna przy eval)
    });
  }
  return functions;
}

/* --------------------------------------------------------------
   3️⃣  POBIERZ TABLICĘ I FUNKCJĘ POMOCNICZĄ (tzw. e.arr i e.func)
   -------------------------------------------------------------- */
function getHelperStuff() {
  return new Promise((resolve, reject) => {
    fs.readFile(path, 'utf-8', (err, data) => {
      if (err) return reject(err);

      // ---- znajdź deklarację tablicy (np. const _0x1234 = [1,2,3]); ----
      const arrayRegex = /const\s+(\w+)\s*=\s*\[([^\]]+)\]/m;
      const arrMatch = arrayRegex.exec(data);
      const arr = arrMatch ? arrMatch[2].replace(/\s+/g, '') : '';

      // ---- znajdź funkcję, której nazwa spełnia wzorzec a0_\w+ ----
      const funcNameRegex = /a0_\w+/;
      const funcDeclRegex = new RegExp(`(${funcNameRegex.source})\\s*=\\s*function\\s*\\(\\)\\s*{([\\s\\S]*?)};?`);
      const funcMatch = funcDeclRegex.exec(data);
      const funcName = funcMatch ? funcMatch[1] : 'unknown_helper';

      // Budujemy kod, który później `eval`ujemy
      const helperFunc = `
        function ${funcName}(){
          const essa = [${arr}];
          ${funcName} = function(){ return essa; };
          return ${funcName}();
        }
      `;

      resolve({ arr, func: helperFunc });
    });
  });
}

/* --------------------------------------------------------------
   4️⃣  WYCIĄGNIJ „FP‑VALUE” Z DEKLARACJI FUNKCJI
   -------------------------------------------------------------- */
function extractFPValue(fnBody) {
  // w oryginale:  _0x1234(_0x5678)
  // szukamy wywołania _0x???( something ) – pierwsze wystąpienie
  const regex = /_0x[0-9a-fA-F]+\(([^()]+)\)/;
  const match = regex.exec(fnBody);
  return match ? match[1].trim() : null;
}

/* --------------------------------------------------------------
   5️⃣  RZECZYWIŚCIWE ODPOWIEDZI – EKSEKUCJA KODU
   -------------------------------------------------------------- */
async function runDecoder({ helperFunc, helperArr, fpDeclaration, fpValue, argHex }) {
  // Budujemy jednorazowy skrypt, którego `eval` wykona wszystkie potrzebne rzeczy:
  // 1️⃣ definiujemy tablicę i pomocniczą funkcję (z kroku 3)
  // 2️⃣ definiujemy funkcję FP (przekazaną jako string – to kod w stylu `GET_FP['fp'] = …`)
  // 3️⃣ wywołujemy ją z podanym argumentem (`argHex`)
  // 4️⃣ wynik podajemy do `console.log` – dzięki temu zwracamy go w Promise

  const script = `
    ${helperFunc}               // <‑‑ definiuje np. function a0_xxx(){…}
    ${fpDeclaration}           // <‑‑ to cała linijka np. GET_FP['fp'] = _0x1b2c(_0x3d4e);
    // ------------------------------
    // Teraz wyciągamy samą funkcję (taką, której nazwa jest w fpDeclaration)
    // Zwykle jest to coś w stylu:  GET_FP['fp'] = <funcName>(...)
    const fpFuncName = Object.keys(GET_FP)[0];            // "fp"
    const realFunc   = GET_FP[fpFuncName];                // np. _0x1b2c

    // uruchamiamy „odkodowujący” kod
    const decoded = realFunc(${argHex});                 // argHex to np. 0x1df

    // zwracamy wynik
    decoded;
  `;

  // `eval` zwraca co wykonał ostatni wyrażenie – czyli zmienną `decoded`
  // Aby zachować izolację (i nie mieszać z globalnym scope), użyjemy `new Function`
  // (to samo co `eval`, ale bez ryzyka „przypadkowego” zanieczyszczenia)
  try {
    const fn = new Function('GET_FP', script);
    // `GET_FP` musi istnieć – w kodzie źródłowym najprawdopodobniej jest już zdefiniowane
    // Jeśli nie, tworzymy pusty obiekt i pozwalamy na jego wypełnienie w `fpDeclaration`
    const GET_FP = {};
    const result = fn(GET_FP);
    return result;
  } catch (e) {
    console.error('Błąd przy dekodowaniu:', e);
    return null;
  }
}
```

### Co dokładnie zmieniło się w stosunku do Twojego pierwotnego kodu?

| Numer | Zmiana | Dlaczego |
|------|--------|----------|
| **1** | **`extractAllFunctions`** – jednorazowo parsuje **wszystkie** funkcje w pliku (regex `/(\w+)\s*=\s*function\s*\(([^)]*)\)\s*{([\s\S]*?)}/gm`). | Dzięki temu nie musimy znać konkretnego wzorca `, (function() {` – znajdziemy *każdą* funkcję. |
| **2** | **Filtrowanie** przy pomocy `candidates = allFunctions.filter(...)`. | Warunek „2 argumenty i jeden jest liczbą hex” jest realizowany w czystej JavaScript‑owej logice. |
| **3** | **`getHelperStuff`** – wyodrębnia jednorazowo `e.arr` i `e.func` (tablicę oraz pomocniczą funkcję). | Nie musimy już w pętli odczytywać pliku – robimy to raz i przekazujemy dalej. |
| **4** | **`extractFPValue`** przyjmuje **całe ciało funkcji** i zwraca jedynie argument (np. `0x1234`). | Teraz możemy używać tej samej funkcji dla *każdej* znalezionej deklaracji. |
| **5** | **`runDecoder`** – zamknięty w `new Function` (bezpieczniejszy niż `eval` w kontekście globalnym). | Najważniejsze jest wywołanie `realFunc(argHex)` i zwrócenie wyniku. |
| **6** | **Zwracamy tablicę wyników** (`[{functionName, argValue, decoded}, …]`) i wyświetlamy je w końcowym `console.log`. | W ten sposób widzisz **wszystkie** odkodowane wartości. |

