## 2️⃣ Server side – `server.js`

```js
// server.js
const express = require('express');
const http = require('http');          // native node http server
const path = require('path');
const { Server } = require('socket.io'); // socket.io server class

const app = express();

// Serve static files from the "public" folder
app.use(express.static(path.join(__dirname, 'public')));

// OPTIONAL: a simple health endpoint
app.get('/health', (req, res) => res.send('OK'));

// Create HTTP server & attach Socket.io
const httpServer = http.createServer(app);
const io = new Server(httpServer, {
  // options (CORS, path, etc.)
  cors: {
    origin: "*",          // In production replace with your domain
    methods: ["GET", "POST"]
  }
});

/**
 * Data structures (in‑memory)
 * ----------------------------
 * - `users`    : socket.id => username
 * - `messages` : [{ username, text, timestamp }]
 *
 * For a production‑grade app you would replace these with a DB.
 */
const users = new Map();   // socket.id => username
const messages = [];       // keep last 100 messages in memory

// ---------- SOCKET.IO EVENT HANDLERS ----------
io.on('connection', (socket) => {
  console.log(`🔌 New client connected → socket.id = ${socket.id}`);

  // 1️⃣  Client sends their username after connecting
  socket.on('join', (username) => {
    if (typeof username !== 'string' || username.trim() === '') {
      username = 'Anonymous';
    }
    users.set(socket.id, username);
    console.log(`🟢 ${username} joined (socket ${socket.id})`);

    // Tell everybody else that a new user arrived
    socket.broadcast.emit('user joined', username);

    // Send recent chat history to the newly joined client
    socket.emit('chat history', messages);
  });

  // 2️⃣  Client sends a chat message
  socket.on('chat message', (msgText) => {
    const username = users.get(socket.id) || 'Anonymous';
    const msg = {
      username,
      text: String(msgText).trim(),
      timestamp: new Date().toISOString()
    };
    // Store (capped at 100)
    messages.push(msg);
    if (messages.length > 100) messages.shift();

    // Broadcast to *all* sockets including sender
    io.emit('chat message', msg);
  });

  // 3️⃣  Client disconnects
  socket.on('disconnect', () => {
    const username = users.get(socket.id);
    if (username) {
      console.log(`❌ ${username} disconnected`);
      socket.broadcast.emit('user left', username);
      users.delete(socket.id);
    } else {
      console.log(`❌ Unknown socket (${socket.id}) disconnected`);
    }
  });
});

// ---------- START THE SERVER ----------
const PORT = process.env.PORT || 3000;
httpServer.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
```

### What the server does

| Event | Direction | Payload | Purpose |
|-------|-----------|---------|---------|
| `join` | client → server | `username` | Register user, broadcast “user joined”, send past messages |
| `chat message` | client → server | `text` | Build full message object (username + timestamp) and broadcast |
| `user joined` | server → all‑except‑sender | `username` | UI hint that a new user entered |
| `user left` | server → all‑except‑sender | `username` | UI hint that someone left |
| `chat history` | server → just‑joined client | `Array<Message>` | Populate chat window with recent messages |
| `chat message` | server → all | `Message` | Show new message in everyone's UI |

---

## 3️⃣ Client side – `public/index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>🚀 Express‑Socket.io Chat</title>
  <style>
    body { font-family: sans-serif; background:#f7f7f7; margin:0; padding:0; }
    #chat { max-width:800px; margin:2rem auto; background:#fff; border:1px solid #ddd; display:flex; flex-direction:column; height:80vh;}
    #messages { flex:1; overflow-y:auto; padding:1rem; }
    #messages li { margin-bottom:.5rem; list-style:none; }
    #messages .meta { color:#555; font-size:.85rem; }
    #form { display:flex; border-top:1px solid #ddd; }
    #input { flex:1; padding:0.5rem; border:none; font-size:1rem; }
    #input:focus { outline:none; }
    #send { padding:0.5rem 1rem; border:none; background:#0d6efd; color:#fff; cursor:pointer; }
    #send:hover { background:#0b5ed7; }
  </style>
</head>
<body>

<div id="chat">
  <ul id="messages"></ul>
  <form id="form" autocomplete="off">
    <input id="input" placeholder="Type a message…" maxlength="500" />
    <button id="send">Send</button>
  </form>
</div>

<script src="/socket.io/socket.io.js"></script>
<script>
  // ---------- 1️⃣ Prompt for a username ----------
  let username = '';
  while (!username) {
    username = prompt('Enter your name:', '');
    if (username === null) { // user pressed Cancel
      username = 'Anonymous';
      break;
    }
    username = username.trim();
  }

  // ---------- 2️⃣ Connect ----------
  const socket = io(); // automatically connects to the same host

  // After socket is connected, tell the server who we are
  socket.on('connect', () => {
    socket.emit('join', username);
  });

  // ---------- 3️⃣ UI helpers ----------
  const $messages = document.getElementById('messages');
  const $form = document.getElementById('form');
  const $input = document.getElementById('input');

  // Append a line to the chat window
  function addMessage({ username, text, timestamp }, isOwn = false) {
    const li = document.createElement('li');

    // Add meta info
    const meta = document.createElement('div');
    meta.className = 'meta';
    const time = new Date(timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    meta.textContent = `${username} • ${time}`;
    li.appendChild(meta);

    // Add message body
    const body = document.createElement('div');
    body.textContent = text;
    li.appendChild(body);

    if (isOwn) li.style.background = '#e6f7ff';

    $messages.appendChild(li);
    // Auto‑scroll to bottom
    $messages.scrollTop = $messages.scrollHeight;
  }

  // ---------- 4️⃣ Socket event listeners ----------
  socket.on('chat history', (history) => {
    history.forEach(msg => addMessage(msg));
  });

  socket.on('chat message', (msg) => {
    const isOwn = msg.username === username;
    addMessage(msg, isOwn);
  });

  socket.on('user joined', (name) => {
    const info = document.createElement('li');
    info.style.fontStyle = 'italic';
    info.textContent = `${name} joined the chat`;
    $messages.appendChild(info);
    $messages.scrollTop = $messages.scrollHeight;
  });

  socket.on('user left', (name) => {
    const info = document.createElement('li');
    info.style.fontStyle = 'italic';
    info.textContent = `${name} left the chat`;
    $messages.appendChild(info);
    $messages.scrollTop = $messages.scrollHeight;
  });

  // ---------- 5️⃣ Send a new message ----------
  $form.addEventListener('submit', (e) => {
    e.preventDefault();
    const text = $input.value.trim();
    if (!text) return;
    socket.emit('chat message', text);
    $input.value = '';
  });
</script>

</body>
</html>
```

### How it works

1. **Prompt for a name** – you can replace this with a login page or use a JWT token later.
2. **Connect** – `io()` automatically connects to the server that served the page.
3. **Emit `join`** – tells the server which name belongs to this socket.
4. **Listen** for:
   * `chat history` – initial backlog of recent messages.
   * `chat message` – any new inbound message.
   * `user joined` / `user left` – simple status updates.
5. **Send messages** – on form submit we `emit('chat message', text)`.

---

## 4️⃣ Run it locally

```bash
npm start
```

Open one (or many) browser tabs at **http://localhost:3000**.  
Enter your name in the prompt, start typing, and watch the messages appear in all open windows instantly.

---

## 5️⃣ Optional enhancements (quick cheat‑sheet)

| Feature | How to add (code snippets) |
|---------|---------------------------|
| **Multiple rooms** | ```js // server <br> socket.on('join room', (room) => { socket.join(room); }); <br> // client <br> socket.emit('join room','sports'); // then emit & listen to room‑specific events ``` |
| **Persist chat** (MongoDB) | Install `mongoose`, create a `Message` schema, replace the in‑memory `messages` array with `Message.find().limit(100)` and `new Message(msg).save()` on each incoming message. |
| **User authentication** | Use JWT or session cookies; on connection read `socket.handshake.auth` or `socket.request.headers.cookie` to get user info; reject unauthorized sockets (`socket.disconnect(true)`). |
| **Message sanitisation** | Use `dompurify` on the client or `sanitize-html`/`xss-filters` on the server to prevent XSS. |
| **Typing indicator** | Emit `typing` / `stop typing` events; show “John is typing…” in UI with a timeout. |
| **Deploy to Heroku / Render / Railway** | Ensure the `PORT` env var is respected (already done). Add a `Procfile` (`web: node server.js`). |
| **HTTPS + WSS** | For production use a reverse‑proxy (NGINX, Cloudflare, or a platform that terminates TLS) – socket.io will automatically upgrade to `wss://`. |
| **Rate limiting / anti‑spam** | Keep a per‑socket timestamp map; reject messages sent faster than e.g. 300 ms. |
| **Front‑end framework** | Replace the vanilla HTML with React/Vue/Svelte – just keep `socket.io-client` and the same event names. |

---

## 6️⃣ “Bare‑bones WebSocket” (no socket.io)

If you *must* use the native WebSocket API (e.g., to avoid the extra package), you can swap out `socket.io` for the `ws` library:

```bash
npm install ws
```

**Server (`server-ws.js`):**

```js
const express = require('express');
const http = require('http');
const path = require('path');
const { WebSocketServer } = require('ws');

const app = express();
app.use(express.static(path.join(__dirname, 'public')));

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

const clients = new Set();

wss.on('connection', (ws) => {
  clients.add(ws);
  ws.on('message', (data) => {
    // data is a JSON string from the client
    const msg = JSON.parse(data);
    // broadcast to *all* other clients
    for (const client of clients) {
      if (client !== ws && client.readyState === client.OPEN) {
        client.send(JSON.stringify(msg));
      }
    }
  });
  ws.on('close', () => clients.delete(ws));
});

server.listen(3000, () => console.log('WS server listening on :3000'));
```

**Client (`public/index.html` tiny change):**

```html
<script>
  const ws = new WebSocket(`ws://${location.host}`);
  ws.onopen = () => ws.send(JSON.stringify({type:'join', username}));
  ws.onmessage = e => {
