    if (msg.type === 'chat') addMessage(msg);
    // handle other types (join/leave) similarly
  };
  // send a chat message:
  socket.emit = (type, payload) => ws.send(JSON.stringify({type, ...payload}));
</script>
```

*Pros*: pure WebSocket, no extra abstractions.  
*Cons*: you have to implement rooms, ACKs, reconnection logic, etc., yourself.

