  <div id="status"></div>
  <div id="bpm">—</div>

  <script>
    // --------------------------------------------------------------
    //   Simple real‑time beat detector using the Web Audio API
    // --------------------------------------------------------------
    const startBtn = document.getElementById('startBtn');
    const statusEl = document.getElementById('status');
    const bpmEl = document.getElementById('bpm');

    // Configuration
    const THRESHOLD = 0.25;          // RMS level that counts as a "beat"
    const MIN_INTERVAL = 0.3;       // seconds – ignore peaks closer than this
    const MAX_BEAT_HISTORY = 8;     // how many recent beats to average

    // Runtime state
    let audioCtx, analyser, scriptNode;
    let lastPeakTime = 0;
    const beats = [];               // timestamps (in seconds) of recent beats

    startBtn.onclick = async () => {
      startBtn.disabled = true;
      statusEl.textContent = '🔊 Requesting microphone…';
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
        initAudio(stream);
        statusEl.textContent = '👂 Listening… tap any beat on the mic';
      } catch (e) {
        console.error(e);
        statusEl.textContent = '❌ Microphone access denied';
        startBtn.disabled = false;
      }
    };

    function initAudio(stream) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioCtx.createMediaStreamSource(stream);

      // Analyzer for getting raw PCM data
      analyser = audioCtx.createAnalyser();
      analyser.fftSize = 512;               // small FFT – we only need time‑domain data
      const bufferLength = analyser.fftSize;
      const dataArray = new Float32Array(bufferLength);

      // ScriptProcessorNode is deprecated but still works in all browsers.
      // For newer browsers you could swap it with an AudioWorklet.
      scriptNode = audioCtx.createScriptProcessor(2048, 1, 1);
      scriptNode.onaudioprocess = (audioProcessingEvent) => {
        analyser.getFloatTimeDomainData(dataArray);
        const rms = calculateRMS(dataArray);
        const now = audioCtx.currentTime;

        // Simple peak detector
        if (rms > THRESHOLD && (now - lastPeakTime) > MIN_INTERVAL) {
          // We have a new beat!
          lastPeakTime = now;
          beats.push(now);
          if (beats.length > MAX_BEAT_HISTORY) beats.shift(); // keep recent ones only
          const bpm = calculateBPM(beats);
          if (bpm) {
            bpmEl.textContent = Math.round(bpm);
          }
        }
      };

      // Connect the graph
      source.connect(analyser);
      analyser.connect(scriptNode);
      scriptNode.connect(audioCtx.destination);
    }

    // --------------------------------------------------------------
    // Helper: RMS (root‑mean‑square) – a cheap proxy for signal energy
    // --------------------------------------------------------------
    function calculateRMS(buffer) {
      let sum = 0;
      for (let i = 0; i < buffer.length; i++) {
        sum += buffer[i] * buffer[i];
      }
      return Math.sqrt(sum / buffer.length);
    }

    // --------------------------------------------------------------
    // Helper: from a list of beat timestamps → BPM
    // --------------------------------------------------------------
    function calculateBPM(timestamps) {
      if (timestamps.length < 2) return null;

      // Compute intervals between consecutive beats
      const intervals = [];
      for (let i = 1; i < timestamps.length; i++) {
        intervals.push(timestamps[i] - timestamps[i - 1]);
      }

      // Remove outliers (very short / very long intervals)
      const median = intervals.sort((a, b) => a - b)[Math.floor(intervals.length / 2)];
      const filtered = intervals.filter(i => Math.abs(i - median) < 0.2 * median);
      if (filtered.length < 2) return null;

      const avgInterval = filtered.reduce((a, b) => a + b, 0) / filtered.length; // seconds
      return 60 / avgInterval; // beats per minute
    }

    // --------------------------------------------------------------
    // Clean up when the page is hidden (optional but nice)
    // --------------------------------------------------------------
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && audioCtx) {
