## 7️⃣ Express Routes

### 7.1 Auth route – `src/routes/auth.js`

```js
// src/routes/auth.js
const express = require('express');
const router = express.Router();
const { findByUsername } = require('../models/user');
const bcrypt = require('bcrypt');
const { sign } = require('../config/jwt');

/**
 * POST /api/auth/login
 * body: { username, password }
 */
router.post('/login', async (req, res) => {
  const { username, password } = req.body;

  // Basic validation
  if (!username || !password) {
    return res.status(400).json({ message: 'Missing username or password' });
  }

  try {
    const user = await findByUsername(username);
    if (!user) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    const passwordMatches = await bcrypt.compare(password, user.password);
    if (!passwordMatches) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    // Create JWT (payload usually a minimal set)
    const token = sign({ userId: user.id, username: user.username });

    res.json({ token, username: user.username });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

module.exports = router;
```

### 7.2 Entries route – `src/routes/entries.js`

```js
// src/routes/entries.js
const express = require('express');
const router = express.Router();
const db = require('../config/db');
const { authenticateToken } = require('../middleware/auth');

/**
 * GET /api/entries
 * Returns all entries for the authenticated user
 */
router.get('/', authenticateToken, async (req, res) => {
  const userId = req.user.userId; // set by auth middleware
  try {
    const { rows } = await db.query(
      'SELECT id, title, content, created_at FROM entries WHERE user_id = $1 ORDER BY created_at DESC',
      [userId]
    );
    res.json(rows);
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Error fetching entries' });
  }
});

/**
 * POST /api/entries
 * body: { title, content }
 * Creates a new entry for the current user
 */
router.post('/', authenticateToken, async (req, res) => {
  const userId = req.user.userId;
  const { title, content } = req.body;

  if (!title) {
    return res.status(400).json({ message: 'Title required' });
  }

  try {
    const { rows } = await db.query(
      `INSERT INTO entries (user_id, title, content)
       VALUES ($1, $2, $3)
       RETURNING id, title, content, created_at`,
      [userId, title, content]
    );
    res.status(201).json(rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Error creating entry' });
  }
});

module.exports = router;
```

### 7.3 Auth middleware – `src/middleware/auth.js`

```js
// src/middleware/auth.js
const { verify } = require('../config/jwt');

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  // Expect "Bearer <token>"
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401); // Unauthorized

  try {
    const payload = verify(token);
    req.user = payload; // e.g., { userId, username, iat, exp }
    next();
  } catch (err) {
    console.warn('Invalid JWT', err);
    return res.sendStatus(403); // Forbidden
  }
}

module.exports = { authenticateToken };
```

