## 11️⃣ Auth Context – Central place to store JWT

Create **`src/context/AuthContext.jsx`**

```jsx
// src/context/AuthContext.jsx
import React, { createContext, useState, useEffect } from 'react';
import axios from 'axios';

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [auth, setAuth] = useState(() => {
    // Load from localStorage on first render
    const token = localStorage.getItem('token');
    const username = localStorage.getItem('username');
    return token ? { token, username } : null;
  });

  // Keep axios default header in sync
  useEffect(() => {
    if (auth?.token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${auth.token}`;
    } else {
      delete axios.defaults.headers.common['Authorization'];
    }
  }, [auth]);

  const login = async (username, password) => {
    const resp = await axios.post(
      `${process.env.REACT_APP_API_URL}/auth/login`,
      { username, password }
    );
    const { token, username: serverUsername } = resp.data;
    localStorage.setItem('token', token);
    localStorage.setItem('username', serverUsername);
    setAuth({ token, username: serverUsername });
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('username');
    setAuth(null);
  };

  return (
    <AuthContext.Provider value={{ auth, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};
```

