## 13️⃣ Axios API Helper – `src/api/client.js`

We already set the default Authorization header in the `AuthContext`. The helper below adds the base URL and swallows 401/403 to trigger a logout (optional).

```js
// src/api/client.js
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import { useContext } from 'react';

export const useApi = () => {
  const { logout } = useContext(AuthContext);
  const client = axios.create({
    baseURL: process.env.REACT_APP_API_URL,
    timeout: 5000,
  });

  // Interceptor to automatically logout on auth errors
  client.interceptors.response.use(
    res => res,
    err => {
      if (err.response && [401, 403].includes(err.response.status)) {
        logout();
      }
      return Promise.reject(err);
    }
  );
  return client;
};
```

You can now import `useApi` in components.

