    try {
      const res = await api.get('/entries');
      setEntries(res.data);
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.message || 'Failed to load entries');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEntries();
    // Optional: start a polling interval or WebSocket update here
  }, []);

  if (loading) return <p>Loading...</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  if (entries.length === 0) return <p>No entries yet.</p>;

  return (
    <section style={{ marginTop: 30 }}>
      <h2>Your Entries</h2>
      <ul>
        {entries.map(entry => (
          <li key={entry.id} style={{ marginBottom: 10 }}>
            <strong>{entry.title}</strong>
            <p>{entry.content}</p>
            <small>{new Date(entry.created_at).toLocaleString()}</small>
          </li>
        ))}
      </ul>
