### `server/config/db.js` – подключение к MongoDB
```js
const mongoose = require('mongoose');
require('dotenv').config();

const connectDB = async () => {
  try {
    await mongoose.connect(process.env.MONGODB_URI, {
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });
    console.log('✅ MongoDB connected');
  } catch (err) {
    console.error('❌ MongoDB connection error:', err);
    process.exit(1);
  }
};

module.exports = connectDB;
```

### `server/models/User.js` – пользователь и хеш пароля
```js
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');

const UserSchema = new mongoose.Schema({
  email: { type: String, required: true, unique: true, lowercase: true },
  passwordHash: { type: String, required: true },
  // ссылка на персонажа (можно иметь несколько, но пока один)
  character: { type: mongoose.Schema.Types.ObjectId, ref: 'Character' },
});

UserSchema.methods.setPassword = async function (pwd) {
  this.passwordHash = await bcrypt.hash(pwd, 10);
};

UserSchema.methods.validatePassword = async function (pwd) {
  return await bcrypt.compare(pwd, this.passwordHash);
};

module.exports = mongoose.model('User', UserSchema);
```

### `server/models/Character.js` – персонаж игрока
```js
const mongoose = require('mongoose');

const ItemSchema = new mongoose.Schema({
  itemId: String,        // ID предмета (можно привязать к отдельной таблице предметов)
  amount: { type: Number, default: 1 },
});

const SkillSchema = new mongoose.Schema({
  skillId: String,
  cooldown: { type: Number, default: 0 }, // в миллисекундах, будет обновляться сервером
});

const CharacterSchema = new mongoose.Schema({
  name: { type: String, required: true },
  // базовые характеристики
  level: { type: Number, default: 1 },
  hp: { type: Number, default: 100 },
  maxHp: { type: Number, default: 100 },

  // позиция в мире (можно заменить на более сложную структуру)
  x: { type: Number, default: 0 },
  y: { type: Number, default: 0 },

  // инвентарь и навыки
  inventory: [ItemSchema],
  skills: [SkillSchema],
});

module.exports = mongoose.model('Character', CharacterSchema);
