### `server/routes/auth.js` – регистрация / логин
```js
const express = require('express');
const router = express.Router();
const jwt = require('jsonwebtoken');
const User = require('../models/User');
const Character = require('../models/Character');

const JWT_SECRET = process.env.JWT_SECRET;
const JWT_EXPIRES = '7d';

// ---------- Регистрация ----------
router.post('/register', async (req, res) => {
  const { email, password, characterName } = req.body;
  if (!email || !password || !characterName) {
    return res.status(400).json({ msg: 'Все поля обязательны' });
  }

  try {
    // проверяем, нет ли уже пользователя
    if (await User.findOne({ email })) {
      return res.status(400).json({ msg: 'Пользователь уже существует' });
    }

    // создаём персонажа
    const character = await Character.create({ name: characterName });

    // создаём пользователя
    const user = new User({ email, character: character._id });
    await user.setPassword(password);
    await user.save();

    // JWT
    const token = jwt.sign({ id: user._id }, JWT_SECRET, { expiresIn: JWT_EXPIRES });
    res.json({ token, character });
  } catch (e) {
    console.error(e);
    res.status(500).json({ msg: 'Ошибка сервера' });
  }
});

// ---------- Логин ----------
router.post('/login', async (req, res) => {
  const { email, password } = req.body;
  try {
    const user = await User.findOne({ email }).populate('character');
    if (!user) return res.status(400).json({ msg: 'Неверный e‑mail' });

    const ok = await user.validatePassword(password);
    if (!ok) return res.status(400).json({ msg: 'Неверный пароль' });

    const token = jwt.sign({ id: user._id }, JWT_SECRET, { expiresIn: JWT_EXPIRES });
    res.json({ token, character: user.character });
  } catch (e) {
    console.error(e);
    res.status(500).json({ msg: 'Ошибка сервера' });
  }
});

module.exports = router;
```

### `server/socket/index.js` – обработка реального времени (movement, skills)
```js
const { Server } = require('socket.io');
const jwt = require('jsonwebtoken');
const User = require('../models/User');
const Character = require('../models/Character');

const JWT_SECRET = process.env.JWT_SECRET;

/**
 * Функция инициализации Socket.io.
 * Вызывается из app.js после `httpServer.listen`.
 */
module.exports = function initSocket(httpServer) {
  const io = new Server(httpServer, {
    cors: {
      origin: '*', // в проде ограничьте домен
    },
  });

  // Хранилище подключённых игроков: socket.id -> characterId
  const onlinePlayers = new Map();

  // ---- Middleware для аутентификации ----
  io.use(async (socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error('Нет токена'));

    try {
      const payload = jwt.verify(token, JWT_SECRET);
      const user = await User.findById(payload.id).populate('character');
      if (!user) return next(new Error('Пользователь не найден'));
      socket.user = user;          // сохраняем в socket
      socket.character = user.character;
      next();
    } catch (e) {
      console.error('Socket auth error:', e);
      next(new Error('Неверный токен'));
    }
  });

  // ---- Подключение клиента ----
  io.on('connection', (socket) => {
    const { character } = socket;
    onlinePlayers.set(socket.id, character._id);
    console.log(`🟢 ${character.name} подключён`);

    // Информируем других игроков о появлении
    socket.broadcast.emit('playerJoined', {
      id: character._id,
      name: character.name,
      x: character.x,
      y: character.y,
    });

    // --------- Перемещение ----------
    // payload: { dx, dy } – изменение координат
    socket.on('move', async (payload) => {
      const speed = 5; // можно хранить в персонаже
      const newX = character.x + (payload.dx * speed);
      const newY = character.y + (payload.dy * speed);

      // простая проверка границ (здесь мир 0..1000)
      character.x = Math.max(0, Math.min(1000, newX));
      character.y = Math.max(0, Math.min(1000, newY));
      await character.save();

      // рассылка другим клиентам
      socket.broadcast.emit('playerMoved', {
        id: character._id,
        x: character.x,
        y: character.y,
      });

      // также подтверждаем отправителю (можно опустить)
      socket.emit('moveConfirmed', { x: character.x, y: character.y });
    });

    // --------- Применение навыка ----------
    // payload: { skillId, targetId? }
    socket.on('useSkill', async (payload) => {
      const skill = character.skills.find((s) => s.skillId === payload.skillId);
      if (!skill) return socket.emit('errorMessage', 'Навык не найден');

      const now = Date.now();
      if (skill.cooldown > now) {
        const remaining = Math.ceil((skill.cooldown - now) / 1000);
        return socket.emit('errorMessage', `Навык на кулдауне: ${remaining}s`);
      }

      // -----------------
      // Пример простого навыка "fireball":
      //   - наносит урон цели (если указана)
      //   - иначе просто показывает анимацию
      // -----------------
      const damage = 30; // фиксированный урон

      // сохраняем время следующего использования
      skill.cooldown = now + 5_000; // 5 секунд кулдаун
      await character.save();

      // Если цель указана, наносим урон
      if (payload.targetId) {
        const targetChar = await Character.findById(payload.targetId);
        if (targetChar) {
          targetChar.hp = Math.max(0, targetChar.hp - damage);
          await targetChar.save();

          // Уведомляем обе стороны + всех остальных
          io.to(socket.id).emit('skillResult', {
            skillId: payload.skillId,
            targetId: targetChar._id,
            dmg: damage,
            targetHp: targetChar.hp,
          });

          // Сообщаем всем, кто находится рядом (можно добавить радиус)
          socket.broadcast.emit('skillResult', {
            skillId: payload.skillId,
            casterId: character._id,
            targetId: targetChar._id,
            dmg: damage,
            targetHp: targetChar.hp,
          });
        }
      } else {
        // без цели – только анимация
        socket.broadcast.emit('skillCast', {
          skillId: payload.skillId,
          casterId: character._id,
        });
      }
    });

    // --------- Инвентарь ----------
    // Получение текущего инвентаря
    socket.on('getInventory', () => {
      socket.emit('inventoryData', character.inventory);
    });

    // Добавление предмета (только пример, без проверок)
    socket.on('addItem', async (item) => {
      const existing = character.inventory.find((i) => i.itemId === item.itemId);
      if (existing) {
        existing.amount += item.amount || 1;
      } else {
        character.inventory.push({ itemId: item.itemId, amount: item.amount || 1 });
      }
      await character.save();
      socket.emit('inventoryUpdated', character.inventory);
    });

    // ---------- Отключение ----------
    socket.on('disconnect', () => {
      console.log(`🔴 ${character.name} отключён`);
      onlinePlayers.delete(socket.id);
      socket.broadcast.emit('playerLeft', { id: character._id });
    });
  });
};
```

