```js
// ---------- Конфигурация ----------
const API_URL = '/api/auth';
const SOCKET_URL = location.origin; // тот же хост

// ---------- Состояние ----------
let token = null;      // JWT
let myChar = null;     // персонаж текущего пользователя
let socket = null;     // socket.io клиент
const players = new Map(); // id -> DOM элемент

// ---------- UI ----------
const statusEl = document.getElementById('status');
function setStatus(msg, err = false) {
  statusEl.textContent = msg;
  statusEl.style.color = err ? 'red' : 'lightgreen';
}

// ---------- Авторизация ----------
document.getElementById('loginBtn').onclick = async () => {
  const email = document.getElementById('email').value.trim();
  const pw = document.getElementById('password').value;
  if (!email || !pw) return setStatus('Заполните e‑mail и пароль', true);
  try {
    const res = await fetch(`${API_URL}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password: pw })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.msg);
    token = data.token;
    myChar = data.character;
    setStatus('Успешный вход');
    startGame();
  } catch (e) {
    setStatus(e.message, true);
  }
};

document.getElementById('registerBtn').onclick = async () => {
  const email = document.getElementById('email').value.trim();
  const pw = document.getElementById('password').value;
  const name = document.getElementById('charName').value.trim();
  if (!email || !pw || !name) return setStatus('Заполните все поля', true);
  try {
    const res = await fetch(`${API_URL}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password: pw, characterName: name })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.msg);
    token = data.token;
    myChar = data.character;
    setStatus('Регистрация прошла успешно');
    startGame();
  } catch (e) {
    setStatus(e.message, true);
  }
};

// ---------- Инициализация игры ----------
function startGame() {
  // скрываем форму
  document.getElementById('ui').style.display = 'none';
  document.getElementById('game').style.display = 'block';

  // создаём собственного аватара
  const gameDiv = document.getElementById('game');
  const meDiv = createPlayerDiv(myChar);
  gameDiv.appendChild(meDiv);
  players.set(myChar._id, meDiv);
  updatePlayerPos(myChar);

  // соединяемся с socket.io и передаём токен
  socket = io(SOCKET_URL, { auth: { token } });

  // ---------- События socket ----------
  socket.on('connect', () => console.log('✅ Socket connected'));

  socket.on('playerJoined', (data) => {
    if (players.has(data.id)) return;
    const el = createPlayerDiv({ _id: data.id, name: data.name });
    document.getElementById('game').appendChild(el);
    players.set(data.id, el);
    el.style.left = data.x + 'px';
    el.style.top = data.y + 'px';
  });

  socket.on('playerMoved', (data) => {
    const el = players.get(data.id);
    if (el) {
      el.style.left = data.x + 'px';
      el.style.top = data.y + 'px';
    }
  });

  socket.on('playerLeft', ({ id }) => {
    const el = players.get(id);
    if (el) el.remove();
    players.delete(id);
  });

  socket.on('skillCast', ({ casterId, skillId }) => {
    console.log(`Skill ${skillId} cast by ${casterId}`);
    // здесь можно добавить анимацию
  });

  socket.on('skillResult', (info) => {
    console.log('Skill result:', info);
    // анимация броска/урона, обновление HP и т.д.
  });

  socket.on('errorMessage', (msg) => alert('Ошибка: ' + msg));

  // ---------- Управление перемещением ----------
  document.addEventListener('keydown', (e) => {
    const key = e.key;
    let dx = 0, dy = 0;
    if (key === 'ArrowUp') dy = -1;
    else if (key === 'ArrowDown') dy = 1;
    else if (key === 'ArrowLeft') dx = -1;
    else if (key === 'ArrowRight') dx = 1;
    else if (key === ' ') { // пробел — пример использования навыка "fireball"
      socket.emit('useSkill', { skillId: 'fireball' });
      return;
    }

    if (dx !== 0 || dy !== 0) {
      socket.emit('move', { dx, dy });
    }
  });

  // ---------- Инвентарь (пример) ----------
  // Получаем текущий инвентарь после входа
  socket.emit('getInventory');
  socket.on('inventoryData', (items) => {
    console.log('Inventory:', items);
  });
}

// ---------- Утилиты ----------
function createPlayerDiv({ _id, name }) {
  const el = document.createElement('div');
  el.className = 'player';
  el.dataset.id = _id;
  el.title = name;
  el.textContent = name[0].toUpperCase();
  el.style.left = '0px';
  el.style.top = '0px';
  return el;
}

function updatePlayerPos(char) {
  const el = players.get(char._id);
  if (el) {
    el.style.left = char.x + 'px';
    el.style.top = char.y + 'px';
  }
}
