// -------------------------------------------------------------
function rectIntersect(a, b) {
    return a.x < b.x + b.w &&
           a.x + a.w > b.x &&
           a.y < b.y + b.h &&
           a.y + a.h > b.y;
}

// -------------------------------------------------------------
// 3️⃣  Game entities (Player, Bullet, Enemy)
// -------------------------------------------------------------

class Player {
    constructor() {
        this.w = 60; this.h = 30;
        this.x = canvas.width/2 - this.w/2;
        this.y = canvas.height - this.h - 20; // a little above bottom
        this.lives = 3;
        this.color = '#4caf50';
    }
    move(dx) {
        this.x = Math.max(0, Math.min(canvas.width - this.w, this.x + dx));
    }
    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.w, this.h);
        // draw a little turret
        ctx.fillStyle = '#333';
        ctx.fillRect(this.x + this.w/2 - 5, this.y - 10, 10, 10);
    }
}

class Bullet {
    constructor(x, y) {
        this.w = 4; this.h = 12;
        this.x = x - this.w/2;
        this.y = y;
        this.color = '#ffeb3b';
    }
    update() {
        this.y -= BULLET_SPEED;
    }
    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.w, this.h);
    }
    offScreen() {
        return this.y + this.h < 0;
    }
}

class Enemy {
    constructor(x, y) {
        this.w = 50; this.h = 30;
        this.x = x;
        this.y = y;
        this.speed = ENEMY_SPEED;
        this.color = '#f44336';
    }
