        this.y += this.speed;
    }
    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.w, this.h);
        // simple cannon
        ctx.fillStyle = '#111';
        ctx.fillRect(this.x + this.w/2 - 4, this.y + this.h, 8, 10);
    }
    offScreen() {
        return this.y > canvas.height;
    }
}

