    if (gameOver) {
        uiMsg.style.display = 'block';
        uiMsg.textContent = 'GAME OVER';
        return;
    }

    // ---- 7.1 Update -------------------------------------------------
    // Move player
    if (keys['ArrowLeft'])  player.move(-PLAYER_SPEED);
    if (keys['ArrowRight']) player.move( PLAYER_SPEED);

    // Shoot (space) – simple rate limit (one bullet per 250 ms)
    if (keys['Space'] && (!player.lastShot || timestamp - player.lastShot > 250)) {
        bullets.push(new Bullet(player.x + player.w/2, player.y));
        player.lastShot = timestamp;
    }

    // Update bullets
    bullets.forEach(b => b.update());
    // Remove off‑screen bullets
    for (let i = bullets.length-1; i >= 0; i--) {
        if (bullets[i].offScreen()) bullets.splice(i,1);
    }

    // Spawn enemies
    if (timestamp - lastEnemySpawn > ENEMY_SPAWN_INTERVAL) {
        const ex = Math.random() * (canvas.width - 50);
        enemies.push(new Enemy(ex, -30));
        lastEnemySpawn = timestamp;
    }

    // Update enemies
    enemies.forEach(e => e.update());

    // Collision: bullet ↔ enemy
    for (let i = enemies.length-1; i >= 0; i--) {
        const enemy = enemies[i];
        // Enemy reaches bottom → player loses a life
        if (enemy.offScreen()) {
            enemies.splice(i,1);
            player.lives--;
            if (player.lives <= 0) gameOver = true;
            continue;
        }

        // Bullet hit?
        for (let j = bullets.length-1; j >= 0; j--) {
            const bullet = bullets[j];
            if (rectIntersect(bullet, enemy)) {
                // remove both
                bullets.splice(j,1);
                enemies.splice(i,1);
                score += 10;
                break;
            }
        }
    }

    // ------------------------------------------------- Render ----
    ctx.clearRect(0,0,canvas.width,canvas.height);

    // background – simple crosshatch (optional)
    ctx.fillStyle = '#2e2e2e';
    ctx.fillRect(0,0,canvas.width,canvas.height);

    // draw entities
    player.draw();
    bullets.forEach(b => b.draw());
    enemies.forEach(e => e.draw());

    // UI
    updateUI();

    // Next frame
    requestAnimationFrame(gameLoop);
}

// -------------------------------------------------------------
// 8️⃣  Start the game
// -------------------------------------------------------------
requestAnimationFrame(gameLoop);
```

