  // -------------------------------------------------
  async function loadMarkdown(mdPath) {
    // Show a simple spinner/message while we fetch
    contentEl.innerHTML = `<p class="loading">Loading ${mdPath} …</p>`;

    try {
      const resp = await fetch(mdPath);
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const rawMD = await resp.text();

      // ---- Convert markdown → HTML ----
      // Marked's default options already give us
      // sane HTML (e.g., tables support, gfm, etc.)
      const html = marked.parse(rawMD, {
        // optional: you can add custom renderer or extensions here
        // highlight: (code, lang) => hljs.highlightAuto(code, [lang]).value,
      });

      // ---- Insert HTML & highlight code blocks ----
      contentEl.innerHTML = html;
      // Highlight.js works on the fresh DOM
      hljs.highlightAll();

    } catch (err) {
      console.error(err);
