    return new RegExp(`^\\[(${tags})=?(.*?)\\](.*)\\[\\/\\1\\]$`, flags);
  }

  /* -----------------------------------------------------------
   *  BREAK‑LINE BEFORE TAG
   *  -----------------------------------------------------------
   *  Original (look‑behind):
   *      (?<=\[\/?(.*?)\])\n+(?=\[\/?(?:${tags})\])
   *
   *  New version:
   *      (\[\/?([^\\]]+)\])\n+(?=\[\/?(?:${tags})\])
   *
   *  • The preceding tag is captured in group 1 (the whole "[b]" etc.).
   *  • The tag name (without the brackets) is captured in group 2 – this
   *    is what the original callback expected as the second argument.
   *  • The newline(s) are still matched, but they are part of the overall
   *    match, so we can decide whether to keep or drop them in the replace‑
   *    callback.
   * ----------------------------------------------------------- */
  static getBreakLineBeforeTag(tagTypes, flags = '') {
    const tags = Patterns.prepareTags(...tagTypes);
    // 1‑st capture = whole preceding tag, 2‑nd capture = its name
    return new RegExp(`(\\[\\/?([^\\]]+)\\])\\n+(?=\\[\\/?(?:${tags})\\])`, flags);
  }

  /* -----------------------------------------------------------
   *  BREAK‑LINE AFTER TAG
   *  -----------------------------------------------------------
   *  Original (look‑behind):
   *      (?<=\[(?:${tags})\])\n
   *
   *  New version:
   *      (\[(?:${tags})\])\n
   *
   *  The tag itself is captured (group 1) and the trailing newline is
   *  matched.  When we replace we keep only the captured tag, i.e. we
   *  simply drop the newline.
   * ----------------------------------------------------------- */
  static getBreakLineAfterTag(tagTypes, flags = '') {
    const tags = Patterns.prepareTags(...tagTypes);
    return new RegExp(`(\\[\\/?(?:${tags})\\])\\n`, flags);
  }

  static getNotParameterizedOpeningTag(tagTypes, flags = '') {
    const tags = Patterns.prepareTags(...tagTypes);
    return new RegExp(`\\[(${tags})\\]`, flags);
  }
}
```

### 2.  Adjust the places where the two patterns are used  

Only **`prepareContent`** depends on those patterns, so we modify the two
`replace` calls to work with the new capture groups.

```js
prepareContent(contents = '') {
  if (!contents || typeof contents !== 'string') {
    return '';
  }

  const tags = [...this.tags.getBreakLineTags(), 'li'];

  // -----------------------------------------------------------------
  //  BREAK‑LINE AFTER TAG
  // -----------------------------------------------------------------
  //  afterTags now matches "<tag>\n" – we replace it with just "<tag>"
  const afterTags = Patterns.getBreakLineAfterTag(tags, 'g');
  contents = contents.replace(afterTags, '$1');   // keep the captured tag

  // -----------------------------------------------------------------
  //  BREAK‑LINE BEFORE TAG
  // -----------------------------------------------------------------
  //  beforeTags now matches "[prevTag]\n" when it is followed by a
  //  break‑line‑allowed tag (ul|ol|li …).  The callback receives:
  //      match           – whole "[prevTag]\n"
  //      precedingTag    – the whole "[prevTag]" (group 1)
  //      tagName         – just the name of the preceding tag (group 2)
  //  If the preceding tag is one of the tags that *must* keep the newline,
  //  we return the tag **plus** a newline, otherwise we return only the tag.
  const beforeTags = Patterns.getBreakLineBeforeTag(['ul', 'ol', 'li'], 'g');
  contents = contents.replace(beforeTags, (match, precedingTag, tagName) => {
    // If the preceding tag is in the “keep‑newline” list we preserve it,
    // otherwise we strip the newline.
    if (tags.includes(tagName)) {
      return precedingTag + '\n';
    }
    return precedingTag;      // newline removed
  });

  // -----------------------------------------------------------------
  //  The rest of the original logic (unchanged)
  // -----------------------------------------------------------------
  contents = contents.replace(/\[ml\]/g, '');
  contents = contents.replace(/\[\/ml\]/g, '\n');

  contents = contents.replace(/\n\[\/(center|justify|right|code)\]/g, (match, tag) => `[/${tag}]\n`);

  contents = contents.replace(/\[\/quote\]/g, (match) => match + '\n');

  // the `afterTags` replacement is already done above
  // (the original `contents.replace(afterTags, '')` is no longer needed)

  return contents;
}
```

### 3.  What changed, why it works

| Original pattern | New pattern | What it matches now |
|------------------|-------------|---------------------|
| `(?<=\[(?:${tags})\])\n` | `(\\[\\/?(?:${tags})\\])\\n` | captures the tag (`$1`) and the newline; the replace keeps `$1` and discards the newline. |
| `(?<=\\[\\/?(.*?)\\])\n+(?=\\[\\/?(?:${tags})\\])` | `(\\[\\/?([^\\]]+)\\])\\n+(?=\\[\\/?(?:${tags})\\])` | captures the preceding tag (`$1`) and its *name* (`$2`); the replacement can decide whether to keep the newline. |

No look‑behind is used any more, so the code now runs on iOS Safari (or any
other JavaScript engine that does not support `(?<=…)`). All other parts of
the parser remain untouched, so the behaviour is identical to the original
implementation.

