// src/routes/users.js
import { Router } from 'express';
import { getAll, getOne, create, update, remove } from '../models/userModel.js';

const router = Router();

/**
 * @route   GET /api/users
 * @desc    Obtener todos los usuarios
 */
router.get('/', (req, res) => {
  const users = getAll();
  res.json(users);
});

/**
 * @route   GET /api/users/:id
 * @desc    Obtener un usuario por ID
 */
router.get('/:id', (req, res) => {
  const user = getOne(req.params.id);
  if (!user) {
    return res.status(404).json({ message: 'Usuario no encontrado' });
  }
  res.json(user);
});

/**
 * @route   POST /api/users
 * @desc    Crear nuevo usuario
 * @body    { name: string, email: string }
 */
router.post('/', (req, res) => {
  const { name, email } = req.body;
  if (!name || !email) {
    return res.status(400).json({ message: 'Name y email son obligatorios' });
  }
  const newUser = create({ name, email });
  res.status(201).json(newUser);
});

/**
 * @route   PUT /api/users/:id
 * @desc    Actualizar usuario existente
 * @body    { name?: string, email?: string }
 */
router.put('/:id', (req, res) => {
  const updated = update(req.params.id, req.body);
  if (!updated) {
    return res.status(404).json({ message: 'Usuario no encontrado' });
  }
  res.json(updated);
});

/**
 * @route   DELETE /api/users/:id
 * @desc    Eliminar usuario
 */
router.delete('/:id', (req, res) => {
  const removed = remove(req.params.id);
  if (!removed) {
    return res.status(404).json({ message: 'Usuario no encontrado' });
  }
  res.json({ message: 'Usuario eliminado' });
});

export default router;
```

