## 5️⃣ src/models/userModel.js (data store en memoria)

> **Nota:** En un proyecto real normalmente usarías una base de datos (MongoDB, PostgreSQL, etc.). Aquí usamos un array para que la demo sea autoconclusiva.

```js
// src/models/userModel.js
let users = [
  // Algunos usuarios de ejemplo
  { id: '1', name: 'Ana Pérez', email: 'ana@example.com' },
  { id: '2', name: 'Luis Gómez', email: 'luis@example.com' },
];

// Generador simple de IDs (UUID v4 sería ideal en prod)
const generateId = () => `${Date.now()}${Math.floor(Math.random() * 1000)}`;

/* ---------- Operaciones CRUD ---------- */

export const getAll = () => {
  // Devuelve una copia para evitar mutaciones externas
  return [...users];
};

export const getOne = (id) => {
  return users.find((u) => u.id === id);
};

export const create = ({ name, email }) => {
  const newUser = { id: generateId(), name, email };
  users.push(newUser);
  return newUser;
};

export const update = (id, data) => {
  const index = users.findIndex((u) => u.id === id);
  if (index === -1) return null;

  const updatedUser = { ...users[index], ...data };
  users[index] = updatedUser;
  return updatedUser;
};

export const remove = (id) => {
  const index = users.findIndex((u) => u.id === id);
  if (index === -1) return false;
  users.splice(index, 1);
  return true;
};
```

