Ниже – полностью работающий фрагмент Java‑Script, в котором эти шаги уже реализованы.  

```javascript
$(".custom-select").each(function () {
    const $original = $(this);                     // оригинальный <select>
    const classes   = $original.attr("class");
    const placeholder = $original.attr("placeholder");   // значение placeholder

    // -----------------------------------------------------------------
    // 1) Сначала пытаемся «выбрать» нужный option по placeholder
    // -----------------------------------------------------------------
    let selectedOption = null;   // будем хранить найденный option (DOM‑элемент)

    $original.find("option").each(function () {
        if (placeholder && placeholder === $(this).attr("value")) {
            // совпало – делаем option выбранным
            $(this).prop("selected", true);
            selectedOption = this;                 // запомним, какая option выбрана
        }
    });

    // Если по placeholder ничего не нашли – оставляем выбранным первый option
    if (!selectedOption) {
        selectedOption = $original.find("option").first().get(0);
        $(selectedOption).prop("selected", true);
    }

    // -----------------------------------------------------------------
    // 2) Формируем шаблон кастомного селекта
    // -----------------------------------------------------------------
    let template = `<div class="${classes}">`;
    // Текст в триггере берём из выбранного option (не из placeholder)
    const triggerText = $(selectedOption).text();
    template += `<span class="custom-select-trigger">${triggerText}</span>`;
    template += '<div class="custom-options">';

    $original.find("option").each(function () {
        const $opt   = $(this);
        const optCls = $opt.attr("class") || "";
        const optVal = $opt.attr("value");
        const optTxt = $opt.html();

        // Добавляем класс `selection`, если это выбранный пункт
        const selectedClass = $opt.is(":selected") ? " selection" : "";
        template += `<span class="custom-option ${optCls}${selectedClass}"
                         data-value="${optVal}">${optTxt}</span>`;
    });

    template += "</div></div>";

    // -----------------------------------------------------------------
    // 3) Скрываем оригинальный <select> и вставляем наш шаблон
    // -----------------------------------------------------------------
    $original.wrap('<div class="custom-select-wrapper"></div>');
    $original.hide();
    $original.after(template);
});

/* -------------------------------------------------------------------------
   Дальнейшее поведение (hover, открытие/закрытие, выбор) – без изменений
   ------------------------------------------------------------------------- */
