    const $wrapper = $(this).parents(".custom-select-wrapper");
    const $select  = $wrapper.find("select");
    const value    = $(this).data("value");

    // 1) меняем значение оригинального select
    $select.val(value).trigger("change");

    // 2) обновляем стили выбранного пункта
    $(this).siblings(".custom-option").removeClass("selection");
    $(this).addClass("selection");

    // 3) закрываем список и меняем текст триггера
    $(this).parents(".custom-select")
           .removeClass("opened")
           .find(".custom-select-trigger")
           .text($(this).text());
});

