   *  Récupère le tableau des favoris depuis le localStorage
   * ------------------------------------------------------------- */
  static _getFavorites() {
    return JSON.parse(localStorage.getItem('favorites')) || [];
  }

  /* -------------------------------------------------------------
   *  Enregistre le tableau des favoris dans le localStorage
   * ------------------------------------------------------------- */
  static _setFavorites(favs) {
    localStorage.setItem('favorites', JSON.stringify(favs));
  }

  /* -------------------------------------------------------------
   *  L'id est‑il déjà en favoris ?
   * ------------------------------------------------------------- */
  static isFavorite(id) {
    return this._getFavorites().includes(id);
  }

  /* -------------------------------------------------------------
   *  Ajoute un id aux favoris
   * ------------------------------------------------------------- */
  static add(id) {
    const favs = this._getFavorites();
    if (!favs.includes(id)) {
      favs.push(id);
      this._setFavorites(favs);
    }
  }

  /* -------------------------------------------------------------
   *  Retire un id des favoris
   * ------------------------------------------------------------- */
  static remove(id) {
    const favs = this._getFavorites().filter(favId => favId !== id);
    this._setFavorites(favs);
  }

  /* -------------------------------------------------------------
   *  Bascule l’état (add ↔ remove) et retourne le nouvel état
   * ------------------------------------------------------------- */
  static toggle(id) {
    if (this.isFavorite(id)) {
      this.remove(id);
      return false;               // maintenant pas en favori
    } else {
      this.add(id);
      return true;                // maintenant en favori
    }
  }

  /* -------------------------------------------------------------
   *  Met à jour l’icône du bouton (appelé après un toggle)
   * ------------------------------------------------------------- */
  static updateButton($btn, isFav) {
    // on utilise les classes FontAwesome, mais on peut très facilement
    // remplacer par <img src="heart_filled.svg"> / <img src="heart.svg">
    $btn.classList.toggle('fav-added', isFav);   // utilitaire CSS
    $btn.innerHTML = isFav
      ? '<i class="fas fa-heart"></i>'   // cœur plein
      : '<i class="far fa-heart"></i>'; // cœur creux
  }
}

/* -----------------------------------------------------------------
 *  On expose l’objet au global (pour les liens `onclick` éventuels)
 * ----------------------------------------------------------------- */
window.FavoriteManager = FavoriteManager;
```

> **Pourquoi deux méthodes (`toggle` + `updateButton`) ?**  
> `toggle` s’occupe uniquement de la donnée (localStorage).  
> `updateButton` s’occupe uniquement de l’affichage.  
> Cela permet de les appeler séparément si, par exemple, on veut synchroniser
> l’état depuis un autre composant.

