<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <title>Excel 多 Sheet 预览 Demo</title>
  <style>
    body {font-family: Arial, sans-serif; margin: 20px;}
    .sheet-tab {margin-bottom: 10px;}
    .sheet-tab button {margin-right: 4px; padding: 6px 12px;}
    .sheet-content {border: 1px solid #ddd; padding: 10px; overflow:auto;}
