### 3. 核心 JavaScript (preview.js)

```js
// ==== 读取文件 ====
document.getElementById('excel-file').addEventListener('change', handleFileSelect);

function handleFileSelect(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();

  // 读取为二进制字符串（ArrayBuffer 更快，也可以使用 readAsBinaryString）
  reader.onload = e => {
    const data = new Uint8Array(e.target.result);
    const workbook = XLSX.read(data, {type: 'array'});
    renderWorkbook(workbook);
  };
  reader.readAsArrayBuffer(file);
}

// ==== 渲染工作簿 ====
function renderWorkbook(workbook) {
  const sheetTabs = document.getElementById('sheet-tabs');
  const container = document.getElementById('sheet-container');

  // 清空上一次的内容
  sheetTabs.innerHTML = '';
  container.innerHTML = '';

  const sheetNames = workbook.SheetNames; // ['Sheet1', 'Sheet2', ...]

  // 生成 Tab 按钮
  sheetNames.forEach((name, idx) => {
    const btn = document.createElement('button');
    btn.textContent = name;
    btn.dataset.idx = idx;
    btn.onclick = () => showSheet(idx);
    sheetTabs.appendChild(btn);
  });

  // 默认展示第一个 Sheet
  if (sheetNames.length > 0) showSheet(0);

  // ==== 展示单个 Sheet ====
  function showSheet(idx) {
    const name = sheetNames[idx];
    const ws = workbook.Sheets[name];
    // 将工作表转成 JSON（数组形式），方便渲染
    const json = XLSX.utils.sheet_to_json(ws, {header: 1, blankrows: false});
    // 创建 HTML Table
    const table = document.createElement('table');

    json.forEach((row, r) => {
      const tr = document.createElement('tr');
      row.forEach((cell, c) => {
        const cellEl = (r === 0) ? document.createElement('th') : document.createElement('td');
        cellEl.textContent = cell === undefined ? '' : cell;
        tr.appendChild(cellEl);
      });
      table.appendChild(tr);
    });

    container.innerHTML = ''; // 清空旧内容
    const title = document.createElement('h3');
    title.textContent = `Sheet: ${name}`;
    container.appendChild(title);
    container.appendChild(table);
  }
}
```

#### 代码说明

| 步骤 | 关键点 | 备注 |
|------|--------|------|
| **读取文件** | `FileReader.readAsArrayBuffer` → `Uint8Array` | `ArrayBuffer` 支持大文件，且兼容 `xlsx` 的 `type: 'array'` |
| **解析工作簿** | `XLSX.read(data, {type:'array'})` | `workbook.SheetNames` 得到所有 sheet 名称 |
| **生成 Tab 切换** | 动态创建 `<button>`，`onclick` 调用 `showSheet(idx)` | 简单的 UI，当然可以用 UI 框架（Bootstrap、Element UI）美化 |
| **sheet → HTML** | `XLSX.utils.sheet_to_json(ws, {header:1})` → 二维数组 → `<table>` | `header:1` 会把首行也当作普通行；若需要表头 **自动** 识别，可改为 `header:"A"` |
| **兼容性** | 支持 `xlsx`, `xls`, `csv` | 如果要兼容 `xlsb`（二进制）需要 `XLSX.read(data, {type:"array", bookType:"xlsb"})`，但浏览器端需要 `XLSX.read` 能解析的文件类型 |

> **小技巧**：如果希望保持 **合并单元格**、**单元格样式**（背景色、字体）可以改为 `XLSX.utils.sheet_to_html(ws)`，它会直接生成含 `<style>` 的 HTML（但体积会大且依赖 `html` 字符串的安全性）。示例：

```js
const html = XLSX.utils.sheet_to_html(ws, {editable:true, header:"A"});
container.innerHTML = html;
```

