```js
import ExcelJS from 'exceljs';

async function previewExcel(file) {
  const wb = new ExcelJS.Workbook();
  const buf = await file.arrayBuffer();
  await wb.xlsx.load(buf);

  const container = document.getElementById('sheet-container');
  container.innerHTML = '';

  // 这里演示把每个 sheet 渲染为 HTML <table>
  wb.eachSheet((worksheet, sheetId) => {
    const table = document.createElement('table');
    worksheet.eachRow((row, rowNumber) => {
      const tr = document.createElement('tr');
      row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
        const td = document.createElement('td');
        td.textContent = cell.value || '';
        // 合并单元格处理（仅示例，实际要处理 colspan/rowspan）
        if (cell.isMerged) {
          const master = cell.master;
          if (master && (master.row !== cell.row || master.col !== cell.col)) {
            // skip渲染，留给 master 处理
            return;
          }
          const merge = worksheet.getCell(master.address).model;
          if (merge && merge.colSpan) td.colSpan = merge.colSpan;
          if (merge && merge.rowSpan) td.rowSpan = merge.rowSpan;
        }
        // 样式（背景色、粗体）
        if (cell.style && cell.style.font && cell.style.font.bold) td.style.fontWeight = 'bold';
        if (cell.style && cell.style.fill && cell.style.fill.fgColor) {
          td.style.backgroundColor = `#${cell.style.fill.fgColor.argb.slice(2)}`;
        }
        tr.appendChild(td);
      });
      table.appendChild(tr);
    });
    // 添加标题
    const title = document.createElement('h4');
    title.textContent = `Sheet: ${worksheet.name}`;
    container.appendChild(title);
    container.appendChild(table);
  });
}
```

> **优势**：ExcelJS 支持 **读取图片、合并单元格、边框、字体样式**，渲染出来的表格会更接近原始排版。  
