## 完整示例（整合两种方式）

下面给出一个 **单页面 Demo**，可以 **先尝试本地预览**（SheetJS），如果用户勾选“使用 Office 在线预览”，则自动把文件上传到临时对象存储（示例使用 `axios` 向后端 `/upload` 接口），返回公开 URL 后用 iframe 渲染。

```html
<!DOCTYPE html>
<html lang="zh">
<head>
  <meta charset="UTF-8">
  <title>Excel 多 Sheet 预览（本地+Office）</title>
  <style>
    body {font-family:Arial,Helvetica, sans-serif; margin:20px;}
    #tabs button{margin:2px; padding:5px 10px;}
    #container {margin-top:15px;}
    iframe {width:100%; height:800px; border:none;}
  </style>
</head>
<body>
<h2>Excel 多 Sheet 预览 Demo</h2>
<input type="file" id="fileIn" accept=".xlsx,.xls,.csv" />
<label><input type="checkbox" id="useOffice" /> 使用 Office 在线预览 (需要后端上传)</label>
<div id="tabs"></div>
<div id="container"></div>

<script src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js"></script>
<script>
const fileInput = document.getElementById('fileIn');
const useOffice = document.getElementById('useOffice');
const tabsDiv = document.getElementById('tabs');
const container = document.getElementById('container');

fileInput.addEventListener('change', async e => {
  const file = e.target.files[0];
  if (!file) return;

  if (useOffice.checked) {
    // ---- 1️⃣ 上传至后端，获取公开 URL ----
    const form = new FormData();
    form.append('file', file);
    try {
      const {data} = await axios.post('/upload', form, {headers:{'Content-Type':'multipart/form-data'}});
      // 假设后端返回 {url: "https://cdn.example.com/xxxx.xlsx"}
      embedOffice(data.url);
    } catch (err) {
      console.error('Upload error', err);
      alert('上传失败，请检查后端接口');
    }
  } else {
    // ---- 2️⃣ 本地 SheetJS 渲染 ----
    const reader = new FileReader();
    reader.onload = ev => {
      const wb = XLSX.read(new Uint8Array(ev.target.result), {type:'array'});
      renderTabsAndSheets(wb);
    };
    reader.readAsArrayBuffer(file);
  }
});

// ---------- 本地渲染 ----------
function renderTabsAndSheets(workbook) {
  tabsDiv.innerHTML = '';
  container.innerHTML = '';
  const sheetNames = workbook.SheetNames;

  sheetNames.forEach((name, i) => {
    const btn = document.createElement('button');
    btn.textContent = name;
    btn.onclick = () => showSheet(i);
    tabsDiv.appendChild(btn);
  });

  if (sheetNames.length) showSheet(0);

  function showSheet(idx) {
    const ws = workbook.Sheets[workbook.SheetNames[idx]];
    const json = XLSX.utils.sheet_to_json(ws, {header:1, blankrows:false});
    const table = document.createElement('table');
    table.style.borderCollapse='collapse';
    json.forEach((row, r) => {
      const tr = document.createElement('tr');
      row.forEach(cell => {
        const el = (r===0) ? document.createElement('th') : document.createElement('td');
        el.textContent = cell===undefined? '' : cell;
        el.style.border='1px solid #ccc';
        el.style.padding='4px 6px';
        tr.appendChild(el);
      });
      table.appendChild(tr);
    });
    container.innerHTML = `<h3>Sheet: ${workbook.SheetNames[idx]}</h3>`;
    container.appendChild(table);
  }
}

// ---------- Office 在线渲染 ----------
function embedOffice(fileUrl) {
  tabsDiv.innerHTML = '';
  container.innerHTML = '';
  const viewer = 'https://view.officeapps.live.com/op/view.aspx?src=' + encodeURIComponent(fileUrl);
  const iframe = document.createElement('iframe');
  iframe.src = viewer;
  container.appendChild(iframe);
}
</script>
</body>
</html>
```

> **后端 `/upload` 示例（Node.js + Express + Multer）**  

```js
// npm i express multer cors
const express = require('express');
const multer = require('multer');
const cors = require('cors');
const path = require('path');
const app = express();
app.use(cors());

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, 'public/'),    // 存放目录
  filename: (req, file, cb) => cb(null, Date.now()+'_'+file.originalname)
});
const upload = multer({storage});

app.post('/upload', upload.single('file'), (req, res) => {
  const publicUrl = `${req.protocol}://${req.get('host')}/public/${req.file.filename}`;
  res.json({url: publicUrl});   // 前端拿到这个 URL 进行 Office 在线预览
});

app.use('/public', express.static(path.join(__dirname,'public')));

app.listen(3000,()=>console.log('服务器启动 http://localhost:3000'));
```

