<script>
    $('#playBtn').on('click', function () {
        // ---- 1️⃣  Make the request ----
        $.ajax({
            url: '/api/chat/getStream',        // ← your endpoint
            method: 'POST',                    // ← or GET, according to API
            data: { /* any payload */ },       // ← optional data
            cache: false,                      // prevent old cached responses
            // ------ 2️⃣  Tell XHR we want a binary Blob  ------
            xhrFields: {
                responseType: 'blob'            // <-- crucial! (jQuery 1.8+)
            },
            // ------ 3️⃣  Success handling ------
            success: function (blob) {
                // Convert the Blob (binary MP3) to a temporary URL
                const audioURL = URL.createObjectURL(blob);

                // Create a new <audio> element (you could reuse an existing one)
                const audio = new Audio();
                audio.src = audioURL;
                audio.controls = true;         // optional UI controls
                audio.autoplay = true;         // start automatically

                // Optional: clean up when playback ends
                audio.onended = () => {
                    URL.revokeObjectURL(audioURL); // free memory
                    audio.remove();                // remove the element if you like
                };

                // Insert into the page (or you could do document.body.appendChild)
                document.body.appendChild(audio);
            },
            // ------ 4️⃣  Error handling ------
            error: function (jqXHR, textStatus, errorThrown) {
                console.error('Failed to fetch MP3:', textStatus, errorThrown);
