```js
/**
 * Play an MP3 returned from the server.
 *
 * @param {Object} opts
 *   @property {string} url                – endpoint (e.g. '/api/chat/getStream')
 *   @property {Object} [data]            – POST payload (will be JSON‑stringified)
 *   @property {function(number)} [onProgress] – receives loaded bytes (0..1)
 *   @property {boolean} [autoplay=true] – start playing immediately
 *   @property {HTMLElement} [container=document.body] – where to insert <audio>
 *   @property {Object} [headers]        – extra HTTP headers (e.g. Authorization)
 */
function playMp3ViaAjax(opts) {
    const {
        url,
        data = null,
        onProgress = null,
        autoplay = true,
        container = document.body,
        headers = {}
    } = opts;

    // Try the modern Blob approach first
    const ajaxSettings = {
        url,
        method: 'POST',
        cache: false,
        xhrFields: { responseType: 'blob' },
        headers,
        success: handleBlob,
        error: handleError
    };

    if (data) ajaxSettings.data = JSON.stringify(data);
    if (data) ajaxSettings.contentType = 'application/json';

    // Progress events (only works when the browser supports them)
    ajaxSettings.xhr = function () {
        const xhr = new window.XMLHttpRequest();
        if (onProgress) {
            xhr.addEventListener('progress', function (e) {
                if (e.lengthComputable && onProgress) {
                    onProgress(e.loaded / e.total);
                }
            });
        }
        return xhr;
    };

    $.ajax(ajaxSettings);

    // -----------------------------------------------------------------
    function handleBlob(blob) {
        // Some very old browsers (IE) ignore `responseType: 'blob'` and give you a string.
        // Detect and fallback to a data‑URL if needed.
        if (typeof blob === 'string') {
            // Convert base64 string to Blob (skip for brevity – see below)
            console.warn('Blob fallback triggered – consider using fetch() for better compatibility.');
            // For now just attach the string directly (its content *might* be a data URL already)
            createAudioElement(blob);
            return;
        }

        const objectURL = URL.createObjectURL(blob);
        createAudioElement(objectURL);
    }

    function createAudioElement(src) {
        const audio = document.createElement('audio');
        audio.controls = true;
        audio.src = src;
        if (autoplay) audio.autoplay = true;

        // Clean up after playback finishes (or when element removed)
        audio.addEventListener('ended', () => {
            URL.revokeObjectURL(src);
        });
        audio.addEventListener('error', () => {
            console.error('Audio element failed to load/play');
            URL.revokeObjectURL(src);
        });

        container.appendChild(audio);
        // Return the element in case caller wants to keep a reference
        return audio;
    }

    function handleError(jqXHR, textStatus, err) {
        console.error('MP3 request failed:', textStatus, err);
        // Fallback: try a direct <audio src="url"> GET request (no POST data)
        if (!data) {
            const fallbackAudio = document.createElement('audio');
            fallbackAudio.controls = true;
            fallbackAudio.src = url;
            if (autoplay) fallbackAudio.autoplay = true;
            container.appendChild(fallbackAudio);
        }
    }
}
```

**Usage example**

```js
$('#playBtn').on('click', () => {
    playMp3ViaAjax({
        url: '/api/chat/getStream',
        data: { chatId: 12345 },
        onProgress: pct => console.log('download', (pct * 100).toFixed(1) + '%'),
        headers: { Authorization: 'Bearer ' + token }
    });
});
```

---

## 7️⃣  Quick checklist before you ship

| ✅ Item | Why it matters |
|--------|----------------|
| **Server sends `Content‑Type: audio/mpeg`** | Guarantees the browser knows it’s MP3. |
| **`responseType: 'blob'` (or `fetch(...).blob()`)** | Prevents automatic text conversion and preserves binary integrity. |
| **Object URL revoked** (`URL.revokeObjectURL`) | Avoids memory leaks, especially when playing many tracks. |
| **CORS headers** (`Access-Control-Allow-Origin`) | Needed if front‑end and API are on different origins. |
| **Error handling (network + audio element)** | Gives the user feedback instead of silent failures. |
| **Optional progress UI** (`xhr.onprogress` or `fetch` streams) | Improves UX for large files. |
| **Test on required browsers** (Chrome, Edge, Safari ≥ 14, Firefox) | Some older mobile browsers don’t support `responseType: 'blob'`. |
| **HTTPS** (or same‑origin) | Browsers block mixed‑content media requests. |
| **Security** – don’t expose raw file paths; use authentication tokens. | Prevents unauthorized downloads. |

---

## 8️⃣  TL;DR Recap (one‑liner)

```js
$.ajax({
    url: '/api/chat/getStream',
    method: 'POST',
    xhrFields: { responseType: 'blob' },
    success: b => { const a = new Audio(URL.createObjectURL(b)); a.play(); }
});
```

That line (plus correct server headers) is everything you need to fetch an MP3 with Ajax and play it instantly. 🎧

Happy coding! 🚀

