### 4.7 `src/routes/auth.js` – Register & Login

```js
import express from "express";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import dotenv from "dotenv";

import User from "../models/User.js";

dotenv.config();

const router = express.Router();

/**
 * @route   POST /api/auth/register
 * @desc    Register a new user
 * @access  Public
 */
router.post("/register", async (req, res) => {
  const { email, password } = req.body;

  // Simple validation
  if (!email || !password) {
    return res.status(400).json({ message: "Please provide email & password" });
  }

  try {
    // 1️⃣ Check if user already exists
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res
        .status(409)
        .json({ message: "User with that email already exists" });
    }

    // 2️⃣ Hash password
    const salt = await bcrypt.genSalt(10);
    const hashedPwd = await bcrypt.hash(password, salt);

    // 3️⃣ Create & save user
    const user = await User.create({ email, password: hashedPwd });

    // 4️⃣ Create JWT (payload can be any fields you need later)
    const payload = { id: user._id, email: user.email };
    const token = jwt.sign(payload, process.env.JWT_SECRET, {
      expiresIn: process.env.JWT_EXPIRES_IN || "7d",
    });

    // 5️⃣ Return token (you could also return user data if you wish)
    res.status(201).json({ token });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: "Server error" });
  }
});

/**
 * @route   POST /api/auth/login
 * @desc    Authenticate user & get token
 * @access  Public
 */
router.post("/login", async (req, res) => {
  const { email, password } = req.body;

  // Simple validation
  if (!email || !password) {
    return res.status(400).json({ message: "Please provide email & password" });
  }

  try {
    // 1️⃣ Find user
    const user = await User.findOne({ email });
    if (!user) {
      return res
        .status(401)
        .json({ message: "Invalid credentials (email not found)" });
    }

    // 2️⃣ Compare password
    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) {
      return res
        .status(401)
        .json({ message: "Invalid credentials (wrong password)" });
    }

    // 3️⃣ Sign JWT
    const payload = { id: user._id, email: user.email };
    const token = jwt.sign(payload, process.env.JWT_SECRET, {
      expiresIn: process.env.JWT_EXPIRES_IN || "7d",
    });

    // 4️⃣ Return token
    res.json({ token });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: "Server error" });
  }
});

export default router;
```

---

### 4.8 `src/server.js` – Main entry point

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";

import { connectDB } from "./config/db.js";
import authRoutes from "./routes/auth.js";
import { protect } from "./middleware/auth.js";

dotenv.config();

const app = express();

// ---- Middleware ----
app.use(cors()); // enable CORS (adjust origin in production)
app.use(express.json()); // parse JSON bodies

// ---- DB connection ----
connectDB();

// ---- Routes ----
app.get("/", (req, res) => res.send("API is running 🚀"));
app.use("/api/auth", authRoutes);

// Example of a protected route
app.get("/api/profile", protect, async (req, res) => {
  // `req.user` was set by the protect middleware
  res.json({
    message: "You are authenticated!",
    user: req.user, // { id, email } – whatever you encoded in the JWT
  });
});

// ---- Error handling (fallback) ----
app.use((req, res) => {
  res.status(404).json({ message: "Route not found" });
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server listening on ${PORT}`));
```

