<body>

<div class="card">
    <h1>حاسبة العمر</h1>

    <label for="birth">اختر تاريخ الميلاد:</label>
    <input type="date" id="birth" max="9999-12-31">

    <button id="calcBtn">احسب العمر</button>

    <div id="output" class="result"></div>
</div>

<script>
    // ---------- JavaScript ----------
    const birthInput = document.getElementById('birth');
    const calcBtn    = document.getElementById('calcBtn');
    const outputDiv  = document.getElementById('output');

    // دالة لحساب الفرق بين تاريخين بالسنوات، الشهور و الأيام
    function calculateAge(birthDate) {
        const now   = new Date();
        let years   = now.getFullYear() - birthDate.getFullYear();
        let months  = now.getMonth() - birthDate.getMonth();
        let days    = now.getDate() - birthDate.getDate();

        // تصحيح إذا كان الشهر أو اليوم سالباً
        if (days < 0) {
            // احصل على عدد أيام الشهر السابق
            const previousMonth = new Date(now.getFullYear(), now.getMonth(), 0);
            days += previousMonth.getDate();
            months--;
        }
        if (months < 0) {
            months += 12;
            years--;
        }

        return { years, months, days };
    }

    // حدث الضغط على الزر
    calcBtn.addEventListener('click', () => {
        const birthValue = birthInput.value;
        outputDiv.classList.remove('error');
        outputDiv.textContent = '';   // مسح النتيجة السابقة

        if (!birthValue) {
            outputDiv.textContent = 'من فضلك أدخل تاريخ الميلاد.';
            outputDiv.classList.add('error');
            return;
        }

        const birthDate = new Date(birthValue);
        const today = new Date();

        // منع اختيار تاريخ مستقبلي
        if (birthDate > today) {
            outputDiv.textContent = 'لا يمكن أن يكون تاريخ الميلاد في المستقبل.';
            outputDiv.classList.add('error');
            return;
        }

        const age = calculateAge(birthDate);
        outputDiv.textContent = `العمر: ${age.years} سنة، ${age.months} شهر، ${age.days} يوم`;
    });
</script>
</body>
</html>
```

