## 2️⃣ Database Helper – `lib/db.ts`

```ts
// lib/db.ts
import { Pool, PoolClient } from 'pg';

/**
 * 1️⃣ Create a connection pool.
 *    - `process.env.DATABASE_URL` should contain a full Postgres URI.
 *    - `ssl: { rejectUnauthorized: false }` is needed on some hosted services
 *      (e.g. Heroku). Remove it for local dev if you don't use TLS.
 */
export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false,
});

/**
 * 2️⃣ Helper that returns a dedicated client which is **listening** on a
 *    PostgreSQL channel (e.g. 'flight_updates').
 *
 *    We keep the client alive so that `LISTEN` stays active for the lifetime of
 *    the server process.
 */
export async function getListenerClient(channel: string, onNotify: (payload: string) => void) {
  // Grab a client from the pool – it will be dedicated to notifications only.
  const client: PoolClient = await pool.connect();

  // Make sure any previous listeners are cleared (defensive).
  await client.query(`UNLISTEN *`);

  // Register the callback that fires every time Postgres sends a NOTIFY.
  client.on('notification', async (msg) => {
    if (msg.channel === channel) {
      onNotify(msg.payload ?? '');
    }
  });

  // Begin listening on the named channel.
  await client.query(`LISTEN ${channel}`);

  // Return the client so the caller can later call client.release() if needed.
  return client;
}

/**
 * 3️⃣ Re‑export the query method for convenience elsewhere.
 */
export const query = (text: string, params?: any[]) => pool.query(text, params);
```

### What each line does

| Line(s) | Explanation |
|---------|-------------|
| `import { Pool, PoolClient }` | Pull in the pg client types. |
| `new Pool({ … })` | Creates a pool of reusable connections – optimal for a web server. |
| `connectionString: process.env.DATABASE_URL` | Externalises credentials; never hard‑code them. |
| `ssl: …` | Enables TLS in production (required by many cloud DBs). |
| `export async function getListenerClient` | Utility that starts a persistent listener for Postgres NOTIFY messages. |
| `client = await pool.connect()` | Takes a dedicated connection from the pool (must stay open). |
| `client.on('notification', …)` | Registers a Node.js event handler that fires on every DB NOTIFY. |
| `client.query('LISTEN …')` | Subscribes to a named channel – the DB will push to it. |
| `export const query` | A thin wrapper so we can write `query('SELECT …')` elsewhere without importing the pool each time. |

