## 4️⃣ Socket.io Server – Push DB Changes (`pages/api/socket.ts`)

```ts
// pages/api/socket.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import { Server as NetServer } from 'http';
import { Server as SocketIOServer } from 'socket.io';
import { getListenerClient } from '../../lib/db';

// ---------------------------------------------------------------------------
// 1️⃣ This file **only runs once** because we store the Socket.io instance on
//    the Next.js server (`global`) – otherwise every API call would create a
//    brand‑new WebSocket server.
// ---------------------------------------------------------------------------
export default function handler(req: NextApiRequest, res: NextApiResponse) {
  // -------------------------------------------------
  // 2️⃣ Upgrade the HTTP request to a WebSocket connection
  // -------------------------------------------------
  if (!res.socket.server.io) {
    console.log('🔧 Setting up Socket.io server…');

    // 2a️⃣ Grab the underlying raw http.Server from Next.js.
    const httpServer: NetServer = res.socket.server as any;
    const io = new SocketIOServer(httpServer, {
      // Options – allow CORS from the same origin (your Next.js app)
      cors: {
        origin: '*', // 👉 In production replace `*` with your domain.
        methods: ['GET', 'POST'],
      },
    });

    // 2b️⃣ Store it globally so later calls see the same instance.
    res.socket.server.io = io;

    // -------------------------------------------------
    // 3️⃣ When a client connects, we just log for demo.
    // -------------------------------------------------
    io.on('connection', (socket) => {
      console.log('🟢 New client connected:', socket.id);
    });

    // -------------------------------------------------
    // 4️⃣ Listen to PostgreSQL NOTIFY events and forward them.
    // -------------------------------------------------
    // The DB must emit NOTIFY on the channel 'flight_updates' with the
    // changed flight row (as JSON) as the payload.
    getListenerClient('flight_updates', (payload) => {
      try {
        const data = JSON.parse(payload);
        // Broadcast the change to *all* connected browsers.
        io.emit('flightUpdate', data);
        console.log('📡 Forwarded flight update →', data);
      } catch (e) {
        console.error('❗️ Failed to parse NOTIFY payload:', payload);
      }
    });
  }

  // -------------------------------------------------
  // 5️⃣ End the API request – the WebSocket lives on the
  //    underlying http server, not this response.
  // -------------------------------------------------
  res.end();
}
```

### Explanation of every block

| Block | What it does |
|-------|--------------|
| `if (!res.socket.server.io) { … }` | **Singleton pattern** – ensures the Socket.io server is created only once per Node process. Next.js re‑uses the same `http.Server` for every API request, so we can stash the `io` instance on the server socket. |
| `const httpServer: NetServer = res.socket.server as any;` | Extract the raw Node `http.Server` that Next.js is using under the hood. |
| `new SocketIOServer(httpServer, { cors … })` | Starts a Socket.io server that attaches to the same port (no extra port needed). |
| `io.on('connection', …)` | Fires when a browser opens a WebSocket – nice place to send a “welcome” message or authenticate. |
| `getListenerClient('flight_updates', …)` | Calls the helper from `lib/db.ts`. It opens a dedicated Postgres client that runs `LISTEN flight_updates`. Whenever the DB emits a `NOTIFY`, the callback runs. |
| `io.emit('flightUpdate', data)` | Broadcasts the change to **every** connected client. (`flightUpdate` is the event name the front‑end will listen for.) |
| `res.end()` | Ends the HTTP request – the real communication now happens over the persistent WebSocket. |

