// pages/flights.tsx
import { useEffect, useState } from 'react';
import type { GetServerSideProps, NextPage } from 'next';
import io from 'socket.io-client';
import Head from 'next/head';

// -------------------------------------------------
// 1️⃣ TypeScript type that mirrors the DB row.
// -------------------------------------------------
export type Flight = {
  id: number;
  airline: string;
  flight_number: string;
  departure_airport: string;
  arrival_airport: string;
  departure_time: string; // ISO string (UTC)
  arrival_time: string;   // ISO string (UTC)
  status: string;
};

// -------------------------------------------------
// 2️⃣ Props passed from `getServerSideProps`.
// -------------------------------------------------
type Props = {
  initialFlights: Flight[];
};

// -------------------------------------------------
// 3️⃣ The page component.
// -------------------------------------------------
const FlightsPage: NextPage<Props> = ({ initialFlights }) => {
  // a) Local state holds the current list shown on the UI.
  const [flights, setFlights] = useState<Flight[]>(initialFlights);

  // -------------------------------------------------
  // b) Establish a single Socket.io connection (once).
  // -------------------------------------------------
  useEffect(() => {
    // 👉 `socket.io-client` automatically tries the same origin.
    const socket = io();

    // c) Listen for the event emitted by the server.
    socket.on('flightUpdate', (msg: { operation: string; row: Flight }) => {
      console.log('🚀 Received flight update:', msg);
      setFlights((prev) => {
        const { operation, row } = msg;
        // -----------------------------------------------------------------
        //   – INSERT → push to the array (keeping order by departure_time)
        //   – UPDATE → replace the matching row
        //   – DELETE → filter it out
        // -----------------------------------------------------------------
        if (operation === 'INSERT') {
          return [...prev, row].sort(
            (a, b) => new Date(a.departure_time).valueOf() - new Date(b.departure_time).valueOf()
          );
        }
        if (operation === 'UPDATE') {
          return prev
            .map((f) => (f.id === row.id ? row : f))
            .sort(
              (a, b) => new Date(a.departure_time).valueOf() - new Date(b.departure_time).valueOf()
            );
        }
        // DELETE
        return prev.filter((f) => f.id !== row.id);
      });
    });

    // Clean up on unmount – close the WS connection.
    return () => {
      socket.disconnect();
    };
  }, []); // Empty dependency array ⇒ runs once on mount.

  // -------------------------------------------------
  // 4️⃣ Render a simple table.
  // -------------------------------------------------
  return (
    <>
      <Head>
        <title>Live Flight Board</title>
        <meta name="description" content="Server‑side rendered flight information with live updates." />
      </Head>

      <main style={{ padding: '2rem' }}>
        <h1>🛫 Live Flight Board</h1>

        <table
          style={{
            width: '100%',
            borderCollapse: 'collapse',
            marginTop: '1rem',
          }}
        >
          <thead>
            <tr style={{ borderBottom: '2px solid #444' }}>
              <th>Airline</th>
              <th>Flight #</th>
              <th>From → To</th>
              <th>Departs (UTC)</th>
              <th>Arrives (UTC)</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {flights.map((f) => (
              <tr key={f.id} style={{ borderBottom: '1px solid #ccc' }}>
                <td>{f.airline}</td>
                <td>{f.flight_number}</td>
                <td>{f.departure_airport} → {f.arrival_airport}</td>
                <td>{new Date(f.departure_time).toLocaleString('en-GB', { timeZone: 'UTC', hour12: false })}</td>
                <td>{new Date(f.arrival_time).toLocaleString('en-GB', { timeZone: 'UTC', hour12: false })}</td>
                <td>{f.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </main>
    </>
  );
};

// -------------------------------------------------
// 5️⃣ `getServerSideProps` – runs on every HTTP request.
// -------------------------------------------------
export const getServerSideProps: GetServerSideProps<Props> = async () => {
  // a) Call the internal API we created earlier (or query DB directly).
  const res = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL}/api/flights`);
  const initialFlights: Flight[] = await res.json();

  // b) Pass the data to the component as a prop.
  return { props: { initialFlights } };
};

export default FlightsPage;
```

### Line‑by‑line walk‑through

| Section | What it does |
|---------|--------------|
| **Types (`Flight`, `Props`)** | Describes the shape of data we receive from Postgres; guarantees type safety throughout the component. |
| `useState<Flight[]>(initialFlights)` | Stores the list locally. The initial value comes from the server‑side render, guaranteeing the first paint already has data (no loading spinner needed). |
| `useEffect(() => { … }, [])` | Runs once when the component mounts – opens a WebSocket connection via `socket.io-client`. |
| `socket.on('flightUpdate', …)` | Listens for updates pushed from the server (insert / update / delete). When a message arrives we **optimistically merge** it into the current UI state. |
| `setFlights(prev => …)` | Immutable state update. The three branches (`INSERT`, `UPDATE`, `DELETE`) modify the array accordingly while sorting by departure time so the UI stays ordered. |
| `socket.disconnect()` | Clean‑up to avoid memory leaks if the user navigates away. |
| **Render (`<table>`)** | Simple HTML table styled with inline CSS – you could replace it with Tailwind, Material‑UI, etc. |
