// analyze-tsx-deps.js
const fs = require('node:fs');
const path = require('node:path');
const parser = require('@babel/parser');
const traverse = require('@babel/traverse').default;

/**
 * 读取并解析一个 .tsx/.ts/.jsx/.js 文件，返回所有「运行时」依赖模块名。
 *
 * @param {string} filePath           目标文件的绝对路径或相对路径（相对于 process.cwd()）
 * @param {object} [options]          可选配置
 * @param {boolean} [options.includeTypeOnly]   是否保留 `import type …`（默认 false）
 * @param {boolean} [options.includeDevDeps]    是否保留 `/// <reference types="…"/>` 之类的引用（默认 false）
 * @returns {Promise<string[]>}      按出现顺序去重后的依赖列表
 */
async function analyzeTSXDependencies(filePath, options = {}) {
  const {
    includeTypeOnly = false,
    includeDevDeps = false,
  } = options;

  // 1️⃣ 读取文件内容
  const absolutePath = path.isAbsolute(filePath)
    ? filePath
    : path.resolve(process.cwd(), filePath);
  const code = await fs.promises.readFile(absolutePath, 'utf8');

  // 2️⃣ 使用 Babel parser 解析（开启所有可能的语法特性）
  const ast = parser.parse(code, {
    sourceType: 'module', // 支持 import/export
    plugins: [
      'typescript',
      'jsx',
      'classProperties',
      'classPrivateProperties',
      'classPrivateMethods',
      'decorators-legacy',
      'dynamicImport',
      'exportDefaultFrom',
      'exportNamespaceFrom',
      // 下面的插件基本不影响依赖收集，但可以让 parser 更宽容
      'optionalChaining',
      'nullishCoalescingOperator',
      'objectRestSpread',
    ],
    // 让 parser 能识别 // @ts-ignore、/// <reference …/> 这类 TS 注释
    allowUndeclaredExports: true,
    errorRecovery: true,
  });

  // 3️⃣ 遍历 AST 收集模块名
  const deps = [];          // 按出现顺序保存（后面会去重）
  const seen = new Set();   // 用来去重

  function addDep(moduleName, node) {
    if (!moduleName) return;
    // 为了兼容 dynamic import、require 等在运行时可能是表达式的情况，
    // 只收集字面量字符串（Literal）或 TemplateLiteral (没有占位符) 的值。
    if (typeof moduleName !== 'string') return;
    if (!seen.has(moduleName)) {
      seen.add(moduleName);
      deps.push(moduleName);
    }
  }

  traverse(ast, {
    // -------- 1️⃣ 静态 ES import ----------
    ImportDeclaration(path) {
      // import type … from 'foo'（type‑only import）
      const isTypeOnly = path.node.importKind === 'type';
      if (isTypeOnly && !includeTypeOnly) return;

      // source.value 为字符串字面量
      addDep(path.node.source.value, path.node);
    },

    // -------- 2️⃣ 再导出时的来源 ----------
    ExportAllDeclaration(path) {
      // export * from 'foo';
      addDep(path.node.source.value, path.node);
    },

    ExportNamedDeclaration(path) {
      // export { X } from 'foo';
      if (path.node.source) {
        addDep(path.node.source.value, path.node);
      }
    },

    // -------- 3️⃣ 动态 import ----------
    Import(path) {
      // 这里捕获的其实是 CallExpression: import('foo')
      const parent = path.parentPath;
      if (parent.isCallExpression()) {
        const arg = parent.node.arguments[0];
        if (arg && arg.type === 'StringLiteral') {
          addDep(arg.value, parent.node);
        } else if (
          arg &&
          arg.type === 'TemplateLiteral' &&
          arg.expressions.length === 0
        ) {
          // `import(`foo`)` 这种没有占位符的模板字符串
          addDep(arg.quasis[0].value.cooked, parent.node);
        }
      }
    },

    // -------- 4️⃣ CommonJS require ----------
    CallExpression(path) {
      // require('foo')
      if (
        path.node.callee.type === 'Identifier' &&
        path.node.callee.name === 'require' &&
        path.node.arguments.length === 1
      ) {
        const arg = path.node.arguments[0];
        if (arg.type === 'StringLiteral') {
          addDep(arg.value, path.node);
        } else if (
          arg.type === 'TemplateLiteral' &&
          arg.expressions.length === 0
        ) {
          addDep(arg.quasis[0].value.cooked, path.node);
        }
      }
    },

    // -------- 5️⃣ TypeScript 特殊 import = require ----------
    TSImportEqualsDeclaration(path) {
      // import foo = require('foo')
      if (path.node.moduleReference.type === 'TSExternalModuleReference') {
        const expr = path.node.moduleReference.expression;
        if (expr && expr.type === 'StringLiteral') {
          addDep(expr.value, path.node);
        }
      }
    },

    // -------- 6️⃣ export = … (CommonJS) ----------
    ExportAssignment(path) {
      // export = foo;   // 只会把整个文件当作一个模块，通常不算外部依赖
      // 这里不做任何处理
    },

    // -------- 7️⃣ 处理 triple‑slash reference ----------
    // 例如：/// <reference types="node" />
    // 这类声明并不是真正的 runtime 依赖，默认不收
    TSReferenceDirective(path) {
      if (includeDevDeps && path.node.types) {
        addDep(path.node.types, path.node);
      }
    },
  });

  return deps;
}

// ---------- 示例用法 ----------
async function demo() {
  const file = './example.tsx'; // 换成你的文件路径
  try {
    const deps = await analyzeTSXDependencies(file, {
      includeTypeOnly: false, // 如需保留 type‑only 则改为 true
      includeDevDeps: false,
    });
    console.log('Dependencies in', file);
    console.log(deps);
  } catch (e) {
    console.error('Error while analyzing:', e);
  }
}

// 如果直接运行此文件，就执行 demo
if (require.main === module) {
  demo();
}

// 导出让其他模块也能复用
module.exports = {
  analyzeTSXDependencies,
};
