## 2. Пример с `sqlite3` (callbacks)

```js
// server.js
const express = require('express');
const sqlite3 = require('sqlite3').verbose(); // включаем расширенный режим

const app = express();
const PORT = 3000;

// ── Подключаемся к базе (файл mydb.sqlite3) ───────────────────────────────
const db = new sqlite3.Database('./mydb.sqlite3', err => {
  if (err) {
    console.error('Не удалось открыть БД:', err.message);
    process.exit(1);
  }
  console.log('Подключены к SQLite');
});

// ── Маршрут, который возвращает двумерный массив ───────────────────────────
app.get('/data', (req, res) => {
  const sql = `SELECT id, name, age FROM users`; // <-- любой ваш SELECT

  db.all(sql, [], (err, rows) => {
    if (err) {
      console.error('Ошибка SQL:', err.message);
      return res.status(500).json({ error: err.message });
    }

    // rows – массив объектов: [{id:1, name:'Bob', age:23}, {...}]
    // Преобразуем в массив массивов:
    const result = rows.map(row => [row.id, row.name, row.age]);

    // Если хотите добавить шапку (именя столбцов) – раскомментируйте:
    // const header = ['id', 'name', 'age'];
    // const result = [header, ...rows.map(Object.values)];

    res.json(result); // отправляем JSON
  });
});

// ── Запуск сервера ────────────────────────────────────────────────────────
app.listen(PORT, () => {
  console.log(`Express слушает http://localhost:${PORT}`);
});
```

### Как это работает

| Шаг | Что делает |
|-----|------------|
| `db.all(sql, [], cb)` | Выполняет запрос и возвращает **массив объектов** (`rows`). |
| `rows.map(row => [row.id, row.name, row.age])` | Берём каждый объект и вытягиваем нужные поля в массив. Получаем `[[1,'Bob',23], [2,'Alice',31], …]`. |
| `res.json(result)` | Отдаём клиенту JSON‑представление двумерного массива. |

> **Важно:** порядок столбцов в `SELECT`-запросе определяет порядок элементов в вложенных массивах. Если вы хотите гибко менять набор столбцов, используйте `Object.values(row)` (подробнее ниже).

