// ── Инициализируем БД и сервер ─────────────────────────────────────────────
(async () => {
  try {
    db = await open({
      filename: './mydb.sqlite3',
      driver: sqlite3.Database
    });
    console.log('Подключены к SQLite (async/await)');

    // Запускаем сервер только после успешного открытия БД
    app.listen(PORT, () => {
      console.log(`Express слушает http://localhost:${PORT}`);
    });
  } catch (e) {
    console.error('Не удалось открыть БД:', e);
    process.exit(1);
  }
})();

