## 2️⃣ The Node.js WebSocket Server

### 2.1 Create a project folder

```powershell
mkdir SimpleChat
cd SimpleChat
```

### 2.2 Initialise npm and install the `ws` package

```powershell
npm init -y               # creates a bare package.json
npm install ws           # the popular WebSocket library
```

### 2.3 `server.js`

Create a file named **`server.js`** in the same folder and paste the code below:

```js
// server.js
// ----------------------------------------------------------
// Simple WebSocket chat server (Node.js + ws)
// ----------------------------------------------------------

const WebSocket = require('ws');

// ----- Configuration -------------------------------------------------
const PORT = 8080;                     // change if you need another port
// ---------------------------------------------------------------------

// Create a WebSocket server
const wss = new WebSocket.Server({ port: PORT }, () => {
  console.log(`🟢  Chat server listening on ws://localhost:${PORT}`);
});

// Keep a Set of all connected clients
const clients = new Set();

wss.on('connection', (ws) => {
  console.log('🔵 New client connected');
  clients.add(ws);

  // Broadcast any message we receive from this client to all others
  ws.on('message', (msg) => {
    // Prepend a timestamp (optional)
    const timestamp = new Date().toLocaleTimeString();
    const payload   = `[${timestamp}] ${msg}`;

    console.log(`📨 Received: ${payload}`);

    // Send to **every** client (including the sender)
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(payload);
      }
    }
  });

  ws.on('close', () => {
    console.log('⚪ Client disconnected');
    clients.delete(ws);
  });

  ws.on('error', (err) => {
    console.error('❌ WebSocket error:', err);
  });
});

// Graceful shutdown (Ctrl‑C)
process.on('SIGINT', () => {
  console.log('\n🛑 Shutting down server...');
  wss.close(() => process.exit(0));
});
```

### 2.4 Run the server

```powershell
node server.js
```

You should now see:

```
🟢  Chat server listening on ws://localhost:8080
```

