// src/lib/api.ts
import axios from 'axios';
import axiosRetry from 'axios-retry';

// Base URL from Vite env (VITE_ prefix is exposed to client)
const api = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL,
  withCredentials: true, // send HttpOnly cookies automatically
  headers: {
    'Content-Type': 'application/json',
  },
});

// Retry on network errors / 5xx (max 2 retries)
axiosRetry(api, { retries: 2, retryDelay: axiosRetry.exponentialDelay });

/**
 * Response interceptor – extracts data, handles global errors.
 */
api.interceptors.response.use(
  (response) => response.data,
  (error) => {
    // If the error is a 401, we can trigger a logout automatically.
    if (error.response?.status === 401) {
      // Could broadcast a logout event or call a context method.
      // For now we just reject and let the UI handle it.
    }
    return Promise.reject(error);
  }
);

export default api;
```

