```js
// src/controllers/openaiController.js
import { Configuration, OpenAIApi } from 'openai';

// Config da SDK (global, pode ser reutilizada)
const configuration = new Configuration({
  apiKey: process.env.OPENAI_API_KEY,
});
const openai = new OpenAIApi(configuration);

/* ------------------------------------------------------------------- */
/* 1️⃣ Chat Completion (GPT-3.5 / GPT-4)                                 */
export const chatCompletion = async (req, res, next) => {
  try {
    const {
      model = 'gpt-3.5-turbo',
      messages,
      temperature = 0.7,
      max_tokens,
    } = req.body;

    if (!Array.isArray(messages) || messages.length === 0) {
      return res.status(400).json({ error: 'Campo "messages" é obrigatório e deve ser um array.' });
    }

    const response = await openai.createChatCompletion({
      model,
      messages,
      temperature,
      max_tokens,
    });

    // Retorna exatamente o que a OpenAI devolve (ou pode filtrar)
    res.json(response.data);
  } catch (err) {
    next(err);
  }
};

/* ------------------------------------------------------------------- */
/* 2️⃣ Generate Image (DALL·E)                                          */
export const createImage = async (req, res, next) => {
  try {
    const {
      prompt,
      n = 1,
      size = '1024x1024', // 256x256 | 512x512 | 1024x1024
    } = req.body;

    if (!prompt) {
      return res.status(400).json({ error: 'Campo "prompt" é obrigatório.' });
    }

    const response = await openai.createImage({
      prompt,
      n,
      size,
    });

    res.json(response.data);
  } catch (err) {
    next(err);
  }
};

/* ------------------------------------------------------------------- */
/* 3️⃣ Embeddings (texto → vetor)                                        */
export const embeddings = async (req, res, next) => {
  try {
    const { model = 'text-embedding-ada-002', input } = req.body;

    if (!input) {
      return res.status(400).json({ error: 'Campo "input" é obrigatório.' });
    }

    const response = await openai.createEmbedding({
      model,
      input,
    });

    res.json(response.data);
  } catch (err) {
    next(err);
  }
};
```

### 3.3 Tratamento de erros (`src/middlewares/errorHandler.js`)

```js
// src/middlewares/errorHandler.js
export default function errorHandler(err, req, res, next) {
  console.error('[ERROR]', err);

  // Se o erro vier da SDK OpenAI, tem a estrutura `response`
  if (err.response) {
    const { status, data } = err.response;
    return res.status(status).json({
      error: data?.error?.message || 'Erro da OpenAI',
      details: data?.error,
    });
  }

  // Erro genérico
  res.status(err.status || 500).json({
    error: err.message || 'Erro interno do servidor',
  });
}
```

