## ⚡ 4️⃣ `assets/js/app.js` – the heart of the SPA

```js
/* ---------------------------------------------------
   app.js – UI rendering, routing, search, reservation
   --------------------------------------------------- */

// ---------- Helper utilities ----------
function $(sel) {return document.querySelector(sel);}
function $$(sel) {return document.querySelectorAll(sel);}
function formatPrice(v) {return `$${v.toFixed(2)}`;}
function stars(rating) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5;
  let html = "";
  for (let i = 0; i < full; i++) html += '<i class="fa-solid fa-star"></i>';
  if (half) html += '<i class="fa-solid fa-star-half-stroke"></i>';
  for (let i = full + (half?1:0); i < 5; i++) html += '<i class="fa-regular fa-star"></i>';
  return html;
}

// ---------- Rendering ----------
function renderCatalog(filter = "") {
  const container = document.createElement("section");
  container.className = "catalog";

  const filtered = EQUIPMENT.filter(item =>
    item.name.toLowerCase().includes(filter.toLowerCase())
  );

  filtered.forEach(item => {
    const card = document.createElement("article");
    card.className = "card";
    card.innerHTML = `
      <img src="${item.images[0]}" alt="${item.name}">
      <div class="content">
        <h3>${item.name}</h3>
        <div class="rating">${stars(item.rating)}</div>
        <div class="price">${formatPrice(item.price)}</div>
      </div>
    `;
    card.addEventListener("click", () => navigateTo(`#item=${item.id}`));
    container.appendChild(card);
  });

  if (filtered.length === 0) {
    container.innerHTML = `<p style="grid-column:1/-1; text-align:center;">No items match your search.</p>`;
  }

  $("#app").innerHTML = "";
  $("#app").appendChild(container);
}

function renderDetail(id) {
  const item = EQUIPMENT.find(p => p.id === id);
  if (!item) {
    $("#app").innerHTML = `<p>Item not found.</p>`;
    return;
  }

  // --------- Gallery (image carousel) ----------
  let curIdx = 0;
  const galleryDiv = document.createElement("div");
  galleryDiv.className = "gallery";

  const imgEl = document.createElement("img");
  imgEl.src = item.images[0];
  imgEl.alt = item.name;
  galleryDiv.appendChild(imgEl);

  if (item.images.length > 1) {
    const prevBtn = document.createElement("button");
    const nextBtn = document.createElement("button");
    prevBtn.className = "prev";
    nextBtn.className = "next";
    prevBtn.innerHTML = '<i class="fa-solid fa-chevron-left"></i>';
    nextBtn.innerHTML = '<i class="fa-solid fa-chevron-right"></i>';
    galleryDiv.appendChild(prevBtn);
    galleryDiv.appendChild(nextBtn);

    function updateImg() {
      imgEl.src = item.images[curIdx];
    }
    prevBtn.onclick = () => {
      curIdx = (curIdx - 1 + item.images.length) % item.images.length;
      updateImg();
    };
    nextBtn.onclick = () => {
      curIdx = (curIdx + 1) % item.images.length;
      updateImg();
    };
  }

  // --------- Video (if any) ----------
  const videoDiv = item.video
    ? `<iframe src="${item.video}" title="${item.name} video" frameborder="0" allowfullscreen></iframe>`
    : "";

  // --------- Features ----------
  const featuresHtml = item.features.map(f => `<li>${f}</li>`).join("");

  // --------- Reservation form ----------
  const reservationForm = document.createElement("form");
  reservationForm.className = "reservation";
  reservationForm.innerHTML = `
    <h3>Reserve this item</h3>
    <input type="text" name="name" placeholder="Your name" required>
    <input type="email" name="email" placeholder="Your email" required>
    <input type="date" name="date" required>
    <textarea name="notes" placeholder="Any notes (optional)"></textarea>
    <button type="submit">Reserve</button>
  `;

  reservationForm.addEventListener("submit", e => {
    e.preventDefault();
    const data = {
      id: item.id,
      name: reservationForm.name.value.trim(),
      email: reservationForm.email.value.trim(),
      date: reservationForm.date.value,
      notes: reservationForm.notes.value.trim()
    };
    // Save to localStorage (array of reservations)
    const key = "reservations";
    const existing = JSON.parse(localStorage.getItem(key) || "[]");
    existing.push(data);
    localStorage.setItem(key, JSON.stringify(existing));

    // Reset form & show toast
    reservationForm.reset();
    showToast("Reservation saved! 🎉");
  });

  // --------- Assemble everything ----------
  const html = `
    <section class="detail">
      <h2>${item.name}</h2>
      <div class="rating">${stars(item.rating)}</div>
      <div class="price">${formatPrice(item.price)}</div>

      ${galleryDiv.outerHTML}
      ${videoDiv}

      <p>${item.description}</p>
      <h4>Features</h4>
      <ul class="features">${featuresHtml}</ul>

      ${reservationForm.outerHTML}
    </section>
  `;

  $("#app").innerHTML = html;
}

// ---------- Toast ----------
function showToast(msg) {
  const toast = $("#toast");
  toast.textContent = msg;
  toast.classList.remove("hidden");
  toast.classList.add("show");
  setTimeout(() => {
    toast.classList.remove("show");
    toast.classList.add("hidden");
  }, 3000);
}

// ---------- Routing ----------
function handleHash() {
  const hash = location.hash.slice(1); // remove #
  if (!hash) {
    renderCatalog($("#searchInput").value);
    return;
  }
  const params = new URLSearchParams(hash);
  if (params.has("item")) {
    renderDetail(params.get("item"));
  } else {
    renderCatalog($("#searchInput").value);
  }
}
function navigateTo(hash) {
  location.hash = hash;
}

// ---------- Search ----------
$("#searchInput").addEventListener("input", e => {
  const term = e.target.value;
  const currentHash = location.hash;
  // We stay on the same view (catalog) while typing
  if (!currentHash.includes("item=")) {
    renderCatalog(term);
  }
});

// ---------- Init ----------
window.addEventListener("hashchange", handleHash);
window.addEventListener("DOMContentLoaded", () => {
  // First render – either catalog or a deep‑linked item
  handleHash();
});
```

### What this script does

| Feature | How it works |
|----------|-------------|
| **Catalog rendering** | `renderCatalog()` builds a grid of cards. Clicking a card updates URL hash (`#item=some-id`) which triggers the router. |
| **Search** | The `<input type="search">` fires on every keystroke; we re‑render the catalog using the current filter string. |
| **Routing** | Pure hash‑based router – no page reload. `handleHash()` reads the hash, decides whether to show a catalogue or a detail view. |
| **Detail view** | Shows a carousel for any number of images, optionally an embedded YouTube video, description, feature list, rating stars, price. |
| **Reservation form** | Simple `<form>` validates required fields (HTML5). On submit we store a JSON record in `localStorage` under `"reservations"` and pop a toast. No server needed. |
| **Responsive** | CSS control layout; JS only deals with data. |
| **Deep‑linkable** | If someone opens `index.html#item=dumbbells-01` they land straight on that product – great for sharing. |

