const USERS_KEY  = 'repapedik_users';

// Получаем корзину из localStorage (массив объектов)
function getCart() {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
}

// Записать корзину
function setCart(cart) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(cart));
}

// Добавить товар в корзину
function addToCart(product) {
    const cart = getCart();
    const existing = cart.find(item => item.id === product.id);
    if (existing) {
        existing.qty++;
    } else {
        cart.push({ ...product, qty:1 });
    }
    setCart(cart);
    alert(`Товар «${product.name}» добавлен в корзину!`);
    updateCartCount();
}

// Вывести количество товаров в шапке (кнопка корзины)
function updateCartCount() {
    const cart = getCart();
    const count = cart.reduce((sum, it) => sum + it.qty, 0);
    const badge = document.getElementById('cart-count');
    if (badge) badge.textContent = count;
}

// ---------- Регистрация ----------
function registerUser(form) {
    const name = form.name.value.trim();
    const email = form.email.value.trim().toLowerCase();
    const pass = form.password.value;

    if (!name || !email || !pass) {
        alert('Заполните все поля!');
        return false;
    }

    const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    if (users.some(u => u.email === email)) {
        alert('Пользователь с таким email уже зарегистрирован');
        return false;
    }

    users.push({ name, email, pass });
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
    alert('Регистрация прошла успешно! Теперь вы можете входить.');
    form.reset();
    return false; // не отправляем форму по умолчанию
}

