    const params = node
      .getParameters()
      .map(p => p.getName() + (p.getTypeNode() ? `: ${p.getTypeNode()!.getText()}` : ""));
    const returnType = node.getReturnTypeNode()?.getText();

    functions.push({
      name,
      params,
      returnType,
      file: node.getSourceFile().getFilePath(),
    });
    // No need to walk inside the function body if you only care about its signature:
    return; // stop traversing this node’s children
  }

  // -------------------------------------------------
  // 2️⃣  CASES we *want to ignore* – `ImportDeclaration` (proof of early exit)
  // -------------------------------------------------
  if (node.getKind() === SyntaxKind.ImportDeclaration) {
    return; // Skip walking its children (they’re irrelevant for most analyses)
  }

  // -------------------------------------------------
  // 3️⃣  Default – continue walking all children
  // -------------------------------------------------
  node.forEachChild(visit);
}

// -------------------------------------------------------------------
// Output what we collected
// -------------------------------------------------------------------
console.log("=== Functions found ===");
functions.forEach(fn => {
  console.log(`${fn.file}: ${fn.name}(${fn.params.join(", ")})${fn.returnType ? `: ${fn.returnType}` : ""}`);
});
```

**What this script does**

| Step | Explanation |
|------|-------------|
| **`node.getKind() === SyntaxKind.FunctionDeclaration`** | Checks if we’re looking at a function declaration. (`SyntaxKind` is re‑exported from `ts‑morph` so you can use it directly.) |
| **`node.getFirstChildByKind`** | Quick way to retrieve the identifier without having to call `getChildren()` manually. |
| **`node.getParameters()`** | Returns an array of `ParameterDeclaration` objects, each exposing `getName()` and `getTypeNode()`. |
| **`return;`** inside the first case **stops traversal of that subtree** – we don’t dive into the function body because we only need the signature. |
| **`node.forEachChild(visit);`** | Recursively visits every child node if we didn’t early‑return. |

> **⚡ Performance tip** – `node.forEachChild(visit)` is *slightly* faster than `sourceFile.forEachDescendant` because it lets you skip whole branches early.

### 5.2  Using the **built‑in `forEachDescendant` filter** (concise)

If you just want to collect nodes of a certain kind (and you don’t need early‑stop logic), you can do it in one liner:

```ts
const allCalls = project
  .getSourceFiles()
  .map(sf => sf.getDescendantsOfKind(SyntaxKind.CallExpression))
  .flat();

allCalls.forEach(call => {
  const text = call.getExpression().getText(); // e.g. "console.log"
  console.log(`${call.getSourceFile().getBaseName()}: ${text}`);
});
```

*`getDescendantsOfKind`* walks the file **once** and returns every node that matches the supplied `SyntaxKind`. It’s great for “global” queries like “list every `await` expression” or “find all `@deprecated` JSDoc tags”.

---

## 6️⃣  Accessing the **underlying TypeScript compiler node** (if needed)

All `ts‑morph` node types expose the raw `ts.Node` via `.compilerNode`. You might need it for:

* Using a TypeScript API that `ts‑morph` doesn’t wrap yet.
* Accessing properties that are not (yet) exposed (e.g., `node.flags`).

```ts
import ts from "typescript";

sourceFile.forEachDescendant(node => {
  if (node.getKind() === SyntaxKind.MethodDeclaration) {
    const tsNode = node.compilerNode as ts.MethodDeclaration;
    console.log(tsNode.typeParameters?.length ?? 0, "type parameters");
  }
});
```

> **Important:** When you touch `.compilerNode` directly you bypass all the safety checks built into `ts‑morph`. Use it sparingly.

---

## 7️⃣  Using the **type checker** while walking

Often you need *type information* (e.g., resolve the return type of an expression). `ts‑morph` gives you a `TypeChecker` that works on any node:

```ts
import { Project, SyntaxKind } from "ts-morph";

const project = new Project({ tsConfigFilePath: "tsconfig.json" });
const checker = project.getTypeChecker();

project.getSourceFiles().forEach(sf => {
  sf.forEachDescendant(node => {
    if (node.getKind() === SyntaxKind.Identifier) {
      const type = checker.getTypeAtLocation(node);
      console.log(`${node.getText()} : ${type.getText()}`);
    }
  });
});
```

> **Performance note** – the type checker is **lazy**: it only fully resolves types when you query them. So if you are only interested in syntactic patterns, avoid calling `checker` inside the hot loop.

---

## 8️⃣  Putting it all together – a **complete reusable CLI script**

Below is a ready‑to‑run script (`ast-walk.ts`) you can drop into any repo. It

1. Accepts a **globbable pattern** (or defaults to `src/**/*.ts`),
2. Loads the files using a fresh `Project`,
3. Walks the AST **once per file**,
4. Collects **function signatures** *and* **all `await` expressions**,
5. Prints a neat report.

```ts
#!/usr/bin/env ts-node

import { Project, SyntaxKind, Node } from "ts-morph";
import * as path from "path";
import * as process from "process";

// -------------------------------------------------
// 1️⃣  Parse CLI arguments (very small CLI)
// -------------------------------------------------
const args = process.argv.slice(2);
const globPattern = args[0] ?? "src/**/*.ts";
const tsConfig = args[1] ?? "tsconfig.json";

console.log(`🔎  Scanning "${globPattern}" using "${tsConfig}"`);

// -------------------------------------------------
// 2️⃣  Build the Project
// -------------------------------------------------
const project = new Project({
  tsConfigFilePath: tsConfig,
  // Optional – helps avoid pulling the entire node_modules tree.
  skipFileDependencyResolution: true,
});

project.addSourceFilesAtPaths(globPattern);

// -------------------------------------------------
// 3️⃣  Accumulators
// -------------------------------------------------
interface FuncInfo {
  name: string;
  params: string[];
  returnType: string | undefined;
  file: string;
}
const functions: FuncInfo[] = [];

interface AwaitInfo {
  expression: string;
  file: string;
  line: number;
}
const awaits: AwaitInfo[] = [];

// -------------------------------------------------
// 4️⃣  Visitor implementation
// -------------------------------------------------
function visit(node: Node) {
  const kind = node.getKind();

  // ---- Functions -------------------------------------------------
  if (kind === SyntaxKind.FunctionDeclaration) {
    const name = node.getFirstChildByKind(SyntaxKind.Identifier)?.getText() ?? "<anonymous>";
    const params = node
      .getParameters()
      .map(p => p.getName() + (p.getTypeNode() ? `: ${p.getTypeNode()!.getText()}` : ""));
    const returnType = node.getReturnTypeNode()?.getText();
    functions.push({
      name,
      params,
      returnType,
      file: node.getSourceFile().getFilePath(),
    });
    // Stop walking the function's body – we already gathered the signature.
    return;
  }

  // ---- Await expressions -----------------------------------------
  if (kind === SyntaxKind.AwaitExpression) {
    const expressionText = node.getExpression().getText();
    const source = node.getSourceFile();
    const { line } = source.getLineAndColumnAtPos(node.getStart());
    awaits.push({
      expression: expressionText,
      file: source.getFilePath(),
      line,
    });
  }

  // -------------------------------------------------
  // 5️⃣  Continue traversing children (default case)
  // -------------------------------------------------
  node.forEachChild(visit);
}

// -------------------------------------------------
// 6️⃣  Walk every source file
// -------------------------------------------------
project.getSourceFiles().forEach(sf => visit(sf));

// -------------------------------------------------
// 7️⃣  Emit a human‑readable report
// -------------------------------------------------
console.log("\n=== Function signatures =====================================================");
functions.forEach(fn => {
  const rel = path.relative(process.cwd(), fn.file);
  console.log(`${rel}: ${fn.name}(${fn.params.join(", ")})${fn.returnType ? `: ${fn.returnType}` : ""}`);
});

console.log("\n=== Await expressions =======================================================");
awaits.forEach(a => {
  const rel = path.relative(process.cwd(), a.file);
  console.log(`${rel}:${a.line} – await ${a.expression}`);
});
```

### How to run

```bash
# Make the file executable (once):
chmod +x ast-walk.ts

# Run it against the default pattern & tsconfig:
./ast-walk.ts

# Custom pattern / tsconfig:
./ast-walk.ts "packages/*/src/**/*.tsx" "packages/core/tsconfig.json"
```

That script demonstrates **all the pieces**:

* `Project` construction,
* adding source files,
* a *single* recursive `visit` function,
* early exits (`return` from a case),
* gathering data into arrays,
* using helper methods (`getParameters()`, `getLineAndColumnAtPos`),
* printing nice, relative paths.

---

## 9️⃣  Common Gotchas & Tips

| Issue | How to solve / avoid |
|-------|----------------------|
| **“File not found”** when you use `tsConfigFilePath` | Use an absolute path (`path.resolve(__dirname, "tsconfig.json")`) or run the script **from** the repo root. |
| **Large node_modules tree slows down parsing** | Pass `skipFileDependencyResolution: true` or `addSourceFilesAtPaths` *after* creating the `Project` (don’t rely on the `tsconfig` to pull everything). |
| **Need JSX support** | Ensure `compilerOptions.jsx` is set in `tsconfig.json` (e.g., `"react-jsx"`). `ts‑morph` respects whatever JSX mode TypeScript uses. |
| **You only want `.ts` (not `.d.ts`)** | Filter after `project.getSourceFiles()` or set `skipAddingFilesFromTsConfig: true` and add your own globs with `addSourceFilesAtPaths("src/**/*.ts")`. |
| **You want to transform the AST** | After visiting a node, you can call mutating APIs (`node.replaceWithText`, `node.insertAfter`, `sourceFile.formatText()`, …). The visitor pattern shown above works just as well for transformations – just don’t modify the **current** node’s children while iterating (collect changes and apply them later). |
| **Circular imports cause duplicate `SourceFile` objects** | `ts‑morph` deduplicates by file path, but you might see the same file appear via two different import styles (`./foo` vs `../src/foo`). Use `sourceFile.getFilePath()` (absolute) for comparison. |
| **You need the AST of a *generated* file (e.g., codegen output)** | Use `project.createSourceFile("generated.ts", generatedCode, { overwrite: true })` and then walk that `SourceFile`. No need to write to disk first. |
| **You need to support newer syntax (e.g., `await using`)** | `ts‑morph` bundles the latest stable TypeScript. If you need bleeding‑edge features, upgrade the `typescript` dependency to the desired version – `ts‑morph` will automatically use it. |

---

## 🎉 Summary

1. **Create a `Project`** – either from a `tsconfig.json` or from explicit glob patterns.
2. **Grab the `SourceFile`s** via `project.getSourceFiles()`.
3. **Walk the AST**:
   * Simple full walk → `sourceFile.forEachDescendant(cb)`.
   * Controlled, early‑exit walk → your own `visit(node)` with `node.forEachChild(visit)`.
   * Quick filtered queries → `sourceFile.getDescendantsOfKind(SyntaxKind.X)`.
4. **Do something useful** at each node: collect data, emit diagnostics, or mutably transform the source.
5. **(Optional) Use the type checker** (`project.getTypeChecker()`) for semantic information.
6. **Apply performance tricks** (`skipFileDependencyResolution`, early returns, avoid `checker` in hot loops).

With these building blocks you can now write **any static analysis, lint rule, code‑mod, or documentation generator** that operates on the full TypeScript AST while staying fully type‑safe and ergonomic. Happy AST hacking! 🚀

