**Node.js – proste szyfrowanie / deszyfrowanie plików**  
Poniżej znajdziesz kompletny, gotowy do uruchomienia skrypt, który w zależności od podanego trybu (`encrypt` / `decrypt`) zaszyfruje albo odszyfruje wybrany plik.  
Używa on wbudowanego modułu **crypto**, algorytmu **AES‑256‑CBC** oraz **scrypt** do wyprowadzenia klucza z hasła.  

---

## 1. Co potrzebujemy

| Element | Dlaczego? |
|---------|-----------|
| `crypto` (core) | Tworzy klucz, wektor inicjalizujący (IV) oraz wykonuje szyfrowanie |
| `fs` | Czyta i zapisuje pliki (w trybie strumieniowym) |
| `stream` | Łączy strumienie w tzw. pipeline, aby obsłużyć duże pliki bez wczytywania ich w całości do pamięci |
| `util.promisify` | Umożliwia użycie `pipeline` w **async/await** |

Nie musisz instalować dodatkowych paczek – wszystko działa „z pudełka”.

---

## 2. Pełny kod (plik `file-crypto.js`)

```js
#!/usr/bin/env node
/**
 * file-crypto.js
 * ----------------
 * Szyfruje lub deszyfruje dowolny plik przy pomocy AES‑256‑CBC.
 *
 * Użycie:
 *   node file-crypto.js encrypt  <hasło> <ścieżka_pliku>  <plik_wyjściowy>
 *   node file-crypto.js decrypt  <hasło> <plik_wejściowy> <plik_wyjściowy>
 *
 * Przykład:
 *   node file-crypto.js encrypt mySecretPass ./plik.js ./plik.enc
 *   node file-crypto.js decrypt mySecretPass ./plik.enc ./plik.dec.js
 */

const crypto = require('crypto');
const fs = require('fs');
const { pipeline } = require('stream');
const { promisify } = require('util');
const asyncPipeline = promisify(pipeline);

// Stałe kryptograficzne
const ALGO = 'aes-256-cbc';          // Algorytm symetryczny
const KEY_LEN = 32;                  // 256 bit = 32 bajty
const IV_LEN = 16;                   // Rozmiar IV dla AES-CBC
const SALT_LEN = 16;                 // Długość soli (przy wyprowadzaniu klucza)
const SCRYPT_PARAMS = { N: 2 ** 14, r: 8, p: 1 }; // Bezpieczne domyślne parametry

/**
 * Wyprowadza klucz 256‑bitowy z hasła i soli przy pomocy scrypt().
 *
 * @param {string|Buffer} password - Twoje hasło
 * @param {Buffer} salt - Losowa sól (16 B)
 * @returns {Promise<Buffer>} - Klucz o długości 32 B
 */
function deriveKey(password, salt) {
  return new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, KEY_LEN, SCRYPT_PARAMS, (err, derivedKey) => {
      if (err) reject(err);
      else resolve(derivedKey);
    });
  });
}

/**
 * Szyfruje plik.
 *
 * @param {string|Buffer} password
 * @param {string} inputPath   - Ścieżka do pliku źródłowego (np. plik.js)
 * @param {string} outputPath  - Ścieżka do pliku zaszyfrowanego
 */
async function encryptFile(password, inputPath, outputPath) {
  // 1️⃣ losujemy sól i IV
  const salt = crypto.randomBytes(SALT_LEN);
  const iv = crypto.randomBytes(IV_LEN);

  // 2️⃣ wyprowadzamy klucz
  const key = await deriveKey(password, salt);

  // 3️⃣ tworzymy strumienie
  const input = fs.createReadStream(inputPath);
  const cipher = crypto.createCipheriv(ALGO, key, iv);
  const output = fs.createWriteStream(outputPath);

  // 4️⃣ zapisujemy nagłówek: | SALT (16B) | IV (16B) |
  output.write(salt);
  output.write(iv);

  // 5️⃣ łączymy strumienie: plik → szyfr → plik wynikowy
  await asyncPipeline(input, cipher, output);

  console.log(`✅ Zaszyfrowano → ${outputPath}`);
}

/**
 * Deszyfruje plik.
 *
 * @param {string|Buffer} password
 * @param {string} inputPath   - Ścieżka do pliku zaszyfrowanego
 * @param {string} outputPath  - Ścieżka do odszyfrowanego wyniku
 */
async function decryptFile(password, inputPath, outputPath) {
  // 1️⃣ otwieramy plik i odczytujemy SALT + IV (pierwsze 32 B)
  const fd = await fs.promises.open(inputPath, 'r');
  const header = Buffer.alloc(SALT_LEN + IV_LEN);
  await fd.read(header, 0, header.length, 0);
  await fd.close();

  const salt = header.slice(0, SALT_LEN);
  const iv = header.slice(SALT_LEN, SALT_LEN + IV_LEN);

  // 2️⃣ wyprowadzamy klucz na podstawie hasła + soli
  const key = await deriveKey(password, salt);

  // 3️⃣ tworzymy strumienie (omijamy już przeczytany nagłówek)
  const input = fs.createReadStream(inputPath, { start: SALT_LEN + IV_LEN });
  const decipher = crypto.createDecipheriv(ALGO, key, iv);
  const output = fs.createWriteStream(outputPath);

  // 4️⃣ łączymy strumienie: zaszyfrowany → deszyfr → plik wynikowy
  await asyncPipeline(input, decipher, output);

  console.log(`✅ Odszyfrowano → ${outputPath}`);
}

/* ======================  CLI ENTRY POINT ====================== */
(async () => {
  const [, , mode, password, srcPath, dstPath] = process.argv;

  if (!mode || !password || !srcPath || !dstPath) {
    console.error(`
Użycie:
  node file-crypto.js encrypt <hasło> <plik_wejściowy> <plik_wyjściowy>
  node file-crypto.js decrypt <hasło> <plik_wejściowy> <plik_wyjściowy>

Przykład:
  node file-crypto.js encrypt mySecretPass ./plik.js ./plik.enc
  node file-crypto.js decrypt mySecretPass ./plik.enc ./plik.dec.js
`);
    process.exit(1);
  }

  try {
    if (mode === 'encrypt') {
      await encryptFile(password, srcPath, dstPath);
    } else if (mode === 'decrypt') {
      await decryptFile(password, srcPath, dstPath);
    } else {
      throw new Error('Nieprawidłowy tryb – użyj "encrypt" albo "decrypt".');
    }
  } catch (err) {
    console.error('❗️ Błąd:', err.message);
    process.exit(1);
  }
})();
```

### Jak uruchomić?

1. **Zapisz kod** do pliku, np. `file-crypto.js`.
2. **Ustaw uprawnienia wykonywalne** (opcjonalnie):
   ```bash
   chmod +x file-crypto.js
   ```
3. **Zaszyfruj plik**:
   ```bash
   node file-crypto.js encrypt superSecurePassword ./plik.js ./plik.enc
   ```
   Powstanie plik `plik.enc`, którego pierwszy 32 B to nagłówek (sól + IV) potrzebny do odszyfrowania.
4. **Odszyfruj**:
   ```bash
   node file-crypto.js decrypt superSecurePassword ./plik.enc ./plik.dec.js
   ```
   `plik.dec.js` powinien być identyczny z oryginalnym `plik.js`.

---

## 3. Dlaczego tak działa?

| Krok | Co się dzieje | Dlaczego jest ważne? |
|------|---------------|---------------------|
| **Sól (`salt`)** | Losowo generowane 16 B, zapisywane w nagłówku | Zapobiega atakom słownikowym i umożliwia użycie tego samego hasła dla wielu plików bez powtarzalnych kluczy. |
| **IV** | Losowe 16 B (takie samo jak blok AES) | Dla trybu CBC zapewnia, że dwa identyczne bloki nie zostaną zaszyfrowane tak samo. |
| **scrypt** | Derywacja klucza z hasła + soli | Scrypt jest „memory‑hard”, co utrudnia ataki brute‑force na hasło. |
| **AES‑256‑CBC** | Symetryczne szyfrowanie blokowe | Popularny, szybki i bezpieczny (przy prawidłowym użyciu IV). |
| **Strumienie** | `pipeline(input → cipher/decipher → output)` | Nie musisz trzymać całego pliku w RAM – działa także na GB‑owych plikach. |
| **Nagłówek** | `| SALT | IV |` (pierwsze 32 B) | Umożliwia odtworzenie klucza/IV przy deszyfrowaniu bez dodatkowych plików konfiguracyjnych. |

---

## 4. Bezpieczeństwo – co jeszcze wziąć pod uwagę?

1. **Silne hasło** – hasło jest jedynym sekretem. Używaj długich, losowych fraz (np. menmoniczny passphrase) albo przechowuj hasło w bezpiecznym menedżerze.
2. **Rozważ użycie **AEAD** (np. `aes-256-gcm`)** – zapewnia integralność danych (autentyczność) oraz szyfrowanie w jednym kroku. Powyższy przykład z CBC nie posiada wbudowanego MAC, więc przy ataku “tamper” nie zostanie wykryty. Zmiana algorytmu wymaga jedynie kilku linijek kodu.
3. **Zarządzanie kluczami** – jeśli potrzebujesz szyfrować wiele plików w dużej skali, rozważ wygenerowanie losowego klucza symetrycznego i jego zaszyfrowanie przy pomocy RSA/ECDH. Hasło jest wtedy jedynie “kłódką” na klucz.
4. **Rozmiar pliku** – w trybie CBC zaszyfrowany plik jest nieco większy ze względu na wyrównanie (padding PKCS#7). Dla GCM nie ma dodatkowego paddingu.
5. **Bezpieczne usuwanie oryginału** – po zaszyfrowaniu możesz bezpiecznie usunąć pierwotny plik, np. `fs.unlinkSync(inputPath)`; ale pamiętaj, że w systemach plików nie zawsze usuwa on dane natychmiast.

---

## 5. Alternatywa: AES‑256‑GCM (z wbudowanym MAC)

Jeśli chcesz natychmiast mieć wbudowaną weryfikację integralności, zamień jedynie kilka linii:

```js
const ALGO = 'aes-256-gcm';   // zamiast CBC
const TAG_LEN = 16;           // domyślny rozmiar tagu GCM

// Po utworzeniu cipher/decipher:
const cipher = crypto.createCipheriv(ALGO, key, iv);
cipher.setAAD(Buffer.alloc(0)); // opcjonalnie dodatkowe "associated data"

...
// Po zakończeniu szyfrowania:
const tag = cipher.getAuthTag(); // 16 B
output.write(tag);               // dopisz na koniec pliku (lub na początek)

// przy deszyfrowaniu:
const tag = header.slice(-TAG_LEN); // ostatnie 16B (jeśli przechowujesz w nagłówku)
const encrypted = fs.createReadStream(inputPath, { start: SALT_LEN + IV_LEN, end: fileSize - TAG_LEN - 1 });
const decipher = crypto.createDecipheriv(ALGO, key, iv);
decipher.setAuthTag(tag);
```

Dzięki GCM nie musisz już martwić się o ręczny padding i dodatkowo masz gwarancję, że każdy nieautoryzowany „tamper” spowoduje `Decipher.final()` → błąd.

---

### Podsumowanie
* **`file-crypto.js`** – prosty, samowystarczalny skrypt do szyfrowania i deszyfrowania plików w Node.js.  
