### 1️⃣.2 JavaScript logic (`grid-filters.js`)

```js
/**
 * Grid filtering – works on any <table id="grid"> with:
 *   - a <thead> that has two rows: header + filter inputs
 *   - <tbody> with rows of data
 *
 * The algorithm:
 *   1. Read the value of the global input.
 *   2. Read the value of each column filter (text, number or select).
 *   3. For each <tr> in <tbody>:
 *        – Check each cell against its column filter (if set).
 *        – If any column fails, hide the row.
 *        – If the row passes all column filters,
 *           also test the global filter (search across *all* visible cells).
 *   4. Show/hide rows accordingly.
 *
 * Debounce is used to avoid re‑filtering on every keystroke.
 */

(() => {
  const table      = document.getElementById('grid');
  const tbody      = table.querySelector('tbody');
  const rows       = Array.from(tbody.rows);
  const globalInp  = document.getElementById('globalFilter');
  const colInputs  = Array.from(table.querySelectorAll('.filter-row input, .filter-row select'));

  // ------- Helper ---------------------------------------------------------
  const debounce = (fn, delay) => {
    let timer;
    return (...args) => {
      clearTimeout(timer);
      timer = setTimeout(() => fn.apply(this, args), delay);
    };
  };

  // ------- Core filter function -------------------------------------------
  const filterGrid = () => {
    const globalVal = globalInp.value.trim().toLowerCase();

    // Build an array **by column index** with the filter value (or null)
    const columnFilters = colInputs.map(inp => {
      const raw = inp.value.trim();
      if (!raw) return null;                     // “no filter”
      // Numbers are compared as numbers, otherwise case‑insensitive string
      return inp.type === 'number' ? Number(raw) : raw.toLowerCase();
    });

    rows.forEach(row => {
      const cells = row.cells;
      let keep = true;

      // ---- Column filter test --------------------------------------------
      for (let col = 0; col < columnFilters.length; col++) {
        const filterVal = columnFilters[col];
        if (filterVal === null) continue; // nothing to test for this column

        const cellText = cells[col].textContent.trim().toLowerCase();

        // Numeric comparison (exact match)
        if (typeof filterVal === 'number') {
          if (Number(cellText) !== filterVal) { keep = false; break; }
        } else { // string comparison – “contains”
          if (!cellText.includes(filterVal)) { keep = false; break; }
        }
      }

      // ---- Global search test ---------------------------------------------
      if (keep && globalVal) {
        // build a single string from all visible cells (lower‑cased)
        const rowText = Array.from(cells)
          .map(c => c.textContent.trim().toLowerCase())
          .join(' ');
        if (!rowText.includes(globalVal)) keep = false;
      }

      // Show / hide
      row.style.display = keep ? '' : 'none';
    });
  };

  // ------- Event bindings -------------------------------------------------
  const debouncedFilter = debounce(filterGrid, 200);
  globalInp.addEventListener('input', debouncedFilter);
  colInputs.forEach(inp => inp.addEventListener('input', debouncedFilter));
  // For <select> we also need `change`
  colInputs.filter(i => i.tagName === 'SELECT').forEach(sel => sel.addEventListener('change', debouncedFilter));

  // Initial run (in case there is a pre‑filled query string)
  filterGrid();
})();
```

### 1️⃣.3 What this gives you

| Feature | How it works |
|---------|--------------|
| **Column filter** | Each input (text, number, or `<select>`) is tied to a column index via `data-col`. Every time the user types/selects, the grid re‑evaluates that column only. |
| **Global filter** | A separate textbox (`#globalFilter`) checks *all* cells of a row after the column filters have passed. |
| **Debounce** | Filtering is delayed by ~200 ms to avoid wasteful loops on rapid typing. |
| **No external library** | Works in any modern browser (ES6). |

