    { field: 'dept', headerName: 'Dept.', filter: 'agSetColumnFilter', sortable: true },
    { field: 'age', headerName: 'Age', filter: 'agNumberColumnFilter', sortable: true },
    { field: 'country', headerName: 'Country', filter: 'agTextColumnFilter', sortable: true },
  ], []);

