  // You can also expose external inputs if you want:
  const onColumnFilterChange = useCallback((colId, value) => {
    const filterInstance = gridRef.current.api.getFilterInstance(colId);
    filterInstance.setModel(
      value ? { type: 'contains', filter: value } : null
    );
