          placeholder="Global search…"
          onChange={onGlobalFilterChange}
          style={{ width: 200, padding: 4 }}
        />
      </div>

      {/* Optional external column filters */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
        {columnDefs.map(col => (
          <input
            key={col.field}
            placeholder={`Filter ${col.headerName}`}
            onChange={e => onColumnFilterChange(col.field, e.target.value)}
            style={{ width: 120 }}
          />
        ))}
      </div>

      <AgGridReact
        ref={gridRef}
        rowData={rowData}
        columnDefs={columnDefs}
        defaultColDef={{
          flex: 1,
          minWidth: 100,
          filter: true,
          floatingFilter: true,   // shows a tiny input box in the header
          sortable: true,
          resizable: true,
        }}
        animateRows={true}
      />
    </div>
  );
};

export default EmployeeGrid;
```

**Key points**

| Feature | How it’s set up |
|--------|-----------------|
| **Column filters** | `filter: true` + `floatingFilter: true` automatically gives you a tiny filter input inside each column header. You can also control them programmatically via `api.getFilterInstance(colId)` as shown. |
| **Global filter** | `api.setQuickFilter(value)` – searches *all* visible columns (case‑insensitive, substring). |
