    // 1️⃣ Convert the object to a query string.
    const query = Object.entries(filterObj)
        .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
        .join('&');

    // 2️⃣ Append the query string (only if there is something to add)
    const localVarPath = `${this.basePath}/api/excelReports/missingUnassignedAccelerator${query ? '?' + query : ''}`;

    // 3️⃣ The rest of the code stays exactly the same…
    return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open('GET', localVarPath, true);
        xhr.setRequestHeader('Content-Type', 'application/json');   // still OK – it just tells the server what we *expect* back
        xhr.withCredentials = true;
        xhr.responseType = 'blob';

        /* …original onload / onerror handling… */

        xhr.send();          // ← still no body, just the URL carries the data
    });
};
```

**When to use this?**  
* The API only needs a handful of simple scalar values (e.g., `startDate`, `endDate`, `regionId`).  
