                });
            } else {
                reject(new Error(xhr.statusText));
            }
        };

        xhr.onerror = () => reject(new Error('Network error'));

        // ---------- 5️⃣ Send the JSON body ----------
        xhr.send(JSON.stringify(payload));
    });
};

/**
 * Helper that extracts the filename from `content‑disposition`,
 * creates a hidden `<a>` element and triggers the download.
 * (extracted from your original code to keep it tidy)
 */
function handleBlobDownload(xhr, resolve) {
    const blob = xhr.response;
    const reader = new FileReader();
    const disposition = xhr.getResponseHeader('content-disposition') || '';
    const matches = /filename[^;=\n]*=((["']).*?\2|[^;\n]*)/.exec(disposition);
    let filename = matches && matches[1] ? matches[1].replace(/[""]/g, '') : 'download.bin';

    reader.readAsDataURL(blob);
    reader.onload = function (e) {
        const a = document.createElement('a');
        a.download = filename;
        a.href = e.target.result;
        document.body.appendChild(a);
        a.click();
        resolve(200);
        document.body.removeChild(a);
    };
}
```

### What changed?

| Line / Section | What it does now |
|----------------|------------------|
| `xhr.open('POST', …)` | Makes the request a **POST**. |
| `xhr.send(JSON.stringify(payload))` | Sends the supplied JavaScript object as a JSON string in the request body. |
| `payload` argument (default `{}`) | Allows the caller to pass any object – e.g. `{ startDate: '2024‑01‑01', regionIds: [12,45] }`. |
| `handleBlobDownload` | Small refactor of the repeated “download‑blob” code – makes the main flow easier to read. |

**When to use this?**  

* The API spec says *POST `/api/excelReports/missingUnassignedAccelerator`* with a JSON body.  
* You need to transmit complex data (arrays, nested objects, dates, etc.).  
* You’re fine with a slightly bigger request (POST bodies are not cached by browsers the way GET URLs are).

---

## 4️⃣ Quick checklist before you ship

| ✅ | Item |
|---|------|
| **API contract** | Verify whether the server expects **GET + query string** *or* **POST + JSON**. If it’s documented as a GET, stick to the query‑string version. |
| **CORS / credentials** | You already have `xhr.withCredentials = true;` – keep it if the back‑end uses cookies / HTTP auth. |
| **Content‑type header** | `application/json` is perfect for POST. For GET you can drop it (it’s only needed when you *send* JSON). |
| **Error handling** | Your existing `try / catch` logic nicely distinguishes “JSON response with an error” from “binary file”. Keep that flow. |
| **File‑name extraction** | The regex you have works for standard `Content‑Disposition: attachment; filename="report.xlsx"` headers. No change needed. |
| **Browser support** | `XMLHttpRequest` works everywhere, but if you are on a modern codebase you could rewrite the whole thing with `fetch` and `async/await` – it’s less boilerplate. |

---

## 5️⃣ Bonus: The same logic with **fetch** (if you ever want to modernise)

```javascript
ReportsApi.prototype.missingUnassignedAccelerator = async function (payload = {}) {
    const url = `${this.basePath}/api/excelReports/missingUnassignedAccelerator`;

    const response = await fetch(url, {
        method: 'POST',                       // or 'GET' → then append querystring to `url`
        credentials: 'include',               // same as xhr.withCredentials = true
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)         // omit for GET
    });

    if (!response.ok) throw new Error(response.statusText);

    // Try to parse JSON first – if that fails we assume it is an Excel file (blob)
    const text = await response.clone().text();   // clone because we might also need the blob
    try {
        const json = JSON.parse(text);
        if (json.status !== '201') {
            // Not a JSON error → treat as file download
            await downloadBlob(response);
            return 200;
        }
        return json;   // JSON error object
    } catch (_) {
        // Not JSON → file download
        await downloadBlob(response);
        return 200;
    }
};

async function downloadBlob(resp) {
    const blob = await resp.blob();
    const disposition = resp.headers.get('content-disposition') || '';
    const matches = /filename[^;=\n]*=((["']).*?\2|[^;\n]*)/.exec(disposition);
    const filename = matches && matches[1] ? matches[1].replace(/[""]/g, '') : 'download.bin';

    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}
```

*`fetch`* automatically resolves CORS, promises, and works nicely with `async/await`. The logic is the same; you just get rid of the nested `onload` callbacks.

---

## TL;DR – What you need to do

1. **GET**:  
   *If the API only accepts query parameters* – build a query string from your object and append it to the URL. No request body.  

2. **POST**:  
   *If you need a JSON payload* – change `xhr.open('GET', …)` to `xhr.open('POST', …)`, keep the `Content-Type: application/json` header, and call `xhr.send(JSON.stringify(yourObject))`.  

Pick the route that matches the server contract, and you’ll be able to ship the payload along with the file‑download request. Happy coding! 🚀

