## 3️⃣  Opening / Versioning the Database

### 3.1  Vanilla IndexedDB (Promise‑wrapped)

```js
/**
 * Open (or create) an IndexedDB database.
 * Returns a Promise that resolves to the DB instance.
 */
function openDB(name, version = 1) {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(name, version);

    // === RUN ONLY WHEN DB IS CREATED OR VERSION IS INCREMENTED ===
    request.onupgradeneeded = (event) => {
      const db = request.result;
      console.log(`Upgrade needed: from ${event.oldVersion} to ${event.newVersion}`);

      // Create object stores only if they don't already exist
      if (!db.objectStoreNames.contains('posts')) {
        const posts = db.createObjectStore('posts', { keyPath: 'id', autoIncrement: true });
        posts.createIndex('title', 'title', { unique: false });
        posts.createIndex('slug', 'slug', { unique: true });
        posts.createIndex('authorId', 'authorId', { unique: false });
        posts.createIndex('createdAt', 'createdAt', { unique: false });
        posts.createIndex('tags', 'tags', { unique: false, multiEntry: true });
        posts.createIndex('fullText', 'fullText', { unique: false });
      }

      if (!db.objectStoreNames.contains('authors')) {
        const authors = db.createObjectStore('authors', { keyPath: 'id', autoIncrement: true });
        authors.createIndex('username', 'username', { unique: true });
        authors.createIndex('email', 'email', { unique: true });
      }

      if (!db.objectStoreNames.contains('comments')) {
        const comments = db.createObjectStore('comments', { keyPath: 'id', autoIncrement: true });
        comments.createIndex('postId', 'postId', { unique: false });
        comments.createIndex('authorId', 'authorId', { unique: false });
        comments.createIndex('createdAt', 'createdAt', { unique: false });
      }

      if (!db.objectStoreNames.contains('media')) {
        const media = db.createObjectStore('media', { keyPath: 'id', autoIncrement: true });
        media.createIndex('postId', 'postId', { unique: false });
        media.createIndex('mimeType', 'mimeType', { unique: false });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

// Example usage:
openDB('myBlogDB', 1)
  .then(db => console.log('DB ready', db))
  .catch(err => console.error('Failed to open DB', err));
```

