  await tx.objectStore('posts').delete(id);

  // 2️⃣ Delete related comments
  const commentIdx = tx.objectStore('comments').index('postId');
  const commentRange = IDBKeyRange.only(id);
  for await (const cursor of commentIdx.iterate(commentRange)) {
    await cursor.delete();
