  // 3️⃣ Delete related media
  const mediaIdx = tx.objectStore('media').index('postId');
  const mediaRange = IDBKeyRange.only(id);
  for await (const cursor of mediaIdx.iterate(mediaRange)) {
    await cursor.delete();
  }

  await tx.done; // resolves when all operations are committed
}

