    tx.objectStore('posts').delete(id);

    // Comments cascade
    const commentIdx = tx.objectStore('comments').index('postId');
    const commentRange = IDBKeyRange.only(id);
    commentIdx.openCursor(commentRange).onsuccess = function (e) {
      const cursor = e.target.result;
      if (cursor) {
        cursor.delete();
        cursor.continue();
      }
    };

    // Media cascade
    const mediaIdx = tx.objectStore('media').index('postId');
    const mediaRange = IDBKeyRange.only(id);
    mediaIdx.openCursor(mediaRange).onsuccess = function (e) {
      const cursor = e.target.result;
      if (cursor) {
        cursor.delete();
        cursor.continue();
      }
    };

    return new Promise((resolve, reject) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
