## 5️⃣  Advanced Queries  

### 5.1  Get All Posts, Sorted by Date (Newest First)

```js
async function getAllPosts({ offset = 0, limit = 20 } = {}) {
  const db = await dbPromise;
  const tx = db.transaction('posts');
  const store = tx.objectStore('posts');
  const index = store.index('createdAt');

  // Use a reverse cursor to get newest first
  const results = [];
  let cursor = await index.openCursor(null, 'prev'); // 'prev' = descending
  while (cursor && results.length < offset + limit) {
    if (results.length >= offset) results.push(cursor.value);
    cursor = await cursor.continue();
  }
  return results;
}
```

### 5.2  Filter by Tag (multi‑entry index)

```js
async function getPostsByTag(tag, { offset = 0, limit = 20 } = {}) {
  const db = await dbPromise;
  const index = db.transaction('posts').objectStore('posts').index('tags');
  const range = IDBKeyRange.only(tag);
  const results = [];

  for await (const cursor of index.iterate(range)) {
    if (results.length >= offset + limit) break;
    if (results.length >= offset) results.push(cursor.value);
  }
  return results;
}
```

### 5.3  Simple Full‑Text Search (case‑insensitive includes)

```js
async function searchPosts(query, { offset = 0, limit = 20 } = {}) {
  const db = await dbPromise;
  const index = db.transaction('posts').objectStore('posts').index('fullText');
  const lower = query.toLowerCase();
  const results = [];

  // Full‑text index stores a big string, so we can use a range that matches lexicographically.
  // We’ll just open a cursor over the whole index and filter manually; this is OK for <10k records.
  for await (const cursor of index.iterate()) {
    if (cursor.value.fullText.includes(lower)) {
      if (results.length >= offset && results.length < offset + limit) {
        results.push(cursor.value);
      }
      if (results.length >= offset + limit) break;
    }
  }
  return results;
}
```

*For larger blogs* you’ll want a dedicated client‑side search engine (e.g., **lunr.js**, **elasticlunr**, or **FlexSearch**) that builds its own inverted index from the `posts` data after a sync.

### 5.4  Pagination with Cursors (Cursor‑based “page after”)

```js
/**
 * Get the next N posts *after* the given primary key.
 * This is superior to offset‑based pagination because it’s O(1).
 */
async function getPostsAfter(lastId, limit = 20) {
  const db = await dbPromise;
  const store = db.transaction('posts').objectStore('posts');
  const range = IDBKeyRange.lowerBound(lastId, true); // true => exclusive
  const cursor = await store.openCursor(range);
  const results = [];

  let cur = cursor;
  while (cur && results.length < limit) {
    results.push(cur.value);
    cur = await cur.continue();
  }
  return results;
}
```

