## 🔟  Full‑Featured Example – A Minimal Blog App

Below is a **complete, self‑contained** example you can paste into an HTML file and run locally (no server needed). It showcases:

* Adding a post (title + content + tags)  
* Listing posts with pagination  
* Editing a post  
* Adding an image (Blob) to a post  
* Exporting & importing the DB  

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>IndexedDB Blog Demo</title>
  <style>
    body {font-family:Arial; max-width:800px; margin:auto; padding:1rem;}
    .post {border:1px solid #ccc; padding:1rem; margin:0.5rem 0;}
    .post img {max-width:100%; height:auto;}
  </style>
</head>
<body>

<h1>📚 My IndexedDB Blog</h1>

<section id="editor">
  <h2>Create / Edit Post</h2>
  <input id="post-id" type="hidden">
  <input id="post-title" placeholder="Title" style="width:100%;font-size:1.2rem;">
  <textarea id="post-content" placeholder="Content (HTML)" rows="6" style="width:100%;"></textarea>
  <input id="post-tags" placeholder="Comma‑separated tags" style="width:100%;">
  <label>
    Add image: <input id="post-image" type="file" accept="image/*">
  </label><br><br>
  <button id="saveBtn">Save Post</button>
  <button id="clearBtn">Clear Form</button>
</section>

<hr>

<section id="list">
  <h2>All Posts</h2>
  <div id="posts"></div>
  <button id="prevPage">← Prev</button>
  <button id="nextPage">Next →</button>
</section>

<hr>

<section id="backup">
  <h2>Backup & Restore</h2>
  <button id="exportBtn">Export JSON</button>
  <input id="importFile" type="file" accept="application/json">
</section>

<script type="module">
/* ---- 1️⃣ Import idb --------------------------------------------------- */
import { openDB } from 'https://cdn.jsdelivr.net/npm/idb@7/+esm';

/* ---- 2️⃣ Define DB ---------------------------------------------------- */
const dbPromise = openDB('myBlogDB', 1, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('posts')) {
      const posts = db.createObjectStore('posts', { keyPath: 'id', autoIncrement: true });
      posts.createIndex('title', 'title');
      posts.createIndex('slug', 'slug', { unique: true });
      posts.createIndex('createdAt', 'createdAt');
      posts.createIndex('tags', 'tags', { multiEntry: true });
      posts.createIndex('fullText', 'fullText');
    }
    if (!db.objectStoreNames.contains('media')) {
      const media = db.createObjectStore('media', { keyPath: 'id', autoIncrement: true });
      media.createIndex('postId', 'postId');
    }
  },
});

/* ---- 3️⃣ Helper functions --------------------------------------------- */
const utils = {
  slugify: str => str.toLowerCase().trim()
                     .replace(/[^\w\s-]/g, '')
                     .replace(/[\s_-]+/g, '-')
                     .replace(/^[-]+|[-]+$/g, ''),

  // Returns a promise that resolves when the transaction finishes.
  runTx: async (storeNames, mode, callback) => {
    const db = await dbPromise;
    const tx = db.transaction(storeNames, mode);
    const result = await callback(tx);
    await tx.done;
    return result;
  },
};

/* ---- 4️⃣ CRUD ---------------------------------------------------------- */
async function addOrUpdatePost(data) {
  data.updatedAt = new Date().toISOString();
  data.fullText = `${data.title} ${data.content}`.toLowerCase();

  if (!data.slug) data.slug = utils.slugify(data.title);
  if (!data.createdAt) data.createdAt = data.updatedAt;

  return utils.runTx(['posts'], 'readwrite', async tx => {
    const store = tx.objectStore('posts');

    if (data.id) {
      await store.put(data);     // update
      return data.id;
    } else {
      const id = await store.add(data); // create
      return id;
    }
  });
}

/* ---- 5️⃣ Media upload ------------------------------------------------- */
async function addImageToPost(postId, file) {
  const media = {
    postId,
    mimeType: file.type,
    blob: file,
    createdAt: new Date().toISOString(),
    name: file.name,
    size: file.size,
  };
  return utils.runTx(['media'], 'readwrite', async tx => {
    const id = await tx.objectStore('media').add(media);
    return id;
  });
}

/* ---- 6️⃣ Rendering ----------------------------------------------------- */
let currentPage = 0;
const PAGE_SIZE = 5;

async function renderPosts() {
  const start = currentPage * PAGE_SIZE;
  const posts = await utils.runTx(['posts'], 'readonly', async tx => {
    const idx = tx.objectStore('posts').index('createdAt');
    const cursor = await idx.openCursor(null, 'prev'); // newest first
    const list = [];
    let i = 0;
    let cur = cursor;
    while (cur && list.length < PAGE_SIZE) {
      if (i >= start) list.push(cur.value);
      i++;
      cur = await cur.continue();
    }
    return list;
  });

  const container = document.getElementById('posts');
  container.innerHTML = '';
  for (const p of posts) {
    const div = document.createElement('div');
    div.className = 'post';
    div.innerHTML = `
      <h3>${p.title}</h3>
      <small>🗓 ${new Date(p.createdAt).toLocaleString()}</small>
      <div>${p.content}</div>
      <p><strong>Tags:</strong> ${p.tags?.join(', ')}</p>
      <button data-id="${p.id}" class="editBtn">✏️ Edit</button>
    `;

    // Load attached image(s) if any
    const mediaIds = await utils.runTx(['media'], 'readonly', async tx => {
      const idx = tx.objectStore('media').index('postId');
      const range = IDBKeyRange.only(p.id);
      const ids = [];
      for await (const cur of idx.iterate(range)) ids.push(cur.value.id);
      return ids;
    });

    for (const mid of mediaIds) {
      const url = await utils.runTx(['media'], 'readonly', async tx => {
        const rec = await tx.objectStore('media').get(mid);
        return URL.createObjectURL(rec.blob);
      });
      const img = document.createElement('img');
      img.src = url;
      div.appendChild(img);
    }

    container.appendChild(div);
  }
}

/* ---- 7️⃣ Form handling ------------------------------------------------ */
document.getElementById('saveBtn').addEventListener('click', async () => {
  const id = document.getElementById('post-id').value;
  const title = document.getElementById('post-title').value.trim();
  const content = document.getElementById('post-content').value.trim();
  const tags = document.getElementById('post-tags').value.split(',').map(t=>t.trim()).filter(Boolean);
  const imageFile = document.getElementById('post-image').files[0];

  if (!title) return alert('Title required');

  const post = { id: id ? Number(id) : undefined, title, content, tags };
  const postId = await addOrUpdatePost(post);

  if (imageFile) {
    await addImageToPost(postId, imageFile);
    // clear file input
    document.getElementById('post-image').value = '';
  }

  // reset form
  document.getElementById('post-id').value = '';
  document.getElementById('post-title').value = '';
  document.getElementById('post-content').value = '';
  document.getElementById('post-tags').value = '';

  await renderPosts();
});

document.getElementById('clearBtn').addEventListener('click', () => {
  document.getElementById('post-id').value = '';
  document.getElementById('post-title').value = '';
  document.getElementById('post-content').value = '';
  document.getElementById('post-tags').value = '';
  document.getElementById('post-image').value = '';
});

document.getElementById('posts').addEventListener('click', async e => {
  if (e.target.classList.contains('editBtn')) {
    const pid = Number(e.target.dataset.id);
    const post = await utils.runTx(['posts'], 'readonly', tx => tx.objectStore('posts').get(pid));
    document.getElementById('post-id').value = post.id;
    document.getElementById('post-title').value = post.title;
    document.getElementById('post-content').value = post.content;
    document.getElementById('post-tags').value = post.tags?.join(', ');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
});

/* ---- 8️⃣ Pagination ---------------------------------------------------- */
document.getElementById('prevPage').addEventListener('click', async () => {
  if (currentPage > 0) {
    currentPage--;
    await renderPosts();
  }
});
document.getElementById('nextPage').addEventListener('click', async () => {
  currentPage++;
  await renderPosts();
});

/* ---- 9️⃣ Export / Import ---------------------------------------------- */
document.getElementById('exportBtn').addEventListener('click', async () => {
  const db = await dbPromise;
  const data = {};
  for (const storeName of db.objectStoreNames) {
    data[storeName] = await db.getAll(storeName);
  }
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `blog-backup-${new Date().toISOString()}.json`;
  a.click();
  URL.revokeObjectURL(url);
});

document.getElementById('importFile').addEventListener('change', async e => {
  const file = e.target.files[0];
  if (!file) return;
  const txt = await file.text();
  const json = JSON.parse(txt);
  const db = await dbPromise;
  const tx = db.transaction(db.objectStoreNames, 'readwrite');
  for (const [storeName, records] of Object.entries(json)) {
    const store = tx.objectStore(storeName);
    await store.clear();
    for (const rec of records) {
      // If you exported blobs as base64, you would need to reconstruct them here.
      await store.add(rec);
    }
  }
  await tx.done;
  alert('Import completed!');
  await renderPosts();
});

/* ---- 10️⃣ Initial render ------------------------------------------------ */
renderPosts();
</script>

</body>
</html>
```

**What this demo does**

* **Creates the DB** (posts + media) with version 1.  
* **Adds/edits posts** – the same function acts as `create` or `update`.  
* **Attaches an image** (as a `Blob`) to the post.  
* **Lists posts** with a simple pagination (5 per page).  
* **Exports** the whole DB as a downloadable JSON file.  
* **Imports** a JSON backup (clears existing data first).  

