// Helper class that just prints the SDP offer/answer to stdout.
class SimpleSignaling : public webrtc::PeerConnectionObserver {
public:
    explicit SimpleSignaling(rtc::scoped_refptr<webrtc::PeerConnectionInterface> pc)
        : pc_(std::move(pc)) {}

    // Called when ICE gathering is complete – we can finally output the SDP.
    void OnIceGatheringChange(webrtc::PeerConnectionInterface::IceGatheringState new_state) override {
        if (new_state == webrtc::PeerConnectionInterface::kIceGatheringComplete) {
            pc_->CreateOffer(
                webrtc::CreateSessionDescriptionObserver::Create(
                    [this](webrtc::SessionDescriptionInterface* desc) {
                        pc_->SetLocalDescription(
                            webrtc::SetSessionDescriptionObserver::Create(),
                            desc);
                        std::string sdp;
                        desc->ToString(&sdp);
                        puts("\n=== SDP OFFER ===");
                        puts(sdp.c_str());
                        puts("\nPaste remote answer and press ENTER...");
                        std::string answer;
                        std::getline(std::cin, answer);
                        webrtc::SdpParseError err;
                        auto remote_desc = webrtc::CreateSessionDescription(webrtc::SdpType::kAnswer, answer, &err);
                        if (!remote_desc) {
                            fprintf(stderr, "Failed to parse answer: %s\n", err.description.c_str());
                            return;
                        }
                        pc_->SetRemoteDescription(
                            webrtc::SetSessionDescriptionObserver::Create(),
                            remote_desc.release());
                    },
                    [](webrtc::RTCError const& e){ fprintf(stderr, "Offer failed: %s\n", e.message().c_str()); })
                , webrtc::PeerConnectionInterface::RTCOfferAnswerOptions());
        }
    }

    // Unused callbacks (required by the interface)
    void OnSignalingChange(webrtc::PeerConnectionInterface::SignalingState) override {}
    void OnIceConnectionChange(webrtc::PeerConnectionInterface::IceConnectionState) override {}
    void OnIceCandidate(const webrtc::IceCandidateInterface*) override {}
    void OnAddStream(rtc::scoped_refptr<webrtc::MediaStreamInterface>) override {}
    // ... add more as needed

private:
    rtc::scoped_refptr<webrtc::PeerConnectionInterface> pc_;
};

int main(int argc, char** argv) {
    // 1️⃣ Initialise global SSL (required for DTLS‑SRTP)
    rtc::InitializeSSL();

    // 2️⃣ Create a signalling thread & network thread (WebRTC needs them)
    rtc::Thread* network_thread = rtc::Thread::CreateWithSocketServer().release();
    rtc::Thread* worker_thread  = rtc::Thread::Create().release();
    rtc::Thread* signaling_thread = rtc::Thread::Current();

    network_thread->Start();
    worker_thread->Start();

    // 3️⃣ Build a PeerConnectionFactory
    auto pc_factory = webrtc::CreatePeerConnectionFactory(
        network_thread, worker_thread, signaling_thread,
        /*default_adm=*/nullptr,
        webrtc::CreateBuiltinAudioEncoderFactory(),
        webrtc::CreateBuiltinAudioDecoderFactory(),
        webrtc::CreateBuiltinVideoEncoderFactory(),
        webrtc::CreateBuiltinVideoDecoderFactory(),
        nullptr, nullptr);

    if (!pc_factory) {
        fprintf(stderr, "Failed to create PeerConnectionFactory\n");
        return -1;
    }

    // 4️⃣ Configure ICE (use Google public STUN server)
    webrtc::PeerConnectionInterface::RTCConfiguration config;
    webrtc::PeerConnectionInterface::IceServer stun;
    stun.uri = "stun:stun.l.google.com:19302";
    config.servers.push_back(stun);
    config.sdp_semantics = webrtc::SdpSemantics::kUnifiedPlan;

    // 5️⃣ Create the actual PeerConnection
    rtc::scoped_refptr<webrtc::PeerConnectionInterface> pc =
        pc_factory->CreatePeerConnection(config, nullptr, nullptr, nullptr,
                                         nullptr);  // observer added later

    // 6️⃣ Add a video track from the default webcam (V4L2)
    rtc::scoped_refptr<webrtc::VideoTrackSourceInterface> video_source =
        webrtc::VideoCaptureFactory::Create(
            /*device_id=*/nullptr,
            webrtc::VideoCaptureCapability{
                640, 480, 30, webrtc::VideoCaptureCapability::kVideoCaptureFormatI420});
    auto video_track = pc_factory->CreateVideoTrack(
        "video", video_source);
    pc->AddTrack(video_track, {"stream"});

