### 3️⃣ script.js
```js
/* ------------------------------------------------------------
   Cuestionario: 10 preguntas con respuestas de opción múltiple
   ------------------------------------------------------------ */

const quizData = [
    {
        question: "¿Cuál es la capital de Francia?",
        options: ["París", "Londres", "Berlín", "Roma"],
        answer: 0            // índice de la respuesta correcta
    },
    {
        question: "¿Qué lenguaje se utiliza principalmente para desarrollo web en el front‑end?",
        options: ["Python", "C#", "JavaScript", "Java"],
        answer: 2
    },
    {
        question: "¿Cuál de los siguientes es un número primo?",
        options: ["15", "21", "29", "35"],
        answer: 2
    },
    {
        question: "¿En qué año llegó el hombre a la Luna?",
        options: ["1965", "1969", "1972", "1975"],
        answer: 1
    },
    {
        question: "El proceso de convertir código fuente a código máquina se llama:",
        options: ["Compilación", "Interpretación", "Depuración", "Encriptación"],
        answer: 0
    },
    {
        question: "¿Cuál es el océano más grande del planeta?",
        options: ["Atlántico", "Índico", "Ártico", "Pacífico"],
        answer: 3
    },
    {
        question: "¿Qué elemento químico tiene el símbolo 'Fe'?",
        options: ["Fósforo", "Flúor", "Hierro", "Francio"],
        answer: 2
    },
    {
        question: "¿Qué autor escribió 'Cien años de soledad'?",
        options: ["Mario Vargas Llosa", "Gabriel García Márquez", "Julio Cortázar", "Carlos Fuentes"],
        answer: 1
    },
    {
        question: "En matemáticas, ¿cómo se llama un polígono de ocho lados?",
        options: ["Hexágono", "Octágono", "Heptágono", "Nonágono"],
        answer: 1
    },
    {
        question: "¿Cuál de los siguientes sistemas operativos es de código abierto?",
        options: ["Windows", "macOS", "Linux", "iOS"],
        answer: 2
    }
];

/* ------------------------------------------------------------
   Renderizado dinámico del cuestionario
   ------------------------------------------------------------ */
const quizContainer = document.getElementById('quiz-container');

function renderQuiz() {
    quizContainer.innerHTML = ''; // limpio cualquier contenido previo

    quizData.forEach((item, idx) => {
        const qDiv = document.createElement('div');
        qDiv.className = 'question';
        qDiv.dataset.qid = idx;

        const qTitle = document.createElement('h3');
        qTitle.textContent = `${idx + 1}. ${item.question}`;
        qDiv.appendChild(qTitle);

        const optionsDiv = document.createElement('div');
        optionsDiv.className = 'options';

        item.options.forEach((opt, oIdx) => {
            const label = document.createElement('label');

            const radio = document.createElement('input');
            radio.type = 'radio';
            radio.name = `question-${idx}`;
            radio.value = oIdx;               // guardamos el índice de la opción
            radio.required = true;            // obligamos a seleccionar una

            label.appendChild(radio);
            label.appendChild(document.createTextNode(' ' + opt));
            optionsDiv.appendChild(label);
        });

        qDiv.appendChild(optionsDiv);
        quizContainer.appendChild(qDiv);
    });
}

/* ------------------------------------------------------------
   Lógica del botón "Comprobar"
   ------------------------------------------------------------ */
const checkBtn = document.getElementById('check-btn');
const resetBtn = document.getElementById('reset-btn');
const resultP  = document.getElementById('result');

function evaluateQuiz() {
    let score = 0;

    quizData.forEach((item, idx) => {
        const selected = document.querySelector(`input[name="question-${idx}"]:checked`);
        if (!selected) return; // (no debería pasar por el required)
        const answerIdx = parseInt(selected.value, 10);
        if (answerIdx === item.answer) score++;
    });

    // Mostrar resultados
    resultP.textContent = `Obtuviste ${score} de ${quizData.length} respuestas correctas.`;
    resultP.classList.remove('hidden');

    // Desactivar todas las opciones para que no se cambie después
    const allRadios = document.querySelectorAll('input[type="radio"]');
    allRadios.forEach(r => r.disabled = true);

    // Cambiar botones
    checkBtn.disabled = true;
    resetBtn.classList.remove('hidden');
}

/* ------------------------------------------------------------
   Reinicio del quiz
   ------------------------------------------------------------ */
function resetQuiz() {
    renderQuiz();                  // vuelve a generar todo
    resultP.classList.add('hidden');
    checkBtn.disabled = false;
    resetBtn.classList.add('hidden');
}

/* ------------------------------------------------------------
   Eventos
   ------------------------------------------------------------ */
checkBtn.addEventListener('click', evaluateQuiz);
resetBtn.addEventListener('click', resetQuiz);

/* ------------------------------------------------------------
   Inicializamos la página
   ------------------------------------------------------------ */
renderQuiz();
```

---

## 📦 ¿Cómo usarlo?

1. **Crea una carpeta** (por ejemplo `quiz10`).  
2. Dentro de esa carpeta crea los tres archivos:
   - `index.html`
   - `style.css`
   - `script.js`
3. Copia el código correspondiente a cada archivo (los bloques arriba).  
4. Abre `index.html` con tu navegador favorito. ¡Listo! Verás el cuestionario con 10 preguntas, podrás seleccionar una opción por cada una y, al pulsar **Comprobar**, obtendrás tu puntuación.

### Personalización
- **Cambiar preguntas**: Edita el arreglo `quizData` en `script.js`. Cada objeto tiene `question`, `options` (array) y `answer` (índice de la opción correcta, empezando en 0).
- **Modificar estilo**: Cambia colores, tipografías o márgenes en `style.css`.
- **Añadir funcionalidades**: temporizador, feedback por pregunta, guardado en `localStorage`, etc.

---

## 🎉 ¡Listo!  
Con estos tres archivos tienes una aplicación web sencilla pero completa para administrar un cuestionario de 10 preguntas. Puedes ampliarla a más preguntas, añadir categorías, o incluso conectar un backend para almacenar resultados. ¡Diviértete programando! 🚀

