```js
// build-db.js
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('./db/blog.sqlite');

db.serialize(() => {
  // Settings table – always a single row (id = 1)
  db.run(`
    CREATE TABLE IF NOT EXISTS settings (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      blog_title TEXT NOT NULL,
      blog_subtitle TEXT NOT NULL,
      author_name TEXT NOT NULL
    )
  `);
  db.run(`
    INSERT OR IGNORE INTO settings (id, blog_title, blog_subtitle, author_name)
    VALUES (1, 'My Blog', 'A place for my thoughts', 'Author')
  `);

  // Articles table
  db.run(`
    CREATE TABLE IF NOT EXISTS articles (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      subtitle TEXT,
      content TEXT NOT NULL,
      created_at DATETIME NOT NULL,
      updated_at DATETIME NOT NULL,
      published_at DATETIME,
      is_published INTEGER NOT NULL DEFAULT 0,
      likes INTEGER NOT NULL DEFAULT 0
    )
  `);

  // Comments table
  db.run(`
    CREATE TABLE IF NOT EXISTS comments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      article_id INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at DATETIME NOT NULL,
      FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE
    )
  `);
});

db.close(() => {
  console.log('Database ready.');
});
```

Running `npm run build-db` creates `db/blog.sqlite` with the required tables and a default settings row.

