## 4️⃣ Main server – `index.js`

```js
// index.js
const express = require('express');
const path = require('path');
const sqlite3 = require('sqlite3').verbose();
const { open } = require('sqlite');
const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Middleware
app.use(express.urlencoded({ extended: false }));
app.use(express.static(path.join(__dirname, 'public')));
app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

// ---------------------------------------------------------------------------
// Helper to get DB connection (async/await style)
async function getDb() {
  return open({
    filename: './db/blog.sqlite',
    driver: sqlite3.Database
  });
}

// ---------------------------------------------------------------------------
// ---- SETTINGS -------------------------------------------------------------
async function getSettings() {
  const db = await getDb();
  const row = await db.get('SELECT * FROM settings WHERE id = 1');
  await db.close();
  return row;
}

// ---------------------------------------------------------------------------
// --------------------------- AUTHOR ROUTES --------------------------------
// Author Home --------------------------------------------------------------
app.get('/author', async (req, res) => {
  const db = await getDb();
  const settings = await db.get('SELECT * FROM settings WHERE id = 1');

  const published = await db.all(
    `SELECT id, title, created_at, updated_at, published_at, likes
     FROM articles WHERE is_published = 1 ORDER BY published_at DESC`
  );

  const drafts = await db.all(
    `SELECT id, title, created_at, updated_at FROM articles WHERE is_published = 0
     ORDER BY created_at DESC`
  );

  await db.close();

  res.render('author/home', {
    settings,
    published,
    drafts
  });
});

// Create new draft ----------------------------------------------------------
app.post('/author/create', async (req, res) => {
  const db = await getDb();
  const now = new Date().toISOString();
  const result = await db.run(
    `INSERT INTO articles (title, subtitle, content, created_at, updated_at)
     VALUES ('Untitled', '', '', ?, ?)`,
    now,
    now
  );
  await db.close();
  res.redirect(`/author/edit/${result.lastID}`);
});

// Edit article (GET) --------------------------------------------------------
app.get('/author/edit/:id', async (req, res) => {
  const db = await getDb();
  const article = await db.get(`SELECT * FROM articles WHERE id = ?`, req.params.id);
  const settings = await db.get('SELECT * FROM settings WHERE id = 1');
  await db.close();

  if (!article) return res.status(404).send('Article not found');
  res.render('author/edit', { article, settings });
});

// Edit article (POST) -------------------------------------------------------
app.post('/author/edit/:id', async (req, res) => {
  const { title, subtitle, content } = req.body;
  const now = new Date().toISOString();

  const db = await getDb();
  await db.run(
    `UPDATE articles
     SET title = ?, subtitle = ?, content = ?, updated_at = ?
     WHERE id = ?`,
    title,
    subtitle,
    content,
    now,
    req.params.id
  );
  await db.close();

  res.redirect('/author');
});

// Publish draft -------------------------------------------------------------
app.post('/author/publish/:id', async (req, res) => {
  const now = new Date().toISOString();
  const db = await getDb();
  await db.run(
    `UPDATE articles
     SET is_published = 1, published_at = ?, updated_at = ?
     WHERE id = ?`,
    now,
    now,
    req.params.id
  );
  await db.close();
  res.redirect('/author');
});

// Delete article ------------------------------------------------------------
app.post('/author/delete/:id', async (req, res) => {
  const db = await getDb();
  await db.run(`DELETE FROM articles WHERE id = ?`, req.params.id);
  await db.close();
  res.redirect('/author');
});

// Settings page (GET) -------------------------------------------------------
app.get('/author/settings', async (req, res) => {
  const settings = await getSettings();
  res.render('author/settings', { settings });
});

// Settings page (POST) ------------------------------------------------------
app.post('/author/settings', async (req, res) => {
  const { blog_title, blog_subtitle, author_name } = req.body;
  const db = await getDb();
  await db.run(
    `UPDATE settings SET blog_title = ?, blog_subtitle = ?, author_name = ? WHERE id = 1`,
    blog_title,
    blog_subtitle,
    author_name
  );
  await db.close();
  res.redirect('/author');
});

// ---------------------------------------------------------------------------
// --------------------------- READER ROUTES --------------------------------
// Reader Home ---------------------------------------------------------------
app.get('/', async (req, res) => {
  const db = await getDb();
  const settings = await db.get('SELECT * FROM settings WHERE id = 1');

  const articles = await db.all(
    `SELECT id, title, published_at FROM articles
     WHERE is_published = 1
     ORDER BY published_at DESC`
  );

  await db.close();
  res.render('reader/home', { settings, articles });
});

// Reader article page --------------------------------------------------------
app.get('/article/:id', async (req, res) => {
  const db = await getDb();
  const article = await db.get(`SELECT * FROM articles WHERE id = ? AND is_published = 1`, req.params.id);
  const settings = await db.get('SELECT * FROM settings WHERE id = 1');

  if (!article) {
    await db.close();
    return res.status(404).send('Article not found');
  }

  const comments = await db.all(
    `SELECT content, created_at FROM comments
     WHERE article_id = ?
     ORDER BY created_at ASC`,
    req.params.id
  );

  await db.close();

  res.render('reader/article', { settings, article, comments });
});

// Like article ---------------------------------------------------------------
app.post('/article/:id/like', async (req, res) => {
  const db = await getDb();
  await db.run(
    `UPDATE articles SET likes = likes + 1 WHERE id = ?`,
    req.params.id
  );
  await db.close();
  res.redirect(`/article/${req.params.id}`);
});

// Add comment ----------------------------------------------------------------
app.post('/article/:id/comment', async (req, res) => {
  const { comment } = req.body;
  const now = new Date().toISOString();

  const db = await getDb();
  await db.run(
    `INSERT INTO comments (article_id, content, created_at)
     VALUES (?, ?, ?)`,
    req.params.id,
    comment,
    now
  );
  await db.close();

  res.redirect(`/article/${req.params.id}`);
});

// ---------------------------------------------------------------------------
// 404 fallback
app.use((req, res) => {
