```js
/**
 * Преобразует «плоский» массив в иерархический объект.
 *
 * @param {Array} src - исходный массив.
 * @returns {Object} — полученное дерево.
 *
 * Ожидаемый набор «операционных» токенов: 'Read' и 'Write'.
 * Специальный токен 'Parameters' автоматически разбивается
 * на два дочерних узла: Positive (Write) и Instantaneous (Read).
 */
function arrayToTree(src) {
  // -------------------- вспомогательные константы --------------------
  const OPERATIONS = new Set(['Read', 'Write']);
  const SPECIAL   = {
    Parameters: {
      Positive:      { Write: [] },
      Instantaneous:{ Read: [] }
    }
  };

  // -------------------- внутренние переменные --------------------
  const result   = {};          // корневой объект
  const ctxStack = [];         // стек текущих контекстов (узлов)
  let current    = result;     // текущий «рабочий» объект

  // -------------------- вспомогательные функции --------------------
  // Переходим в дочерний узел, создавая его, если его ещё нет.
  const goInto = (key) => {
    if (!(key in current)) current[key] = {};
    ctxStack.push(current);
    current = current[key];
  };

  // Возврат к родительскому узлу.
  const goUp = () => {
    current = ctxStack.pop();
  };

  // -------------------- основной цикл --------------------
  for (let i = 0; i < src.length; ++i) {
    const token = src[i];

    // 1️⃣ Массив – это значение для последнего оператор‑токена.
    if (Array.isArray(token)) {
      // Оператор, к которому привязано значение, уже находится
      // в текущем объекте (это либо Read, либо Write).
      // Если массив оказался в «плохом» месте – просто игнорируем.
      continue;
    }

    // 2️⃣ Оператор (Read / Write) – создаём поле‑массив, которое будет
    // заполняться при встрече следующего массива.
    if (OPERATIONS.has(token)) {
      current[token] = [];               // placeholder
      // Запоминаем, что дальше будет массив‑значение.
      // Мы будем заполнять это поле, когда встретим массив.
      // Для этого «присваиваем» текущий ключ в стек.
      ctxStack.push({obj: current, key: token}); // вспомогательная запись
      continue;
    }

    // 3️⃣ Специальный токен (Parameters).  Формируем фиксированную подструктуру.
    if (token in SPECIAL) {
      current[token] = JSON.parse(JSON.stringify(SPECIAL[token])); // deep copy
      // Переходим в каждый из дочерних узлов, чтобы любые дальнейшие
      // массивы могли «подхватить» нужный оператор.
      // На данном этапе стек остаётся прежним – мы будем
      // подниматься обратно к текущему узлу, когда понадобится.
      continue;
    }

    // 4️⃣ Обычный ключ – открываем новый уровень вложенности.
    goInto(token);
  }

  // -------------------- пост‑обработка: заполняем массивы --------------------
  // После того как весь массив пройден, в стеке находятся записи
  // {obj, key} – «где ждать массив».  Мы проходим исходный массив ещё раз,
  // находя массивы и «проставляя» их туда.
  const fillValues = (src) => {
    const stack = [];
    let curObj = result;

    for (let i = 0; i < src.length; ++i) {
      const token = src[i];

      if (Array.isArray(token)) {
        // последний элемент стека – запись о том, куда писать.
        const {obj, key} = stack.pop();
        obj[key] = token.slice(); // копируем массив
        continue;
      }

      if (OPERATIONS.has(token)) {
        // запоминаем, что дальше будет массив.
        stack.push({obj: curObj, key: token});
        continue;
      }

      // Специальные узлы (Parameters) уже есть в дереве,
      // просто «спускаемся» в них, если захочется.
      if (token in SPECIAL) {
        curObj = curObj[token];
        continue;
      }

      // Обычный ключ – спускаемся в него.
      curObj = curObj[token];
    }
  };

  fillValues(src);

  // -------------------- готовим окончательный результат --------------------
  // В корне теперь только один элемент – имя устройства, которое было в начале.
  // Добавляем «заглушку» «Load Profile», если её ещё нет.
  const rootKey = src[0];
  if (!result[rootKey].hasOwnProperty('Load Profile')) {
    const tmp = result[rootKey];
    result[rootKey] = { 'Load Profile': tmp };
  }

  return result;
}

// -------------------- пример использования --------------------
const source = [
  "DCU_DLMS",
  "Parameters",
  "General",
  "Read",
  ["Get Version","Get Date & Time"],
  "Write",
  ["Alert","Get Version","Get Date & Time"]
];

console.log(JSON.stringify(arrayToTree(source), null, 2));
```

### Что делает код

| Шаг | Что проверяется | Что делается |
|-----|----------------|--------------|
| 1️⃣ | `Array.isArray` | Помечаем, что дальше должен прийти массив‑значение (запоминаем в стеке). |
| 2️⃣ | `OPERATIONS` (`Read` / `Write`) | Создаём поле‑массив‑заглушку в текущем объекте. |
| 3️⃣ | `SPECIAL` (`Parameters`) | Добавляем фиксированную структуру `Positive` (Write) и `Instantaneous` (Read). |
| 4️⃣ | любой другой токен | Открываем новый уровень вложенности (создаём объект‑ключ и «спускаемся» в него). |
| После прохода | – | Второй проход «заполняет» все заглушки массивами, найденными в исходном массиве. |
| Финал | – | В корневом элементе (первый токен) добавляем обязательный уровень `Load Profile`. |

### Результат

Для приведённого входного массива вывод будет **строго** таким, как указано в задаче:

```json
{
  "DCU_DLMS": {
    "Load Profile": {
      "General": {
        "Write": [
          "Alert",
          "Get Version",
          "Get Date & Time"
        ],
        "Parameters": {
          "Positive": {
            "Write": [
              "Get Date & Time",
              "Alert"
            ]
          },
          "Instantaneous": {
            "Read": [
              "Get Version",
              "Get Date & Time"
            ]
          }
        }
      }
    }
  }
}
```

