  server.listen(PORT, () => {
    logger.info('🚀 Server listening on http://0.0.0.0:%d', PORT);
  });

  // ---------- Graceful shutdown ----------
  const shutdown = async (signal) => {
    logger.info('🛎️ Received %s – shutting down...', signal);
    server.close(async (err) => {
      if (err) {
        logger.error('Error while closing HTTP server: %s', err);
        process.exit(1);
      }
      try {
        await mongoService.close();
        await lockManager.release();
        logger.info('✅ Graceful shutdown complete.');
        process.exit(0);
      } catch (e) {
        logger.error('Error during graceful shutdown: %s', e);
        process.exit(1);
      }
    });

    // Force‑exit if shutdown takes too long
    setTimeout(() => {
      logger.warn('🔴 Forced shutdown after 10 s');
      process.exit(1);
    }, 10_000).unref();
  };

