/**
 * @module websocketApi
 * @description
 * A tiny wrapper around a native WebSocket that normalises incoming messages
 * into **mitt** events. The default export is a singleton instance
 * (`websocketApi`) that can be imported wherever a WebSocket connection is required.
 *
 * @example
 * import { websocketApi } from '@/utils/websocketApi.js'
 *
 * // Open the connection once (e.g. on app start)
 * websocketApi.open()
 *
 * // Listen for events emitted by the manager
 * websocketApi.emitter.on('update_station', ({ uuid }) => {
 *   console.log('Station updated →', uuid)
 * })
 *
 * // Send a message to the server
 * websocketApi.sendMessage({ action: 'ping' })
 */

/* --------------------------------------------------------------- *
 *  Dependencies
 * --------------------------------------------------------------- */
import mitt from 'mitt'   // mitt is a tiny event emitter (https://github.com/developit/mitt)

/* --------------------------------------------------------------- *
 *  Type definitions
 * --------------------------------------------------------------- */

/**
 * The shape of a raw JSON payload received from the server.
 *
 * @typedef {Object} WSMessage
 * @property {'update_station'|'update_station_list'|'update_inventory'} action
 * @property {string} [uuid]          – UUID of the station (present when `action === 'update_station'`).
 * @property {string} [factory]       – Factory UUID (present when `action === 'update_inventory'`).
 * @property {string} [inventory]     – Inventory name (present when `action === 'update_inventory'`).
 */

/**
 * Payload emitted by the `update_station` event.
 *
 * @typedef {Object} UpdateStationPayload
 * @property {string} uuid – The UUID of the station that changed.
 */

/**
 * Payload emitted by the `update_inventory` event.
 *
 * @typedef {Object} UpdateInventoryPayload
 * @property {string} factory_uuid   – The factory’s UUID.
 * @property {string} inventory_name – The name of the inventory that changed.
 */

/* --------------------------------------------------------------- *
 *  Class definition
 * --------------------------------------------------------------- */

/**
 * Manages a single WebSocket connection and forwards server messages
 * as **mitt** events.
 *
 * @class
 */
class WebSocketManager {
  /**
   * Creates a new manager.
   *
   * The constructor does **not** open a connection – call {@link WebSocketManager#open}
   * explicitly when you are ready.
   *
   * @protected
   * @property {Mitt.Emitter} emitter - A mitt emitter used to broadcast events.
   * @property {WebSocket|null} socket - The underlying native WebSocket (null until `open()` is called).
   */
  constructor () {
    /**
     * @type {Mitt.Emitter}
     */
    this.emitter = mitt()

    /** @type {WebSocket|null} */
    this.socket = null
  }

  /**
   * Opens a WebSocket connection to the backend and registers a listener
   * that transforms incoming JSON messages into mitt events.
   *
   * The method is **idempotent** – calling it when a socket is already open will
   * replace the old instance with a new one.
   *
   * @fires WebSocketManager#update_station
   * @fires WebSocketManager#update_station_list
   * @fires WebSocketManager#update_inventory
   *
   * @returns {void}
   */
  open () {
    this.socket = new WebSocket('ws://owbalancer.ddns.net:8765/site')

    // Preserve `this` for the closure
    const self = this

    this.socket.addEventListener('message', (msg) => {
      /** @type {WSMessage} */
      const json = JSON.parse(msg.data)

      const { action, uuid, factory, inventory } = json

      // Dispatch a mitt event according to the server payload
      if (action === 'update_station') {
        /** @type {UpdateStationPayload} */
        const payload = { uuid }
        self.emitter.emit('update_station', payload)
        return
      }

      if (action === 'update_station_list') {
        self.emitter.emit('update_station_list')
        return
      }

      if (action === 'update_inventory') {
        /** @type {UpdateInventoryPayload} */
        const payload = {
          factory_uuid: factory,
          inventory_name: inventory
        }
        self.emitter.emit('update_inventory', payload)
      }
    })
  }

  /**
   * Sends a plain‑object payload to the server via the open WebSocket.
   *
   * The object is automatically `JSON.stringify`‑ed before transmission.
   *
   * @param {Object} data - The data to send. Must be JSON‑serialisable.
   *
   * @throws {Error} If called before a connection has been opened.
   *
   * @returns {void}
   */
  sendMessage (data) {
