```python
# main.py
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from sqlalchemy import select, func, or_
from models import User, async_session  # ваш async SQLAlchemy

app = FastAPI()

@app.get("/api/users")
async def get_users(request: Request):
    params = await request.query_params
    draw   = int(params.get('draw', 0))
    start  = int(params.get('start', 0))
    length = int(params.get('length', 10))
    search = params.get('search[value]', '').strip()

    async with async_session() as session:
        # total rows
        total_stmt = select(func.count()).select_from(User)
        records_total = (await session.execute(total_stmt)).scalar_one()

        # filter
        where_clause = True
        if search:
            where_clause = or_(
                User.name.ilike(f"%{search}%"),
                User.email.ilike(f"%{search}%")
            )

        # filtered count
        filtered_stmt = select(func.count()).select_from(User).where(where_clause)
        records_filtered = (await session.execute(filtered_stmt)).scalar_one()

        # data page
        data_stmt = (
            select(User.id, User.name, User.email,
                   func.strftime('%Y-%m-%d %H:%M:%S', User.created_at).label('registered_at'))
            .where(where_clause)
            .order_by(User.id.asc())
            .offset(start)
            .limit(length)
        )
        rows = (await session.execute(data_stmt)).all()
        data = [dict(row) for row in rows]

    return JSONResponse({
        "draw": draw,
        "recordsTotal": records_total,
        "recordsFiltered": records_filtered,
        "data": data
    })
```

> **Замечание:** во всех примерах мы делаем **простейшую сортировку** (`ORDER BY id`). В реальном проекте стоит добавить динамический `order` (получаем из `req.query.order[0][column]` и `order[0][dir]`) и защитаться от SQL‑инъекций.

---

### 4️⃣ Как протестировать без собственного бек‑энда  

Если у вас сейчас нет сервера, можно воспользоваться **Mock‑API** (например, `json-server` или `Mocki.io`). Ниже – простой «фиктивный» ответ, который будет отдаваться при запросе к `/api/users` (предполагаем, что вы запустили локальный сервер).

```js
// mock.js – подключайте после jQuery, но перед DataTables init
$.mockjax({
    url: '/api/users',
    responseTime: 500,
    response: function (settings) {
        const draw   = parseInt(settings.data.draw);
        const start  = parseInt(settings.data.start);
        const length = parseInt(settings.data.length);
        const total  = 123;               // общее количество записей

        // генерируем фиктивные строки
        const data = [];
        for (let i = 0; i < length; i++) {
            const id = start + i + 1;
            if (id > total) break;
            data.push({
                id: id,
                name: `Имя ${id}`,
                email: `user${id}@example.com`,
                registered_at: '2023-01-01 12:00:00'
            });
        }

        this.responseText = {
            draw: draw,
            recordsTotal: total,
            recordsFiltered: total,
            data: data
        };
    }
});
```

*Для работы нужен плагин `jquery.mockjax`* – подключите его так:

```html
<script src="https://cdnjs.cloudflare.com/ajax/libs/jquery-mockjax/2.6.0/jquery.mockjax.min.js"></script>
```

---

### 5️⃣ Что ещё можно улучшить  

| Фича | Как добавить |
|------|--------------|
| **Кастомные кнопки** (экспорт в Excel/CSV, печать) | Подключить `Buttons`-extension DataTables и добавить в `dom`‑опцию: `dom: 'Bfrtip', buttons: ['excel', 'csv', 'print']`. |
| **Колонки‑фильтры** в заголовке | Добавьте в `<thead>` второй `<tr>` с `<input class="form-control form-control-sm">` и в `initComplete` привяжите их к `column().search()`. |
| **Темный режим** | Используйте `bootstrap-dark` тему или добавьте кастомный CSS (`table-dark` и `bg-dark`). |
| **Индикатор загрузки** | DataTables уже показывает «Processing...», но можно кастомизировать через `language.processing`. |
| **Обработка ошибок** | В `ajax` добавьте `error: function(xhr, error, thrown){ console.error(error); }`. |

