// server.js
const express = require('express');
const path = require('path');
const fs = require('fs');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 3000;

// 允许跨域（前端如果和后端不在同一域名时需要）
app.use(cors());

// 静态资源目录
app.use(express.static(path.join(__dirname, 'public')));
app.use('/models', express.static(path.join(__dirname, 'models')));

/**
 * 读取 models 目录下的所有模型信息
 * 约定每个模型放在独立子文件夹里，必须有：
 *   - 任意 3D 模型文件（我们不在这里判断后缀，只要存在即可）
 *   - preview.xxx（图片，用于预览）
 *   - meta.json   {"name":"模型名称","category":"分类名称"}
 */
function loadModels() {
  const modelsRoot = path.join(__dirname, 'models');
  const items = fs.readdirSync(modelsRoot, { withFileTypes: true });

  const models = [];

  items.forEach(dirent => {
    if (!dirent.isDirectory()) return;

    const folder = path.join(modelsRoot, dirent.name);
    const metaPath = path.join(folder, 'meta.json');

    if (!fs.existsSync(metaPath)) return; // 必须有 meta.json

    let meta;
    try {
      meta = JSON.parse(fs.readFileSync(metaPath, 'utf-8'));
    } catch (e) {
      console.warn(`Invalid meta.json in ${dirent.name}:`, e);
      return;
    }

    // 寻找模型文件（第一个非 meta.json / preview.* 的文件）
    const files = fs.readdirSync(folder);
    const modelFile = files.find(f => !f.startsWith('meta.') && !f.startsWith('preview.'));
    const previewFile = files.find(f => f.toLowerCase().startsWith('preview.'));

    if (!modelFile || !previewFile) return; // 必须都有

    models.push({
      id: dirent.name,                                   // 唯一标识（文件夹名）
      name: meta.name || dirent.name,
      category: meta.category || '未分类',
      modelUrl: `/models/${dirent.name}/${modelFile}`,
      previewUrl: `/models/${dirent.name}/${previewFile}`
    });
  });

  return models;
}

// API：返回全部模型信息（前端自行过滤、分页）
app.get('/api/models', (req, res) => {
  const models = loadModels();
  res.json(models);
});

// 其它所有路由交给前端 index.html（单页面应用）
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`🚀 Server is running at http://localhost:${PORT}`);
});
```

