## 5️⃣ public/app.js（前端交互逻辑）

```js
/* app.js */
const API_URL = '/api/models';
const ITEMS_PER_PAGE = 20;   // 4 列 × 5 行
let allModels = [];          // 从后端获取的全部模型
let filteredModels = [];    // 当前分类过滤后的模型
let currentCategory = 'all';
let currentPage = 1;

/* ---------- 初始化 ---------- */
document.addEventListener('DOMContentLoaded', async () => {
  await loadModels();
  renderCategoryFilters();
  applyFilter(); // 默认全部
});

/* ---------- 读取模型数据 ---------- */
async function loadModels() {
  try {
    const resp = await fetch(API_URL);
    allModels = await resp.json();
  } catch (e) {
    console.error('Failed to fetch models:', e);
    allModels = [];
  }
}

/* ---------- 分类过滤 ---------- */
function renderCategoryFilters() {
  const container = document.getElementById('categoryContainer');
  const categories = [...new Set(allModels.map(m => m.category))].sort();

  // 为每个分类生成单选框
  categories.forEach(cat => {
    const label = document.createElement('label');
    label.innerHTML = `<input type="radio" name="category" value="${cat}"> ${cat}`;
    container.appendChild(label);
  });

  // 监听分类切换
  document.querySelectorAll('input[name="category"]').forEach(radio => {
    radio.addEventListener('change', e => {
      currentCategory = e.target.value;
      currentPage = 1;
      applyFilter();
    });
  });
}

/* ---------- 过滤并渲染 ---------- */
function applyFilter() {
  if (currentCategory === 'all') {
    filteredModels = allModels.slice(); // 复制
  } else {
    filteredModels = allModels.filter(m => m.category === currentCategory);
  }
  renderPage();
}

/* ---------- 渲染当前页 ---------- */
function renderPage() {
  const grid = document.getElementById('gridContainer');
  grid.innerHTML = '';

  const startIdx = (currentPage - 1) * ITEMS_PER_PAGE;
  const pageItems = filteredModels.slice(startIdx, startIdx + ITEMS_PER_PAGE);

  pageItems.forEach(item => {
    const div = document.createElement('div');
    div.className = 'grid-item';

    // <a href="模型文件" download> 包裹图片
    const a = document.createElement('a');
    a.href = item.modelUrl;
    a.download = `${item.name}${getFileExtension(item.modelUrl)}`;

    const img = document.createElement('img');
    img.src = item.previewUrl;
    img.alt = item.name;
    a.appendChild(img);

    const title = document.createElement('div');
    title.className = 'title';
    title.textContent = item.name;

    div.appendChild(a);
    div.appendChild(title);
    grid.appendChild(div);
  });

  renderPagination();
}

/* ---------- 分页条 ---------- */
function renderPagination() {
  const pagination = document.getElementById('pagination');
  pagination.innerHTML = '';

  const totalPages = Math.ceil(filteredModels.length / ITEMS_PER_PAGE);
  if (totalPages <= 1) return; // 不需要分页

  // 上一页按钮
  const prevBtn = document.createElement('button');
  prevBtn.textContent = '← 上一页';
  prevBtn.disabled = currentPage === 1;
  prevBtn.onclick = () => { currentPage--; renderPage(); };
  pagination.appendChild(prevBtn);

  // 页面数字（最多显示 5 个相邻页码）
  const maxVisible = 5;
  let start = Math.max(1, currentPage - Math.floor(maxVisible / 2));
  let end = Math.min(totalPages, start + maxVisible - 1);
  if (end - start < maxVisible - 1) start = Math.max(1, end - maxVisible + 1);

  for (let i = start; i <= end; i++) {
    const span = document.createElement('span');
    span.textContent = i;
    span.className = i === currentPage ? 'active' : '';
    span.onclick = () => { currentPage = i; renderPage(); };
    pagination.appendChild(span);
  }

  // 下一页按钮
  const nextBtn = document.createElement('button');
  nextBtn.textContent = '下一页 →';
  nextBtn.disabled = currentPage === totalPages;
  nextBtn.onclick = () => { currentPage++; renderPage(); };
  pagination.appendChild(nextBtn);
}

/* ---------- 小工具 ---------- */
function getFileExtension(url) {
  const parts = url.split('.');
  return parts.length > 1 ? '.' + parts.pop().split(/[?#]/)[0] : '';
}
```

