// 1️⃣ Парсеры тела запроса
app.use(express.json());                 // JSON
app.use(express.urlencoded({ extended: true })); // application/x-www-form-urlencoded

// 2️⃣ Роуты

// POST JSON
app.post('/api/users', (req, res) => {
  const { name, age } = req.body;
  if (!name || typeof age !== 'number') {
    return res.status(400).json({ error: 'Invalid payload' });
  }
  // имитация сохранения...
  res.json({ status: 'created', user: { name, age } });
});

// GET с query‑параметрами
app.get('/search', (req, res) => {
  const { term = '', page = '1' } = req.query;
  res.json({ term, page: Number(page) });
});

// GET с path‑параметром
app.get('/users/:id', (req, res) => {
  const userId = Number(req.params.id);
  if (Number.isNaN(userId)) {
    return res.status(400).json({ error: 'Invalid id' });
  }
  // stub user
  res.json({ id: userId, name: 'Demo User' });
});

// Upload single file
app.post('/avatar', upload.single('avatar'), (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'File missing' });
  res.json({ file: req.file });
});

// 3️⃣ Обработчик ошибок парсинга
app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({ error: 'Bad JSON' });
  }
  console.error(err);
  res.status(500).json({ error: 'Server error' });
});

// 4️⃣ Запуск
app.listen(PORT, () => {
  console.log(`Server started on http://localhost:${PORT}`);
