const ELON_TWITTER_ID = "44196397"; // Elon Musk's user_id on Twitter
const CACHE_TTL_MS = 1000 * 60 * 60 * 24; // 24 h

/**
 * Simple in‑memory cache (persisted in chrome.storage.sync)
 */
async function getCache(key) {
  const result = await chrome.storage.sync.get([key]);
  if (result[key] && Date.now() - result[key].ts < CACHE_TTL_MS) {
    return result[key].data;
  }
  return null;
}
async function setCache(key, data) {
  const entry = { data, ts: Date.now() };
  await chrome.storage.sync.set({ [key]: entry });
}

/**
 * Helper: fetch Elon tweets that contain `term`.
 * Requires a Bearer token stored in chrome.storage (see options page).
 */
async function fetchElonTweets(term) {
  const { bearerToken } = await chrome.storage.sync.get(["bearerToken"]);
  if (!bearerToken) throw new Error("Twitter bearer token not set.");

  // Encode term for basic full‑text match. Twitter API does not support fuzzy search,
  // so we use the simple "keyword" operator.
  const query = encodeURIComponent(`from:elonmusk ${term}`);
  const url = `https://api.twitter.com/2/tweets/search/recent?query=${query}&max_results=10&tweet.fields=created_at,public_metrics`;

  const resp = await fetch(url, {
    headers: { Authorization: `Bearer ${bearerToken}` },
  });

  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`Twitter API error: ${resp.status} ${txt}`);
  }

  const json = await resp.json();
  // Return an array of simple objects.
  return json.data?.map(t => ({
    text: t.text,
    created_at: t.created_at,
    url: `https://twitter.com/elonmusk/status/${t.id}`
  })) ?? [];
}

/**
 * Fallback: ask OpenAI for a concise quote.
