async function askOpenAI(term) {
  const { openAiKey } = await chrome.storage.sync.get(["openAiKey"]);
  if (!openAiKey) throw new Error("OpenAI key not set.");

  const prompt = `Give me up to 3 short direct quotes (max 140 characters each) that Elon Musk has publicly said about “${term}”. Include a source URL if possible. If no quote exists, respond with “No known quote”.`;

  const resp = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${openAiKey}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",          // cheap & fast
      messages: [{ role: "user", content: prompt }],
      temperature: 0.2,
      max_tokens: 500
