function createInfoButton(range) {
  // Remove old button if present
  removeInfoButton();

  const button = document.createElement("div");
  button.className = "elon-info-btn";
  button.title = "What has Elon Musk said about this?";
  button.textContent = "🚀";

  // Position: top‑right of the bounding rect
  const rect = range.getBoundingClientRect();
  button.style.top = `${rect.top + window.scrollY - 10}px`;
  button.style.left = `${rect.right + window.scrollX + 4}px`;

  button.addEventListener("click", async e => {
    e.stopPropagation();
    const term = lastSelection;
    if (!term) return;
    button.textContent = "⌛";

    const resp = await chrome.runtime.sendMessage({
      type: "GET_ELON_QUOTES",
      term
    });

    button.textContent = "🚀"; // restore

    if (resp.error) {
      showTooltip(term, `<b>Error:</b> ${resp.error}`);
    } else if (resp.quotes && resp.quotes.length) {
      const html = resp.quotes.map(q => {
        const src = q.url
          ? `<a href="${q.url}" target="_blank">↗ tweet</a>`
          : "";
        return `<p>${escapeHtml(q.text)} ${src}</p>`;
      }).join("");
      showTooltip(term, html);
    } else {
      showTooltip(term, "No known Elon‑Musk quote for this term.");
    }
  });

  document.body.appendChild(button);
}

/**
 * Simple tooltip displayed near the selection.
 */
function showTooltip(term, html) {
  removeTooltip();

  tooltipNode = document.createElement("div");
  tooltipNode.className = "elon-tooltip";
  tooltipNode.innerHTML = `<strong>Elon on “${escapeHtml(term)}”</strong>${html}`;

  // Position near current selection (re‑use range)
  const sel = window.getSelection();
  if (sel.rangeCount) {
    const range = sel.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    tooltipNode.style.top = `${rect.bottom + window.scrollY + 8}px`;
    tooltipNode.style.left = `${rect.left + window.scrollX}px`;
  }

  document.body.appendChild(tooltipNode);

  // Auto‑close after 12 s
  setTimeout(removeTooltip, 12_000);
}

/**
 * Helpers
 */
function removeInfoButton() {
  const old = document.querySelector(".elon-info-btn");
  if (old) old.remove();
}
function removeTooltip() {
  if (tooltipNode) tooltipNode.remove();
  tooltipNode = null;
}
function escapeHtml(str) {
  return str.replace(/[&<>"']/g, m => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[m]);
}

/**
 * Listen for text selection changes.
 */
document.addEventListener("mouseup", () => {
  const sel = window.getSelection();
  const txt = sel.toString().trim();
  if (!txt) {
    removeInfoButton();
    return;
  }

  // Heuristic: ignore very long selections (>150 chars) or selections that contain spaces only
  if (txt.length > 150 || /^\s+$/.test(txt)) {
    removeInfoButton();
    return;
  }

  lastSelection = txt;
  // Use the first range for positioning
  const range = sel.getRangeAt(0);
  createInfoButton(range);
});

/**
 * Clean‑up when the page changes (SPA navigation, etc.)
 */
document.addEventListener("visibilitychange", () => {
