### `script.js`
```js
/* ------------------------------
   Weather Projection – OpenWeatherMap
   -------------------------------------------------
   1️⃣  Replace YOUR_API_KEY_HERE with a real key.
   2️⃣  The app fetches:
        • Current weather (temp, description, icon)
        • 3‑day forecast (mid‑day data points)
   3️⃣  All data is displayed in Metric (°C)
   ------------------------------------------------- */
const API_KEY = "YOUR_API_KEY_HERE";
const BASE_URL = "https://api.openweathermap.org/data/2.5";

const $cityInput   = document.getElementById('city-input');
const $searchBtn   = document.getElementById('search-btn');
const $errorBox    = document.getElementById('error');
const $weatherBox  = document.getElementById('weather');
const $cityName    = document.getElementById('city-name');
const $icon        = document.getElementById('icon');
const $description = document.getElementById('description');
const $temp        = document.getElementById('temp');
const $forecast    = document.getElementById('forecast');

/* ---------- Helper ----------
   Convert UNIX timestamp → readable date (weekday)   */
function weekdayFromUnix(ts) {
    const d = new Date(ts * 1000);
    return d.toLocaleDateString(undefined, { weekday: 'short' });
}

/* ---------- Render current weather ---------- */
function renderCurrent(data) {
    $cityName.textContent = `${data.name}, ${data.sys.country}`;
    $temp.textContent = Math.round(data.main.temp);
    $description.textContent = data.weather[0].description;
    $icon.src = `https://openweathermap.org/img/wn/${data.weather[0].icon}@2x.png`;
    $icon.alt = data.weather[0].description;
}

/* ---------- Render 3‑day forecast ----------
   OpenWeatherMap free tier gives a 3‑hour interval list.
   We pick the item that is closest to 12:00 UTC of each next day. */
function renderForecast(list) {
    // Build a map of date → array of entries for that date
    const daily = {};
    list.forEach(item => {
        const date = new Date(item.dt * 1000).toISOString().split('T')[0];
        if (!daily[date]) daily[date] = [];
        daily[date].push(item);
    });

    // Grab the next three days (excluding today)
    const today = new Date().toISOString().split('T')[0];
    const dates = Object.keys(daily).filter(d => d > today).slice(0, 3);

    $forecast.innerHTML = ""; // clear previous
    dates.forEach(date => {
        // Find the entry whose hour is closest to 12:00
        const best = daily[date].reduce((a, b) => {
            const aDiff = Math.abs(new Date(a.dt * 1000).getUTCHours() - 12);
            const bDiff = Math.abs(new Date(b.dt * 1000).getUTCHours() - 12);
            return bDiff < aDiff ? b : a;
        });

        const dayDiv = document.createElement('div');
        dayDiv.className = 'day';
        dayDiv.innerHTML = `
            <strong>${weekdayFromUnix(best.dt)}</strong>
            <br>
            <img src="https://openweathermap.org/img/wn/${best.weather[0].icon}@2x.png"
                 alt="${best.weather[0].description}"
                 title="${best.weather[0].description}">
            <br>
            <span>${Math.round(best.main.temp)}°C</span>
        `;
        $forecast.appendChild(dayDiv);
    });
}

/* ---------- Show / Hide helpers ---------- */
function showError(msg) {
    $errorBox.textContent = msg;
    $errorBox.classList.remove('hidden');
    $weatherBox.classList.add('hidden');
}
function showWeather() {
    $errorBox.classList.add('hidden');
    $weatherBox.classList.remove('hidden');
}

/* ---------- Main API call ----------
   1️⃣ Current weather    → /weather
   2️⃣ 5‑day/3‑hr forecast → /forecast
   Both are requested in parallel for speed. */
async function fetchWeather(city) {
    const urlCurrent = `${BASE_URL}/weather?q=${encodeURIComponent(city)}&units=metric&appid=${API_KEY}`;
    const urlForecast = `${BASE_URL}/forecast?q=${encodeURIComponent(city)}&units=metric&appid=${API_KEY}`;

    try {
        const [resCurrent, resForecast] = await Promise.all([
            fetch(urlCurrent),
            fetch(urlForecast)
        ]);

        if (!resCurrent.ok) throw new Error(`Current weather: ${resCurrent.statusText}`);
        if (!resForecast.ok) throw new Error(`Forecast: ${resForecast.statusText}`);

        const dataCurrent = await resCurrent.json();
        const dataForecast = await resForecast.json();

        renderCurrent(dataCurrent);
        renderForecast(dataForecast.list);
        showWeather();
    } catch (err) {
        console.error(err);
        showError(err.message);
    }
}

/* ---------- Event listeners ---------- */
$searchBtn.addEventListener('click', () => {
    const city = $cityInput.value.trim();
    if (city) fetchWeather(city);
});

$cityInput.addEventListener('keypress', e => {
    if (e.key === 'Enter') $searchBtn.click();
});

/* ---------- Optional: try user's location ----------
   If you want to auto‑detect the user's city, uncomment the block below.
   (You still need an API key.) */
/*
if ('geolocation' in navigator) {
    navigator.geolocation.getCurrentPosition(pos => {
        const { latitude, longitude } = pos.coords;
        const reverse = `${BASE_URL}/weather?lat=${latitude}&lon=${longitude}&units=metric&appid=${API_KEY}`;
        fetch(reverse).then(r => r.json()).then(data => {
            $cityInput.value = data.name;
            fetchWeather(data.name);
        });
    });
}
*/
```

### `README.md` (quick start)
```markdown
# Weather Projection (OpenWeatherMap)

A tiny, mobile‑friendly web app that shows the current weather and a three‑day forecast for any city.

## 📋 Features

* Search by city name
* Current temperature, description and icon
* 3‑day forecast (mid‑day temperature & icon)
* Responsive design – works on phones & tablets
* Pure HTML / CSS / JavaScript – no frameworks, no build step

## 🔑 Prerequisite – OpenWeatherMap API key

1. Create a free account at https://home.openweathermap.org/users/sign_up  
2. Go to **API keys** → **Create key** → copy the key string.  
3. Open `script.js` and replace the placeholder

```js
const API_KEY = "YOUR_API_KEY_HERE";
```

## 🚀 How to run locally

1. **Download / clone** the three files (`index.html`, `style.css`, `script.js`) into the same folder.  
2. Open `index.html` in any modern browser (Chrome, Firefox, Edge, Safari).  
3. Type a city (e.g. `London`) and press **Search**.

> No server is required – the project works purely client‑side.  
> If you open the file via `file://` you may see a CORS warning on some browsers.  
> In that case, start a tiny static server (e.g. `python -m http.server`) and browse to `http://localhost:8000`.

## 🛠️ Extending the app

* **Add more days** – increase the slice `dates = … .slice(0, 3);` or extract all.
* **Switch units** – replace `units=metric` with `imperial` for °F, or add a toggle UI.
* **Show sunrise / sunset** – the current‑weather JSON contains `sys.sunrise` & `sys.sunset`.
* **Cache results** – store the last query in `localStorage` and auto‑load on page refresh.
* **Backend proxy** – to hide the API key you could route requests through a tiny Node/Express endpoint.

## 📜 License

Feel free to copy, modify and share – just give credit if you publish it somewhere.

---

Enjoy coding! 🌤️
```

