    <div id="ball"></div>
</div>

<script>
/* ==================== 配置 ==================== */
const GAME_SIZE   = 600;      // 游戏区域尺寸（px）
const BALL_DIAM   = 60;       // 圆形按钮直径（px）
const BALL_RAD    = BALL_DIAM/2;
const ESCAPE_DIST = 120;      // 当鼠标距离 ≤ 120px 时触发逃跑（可自行调节）
const SAFE_MARGIN = 80;       // 重新生成位置时，必须离鼠标 ≥ 80px
/* ==================== 变量 ==================== */
let score = 0;                         // 当前得分
let escaped = false;                   // 本次接近是否已经触发逃跑（防止一次接近多次逃跑）

const game   = document.getElementById('game');
const ball   = document.getElementById('ball');
const board  = document.getElementById('scoreBoard');

/* -------------------- 初始化 -------------------- */
// 把球放到正中心
resetBallToCenter();

/* -------------------- 事件绑定 -------------------- */
// 1）鼠标在游戏区移动时检测是否需要逃跑
game.addEventListener('mousemove', e => {
    const mousePos = getMousePos(e);
    const ballPos  = getBallCenter();

    const dist = distance(mousePos, ballPos);
    // 当鼠标靠近且本轮未逃跑时，执行逃跑
    if (dist <= ESCAPE_DIST && !escaped) {
        escapeBall(mousePos);
        escaped = true;                  // 本轮已逃跑
    }

    // 当鼠标离球足够远时，恢复 “未逃跑” 状态，准备下一次触发
    if (dist > ESCAPE_DIST + 30) {      // 加一点缓冲，防止抖动
        escaped = false;
    }
});

// 2）点击圆形按钮时计分并复位
ball.addEventListener('click', e => {
    e.stopPropagation(); // 防止触发父容器的 mousemove
    score++;
    board.textContent = `得分：${score}`;
    resetBallToCenter();
    escaped = false; // 复位后再次允许逃跑
});

/* -------------------- 辅助函数 -------------------- */

/**
 * 把圆形按钮放回正中心
 */
function resetBallToCenter(){
    const cx = (GAME_SIZE - BALL_DIAM)/2;   // 左上角坐标
    const cy = (GAME_SIZE - BALL_DIAM)/2;
    ball.style.left = cx + 'px';
    ball.style.top  = cy + 'px';
}

/**
 * 让圆形按钮随机逃跑
 * @param {{x:number,y:number}} mousePos 鼠标当前位置（相对于 #game 左上角）
 */
function escapeBall(mousePos){
    // 计算可用的随机范围（确保球完整在边框内）
    const maxX = GAME_SIZE - BALL_DIAM;
    const maxY = GAME_SIZE - BALL_DIAM;

    // 循环尝试生成一个满足安全距离的坐标（最多尝试 30 次，理论上足够）
    let newX, newY, tries = 0;
    do{
        newX = Math.random() * maxX;
        newY = Math.random() * maxY;
        tries++;
        // 若尝试次数太多，直接接受当前位置（防止死循环）
        if (tries > 30) break;
    }while( distance( {x:newX+BALL_RAD, y:newY+BALL_RAD}, mousePos ) < SAFE_MARGIN );

    // 直接把球移动过去（加一点 CSS 动画效果）
    ball.style.left = newX + 'px';
    ball.style.top  = newY + 'px';
    ball.style.transform = 'scale(1.2)'; // 轻微放大反馈
    setTimeout(()=> ball.style.transform='scale(1)', 80);
}

/**
 * 获取鼠标相对于 #game 左上角的坐标
 */
function getMousePos(e){
    const rect = game.getBoundingClientRect();
    return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
    };
}

/**
 * 获取当前圆形按钮圆心相对于 #game 左上角的坐标
 */
function getBallCenter(){
    const left  = parseFloat(ball.style.left);
    const top   = parseFloat(ball.style.top);
    return {
        x: left + BALL_RAD,
        y: top  + BALL_RAD
    };
}

/**
 * 计算两点之间的欧氏距离
 */
function distance(p1, p2){
    const dx = p1.x - p2.x;
    const dy = p1.y - p2.y;
    return Math.hypot(dx, dy);
}
