    if (role)   { conditions.push(`role = ?`);   params.push(role); }
    if (city)   { conditions.push(`LOWER(city) = ?`);   params.push(city.toLowerCase()); }
    if (genre)  { conditions.push(`LOWER(genre) = ?`);  params.push(genre.toLowerCase()); }

    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

    const sql = `
      SELECT id, name, genre, role, city, thumbnail, soundcloud
      FROM users
      ${where}
      ORDER BY
        CASE
          WHEN LOWER(name) LIKE ? THEN 2        /* exact‑start match */
          WHEN LOWER(name) LIKE ? THEN 1
          ELSE 0
        END DESC,
        CASE
          WHEN LOWER(genre) LIKE ? THEN 2
          WHEN LOWER(genre) LIKE ? THEN 1
          ELSE 0
