## 7️⃣ src/routes/newsletter.js – The API route

```js
// src/routes/newsletter.js
import express from 'express';
import { body, validationResult } from 'express-validator';
import Subscriber from '../models/Subscriber.js';

const router = express.Router();

/**
 * @route   POST /api/newsletter
 * @desc    Subscribe a user to the newsletter
 * @access  Public
 */
router.post(
  '/',
  // ---------- validation ----------
  [
    body('email')
      .isEmail()
      .withMessage('A valid email address is required')
      .normalizeEmail(),
    body('name')
      .optional()
      .isString()
      .trim()
      .isLength({ max: 100 })
      .withMessage('Name must be shorter than 100 characters'),
  ],
  // ---------- controller ----------
  async (req, res) => {
    // 1️⃣ Gather validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        success: false,
        errors: errors.array().map((e) => e.msg),
      });
    }

    const { email, name = '' } = req.body;

    try {
      // 2️⃣ Prevent duplicate subscriptions
      const existing = await Subscriber.findOne({ email });
      if (existing) {
        return res.status(409).json({
          success: false,
          message: 'Email is already subscribed',
        });
      }

      // 3️⃣ Save new subscriber
      await Subscriber.create({ email, name });

      // 4️⃣ Respond with success flag
      return res.status(201).json({
        success: true,
        message: 'Subscribed successfully',
      });
    } catch (err) {
      console.error('❗️ Subscription error:', err);
      return res.status(500).json({
        success: false,
        message: 'Server error. Please try again later.',
      });
    }
  }
);

export default router;
```

