Below the existing `<script>` block (or inside it) add the **new functions**.  
Everything is plain ES6, no external libraries required.

```javascript
/* =========================  HIGH‑SCORE LOGIC  ========================= */

function showHighScoreModal() {
    // 1️⃣ Fill the final score placeholder
    document.getElementById('final-score').textContent = score; // `score` is your global variable

    // 2️⃣ Reset the name field (optional)
    document.getElementById('player-name').value = '';

    // 3️⃣ Show the modal
    document.getElementById('highscore-modal').style.display = 'flex';
}

/**
 * Send a POST request to save_score.php and then reload the toplist.
 */
async function saveScoreAndRefresh() {
    const nameInput = document.getElementById('player-name');
    const name = nameInput.value.trim();

    if (name === '') {
        alert('Please type a name.');
        return;
    }

    // ----- POST the data -------------------------------------------------
    const formData = new URLSearchParams();
    formData.append('name',  name);
    formData.append('score', score); // `score` is the global variable of your game

    let responseText;
    try {
        const response = await fetch('save_score.php', {
            method: 'POST',
            body: formData,
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
        });

        if (!response.ok) throw new Error('Server responded ' + response.status);
        responseText = await response.text(); // the whole file (lines)
    } catch (e) {
        console.error(e);
        alert('Could not save the score – see console for details.');
        return;
    }

    // ----- Parse the raw file ------------------------------------------------
    const entries = responseText
        .trim()
        .split('\n')
        .map(line => {
            const [pName, pScore] = line.split('|');
            return { name: pName, score: Number(pScore) };
        });

    // ----- Sort descending by score -----------------------------------------
    entries.sort((a, b) => b.score - a.score);

    // ----- Render top‑10 -------------------------------------------------------
    const tbody = document.querySelector('#toplist-table tbody');
    tbody.innerHTML = ''; // clear previous rows

    const top10 = entries.slice(0, 10);
    top10.forEach((entry, idx) => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td style="padding:4px; text-align:center;">${idx + 1}</td>
            <td style="padding:4px;">${entry.name}</td>
            <td style="padding:4px; text-align:right;">${entry.score}</td>
        `;
        tbody.appendChild(tr);
    });

    // ----- Hide the input part (optional) ------------------------------------
    // You could also keep it visible to allow another entry
    nameInput.disabled = true;
    document.getElementById('save-score-btn').disabled = true;
}

/* --------------------------  EVENT BINDINGS  -------------------------- */
document.getElementById('save-score-btn')
        .addEventListener('click', saveScoreAndRefresh);

/* --------------------------  MODIFY endGame()  ------------------------ */
function endGame() {
    document.removeEventListener("mousemove", dragRectangle);
    backgroundMusic.pause();

    // 👉 Show the high‑score dialog instead of a plain alert
    showHighScoreModal();

    // If you still want a quick “Game over!” alert, you can keep it:
    // alert("Game over!");
}
```

### What changed?

| Change | Reason |
|--------|--------|
| **`showHighScoreModal()`** | Pre‑pares the modal (writes the final score, clears the text field) and makes it visible. |
| **`saveScoreAndRefresh()`** | Sends the name + score to the PHP script, receives the whole `scores.txt`, parses each line, sorts, and builds a `<table>` with the top ten entries. |
| **`document.getElementById('save-score-btn').addEventListener('click', …)`** | Wire the button to the function above. |
| **`endGame()`** | Instead of the plain `alert()` we now call `showHighScoreModal()` (you still can keep the alert if you like). |

