            scoreElement.innerHTML = 'Score: 0';
            score = 0;                  // reset global score

            backgroundMusic.play();
            backgroundMusic.loop = true;

            setTimerAndAddRow();
        }

        function getRandomColor() {
            const colors = ['red', 'blue', 'green', 'yellow', 'purple', 'orange'];
            const randomIndex = Math.floor(Math.random() * colors.length);
            return colors[randomIndex];
        }

        /* --------------------------------------------------------------------- */
        /* --------------------------- Game logic ----------------------------- */
        /* --------------------------------------------------------------------- */

        let click = 0;    
        let draggedRectangles = [];
        let numberOfRectangles = 0;
        let rectangleColor = null;
        let i = 0;
        let pickedUpRectangles = 0;

        function pickRectangle(event) {
            if (click === 0) {
                const gameBoard = document.getElementById("game-board");
                const boardRect = gameBoard.getBoundingClientRect();
                const columnWidth = gameBoard.offsetWidth / boardWidth;
                const columnIndex = Math.floor((event.clientX - boardRect.left) / columnWidth);
                draggedRectangles.push(...getColoredRectangles(columnIndex));

                // Find the bottom-most empty row in that column
                const rectangles = document.getElementsByClassName("rectangle");
                rectangleColor = draggedRectangles[0].style.backgroundColor;
                numberOfRectangles = draggedRectangles.length;
                pickedUpRectangles = draggedRectangles.length;
                draggedRectangles.forEach(rectangle => {
                    rectangle.style.backgroundColor = "";
                    rectangle.classList.remove("visible");
                });

                for (let row = boardHeight - 1; row >= 0; row--) {
                    const index = row * boardWidth + columnIndex;
                    const rectangle = rectangles[index];

                    if (!rectangle.style.backgroundColor) {
                        rectangle.style.backgroundColor = rectangleColor;
                        rectangle.classList.add("visible");
                        draggedRectangles[i] = rectangle;
                        numberOfRectangles--;
                        i++;
                        if (numberOfRectangles === 0) {
                            break;
                        }
                    }
                }

                document.addEventListener("mousemove", dragRectangle);
                click = 1;
                i = 0;
            } else if (click === 1) {

                // Find the column that the mouse is in
                const gameBoard = document.getElementById("game-board");
                const boardRect = gameBoard.getBoundingClientRect();
                const columnWidth = gameBoard.offsetWidth / boardWidth;
                const columnIndex = Math.floor((event.clientX - boardRect.left) / columnWidth);

                // Restore colors for the dragged rectangles and place them
                draggedRectangles.forEach(rectangle => {
                    const rectanglePlace = getLastNonColoredRectangle(columnIndex);
                    if (rectanglePlace) {
                        rectangle.style.backgroundColor = "";
                        rectangle.classList.remove("visible");
                        rectanglePlace.style.backgroundColor = rectangleColor;
                        rectanglePlace.classList.add("visible");
                    }
                });

                let rectanglePlace = getLastNonColoredRectangle(columnIndex);
                const rectangles = document.getElementsByClassName("rectangle");
                const rectangleIndex = Array.from(rectangles).indexOf(rectanglePlace) - 10;
                console.log(rectangleIndex);

                click = 0;
                document.removeEventListener("mousemove", dragRectangle);
                checkConnectedRectangles(rectangleColor, rectangleIndex);
                draggedRectangles = [];
            }
        }

        function dragRectangle(event) {
          if (draggedRectangles.length > 0) {
            draggedRectangles.forEach((draggedRectangle) => {
              draggedRectangle.style.left = event.clientX - draggedRectangle.offsetWidth / 2 + 'px';
              draggedRectangle.style.top = event.clientY - draggedRectangle.offsetHeight / 2 + 'px';
            });
          }
        }

        function getLastNonColoredRectangle(columnIndex) {
          const rectangles = document.getElementsByClassName('rectangle');
          let lastNonColoredRectangle = null;

          for (let row = 0; row < boardHeight - 4; row++) {
            const index = row * boardWidth + columnIndex;
            const rectangle = rectangles[index];

            if (!rectangle.style.backgroundColor) {
              lastNonColoredRectangle = rectangle;
              break;
            }
          }

          return lastNonColoredRectangle;
        }

        function getColoredRectangles(columnIndex) {
            const rectangles = document.getElementsByClassName("rectangle");
            const coloredRectangles = [];
            let rectangleColor = null;

            for (let row = boardHeight - 4; row >= 0; row--) {
                const index = row * boardWidth + columnIndex;
                const rectangle = rectangles[index];

                if (rectangle.style.backgroundColor) {
                    if (rectangleColor === null) {
                        rectangleColor = rectangle.style.backgroundColor;
                    }
                    if (rectangleColor && rectangle.style.backgroundColor === rectangleColor) {
                        coloredRectangles.push(rectangle);
                    } else if (rectangleColor !== null && rectangle.style.backgroundColor !== rectangleColor) {
                        break;
                    }
                }
            }

            return coloredRectangles;
        }

        let score = 0;

        function checkConnectedRectangles(rectangleColor, index) {
          const rectangles = document.getElementsByClassName("rectangle");
          const draggedRow = Math.floor(index / boardWidth);
          const draggedCol = index % boardWidth;

          const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
          let totalCount = 0;
          let indicesToClear = new Set();

          function checkForConnected(row, col) {
            const idx = row * boardWidth + col;
            if (
              row >= 0 && row < boardHeight &&
              col >= 0 && col < boardWidth &&
              rectangles[idx].style.backgroundColor === rectangleColor
            ) {
                if (!indicesToClear.has(idx)) {
                    indicesToClear.add(idx);
                    directions.forEach(([rStep, cStep]) => {
                        checkForConnected(row + rStep, col + cStep);
                    });
                }
            }
          }

          checkForConnected(draggedRow, draggedCol);
          totalCount = indicesToClear.size;

          if (totalCount >= 4) {
            // Erase the group
            indicesToClear.forEach((idx) => {
                rectangles[idx].style.backgroundColor = "";
                rectangles[idx].classList.remove("visible");
            });
            score += 100 * totalCount;
            document.getElementById("score").innerHTML = "Score: " + score;
            checkGapsInColumns();
          }
        }

        function checkGapsInColumns() {
          const rectangles = document.getElementsByClassName("rectangle");

          for (let col = 0; col < boardWidth; col++) {
            let coloredRectCount = 0;

            // Count how many colored rectangles are present in the current column
            for (let row = 0; row < boardHeight - 4; row++) {
              const idx = row * boardWidth + col;
              const rect = rectangles[idx];

              if (rect.style.backgroundColor) {
                coloredRectCount++;
              }
            }

            // Check for gaps between colored rectangles
            let gapRow = -1;
            for (let row = 0; row < boardHeight - 4 && coloredRectCount > 0; row++) {
              const idx = row * boardWidth + col;
              const rect = rectangles[idx];

              if (gapRow === -1 && !rect.style.backgroundColor) {
                gapRow = row;
              } else if (rect.style.backgroundColor) {
                if (gapRow !== -1) {
                  const gapIdx = gapRow * boardWidth + col;
                  const emptyRect = rectangles[gapIdx];

                  emptyRect.style.backgroundColor = rect.style.backgroundColor;
                  emptyRect.classList.add("visible");
                  rect.style.backgroundColor = "";
                  rect.classList.remove("visible");
                  checkConnectedRectangles(emptyRect.style.backgroundColor, gapIdx);
                  gapRow++;
                }
                coloredRectCount--;
              }
            }
          }
        }

        function addRowToTop() {
          const gameBoard = document.getElementById('game-board');
          const rowDivs = gameBoard.querySelectorAll('.row');

          // Get the colors of the rectangles in the bottom row
          const bottomRowRectangles = rowDivs[rowDivs.length - 1].querySelectorAll('.rectangle');
          const bottomRowColors = Array.from(bottomRowRectangles).map(rect => rect.style.backgroundColor);

          // Shift all rows down by 1
          for (let i = rowDivs.length - 5; i > 0; i--) {
            const cur = rowDivs[i].querySelectorAll('.rectangle');
            const prev = rowDivs[i - 1].querySelectorAll('.rectangle');

            cur.forEach((rect, idx) => {
                const prevRect = prev[idx];
                rect.style.backgroundColor = prevRect.style.backgroundColor;
                rect.classList.toggle('visible', prevRect.classList.contains('visible'));
            });
          }

          // Fill the first row with new colors
          const firstRow = rowDivs[0].querySelectorAll('.rectangle');
          firstRow.forEach((rect, idx) => {
            rect.style.backgroundColor = bottomRowColors[idx] || getRandomColor();
            rect.classList.add('visible');
          });

          checkColumns();
          setTimerAndAddRow();
        }

        let cycle = 1;

        function setTimerAndAddRow() {
            setTimeout(addRowToTop, 2 / cycle * 1000);
            cycle += 0.05;
        }

        function checkColumns() {
          const rectangles = document.getElementsByClassName("rectangle");
          for (let col = 0; col < boardWidth; col++) {
            let count = 0;
            for (let row = boardHeight - 4; row >= 0; row--) {
              const idx = row * boardWidth + col;
              const rect = rectangles[idx];
              if (rect.classList.contains("visible")) count++;
            }
            if (count >= 10) {
              endGame();
              return;
            }
          }
        }

        /* ==================================================================== */
        /* =====================  HIGH‑SCORE SECTION ========================= */
        /* ==================================================================== */

        /** Show modal and put the final score inside */
        function showHighScoreModal() {
            document.getElementById('final-score').textContent = score;
            document.getElementById('player-name').value = '';
            document.getElementById('player-name').disabled = false;
            document.getElementById('save-score-btn').disabled = false;
            document.getElementById('highscore-modal').style.display = 'flex';
        }

        /** POST the name+score, then refresh the displayed top‑list */
        async function saveScoreAndRefresh() {
            const name = document.getElementById('player-name').value.trim();
            if (!name) {
                alert('Please type a name.');
                return;
            }

            // ----- send data -------------------------------------------------
            const payload = new URLSearchParams();
            payload.append('name', name);
            payload.append('score', score);

            let rawFile;
            try {
                const resp = await fetch('save_score.php', {
                    method: 'POST',
                    body: payload,
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
                });
                if (!resp.ok) throw new Error('HTTP ' + resp.status);
                rawFile = await resp.text();            // whole scores.txt
            } catch (e) {
                console.error(e);
                alert('Could not store the score. Check console.');
                return;
            }

            // ----- parse file ------------------------------------------------
            const entries = rawFile.trim().split('\n')
                .filter(l => l)                         // ignore empty lines
                .map(l => {
                    const [pName, pScore] = l.split('|');
                    return { name: pName, score: Number(pScore) };
                });

            // ----- sort descending -------------------------------------------
            entries.sort((a, b) => b.score - a.score);

            // ----- render top‑10 ---------------------------------------------
            const tbody = document.querySelector('#toplist-table tbody');
            tbody.innerHTML = '';
            entries.slice(0, 10).forEach((e, i) => {
                const tr = document.createElement('tr');
                tr.innerHTML = `
                    <td style="text-align:center;">${i + 1}</td>
                    <td>${e.name}</td>
                    <td style="text-align:right;">${e.score}</td>
                `;
                tbody.appendChild(tr);
            });

            // Disable further input (optional)
            document.getElementById('player-name').disabled = true;
            document.getElementById('save-score-btn').disabled = true;
        }

        // Hook the button
        document.getElementById('save-score-btn')
                .addEventListener('click', saveScoreAndRefresh);

        /** Replace the simple alert with the modal */
        function endGame() {
            document.removeEventListener("mousemove", dragRectangle);
            backgroundMusic.pause();
            showHighScoreModal();          // <‑‑ NEW
        }

    </script>
</body>
</html>
```

