## 4. Модель пользователя – `src/models/userModel.js`

Модель – это «чистый» слой доступа к данным. Он не знает ничего о HTTP‑запросах.

```js
// src/models/userModel.js
const db = require('../config/db');
const bcrypt = require('bcryptjs');

const SALT_ROUNDS = 10;

/**
 * Находит пользователя по email.
 * @param {string} email
 * @returns {Promise<Object|null>}
 */
function findByEmail(email) {
  const sql = 'SELECT * FROM users WHERE email = ?';
  return new Promise((resolve, reject) => {
    db.get(sql, [email], (err, row) => {
      if (err) return reject(err);
      resolve(row || null);
    });
  });
}

/**
 * Находит пользователя по id.
 * @param {number} id
 * @returns {Promise<Object|null>}
 */
function findById(id) {
  const sql = 'SELECT id, username, email, created_at FROM users WHERE id = ?';
  return new Promise((resolve, reject) => {
    db.get(sql, [id], (err, row) => {
      if (err) return reject(err);
      resolve(row || null);
    });
  });
}

/**
 * Создаёт нового пользователя.
 * @param {Object} param0
 * @param {string} param0.username
 * @param {string} param0.email
 * @param {string} param0.password  // plain password
 * @returns {Promise<number>} id нового пользователя
 */
async function create({ username, email, password }) {
  const hashed = await bcrypt.hash(password, SALT_ROUNDS);
  const sql = `INSERT INTO users (username, email, password) VALUES (?, ?, ?)`;
  return new Promise((resolve, reject) => {
    db.run(sql, [username, email, hashed], function (err) {
      if (err) return reject(err);
      resolve(this.lastID); // this – контекст run()
    });
  });
}

/**
 * Проверка пароля.
 * @param {string} plainPassword
 * @param {string} hashedPassword
 * @returns {Promise<boolean>}
 */
function comparePassword(plainPassword, hashedPassword) {
  return bcrypt.compare(plainPassword, hashedPassword);
}

module.exports = {
  findByEmail,
  findById,
  create,
  comparePassword,
};
```

*Почему в `findById` мы НЕ возвращаем пароль?* – чтобы в контроллере случайно не отправить хеш клиенту.

