## 6. Контроллер авторизации – `src/controllers/authController.js`

Контроллеры получают `req`, `res`, вызывают модели и формируют ответ.

```js
// src/controllers/authController.js
const jwt = require('jsonwebtoken');
const User = require('../models/userModel');
require('dotenv').config();

const JWT_SECRET = process.env.JWT_SECRET;
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '1h';

/**
 * Формирует JWT для указанного пользователя.
 */
function signToken(user) {
  const payload = { id: user.id };
  return jwt.sign(payload, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });
}

/**
 * POST /api/auth/register
 */
async function register(req, res) {
  const { username, email, password } = req.body;

  try {
    // Проверяем, нет ли уже пользователя с таким email
    const existing = await User.findByEmail(email);
    if (existing) {
      return res
        .status(409) // Conflict
        .json({ message: 'Пользователь с таким email уже существует' });
    }

    const userId = await User.create({ username, email, password });
    const user = await User.findById(userId);

    // Можно сразу вернуть токен, но в примере делаем отдельный login
    const token = signToken(user);
    res.status(201).json({
      message: 'Регистрация прошла успешно',
      token,
      user,
    });
  } catch (err) {
    console.error('❌ Ошибка регистрации:', err);
    res.status(500).json({ message: 'Внутренняя ошибка сервера' });
  }
}

/**
 * POST /api/auth/login
 */
async function login(req, res) {
  const { email, password } = req.body;

  try {
    const user = await User.findByEmail(email);
    if (!user) {
      // Не раскрываем, какой именно параметр неправильный
      return res.status(401).json({ message: 'Неверный email или пароль' });
    }

    const passwordMatches = await User.comparePassword(
      password,
      user.password
    );
    if (!passwordMatches) {
      return res.status(401).json({ message: 'Неверный email или пароль' });
    }

    // Убираем пароль из ответа
    const cleanUser = {
      id: user.id,
      username: user.username,
      email: user.email,
      created_at: user.created_at,
    };

    const token = signToken(cleanUser);
    res.json({
      message: 'Вход выполнен успешно',
      token,
      user: cleanUser,
    });
  } catch (err) {
    console.error('❌ Ошибка логина:', err);
    res.status(500).json({ message: 'Внутренняя ошибка сервера' });
  }
}

/**
 * GET /api/profile – защищённый маршрут
 */
async function getProfile(req, res) {
  // Пользователь уже извлечён из JWT в authMiddleware
  const user = req.user; // { id, iat, exp }
  try {
    const fullUser = await User.findById(user.id);
    if (!fullUser) {
      return res.status(404).json({ message: 'Пользователь не найден' });
    }
    res.json({ user: fullUser });
  } catch (err) {
    console.error('❌ Ошибка получения профиля:', err);
    res.status(500).json({ message: 'Внутренняя ошибка сервера' });
  }
}

module.exports = {
  register,
  login,
  getProfile,
};
```

> **Почему `signToken` только с `id`?** – хранить в JWT минимум данных, иначе токен растёт и легче подделать. По `id` мы легко получаем полную запись из БД.

