## 7. Middleware проверки JWT – `src/middleware/authMiddleware.js`

```js
// src/middleware/authMiddleware.js
const jwt = require('jsonwebtoken');
require('dotenv').config();

const JWT_SECRET = process.env.JWT_SECRET;

/**
 * Middleware, который проверяет наличие и валидность JWT.
 * Если токен валиден – в req.user помещаем payload.
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  // Токен обычно выглядит: "Bearer <token>"
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res
      .status(401)
      .json({ message: 'Токен не найден. Требуется авторизация.' });
  }

  jwt.verify(token, JWT_SECRET, (err, payload) => {
    if (err) {
      console.warn('⚠️ JWT verification error:', err.message);
      return res.status(403).json({ message: 'Неверный или просроченный токен' });
    }

    // payload = { id: ..., iat: ..., exp: ... }
    req.user = payload;
    next();
  });
}

module.exports = authenticateToken;
```

