import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';

export interface PostMeta {
  slug: string;
  title: string;
  date: string;
  excerpt: string;
  // any extra front‑matter you want
}

/**
 * Reads all *.mdx files under the /posts folder,
 * extracts the front‑matter and returns a list sorted by date DESC.
 */
export function getAllPosts(): PostMeta[] {
  const postsDir = path.join(process.cwd(), 'posts');
  const filenames = fs.readdirSync(postsDir).filter((f) => f.endsWith('.mdx'));

  const posts = filenames.map((filename) => {
    const filePath = path.join(postsDir, filename);
    const fileContents = fs.readFileSync(filePath, 'utf8');
    const { data } = matter(fileContents);

    // slug = filename without extension
    const slug = filename.replace(/\.mdx?$/, '');

    return {
      slug,
      title: data.title ?? slug,
      date: data.date ?? new Date().toISOString(),
      excerpt: data.excerpt ?? '',
    } as PostMeta;
  });

  // Sort newest first
  return posts.sort((a, b) => (a.date < b.date ? 1 : -1));
}

/**
 * Returns the full MDX source of a single post (used by the MDX component).
 */
export function getPostBySlug(slug: string) {
  const filePath = path.join(process.cwd(), 'posts', `${slug}.mdx`);
  const source = fs.readFileSync(filePath, 'utf8');
  const { content, data } = matter(source);
  return {
    content,
    meta: {
      slug,
      title: data.title ?? slug,
      date: data.date ?? new Date().toISOString(),
      excerpt: data.excerpt ?? '',
    } as PostMeta,
  };
}
```

