import { notFound } from 'next/navigation';
import { getPostBySlug, getAllPosts } from '@/lib/posts';
import { MDXRemote, MDXRemoteSerializeResult } from 'next-mdx-remote/rsc';
import { format, parseISO } from 'date-fns';
import Head from 'next/head';

// The MDX component is rendered on the server (RSC) → no need for next-mdx-remote on client.
export async function generateStaticParams() {
  const posts = getAllPosts();
  return posts.map((post) => ({
    slug: post.slug,
  }));
}

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}) {
  const post = getPostBySlug(params.slug);
  if (!post) return {};

  return {
    title: post.meta.title,
    description: post.meta.excerpt,
  };
}

export default async function PostPage({ params }: { params: { slug: string } }) {
  const { slug } = params;
  const post = getPostBySlug(slug);
  if (!post) notFound();

  const { meta, content } = post;

  return (
    <>
      <Head>
        {/* Open Graph tags – optional */}
        <meta property="og:title" content={meta.title} />
        <meta property="og:description" content={meta.excerpt} />
        <meta property="og:type" content="article" />
      </Head>

      <article className="prose lg:prose-xl dark:prose-invert max-w-none mx-auto">
        <h1 className="mb-2">{meta.title}</h1>
        <p className="text-sm text-gray-500 dark:text-gray-400 mb-8">
          {format(parseISO(meta.date), 'MMMM d, yyyy')}
        </p>

        {/* Render the MDX content */}
        <MDXRemote source={content} />
      </article>
    </>
  );
}
```

> The `MDXRemote` component from `next-mdx-remote/rsc` works with **React Server Components**, so you don’t need to pre‑serialize the content. This keeps the code minimal.  

> If you prefer the classic `next-mdx-remote` (client‑side) approach, replace the MDX handling accordingly.

