        <input type="number" id="cost" placeholder="e.g. 1200" min="0" step="0.01">
    </div>

    <div class="toggle">
        <button id="toggleMode">Use Fixed Markup Amount</button>
    </div>

    <div class="field-group" id="percentGroup">
        <label for="percent">Markup %</label>
        <input type="number" id="percent" placeholder="e.g. 25" min="0" step="0.01">
    </div>

    <div class="field-group" id="amountGroup" style="display:none;">
        <label for="amount">Markup Amount (₱)</label>
        <input type="number" id="amount" placeholder="e.g. 300" min="0" step="0.01">
    </div>

    <button id="calcBtn">Calculate</button>

    <div class="results" id="results" style="display:none;">
        <div class="result-box">
            <strong>Cost</strong>
            <span id="outCost">₱0.00</span>
        </div>
        <div class="result-box">
            <strong>Profit</strong>
            <span id="outProfit">₱0.00</span>
        </div>
        <div class="result-box">
            <strong>Selling Price</strong>
            <span id="outSell">₱0.00</span>
        </div>
        <div class="result-box">
            <strong>Markup %</strong>
            <span id="outPercent">0%</span>
        </div>
    </div>

    <canvas id="chart" width="400" height="300"></canvas>
</div>

<!-- Chart.js library (CDN) -->
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<script>
(() => {
    const costInput   = document.getElementById('cost');
    const percentInput= document.getElementById('percent');
    const amountInput = document.getElementById('amount');
    const toggleBtn   = document.getElementById('toggleMode');
    const percentGrp  = document.getElementById('percentGroup');
    const amountGrp   = document.getElementById('amountGroup');
    const calcBtn     = document.getElementById('calcBtn');
    const resultsDiv  = document.getElementById('results');

    const outCost    = document.getElementById('outCost');
    const outProfit  = document.getElementById('outProfit');
    const outSell    = document.getElementById('outSell');
    const outPercent = document.getElementById('outPercent');

    let usePercent = true;   // default mode

    // ------- toggle between % and fixed amount -------
    toggleBtn.addEventListener('click', () => {
        usePercent = !usePercent;
        if (usePercent) {
            percentGrp.style.display = 'flex';
            amountGrp.style.display  = 'none';
            toggleBtn.textContent = 'Use Fixed Markup Amount';
        } else {
            percentGrp.style.display = 'none';
            amountGrp.style.display  = 'flex';
            toggleBtn.textContent = 'Use Markup %';
        }
        // clear both fields
        percentInput.value = '';
        amountInput.value  = '';
    });

    // ------- Chart.js initialisation -------
    const ctx = document.getElementById('chart').getContext('2d');
    const chart = new Chart(ctx, {
        type: 'pie',
        data: {
            labels: ['Cost', 'Profit'],
            datasets: [{
                label: 'Break‑down',
                data: [0, 0],
                backgroundColor: ['#4a90e2', '#e94e77'],
                borderColor: '#fff',
                borderWidth: 2
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: { position: 'bottom' },
                tooltip: {
                    callbacks: {
                        label: ctx => {
                            const val = ctx.parsed;
                            return `${ctx.label}: ₱${val.toLocaleString(undefined,{minimumFractionDigits:2})}`;
                        }
                    }
                }
            }
        }
    });

    // ------- calculator logic -------
    const format = n => `₱${Number(n).toLocaleString(undefined,{minimumFractionDigits:2})}`;

    calcBtn.addEventListener('click', () => {
        const cost = parseFloat(costInput.value);
        if (isNaN(cost) || cost < 0) {
            alert('Please enter a valid Cost.');
            return;
        }

        let profit, sellPrice, markupPct;

        if (usePercent) {
            const pct = parseFloat(percentInput.value);
            if (isNaN(pct) || pct < 0) {
                alert('Please enter a valid Markup %.');
                return;
            }
            profit    = cost * pct / 100;
            sellPrice = cost + profit;
            markupPct = pct;
        } else {
            const amt = parseFloat(amountInput.value);
            if (isNaN(amt) || amt < 0) {
                alert('Please enter a valid Markup Amount.');
                return;
            }
            profit    = amt;
            sellPrice = cost + profit;
            markupPct = (profit / cost) * 100;
        }

        // ---- output ----
        outCost.textContent    = format(cost);
        outProfit.textContent  = format(profit);
        outSell.textContent    = format(sellPrice);
        outPercent.textContent = `${markupPct.toFixed(2)}%`;
        resultsDiv.style.display = 'grid';

        // ---- update chart ----
        chart.data.datasets[0].data = [cost, profit];
        chart.update();
    });

})();
</script>
</body>
</html>
```

---  

## 2️⃣  How It Works  

| Part | Explanation |
|------|--------------|
| **HTML** | - Input fields for **cost** and either **markup %** or **markup amount**.<br>- A button to toggle between the two modes.<br>- Result boxes display calculated values.<br>- `<canvas>` element hosts the Chart.js pie chart. |
| **CSS** | Simple, clean design using CSS variables, flex‑grid and a subtle box‑shadow. Works on any screen width up to ~480 px (mobile‑friendly). |
| **JavaScript** | 1. **Toggle** – switches UI between “%” and “fixed amount”.<br>2. **Calculation** – depending on mode it computes profit, selling price and the effective markup %.<br>3. **Formatting** – numbers are rendered as Philippine Peso (`₱`) with two decimal places.<br>4. **Chart.js** – a pie chart shows the proportion **Cost vs Profit**. The chart is updated each time the user clicks *Calculate*. |
| **Chart.js** | Pulled from the CDN (`cdn.jsdelivr.net/npm/chart.js`). Only the *pie* chart type is needed, but you could change it to a *doughnut*, *bar*, etc., by tweaking the `type` and options. |

---  

## 3️⃣  Extending / Customising  

| Want to… | How to do it |
|----------|--------------|
| **Show a line/bar chart of price vs markup** | Replace `type: 'pie'` with `'line'` or `'bar'`, add a second dataset for “selling price”, and feed an array of different markup values (e.g., 5 %, 10 %, 15 %). |
| **Add currency selection** | Add a `<select>` with currency codes and a small function that changes the `format()` helper accordingly (e.g., using `Intl.NumberFormat`). |
| **Persist last calculation** | Store the last inputs in `localStorage` and load them on page load. |
| **Export chart as PNG** | Use `chart.toBase64Image()` and create a download link (`<a download="markup.png">`). |
| **Responsive layout on very small screens** | Add a media query that stacks the result boxes vertically (`grid-template-columns: 1fr`). |

---  

## 4️⃣  Run It  

1. **Save** the code into a file called `markup-calculator.html`.  
2. **Open** that file in any modern browser (Chrome, Edge, Firefox, Safari).  
3. Input a **cost**, choose either **%** or **fixed amount**, click **Calculate**, and watch the numbers and the pie chart update instantly.

That’s it – a fully functional markup calculator with live chart visualisation built only with HTML, CSS, JavaScript and the free Chart.js library. Happy coding! 🚀

