```python
#!/usr/bin/env python3
"""
Simple command‑line calculator.
Supports:
    +  addition
    -  subtraction
    *  multiplication
    /  division
    ^  exponentiation
    %  modulo
Enter "quit" or "exit" to stop.
"""

def add(a, b):
    return a + b

def sub(a, b):
    return a - b

def mul(a, b):
    return a * b

def div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    return a / b

def pow_(a, b):
    return a ** b

def mod(a, b):
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    return a % b

# Mapping of operator symbol → function
OPS = {
    '+': add,
    '-': sub,
    '*': mul,
    '/': div,
    '^': pow_,
    '%': mod,
}


def parse_expression(expr: str):
    """
    Very small parser that expects: <number> <operator> <number>
    Numbers may be integer or float.
    Example: "12.5 * 4"
    """
    parts = expr.strip().split()
    if len(parts) != 3:
        raise ValueError("Expression must be in the form: <num> <op> <num>")
    left_str, op, right_str = parts
    if op not in OPS:
        raise ValueError(f"Unsupported operator: {op}")

    try:
        left = float(left_str) if '.' in left_str else int(left_str)
        right = float(right_str) if '.' in right_str else int(right_str)
    except ValueError:
        raise ValueError("Both operands must be numbers")
    return left, op, right


def main():
    print("=== Python CLI Calculator ===")
    print("Enter expressions like: 3 + 4   or   5.2 ^ 3")
    print("Supported operators: + - * / ^ %")
    print('Type "quit" or "exit" to stop.\n')

    while True:
        try:
            expr = input(">>> ").strip()
            if expr.lower() in {"quit", "exit"}:
                print("Good‑bye!")
                break
            if not expr:
                continue

            left, op, right = parse_expression(expr)
            result = OPS[op](left, right)
            # Show result without unnecessary decimal point
            if isinstance(result, float) and result.is_integer():
                result = int(result)
            print("= ", result)

        except Exception as e:
            # Friendly error messages – keep the loop alive
            print("Error:", e)


if __name__ == "__main__":
    main()
