## 📄 Código HTML + JavaScript

```html
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Logo TMDB</title>
  <style>
    #logoContainer img{
      max-width:100%;
      height:auto;
      display:block;
      margin:0 auto;
    }
  </style>
</head>
<body>
  <div id="logoContainer"></div>

  <script>
    /* --------------------------------------------------------------
       1️⃣  Obtener el “slug” (nombre con guiones bajos) de la URL
       -------------------------------------------------------------- */
    function obtenerSlugDesdeURL() {
      const url = window.location.href;
      const partes = url.split('/');
      // Busca la parte que viene después de /movies/ o /series/
      const idx = Math.max(partes.lastIndexOf('movies'), partes.lastIndexOf('series'));
      if (idx === -1 || idx === partes.length - 1) return null;
      return partes[idx + 1];            // ej.: "the_godfather_part_ii"
    }

    /* --------------------------------------------------------------
       2️⃣  Convertir el slug a un título legible (reemplaza _ por espacio)
       -------------------------------------------------------------- */
    function slugATitulo(slug) {
      if (!slug) return null;
      // También quitamos posibles parámetros "?..." o "#..."
      return decodeURIComponent(slug.replace(/_/g, ' '))
                     .replace(/\?.*$/, '')
                     .replace(/#.*$/, '');
    }

    /* --------------------------------------------------------------
       3️⃣  Llamada a TMDB: buscar el título y obtener su id + tipo
       -------------------------------------------------------------- */
    async function buscarEnTMDB(titulo) {
      const apiKey = "TU_CLAVE_API_AQUÍ";                // <─⚠️ Cambia esto
      const query = encodeURIComponent(titulo);
      const url = `https://api.themoviedb.org/3/search/multi?api_key=${apiKey}&language=es&query=${query}`;

      const resp = await fetch(url);
      if (!resp.ok) throw new Error('Error en la búsqueda de TMDB');
      const datos = await resp.json();

      if (!datos.results || datos.results.length === 0) return null;

      // Tomamos el primer resultado (el más relevante)
      const r = datos.results[0];
      return {
        id: r.id,
        media_type: r.media_type   // "movie" o "tv"
      };
    }

    /* --------------------------------------------------------------
       4️⃣  Obtener los logos de la entidad (movie / tv)
       -------------------------------------------------------------- */
    async function obtenerLogos({id, media_type}) {
      const apiKey = "TU_CLAVE_API_AQUÍ";                // <─⚠️ Cambia esto
      const url = `https://api.themoviedb.org/3/${media_type}/${id}/images?api_key=${apiKey}`;

      const resp = await fetch(url);
      if (!resp.ok) throw new Error('Error al obtener imágenes de TMDB');
      const datos = await resp.json();

      // "logos" contiene objetos con file_path, width, height, iso_639_1 …
      return datos.logos || [];
    }

    /* --------------------------------------------------------------
       5️⃣  Elegir el mejor logo
       -------------------------------------------------------------- */
    function seleccionarMejorLogo(logos) {
      if (logos.length === 0) return null;

      // Preferimos logos sin idioma (iso_639_1 === null) porque son universales.
      const sinIdioma = logos.filter(l => l.iso_639_1 === null);
      const candidatos = sinIdioma.length ? sinIdioma : logos;

      // Elegimos el de mayor anchura (más calidad)
      return candidatos.reduce((mejor, actual) =>
        (!mejor || actual.width > mejor.width) ? actual : mejor
      , null);
    }

    /* --------------------------------------------------------------
       6️⃣  Mostrar el logo (primero intenta el local, después el de TMDB)
       -------------------------------------------------------------- */
    function mostrarLogo({file_path, id}) {
      const cont = document.getElementById('logoContainer');

      // 6a️⃣  Ruta local (si la tienes guardada)
      const rutaLocal = `Multimedia/logo/${id}${file_path ? file_path.replace(/\/.*\//, '') : ''}.png`;
      // Intentamos cargar la ruta local. Si falla (404) usamos la de TMDB.
      const img = document.createElement('img');
      img.alt = `Logo de ${tituloPagina}`;
      img.onerror = () => {
        // 6b️⃣  Ruta TMDB (original = mejor calidad)
        img.src = `https://image.tmdb.org/t/p/original${file_path}`;
      };
      img.src = rutaLocal;   // Primero probamos el local

      cont.innerHTML = '';   // Limpiamos contenido previo
      cont.appendChild(img);
    }

    /* --------------------------------------------------------------
       7️⃣  Orquestación: todo en una función async auto‑ejecutada
       -------------------------------------------------------------- */
    (async () => {
      try {
        // 7a️⃣  Obtener título a partir de la URL
        const slug      = obtenerSlugDesdeURL();
        const tituloPagina = slugATitulo(slug);
        if (!tituloPagina) throw new Error('No se pudo extraer el título de la URL');

        // 7b️⃣  Buscar en TMDB (id + tipo)
        const entidad = await buscarEnTMDB(tituloPagina);
        if (!entidad) throw new Error('No se encontró la película/serie en TMDB');

        // 7c️⃣  Obtener los logos disponibles
        const logos = await obtenerLogos(entidad);
        const mejorLogo = seleccionarMejorLogo(logos);
        if (!mejorLogo) {
          console.warn('No hay logos disponibles para este título.');
          return;
        }

        // 7d️⃣  Mostrar el logo (intenta local > remoto)
        mostrarLogo({file_path: mejorLogo.file_path, id: entidad.id});
      } catch (e) {
        console.error(e);
        document.getElementById('logoContainer').innerHTML =
          `<p style="color:red;">${e.message}</p>`;
      }
    })();
  </script>
</body>
</html>
```

