// routes/order.js -------------------------------------------------
const express = require('express');
const router = express.Router();
const Order = require('../models/Order');

// --------- Fake menu (in a real app you’d store in DB) ----------
const MENU_ITEMS = [
  { id: 1, name: 'Margherita Pizza', price: 8.99 },
  { id: 2, name: 'Cheeseburger', price: 6.5 },
  { id: 3, name: 'Caesar Salad', price: 5.75 },
  { id: 4, name: 'Spaghetti Bolognese', price: 7.2 },
  { id: 5, name: 'Chicken Nuggets (6 pcs)', price: 4.99 },
];

// Middleware to protect routes
function ensureAuth(req, res, next) {
  if (req.isAuthenticated()) return next();
  res.redirect('/login');
}

// --------- Show menu / order form ----------
router.get('/menu', ensureAuth, (req, res) => {
  res.render('index', { user: req.user, menu: MENU_ITEMS });
});

// --------- Process order ----------
router.post('/order', ensureAuth, async (req, res) => {
  const { items } = req.body; // items will be JSON stringified client‑side

  let parsedItems;
  try {
    parsedItems = JSON.parse(items);
  } catch (e) {
    return res.status(400).send('Invalid order data');
  }

  // Compute total
  const total = parsedItems.reduce(
    (sum, it) => sum + it.price * it.qty,
    0
  );

  // Save order
  const newOrder = new Order({
    user: req.user.id,
    items: parsedItems,
    total,
  });

  try {
    await newOrder.save();
    res.render('success', { order: newOrder, user: req.user });
  } catch (err) {
    console.error(err);
    res.status(500).send('Failed to save order');
  }
});

module.exports = router;
