<script>
// client‑side calculation of total and building JSON payload
const qtyInputs = document.querySelectorAll('.qty-input');
const totalEl = document.getElementById('total');
const itemsJsonInput = document.getElementById('itemsJson');

function recalc() {
  let total = 0;
  const items = [];

  qtyInputs.forEach(inp => {
    const qty = parseInt(inp.value, 10);
    if (qty > 0) {
      const price = parseFloat(inp.dataset.price);
      const name = inp.dataset.name;
      const id = inp.dataset.id;

      total += price * qty;
      items.push({ id, name, price, qty });
    }
  });

  totalEl.textContent = total.toFixed(2);
  itemsJsonInput.value = JSON.stringify(items);
}

// Run on change
qtyInputs.forEach(i => i.addEventListener('input', recalc));
</script>
```

