Below is a **complete, self‑contained** example of a very simple “Snake” game that you can run in any modern browser.  
All the code lives in a single HTML file (HTML + CSS + JavaScript) so you can copy‑paste it into a file called `snake.html` and open it.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake – Simple HTML5 Canvas Game</title>
<style>
  /* ---- Basic page layout ------------------------------------------------ */
  body {
    margin: 0;
    background: #111;
    color: #fff;
    font-family: Arial, Helvetica, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    height: 100vh;
    overflow: hidden;
  }
  h1 { margin: 20px 0 5px; font-size: 2rem; }
  #score { margin-bottom: 10px; }

  /* ---- Canvas styling --------------------------------------------------- */
  canvas {
    background: #000;
    border: 2px solid #555;
  }
</style>
</head>
<body>

<h1>Snake</h1>
<div id="score">Score: 0</div>
<canvas id="gameCanvas" width="400" height="400"></canvas>

<script>
/* ========================================================================= *
 *  Simple Snake (HTML5 Canvas + vanilla JS)
 *  – grid based
 *  – arrow keys to steer
 *  – eats red food, grows, and game ends on collision
 * ========================================================================= */

/* ------- Configuration --------------------------------------------------- */
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const CELL_SIZE = 20;                     // size of one grid cell (px)
const COLS = canvas.width / CELL_SIZE;    // number of columns
const ROWS = canvas.height / CELL_SIZE;   // number of rows
const FPS = 12;                           // frames per second (speed)

let snake = [{x: 5, y: 5}];                // initial snake (head only)
let direction = {x: 1, y: 0};              // moving right initially
let nextDirection = direction;            // buffer for fast key presses
let food = null;                          // will be set in placeFood()
let score = 0;
let gameLoop = null;

/* ------- Helper functions ------------------------------------------------ */
function getRandomCell() {
  // return a random grid coordinate that is NOT occupied by the snake
  let cell;
  while (true) {
    cell = {
      x: Math.floor(Math.random() * COLS),
      y: Math.floor(Math.random() * ROWS)
    };
    // make sure we didn't generate a coordinate that collides with the snake
    if (!snake.some(segment => segment.x === cell.x && segment.y === cell.y)) {
      return cell;
    }
  }
}

function placeFood() {
  food = getRandomCell();
}

/* ------- Game logic ------------------------------------------------------ */
function update() {
  // ---- Apply buffered direction (prevents 180° turn) -------------------
  if (
    (nextDirection.x !== -direction.x) ||
    (nextDirection.y !== -direction.y)
  ) {
    direction = nextDirection;
  }

  // ---- Compute new head position ---------------------------------------
  const newHead = {
    x: (snake[0].x + direction.x + COLS) % COLS,
    y: (snake[0].y + direction.y + ROWS) % ROWS
  };

  // ---- Check self‑collision --------------------------------------------
  if (snake.some(segment => segment.x === newHead.x && segment.y === newHead.y)) {
    endGame();
    return;
  }

  // ---- Add new head ----------------------------------------------------
  snake.unshift(newHead);

  // ---- Check food -------------------------------------------------------
  if (newHead.x === food.x && newHead.y === food.y) {
    score++;
    document.getElementById('score').textContent = 'Score: ' + score;
    placeFood();               // create new food
    // (no pop – the snake grows)
  } else {
    snake.pop();               // remove tail (normal movement)
  }
}

/* ------- Rendering ------------------------------------------------------- */
function drawCell(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
}

function render() {
  // clear board
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // draw food
  drawCell(food.x, food.y, 'red');

  // draw snake – head in a brighter shade
  snake.forEach((segment, idx) => {
    const col = idx === 0 ? '#0f0' : '#08a';
    drawCell(segment.x, segment.y, col);
  });
}

/* ------- Main loop ------------------------------------------------------- */
function tick() {
  update();
  render();
}

/* ------- Game start / end ------------------------------------------------ */
function startGame() {
  snake = [{x: 5, y: 5}];
  direction = {x: 1, y: 0};
  nextDirection = direction;
  score = 0;
  document.getElementById('score').textContent = 'Score: 0';
  placeFood();
  clearInterval(gameLoop);
  gameLoop = setInterval(tick, 1000 / FPS);
}
function endGame() {
  clearInterval(gameLoop);
  alert('Game over! Your score: ' + score);
  startGame();      // automatically restart – comment this line if you don’t want it
}

/* ------- Input handling -------------------------------------------------- */
window.addEventListener('keydown', e => {
  switch (e.key) {
    case 'ArrowUp':    nextDirection = {x: 0, y: -1}; break;
    case 'ArrowDown':  nextDirection = {x: 0, y:  1}; break;
    case 'ArrowLeft':  nextDirection = {x: -1, y: 0}; break;
    case 'ArrowRight': nextDirection = {x:  1, y: 0}; break;
  }
});

/* ------- Kick‑off -------------------------------------------------------- */
startGame();
</script>

</body>
</html>
```

---

## How it works (a quick walk‑through)

| Part | What it does |
|------|--------------|
| **Canvas** (`<canvas id="gameCanvas">`) | Provides a drawing surface. We draw a grid of 20 × 20 px cells. |
| **Constants** (`CELL_SIZE`, `COLS`, `ROWS`, `FPS`) | Define the grid size and the game speed. |
| **Snake data** (`snake` array) | Holds the coordinates of each segment; the first element is the head. |
| **`direction` / `nextDirection`** | `direction` is the current movement vector; `nextDirection` buffers the newest key‑press so rapid changes are handled correctly. |
| **`placeFood()`** | Randomly positions the food on a cell that isn’t occupied by the snake. |
| **`update()`** | Moves the snake, checks for collisions with itself, handles eating food and growing the snake. |
| **`render()`** | Clears the canvas and paints the food (red) and the snake (bright head, darker body). |
| **Game loop (`setInterval`)** | Calls `tick()` ≈ 12 times per second (adjust `FPS` for faster/slower gameplay). |
| **Keyboard handling** | Arrow keys update `nextDirection`. 180° turns are prevented. |
| **`endGame()`** | Stops the loop, shows an alert with the final score, and (optionally) restarts automatically. |

---

## Customising the game

| Want to… | How to do it |
|----------|--------------|
| **Change the speed** | Edit `FPS` (e.g., `20` → faster). |
| **Make the board larger** | Adjust the `<canvas>` width/height **and** `CELL_SIZE` or keep `CELL_SIZE` and change the canvas dimensions. |
| **Add walls** (collision instead of wrap‑around) | In `update()`, replace the modulo wrap (`% COLS`/`% ROWS`) with a boundary check that calls `endGame()` if the head leaves the board. |
| **Add a “pause” key** | Add a flag `paused` and a key listener (e.g., `Space`) that toggles it; skip `update()`/`render()` while paused. |
| **Show a start screen** | Hide the canvas initially (`canvas.style.display = 'none'`) and show a button that calls `startGame()` and reveals the canvas. |
| **Improve graphics** | Replace `drawCell()` with images or gradients, or add a simple “tail‑animation” effect. |

---

## Running it

1. Copy the whole code block above into a text file called **`snake.html`**.  
2. Open the file in any modern browser (Chrome, Edge, Firefox, Safari).  
3. Use the **arrow keys** to steer the snake. Eat the red squares, avoid colliding with yourself, and try to get the highest score possible!

Enjoy tinkering! 🎮

