</dependency>
<dependency>
    <groupId>org.apache.tika</groupId>
    <artifactId>tika-core</artifactId>
    <version>2.9.0</version>
</dependency>
<dependency>
    <groupId>software.amazon.awssdk</groupId>
    <artifactId>s3</artifactId>
    <version>2.20.0</version>
</dependency>
<!-- 其他如 JWT、logback 等自行添加 -->
// ---------------------------------------------------------

// application.yml（文件大小限制）
spring:
  servlet:
    multipart:
      max-file-size: 10MB
      max-request-size: 30MB

// FileUploadController.java
@RestController
@RequestMapping("/api/v1/files")
@RequiredArgsConstructor
public class FileUploadController {

    private final FileStorageService storageService; // 负责写入 OSS/S3

    @PostMapping(value = "/upload", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<ApiResult<List<FileInfo>>> upload(
            @RequestPart("file") List<MultipartFile> files,
            @RequestPart(value = "folder", required = false) String folder,
            @RequestPart(value = "metadata", required = false) String metadataJson,
            @AuthenticationPrincipal JwtPrincipal principal) {

        // 1. 参数校验
        if (files == null || files.isEmpty()) {
            throw new BadRequestException("Missing file part");
        }

        // 2. 业务元数据（示例解析为 Map）
        Map<String, Object> metadata = Collections.emptyMap();
        if (StringUtils.hasText(metadataJson)) {
            try {
                metadata = new ObjectMapper().readValue(metadataJson, new TypeReference<>() {});
            } catch (JsonProcessingException e) {
                throw new BadRequestException("Invalid metadata JSON");
            }
        }

        // 3. 处理每个文件
        List<FileInfo> result = new ArrayList<>();
        for (MultipartFile file : files) {
            // 3.1 MIME + Magic Number 检查
            String mime = file.getContentType();
            String detectedMime;
            try (InputStream is = file.getInputStream()) {
                detectedMime = new Tika().detect(is, file.getOriginalFilename());
            }
            if (!mime.equalsIgnoreCase(detectedMime)) {
                throw new BadRequestException("MIME type mismatch");
            }

            // 3.2 存储（这里示例写入 S3）
            String objectKey = buildObjectKey(folder, file.getOriginalFilename());
            String url = storageService.upload(objectKey, file.getInputStream(), mime, file.getSize());

            // 3.3 生成返回信息
            FileInfo info = new FileInfo();
            info.setFileId(UUID.randomUUID().toString());
            info.setFilename(file.getOriginalFilename());
            info.setSize(file.getSize());
            info.setContentType(mime);
            info.setUrl(url);
            info.setFolder(folder);
            info.setUploadedAt(Instant.now());
            result.add(info);
        }

        return ResponseEntity.ok(ApiResult.success(result));
    }

    private String buildObjectKey(String folder, String filename) {
        String cleanFolder = StringUtils.hasText(folder) ? folder.replaceAll("^/|/$", "") : "";
        return StringUtils.hasText(cleanFolder) ? cleanFolder + "/" + UUID.randomUUID() + "_" + filename
                : UUID.randomUUID() + "_" + filename;
    }
}

// FileStorageService（S3 示例）
@Service
public class FileStorageService {
    private final S3Client s3;
    private final String bucket = "my-app-files";

    public FileStorageService() {
        this.s3 = S3Client.builder()
                .region(Region.US_EAST_1) // 根据实际情况
                .credentialsProvider(EnvironmentVariableCredentialsProvider.create())
                .build();
    }

    public String upload(String key, InputStream data, String contentType, long size) {
        PutObjectRequest req = PutObjectRequest.builder()
                .bucket(bucket)
                .key(key)
                .contentType(contentType)
                .contentLength(size)
                .acl(ObjectCannedACL.PUBLIC_READ) // 可视业务需求调整
                .build();
        s3.putObject(req, RequestBody.fromInputStream(data, size));
        return s3.utilities().getUrl(GetUrlRequest.builder().bucket(bucket).key(key).build()).toString();
    }
}

// 统一返回包装
@Getter @Setter @AllArgsConstructor @NoArgsConstructor
public class ApiResult<T> {
    private int code;
    private String message;
    private T data;

    public static <T> ApiResult<T> success(T data) {
        return new ApiResult<>(0, "Upload success", data);
    }

    public static <T> ApiResult<T> failure(int code, String msg) {
        return new ApiResult<>(code, msg, null);
    }
}

// 自定义异常处理器 (略)...
```

> **关键点**：  
> - 使用 `@RequestPart` 读取 `multipart/form-data` 中的多个 `file`。  
> - `Tika` 检测真实 MIME，防止伪造。  
> - `S3Client` 直接流式上传，`InputStream` 不会被完整读入内存。  
> - `ApiResult` 为统一的响应体，兼容前端错误码约定。

