### 6.2 Express（Node.js） + Multer + AWS SDK

```javascript
// package.json 关键依赖
{
  "dependencies": {
    "express": "^4.18",
    "multer": "^1.4",
    "aws-sdk": "^2.1410",   // 或使用 @aws-sdk/client-s3（v3）
    "uuid": "^9.0",
    "dotenv": "^16.0"
  }
}

// server.js
require('dotenv').config();
const express = require('express');
const multer = require('multer');
const { S3 } = require('aws-sdk');
const { v4: uuidv4 } = require('uuid');
const mime = require('mime-types');

const app = express();
const upload = multer({
  limits: { fileSize: 10 * 1024 * 1024 }, // 10 MB 单文件上限
  fileFilter: (req, file, cb) => {
    // 简单白名单
    const allowed = ['image/jpeg', 'image/png', 'application/pdf', 'text/plain'];
    if (allowed.includes(file.mimetype)) cb(null, true);
    else cb(new Error('Unsupported file type'), false);
  }
});

const s3 = new S3({
  accessKeyId: process.env.AWS_ACCESS_ID,
  secretAccessKey: process.env.AWS_SECRET,
  region: process.env.AWS_REGION,
});

app.post('/api/v1/files/upload',
  // 这里用 file: 'multiple' 允许一次上传多个文件（数组）
  upload.array('file', 10), // 最多 10 个文件
  async (req, res) => {
    try {
      if (!req.files || req.files.length === 0) {
        return res.status(400).json({ code: -1001, message: 'Missing file' });
      }
      const folder = req.body.folder?.replace(/^\/|\/$/g, '') || '';
      const metadata = req.body.metadata ? JSON.parse(req.body.metadata) : {};

      const promises = req.files.map(async (file) => {
        const ext = mime.extension(file.mimetype) || '';
        const key = folder
          ? `${folder}/${uuidv4()}_${file.originalname}`
          : `${uuidv4()}_${file.originalname}`;

        // 上传到 S3
        await s3.putObject({
          Bucket: process.env.AWS_BUCKET,
          Key: key,
          Body: file.buffer,
          ContentType: file.mimetype,
          ACL: 'public-read', // 根据业务需求决定
        }).promise();

        const url = `https://${process.env.AWS_BUCKET}.s3.${process.env.AWS_REGION}.amazonaws.com/${key}`;
        return {
          fileId: uuidv4(),
          filename: file.originalname,
          size: file.size,
          contentType: file.mimetype,
          url,
          folder,
          uploadedAt: new Date().toISOString(),
        };
      });

      const result = await Promise.all(promises);
      res.json({ code: 0, message: 'Upload success', data: result });
    } catch (err) {
      console.error(err);
      if (err.message === 'File too large') {
        return res.status(413).json({ code: -1003, message: 'File too large' });
      }
      if (err.message === 'Unsupported file type') {
        return res.status(415).json({ code: -1004, message: err.message });
      }
      res.status(500).json({ code: -2000, message: 'Internal server error' });
    }
  });

app.listen(8080, () => console.log('Server started at http://localhost:8080'));
```

> **说明**  
> - `multer` 将文件暂存到内存（`file.buffer`），适用于 ≤ 10 MB 的场景；大文件建议使用 `multer.diskStorage` + 流式上传到 S3。  
> - `fileFilter` 实现了最基本的 MIME 白名单，生产环境可加 **magic number** 检测。  
> - `metadata` 通过 `req.body.metadata` 传递，可用于业务日志、标签等。

