### 6.3 Flask（Python 3.11）

```python
# requirements.txt
Flask==3.0.0
python-multipart==0.0.9   # werkzeug 已内置 multipart 解析，可直接用
boto3==1.34.0
python-dotenv==1.0.0
python-magic==0.4.27

# app.py
import os, uuid, json, datetime
from flask import Flask, request, jsonify
import boto3
import magic
from werkzeug.utils import secure_filename
from dotenv import load_dotenv

load_dotenv()
app = Flask(__name__)

# 配置
MAX_CONTENT_LENGTH = 30 * 1024 * 1024   # 整体请求体 ≤ 30 MB
ALLOWED_MIME = {'image/jpeg', 'image/png', 'application/pdf', 'text/plain'}

# S3 客户端
s3 = boto3.client(
    's3',
    aws_access_key_id=os.getenv('AWS_ACCESS_ID'),
    aws_secret_access_key=os.getenv('AWS_SECRET'),
    region_name=os.getenv('AWS_REGION')
)
BUCKET = os.getenv('AWS_BUCKET')

def allowed_file(mime_type):
    return mime_type in ALLOWED_MIME

@app.route('/api/v1/files/upload', methods=['POST'])
def upload():
    # 1. 鉴权（示例仅检查 Header）
    auth = request.headers.get('Authorization')
    if not auth or not auth.startswith('Bearer '):
        return jsonify(code=-1002, message='Unauthorized'), 401

    # 2. 必要字段检查
    if 'file' not in request.files:
        return jsonify(code=-1001, message='Missing file part'), 400

    files = request.files.getlist('file')
    folder = request.form.get('folder', '').strip('/')
    metadata_raw = request.form.get('metadata')
    try:
        metadata = json.loads(metadata_raw) if metadata_raw else {}
    except json.JSONDecodeError:
        return jsonify(code=-1001, message='Invalid metadata JSON'), 400

    result = []
    for f in files:
        # 3. MIME + magic 检测
        mime_type = f.mimetype
        # 读取前 2048 字节进行 magic 识别
        header = f.stream.read(2048)
        f.stream.seek(0)
        detected = magic.from_buffer(header, mime=True)
        if mime_type != detected:
            return jsonify(code=-1004, message='MIME mismatch'), 415
        if not allowed_file(mime_type):
            return jsonify(code=-1004, message='Unsupported Media Type'), 415

        # 4. 生成唯一对象键
        filename = secure_filename(f.filename)
        obj_key = f"{folder}/{uuid.uuid4()}_{filename}" if folder else f"{uuid.uuid4()}_{filename}"

        # 5. 上传至 S3（使用流式上传，防止占用内存）
        try:
            s3.upload_fileobj(
                Fileobj=f.stream,
                Bucket=BUCKET,
                Key=obj_key,
                ExtraArgs={'ContentType': mime_type, 'ACL': 'public-read'}
            )
        except Exception as e:
            app.logger.error(f"S3 upload error: {e}")
            return jsonify(code=-2000, message='S3 upload failed'), 500

        url = f"https://{BUCKET}.s3.{os.getenv('AWS_REGION')}.amazonaws.com/{obj_key}"
        result.append({
            "fileId": str(uuid.uuid4()),
            "filename": filename,
            "size": f.content_length,
            "contentType": mime_type,
            "url": url,
            "folder": folder,
            "uploadedAt": datetime.datetime.utcnow().isoformat() + 'Z',
        })

    return jsonify(code=0, message='Upload success', data=result)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

> **要点**  
> - `MAX_CONTENT_LENGTH` 自动让 Flask 返回 `413 Request Entity Too Large`。  
> - 使用 `python-magic` 检查文件头，防止 MIME 伪造。  
> - `secure_filename` 去除路径遍历字符。  
> - 直接把文件流 `f.stream` 交给 `boto3.upload_fileobj`，无需临时写磁盘。

