                setTimeout(showTarget, 500);
            }, 1000);
        }

        // إيقاف اللعبة وتنظيف المؤقتات
        function stopGame() {
            clearInterval(gameInterval);
            clearTimeout(hideTimeout);
            target.style.display = 'none';
            startBtn.disabled = false;
        }

        // ---------- أحداث اللعبة ----------
        // النقر على الدائرة
        target.addEventListener('click', () => {
            score++;
            scoreEl.textContent = score;
            // إخفاء الفورية وإظهار جديدة فورًا
            target.style.display = 'none';
            clearTimeout(hideTimeout);
            setTimeout(showTarget, 200);
        });

        // زر البدء
        startBtn.addEventListener('click', () => {
            // إعداد القيم الأولية
            score = 0;
            timeLeft = 30;
            scoreEl.textContent = score;
            timeEl.textContent = timeLeft;
            startBtn.disabled = true;

            // إظهار الدائرة للمرة الأولى
            showTarget();

            // عدّ تنازلي للوقت
            gameInterval = setInterval(() => {
                timeLeft--;
                timeEl.textContent = timeLeft;
                if (timeLeft <= 0) {
                    stopGame();
                    alert(`انتهى الوقت! نتيجتك هي ${score} نقطة`);
                }
            }, 1000);
        });

        // ضبط أحجام النافذة لتجنب خروج الدائرة خارج الشاشة
        window.addEventListener('resize', () => {
            // إذا تغير حجم النافذة، نعيد حساب الموقع الحالي
            if (target.style.display === 'block') {
                const { x, y } = randomPosition();
                target.style.left = `${x}px`;
                target.style.top = `${y}px`;
            }
        });
    </script>
</body>
</html>
```

