## 4️⃣ `script.js`

```js
/* --------------------------------------------------------------
   Busca Inteligente – JavaScript
   Utiliza a API pública da Wikipedia (wikipedia.org/w/api.php)
   -------------------------------------------------------------- */

const form = document.getElementById('search-form');
const input = document.getElementById('search-input');
const resultsContainer = document.getElementById('results');

/* Função que cria o card de resultado */
function createResultCard(title, snippet, pageUrl) {
  const card = document.createElement('div');
  card.className = 'result-card';

  const h2 = document.createElement('h2');
  h2.textContent = title;

  const p = document.createElement('p');
  // A Wikipedia já devolve HTML limpo (com <span class="searchmatch">)
  p.innerHTML = snippet + '...';

  const a = document.createElement('a');
  a.href = pageUrl;
  a.target = '_blank';
  a.rel = 'noopener';
  a.textContent = 'Leia mais →';

  card.appendChild(h2);
  card.appendChild(p);
  card.appendChild(a);
  return card;
}

/* Função que realiza a busca */
async function performSearch(query) {
  // Limpa resultados antigos
  resultsContainer.innerHTML = '<p>Carregando…</p>';

  const endpoint = 'https://en.wikipedia.org/w/api.php';
  const params = new URLSearchParams({
    action: 'query',
    format: 'json',
    origin: '*',               // necessário para CORS
    generator: 'search',
    gsrsearch: query,
    gsrlimit: 10,
    prop: 'extracts|info',
    exintro: 1,
    explaintext: 0,            // queremos HTML (negritos, etc.)
    exsentences: 2,
    inprop: 'url'
  });

  try {
    const response = await fetch(`${endpoint}?${params}`);
    const data = await response.json();

    // Verificar se há resultados
    if (!data.query) {
      resultsContainer.innerHTML = '<p>Nenhum resultado encontrado.</p>';
      return;
    }

    const pages = Object.values(data.query.pages);
    resultsContainer.innerHTML = ''; // limpa texto "Carregando…"

    pages.forEach(page => {
      const title   = page.title;
      const snippet = page.extract; // já contém HTML
      const url     = page.fullurl;

      const card = createResultCard(title, snippet, url);
      resultsContainer.appendChild(card);
    });
  } catch (err) {
    console.error('Erro na busca:', err);
    resultsContainer.innerHTML = '<p>Ocorreu um erro ao buscar. Tente novamente.</p>';
  }
}

/* Evento de submit da barra */
form.addEventListener('submit', e => {
  e.preventDefault();               // impede recarregamento da página
  const query = input.value.trim();
  if (query) {
    performSearch(query);
  }
});

/* Opcional: busca ao digitar (debounce) */
let debounceTimer;
input.addEventListener('input', () => {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => {
    const query = input.value.trim();
    if (query) performSearch(query);
  }, 600); // 600 ms de espera
});
```

