## 4. TypeScript‑код (`src/index.ts`)

```ts
/*======================================================================
  RxJS SPA – Показать/Удалить данные
======================================================================*/

import { fromEvent, Observable } from 'rxjs';
import { ajax } from 'rxjs/ajax';
import { map, switchMap, tap, catchError } from 'rxjs/operators';

// ---------- ВЫБОР ЭЛЕМЕНТОВ -----------------------------------------
const showBtn   = document.getElementById('showBtn')   as HTMLButtonElement;
const deleteBtn = document.getElementById('deleteBtn') as HTMLButtonElement;
const outputDiv = document.getElementById('output')   as HTMLDivElement;

// ---------- ОПИСАНИЕ ТИПОВ ДАННЫХ ------------------------------------
interface Person {
  id:   number;
  name: string;
  age:  number;
}

// ---------- ПОЛУЧЕНИЕ JSON как Observable ---------------------------
const DATA_URL = './data.json';               // относительно index.html

function fetchData(): Observable<Person[]> {
  // ajax.getJSON автоматически парсит JSON в объект
  return ajax.getJSON<Person[]>(DATA_URL).pipe(
    // если захотим отлавливать ошибки, делаем catchError
    catchError(err => {
      console.error('Ошибка при загрузке JSON', err);
      // возвращаем пустой массив, чтобы цепочка не прервалась
      return [] as unknown as Observable<Person[]>;
    })
  );
}

// ---------- ФУНКЦИИ ОТОБРАЖЕНИЯ ------------------------------------
/**
 * Добавляет строки в #output из массива объектов.
 * Каждая строка – отдельный <div class="row">.
 */
function renderRows(rows: Person[]): void {
  rows.forEach(row => {
    const el = document.createElement('div');
    el.className = 'row';
    // Формат отображения – произвольный
    el.textContent = `ID: ${row.id}, Имя: ${row.name}, Возраст: ${row.age}`;
    outputDiv.appendChild(el);
  });
}

/**
 * Удаляет последний элемент из #output (если он есть).
 */
function deleteLastRow(): void {
  const rows = outputDiv.getElementsByClassName('row');
  if (rows.length === 0) return;
  const last = rows[rows.length - 1];
  outputDiv.removeChild(last);
}

// ---------- ОПРАВЕДЛЕНИЕ СОБЫТИЙ ------------------------------------
/**
 * 1) Щелчок по «Показать данные»
 *    → скачиваем JSON (ajax.getJSON) → отображаем полученные строки.
 */
fromEvent(showBtn, 'click')
  .pipe(
    // При каждом новом клике делаем запрос,
    // а если предыдущий запрос ещё не завершился –
    // переключаемся на новый (switchMap)
    switchMap(() => fetchData()),
    // Преобразуем массив в поток отдельных элементов (flatten)
    // но нам удобно сразу передать массив в renderRows,
    // поэтому используем map → массив → side‑effect (tap)
    tap(data => {
      // Если полученные данные – массив, просто отрисовываем
      // (можно добавить проверку: Array.isArray(data))
      renderRows(data);
    })
    // Далее подписка без дальнейшего обработчика,
    // т.к. действие уже выполнено в tap.
  )
  .subscribe({
    error: err => console.error('Ошибка в цепочке showBtn:', err)
  });

/**
 * 2) Щелчок по «Удалить» → удалить последнюю строку.
 */
fromEvent(deleteBtn, 'click')
  .pipe(
    tap(() => deleteLastRow())
  )
  .subscribe();

/*======================================================================
  Всё! При запуске браузер покажет две кнопки, а при клике
  «Показать данные» загрузит JSON, отобразит его, а «Удалить» будет
  убирать последнюю добавленную строку.
======================================================================*/
```

### Краткое объяснение кода  

| Шаг | Что делаем | RxJS‑оператор |
|-----|------------|----------------|
| `fromEvent(showBtn, 'click')` | Создаём Observable, испускающий событие **click** | `fromEvent` |
| `switchMap(() => fetchData())` | При каждом клике переходим к новому HTTP‑запросу; если пред. запрос ещё не завершён – отменяем его | `switchMap` |
| `fetchData()` | Возвращает `ajax.getJSON` – Observable, испускающий массив `Person[]` | `ajax.getJSON` |
| `tap(data => renderRows(data))` | Сторонний эффект – рисуем полученные строки (без изменения потока) | `tap` |
| `fromEvent(deleteBtn, 'click')` → `tap(deleteLastRow)` | При клике просто вызываем функцию, удаляющую последний элемент | `tap` |

