<script src="https://unpkg.com/rxjs@7/dist/bundles/rxjs.ajax.umd.min.js"></script>
```

2. Создайте `public/app.js` (не TypeScript) со следующим содержимым (практически тот же код, но без типов и импортов):

```js
// Доступ к глобальному объекту RxJS
const { fromEvent } = rxjs;
const { ajax } = rxjs.ajax;
const { switchMap, tap, catchError } = rxjs.operators;

// Элементы UI
const showBtn   = document.getElementById('showBtn');
const deleteBtn = document.getElementById('deleteBtn');
const outputDiv = document.getElementById('output');

const DATA_URL = './data.json';

function fetchData() {
  return ajax.getJSON(DATA_URL).pipe(
    catchError(err => {
      console.error('Ошибка загрузки JSON', err);
      return rxjs.of([]);      // пустой массив вместо ошибки
    })
  );
}

function renderRows(rows) {
  rows.forEach(r => {
    const div = document.createElement('div');
    div.className = 'row';
    div.textContent = `ID: ${r.id}, Имя: ${r.name}, Возраст: ${r.age}`;
    outputDiv.appendChild(div);
  });
}

function deleteLastRow() {
  const rows = outputDiv.getElementsByClassName('row');
  if (rows.length) {
    outputDiv.removeChild(rows[rows.length - 1]);
  }
}

/* ------------------- Подписки --------------------- */
fromEvent(showBtn, 'click')
  .pipe(
    switchMap(() => fetchData()),
    tap(data => renderRows(data))
  )
  .subscribe();

fromEvent(deleteBtn, 'click')
  .pipe(tap(deleteLastRow))
  .subscribe();
```

3. В `index.html` замените строку `<script src="bundle.js"></script>` на `<script src="app.js"></script>`.

Это полностью избавит от сборки – всё будет работать «из коробки», используя только CDN‑подключения.

