    { priority: false, name: 'アマテラス',  description: '(Amaterasu, Shinto)',    color: '#E60026' },
];

/* --------------------------------------------------------------
   2️⃣  Helper – deep‑copy & sort by “timeline” (priority first)
   -------------------------------------------------------------- */
function getSortedCon(arr) {
    // copy so we never mutate the original `con`
    const copy = arr.slice();

    // priority:true → earlier → should appear on top
    // we keep the original order for items that share the same priority
    copy.sort((a, b) => {
        if (a.priority === b.priority) return 0;
        return a.priority ? -1 : 1;   // true before false
    });

    return copy;
}

/* --------------------------------------------------------------
   3️⃣  Build the circular UI
   -------------------------------------------------------------- */
function createCon() {
    const circle   = document.getElementById('circle');
    const sorted   = getSortedCon(con);
    const len      = sorted.length;
    const angleInc = 360 / len;

    // wipe any previous children (useful on resize)
    circle.innerHTML = '';

    sorted.forEach((item, i) => {
        const span = document.createElement('span');

        // ---- content ----
        span.innerHTML = `
