### 4.2 关键代码

#### 1. `TenantContext`

```java
package com.example.multitenantredis.util;

public final class TenantContext {
    private static final ThreadLocal<String> CURRENT = new ThreadLocal<>();

    public static void set(String tenantId) { CURRENT.set(tenantId); }

    public static String get() { return CURRENT.get(); }

    public static void clear() { CURRENT.remove(); }
}
```

#### 2. `TenantFilter`

```java
package com.example.multitenantredis.filter;

import com.example.multitenantredis.util.TenantContext;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException;

@Component
public class TenantFilter extends OncePerRequestFilter {

    private static final String HEADER = "X-Tenant-ID";

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {
        try {
            String tenantId = request.getHeader(HEADER);
            if (tenantId == null || tenantId.isBlank()) {
                tenantId = "public"; // fallback
            }
            TenantContext.set(tenantId);
            filterChain.doFilter(request, response);
        } finally {
            TenantContext.clear();
        }
    }
}
```

#### 3. `RedisConfig`（键前缀序列化）

```java
package com.example.multitenantredis.config;

import com.example.multitenantredis.util.TenantContext;
import org.springframework.boot.autoconfigure.data.redis.RedisProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.*;
import org.springframework.data.redis.connection.lettuce.*;
import org.springframework.data.redis.core.*;
import org.springframework.data.redis.serializer.*;

import java.time.Duration;

@Configuration
public class RedisConfig {

    /** 采用 Lettuce 连接 */
    @Bean
    public RedisConnectionFactory redisConnectionFactory(RedisProperties props) {
        LettuceClientConfiguration clientConfig = LettuceClientConfiguration.builder()
                .commandTimeout(Duration.ofMillis(props.getTimeout()))
                .build();

        RedisStandaloneConfiguration serverConfig = new RedisStandaloneConfiguration();
        serverConfig.setHostName(props.getHost());
        serverConfig.setPort(props.getPort());
        serverConfig.setPassword(RedisPassword.of(props.getPassword()));
        return new LettuceConnectionFactory(serverConfig, clientConfig);
    }

    /** 租户感知的 Key 序列化器 */
    static class TenantAwareStringKeySerializer implements RedisSerializer<String> {

        private final RedisSerializer<String> delegate = RedisSerializer.string();

        @Override
        public byte[] serialize(String key) throws SerializationException {
            if (key == null) return new byte[0];
            String tenantId = TenantContext.get();
            String full = (tenantId != null ? tenantId + ":" : "") + key;
            return delegate.serialize(full);
        }

        @Override
        public String deserialize(byte[] bytes) throws SerializationException {
            String full = delegate.deserialize(bytes);
            if (full == null) return null;
            String tenantId = TenantContext.get();
            if (tenantId != null && full.startsWith(tenantId + ":")) {
                return full.substring(tenantId.length() + 1);
            }
            return full;
        }
    }

    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory cf) {
        RedisTemplate<String, Object> tmpl = new RedisTemplate<>();
        tmpl.setConnectionFactory(cf);

        // Key 前缀化
        tmpl.setKeySerializer(new TenantAwareStringKeySerializer());
        tmpl.setHashKeySerializer(new TenantAwareStringKeySerializer());

        // Value 使用 JSON（可自行改为 JdkSerialization、Kryo 等）
        Jackson2JsonRedisSerializer<Object> valueSer =
                new Jackson2JsonRedisSerializer<>(Object.class);
        valueSer.setObjectMapper(new com.fasterxml.jackson.databind.ObjectMapper()
                .configure(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false));
        tmpl.setValueSerializer(valueSer);
        tmpl.setHashValueSerializer(valueSer);
        tmpl.afterPropertiesSet();
        return tmpl;
    }
}
```

#### 4. `CacheConfig`（租户感知 CacheResolver）

```java
package com.example.multitenantredis.config;

import com.example.multitenantredis.util.TenantContext;
import org.springframework.cache.Cache;
import org.springframework.cache.CacheManager;
import org.springframework.cache.interceptor.*;
import org.springframework.context.annotation.*;
import org.springframework.data.redis.cache.*;
import org.springframework.data.redis.connection.RedisConnectionFactory;

import java.time.Duration;
import java.util.*;
import java.util.stream.Collectors;

@Configuration
@EnableCaching
public class CacheConfig {

    @Bean
    public CacheManager cacheManager(RedisConnectionFactory cf) {
        RedisCacheConfiguration defaultCfg = RedisCacheConfiguration.defaultCacheConfig()
                .entryTtl(Duration.ofHours(1))
                .disableCachingNullValues()
                .serializeValuesWith(RedisSerializationContext.SerializationPair.fromSerializer(
                        new GenericJackson2JsonRedisSerializer()));
        return RedisCacheManager.builder(cf)
                .cacheDefaults(defaultCfg)
                .transactionAware()
                .build();
    }

    @Bean
    public CacheResolver cacheResolver(CacheManager manager) {
        return new TenantCacheResolver(manager);
    }

    static class TenantCacheResolver implements CacheResolver {
        private final CacheManager manager;
        TenantCacheResolver(CacheManager manager) { this.manager = manager; }

        @Override
        public Collection<? extends Cache> resolveCaches(CacheOperationInvocationContext<?> context) {
            String tenantId = TenantContext.get();
            Set<String> baseNames = context.getOperation().getCacheNames();
            return baseNames.stream()
                    .map(name -> manager.getCache(tenantId + ":" + name))
                    .collect(Collectors.toList());
        }
    }
}
```

