```java
package com.example.multitenantredis.service;

import com.example.multitenantredis.util.TenantContext;
import lombok.*;
import org.springframework.cache.annotation.*;
import org.springframework.data.redis.core.*;
import org.springframework.stereotype.Service;

import java.util.*;

@Service
@RequiredArgsConstructor
public class UserService {

    private final RedisTemplate<String, Object> redisTemplate;

    /** 通过 @Cacheable 演示 */
    @Cacheable(cacheNames = "user", key = "#id")
    public User getUser(Long id) {
        // 实际业务：查询 DB
        System.out.println(">>> DB 查询 user " + id + " for tenant " + TenantContext.get());
        return new User(id, "User-" + id);
    }

    /** 手动使用 RedisTemplate，展示键前缀已自动拼好 */
    public void putSession(String sessionId, Map<String, Object> data, long seconds) {
        redisTemplate.opsForValue().set("session:" + sessionId, data, seconds);
    }

    public Map<String, Object> getSession(String sessionId) {
        Object o = redisTemplate.opsForValue().get("session:" + sessionId);
        @SuppressWarnings("unchecked")
        Map<String, Object> map = (Map<String, Object>) o;
        return map;
    }

    @Getter @AllArgsConstructor @ToString
    public static class User {
        private Long id;
        private String name;
    }
}
