function animate(marker, coords, index, markerName) {
  // Guard – no next point => end of race
  if (index >= coords.length - 1) return;

  const distance = marker.getLatLng().distanceTo(coords[index + 1]);
  const minSpeed = 160;                      // metres per second (roughly)
  const minDuration = (distance / minSpeed) * 1000; // ms
  const maxDuration = 2000;                  // upper bound for randomness
  const duration = Math.random() * (maxDuration - minDuration) + minDuration;
  const startTime = Date.now();

  function easeInOut(t) {
    return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
  }

  function step() {
    const elapsed = Date.now() - startTime;
    const progress = elapsed / duration;
    const eased = easeInOut(Math.min(progress, 1)); // clamp to 1

    const cur = coords[index];
    const nxt = coords[index + 1];
    const lat = cur[0] + (nxt[0] - cur[0]) * eased;
    const lng = cur[1] + (nxt[1] - cur[1]) * eased;

    marker.setLatLng([lat, lng]);

    if (progress < 1) {
      requestAnimationFrame(step);
