## 3️⃣ Schemas & Models

Create a folder `models/` and add the following files.

### 3.1️⃣ `User.js`

```js
// models/User.js
const { Schema, model } = require('../db');

const UserSchema = new Schema(
  {
    // -----------------------------------------------------------------
    // Core identity – you may replace with your own auth provider ID
    // -----------------------------------------------------------------
    email: {
      type: String,
      required: true,
      unique: true,
      lowercase: true,
      trim: true,
    },
    passwordHash: { type: String, required: true },

    // -----------------------------------------------------------------
    // Profile (public) fields
    // -----------------------------------------------------------------
    username: {
      type: String,
      required: true,
      unique: true,
      trim: true,
      minlength: 3,
      maxlength: 30,
    },
    avatarUrl: { type: String }, // optional
    status: {
      type: String,
      enum: ['online', 'offline', 'away', 'do_not_disturb'],
      default: 'offline',
    },

    // -----------------------------------------------------------------
    // Optional: friend list / blocked users
    // -----------------------------------------------------------------
    contacts: [{ type: Schema.Types.ObjectId, ref: 'User' }],
    blocked: [{ type: Schema.Types.ObjectId, ref: 'User' }],
  },
  {
    timestamps: true, // createdAt, updatedAt
    toJSON: { virtuals: true },
    toObject: { virtuals: true },
  },
);

// Indexes for fast lookup
UserSchema.index({ email: 1 });
UserSchema.index({ username: 1 });

module.exports = model('User', UserSchema);
```

### 3.2️⃣ `Chat.js`

```js
// models/Chat.js
const { Schema, model } = require('../db');

const ChatSchema = new Schema(
  {
    // -----------------------------------------------------------------
    // Type of conversation – 'direct' for 1‑to‑1, 'group' for many‑to‑many
    // -----------------------------------------------------------------
    type: {
      type: String,
      enum: ['direct', 'group'],
      required: true,
      default: 'direct',
    },

    // -----------------------------------------------------------------
    // Group‑specific fields
    // -----------------------------------------------------------------
    name: { type: String, trim: true },           // optional for groups
    avatarUrl: { type: String },                  // optional group picture
    createdBy: { type: Schema.Types.ObjectId, ref: 'User', required: true },

    // -----------------------------------------------------------------
    // Participants – each entry holds extra per‑user data (e.g. role)
    // -----------------------------------------------------------------
    participants: [
      {
        user: { type: Schema.Types.ObjectId, ref: 'User', required: true },
        // role can be 'owner', 'admin', 'member' – useful for groups
        role: {
          type: String,
          enum: ['owner', 'admin', 'member'],
          default: 'member',
        },
        // when the user last read the chat – used for unread counters
        lastReadAt: { type: Date, default: null },
        // optional muted flag / mute expiry timestamp
        mutedUntil: { type: Date, default: null },
      },
    ],

    // -----------------------------------------------------------------
    // Cached data to avoid heavy aggregation on every request
    // -----------------------------------------------------------------
    lastMessage: {
      type: Schema.Types.ObjectId,
      ref: 'Message',
    },
    lastMessageAt: { type: Date },

    // -----------------------------------------------------------------
    // Soft‑delete flag (helps with GDPR “right to be forgotten”)
    // -----------------------------------------------------------------
    isDeleted: { type: Boolean, default: false },
  },
  {
    timestamps: true,
    toJSON: { virtuals: true },
    toObject: { virtuals: true },
  },
);

/**
 * Indexes for the most frequent queries:
 * 1️⃣ Find a chat by its participants (direct chat)
 * 2️⃣ Load a user’s chats (sorted by activity)
 */
ChatSchema.index(
  {
    type: 1,
    'participants.user': 1,
  },
  { unique: false }
);

// Helper virtual: list of participant IDs only
ChatSchema.virtual('participantIds').get(function () {
  return this.participants.map(p => p.user);
});

module.exports = model('Chat', ChatSchema);
```

### 3.3️⃣ `Message.js`

```js
// models/Message.js
const { Schema, model } = require('../db');

const MessageSchema = new Schema(
  {
    chat: { type: Schema.Types.ObjectId, ref: 'Chat', required: true },

    // -------------------------------------------------------------
    // The author of the message
    // -------------------------------------------------------------
    sender: { type: Schema.Types.ObjectId, ref: 'User', required: true },

    // -------------------------------------------------------------
    // Content – support text, media, and a generic JSON payload
    // -------------------------------------------------------------
    type: {
      type: String,
      enum: ['text', 'image', 'video', 'audio', 'file', 'system'],
      default: 'text',
    },

    // plain text for type === 'text' (max 4 KB, can be increased)
    text: { type: String, maxlength: 4096 },

    // for media/files we store a JSON blob with URL & meta‑info
    payload: {
      url: { type: String }, // S3, Cloudinary, etc.
      name: { type: String },
      size: { type: Number }, // bytes
      mime: { type: String },
      // any other custom fields you need
    },

    // -------------------------------------------------------------
    // Reactions – each entry is a map of emoji -> users who reacted
    // -------------------------------------------------------------
    reactions: {
      type: Map,
      of: [{ type: Schema.Types.ObjectId, ref: 'User' }],
      default: {},
    },

    // -------------------------------------------------------------
    // System messages (e.g. "user X added to the group")
    // -------------------------------------------------------------
    systemInfo: {
      action: { type: String }, // 'add_user', 'remove_user', 'name_change', …
      data: { type: Schema.Types.Mixed },
    },

    // -------------------------------------------------------------
    // Read receipts – optional – if you want per‑message per‑user flags
    // -------------------------------------------------------------
    readBy: [{ type: Schema.Types.ObjectId, ref: 'User' }],

    // -------------------------------------------------------------
    // Soft delete – keep for audit while hiding from UI
    // -------------------------------------------------------------
    isDeleted: { type: Boolean, default: false },
  },
  {
    timestamps: true, // createdAt = when message was sent
    toJSON: { virtuals: true },
    toObject: { virtuals: true },
  },
);

/**
 * Indexes for fast fetching:
 * • All messages of a chat (sorted by createdAt desc)
 * • Unread messages for a single user
 */
MessageSchema.index({ chat: 1, createdAt: -1 });
MessageSchema.index({ chat: 1, isDeleted: 1, createdAt: -1 });

module.exports = model('Message', MessageSchema);
```

### 3.4️⃣ (Optional) `MessageRead.js`

If you **don’t want to store `readBy` array on each message** (which can become large), you can use a *separate* collection that stores the latest read timestamp per user per chat. This is what most modern chat services do.

```js
// models/MessageRead.js
const { Schema, model } = require('../db');

/**
 * One document per (user, chat) pair.
 * `lastReadAt` is the timestamp of the latest message the user has seen.
 */
const MessageReadSchema = new Schema(
  {
    user: { type: Schema.Types.ObjectId, ref: 'User', required: true },
    chat: { type: Schema.Types.ObjectId, ref: 'Chat', required: true },

    // The `createdAt` of the last message the user opened.
    lastReadAt: { type: Date, required: true },

    // Optional: keep the id of that last message (helps with UI "new")
    lastReadMessageId: { type: Schema.Types.ObjectId, ref: 'Message' },
  },
  { timestamps: true },
);

// Ensure uniqueness per user‑chat
MessageReadSchema.index({ user: 1, chat: 1 }, { unique: true });

module.exports = model('MessageRead', MessageReadSchema);
```

