## 4️⃣ CRUD & Helper Functions (example usage)

Below are a few common operations that show **how you populate, paginate, and keep counters up‑to‑date**.

```js
// services/chatService.js
const Chat = require('../models/Chat');
const Message = require('../models/Message');
const User = require('../models/User');
const MessageRead = require('../models/MessageRead');

/**
 * 1️⃣ Find or create a direct (1‑to‑1) chat between two users.
 */
async function getOrCreateDirectChat(userIdA, userIdB) {
  // Order ids to guarantee a deterministic query
  const [userA, userB] = [userIdA, userIdB].sort();

  // Try to find an existing direct chat
  let chat = await Chat.findOne({
    type: 'direct',
    'participants.user': { $all: [userA, userB] },
  });

  if (!chat) {
    chat = await Chat.create({
      type: 'direct',
      participants: [
        { user: userA, role: 'member' },
        { user: userB, role: 'member' },
      ],
      createdBy: userA,
    });
  }

  return chat;
}

/**
 * 2️⃣ Send a new message.
 */
async function sendMessage({ chatId, senderId, type = 'text', text, payload }) {
  const msg = await Message.create({
    chat: chatId,
    sender: senderId,
    type,
    text,
    payload,
  });

  // Update chat's lastMessage fields (atomic)
  await Chat.findByIdAndUpdate(chatId, {
    lastMessage: msg._id,
    lastMessageAt: msg.createdAt,
  });

  // Optionally push a notification to other participants here.

  return msg;
}

/**
 * 3️⃣ Fetch a paginated slice of messages for a chat (newest first).
 *    `page` starts at 1, `limit` up to 100 is recommended.
 */
async function getChatMessages(chatId, { page = 1, limit = 30 } = {}) {
  const skip = (page - 1) * limit;
  const messages = await Message.find({ chat: chatId, isDeleted: false })
    .sort({ createdAt: -1 })
    .skip(skip)
    .limit(limit)
    .populate('sender', 'username avatarUrl')
    .lean(); // plain JS objects, faster for read‑only

  // Reverse order for UI (oldest → newest) if you like
  return messages.reverse();
}

/**
 * 4️⃣ Mark a chat as read for a specific user.
 */
async function markChatAsRead({ chatId, userId }) {
  const mostRecentMessage = await Message.findOne({
    chat: chatId,
    isDeleted: false,
  })
    .sort({ createdAt: -1 })
    .select('_id createdAt')
    .lean();

  if (!mostRecentMessage) return null;

  // Either upsert into the dedicated collection…
  await MessageRead.findOneAndUpdate(
    { chat: chatId, user: userId },
    {
      lastReadAt: mostRecentMessage.createdAt,
      lastReadMessageId: mostRecentMessage._id,
    },
    { upsert: true, new: true }
  );

  // …or update the embedded `participants.lastReadAt`
  await Chat.updateOne(
    { _id: chatId, 'participants.user': userId },
    {
      $set: { 'participants.$.lastReadAt': mostRecentMessage.createdAt },
    }
  );

  return mostRecentMessage;
}

/**
 * 5️⃣ Compute unread count for a user on a given chat.
 */
async function getUnreadCount({ chatId, userId }) {
  // 1️⃣ fetch the participant entry (or MessageRead doc)
  const chat = await Chat.findById(chatId, {
    participants: 1,
  }).lean();

  const participant = chat.participants.find(p => p.user.equals(userId));

  const lastReadAt = participant?.lastReadAt || new Date(0); // epoch if never read

  // 2️⃣ count newer messages
  const count = await Message.countDocuments({
    chat: chatId,
    isDeleted: false,
    createdAt: { $gt: lastReadAt },
  });

  return count;
}

/**
 * 6️⃣ Add a reaction (emoji) to a message.
 */
async function toggleReaction({ messageId, userId, emoji }) {
  const msg = await Message.findById(messageId);

  const users = msg.reactions.get(emoji) || [];

  const alreadyReacted = users.some(id => id.equals(userId));

  if (alreadyReacted) {
    // remove reaction
    const filtered = users.filter(id => !id.equals(userId));
    if (filtered.length) msg.reactions.set(emoji, filtered);
    else msg.reactions.delete(emoji);
  } else {
    // add reaction
    users.push(userId);
    msg.reactions.set(emoji, users);
  }

  await msg.save();
  return msg;
}
```

