#### Example: A simple userscript that highlights all occurrences of the word “OpenAI” on any page

If you’re looking for something quick and easy, here’s a **Tampermonkey userscript** you can copy‑paste into the extension:

```javascript
// ==UserScript==
// @name         Highlight "OpenAI"
// @namespace    https://example.com
// @version      1.0
// @description  Highlights every occurrence of the word "OpenAI" on the page.
// @match        *://*/*
// @grant        none
// ==/UserScript==

(function() {
    'use strict';

    // Configuration
    const word = "OpenAI";
    const highlightStyle = "background-color: #fffd38; color: #000; font-weight: bold;";

    // Create a regular expression that matches the word case‑insensitively
    const re = new RegExp(`(${word})`, "gi");

    // Walk the DOM and replace text nodes
    function walk(node) {
        // Skip script/style or already processed nodes
        if (node.nodeType === Node.ELEMENT_NODE &&
            (node.tagName === "SCRIPT" || node.tagName === "STYLE" || node.dataset.highlighted)) {
            return;
        }
        if (node.nodeType === Node.TEXT_NODE) {
            const parent = node.parentNode;
            if (re.test(node.textContent)) {
                const span = document.createElement("span");
                span.dataset.highlighted = "true";
                span.innerHTML = node.textContent.replace(re, `<mark style="${highlightStyle}">$1</mark>`);
                parent.replaceChild(span, node);
            }
        } else {
            // Recursively process child nodes
            node.childNodes.forEach(walk);
        }
    }

    walk(document.body);
})();
```

**How to use it**

1. Install **Tampermonkey** (or any userscript manager) from the Chrome Web Store.  
2. Click the extension icon → “Create a new script”.  
3. Replace the default template with the code above.  
4. Save (⌘+S / Ctrl+S).  
5. Reload any page – every occurrence of “OpenAI” will be highlighted in yellow.

