<div id="main" class="hidden">
  <p>当前用户：<span id="userLabel"></span>
     <button id="closeBtn">断开连接</button>
  </p>

  <textarea id="log" rows="15" readonly></textarea><br>

  <input id="msgInput" type="text" placeholder="说点什么…">
  <button id="sendBtn">发送消息</button>

