  <input type="file" id="fileInput">
  <button id="sendFileBtn">发送文件</button>
</div>

<script>
/* --------------------------------------------------------------
   Global state
   -------------------------------------------------------------- */
let ws = null;
let myName = null;

/* --------------------------------------------------------------
   UI helpers
   -------------------------------------------------------------- */
function log(message) {
  const ta = document.getElementById('log');
  ta.value = ta.value ? `${ta.value}\n${message}` : message;
  // Auto‑scroll to bottom
  ta.scrollTop = ta.scrollHeight;
}

/* --------------------------------------------------------------
   WebSocket handling
   -------------------------------------------------------------- */
function startWebSocket() {
  // Use relative URL → works whether you serve via http:// or https://
  ws = new WebSocket(`ws://${location.host}`);

  // We want the binary data as an ArrayBuffer (so we can prefix our own header)
  ws.binaryType = 'arraybuffer';

  ws.addEventListener('open', () => {
    log('✅ 连接已打开，等待登录…');
    // Send login immediately after open
    ws.send(JSON.stringify({ type: 'login', name: myName }));
  });

  ws.addEventListener('message', event => {
    // --------------------------------------------------- Text (JSON) ----
