    const headerLen = view.getUint32(0, true);
    const headerStr = new TextDecoder('utf-8')
                      .decode(new Uint8Array(buf, 4, headerLen));
    let header;
    try { header = JSON.parse(headerStr); } catch (_) { return; }

    // Extract the file payload
    const fileStart = 4 + headerLen;
    const fileBlob = new Blob([buf.slice(fileStart)], { type: header.mime });

    // --------------------------------------------------- Show result ---
    const time = new Date(header.ts).toLocaleTimeString();
    log(`[${time}] ${header.name} (${header.ip}) 发送文件 ${header.fileName}`);

    // If the file is an image, embed it right under the log textarea:
    if (header.mime.startsWith('image/')) {
      const img = document.createElement('img');
      img.style.maxWidth = '300px';
      img.style.display = 'block';
      img.style.marginTop = '4px';
      img.src = URL.createObjectURL(fileBlob);
      document.body.appendChild(img);
    } else {
      // For non‑image files we simply provide a download link.
      const a = document.createElement('a');
      a.href = URL.createObjectURL(fileBlob);
      a.download = header.fileName;
      a.textContent = `下载 ${header.fileName}`;
      a.style.display = 'block';
      a.style.marginTop = '4px';
      document.body.appendChild(a);
    }
  });

  ws.addEventListener('close', () => {
    log('❌ 连接已关闭');
    toggleUI(false);
  });

  ws.addEventListener('error', err => {
    console.error('WebSocket error', err);
    log('⚠️ WebSocket 错误 (查看控制台)');
  });
}

/* --------------------------------------------------------------
   JSON message dispatcher
   -------------------------------------------------------------- */
function handleJsonMessage(msg) {
  const time = new Date(msg.ts).toLocaleTimeString();

  switch (msg.type) {
    case 'welcome':
      log(`[${time}] 系统: ${msg.msg}`);
      break;

    case 'system':
      log(`[${time}] 系统: ${msg.msg}`);
      break;

    case 'text':
      const from = `${msg.name} (${msg.ip})`;
      log(`[${time}] ${from}: ${msg.body}`);
      break;

    case 'error':
      log(`[${time}] 错误: ${msg.msg}`);
      break;

    default:
      console.warn('未知消息类型', msg);
  }
}

/* --------------------------------------------------------------
