  if (!name) { alert('请填写用户名'); return; }

  myName = name;
  document.getElementById('userLabel').textContent = name;
  toggleUI(true);
  startWebSocket();
});

document.getElementById('closeBtn').addEventListener('click', () => {
  if (ws) ws.close();
});

document.getElementById('sendBtn').addEventListener('click', () => {
  const txt = document.getElementById('msgInput').value.trim();
  if (!txt) return;
  ws.send(JSON.stringify({ type: 'text', body: txt }));
  document.getElementById('msgInput').value = '';
});

document.getElementById('sendFileBtn').addEventListener('click', () => {
  const file = document.getElementById('fileInput').files[0];
  if (!file) { alert('请选择文件'); return; }

  // ---- Build binary envelope (header + file) ---------------------
  const header = {
    type    : 'file',
    name    : myName,
    ip      : null,          // the server will fill this in for us
    fileName: file.name,
    mime    : file.type || 'application/octet-stream',
    // ts will be added by server, but we put one now for local debugging:
    ts      : new Date().toISOString()
  };
  const headerJson = JSON.stringify(header);
  const headerBuf = new TextEncoder().encode(headerJson);
  const headerLenBuf = new Uint8Array(4);
  new DataView(headerLenBuf.buffer).setUint32(0, headerBuf.length, true);

  // ---- Read the file into an ArrayBuffer -------------------------
  const reader = new FileReader();
  reader.onload = e => {
    const fileBuf = new Uint8Array(e.target.result);
    // Concatenate: [4‑byte length][header][file]
    const payload = new Uint8Array(
      headerLenBuf.length + headerBuf.length + fileBuf.length
    );
    payload.set(headerLenBuf, 0);
    payload.set(headerBuf, 4);
    payload.set(fileBuf, 4 + headerBuf.length);
    ws.send(payload.buffer);
  };
  reader.readAsArrayBuffer(file);
});

/* --------------------------------------------------------------
   Helper to show / hide the two big UI panels
   -------------------------------------------------------------- */
function toggleUI(connected) {
  document.getElementById('register').classList.toggle('hidden', connected);
  document.getElementById('main').classList.toggle('hidden', !connected);
}
</script>
</body>
</html>
```

### Why the front‑end now looks cleaner

| Change | Reason |
|--------|--------|
| **Single `ws.onmessage`** | The old code assigned `socket.onmessage` **twice**, wiping out the first handler. Now we register **one** listener and dispatch based on `typeof event.data`. |
| **No external IP lookup** | The server already knows the remote address and sends it back in every message (`msg.ip`). The client no longer needs `axios` + `api.ipify.org`. |
| **Explicit login message** | The client sends a `{type:'login', name}` JSON right after opening the socket, so the server can store the name and broadcast a “user entered” system message. |
| **Binary envelope** | We prepend a small 4‑byte length field + JSON header. This lets the server know the file name, MIME type, and original sender while still treating the whole payload as a single binary frame. |
| **Automatic UI toggling** | A tiny `toggleUI()` helper adds/removes the `.hidden` class instead of fiddling with `style.visibility`. |
| **Graceful error display** | Errors from the server now appear in the same chat log (`type:'error'`). |
| **Image preview & download link** | When a binary message arrives, the client decides whether to embed an `<img>` (if `mime` starts with `image/`) or to create a download link for other file types. |

---

## 4️⃣ How to run everything

1. **Create a folder**  
   ```bash
   mkdir ws‑chat && cd ws‑chat
   npm init -y                # creates a package.json
   npm i ws                    # install the WebSocket library
   ```

