const rankValue = rank => RANKS.indexOf(String(rank));

/**
 * Compare two cards by rank (high → low).  If the ranks are equal we
 * keep the original order – the suit does not matter for a pair.
 */
function compareCardsDesc(a, b) {
  return rankValue(b.rank) - rankValue(a.rank);
