   *
   * @param {Card[]} cards – the 5‑card (or 7‑card) pool
   * @returns {{combination: TwoPairs, cards: Card[]} | null}
   */
  static test(cards) {
    // 1️⃣  Count how many cards we have of each rank
    const countByRank = {};
    for (const c of cards) {
      const r = c.rank;
      countByRank[r] = (countByRank[r] || 0) + 1;
    }

    // 2️⃣  Keep only the ranks that appear at least twice
    const pairRanks = Object.keys(countByRank).filter(r => countByRank[r] >= 2);
    if (pairRanks.length < 2) return null; // not enough pairs

    // 3️⃣  Choose the two *highest* pair‑ranks
    pairRanks.sort((a, b) => rankValue(b) - rankValue(a));
    const [highRank, lowRank] = pairRanks;               // the two best ranks

    // 4️⃣  Pick the two highest cards of each rank
    const highPair = cards
      .filter(c => c.rank === highRank)
      .sort(compareCardsDesc)
      .slice(0, 2);

    const lowPair = cards
      .filter(c => c.rank === lowRank)
      .sort(compareCardsDesc)
      .slice(0, 2);

    // 5️⃣  Return the result (the combination object is a *new* instance)
    return {
      combination: new TwoPairs(),
      cards: [...highPair, ...lowPair]   // order: higher pair first
    };
  }
}

