  const combinations = [
    // RoyalFlush,
    // StraightFlush,
    // FourOfAKind,
    // FullHouse,
    // Flush,
    // Straight,
    // ThreeOfAKind,
    // TwoPairs,
    TwoPairs,
    // Pair,
  ];

  // we walk from the strongest hand to the weakest; the first match wins
  for (const CombinationClass of combinations) {
    const result = CombinationClass.test(cards);
    if (result) {
