// server.js (or wherever you set up Express)
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const bcrypt = require('bcrypt');            // npm i bcrypt
const validator = require('validator');      // npm i validator
const bodyParser = require('express').json; // built‑in in recent Express

const app = express();
app.use(bodyParser()); // parses JSON bodies

// Open (or create) the DB – keep a single instance for the app lifetime
const db = new sqlite3.Database('./db.sqlite', err => {
  if (err) {
    console.error('Failed to open DB:', err);
    process.exit(1);
  }
  // Optional: create table if it doesn’t exist
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password TEXT NOT NULL,
      email TEXT UNIQUE NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

/**
 * POST /api/register
 * Expected JSON payload:
 * {
 *   "username": "bob",
 *   "password": "mySecret123",
 *   "email": "bob@example.com"
 * }
 */
app.post('/api/register', async (req, res) => {
  const { username, password, email } = req.body;

  // ---- 1️⃣ Basic validation ----
  if (
    typeof username !== 'string' || username.trim() === '' ||
    typeof password !== 'string' || password.length < 6 ||
    typeof email !== 'string' || !validator.isEmail(email)
  ) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  // ---- 2️⃣ Hash the password ----
  const saltRounds = 12;                      // adjust as needed
  let passwordHash;
  try {
    passwordHash = await bcrypt.hash(password, saltRounds);
  } catch (err) {
    console.error('bcrypt error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }

  // ---- 3️⃣ Insert using a prepared statement ----
  const sql = `
    INSERT INTO users (username, password, email)
    VALUES (?, ?, ?)
  `;

  db.run(sql, [username.trim(), passwordHash, email.trim().toLowerCase()], function (err) {
    if (err) {
      // ────── Duplicate key handling ──────
      if (err.code === 'SQLITE_CONSTRAINT') {
        // SQLite throws the same error for any UNIQUE violation;
        // you can inspect err.message to differentiate if needed.
        return res.status(409).json({ error: 'Username or email already taken' });
      }

      // ────── Other DB errors ──────
      console.error('DB insert error:', err);
      return res.status(500).json({ error: 'Database error' });
    }

    // Success! `this.lastID` holds the newly created row id
    return res.status(201).json({ success: true, userId: this.lastID });
  });
});

// ---- 4️⃣ Global error handler (optional but nice) ----
app.use((err, _req, res, _next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Something went wrong' });
});

// ---- 5️⃣ Start server ----
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`🚀 API listening on http://localhost:${PORT}`));
```

### What changed?

| Old code | New code | Reason |
|----------|----------|--------|
| `app.get('/api/register', ...)` | `app.post('/api/register', ...)` | POST keeps credentials out of the URL. |
| `req.query` | `req.body` (JSON) | Body parser gives you a clean object; no URL‑encoding headaches. |
| String interpolation into SQL | `?` placeholders + array of parameters | SQLite driver escapes & quotes automatically, eliminates injection. |
| Plain password stored | `bcrypt.hash` → stored hash | Never store raw passwords. |
| No validation | Checks for empty strings, length, email pattern | Prevents garbage data & early feedback. |
| No error handling | `if (err) { … }` and a global error handler | Returns proper HTTP status codes instead of crashing. |
| No column list in `INSERT` | `INSERT INTO users (username, password, email) …` | Makes query independent of column order and future schema changes. |

---

## 3️⃣ Quick tests

You can test the endpoint with `curl` (or Postman, Insomnia, etc.):

```bash
curl -X POST http://localhost:3000/api/register \
  -H "Content-Type: application/json" \
  -d '{"username":"bob","password":"mySecret123","email":"bob@example.com"}'
```

Expected successful response:

```json
{
  "success": true,
  "userId": 1
}
```

If you try the same username or email again:

```json
{
  "error": "Username or email already taken"
}
```

If you send malformed JSON or an invalid email:

```json
{
  "error": "Invalid input"
}
```

---

## 4️⃣ Bonus: Using a Promise‑based wrapper

The native `sqlite3` API is callback‑heavy. If you prefer `async/await`, you can wrap it with `sqlite` (a tiny promise wrapper) or use `better-sqlite3`.

```bash
npm i sqlite   # or npm i better-sqlite3
```

```js
// Example with `sqlite` (async/await)
const sqlite = require('sqlite');
const sqlite3 = require('sqlite3');

(async () => {
  const db = await sqlite.open({ filename: './db.sqlite', driver: sqlite3.Database });

  // later inside route:
  try {
    const result = await db.run(
      `INSERT INTO users (username,password,email) VALUES (?,?,?)`,
      [username, passwordHash, email]
    );
    res.status(201).json({ success: true, userId: result.lastID });
  } catch (err) {
    // same error handling as before
  }
})();
```

`better-sqlite3` offers a **synchronous** API that many find simpler for small services.

---

## 5️⃣ TL;DR checklist (copy‑paste)

```text
[ ] Switch to POST + JSON body
[ ] Validate username / password / email
[ ] Hash password (bcrypt/argon2)
[ ] Use prepared statement with placeholders
[ ] Explicit column list in INSERT
[ ] Handle UNIQUE constraint (409)
[ ] Return proper HTTP status codes
[ ] Log DB errors, don’t expose internals to client
[ ] Never store clear‑text passwords
[ ] Consider a promise wrapper (sqlite / better-sqlite3)
[ ] Add a global error handler
```

Implement those, and the “unrecognized token” error disappears while your registration endpoint becomes **secure**, **robust**, and **maintainable**. Happy coding! 🚀

