// ---------- Helper ----------
function countWords(str) {
  // simple split on whitespace, filter empty strings
  return str.trim().split(/\s+/).filter(Boolean).length;
}

// ---------- Word counter for textarea ----------
const textarea = document.querySelector('textarea[name="context"]');
const wordCountEl = document.getElementById('word-count');

textarea.addEventListener('input', () => {
  const words = countWords(textarea.value);
  wordCountEl.textContent = `${words} / 500 words`;
  if (words > 500) {
    wordCountEl.style.color = 'red';
  } else {
    wordCountEl.style.color = '#555';
  }
});

// ---------- Form submit ----------
const form = document.getElementById('quiz-form');
const resultSection = document.getElementById('result');
const outputPre = document.getElementById('quiz-output');
const copyBtn = document.getElementById('copy-btn');

form.addEventListener('submit', async e => {
  e.preventDefault();

  // ----- client side validation -----
  const context = textarea.value.trim();
  if (countWords(context) > 500) {
    alert('Context exceeds 500‑word limit.');
    return;
  }

  const data = {
    board: form.board.value,
    type: form.type.value,
    difficulty: form.difficulty.value,
    num: parseInt(form.num.value, 10),
    context
  };

  // ----- show loading feedback -----
  outputPre.textContent = '⏳ Generating quiz...';
  resultSection.classList.remove('hidden');

  try {
    const resp = await fetch('/api/generate-quiz', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });

    if (!resp.ok) throw new Error(`Server error ${resp.status}`);

    const { quiz } = await resp.json();
    outputPre.textContent = quiz;
  } catch (err) {
    console.error(err);
    outputPre.textContent = `❌ Error: ${err.message}`;
  }
});

// ----- copy to clipboard -----
copyBtn.addEventListener('click', () => {
  const text = outputPre.textContent;
  navigator.clipboard.writeText(text).then(() => {
    copyBtn.textContent = 'Copied!';
    setTimeout(() => copyBtn.textContent = 'Copy to Clipboard', 1500);
  });
});
```

**What happens**

1. Word‑count validation (≤ 500).  
2. POST `/api/generate-quiz` with a JSON payload.  
3. Server replies with `{ quiz: "..." }`.  
