## 3️⃣ Back‑end – `server.js`

```js
/**
 * server.js
 * ---------
 * Express server that receives quiz requests, builds a prompt,
 * calls OpenAI's Chat Completion API (gpt-3.5‑turbo by default),
 * and returns the generated quiz text.
 *
 * Security note:
 *   • The OpenAI API key lives only in the server environment (.env).
 *   • The front‑end never sees it.
 */

require('dotenv').config();                // Loads .env
const express = require('express');
const cors = require('cors');
const axios = require('axios');            // HTTP client (could also use openai SDK)
const path = require('path');

// ------------------ Config ------------------
const PORT = process.env.PORT || 3000;
const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
if (!OPENAI_API_KEY) {
  console.error('❗️ Missing OPENAI_API_KEY in .env');
  process.exit(1);
}

// ------------------ App ------------------
const app = express();

app.use(cors());                     // Allow local dev requests (origin = '*')
app.use(express.json({ limit: '2mb' })); // Parse JSON bodies
app.use(express.static(path.join(__dirname, 'public')));

// ------------------ Helper: Build Prompt ------------------
function buildPrompt({ board, type, difficulty, num, context }) {
  // You can fine‑tune this prompt; keep it concise for token economy.
  return `
You are an expert radiology educator. Generate **${num}** ${type} ${
    difficulty.toLowerCase()
  }-level questions for the **${board}** board exam.

${context ? `Use the following additional context (ignore if not relevant):\n${context}\n` : ''}

Output format:
1. Question
   A) Option 1
   B) Option 2
   C) Option 3
   D) Option 4
   Answer: X
   Explanation: ...

Provide ONLY the questions (no extra commentary).`;
}

// ------------------ API Route ------------------
app.post('/api/generate-quiz', async (req, res) => {
  try {
    const { board, type, difficulty, num, context } = req.body;

    // --------- Very light validation ----------
    if (!board || !type || !difficulty || !num) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const prompt = buildPrompt({ board, type, difficulty, num, context });

    // --------- Call OpenAI (Chat Completion) ----------
    const openaiResp = await axios.post(
      'https://api.openai.com/v1/chat/completions',
      {
        model: process.env.OPENAI_MODEL || 'gpt-3.5-turbo',
        messages: [{ role: 'system', content: 'You are a helpful assistant.' }, { role: 'user', content: prompt }],
        temperature: 0.7,
        max_tokens: 1500   // Adjust as needed – roughly 80‑100 tokens per MCQ
      },
      {
        headers: {
          Authorization: `Bearer ${OPENAI_API_KEY}`,
          'Content-Type': 'application/json'
        }
      }
    );

    const quiz = openaiResp.data?.choices?.[0]?.message?.content?.trim() || '';

    // --------- Return result ----------
    res.json({ quiz });
  } catch (err) {
    console.error('OpenAI error:', err.response?.data || err.message);
    res.status(500).json({ error: 'Failed to generate quiz' });
  }
});

// ------------------ Catch‑all for SPA ----------
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

// ------------------ Start Server ------------------
app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
```

**Key security points**

* The **OpenAI API key** is read from `.env` **server‑side only**.
* The `cors` middleware is minimal; in production you would restrict `origin` to your own domain.
* Input validation is deliberately lightweight – you could add more (e.g., allowed board list, max `num`, word‑count check).

