function loadQuestionDetail(url){
    fetch(url)
        .then(r => r.ok ? r.json() : Promise.reject(`GET ${url} ${r.status}`))
        .then(data => renderQuestionForm(data.question))
        .catch(err => showError(err));
}

/* Construit le formulaire d’édition ou d’ajout (isNew = false) */
function renderQuestionForm(q, isNew = false){
    // Sauvegarde l’URL de la question dans un hidden pour le PUT/DELETE
    const qUrl = q.url || `${API_ROOT}/questions`;

    $("#currenttask").empty()
        .append(`
            <input type="hidden" id="question-id"        value="${q.id || ''}">
            <input type="hidden" id="question-url"       value="${qUrl}">
            <input type="hidden" id="questionnaire-id"  value="${q.questionnaire_id || ''}">
            <div>
                <label>Titre :</label>
                <input type="text" id="title" value="${q.title || ''}">
            </div>
            <div>
                <label>Type :</label>
                <input type="radio" name="type" id="type-simple"  ${q.questionType === "simple" ? "checked" : ""}> Simple
                <input type="radio" name="type" id="type-multiple" ${q.questionType === "multiple" ? "checked" : ""}> Multiple
            </div>
            <div id="simple-part" style="${q.questionType === "simple" ? "" : "display:none"}">
                <label>Réponse :</label>
                <input type="text" id="reponse-simple" value="${q.reponse || ''}">
            </div>
            <div id="multiple-part" style="${q.questionType === "multiple" ? "" : "display:none"}">
                <label>Proposition 1 :</label>
                <input type="text" id="prop1" value="${q.proposition1 || ''}"><br>
                <label>Proposition 2 :</label>
                <input type="text" id="prop2" value="${q.proposition2 || ''}"><br>
                <label>Réponse (1 ou 2) :</label>
                <input type="number" id="reponse-multi" min="1" max="2" value="${q.reponse || ''}">
            </div>
            <br>
            <button id="save-question">${isNew ? "Créer" : "Enregistrer"}</button>
            ${!isNew ? '<button id="delete-question">Supprimer</button>' : ''}
        `);

    // -----------------------------------------------------------------
    //  Gestion du changement de type (simple ↔ multiple)
    // -----------------------------------------------------------------
    $("#type-simple, #type-multiple").on('change', function(){
        const isMultiple = $("#type-multiple").is(':checked');
        $("#simple-part").toggle(!isMultiple);
        $("#multiple-part").toggle(isMultiple);
    });

    // -----------------------------------------------------------------
    //  Sauvegarde (POST ou PUT selon isNew)
    // -----------------------------------------------------------------
    $("#save-question").on('click', function(){
        const payload = buildQuestionPayload();
        const method   = isNew ? "POST" : "PUT";
        const target   = isNew ? `${API_ROOT}/questions` : $("#question-url").val();

        fetch(target, {
            method: method,
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(payload)
        })
        .then(r => r.ok ? r.json() : Promise.reject(`${method} ${target} ${r.status}`))
        .then(() => {
            alert("Enregistrement OK");
            loadQuestionnaires();               // rafraîchit la liste
            $("#currenttask").empty();          // on vide le formulaire
        })
        .catch(err => showError(err));
    });

    // -----------------------------------------------------------------
    //  Suppression (DELETE) – seulement en mode édition
    // -----------------------------------------------------------------
    if (!isNew){
        $("#delete-question").on('click', function(){
            if (!confirm("Supprimer cette question ?")) return;
            fetch($("#question-url").val(), {
                method: "DELETE",
                headers: { 'Accept': 'application/json' }
            })
            .then(r => r.ok ? r.json() : Promise.reject(`DELETE ${r.status}`))
            .then(() => {
                alert("Question supprimée");
                loadQuestionnaires();
                $("#currenttask").empty();
            })
            .catch(err => showError(err));
        });
    }
}

/* Construit le corps JSON à envoyer selon le type choisi */
function buildQuestionPayload(){
    const isMultiple = $("#type-multiple").is(':checked');
    const base = {
        title: $("#title").val(),
        questionType: isMultiple ? "multiple" : "simple",
        questionnaire_id: parseInt($("#questionnaire-id").val(),10)
    };
    if (isMultiple){
        base.proposition1 = $("#prop1").val();
        base.proposition2 = $("#prop2").val();
        base.reponse      = parseInt($("#reponse-multi").val(),10);
    }else{
        base.reponse = $("#reponse-simple").val();
    }
    return base;
}
