}
``` |
| **`initializeApp` runs at import time** – not ideal for libraries or for running a second instance in the same process (e.g., integration tests). | Wrap the call in `if (require.main === module) { initializeApp(); }` so that it only executes when the file is the entry point (`node src/server.js`). |

---

## 3️⃣  Suggested Refactor – Minimal Boilerplate Skeleton

Below is a **concise, yet production‑ready skeleton** you can copy‑paste into a new repository. It shows the **separation of concerns** while keeping the same feature set you already have.

<details>
<summary>📂  Directory layout (collapsed)</summary>

```
src/
 ├─ app.js               # creates the Express app, registers middleware
 ├─ server.js            # boots the HTTP(S) server, graceful shutdown
 ├─ config/
 │   ├─ default.js       # default config (port, DB URI, CORS whitelist)
 │   └─ schema.js        # optional validation with `convict` or `joi`
 ├─ infra/
 │   ├─ db/
 │   │   └─ mongodb.js   # MongoDB client wrapper (connect/disconnect)
 │   └─ lock/
 │       └─ lock.js      # thin wrapper around node-locksmith
 ├─ middleware/
 │   ├─ requestLogger.js
 │   ├─ errorHandler.js
 │   └─ notFound.js
 ├─ routes/
 │   ├─ index.js         # exports { '/api/v1': v1Router }
 │   └─ v1/
 │       └─ users.js
 └─ utils/
     └─ logger.js        # winston/pino wrapper
```
</details>

### `src/app.js`

```js
// -----------------------------------------------------
// 1️⃣  Imports & Config
// -----------------------------------------------------
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const methodOverride = require('method-override');
const compression = require('compression');
const requestId = require('express-request-id')();
const PromiseRouter = require('express-promise-router');
const config = require('./config/default');
const logger = require('./utils/logger');
const requestLogger = require('./middleware/requestLogger');
const errorHandler = require('./middleware/errorHandler');
const notFound = require('./middleware/notFound');

// -----------------------------------------------------
// 2️⃣  App factory
// -----------------------------------------------------
function createApp(dependencies = {}) {
  const app = express();

  // expose minimal deps (helps testing)
  app.locals.logger = logger;
  app.locals.db = dependencies.db;   // optional, set by server.js

  // -------------------------------------------------
  // 3️⃣  Core middlewares (order matters)
  // -------------------------------------------------
  app.use(requestId);                     // adds req.id
  app.use(cors({ origin: config.corsOrigins }));
  app.use(helmet());
  app.use(compression());
  app.use(
    rateLimit({
      windowMs: config.rateLimit.windowMs,
      max: config.rateLimit.max,
    })
  );
  app.use(methodOverride('X-HTTP-Method-Override'));
  app.use(express.json({ limit: '1mb' }));
  app.use(express.urlencoded({ extended: true }));
  app.use(requestLogger);                // custom logger + timing

  // -------------------------------------------------
  // 4️⃣  Health endpoints
  // -------------------------------------------------
  app.get(['/hc', '/healthcheck'], (req, res) => {
    const status = { uptime: process.uptime() };
    res.status(200).json(status);
  });

  // -------------------------------------------------
  // 5️⃣  Route mounting (dynamic)
  // -------------------------------------------------
  const router = PromiseRouter();
  const routes = require('./routes'); // { '/api/v1': v1RouterFactory }
  for (const [mount, factory] of Object.entries(routes)) {
    router.use(mount, factory({ logger, db: dependencies.db }));
  }
  app.use(router);

  // -------------------------------------------------
  // 6️⃣  404 & error handling (must be last)
  // -------------------------------------------------
  app.use(notFound);
  app.use(errorHandler);

  return app;
}

module.exports = { createApp };
```

### `src/server.js`

```js
#!/usr/bin/env node
/* ---------------------------------------------------------
   Server bootstrap – runs only when this file is executed
   (node src/server.js). Keeps app creation pure for tests.
---------------------------------------------------------- */
const http = require('http');
const https = require('https');
const fs = require('fs');
const { createApp } = require('./app');
const config = require('./config/default');
const logger = require('./utils/logger');
const MongoDB = require('./infra/db/mongodb');
const Lock = require('./infra/lock/lock');

async function start() {
  // -------------------------------------------------
  // 1️⃣  Acquire process lock
  // -------------------------------------------------
  const lock = new Lock({ lockFileName: 'medics-communication-server.lock' });
  await lock.acquire(); // throws if another instance holds the lock

  // -------------------------------------------------
  // 2️⃣  Connect to DB
  // -------------------------------------------------
  const db = new MongoDB(config.mongodbUri, logger);
  await db.connect();

  // -------------------------------------------------
  // 3️⃣  Create the Express app (inject deps)
  // -------------------------------------------------
  const app = createApp({ db });

  // -------------------------------------------------
  // 4️⃣  Start HTTP(S) server
  // -------------------------------------------------
  const server = config.tls.enabled
    ? https.createServer(
        {
          key: fs.readFileSync(config.tls.keyPath),
          cert: fs.readFileSync(config.tls.certPath),
        },
        app
      )
    : http.createServer(app);

  server.listen(config.port, () => {
    logger.info(`🟢 Server listening on ${config.tls.enabled ? 'https' : 'http'}://${config.host}:${config.port}`);
  });

  // -------------------------------------------------
  // 5️⃣  Graceful shutdown
  // -------------------------------------------------
  const shutdown = async (signal) => {
    logger.info(`⚡ Received ${signal}. Shutting down…`);
    server.close(async (err) => {
      if (err) logger.error('Error closing server', err);
      await db.disconnect();
      await lock.release();
      process.exit(err ? 1 : 0);
    });
  };
  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));

  // -------------------------------------------------
  // 6️⃣  Global error handlers (optional but recommended)
  // -------------------------------------------------
  process.on('unhandledRejection', (reason) => {
    logger.error('Unhandled Promise Rejection', { reason });
  });
  process.on('uncaughtException', (err) => {
    logger.error('Uncaught Exception', err);
    shutdown('uncaughtException');
  });
}

// Kick‑off when run directly
if (require.main === module) {
  start().catch((e) => {
    logger.error('Fatal startup error', e);
    process.exit(1);
  });
}
```

### `src/utils/logger.js` (example with **pino**)

```js
const pino = require('pino');

const logger = pino({
  level: process.env.LOG_LEVEL || 'info',
  serializers: {
    err: pino.stdSerializers.err,
    req: (req) => ({
      id: req.id,
      method: req.method,
      url: req.url,
      ip: req.ip,
    }),
  },
});

module.exports = logger;
```

### `src/middleware/requestLogger.js`

```js
module.exports = (req, res, next) => {
  const start = process.hrtime.bigint();
  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - start) / 1e6;
    req.app.locals.logger.info({
      msg: 'request completed',
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${durationMs.toFixed(2)}ms`,
      requestId: req.id,
    });
  });
  next();
};
```

### `src/middleware/errorHandler.js`

```js
module.exports = (err, req, res, _next) => {
  const logger = req.app.locals.logger;
  logger.error({ err, requestId: req.id, route: req.originalUrl }, 'Unhandled error');

  const status = err.status ?? 500;
  const response = {
    error: process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
  };
  if (process.env.NODE_ENV !== 'production') response.stack = err.stack;
  res.status(status).json(response);
};
```

### `src/middleware/notFound.js`

```js
module.exports = (req, res) => {
  res.status(404).json({ error: 'Not Found' });
};
```

### `src/config/default.js`

```js
module.exports = {
  port: Number(process.env.PORT ?? 3000),
  host: process.env.HOST ?? '0.0.0.0',
  mongodbUri: process.env.MONGODB_URI ?? 'mongodb://localhost:27017/medics',
  corsOrigins: (process.env.CORS_ORIGINS ?? '*').split(',').map(o => o.trim()),
  rateLimit: {
    windowMs: 15 * 60 * 1000,
    max: Number(process.env.RATE_LIMIT_MAX ?? 100),
  },
  tls: {
    enabled: process.env.ENABLE_TLS === 'true',
    keyPath: process.env.TLS_KEY_PATH ?? './certs/key.pem',
    certPath: process.env.TLS_CERT_PATH ?? './certs/cert.pem',
  },
};
```

> **Why this structure?**  
> 1. **`app.js`** only creates the Express app – perfect for unit tests (`supertest(app)`).  
> 2. **`server.js`** bootstraps external resources (DB, lock, TLS) and handles signals.  
> 3. Dependencies are injected (`app.locals.{logger,db}`) instead of being accessed via globals, making the code **testable** and **re‑usable** across services.  
> 4. All **error‑handling**, **logging**, and **graceful‑shutdown** concerns are in one place, minimizing duplication.  

---

## 4️⃣  Checklist – What to Add / Verify in Every Project

| ✅ Feature | ✅ How to verify (quick command) |
|-----------|---------------------------------|
| **Environment validation** (required vars, correct types) | `npm run verify-config` → use `convict` or `joi`. |
| **Unit tests** for routes, middlewares, DB wrapper | `npm test` (Jest/Mocha). |
| **Integration test** that starts the server on a random port and runs a health‑check | `npm run test:integration`. |
| **Linting & formatting** (ESLint + Prettier) | `npm run lint`. |
| **CI pipeline** (GitHub Actions) that runs lint → test → build | `.github/workflows/ci.yml`. |
| **Dockerfile** with multi‑stage build, copying only compiled code | `docker build .`. |
| **OpenAPI/Swagger spec** generated from route definitions | `npm run docs`. |
| **Metrics endpoint** (`/metrics`) exposing Prometheus format | `npm run start && curl localhost:3000/metrics`. |
| **Feature toggle** library (e.g., `node-config` or `launchdarkly`) if you need per‑environment flags. | `process.env.FEATURE_X === 'true'`. |
| **Secrets management** – never commit `.env` or `config.json` with passwords. | `.gitignore` includes `.env`, `config/*.json`. |
| **Dependency updates** – periodic `npm outdated` & PRs. | `npm outdated`. |
| **License & contribution guidelines** – you’re on a boiler‑plate, include `LICENSE` and `CONTRIBUTING.md`. | Quick glance at repo root. |

---

## 5️⃣  TL;DR – What to Do Next

1. **Separate “app” from “server”** – move the Express setup into its own module (`app.js`).  
2. **Inject dependencies** (logger, DB, lock) rather than pulling them from globals.  
3. **Add proper shutdown**: close HTTP server, DB pool, release lock.  
4. **Tighten logging** – whitelist headers, truncate bodies, add request‑ID & response‑time.  
5. **Add missing middleware** – compression, request‑ID, optional TLS, 404 & global error handler.  
6. **Validate config** at startup (throw early if required env vars missing).  
7. **Export only the factory** (`createApp`) for tests; keep `initializeApp` inside a `if (require.main === module)` block.  
8. **Create a small “starter” script** (`npm start → node src/server.js`) and a corresponding Dockerfile.  

Apply the skeleton above (or blend it with your existing file) and you’ll have a **clean, reusable, production‑grade** boilerplate that works out‑of‑the‑box for any new Node/Express service.  

Happy coding! 🚀

