## 2️⃣ `register.php` – the single file that contains HTML **and** PHP

```php
<?php
/* --------------------------------------------------------------
   register.php  (HTML + PHP)
   -------------------------------------------------------------- */

// ---------- 1. CONFIGURATION ----------
$host     = 'localhost';
$user     = 'admin';
$pass     = 'admin1234';
$dbname   = 'input';
$charset  = 'utf8mb4';

// ---------- 2. CONNECT (mysqli) ----------
$mysqli = new mysqli($host, $user, $pass, $dbname);
if ($mysqli->connect_errno) {
    die('Failed to connect to MySQL: (' . $mysqli->connect_errno . ') '
        . $mysqli->connect_error);
}

// ---------- 3. CSRF TOKEN (simple) ----------
session_start();
if (empty($_SESSION['csrf'])) {
    $_SESSION['csrf'] = bin2hex(random_bytes(32));
}
$csrf_token = $_SESSION['csrf'];

// ---------- 4. PROCESS FORM ----------
$errors   = [];
$success  = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {

    // ---- a) Verify CSRF token
    if (!isset($_POST['csrf']) || $_POST['csrf'] !== $_SESSION['csrf']) {
        $errors[] = 'Invalid CSRF token.';
    }

    // ---- b) Sanitize / validate fields
    $name     = trim($_POST['name'] ?? '');
    $email    = trim($_POST['email'] ?? '');
    $phone    = trim($_POST['phone'] ?? '');
    $pass1    = $_POST['pass']   ?? '';
    $pass2    = $_POST['pass2']  ?? '';
    $gender   = $_POST['gender'] ?? '';

    if ($name === '')      $errors[] = 'Full name is required.';
    if (!filter_var($email, FILTER_VALIDATE_EMAIL))
        $errors[] = 'A valid e‑mail address is required.';
    if ($phone !== '' && !preg_match('/^\+?[0-9]{7,15}$/', $phone))
        $errors[] = 'Phone number looks invalid.';
    if ($gender === '' || !in_array($gender, ['male','female','other']))
        $errors[] = 'Please select a gender.';
    if ($pass1 === '' || $pass2 === '')
        $errors[] = 'Password and confirmation are required.';
    elseif ($pass1 !== $pass2)
        $errors[] = 'Passwords do not match.';

    // ---- c) If no validation errors, insert into DB
    if (empty($errors)) {
        // Hash the password
        $hash = password_hash($pass1, PASSWORD_DEFAULT);

        $stmt = $mysqli->prepare(
            "INSERT INTO students (name,email,phone,password,gender)
             VALUES (?,?,?,?,?)"
        );
        if ($stmt === false) {
            $errors[] = 'Prepare failed: ' . $mysqli->error;
        } else {
            $stmt->bind_param('sssss', $name, $email, $phone, $hash, $gender);

            if ($stmt->execute()) {
