<?php
/**
 * Autoloader très simple (compatible PSR‑4)
 *
 * Il suffit d’appeler Autoloader::register() au tout début du script.
 */
class Autoloader
{
    /**
     * Enregistre la fonction d’autoload.
     */
    public static function register(): void
    {
        spl_autoload_register([self::class, 'autoload']);
    }

    /**
     * Convertit le nom complet de la classe (FQCN) en chemin de fichier.
     *
     * Exemple :  Form\Type\RadioQuestion  →  Classes/Form/Type/RadioQuestion.php
     *
     * @param string $fqcn Nom complet (avec namespace) de la classe à charger
     */
    public static function autoload(string $fqcn): void
    {
        // Le namespace correspond à l'arborescence sous le répertoire Classes/
        $relativePath = str_replace('\\', '/', $fqcn);
        $file = __DIR__ . '/' . $relativePath . '.php';

        if (file_exists($file)) {
            require $file;
        }
    }
}
?>
```

> **Note** : L’autoloader attend que chaque classe soit placée dans un *namespace* qui reflète exactement son chemin sous `Classes/`.  
