## 5️⃣  `Classes/Quiz.php`

```php
<?php
/**
 * Le conteneur de questions. Il génère le formulaire et évalue les réponses.
 */
class Quiz
{
    /** @var Question[]  tableau indexé par l’UUID de chaque question */
    private $questions = [];

    /**
     * Ajoute une question au quiz.
     */
    public function addQuestion(Question $question): void
    {
        $this->questions[$question->getUuid()] = $question;
    }

    /**
     * Affiche le formulaire complet.
     */
    public function afficheQuiz(): void
    {
        // Le formulaire pointe vers le script d’action
        echo '<form method="post" action="../Action/submit.php">';

        foreach ($this->questions as $question) {
            $question->afficheQuestion();
        }

        echo '<input type="submit" name="submit" value="Valider le quiz">';
        echo '</form>';
    }

    /**
     * Vérifie le POST reçu et retourne le nombre de bonnes réponses.
     */
    public function checkReponse(array $postData): int
    {
        $score = 0;

        foreach ($this->questions as $question) {
            $uuid = $question->getUuid();

            // Pour les checkboxes on récupère un tableau, pour les radios une string
            $userAnswer = $postData[$uuid] ?? null;

            if ($question->checkReponse($userAnswer)) {
                $score++;
            }
        }

        return $score;
    }
}
?>
```

