$questionsData = json_decode($json, true);

/* -------------------------------------------------------------
   3️⃣  Construction du Quiz
   ------------------------------------------------------------- */
$quiz = new Quiz();

/* -------------------------------------------------------------
   4️⃣  Instanciation des bonnes classes selon le champ «type».
       On a au moins RadioQuestion et CheckboxQuestion.
   ------------------------------------------------------------- */
foreach ($questionsData as $data) {
    // Le champ "type" du JSON doit contenir le nom de la classe
    // (ex. "RadioQuestion" ou "CheckboxQuestion").
    $class = 'Form\\Type\\' . $data['type'];   // ex : Form\Type\RadioQuestion

    if (class_exists($class)) {
        $quiz->addQuestion(new $class($data));
    } else {
        // Au cas où le type ne serait pas implémenté : on ignore ou on log
        error_log("Question type {$data['type']} non trouvé.");
    }
}

/* -------------------------------------------------------------
   5️⃣  On garde le Quiz en session pour le script d’action
   ------------------------------------------------------------- */
$_SESSION['quiz'] = serialize($quiz);

/* -------------------------------------------------------------
   6️⃣  Affichage du formulaire
   ------------------------------------------------------------- */
$quiz->afficheQuiz();
?>
```

> **Remarque sur le JSON**  
