// ---------------------------------------------------------------
// Helper: redirect with a message (GET param)
// ---------------------------------------------------------------
function redirect(string $url, string $msg = '', bool $isError = true): void
{
    $sep = strpos($url, '?') === false ? '?' : '&';
    $url .= $sep . ($isError ? 'error=' : 'success=') . urlencode($msg);
    header('Location: ' . $url);
    exit;
}

// ---------------------------------------------------------------
// 1️⃣  Basic request checks
// ---------------------------------------------------------------
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    redirect('register.html', 'Invalid request method.', true);
}

