if (empty($_POST['csrf']) || !hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'])) {
    redirect('register.html', 'Invalid CSRF token.', true);
}

// ---------------------------------------------------------------
// 2️⃣  Gather & sanitise input
// ---------------------------------------------------------------
$username        = trim($_POST['username'] ?? '');
$email           = trim($_POST['email'] ?? '');
$password        = $_POST['password'] ?? '';
$passwordConfirm = $_POST['password_confirm'] ?? '';

// ---------------------------------------------------------------
// 3️⃣  Server‑side validation
// ---------------------------------------------------------------
if ($username === '' || $email === '' || $password === '' || $passwordConfirm === '') {
    redirect('register.html', 'All fields are required.');
}
if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
    redirect('register.html', 'Invalid e‑mail address.');
}
if (strlen($username) > 50) {
    redirect('register.html', 'Username is too long.');
}
if (strlen($email) > 255) {
    redirect('register.html', 'E‑mail is too long.');
}
if ($password !== $passwordConfirm) {
    redirect('register.html', 'Passwords do not match.');
}
if (strlen($password) < 8) {
    redirect('register.html', 'Password must be at least 8 characters.');
}

// ---------------------------------------------------------------
// 4️⃣  Check for existing username/e‑mail
// ---------------------------------------------------------------
$sql = "SELECT id FROM users WHERE username = :username OR email = :email LIMIT 1";
$stmt = $pdo->prepare($sql);
$stmt->execute([':username' => $username, ':email' => $email]);

if ($stmt->fetch()) {
    redirect('register.html', 'Username or e‑mail already taken.');
}

// ---------------------------------------------------------------
// 5️⃣  Insert new user (hash the password!)
// ---------------------------------------------------------------
$hash = password_hash($password, PASSWORD_DEFAULT); // bcrypt (or argon2i if PHP compiled with it)

$sql = "INSERT INTO users (username, email, password) 
        VALUES (:username, :email, :password)";
$stmt = $pdo->prepare($sql);
try {
    $stmt->execute([
        ':username' => $username,
        ':email'    => $email,
        ':password' => $hash,
    ]);
} catch (PDOException $e) {
    // Example of a more graceful error log:
    error_log('Register error: ' . $e->getMessage());
    redirect('register.html', 'Database error. Please try again later.');
}

// ---------------------------------------------------------------
// 6️⃣  Auto‑login (optional) or redirect to login page
// ---------------------------------------------------------------
$_SESSION['user_id'] = $pdo->lastInsertId(); // you may store other data here
$_SESSION['username'] = $username;

// Regenerate session ID to prevent session fixation
session_regenerate_id(true);

redirect('welcome.php', 'Your account has been created. You are now logged in!', false);
