function back(string $msg, bool $isError = true): void
{
    $sep = strpos('login.html', '?') === false ? '?' : '&';
    $url = 'login.html' . $sep . ($isError ? 'error=' : 'success=') . urlencode($msg);
    header('Location: ' . $url);
    exit;
}

// ---------------------------------------------------------------
