// ---------------------------------------------------------------
$sql = "SELECT id, username, password FROM users 
        WHERE username = :login OR email = :login LIMIT 1";
$stmt = $pdo->prepare($sql);
$stmt->execute([':login' => $login]);
$user = $stmt->fetch();

if (!$user) {
