}

// Optional: if you want to force password re‑hashes when algorithm changes
if (password_needs_rehash($user['password'], PASSWORD_DEFAULT)) {
    $newHash = password_hash($password, PASSWORD_DEFAULT);
    $pdo->prepare("UPDATE users SET password = :hash WHERE id = :id")
        ->execute([':hash' => $newHash, ':id' => $user['id']]);
}

// ---------------------------------------------------------------
// 6️⃣  Login succeeded – set session and redirect
// ---------------------------------------------------------------
$_SESSION['user_id']   = $user['id'];
$_SESSION['username'] = $user['username'];
session_regenerate_id(true); // prevent session fixation

