 *
 * Или через браузер:
 *   http://yourdomain.com/download.php?url=....
 */

set_time_limit(0); // Чтобы скрипт не «убивал» таймаут при больших файлах

/**
 * Получаем URL из GET‑параметра или из аргументов командной строки.
 */
function getInputUrl()
{
    // Через браузер
    if (isset($_GET['url'])) {
        return trim($_GET['url']);
    }

    // Через CLI
    global $argv;
    if (php_sapi_name() === 'cli' && $argc > 1) {
        return trim($argv[1]);
    }

    die("Укажите URL видео: ?url=...  или передайте его как единственный CLI‑аргумент.\n");
}

/**
 * При необходимости можно «почистить» URL от лишних параметров.
 * В данном случае нам не нужен параметр `auth_key`, но если он нужен – оставить.
 */
function normalizeUrl(string $url): string
{
    // Пример: убрать всё после первого знака «#» (фрагмент)
    $url = preg_replace('/#.*$/', '', $url);
    return $url;
}

/**
 * Скачивание (cURL) с записью в файл.
 */
function downloadFile(string $url, string $destPath): void
{
    $fp = fopen($destPath, 'w+');
    if ($fp === false) {
        throw new RuntimeException("Не удалось открыть файл для записи: {$destPath}");
    }

    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_FILE            => $fp,
        CURLOPT_FOLLOWLOCATION  => true,
        CURLOPT_TIMEOUT         => 0,
        CURLOPT_FAILONERROR     => true,
        CURLOPT_USERAGENT       => 'PHP Video Downloader',
        CURLOPT_SSL_VERIFYPEER  => true,   // Если нужен строгий SSL‑проверка
        CURLOPT_SSL_VERIFYHOST  => 2,
    ]);

    $ok = curl_exec($ch);
    if ($ok === false) {
        $err = curl_error($ch);
        curl_close($ch);
        fclose($fp);
        throw new RuntimeException("cURL error: {$err}");
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    fclose($fp);

    if ($httpCode >= 400) {
        throw new RuntimeException("Сервер вернул ошибку HTTP {$httpCode}");
    }
}

/**
 * Основная часть.
 */
try {
    $remoteUrl = normalizeUrl(getInputUrl());

    // Папка, куда будем сохранять. Если её нет – создаём.
    $uploadDir = __DIR__ . '/videos';
    if (!is_dir($uploadDir)) {
        if (!mkdir($uploadDir, 0755, true)) {
            throw new RuntimeException("Не удалось создать папку {$uploadDir}");
        }
    }

    // Формируем имя файла – берём последний элемент пути и добавляем таймстамп,
    // чтобы избежать конфликтов, если файл уже существует.
    $parsed = parse_url($remoteUrl);
    $basename = basename($parsed['path']);                    // например: video.mp4
    $ext = pathinfo($basename, PATHINFO_EXTENSION);
    $safeName = preg_replace('/[^a-zA-Z0-9_-]/', '_', pathinfo($basename, PATHINFO_FILENAME));
    $localFile = $uploadDir . '/' . $safeName . '_' . time() . '.' . $ext;

    downloadFile($remoteUrl, $localFile);

    // Если скрипт вызывается из браузера – выводим красивый HTML‑ответ.
    if (php_sapi_name() !== 'cli') {
        header('Content-Type: text/html; charset=utf-8');
        echo "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Видео скачано</title></head><body>";
        echo "<h1>Видео успешно скачано</h1>";
        echo "<p>URL: <a href=\"" . htmlspecialchars($remoteUrl) . "\" target=\"_blank\">" . htmlspecialchars($remoteUrl) . "</a></p>";
        echo "<p>Сохранено как: <code>" . htmlspecialchars(basename($localFile)) . "</code></p>";
        echo "<p>Полный путь: <code>" . htmlspecialchars($localFile) . "</code></p>";
        echo "</body></html>";
    } else {
        // CLI‑вывод
        echo "Видео скачано в: {$localFile}\n";
    }
} catch (Throwable $e) {
    // Ошибку тоже выводим в удобочитаемом виде
    if (php_sapi_name() !== 'cli') {
        header('Content-Type: text/plain; charset=utf-8');
        echo "ERROR: " . $e->getMessage();
    } else {
        fwrite(STDERR, "ERROR: " . $e->getMessage() . PHP_EOL);
        exit(1);
    }
}
?>
```

### Как пользоваться

1. **Создайте директорию** рядом со скриптом (можно не создавать – скрипт сам её создаст)  
   ```
   mkdir -p /path/to/your/site/videos
   chmod 755 /path/to/your/site/videos   # убедитесь, что веб‑сервер может писать туда
   ```

2. Положите файл `download.php` в корень сайта.

3. **Через браузер**  
   ```text
   http://example.com/download.php?url=https://video-cdn.aliexpress-media.com/80ffc57ef0293a3a/ae_sg_item/...mp4?auth_key=...
   ```

4. **Через консоль** (полезно для отладки)  
   ```bash
   php download.php "https://video-cdn.aliexpress-media.com/80ffc57ef0293a3a/ae_sg_item/...mp4?auth_key=..."
   ```

5. После выполнения вы увидите файл в папке `videos/` с именем вроде  
   `Bub4DyQ6ex0zl0T8ki7_1100096979227_mp4_264_sd_1691057774.mp4`.

