### 1.2. Định nghĩa (DDL)

```sql
-- -------------------------------------------------
-- Bảng author
-- -------------------------------------------------
CREATE TABLE `author` (
    `author_id`   INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `author_name` VARCHAR(150) NOT NULL,
    PRIMARY KEY (`author_id`),
    UNIQUE KEY `uq_author_name` (`author_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -------------------------------------------------
-- Bảng publisher
-- -------------------------------------------------
CREATE TABLE `publisher` (
    `publisher_id`   INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `publisher_name` VARCHAR(150) NOT NULL,
    PRIMARY KEY (`publisher_id`),
    UNIQUE KEY `uq_publisher_name` (`publisher_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -------------------------------------------------
-- Bảng major (chuyên ngành)
-- -------------------------------------------------
CREATE TABLE `major` (
    `major_id`   INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `major_name` VARCHAR(150) NOT NULL,
    PRIMARY KEY (`major_id`),
    UNIQUE KEY `uq_major_name` (`major_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -------------------------------------------------
-- Bảng book
-- -------------------------------------------------
CREATE TABLE `book` (
    `book_id`        INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `book_code`      VARCHAR(20)  NOT NULL,               -- Mã sách (unique)
    `book_title`     VARCHAR(250) NOT NULL,               -- Tên sách
    `year_published` YEAR        NOT NULL,               -- Năm xuất bản
    `author_id`      INT UNSIGNED NOT NULL,               -- FK → author
    `publisher_id`   INT UNSIGNED NOT NULL,               -- FK → publisher
    `major_id`       INT UNSIGNED NOT NULL,               -- FK → major
    PRIMARY KEY (`book_id`),
    UNIQUE KEY `uq_book_code` (`book_code`),
    CONSTRAINT `fk_book_author`    FOREIGN KEY (`author_id`)    REFERENCES `author`(`author_id`)    ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT `fk_book_publisher` FOREIGN KEY (`publisher_id`) REFERENCES `publisher`(`publisher_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT `fk_book_major`     FOREIGN KEY (`major_id`)     REFERENCES `major`(`major_id`)       ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
