$stmt = $pdo->prepare(
    "SELECT b.book_code, b.book_title, b.year_published,
            a.author_name, p.publisher_name, m.major_name
     FROM book b
     JOIN author a      ON b.author_id = a.author_id
     JOIN publisher p   ON b.publisher_id = p.publisher_id
     JOIN major m       ON b.major_id = m.major_id
     WHERE b.book_id = ?"
);
$stmt->execute([$book_id]);
