    $stmt->execute([$major]);
    $major_id = $stmt->fetchColumn();
    if (!$major_id) {
        $stmt = $pdo->prepare("INSERT INTO major (major_name) VALUES (?)");
        $stmt->execute([$major]);
        $major_id = $pdo->lastInsertId();
    }

    // Cập nhật bảng book
