        "UPDATE book SET book_code = ?, book_title = ?, year_published = ?, 
                author_id = ?, publisher_id = ?, major_id = ?
         WHERE book_id = ?"
    );
    $stmt->execute([$code, $title, $year, $author_id, $publisher_id, $major_id, $book_id]);

    // Quay lại danh sách
    header('Location: index.php');
