## 3️⃣ منطق الإضافة (JavaScript)

**ملف `script.js`** يُعالج:

- قراءة البيانات من النموذج.
- إنشاء عنصر DOM (بطاقة المنتج) وإلحاقه بالحاوية.
- حفظ جميع المنتجات في `localStorage` حتى يبقى المحتوى بعد إعادة تحميل الصفحة.

```js
// ==== تعريف العناصر العامة ====
const productForm = document.getElementById('product-form');
const productsContainer = document.getElementById('products-container');

// ==== استرجاع المنتجات المخزنة عند تحميل الصفحة ====
let products = JSON.parse(localStorage.getItem('products') || '[]');
renderAllProducts();   // عرض ما تم تخزينه مسبقاً

// ==== معالجة إرسال النموذج ====
productForm.addEventListener('submit', function (e) {
    e.preventDefault();                     // منع التحديث الفوري للصفحة
    const formData = new FormData(productForm);

    // تجميع بيانات المنتج في كائن
    const newProduct = {
        id: Date.now(),                      // معرف فريد (يمكن تغييره حسب الحاجة)
        name: formData.get('name').trim(),
        description: formData.get('description').trim(),
        price: parseFloat(formData.get('price')).toFixed(2),
        image: formData.get('image').trim()
    };

    // إضافة المنتج إلى المصفوفة ثم التخزين
    products.push(newProduct);
    localStorage.setItem('products', JSON.stringify(products));

    // إنشاء العنصر في الواجهة
    addProductCard(newProduct);

    // مسح النموذج للملء مرة أخرى
    productForm.reset();
});

// ==== وظائف مساعدة ====

// إنشاء بطاقة HTML للمنتج وإلحاقها بالحاوية
function addProductCard(product) {
    const card = document.createElement('div');
    card.className = 'product-card';
    card.dataset.id = product.id;   // إذا احتجت لإزالة أو تعديل المنتج لاحقاً

    card.innerHTML = `
        <img src="${product.image}" alt="${escapeHtml(product.name)}">
        <div class="info">
            <h3>${escapeHtml(product.name)}</h3>
            <p>${escapeHtml(product.description)}</p>
            <p class="price">السعر: ${product.price} ج.م</p>
        </div>
    `;

    productsContainer.appendChild(card);
}

// عرض جميع المنتجات المخزنة (تُستدعى عند تحميل الصفحة)
function renderAllProducts() {
    productsContainer.innerHTML = '';   // حذف أي محتوى قديم
    products.forEach(addProductCard);
}

// حماية بسيطة من إدخال HTML غير مرغوب فيه
function escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
}
