$ip = $_SERVER['REMOTE_ADDR'];               // ou votre fonction getClientIP()
$data = json_decode(file_get_contents("http://ip-api.com/json/{$ip}?fields=country,city,lat,lon"), true);
echo "IP {$ip} → {$data['city']}, {$data['country']} ({$data['lat']}, {$data['lon']})";
