```

> **Astuce sécurité** : vous pouvez charger ces valeurs depuis un fichier `.env` (via `vlucas/phpdotenv`) et ne jamais les versionner.

---

## 4️⃣ Connexion à la base (src/db.php)

```php
<?php
// src/db.php
require_once __DIR__.'/config.php';

class Database
{
    private static ?PDO $pdo = null;

    public static function getConnection(): PDO
    {
        if (self::$pdo === null) {
            $dsn = 'mysql:host=' . DB_HOST . ';dbname=' . DB_NAME . ';charset=utf8mb4';
            $options = [
                PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES   => false,
            ];
            self::$pdo = new PDO($dsn, DB_USER, DB_PASS, $options);
        }
        return self::$pdo;
    }
}
?>
```

---

## 5️⃣ Modèle Utilisateur (src/User.php)

```php
<?php
// src/User.php
require_once __DIR__.'/db.php';

class User
{
    private PDO $db;

    public function __construct()
    {
        $this->db = Database::getConnection();
    }

    /*** Inscription ***/
    public function register(array $data): bool
    {
        // Validation simple (on peut déléguer à helpers.php)
        if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            throw new InvalidArgumentException('Email invalide');
        }
        if (strlen($data['password']) < 8) {
            throw new InvalidArgumentException('Le mot de passe doit contenir au moins 8 caractères');
        }

        // Hachage sécurisé
        $hash = password_hash($data['password'], PASSWORD_BCRYPT);

        $sql = "INSERT INTO users (email, password, firstname, lastname)
                VALUES (:email, :password, :firstname, :lastname)";
        $stmt = $this->db->prepare($sql);
        return $stmt->execute([
            ':email'     => $data['email'],
            ':password'  => $hash,
            ':firstname' => $data['firstname'],
            ':lastname'  => $data['lastname'],
        ]);
    }

    /*** Connexion ***/
    public function login(string $email, string $password): bool
    {
        $sql = "SELECT * FROM users WHERE email = :email LIMIT 1";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([':email' => $email]);
        $user = $stmt->fetch();

        if ($user && password_verify($password, $user['password'])) {
            // Regénérer l'ID de session pour éviter le fixation
            session_regenerate_id(true);
            $_SESSION['user_id']    = $user['id'];
            $_SESSION['user_email'] = $user['email'];
            $_SESSION['user_name']  = $user['firstname'] . ' ' . $user['lastname'];
            return true;
        }
        return false;
    }

    /*** Vérifier si l'utilisateur est connecté ***/
    public static function isLogged(): bool
    {
        return isset($_SESSION['user_id']);
    }

    /*** Déconnexion ***/
    public static function logout(): void
    {
        $_SESSION = [];
        if (ini_get("session.use_cookies")) {
            $params = session_get_cookie_params();
            setcookie(session_name(), '', time() - 42000,
                $params["path"], $params["domain"],
                $params["secure"], $params["httponly"]
            );
        }
        session_destroy();
    }

    /*** Générer un token de réinitialisation du mot de passe ***/
    public function createPasswordResetToken(string $email): ?string
    {
        $sql = "SELECT id FROM users WHERE email = :email LIMIT 1";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([':email' => $email]);
        $user = $stmt->fetch();
        if (!$user) {
            return null; // email inconnu (ne pas révéler)
        }

        $token = bin2hex(random_bytes(32));
        $expires = (new DateTime('+1 hour'))->format('Y-m-d H:i:s');

        $update = "UPDATE users SET token_reset = :token, token_exp = :exp WHERE id = :id";
        $stmt = $this->db->prepare($update);
        $stmt->execute([
            ':token' => $token,
            ':exp'   => $expires,
            ':id'    => $user['id'],
        ]);

        return $token;
    }

    /*** Réinitialiser le mot de passe avec le token ***/
    public function resetPassword(string $token, string $newPassword): bool
    {
        $sql = "SELECT id, token_exp FROM users WHERE token_reset = :token LIMIT 1";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([':token' => $token]);
        $user = $stmt->fetch();

        if (!$user) {
            return false;
        }

        // Vérifier la date d’expiration
        $now = new DateTime();
        $exp = new DateTime($user['token_exp']);
        if ($now > $exp) {
            return false;
        }

        // Mettre à jour le mot de passe
        $hash = password_hash($newPassword, PASSWORD_BCRYPT);
        $update = "UPDATE users SET password = :hash, token_reset = NULL, token_exp = NULL WHERE id = :id";
        $stmt = $this->db->prepare($update);
        return $stmt->execute([':hash' => $hash, ':id' => $user['id']]);
    }

    /*** Récupérer les infos de l'utilisateur connecté ***/
    public function getCurrentUser(): ?array
    {
        if (!self::isLogged()) {
            return null;
        }
        $sql = "SELECT id, email, firstname, lastname, created_at FROM users WHERE id = :id LIMIT 1";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([':id' => $_SESSION['user_id']]);
        return $stmt->fetch();
    }
}
?>
```

