    echo "<h1>404 Not Found</h1>";
    echo "EH JANGAN MALING BOSS";
    exit;
}

/* --------------------------------------------------------------
 * 2. Get the brand requested by the user
 * -------------------------------------------------------------- */
if (!isset($_GET['daftar'])) {
    feedback404();
}
$requestedBrand = strtolower(trim($_GET['daftar']));

/* --------------------------------------------------------------
 * 3. Verify that the brand really exists (local whitelist)
 * -------------------------------------------------------------- */
$brandFile = __DIR__ . '/brandlist.txt';               // <-- absolute path (safer)
if (!is_readable($brandFile)) {
    // you may want to log this error – it's a server‑side problem
    die('Brand list not readable');
}
$brands = file($brandFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
$validBrand = null;
foreach ($brands as $line) {
    if (strtolower(trim($line)) === $requestedBrand) {
        $validBrand = strtoupper($requestedBrand);    // keep the "canonical" name
        break;
    }
}
if ($validBrand === null) {
    feedback404();   // brand not in the whitelist
}

/* --------------------------------------------------------------
 * 4. Build the URL of the **provider** (Domain B) and ask it
 * -------------------------------------------------------------- */
$providerBase = 'https://provider.example.com/getAssets.php'; // <-- change!
$providerUrl = $providerBase . '?brand=' . urlencode($validBrand);

/* -----------------------------------------------------------------
 * 4a. Choose a HTTP client (cURL is the most reliable)
 * ----------------------------------------------------------------- */
function httpGetJson(string $url, int $timeout = 5): ?array
{
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_TIMEOUT        => $timeout,
        CURLOPT_SSL_VERIFYPEER => true,   // keep SSL verification!
        CURLOPT_HTTPHEADER     => ['Accept: application/json']
    ]);

    $raw = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $curlErr  = curl_error($ch);
    curl_close($ch);

    if ($raw === false) {
        error_log("cURL error for $url : $curlErr");
        return null;
    }
    if ($httpCode !== 200) {
        error_log("Unexpected HTTP $httpCode from $url");
        return null;
    }

    $data = json_decode($raw, true);
    if (json_last_error() !== JSON_ERROR_NONE) {
        error_log("JSON decode error: " . json_last_error_msg());
        return null;
    }
    return $data;
}

/* -----------------------------------------------------------------
