const express = require('express');
const path = require('path');
const bodyParser = require('body-parser');

const app = express();
const PORT = 3000;

// --------- 1️⃣ 中间件 ----------
app.use(express.static(path.join(__dirname, 'public'))); // 提供前端静态文件
app.use(bodyParser.json()); // 解析 JSON 请求体

// --------- 2️⃣ 模拟数据源 ----------
