 * GET /api/todos
 * 返回当前所有 Todo（JSON 数组）
 */
app.get('/api/todos', (req, res) => {
  res.json(todos);
});

/**
 * POST /api/todos
 * 请求体: { text: string }
 * 返回: 新增的 Todo 项
