    return res.status(400).json({ error: 'Invalid text' });
  }
  const newTodo = { id: nextId++, text: text.trim(), done: false };
  todos.push(newTodo);
  // 为了演示 “返回最新列表”，这里直接返回整个数组
  // 也可以只返回 newTodo
  res.status(201).json(newTodo);
});

/**
 * DELETE /api/todos/:id   （可选：删除任务）
 */
app.delete('/api/todos/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const index = todos.findIndex(t => t.id === id);
  if (index === -1) {
    return res.status(404).json({ error: 'Todo not found' });
  }
  todos.splice(index, 1);
  res.status(204).end(); // No Content
});

// --------- 4️⃣ 启动服务器 ----------
app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
```

> **说明**  
> - `express.static` 让 `public/` 里的 `index.html` 可直接访问。  
> - `GET /api/todos` 返回全部 Todo（前端首次加载或定时刷新时使用）。  
> - `POST /api/todos` 接收 JSON `{text: "..."} `，创建新记录并返回该记录。  
> - 这里所有数据都保存在内存数组 `todos`，重启服务器会丢失，演示足够。

