### 4.2. 前端（HTML + JavaScript）

> **文件路径**：`public/index.html`

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <title>Ajax 实现 Todo List（无刷新）</title>
  <style>
    body { font-family: Arial, Helvetica, sans-serif; padding: 20px; }
    ul { list-style: none; padding: 0; }
    li { padding: 5px 0; }
    .done { text-decoration: line-through; color: #777; }
  </style>
</head>
<body>

  <h1>Todo List</h1>

  <!-- ① 输入框 + 按钮 -->
  <input type="text" id="newTodo" placeholder="输入待办事项" />
  <button id="addBtn">添加</button>

  <!-- ② Todo 列表容器 -->
  <ul id="todoList"></ul>

  <script>
    // -------------------------------------------------
    // 1️⃣ 常量 & 工具函数
    // -------------------------------------------------
    const API_BASE = '/api/todos';          // 与后端路由保持一致
    const $list   = document.getElementById('todoList');
    const $input  = document.getElementById('newTodo');
    const $addBtn = document.getElementById('addBtn');

    /**
     * 将 Todo 数组渲染到 <ul>#todoList
     * @param {Array} data
     */
    function renderTodoList(data) {
      $list.innerHTML = ''; // 清空原有
      data.forEach(todo => {
        const li = document.createElement('li');
        li.dataset.id = todo.id;
        li.textContent = todo.text;
        if (todo.done) li.classList.add('done');
        $list.appendChild(li);
      });
    }

    // -------------------------------------------------
    // 2️⃣ Ajax（fetch）封装
    // -------------------------------------------------
    /**
     * GET 请求，获取所有 Todo
     */
    async function fetchTodos() {
      try {
        const resp = await fetch(API_BASE, { credentials: 'same-origin' });
        if (!resp.ok) throw new Error('Network response was not ok');
        const data = await resp.json(); // 期待得到 [{id, text, done}, ...]
        renderTodoList(data);
      } catch (err) {
        console.error('fetchTodos error:', err);
      }
    }

    /**
     * POST 请求，新增 Todo
     * @param {string} text
     */
    async function addTodo(text) {
      try {
        const resp = await fetch(API_BASE, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text })
        });
        if (resp.status === 201) {
          const newTodo = await resp.json(); // 新增成功返回新对象
          // ① 直接把新对象插入列表（局部刷新）
          const li = document.createElement('li');
          li.dataset.id = newTodo.id;
          li.textContent = newTodo.text;
          $list.appendChild(li);
          // ② 若想重新拉取全部列表，可调用 fetchTodos()
        } else {
          const err = await resp.json();
          alert('添加失败: ' + (err.error || resp.statusText));
        }
      } catch (err) {
        console.error('addTodo error:', err);
      }
    }

    // -------------------------------------------------
    // 3️⃣ 事件绑定
    // -------------------------------------------------
    $addBtn.addEventListener('click', () => {
      const txt = $input.value.trim();
      if (!txt) {
        alert('请输入内容！');
        return;
      }
      addTodo(txt);
      $input.value = ''; // 清空输入框
    });

    // 支持回车键提交
    $input.addEventListener('keydown', e => {
      if (e.key === 'Enter') $addBtn.click();
    });

    // -------------------------------------------------
    // 4️⃣ 页面初始化 & 定时刷新（可选）
    // -------------------------------------------------
    fetchTodos(); // 首次加载

    // 每 10 秒自动拉取一次最新数据，实现 “实时刷新”
    const REFRESH_INTERVAL = 10 * 1000; // 10,000 ms
    setInterval(fetchTodos, REFRESH_INTERVAL);
  </script>
</body>
</html>
```

#### 关键点拆解

| 步骤 | 代码片段 | 解释 |
|------|----------|------|
| **1. 页面首次渲染** | `fetchTodos()` | 页面加载完成后发起 `GET /api/todos`，拿到全部 Todo，调用 `renderTodoList` 把 JSON 数据渲染成 `<li>` 列表。 |
| **2. 添加新 Todo** | `addTodo(txt)` | 使用 `fetch` 发起 `POST /api/todos`（JSON body），服务器返回新条目后用 **DOM API** 把 `<li>` 动态加入列表，**无需刷新页面**。 |
| **3. 自动刷新** | `setInterval(fetchTodos, REFRESH_INTERVAL)` | 每 10 秒重新请求一次全部数据，适用于多人协同编辑或服务器端有其他更新的情况。 |
| **4. 错误处理** | `if (!resp.ok) throw new Error...`、`catch` 块 | 捕获网络错误或非 2xx 状态码，提示用户或打印日志，防止页面卡死。 |
| **5. 跨域 & Cookie** | `credentials: 'same-origin'` | 若后端需要读取登录态（Cookie），必须在 fetch 中带上 `credentials`（同源或 `include`）。 |

