## 2️⃣ `functions.php`

```php
<?php
/**
 * functions.php
 *
 * Utility functions used by index.php and download.php
 */

declare(strict_types=1);

require_once __DIR__ . '/config.php';

/**
 * Return an associative array: idSite => siteName
 *
 * @return array<int,string>
 * @throws RuntimeException on API failure
 */
function getMatomoSites(): array
{
    $url = sprintf(
        '%s/index.php?module=API&method=SitesManager.getAllSites&format=JSON&token_auth=%s',
        rtrim(MATOMO_URL, '/'),
        urlencode(MATOMO_TOKEN)
    );

    $response = fetchUrl($url);
    $sites = json_decode($response, true, flags: JSON_THROW_ON_ERROR);

    $list = [];
    foreach ($sites as $site) {
        $list[(int)$site['idSite']] = $site['name'];
    }

    return $list;
}

/**
 * Build the full Matomo API URL for the requested report.
 *
 * @param int    $siteId   Matomo site ID
 * @param string $from     Start date (YYYY-MM-DD)
 * @param string $to       End date (YYYY-MM-DD)
 * @param string $format   csv | xlsx | pdf
 * @return string
 */
function buildReportUrl(int $siteId, string $from, string $to, string $format): string
{
    // Matomo uses "range" period for a custom start/end interval
    $date = sprintf('%s,%s', $from, $to);

    // For Excel we ask Matomo for CSV and later rename the file (Matomo does not have native XLSX)
    $apiFormat = match ($format) {
        'csv'  => 'CSV',
        'xlsx' => 'CSV',          // we will force .xlsx extension – Excel opens CSV fine
        'pdf'  => 'PDF',
        default => 'CSV',
    };

    $url = sprintf(
        '%s/index.php?module=API&method=%s&idSite=%d&period=range&date=%s&format=%s&token_auth=%s',
        rtrim(MATOMO_URL, '/'),
        urlencode(DEFAULT_API_METHOD),
        $siteId,
        urlencode($date),
        $apiFormat,
        urlencode(MATOMO_TOKEN)
    );

    return $url;
}

/**
 * Download a remote URL using cURL and return the raw body.
 *
 * @param string $url
 * @return string
 * @throws RuntimeException on network error or non‑200 HTTP status
 */
function fetchUrl(string $url): string
{
    $ch = curl_init();

    curl_setopt_array($ch, [
        CURLOPT_URL            => $url,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FAILONERROR    => true,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_TIMEOUT        => 30,
    ]);

    $data = curl_exec($ch);
    if ($data === false) {
        $msg = curl_error($ch);
        curl_close($ch);
        throw new RuntimeException('cURL error: ' . $msg);
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($httpCode !== 200) {
        throw new RuntimeException('Matomo API returned HTTP ' . $httpCode);
    }

    return $data;
}

/**
 * Send the appropriate HTTP headers and stream the file to the browser.
 *
 * @param string $content   Raw file data
 * @param string $format    csv|xlsx|pdf
 * @param string $siteName  For a friendlier filename
 * @param string $from
 * @param string $to
 */
function streamDownload(string $content, string $format, string $siteName, string $from, string $to): void
{
    // Clean up the site name for a filename (remove slashes, trim spaces, etc.)
    $safeSite = preg_replace('/[^\w\-.]/', '_', $siteName);

    $filename = sprintf(
        '%s_%s_to_%s.%s',
        $safeSite,
        $from,
        $to,
        $format === 'xlsx' ? 'xlsx' : $format   // keep the chosen extension
    );

    // Header selection
    $contentType = match ($format) {
        'csv'  => 'text/csv',
        'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'pdf'  => 'application/pdf',
        default => 'application/octet-stream',
    };

    // Do NOT output anything before the headers!
    header('Content-Description: File Transfer');
    header('Content-Type: ' . $contentType);
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Expires: 0');
    header('Cache-Control: must-revalidate');
    header('Pragma: public');
    header('Content-Length: ' . strlen($content));

    // Flush the buffer and send the file
    echo $content;
    exit;
}
```

