## 4️⃣ `download.php` – Build the request & stream the file

```php
<?php
/**
 * download.php
 *
 * Handles the form submission, calls the Matomo API and streams the result.
 */

declare(strict_types=1);
require_once __DIR__ . '/functions.php';

// ---------------------------------------------------------------------
// 1️⃣  Validate user input
// ---------------------------------------------------------------------
$siteId = filter_input(INPUT_POST, 'site', FILTER_VALIDATE_INT);
$from   = filter_input(INPUT_POST, 'from', FILTER_SANITIZE_STRING);
$to     = filter_input(INPUT_POST, 'to', FILTER_SANITIZE_STRING);
$format = filter_input(INPUT_POST, 'format', FILTER_SANITIZE_STRING);

if ($siteId === false || $siteId <= 0) {
    http_response_code(400);
    exit('ID sito non valido');
}
if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $from) ||
    !preg_match('/^\d{4}-\d{2}-\d{2}$/', $to) ||
    $from > $to) {
    http_response_code(400);
    exit('Intervallo di date non valido');
}
$allowedFormats = ['csv', 'xlsx', 'pdf'];
if (!in_array($format, $allowedFormats, true)) {
    http_response_code(400);
    exit('Formato non supportato');
}

// ---------------------------------------------------------------------
// 2️⃣  Build Matomo API URL
// ---------------------------------------------------------------------
$apiUrl = buildReportUrl($siteId, $from, $to, $format);

// ---------------------------------------------------------------------
// 3️⃣  Fetch the report
// ---------------------------------------------------------------------
try {
    $rawData = fetchUrl($apiUrl);
} catch (Throwable $e) {
    http_response_code(502);
    exit('Errore durante il fetch del report: ' . $e->getMessage());
}

// ---------------------------------------------------------------------
// 4️⃣  Retrieve the site name (for a nicer filename)
// ---------------------------------------------------------------------
$sites = getMatomoSites();               // reuse the helper
$siteName = $sites[$siteId] ?? 'site_' . $siteId;

// ---------------------------------------------------------------------
// 5️⃣  Stream the file to the browser
// ---------------------------------------------------------------------
streamDownload($rawData, $format, $siteName, $from, $to);
```

